/*
 * Raspberry Pi 4 Model B - DFRobot Soil Moisture Sensor (MCP3008 CH0)
 *
 * Wiring:
 *   MCP3008 VDD  -> 3.3 V (Pin 1)
 *   MCP3008 VREF -> 3.3 V (Pin 1)
 *   MCP3008 AGND -> GND
 *   MCP3008 DGND -> GND
 *   MCP3008 CLK  -> GPIO11 (SCLK)
 *   MCP3008 DOUT -> GPIO9  (MISO)
 *   MCP3008 DIN  -> GPIO10 (MOSI)
 *   MCP3008 CS   -> GPIO8  (CE0)
 *   MCP3008 CH0  -> DFRobot Soil Moisture Sensor analog output
 *
 * Build: gcc -Wall -Wextra -O2 -o soil_moisture soil_moisture.c -lpigpio -lrt
 * Run:   sudo ./soil_moisture
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL    0          /* CE0 on GPIO8 */
#define SPI_SPEED      1000000    /* 1 MHz - well within MCP3008 200 kHz max */
#define SPI_FLAGS      0          /* Mode 0, active-low CE, 8 bits/word */
#define ADC_CHANNEL    0          /* MCP3008 single-ended channel 0 */
#define SAMPLE_PERIOD  1          /* seconds between readings */
#define MAX_SPI_RETRIES 3

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* MCP3008 single-ended read                                           */
/* ------------------------------------------------------------------ */
/*
 * MCP3008 SPI protocol (Mode 0, 8 bits/word):
 *   Byte 0: 0x01                       (start bit)
 *   Byte 1: (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0 = channel)
 *   Byte 2: 0x00                       (clock out remaining bits)
 *
 * Response (3 bytes):
 *   rx[0] = don't care
 *   rx[1] = [null bit][b9 b8] in upper nibble
 *   rx[2] = b7..b0
 *
 * 10-bit result = ((rx[1] & 0x03) << 8) | rx[2]
 */
static int read_mcp3008(int handle, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: invalid ADC channel %d (must be 0-7)\n", channel);
        return -1;
    }

    char tx[3] = { 0x01,
                   (char)((0x08 | channel) << 4),
                   0x00 };
    char rx[3] = { 0, 0, 0 };

    for (int attempt = 1; attempt <= MAX_SPI_RETRIES; ++attempt) {
        int ret = spiXfer(handle, tx, rx, 3);
        if (ret == 3) {
            int adc_value = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
            return adc_value;   /* 0-1023 */
        }

        fprintf(stderr, "Warning: SPI transfer failed (attempt %d/%d, ret=%d)\n",
                attempt, MAX_SPI_RETRIES, ret);
        if (attempt < MAX_SPI_RETRIES) {
            gpioDelay(100000);   /* 100 ms back-off */
        }
    }

    fprintf(stderr, "Error: SPI transfer failed after %d attempts\n", MAX_SPI_RETRIES);
    return -1;
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* --- Open SPI0 CE0 at 1 MHz, Mode 0 --- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "Error: spiOpen failed (handle=%d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Signal handlers for graceful shutdown --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
    }

    printf("Soil Moisture Sensor Reading (MCP3008 CH0)\n");
    printf("Press Ctrl+C to exit.\n\n");

    /* --- Main sampling loop --- */
    while (g_running) {
        int adc_value = read_mcp3008(g_spi_handle, ADC_CHANNEL);

        if (adc_value < 0) {
            fprintf(stderr, "Error: failed to read ADC value\n");
        } else {
            time_t now = time(NULL);
            struct tm tm_info;
            char ts[32];

            if (localtime_r(&now, &tm_info) != NULL &&
                strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info) > 0) {
                printf("[%s] ADC Value: %4d\n", ts, adc_value);
            } else {
                printf("[unknown time] ADC Value: %4d\n", adc_value);
            }
            fflush(stdout);
        }

        /* Sleep SAMPLE_PERIOD seconds, but wake early on signal */
        for (int i = 0; i < SAMPLE_PERIOD && g_running; ++i) {
            gpioDelay(1000000);   /* 1 second */
        }
    }

    /* --- Graceful cleanup --- */
    printf("\nShutting down...\n");
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

