/*
 * MLX91219 current sensor reader via ADS1115 I2C ADC on Raspberry Pi 4.
 *
 * Wiring:
 *   ADS1115 SDA -> Pi GPIO2 (pin 3)
 *   ADS1115 SCL -> Pi GPIO3 (pin 5)
 *   ADS1115 ADDR -> GND  (I2C address 0x48)
 *   ADS1115 VDD -> 3.3V
 *   ADS1115 GND -> GND
 *   MLX91219 VCC -> 3.3V
 *   MLX91219 GND -> GND
 *   MLX91219 AOUT -> ADS1115 AIN0
 *
 * ADS1115 config (single-shot, AIN0 single-ended, PGA ±4.096V, 128 SPS):
 *   0x01  OS=1, MUX=100, PGA=001, MODE=1, DR=100
 *   0x83  CONV=1, COMP_MODE=0, COMP_POL=0, COMP_LAT=0, COMP_QUE=11
 *
 * MLX91219 sensitivity: 40 mV/A, zero-current offset centered at mid-supply.
 *
 * Build: gcc -O2 -Wall -o mlx91219 mlx91219.c -lpigpio -lrt
 * Run:   sudo ./mlx91219
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define ADS1115_ADDR   0x48

/* ADS1115 register addresses */
#define ADS_REG_CONVERSION 0x00
#define ADS_REG_CONFIG     0x01
#define ADS_REG_LO_THRESH  0x02
#define ADS_REG_HI_THRESH  0x03

/* Config register bits */
#define ADS_REG_OS_SINGLE   0x8000  /* OS bit = 1 for single-shot conversion */
#define ADS_REG_MUX_AIN0    0x4000  /* MUX[14:12] = 100 -> AIN0 single-ended */
#define ADS_REG_PGA_4_096V  0x0200  /* PGA[11:9] = 001 -> ±4.096 V */
#define ADS_REG_MODE_SINGLE 0x0100  /* MODE[8:6] = 100 -> single-shot */
#define ADS_REG_DR_128SPS   0x0080  /* DR[5:3] = 100 -> 128 SPS */
#define ADS_REG_COMP_QUE    0x07    /* COMP_QUE[2:0] = 011 -> disable comparator */

#define ADS_REG_LO_THRESH   0x01
#define ADS_REG_HI_THRESH   0x00

/* MLX91219 parameters */
#define MLX_SENSITIVITY   0.040f   /* 40 mV/A */
#define MLX_OFFSET       1.65f    /* mid-supply (3.3V / 2) */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Write a 16-bit value to an ADS1115 register.
 * pigpio's i2cWriteI2CBlockData sends the 2-byte value as a single block
 * after the register address, which is the correct SMBus protocol.
 */
static int ads1115_write_reg(int handle, uint8_t reg, uint16_t value)
{
    char buf[3];
    buf[0] = (char)reg;
    buf[1] = (char)(value & 0xFF);
    buf[2] = (char)((value >> 8) & 0xFF);

    if (i2cWriteI2CBlockData(handle, (char)reg, buf + 1, 2) < 0) {
        fprintf(stderr, "Error: i2cWriteI2CBlockData failed for reg 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

/*
 * Read a 16-bit value from an ADS1115 register.
 * i2cReadI2CBlockData reads `len` bytes starting at the given address.
 */
static int ads1115_read_reg(int handle, uint8_t reg, uint16_t *value)
{
    char buf[2];

    if (i2cWriteI2CBlockData(handle, (char)reg, buf, 0) < 0) {
        fprintf(stderr, "Error: i2cWriteI2CBlockData (set reg) failed for reg 0x%02X\n", reg);
        return -1;
    }

    if (i2cReadI2CBlockData(handle, (char)reg, buf, 2) != 2) {
        fprintf(stderr, "Error: i2cReadI2CBlockData failed for reg 0x%02X\n", reg);
        return -1;
    }

    *value = (uint16_t)((uint8_t)buf[0] | ((uint8_t)buf[1] << 8));
    return 0;
}

/*
 * Trigger a single-shot conversion on AIN0 and read the result.
 * Returns 0 on success, -1 on I2C error.
 */
static int ads1115_read_ain0(int handle, int16_t *raw)
{
    uint16_t config = ADS_REG_OS_SINGLE | ADS_REG_MUX_AIN0 |
                      ADS_REG_PGA_4_096V | ADS_REG_MODE_SINGLE |
                      ADS_REG_DR_128SPS | ADS_REG_COMP_QUE;

    if (ads1115_write_reg(handle, ADS_REG_CONFIG, config) < 0)
        return -1;

    /* Wait for conversion to complete (OS bit reads 1 after conversion) */
    for (int i = 0; i < 100; i++) {
        uint16_t cfg;
        if (ads1115_read_reg(handle, ADS_REG_CONFIG, &cfg) < 0)
            return -1;
        if (cfg & ADS_REG_OS_SINGLE)
            break;
        gpioDelay(1000); /* 1 ms */
    }

    uint16_t raw16;
    if (ads1115_read_reg(handle, ADS_REG_CONVERSION, &raw16) < 0)
        return -1;

    *raw = (int16_t)raw16;
    return 0;
}

int main(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d). Check wiring and address.\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Verify ADS1115 is present by reading the config register */
    uint16_t cfg;
    if (ads1115_read_reg(g_i2c_handle, ADS_REG_CONFIG, &cfg) < 0) {
        fprintf(stderr, "Error: ADS1115 not responding at 0x%02X. Check wiring.\n", ADS1115_ADDR);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("ADS1115 detected (config=0x%04X). Starting MLX91219 current readings...\n", cfg);

    while (g_running) {
        int16_t raw;
        if (ads1115_read_ain0(g_i2c_handle, &raw) < 0) {
            fprintf(stderr, "Warning: I2C read error, retrying...\n");
            gpioDelay(500000);
            continue;
        }

        /* Convert raw ADC value to voltage (PGA ±4.096V, 16-bit signed) */
        float voltage = (float)raw * 4.096f / 32768.0f;

        /* Convert voltage to current (40 mV/A, mid-supply offset) */
        float current = (voltage - MLX_OFFSET) / MLX_SENSITIVITY;

        printf("Current: %.4f A\n", current);

        gpioDelay(500000); /* 500 ms */
    }

    printf("\nShutting down...\n");
    i2cClose(g_i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

