    if (ads1115_read_reg(g_i2c_handle, ADS_REG_CONFIG, &cfg) < 0) {
        fprintf(stderr, "Error: ADS1115 not responding at 0x%02X. Check wiring.\n", ADS1115_ADDR);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("ADS1115 detected (config=0x%04X). Starting MLX91219 current readings...\n", cfg);

    while (g_running) {
        int16_t raw;
        if (ads1115_read_ain0(g_i2c_handle, &raw) < 0) {
            fprintf(stderr, "Warning: I2C read error, retrying...\n");
            gpioDelay(500000);
            continue;
        }

        /* Convert raw ADC value to voltage (PGA ±4.096V, 16-bit signed) */
        float voltage = (float)raw * 4.096f / 32768.0f;

        /* Convert voltage to current (40 mV/A, mid-supply offset) */
        float current = (voltage - MLX_OFFSET) / MLX_SENSITIVITY;

        printf("Current: %.4f A\n", current);

        gpioDelay(500000); /* 500 ms */
    }

    printf("\nShutting down...\n");
    i2cClose(g_i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

