#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

/* ----------------------------- Configuration ----------------------------- */
#define FLAME_SENSOR_GPIO      4
#define BUZZER_GPIO            27
#define I2C_BUS                1
#define ADS1115_ADDR           0x48
#define ADS1115_CONV_REG       0x00
#define ADS1115_CONFIG_REG     0x01
#define ADS1115_CONFIG_BASE    0xC283  /* AIN0 single-ended, ±4.096V, single-shot, 128 SPS */
#define TEMP_THRESHOLD         60.0f   /* °C — fire threshold */
#define DEBOUNCE_MS            50      /* ms between accepted flame events */
#define POLL_INTERVAL_US       100000  /* 100 ms */
#define BUZZER_DURATION_US     2000000 /* 2 s */
#define LOG_FILE               "fire_log.txt"

/* ----------------------------- Globals ----------------------------------- */
static volatile sig_atomic_t g_running = 1;
static volatile sig_atomic_t g_flame_event = 0;
static volatile uint32_t     g_last_flame_tick = 0;
static int                   g_i2c_handle = -1;
static FILE                  *g_log_file  = NULL;

/* ----------------------------- Prototypes -------------------------------- */
static void flame_isr(int gpio, int level, uint32_t tick, void *userdata);
static int  read_temperature(float *temp_out);
static void log_event(const char *msg);
static void cleanup(void);
static void signal_handler(int sig);

/* ----------------------------- ISR --------------------------------------- */
static void flame_isr(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio; (void)userdata;

    if (level != 0)            /* only falling edge */
        return;

    uint32_t now = tick;
    uint32_t elapsed = now - g_last_flame_tick;  /* pigpio ticks are 32-bit; wraps handled correctly */
    if (elapsed < DEBOUNCE_MS * 1000)            /* debounce */
        return;
    g_last_flame_tick = now;
    g_flame_event = 1;
}

/* ----------------------------- Temperature -------------------------------- */
static int read_temperature(float *temp_out)
{
    /* Trigger a single-shot conversion on AIN0 */
    char config[3];
    config[0] = ADS1115_CONFIG_REG;
    config[1] = (ADS1115_CONFIG_BASE >> 8) & 0xFF;
    config[2] = ADS1115_CONFIG_BASE & 0xFF;

    if (i2cWriteDevice(g_i2c_handle, config, 3) != 0) {
        fprintf(stderr, "Error: failed to write ADS1115 config register\n");
        return -1;
    }

    /* Wait for conversion to complete (~8.5 ms at 128 SPS) */
    gpioDelay(10000);  /* 10 ms */

    char reg = ADS1115_CONV_REG;
    if (i2cWriteDevice(g_i2c_handle, &reg, 1) != 0) {
        fprintf(stderr, "Error: failed to set ADS1115 conversion register pointer\n");
        return -1;
    }

    char data[2];
    if (i2cReadDevice(g_i2c_handle, data, 2) != 2) {
        fprintf(stderr, "Error: failed to read ADS1115 conversion data\n");
        return -1;
    }

    int16_t raw = (int16_t)((data[0] << 8) | (data[1] & 0xFF));
    /* ±4.096 V range; 16-bit signed; 1 bit = 0.000125 V */
    float voltage = (float)raw * 0.000125f;
    /* Map 0–3.3 V to 20–80 °C (linear) */
    *temp_out = 20.0f + (voltage / 3.3f) * 60.0f;
    return 0;
}

/* ----------------------------- Logging ----------------------------------- */
static void log_event(const char *msg)
{
    if (!g_log_file)
        return;

    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

    fprintf(g_log_file, "%s: %s\n", ts, msg);
    fflush(g_log_file);
}

/* ----------------------------- Cleanup ----------------------------------- */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    /* Ensure buzzer is off */
    gpioWrite(BUZZER_GPIO, 0);
    gpioTerminate();
}

/* ----------------------------- Signal handler ---------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- Main -------------------------------------- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return 1;
    }

    /* Configure flame sensor pin as input with pull-up */
    gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(FLAME_SENSOR_GPIO, PI_PUD_UP);

    /* Configure buzzer pin as output, initially off */
    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);
    gpioWrite(BUZZER_GPIO, 0);

    /* Open I2C bus to ADS1115 */
    g_i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: failed to open I2C bus %d at address 0x%02X (code %d)\n",
                I2C_BUS, ADS1115_ADDR, g_i2c_handle);
        gpioTerminate();
        return 1;
    }

    /* Open log file in append mode */
    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        fprintf(stderr, "Error: cannot open log file '%s'\n", LOG_FILE);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return 1;
    }

    /* Register ISR for flame sensor (falling edge) */
    if (gpioSetISRFuncEx(FLAME_SENSOR_GPIO, FALLING_EDGE, 0, flame_isr, NULL) != 0) {
        fprintf(stderr, "Error: failed to register ISR on GPIO %d\n", FLAME_SENSOR_GPIO);
        cleanup();
        return 1;
    }

    /* Install signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install SIGINT handler\n");
    }

    log_event("Fire monitoring system started");

    /* Main polling loop */
    while (g_running) {
        float temp = 0.0f;
        int   rc = read_temperature(&temp);

        if (rc == 0) {
            if (g_flame_event) {
                char msg[128];
                snprintf(msg, sizeof(msg),
                         "Flame detected! Temperature: %.1f°C", temp);
                log_event(msg);
                gpioWrite(BUZZER_GPIO, 1);
                gpioDelay(BUZZER_DURATION_US);
                gpioWrite(BUZZER_GPIO, 0);
                g_flame_event = 0;
            } else if (temp > TEMP_THRESHOLD) {
                char msg[128];
                snprintf(msg, sizeof(msg),
                         "Temperature above threshold: %.1f°C", temp);
                log_event(msg);
            }
        } else {
            /* I2C error — log and continue */
            log_event("Error: ADC read failure");
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    /* Graceful shutdown */
    log_event("Fire monitoring system shutting down");
    cleanup();
    return 0;
}

