#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define DEFAULT_ADC_CHANNEL 0
#define DEFAULT_CURRENT_THRESHOLD 5.0
#define DEFAULT_FAN_GPIO_LINE 18
#define DEFAULT_SPI_DEVICE "/dev/spidev0.0"
#define DEFAULT_SPI_SPEED 1000000
#define DEFAULT_SPI_MODE 0
#define DEFAULT_SPI_BITS 8
#define DEFAULT_SENSOR_SENSITIVITY 0.1
#define LOG_FILE "current_log.txt"
#define SAMPLE_INTERVAL_US 1000000
#define ADC_MAX_VALUE 1023
#define ADC_VREF 3.3
#define ADC_CHANNEL_MASK 0x03

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *fan_line = NULL;
static int fan_state = 0;
static double current_threshold = DEFAULT_CURRENT_THRESHOLD;
static int adc_channel = DEFAULT_ADC_CHANNEL;
static double sensor_sensitivity = DEFAULT_SENSOR_SENSITIVITY;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_init(const char *device, int speed, int mode, int bits) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("open SPI device");
        return -1;
    }
    uint8_t mode_val = mode;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode_val) < 0) {
        perror("ioctl SPI_IOC_WR_MODE");
        close(fd);
        return -1;
    }
    uint8_t bits_val = bits;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits_val) < 0) {
        perror("ioctl SPI_IOC_WR_BITS_PER_WORD");
        close(fd);
        return -1;
    }
    uint32_t speed_val = speed;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed_val) < 0) {
        perror("ioctl SPI_IOC_WR_MAX_SPEED_HZ");
        close(fd);
        return -1;
    }
    return fd;
}

static int read_adc(int fd, int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }
    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = DEFAULT_SPI_SPEED,
        .delay_usecs = 0,
        .bits_per_word = DEFAULT_SPI_BITS,
    };
    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("ioctl SPI_IOC_MESSAGE");
        return -1;
    }
    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    if (adc_value == 0 || adc_value == 1023) {
        fprintf(stderr, "Warning: ADC reading at rail (%d) - sensor may be disconnected\n", adc_value);
    }
    return adc_value;
}

static double adc_to_current(int adc_value, double sensitivity) {
    return (double)adc_value * sensor_sensitivity / ADC_VREF;
}

static int set_fan_state(int state) {
    if (fan_line) {
        if (gpiod_line_set_value(fan_line, state) < 0) {
            perror("gpiod_line_set_value");
            return -1;
        }
        fan_state = state;
        return 0;
    }
    return -1;
}

static void log_current(double current) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log file");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
        fprintf(fp, "%s, Current: %.4f A\n", ts, current);
    } else {
        fprintf(fp, "(time error), Current: %.4f A\n", current);
    }
    fclose(fp);
}

static void cleanup(void) {
    if (fan_line) {
        gpiod_line_set_value(fan_line, 0);
        gpiod_line_release(fan_line);
        fan_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
}

int main(int argc, char *argv[]) {
    int opt;
    while ((opt = getopt(argc, argv, "c:t:s:h")) != -1) {
        switch (opt) {
            case 'c': adc_channel = atoi(optarg); break;
            case 't': current_threshold = atof(optarg); break;
            case 's': sensor_sensitivity = atof(optarg); break;
            case 'h':
            default:
                fprintf(stderr, "Usage: %s [-c adc_channel] [-t current_threshold] [-s sensor_sensitivity]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    struct sigaction sa = { .sa_handler = signal_handler };
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    spi_fd = spi_init(DEFAULT_SPI_DEVICE, DEFAULT_SPI_SPEED, DEFAULT_SPI_MODE, DEFAULT_SPI_BITS);
    if (spi_fd < 0) {
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        chip = gpiod_chip_open_by_number(0);
    }
    if (!chip) {
        perror("gpiod_chip_open");
        cleanup();
        return EXIT_FAILURE;
    }
    fan_line = gpiod_chip_get_line(chip, DEFAULT_FAN_GPIO_LINE);
    if (!fan_line) {
        perror("gpiod_chip_get_line");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_output(fan_line, "fan_control", 0) < 0) {
        perror("gpiod_line_request_output");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Current monitoring started. Threshold: %.2f A, ADC channel: %d, SPI: %s, Fan GPIO: %d\n",
           current_threshold, adc_channel, DEFAULT_SPI_DEVICE, DEFAULT_FAN_GPIO_LINE);

    while (running) {
        int adc_value = read_adc(spi_fd, adc_channel);
        if (adc_value < 0) {
            fprintf(stderr, "SPI read error, retrying...\n");
            usleep(SAMPLE_INTERVAL_US);
            continue;
        }
        double current = adc_to_current(adc_value, sensor_sensitivity);
        log_current(current);

        if (current > current_threshold) {
            if (!fan_state) {
                if (set_fan_state(1) == 0) {
                    fan_state = 1;
                    printf("Fan ON\n");
                }
            }
        } else {
            if (fan_state) {
                if (set_fan_state(0) == 0) {
                    fan_state = 0;
                    printf("Fan OFF\n");
                }
            }
        }
        usleep(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

