#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x28
#define LOG_FILE "co_log.txt"
#define SAMPLE_INTERVAL_SEC 5

// ADS1115 register addresses
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG 0x01

// ADS1115 config: single-shot, AIN0, +/-4.096V, 128 SPS, continuous
#define ADS1115_CONFIG_BASE 0x8000  // OS bit
#define ADS1115_CONFIG_MUX_AIN0 0x4000 // MUX[14:12] = 100
#define ADS1115_CONFIG_PGA_4_096V 0x0200 // PGA[11:9] = 001
#define ADS1115_CONFIG_MODE_CONTINUOUS 0x0000 // MODE[8:6] = 000
#define ADS1115_CONFIG_DR_128SPS 0x0080 // DR[5:3] = 100
#define ADS1115_CONFIG_CQUE_NONE 0x0003 // COMP_QUE[1:0] = 11

#define ADS1115_VREF 4.096f
#define ADS1115_MAX_COUNT 32767.0f

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int read_ads1115_raw(int handle, int16_t *raw_value) {
    uint16_t config = ADS1115_CONFIG_BASE | ADS1115_CONFIG_MUX_AIN0 |
                      ADS1115_CONFIG_PGA_4_096V | ADS1115_CONFIG_MODE_CONTINUOUS |
                      ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_CQUE_NONE;

    // Write config to ADS1115 config register
    char config_buf[3];
    config_buf[0] = ADS1115_REG_CONFIG;
    config_buf[1] = (config >> 8) & 0xFF;
    config_buf[2] = config & 0xFF;

    if (i2cWriteDevice(handle, config_buf, 3) != 0) {
        return -1;
    }

    // Wait for conversion (128 SPS -> ~7.8ms, wait 10ms to be safe)
    gpioDelay(10000);

    // Read conversion register
    char reg_buf[1] = {ADS1115_REG_CONVERSION};
    if (i2cWriteDevice(handle, reg_buf, 1) != 0) {
        return -1;
    }

    char data_buf[2];
    if (i2cReadDevice(handle, data_buf, 2) != 2) {
        return -1;
    }

    *raw_value = (int16_t)((data_buf[0] << 8) | data_buf[1]);
    return 0;
}

float calculate_ppm(int16_t raw_value) {
    // Placeholder calibration curve for CO concentration (PPM)
    // Replace with actual calibration data from the sensor datasheet
    float ppm = 0.0f;
    if (raw_value > 0) {
        ppm = 100.0f * (float)raw_value / 10000.0f; // Example linear relationship
    }
    return ppm;
}

int log_ppm(float ppm) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            perror("Error opening log file");
            return -1;
        }
    }

    if (fprintf(log_file, "%s, %.2f PPM\n", timestamp, ppm) < 0) {
        perror("Error writing to log file");
        return -1;
    }
    fflush(log_file);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Failed to set up signal handlers");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at address 0x%02X on bus %d\n", I2C_ADDR, I2C_BUS);
        gpioTerminate();
        return 1;
    }

    printf("CO Sensor Monitoring Started. Press Ctrl+C to exit.\n");

    while (running) {
        int16_t raw_value = 0;
        if (read_ads1115_raw(i2c_handle, &raw_value) != 0) {
            fprintf(stderr, "Error reading from I2C device. Check sensor connection.\n");
            gpioDelay(SAMPLE_INTERVAL_SEC * 1000000);
            continue;
        }

        float ppm = calculate_ppm(raw_value);
        if (log_ppm(ppm) != 0) {
            fprintf(stderr, "Error logging PPM value.\n");
        }

        printf("CO Concentration: %.2f PPM (Raw: %d)\n", ppm, raw_value);

        gpioDelay(SAMPLE_INTERVAL_SEC * 1000000);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return 0;
}

