#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define MICS4514_ADDR 0x68
#define CO_REG 0x04
#define NO2_REG 0x06
#define LOG_FILE "co_log.txt"
#define ALERT_FILE "alert_log.txt"
#define ALERT_THRESHOLD 25.0
#define READ_INTERVAL 5

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int read_sensor_data(int handle, int *co_ppm, int *no2_ppm) {
    char buf[4];
    int result = i2cReadI2CBlockData(handle, CO_REG, buf, 4);
    if (result != 4) {
        fprintf(stderr, "Error reading CO/NO2 data: %d\n", result);
        return -1;
    }
    *co_ppm = (buf[0] << 8) | buf[1];
    *no2_ppm = (buf[2] << 8) | buf[3];
    return 0;
}

float calculate_co_ppm(int raw_value) {
    return (float)raw_value / 100.0;
}

void log_co_level(float co_ppm) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s, %.2f PPM\n", timestamp, co_ppm);
    fclose(fp);
}

void log_alert(float co_ppm) {
    FILE *fp = fopen(ALERT_FILE, "a");
    if (!fp) {
        perror("Error opening alert file");
        return;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s, CO Level: %.2f PPM (Alert: > %.0f PPM)\n", timestamp, co_ppm, ALERT_THRESHOLD);
    fclose(fp);
}

void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, MICS4514_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Starting CO monitoring...\n");

    while (running) {
        int raw_co, raw_no2;
        if (read_sensor_data(i2c_handle, &raw_co, &raw_no2) == 0) {
            float co_ppm = calculate_co_ppm(raw_co);
            log_co_level(co_ppm);
            if (co_ppm > ALERT_THRESHOLD) {
                log_alert(co_ppm);
            }
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying in %d seconds.\n", READ_INTERVAL);
        }
        sleep(READ_INTERVAL);
    }

    cleanup();
    printf("Exiting.\n");
    return 0;
}

