#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SENSOR1_ADDR 0x48
#define SENSOR2_ADDR 0x49
#define SAMPLE_INTERVAL_US 100000
#define LOG_FILE "audio_log.txt"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_sensor(int handle, float *db_out) {
    char reg = 0x00;
    char buf[2];
    int ret;

    ret = i2cWriteDevice(handle, &reg, 1);
    if (ret < 0) {
        fprintf(stderr, "I2C write error (handle %d): %d\n", handle, ret);
        return -1;
    }

    ret = i2cReadDevice(handle, buf, 2);
    if (ret < 0) {
        fprintf(stderr, "I2C read error (handle %d): %d\n", handle, ret);
        return -1;
    }
    if (ret != 2) {
        fprintf(stderr, "I2C read short (handle %d): got %d bytes\n", handle, ret);
        return -1;
    }

    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *db_out = -38.0f + 20.0f * log10f((float)raw / 1000.0f);
    return 0;
}

static void log_data(float db1, float db2) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, db1, db2);
    } else {
        fprintf(fp, "UNKNOWN,%.2f,%.2f\n", db1, db2);
    }
    fclose(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    int h1 = i2cOpen(I2C_BUS, SENSOR1_ADDR, 0);
    if (h1 < 0) {
        fprintf(stderr, "Failed to open I2C for sensor 1 (0x%02X): %d\n", SENSOR1_ADDR, h1);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int h2 = i2cOpen(I2C_BUS, SENSOR2_ADDR, 0);
    if (h2 < 0) {
        fprintf(stderr, "Failed to open I2C for sensor 2 (0x%02X): %d\n", SENSOR2_ADDR, h2);
        i2cClose(h1);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        float db1 = -999.0f, db2 = -999.0f;

        if (read_sensor(h1, &db1) != 0) {
            fprintf(stderr, "Sensor 1 read failed\n");
        }
        if (read_sensor(h2, &db2) != 0) {
            fprintf(stderr, "Sensor 2 read failed\n");
        }

        log_data(db1, db2);
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    i2cClose(h1);
    i2cClose(h2);
    gpioTerminate();
    return EXIT_SUCCESS;
}

