#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <math.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define ADC_CHANNEL_1 0
#define ADC_CHANNEL_2 1
#define LED_GPIO 27
#define THRESHOLD 0.7f
#define SAMPLE_INTERVAL_US 1000 // 1 ms
#define WINDOW_DURATION_MS 100
#define NUM_SAMPLES (WINDOW_DURATION_MS * 1000 / SAMPLE_INTERVAL_US)
#define SCALE 100.0f

// Global variables
int spi_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_adc(int channel);
float calculate_rms(int *samples, int num_samples);
void log_data(float rms1, float rms2);
void signal_handler(int signal);
void cleanup();

// Function to read from MCP3008 ADC via SPI
int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    // MCP3008 SPI command format for single-ended mode:
    // Byte 0: Start bit (0x01)
    // Byte 1: SGL/DIFF=1 (single-ended) + D2 D1 D0 (channel) + padding
    // Byte 2: Don't care (clocks out remaining data)
    unsigned char tx_buf[3] = {0x01, (unsigned char)(0x80 | (channel << 4)), 0x00};
    unsigned char rx_buf[3] = {0};

    int ret = spiXfer(spi_handle, tx_buf, rx_buf, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed for channel %d (ret=%d)\n", channel, ret);
        return -1;
    }

