#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>

// Configuration
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG 0x01
#define OVERCURRENT_THRESHOLD 50.0
#define LED_GPIO 17
#define BUFFER_SIZE 100
#define SAMPLE_RATE_HZ 10
#define SAMPLE_PERIOD_US (1000000 / SAMPLE_RATE_HZ)

// ADS1115 Config: Single-shot, A0-GND, 4.096V, 128 SPS, Disable comparator
#define ADS1115_CONFIG_BASE 0x8000  // OS bit
#define ADS1115_CONFIG_MUX_A0 0x4000 // AIN0 vs GND
#define ADS1115_CONFIG_PGA_4_096 0x0200 // PGA = 4.096V
#define ADS1115_CONFIG_MODE_SINGLE 0x0100 // Single-shot mode
#define ADS1115_CONFIG_DR_128 0x0080 // 128 SPS
#define ADS1115_CONFIG_COMP_QUE_DISABLE 0x0003 // Disable comparator
#define ADS1115_CONFIG (ADS1115_CONFIG_BASE | ADS1115_CONFIG_MUX_A0 | ADS1115_CONFIG_PGA_4_096 | ADS1115_CONFIG_MODE_SINGLE | ADS1115_CONFIG_DR_128 | ADS1115_CONFIG_COMP_QUE_DISABLE)

// MLX91204: 0.5V to 4.5V for 0-100A, 5V supply
#define V_SUPPLY 5.0
#define V_MIN 0.5
#define V_MAX 4.5
#define MAX_CURRENT 100.0

// Circular buffer
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Global state
static int i2c_handle = -1;
static CircularBuffer current_buffer;
static volatile sig_atomic_t running = 1;

// Function prototypes
int initialize();
int read_ads1115(int16_t *raw_value);
float convert_to_current(int16_t raw_value);
void add_to_buffer(CircularBuffer *cb, float value);
float get_average(CircularBuffer *cb);
void check_overcurrent(float average_current);
void cleanup();
void signal_handler(int signal);

int main() {
    if (initialize() != 0) {
        fprintf(stderr, "Initialization failed. Exiting.\n");
        return 1;
    }

    signal(SIGINT, signal_handler);

    while (running) {
        int16_t raw_value;
        if (read_ads1115(&raw_value) == 0) {
            float current = convert_to_current(raw_value);
            add_to_buffer(&current_buffer, current);
            float avg = get_average(&current_buffer);
            check_overcurrent(avg);
        } else {
            fprintf(stderr, "Error reading sensor data. Retrying...\n");
        }
        gpioDelay(SAMPLE_PERIOD_US);
    }

    cleanup();
    return 0;
}

int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Verify ADS1115 is present by reading config register
    char config_buf[2];
    if (i2cReadI2CBlockData(i2c_handle, ADS1115_REG_CONFIG, config_buf, 2) != 2) {
        fprintf(stderr, "ADS1115 not detected at address 0x%02X\n", ADS1115_ADDR);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    current_buffer.head = 0;
    current_buffer.count = 0;

    return 0;
}

int read_ads1115(int16_t *raw_value) {
    char config_buf[3];
    char read_buf[2];

    // Write config to start single conversion
    config_buf[0] = ADS1115_REG_CONFIG;
    config_buf[1] = (ADS1115_CONFIG >> 8) & 0xFF;
    config_buf[2] = ADS1115_CONFIG & 0xFF;
    if (i2cWriteDevice(i2c_handle, config_buf, 3) != 3) {
        fprintf(stderr, "Error writing ADS1115 config\n");
        return 1;
    }

    // Wait for conversion (128 SPS -> ~8ms, add margin)
    gpioDelay(10000);

    // Point to conversion register
    char reg_buf[1] = {ADS1115_REG_CONVERSION};
    if (i2cWriteDevice(i2c_handle, reg_buf, 1) != 1) {
        fprintf(stderr, "Error setting ADS1115 conversion register\n");
        return 1;
    }

    // Read 2 bytes
    if (i2cReadDevice(i2c_handle, read_buf, 2) != 2) {
        fprintf(stderr, "Error reading ADS1115 conversion\n");
        return 1;
    }

    *raw_value = (read_buf[0] << 8) | read_buf[1];
    return 0;
}

float convert_to_current(int16_t raw_value) {
    // Convert raw 16-bit signed value to voltage (PGA = 4.096V, 16-bit signed)
    // Full scale = 32767 * 4.096V = 134.2176V
    // Raw range = -32768 to 32767
    // Voltage = raw * (4.096 / 32768)
    float voltage = (float)raw_value * (V_SUPPLY / 32768.0);
    // Ratiometric conversion: current = (voltage - V_MIN) / (V_MAX - V_MIN) * MAX_CURRENT
    return ((voltage - V_MIN) / (V_MAX - V_MIN)) * MAX_CURRENT;
}

void add_to_buffer(CircularBuffer *cb, float value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
}

float get_average(CircularBuffer *cb) {
    if (cb->count == 0) return 0.0;
    float sum = 0.0;
    for (int i = 0; i < cb->count; i++) {
        sum += cb->buffer[i];
    }
    return sum / cb->count;
}

void check_overcurrent(float average_current) {
    if (average_current > OVERCURRENT_THRESHOLD) {
        gpioWrite(LED_GPIO, 1);
        printf("OVERCURRENT DETECTED! Average Current: %.2f A\n", average_current);
    } else {
        gpioWrite(LED_GPIO, 0);
    }
}

void cleanup() {
    printf("Cleaning up...\n");
    gpioWrite(LED_GPIO, 0);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

