#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TCS34725_I2C_ADDR 0x29
#define TCS34725_ENABLE 0x00
#define TCS34725_ATIME 0x01
#define TCS34725_ID 0x12
#define TCS34725_CDATA 0x14
#define TCS34725_RDATA 0x16
#define TCS34725_GDATA 0x18
#define TCS34725_BDATA 0x1A
#define TCS34725_CONTROL 0x0F
#define TCS34725_POWER_ON 0x01
#define TCS34725_AEN 0x02
#define TCS34725_ID_VALUE 0x44
#define ATIME_2_4MS 0xFF
#define GAIN_4X 0x01
#define LOG_FILE "color_log.csv"
#define MAX_CONSECUTIVE_READ_ERRORS 3

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int i2c_write_byte(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg 0x%02X, val 0x%02X): %d\n", reg, value, rc);
    }
    return rc;
}

static int i2c_read_word(int handle, uint8_t reg, uint16_t *out) {
    int rc = i2cReadWordData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg 0x%02X): %d\n", reg, rc);
        return -1;
    }
    *out = (uint16_t)rc;
    return 0;
}

static int initialize_sensor(int handle) {
    if (i2c_write_byte(handle, TCS34725_ENABLE, TCS34725_POWER_ON) < 0) return -1;
    if (i2c_write_byte(handle, TCS34725_ATIME, ATIME_2_4MS) < 0) return -1;
