        }
        fprintf(stderr, "SPI transfer failed (attempt %d/%d): %s\n", attempt + 1, MAX_RETRIES, strerror(errno));
        usleep(10000);
    }
    return -1;
}

static float convert_to_current(int adc_value) {
    float voltage = (float)adc_value / ADC_MAX * ADC_VREF;
    return (voltage - CURRENT_OFFSET) / CURRENT_SENSITIVITY;
