#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define MLX90817_ADDR  0x40
#define PRESSURE_REG   0x00
#define LOG_FILE       "pressure_log.csv"
#define SAMPLE_US      1000000  /* 1 second */
#define MAX_READ_RETRIES 3

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits cleanly               */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a CSV row with an ISO 8601 UTC timestamp                    */
/* ------------------------------------------------------------------ */
static int log_pressure(FILE *fp, float pressure_kPa)
{
    time_t     now;
    struct tm  utc;
    char       ts[32];

    time(&now);
    gmtime_r(&now, &utc);
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &utc);

    if (fprintf(fp, "%s,%.2f\n", ts, pressure_kPa) < 0) {
        perror("fprintf");
        return -1;
    }
    if (fflush(fp) != 0) {
        perror("fflush");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read 16-bit pressure from the MLX90817 register                    */
/* Returns 0 on success, -1 on I2C error.                             */
/* ------------------------------------------------------------------ */
static int read_pressure(int handle, float *pressure_kPa)
{
    char buf[2];
    int  rc;

    rc = i2cReadI2CBlockData(handle, PRESSURE_REG, buf, 2);
    if (rc != 2) {
        fprintf(stderr,
                "I2C read failed from reg 0x%02X (rc=%d): %s\n",
                PRESSURE_REG, rc, pigpio_error(rc));
        return -1;
    }

    uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) |
                   (uint16_t)(uint8_t)buf[1];
    *pressure_kPa = ((float)raw / 65535.0f) * 500.0f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    float pressure_kPa;

    /* --- pigpio init ------------------------------------------------ */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- open I2C --------------------------------------------------- */
    g_i2c_handle = i2cOpen(I2C_BUS, MLX90817_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed (bus=%d, addr=0x%02X): %s\n",
                I2C_BUS, MLX90817_ADDR, pigpio_error(g_i2c_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- open log file (append, write header once) ------------------ */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("fopen(" LOG_FILE ")");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write header only if file is empty */
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "timestamp,pressure_kPa\n");
        fflush(g_log_file);
    }

    /* --- signal handlers ------------------------------------------- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MLX90817 pressure logger started. Logging to %s\n", LOG_FILE);
    printf("Press Ctrl+C to stop.\n");

    /* --- main loop -------------------------------------------------- */
    while (g_running) {
        if (read_pressure(g_i2c_handle, &pressure_kPa) == 0) {
            if (log_pressure(g_log_file, pressure_kPa) != 0) {
                fprintf(stderr, "Logging failed; continuing.\n");
            }
        } else {
            fprintf(stderr, "Read failed; will retry next cycle.\n");
        }
        gpioDelay(SAMPLE_US);
    }

    /* --- cleanup ---------------------------------------------------- */
    printf("\nShutting down...\n");
    if (g_log_file != NULL) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

