#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define LED_PIN 17
#define PRESSURE_THRESHOLD 105.0
#define RETRY_COUNT 3
#define RETRY_DELAY_US 100000

#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG 0x01

#define ADS1115_CONFIG_OS_SINGLE 0x8000
#define ADS1115_CONFIG_MUX_AIN0 0x4000
#define ADS1115_CONFIG_MUX_AIN1 0x5000
#define ADS1115_CONFIG_PGA_2_3 0x0200
#define ADS1115_CONFIG_MODE_SINGLE 0x0100
#define ADS1115_CONFIG_DR_128 0x0080

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int ads1115_read(int handle, int16_t *raw) {
    uint16_t config = ADS1115_CONFIG_OS_SINGLE | ADS1115_CONFIG_MUX_AIN0 | ADS1115_CONFIG_PGA_2_3 | ADS1115_CONFIG_MODE_SINGLE | ADS1115_CONFIG_DR_128;
    char cfg[3];
    cfg[0] = ADS1115_REG_CONFIG;
    cfg[1] = (config >> 8) & 0xFF;
    cfg[2] = config & 0xFF;

    if (i2cWriteDevice(handle, cfg, 3) < 0) return -1;
    gpioDelay(10000);

    char reg[1] = {ADS1115_REG_CONVERSION};
    if (i2cWriteDevice(handle, reg, 1) < 0) return -1;
    char data[2];
    if (i2cReadDevice(handle, data, 2) != 2) return -1;

    *raw = (int16_t)((data[0] << 8) | data[1]);
    return 0;
