#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define ADC_CHANNEL 0
#define OVERCURRENT_THRESHOLD 10.0
#define SHUTDOWN_PIN 27
#define SAMPLE_INTERVAL_US 100000
#define VREF 3.3
#define ADC_MAX 1024.0
#define SENSOR_SENSITIVITY 0.066
#define SENSOR_ZERO_CURRENT 0.5

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (ret=%d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return adc_value;
}

static float adc_to_current(int adc_value) {
    float voltage = (float)adc_value / ADC_MAX * VREF;
    return (voltage - SENSOR_ZERO_CURRENT) / SENSOR_SENSITIVITY;
}

static void log_current(float current) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm_info);

    if (fprintf(log_file, "%s, Current: %.3f A\n", ts, current) < 0) {
        fprintf(stderr, "Error writing to log file\n");
    }
    fflush(log_file);
}

static void shutdown_system(void) {
    gpioWrite(SHUTDOWN_PIN, 1);
    gpioDelay(500000);
    gpioWrite(SHUTDOWN_PIN, 0);
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle=%d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SHUTDOWN_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", SHUTDOWN_PIN);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(SHUTDOWN_PIN, 0);

    log_file = fopen("current_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Monitoring current... Press Ctrl+C to exit.\n");

    while (running) {
        int adc = read_adc(ADC_CHANNEL);
        if (adc < 0) {
            fprintf(stderr, "ADC read error, retrying...\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        float current = adc_to_current(adc);

        log_current(current);

        if (current > OVERCURRENT_THRESHOLD) {
            printf("OVERCURRENT DETECTED: %.3f A\n", current);
            shutdown_system();
            break;
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    if (spi_handle >= 0) spiClose(spi_handle);
    if (log_file) fclose(log_file);
    gpioWrite(SHUTDOWN_PIN, 0);
    gpioTerminate();
    printf("Shutdown complete.\n");
    return EXIT_SUCCESS;
}

