#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_CONFIG_OS_BEGIN (1 << 15)
#define ADS1115_CONFIG_MUX_AIN0_GND (0x04 << 12)
#define ADS1115_CONFIG_PGA_4_096V (0x01 << 9)
#define ADS1115_CONFIG_MODE_SINGLE (0x01 << 8)
#define ADS1115_CONFIG_DR_128SPS (0x00 << 5)
#define ADS1115_CONFIG_CQUE_NONE (0x03 << 0)
#define ADS1115_CONFIG (ADS1115_CONFIG_OS_BEGIN | ADS1115_CONFIG_MUX_AIN0_GND | ADS1115_CONFIG_PGA_4_096V | ADS1115_CONFIG_MODE_SINGLE | ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_CQUE_NONE)
#define V_OFFSET 0.5
#define SENSITIVITY 0.1
#define MAX_PRESSURE 100.0
#define LOG_FILE "pressure_log.txt"
#define SAMPLE_INTERVAL_US 1000000

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_i2c();
int read_ads1115(int16_t *raw_value);
double convert_to_pressure(int16_t raw_value);
int log_pressure(double pressure);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

// Initialize I2C communication with ADS1115
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %s\n", I2C_BUS, ADS1115_ADDR, strerror(errno));
        return -1;
    }
    return 0;
}

// Read raw ADC value from ADS1115
int read_ads1115(int16_t *raw_value) {
    char config_buf[3];
    char reg_buf[1];
    char data_buf[2];
    int result;

    // Write config to start conversion
    config_buf[0] = ADS1115_REG_CONFIG;
    config_buf[1] = (ADS1115_CONFIG >> 8) & 0xFF;
    config_buf[2] = ADS1115_CONFIG & 0xFF;
    result = i2cWriteDevice(i2c_handle, config_buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error writing ADS1115 config: %s\n", strerror(errno));
        return -1;
    }

    // Wait for conversion to complete (128 SPS -> ~8ms, wait 10ms for safety)
    gpioDelay(10000);

    // Read conversion register
    reg_buf[0] = ADS1115_REG_CONVERSION;
    result = i2cWriteDevice(i2c_handle, reg_buf, 1);
    if (result != 0) {
        fprintf(stderr, "Error setting conversion register pointer: %s\n", strerror(errno));
        return -1;
    }

    result = i2cReadDevice(i2c_handle, data_buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading ADS1115 conversion: %s\n", strerror(errno));
        return -1;
    }

    *raw_value = (data_buf[0] << 8) | data_buf[1];
    return 0;
}

// Convert raw ADC value to pressure in kPa
double convert_to_pressure(int16_t raw_value) {
    double voltage = (double)raw_value * 4.096 / 32768.0;
    double pressure = (voltage - V_OFFSET) / SENSITIVITY;
    return pressure;
}

// Log pressure reading to file with timestamp
int log_pressure(double pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error getting local time\n");
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s, %.2f kPa\n", timestamp, pressure) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(log_file);
    return 0;
}

int main() {
    int16_t raw_value;
    double pressure;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Pressure monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        if (read_ads1115(&raw_value) == 0) {
            pressure = convert_to_pressure(raw_value);
            if (pressure >= 0.0 && pressure <= MAX_PRESSURE) {
                if (log_pressure(pressure) != 0) {
                    fprintf(stderr, "Error logging pressure data\n");
                }
            } else {
                fprintf(stderr, "Pressure out of range: %.2f kPa\n", pressure);
            }
        } else {
            fprintf(stderr, "Error reading pressure data\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    // Cleanup
    cleanup();
    printf("Pressure monitoring stopped.\n");
    return 0;
}

