#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define MCP3208_CHANNEL 0
#define VREF 5.0
#define R0 10.0
#define BETA 3950.0
#define ALERT_THRESHOLD 80.0
#define LOG_FILE "humidity_log.txt"

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static FILE *log_file = NULL;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int read_mcp3208(int channel) {
    if (channel < 0 || channel > 7) return -1;
    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};
    if (spiXfer(spi_handle, tx, rx, 3) != 0) return -1;
    return ((rx[1] & 0x0F) << 8) | rx[2];
}

float calculate_humidity(int adc_value) {
    float vout = ((float)adc_value / 4095.0) * VREF;
    float rh = (vout - 0.824) / 0.0315;
    if (rh < 0) rh = 0;
    if (rh > 100) rh = 100;
    return rh;
}

float calculate_temperature(int adc_value) {
    float vout = ((float)adc_value / 4095.0) * VREF;
    float r = R0 * (VREF / vout - 1.0);
    float temp = BETA / (log10(r) - 0.5 * BETA);
    return temp;
}

void log_data(float humidity, float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    if (log_file) {
        fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, humidity, temperature);
        fflush(log_file);
    }
}

void send_email_alert(float humidity) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    char body[256];
    snprintf(body, sizeof(body), "Subject: Humidity Alert\n\nHumidity exceeded threshold at %s. Current humidity: %.2f%%", timestamp, humidity);
    FILE *smtp = popen("ssmtp -t", "w");
    if (smtp) {
        fprintf(smtp, "From: your_email@example.com\nTo: recipient@example.com\nReply-To: your_email@example.com\n\n%s", body);
        pclose(smtp);
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);
    while (running) {
        int adc_humidity = read_mcp3208(MCP3208_CHANNEL);
        if (adc_humidity < 0) {
            fprintf(stderr, "SPI read error\n");
            break;
        }
        float humidity = calculate_humidity(adc_humidity);
        int adc_temp = read_mcp3208(MCP3208_CHANNEL + 1);
        if (adc_temp < 0) {
            fprintf(stderr, "SPI read error\n");
            break;
        }
        float temperature = calculate_temperature(adc_temp);
        log_data(humidity, temperature);
        if (humidity > ALERT_THRESHOLD) {
            send_email_alert(humidity);
        }
        gpioDelay(1000000);
    }
    if (log_file) fclose(log_file);
    if (spi_handle >= 0) spiClose(spi_handle);
    gpioTerminate();
    return 0;
}

