static int read_adc(int channel, int *value) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }
    if (value == NULL) {
        return -1;
    }

    /* MCP3008 single-ended read: 3-byte transfer
     * tx[0] = 0x01 (start bit)
     * tx[1] = (0x08 | channel) << 4 (single-ended + channel)
     * tx[2] = 0x00 (don't care)
     * Result: 10-bit value in ((rx[1] & 0x03) << 8) | rx[2]
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    if (spiXfer(spi_handle, tx, rx, 3) != 3) {
        fprintf(stderr, "SPI transfer failed on channel %d\n", channel);
        return -1;
    }

    *value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return 0;
}

static double calculate_magnitude_g(int x, int y, int z) {
    double voltage_x = (x / (double)ADC_MAX_VALUE) * SUPPLY_VOLTAGE;
    double voltage_y = (y / (double)ADC_MAX_VALUE) * SUPPLY_VOLTAGE;
    double voltage_z = (z / (double)ADC_MAX_VALUE) * SUPPLY_VOLTAGE;

    double x_g = (voltage_x - ADXL335_ZERO_G_VOLTAGE) / ADXL335_SENSITIVITY;
    double y_g = (voltage_y - ADXL335_ZERO_G_VOLTAGE) / ADXL335_SENSITIVITY;
    double z_g = (voltage_z - ADXL335_ZERO_G_VOLTAGE) / ADXL335_SENSITIVITY;

    return sqrt(x_g * x_g + y_g * y_g + z_g * z_g);
}

static void log_data(int x, int y, int z, double magnitude, int impact) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s,%d,%d,%d,%.3f,%s\n",
                timestamp, x, y, z, magnitude, impact ? "IMPACT DETECTED" : "OK");
        fflush(log_file);
    } else {
        fprintf(stderr, "Error: Log file not open.\n");
    }
}

int main(void) {
    int i;
    int x, y, z;
    double magnitude;
    int impact;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (channel %d, %d Hz)\n", SPI_CHANNEL, SPI_SPEED);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Register signal handler */
    signal(SIGINT, signal_handler);

    printf("Impact detection started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        for (i = 0; i < ADC_CHANNELS; i++) {
            if (read_adc(adc_channels[i].channel, &adc_channels[i].x) != 0) {
                fprintf(stderr, "Failed to read ADC channel %d\n", adc_channels[i].channel);
                continue;
            }
            if (read_adc(adc_channels[i].channel + 1, &adc_channels[i].y) != 0) {
                fprintf(stderr, "Failed to read ADC channel %d\n", adc_channels[i].channel + 1);
                continue;
            }
            if (read_adc(adc_channels[i].channel + 2, &adc_channels[i].z) != 0) {
                fprintf(stderr, "Failed to read ADC channel %d\n", adc_channels[i].channel + 2);
                continue;
            }

            magnitude = calculate_magnitude_g(adc_channels[i].x, adc_channels[i].y, adc_channels[i].z);
            impact = (magnitude > IMPACT_THRESHOLD_G) ? 1 : 0;

            log_data(adc_channels[i].x, adc_channels[i].y, adc_channels[i].z, magnitude, impact);
        }
        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* Cleanup */
    printf("\nCleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

