/* Si1172 I2C 7-bit default address */
#define SI1172_ADDR 0x49

/* Si1172 register addresses */
#define SI1172_REG_COMMAND 0xC0
#define SI1172_REG_FIFO_DATA 0xC1
#define SI1172_REG_FIFO_DATA2 0xC2
#define SI1172_REG_FIFO_DATA3 0xC3
#define SI1172_REG_FIFO_DATA4 0xC4

/* Command to trigger a measurement (example: start PPG) */
#define SI1172_CMD_START_MEASUREMENT 0x0F

/* Sampling interval in microseconds (1 second) */
#define SAMPLE_INTERVAL_US 1000000

/* Global resources for signal handler cleanup */
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* Write a single byte to a Si1172 register via I2C */
static int si1172_write_reg(int handle, uint8_t reg, uint8_t value) {
    char buf[2];
    buf[0] = (char)reg;
    buf[1] = (char)value;
    if (i2cWriteDevice(handle, buf, 2) != 0) {
        fprintf(stderr, "Error writing 0x%02X to register 0x%02X: %s\n",
                value, reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* Read a single byte from a Si1172 register via I2C */
static int si1172_read_reg(int handle, uint8_t reg, uint8_t *value) {
    char buf[1];
    buf[0] = (char)reg;
    if (i2cWriteDevice(handle, buf, 1) != 0) {
        fprintf(stderr, "Error selecting register 0x%02X: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (i2cReadDevice(handle, buf, 1) != 1) {
        fprintf(stderr, "Error reading register 0x%02X: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *value = (uint8_t)buf[0];
    return 0;
}

/* Read 4 bytes of FIFO data (IR, RED, etc.) from Si1172 */
static int si1172_read_fifo(int handle, uint16_t *ir, uint16_t *red) {
    char buf[4];
    if (i2cWriteDevice(handle, SI1172_REG_FIFO_DATA, 1) != 0) {
        fprintf(stderr, "Error selecting FIFO data register: %s\n",
                strerror(errno));
        return -1;
    }
    if (i2cReadDevice(handle, buf, 4) != 4) {
        fprintf(stderr, "Error reading 4 bytes from FIFO: %s\n",
                strerror(errno));
        return -1;
    }
    *ir = (uint16_t)((uint8_t)buf[0] << 8 | (uint8_t)buf[1]);
    *red = (uint16_t)((uint8_t)buf[2] << 8 | (uint8_t)buf[3]);
    return 0;
}

/* Log a data row to the CSV file */
static int log_data(FILE *fp, uint32_t timestamp, uint16_t ir, uint16_t red,
                    int error_flag) {
    if (fprintf(fp, "%u,%u,%u,%d\n", timestamp, ir, red, error_flag) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at the Si1172 default address */
    i2c_handle = i2cOpen(1, SI1172_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at 0x%02X: %s\n",
                SI1172_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode; write header if file is empty */
    log_file = fopen("biometric_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,HR(bpm),SpO2(%%),Error\n");
        fflush(log_file);
    }

    /* Register signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not register SIGINT handler: %s\n",
                strerror(errno));
    }

    printf("Si1172 HR/SpO2 logger started. Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (!terminate) {
        uint16_t ir = 0, red = 0;
        int error_flag = 0;

        /* Trigger a measurement by writing the command register */
        if (si1172_write_reg(i2c_handle, SI1172_REG_COMMAND,
                             SI1172_CMD_START_MEASUREMENT) != 0) {
            error_flag = 1;
        } else {
            /* Wait for the measurement to complete (typical ~10 ms) */
            gpioDelay(15000);

            /* Read 4 bytes of FIFO data */
            if (si1172_read_fifo(i2c_handle, &ir, &red) != 0) {
                error_flag = 1;
            }
        }

        /* Get current timestamp */
        time_t now = time(NULL);

        /* Log the data row */
        if (log_data(log_file, now, ir, red, error_flag) != 0) {
            fprintf(stderr, "Logging failed; continuing.\n");
        }

        /* Wait for the next sample interval */
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    /* Cleanup */
    printf("\nShutting down...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    return EXIT_SUCCESS;
