#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_FLAGS 0
#define NUM_CHANNELS 2
#define SAMPLE_RATE 16000
#define SAMPLE_DELAY_US 1000
#define GAIN_DEFAULT 1.0f

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    char tx[3] = {0x01, (char)((0x08 | channel) << 4), 0x00};
    char rx[3] = {0};

    if (spiXfer(spi_handle, tx, rx, 3) != 3) {
        fprintf(stderr, "Error: SPI transfer failed on channel %d\n", channel);
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
}

static int16_t process_audio(int16_t left, int16_t right, float gain) {
    int16_t diff = left - right;
    diff = (int16_t)((float)diff * gain);
    if (diff > 32767) diff = 32767;
    if (diff < -32768) diff = -32768;
    return diff;
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    float gain = GAIN_DEFAULT;

    if (argc > 1) {
        gain = (float)atof(argv[1]);
        if (gain <= 0.0f) {
            fprintf(stderr, "Error: Invalid gain value. Must be positive.\n");
            return 1;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (handle=%d).\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Gain: %.2f\n", gain);
    printf("Noise cancellation (MP23ABS1 via MCP3008 on SPI0 CE0). Press Ctrl+C to exit.\n");

    while (running) {
        int16_t left = 0, right = 0;
        int ret = 0;

        for (int i = 0; i < NUM_CHANNELS; i++) {
            int val = read_mcp3008(i);
            if (val < 0) {
                ret = 1;
                break;
            }
            if (i == 0) left = (int16_t)val;
            else right = (int16_t)val;
        }

        if (ret) {
            fprintf(stderr, "Error: SPI read failure. Continuing...\n");
            gpioDelay(SAMPLE_DELAY_US);
            continue;
        }

        int16_t diff = process_audio(left, right, gain);
        printf("%d,%d,%d\n", left, right, diff);
        fflush(stdout);

        gpioDelay(SAMPLE_DELAY_US);
    }

    printf("\nExiting gracefully...\n");
    cleanup();
    return 0;
}

