#include <string.h>
#include <signal.h>
#include <unistd.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define MCP3008_CHANNEL 0
#define LOG_FILE "moisture_log.txt"
#define SAMPLE_INTERVAL 60

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    char tx_buf[3] = {0x01, (0x08 | channel) << 4, 0x00};
    char rx_buf[3] = {0};

    int result = spiXfer(spi_handle, tx_buf, rx_buf, 3);
    if (result != 3) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d)\n", result);
        return -1;
    }

    int adc_value = ((rx_buf[1] & 0x03) << 8) | (rx_buf[2] & 0xFF);
    return adc_value;
}

int log_data(int moisture_level) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm_info = gmtime(&t);
    if (tm_info == NULL) {
        perror("Error getting time");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm_info) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s,%d\n", timestamp, moisture_level) < 0) {
        perror("Error writing to log file");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("Error closing log file");
        return -1;
    }

    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Error setting SIGINT handler");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Error setting SIGTERM handler");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    printf("Soil moisture monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int moisture_level = read_mcp3008(MCP3008_CHANNEL);
        if (moisture_level < 0) {
            fprintf(stderr, "Error reading moisture level\n");
        } else {
            if (log_data(moisture_level) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        }

        for (int i = 0; i < SAMPLE_INTERVAL && running; i++) {
            sleep(1);
        }
    }

    printf("\nCleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
    printf("Exiting.\n");
    return 0;
}

