    while (running) {
        int raw_adc = -1;
        int retries = 0;
        int success = 0;

        while (retries < MAX_RETRIES && running) {
            raw_adc = read_mcp3008(0);
            if (raw_adc >= 0 && raw_adc <= ADC_MAX) {
                success = 1;
                break;
            }
            retries++;
            if (retries < MAX_RETRIES) {
                usleep(10000);
            }
        }

        if (!success) {
            fprintf(stderr, "Failed to read ADC after %d retries. Buzzer OFF for safety.\n", MAX_RETRIES);
            control_buzzer(0);
            usleep(SAMPLE_INTERVAL_MS * 1000);
            continue;
        }

        float voltage = read_voltage(raw_adc, read_temperature());
        float compensated_voltage = compensate_voltage(voltage, read_temperature());

        int flame_detected = (compensated_voltage > FLAME_THRESHOLD) ? 1 : 0;

        log_data(raw_adc, voltage, compensated_voltage, read_temperature(), flame_detected);
        control_buzzer(flame_detected);

        printf("Raw ADC: %d, Voltage: %.3f V, Compensated: %.3f V, Temp: %.2f C, Flame: %s\n",
               raw_adc, voltage, compensated_voltage, read_temperature(), flame_detected ? "YES" : "NO");

        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return 0;
}

