#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_FLAGS 0
#define LED_GPIO 17
#define WATER_LEVEL_THRESHOLD_HIGH 75.0
#define WATER_LEVEL_THRESHOLD_LOW 70.0
#define ADC_CHANNEL 0
#define SAMPLE_INTERVAL_US 5000000
#define JSON_FILE "water_levels.json"

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static FILE *json_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)(0x80 | (channel << 4)), 0x00 };
    unsigned char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed: %s\n", pigpio_error(ret));
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static float adc_to_percentage(int adc_value) {
    if (adc_value < 0) adc_value = 0;
    if (adc_value > 1023) adc_value = 1023;
    return (float)adc_value / 1023.0 * 100.0;
}

static int log_water_level(float water_level) {
    time_t now = time(NULL);
    struct tm tm_info;
    struct tm *t = localtime_r(&now, &tm_info);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", t);
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long ms = ts.tv_nsec / 1000000;

    if (json_file == NULL) {
        json_file = fopen(JSON_FILE, "r+");
        if (json_file == NULL) {
            json_file = fopen(JSON_FILE, "w+");
            if (json_file == NULL) {
                fprintf(stderr, "Failed to open %s\n", JSON_FILE);
                return -1;
            }
            fprintf(json_file, "[\n");
        } else {
            fseek(json_file, 0, SEEK_END);
            long size = ftell(json_file);
            if (size == 0) {
                fprintf(json_file, "[\n");
            } else {
                fseek(json_file, -1, SEEK_END);
                int c = fgetc(json_file);
                if (c == ']') {
                    fseek(json_file, -1, SEEK_END);
                    fprintf(json_file, ",\n");
                } else {
                    fseek(json_file, -1, SEEK_END);
                    fprintf(json_file, ",\n");
                }
            }
        }
    }

    fprintf(json_file, "  {\"timestamp\": \"%s.%03ld\", \"water_level\": %.2f},\n",
            timestamp, ms, water_level);
    fflush(json_file);
    return 0;
}

static void control_led(float water_level) {
    static int led_state = 0;
    if (water_level > WATER_LEVEL_THRESHOLD_HIGH && !led_state) {
        gpioWrite(LED_GPIO, 1);
        led_state = 1;
    } else if (water_level < WATER_LEVEL_THRESHOLD_LOW && led_state) {
        gpioWrite(LED_GPIO, 0);
        led_state = 0;
    }
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
    if (json_file != NULL) {
        fseek(json_file, -1, SEEK_END);
        int c = fgetc(json_file);
        if (c == ']') {
            fprintf(json_file, "]\n");
        } else {
            fprintf(json_file, ",\n]\n");
        }
        fclose(json_file);
        json_file = NULL;
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %s\n", pigpio_error(spi_handle));
        gpioTerminate();
        return 1;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Water level monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int adc_value = read_mcp3008(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value\n");
            gpioDelay(100000);
            continue;
        }

        float water_level = adc_to_percentage(adc_value);
        printf("Water level: %.2f%%\n", water_level);

        if (log_water_level(water_level) != 0) {
            fprintf(stderr, "Error logging water level\n");
        }

        control_led(water_level);

        gpioDelay(100000);
    }

    cleanup();
    printf("Water level monitoring stopped.\n");
    return 0;
}

