#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define LOG_FILE "airflow_log.csv"
#define SAMPLE_INTERVAL_US 100000 // 100 milliseconds

// Global variables
static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static FILE *log_file = NULL;

// Function prototypes
int read_mcp3008(int channel);
float convert_to_lpm(int adc_value);
int log_data(float lpm);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

// Cleanup resources
void cleanup() {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

// Read data from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    // MCP3008 SPI command format for single-ended mode:
    // Byte 0: Start bit (0x01)
    // Byte 1: Single-ended mode (0x80) | channel << 4
    // Byte 2: Don't care (0x00)
    unsigned char tx_buffer[3] = {0x01, (unsigned char)(0x80 | (channel << 4)), 0x00};
    unsigned char rx_buffer[3] = {0};

    // Perform SPI transaction
    int result = spiXfer(spi_handle, (char *)tx_buffer, (char *)rx_buffer, 3);
    if (result != 3) {
        fprintf(stderr, "Error: SPI transaction failed, returned %d\n", result);
        return -1;
    }

    // Extract 10-bit ADC value from response
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

