        fprintf(stderr, "pclose failed: %s\n", strerror(errno));
        return -1;
    }
    if (WIFEXITED(status) && WEXITSTATUS(status) != 0) {
        fprintf(stderr, "msmtp exited with status %d\n", WEXITSTATUS(status));
        return -1;
    }
    return 0;
}

static void log_data(FILE *fp, int moisture_percent) {
    time_t t = time(NULL);
    struct tm tm;
    if (!localtime_r(&t, &tm)) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, %d\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, moisture_percent);
    fflush(fp);
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

static void parse_arguments(int argc, char *argv[], Config *cfg) {
    cfg->spi_channel = SPI_CHANNEL;
    cfg->adc_channel = MCP3008_CHANNEL;
    cfg->min_raw = CALIBRATION_MIN;
    cfg->max_raw = CALIBRATION_MAX;
    cfg->moisture_threshold = MOISTURE_THRESHOLD;
    cfg->logging_interval = LOGGING_INTERVAL;
    cfg->email_recipient = strdup(EMAIL_RECIPIENT);
    cfg->smtp_config_file = strdup(EMAIL_RECIPIENT);
    int opt;
    while ((opt = getopt(argc, argv, "s:c:m:M:t:i:r:f:")) != -1) {
        switch (opt) {
            case 's': cfg->spi_channel = atoi(optarg); break;
            case 'c': cfg->adc_channel = atoi(optarg); break;
            case 'm': cfg->min_raw = atoi(optarg); break;
            case 'M': cfg->max_raw = atoi(optarg); break;
            case 't': cfg->moisture_threshold = atoi(optarg); break;
            case 'i': cfg->logging_interval = atoi(optarg); break;
            case 'r': {
                char *recipient = strdup(optarg);
                if (recipient) {
                    free(cfg->email_recipient);
                    cfg->email_recipient = recipient;
                }
            } break;
            case 'f': {
                char *config = strdup(optarg);
                if (config) {
                    free(cfg->smtp_config_file);
                    cfg->smtp_config_file = config;
                }
            } break;
            default:
                fprintf(stderr, "Usage: %s [-s spi_channel] [-c adc_channel] [-m min_raw] [-M max_raw] [-t threshold] [-i interval] [-r recipient] [-f smtp_config]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }
    if (!cfg->email_recipient || !cfg->smtp_config_file) {
        fprintf(stderr, "Error: recipient and smtp_config must be non-null\n");
        cleanup();
        exit(EXIT_FAILURE);
    }
}

int main(int argc, char *argv[]) {
    Config cfg;
    parse_arguments(argc, argv, &cfg);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %s\n", pigpio_error(spi_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Plant monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int raw_value = -1;
        int retries = 0;
        while (retries < MAX_SPI_RETRIES && !terminate) {
            raw_value = read_mcp3008(cfg.adc_channel);
            if (raw_value >= 0) break;
            retries++;
            if (retries < MAX_SPI_RETRIES) {
                fprintf(stderr, "ADC read failed, retrying (%d/%d)...\n", retries, MAX_SPI_RETRIES);
                sleep(5);
            }
        }
        if (raw_value < 0) {
            fprintf(stderr, "Failed to read ADC after %d retries, skipping cycle\n", MAX_SPI_RETRIES);
            sleep(LOGGING_INTERVAL);
            continue;
        }

        int moisture_percent = calibrate_sensor(raw_value);
        log_data(log_file, moisture_percent);

        if (moisture_percent < cfg.moisture_threshold) {
            printf("Moisture below threshold (%d%% < %d%%). Sending email alert.\n",
                   moisture_percent, cfg.moisture_threshold);
            if (send_email_alert(cfg.smtp_config_file) == 0) {
                printf("Email alert sent successfully.\n");
            } else {
                fprintf(stderr, "Failed to send email alert.\n");
            }
        }

        sleep(LOGGING_INTERVAL);
    }

    printf("Shutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

