#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL    0          /* SPI0 CE0 (GPIO8) */
#define SPI_SPEED      1000000    /* 1 MHz */
#define SPI_FLAGS      0          /* Mode 0, active-low CE */
#define ADC_CHANNEL    0          /* MCP3008 single-ended channel 0 */
#define LOG_FILE       "soil_moisture.log"
#define SAMPLE_US      1000000    /* 1 second */
#define ADC_MAX        1023       /* 10-bit ADC */

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read a single-ended channel from the MCP3008.
 * Returns 0-1023 on success, -1 on SPI transfer error.
 */
static int read_mcp3008(int handle, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read (3-byte transfer):
     *   tx[0] = 0x01  (start bit)
     *   tx[1] = (0x08 | channel) << 4  (single-ended + channel)
     *   tx[2] = 0x00  (clock out remaining bits)
     * Result: bits 9..0 are in rx[1] (low 2 bits) and rx[2] (8 bits).
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return adc;
}

static float calculate_moisture(int adc_value)
{
    float pct = ((float)adc_value / (float)ADC_MAX) * 100.0f;
    if (pct < 0.0f)   pct = 0.0f;
    if (pct > 100.0f) pct = 100.0f;
    return pct;
}

static void log_data(FILE *fp, int adc_value, float moisture_pct)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }

    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);

    if (fprintf(fp, "%s, ADC: %d, Moisture: %.2f%%\n", ts, adc_value, moisture_pct) < 0) {
        fprintf(stderr, "fprintf to log failed\n");
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed\n");
    }
}

static void cleanup(void)
{
    if (g_log_fp != NULL) {
        fflush(g_log_fp);
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();
}

int main(int argc, char *argv[])
{
    if (argc > 1) {
        int sample_us = atoi(argv[1]);
        if (sample_us <= 0) {
            fprintf(stderr, "Invalid sample interval; using 1 s\n");
            sample_us = 1000000;
        }
        printf("Using sample interval: %d us\n", sample_us);
    } else {
        printf("Using default sample interval: 1 s\n");
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI0 CE0 at 1 MHz, mode 0 */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (handle %d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Cannot open log file '%s'\n", LOG_FILE);
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
    }

    printf("Soil moisture monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int adc_value = read_mcp3008(g_spi_handle, ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Warning: ADC read failed; skipping sample\n");
        } else {
            float moisture_pct = calculate_moisture(adc_value);
            log_data(g_log_fp, adc_value, moisture_pct);
            printf("ADC: %d, Moisture: %.2f%%\n", adc_value, moisture_pct);
        }

        /* Sleep in small increments so signals are caught promptly */
        for (int i = 0; i < 10 && g_running; i++) {
            gpioDelay(sample_us / 100); /* 100 ms slices */
        }
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

