// Configuration
#define SPI_CHANNEL 0       // SPI0 CE0
#define SPI_SPEED 1000000   // 1 MHz
#define SPI_FLAGS 0          // Mode 0, active low CS
#define ADC_RESOLUTION 1024  // 10-bit ADC
#define VREF 3.3             // Reference voltage
#define MIN_VOLTAGE 0.5      // Minimum voltage for sensor (0.1 bar)
#define MAX_VOLTAGE 4.5      // Maximum voltage for sensor (1.5 bar)
#define MIN_PRESSURE 10.0    // Minimum pressure (kPa)
#define MAX_PRESSURE 150.0   // Maximum pressure (kPa)
#define SAMPLE_INTERVAL 1.0 // Sample interval in seconds

// Global variables
int spi_handle = -1;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float voltage_to_pressure(float voltage);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioTerminate();
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    // MCP3008 SPI command format for single-ended mode:
    // Byte 0: Start bit (0x01)
    // Byte 1: SGL/DIFF=1, D2 D1 D0 = channel, padded to 8 bits
    // Byte 2: Don't care (0x00)
    unsigned char tx_buffer[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx_buffer[3] = {0};

    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 3) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d)\n", result);
        return -1;
    }

    // Extract 10-bit ADC value from response
    // rx_buffer[1] contains the two most significant bits in its lower 2 bits
    // rx_buffer[2] contains the 8 least significant bits
    int adc_value = ((rx_buffer[1] & 0x03) << 8) | rx_buffer[2];
    return adc_value;
}

// Function to convert voltage to pressure (kPa)
float voltage_to_pressure(float voltage) {
    if (voltage < MIN_VOLTAGE || voltage > MAX_VOLTAGE) {
        fprintf(stderr, "Error: Voltage %.3fV out of range [%.1fV, %.1fV]\n", voltage, MIN_VOLTAGE, MAX_VOLTAGE);
        return -1.0;
    }

    // Linear mapping: 0.5V -> 10 kPa, 4.5V -> 150 kPa
    float pressure = (voltage - MIN_VOLTAGE) * (MAX_PRESSURE - MIN_PRESSURE) / (MAX_VOLTAGE - MIN_VOLTAGE) + MIN_PRESSURE;
    return pressure;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling for Ctrl+C and SIGTERM
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MLX90823 Pressure Sensor Reader\n");
    printf("SPI Channel: %d, Speed: %d Hz, ADC Resolution: %d\n", SPI_CHANNEL, SPI_SPEED, ADC_RESOLUTION);
    printf("Press Ctrl+C to exit.\n\n");

    // Main loop
    while (!terminate) {
        // Read ADC value from channel 0
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            time_sleep(SAMPLE_INTERVAL);
            continue;
        }

        // Convert ADC value to voltage
        float voltage = (float)adc_value / ADC_RESOLUTION * VREF;

        // Detect sensor-absent conditions (voltage stuck at rail)
        if (voltage == 0.0 || voltage == VREF) {
            fprintf(stderr, "Warning: Sensor may be absent or disconnected (voltage %.3fV)\n", voltage);
        }

        // Convert voltage to pressure
        float pressure = voltage_to_pressure(voltage);
        if (pressure < 0) {
            fprintf(stderr, "Error: Invalid voltage for conversion\n");
        } else {
            // Get current timestamp
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[80];
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

            // Log pressure reading
            printf("%s - Voltage: %.3fV, Pressure: %.2fkPa\n", timestamp, voltage, pressure);
        }

        // Wait for the next sample interval
        time_sleep(SAMPLE_INTERVAL);
    }

    // Clean up resources
    cleanup();
    printf("\nProgram terminated gracefully.\n");
    return 0;
}

