#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_FLAGS 0
#define PUMP_GPIO 17
#define MOISTURE_LOW_THRESHOLD 300
#define MOISTURE_HIGH_THRESHOLD 600
#define BUFFER_SIZE 20
#define SAMPLE_INTERVAL_SEC 5

typedef struct {
    time_t timestamp;
    int moisture_level;
    int pump_state;
} LogEntry;

static LogEntry log_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;

static int spi_handle = -1;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static void log_event(int moisture_level, int pump_state) {
    time_t now = time(NULL);
    log_buffer[buffer_index].timestamp = now;
    log_buffer[buffer_index].moisture_level = moisture_level;
    log_buffer[buffer_index].pump_state = pump_state;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
