#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define MAX30102_I2C_ADDR 0x57
#define I2C_BUS 1

#define REG_INTR_STATUS_1 0x00
#define REG_INTR_ENABLE_1 0x01
#define REG_FIFO_WR_PTR 0x02
#define REG_OVF_COUNTER 0x03
#define REG_FIFO_RD_PTR 0x04
#define REG_FIFO_DATA 0x07
#define REG_FIFO_CONFIG 0x08
#define REG_MODE_CONFIG 0x09
#define REG_SPO2_CONFIG 0x0A
#define REG_LED1_PA 0x0B
#define REG_LED2_PA 0x0C
#define REG_PART_ID 0xFF

#define EXPECTED_PART_ID 0x15

#define SAMPLE_RATE_HZ 100
#define SPO2_THRESHOLD 95.0f
#define HEART_RATE_THRESHOLD 100

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int i2c_write_reg(uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(i2c_handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed: reg=0x%02X, val=0x%02X, rc=%d\n", reg, value, rc);
    }
    return rc;
}

static int i2c_read_reg(uint8_t reg, uint8_t *value) {
    int rc = i2cReadByteData(i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed: reg=0x%02X, rc=%d\n", reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

static int i2c_read_burst(uint8_t reg, uint8_t *buf, uint32_t len) {
    int rc = i2cReadI2CBlockData(i2c_handle, reg, (char *)buf, len);
    if (rc != (int)len) {
        fprintf(stderr, "I2C burst read failed: reg=0x%02X, expected=%u, got=%d\n", reg, len, rc);
        return -1;
    }
    return 0;
}

static int init_max30102(void) {
    uint8_t part_id = 0;
    if (i2c_read_reg(REG_PART_ID, &part_id) < 0) {
        fprintf(stderr, "Cannot read Part ID - sensor absent or bus error\n");
        return -1;
    }
    if (part_id != EXPECTED_PART_ID) {
        fprintf(stderr, "Unexpected Part ID: 0x%02X (expected 0x%02X)\n", part_id, EXPECTED_PART_ID);
        return -1;
    }

    if (i2c_write_reg(REG_MODE_CONFIG, 0x40) < 0) return -1;
    gpioDelay(100000);

    if (i2c_write_reg(REG_INTR_ENABLE_1, 0x00) < 0) return -1;
    if (i2c_write_reg(REG_FIFO_WR_PTR, 0x00) < 0) return -1;
    if (i2c_write_reg(REG_OVF_COUNTER, 0x00) < 0) return -1;
    if (i2c_write_reg(REG_FIFO_RD_PTR, 0x00) < 0) return -1;
    if (i2c_write_reg(REG_FIFO_CONFIG, 0x4F) < 0) return -1;
    if (i2c_write_reg(REG_MODE_CONFIG, 0x03) < 0) return -1;
    if (i2c_write_reg(REG_SPO2_CONFIG, 0x27) < 0) return -1;
    if (i2c_write_reg(REG_LED1_PA, 0x24) < 0) return -1;
    if (i2c_write_reg(REG_LED2_PA, 0x24) < 0) return -1;

    return 0;
}

static int read_fifo_data(uint32_t *red, uint32_t *ir) {
    uint8_t buf[6];
    if (i2c_read_burst(REG_FIFO_DATA, buf, 6) < 0) return -1;

    *red = ((uint32_t)buf[0] << 16) | ((uint32_t)buf[1] << 8) | buf[2];
    *ir  = ((uint32_t)buf[3] << 16) | ((uint32_t)buf[4] << 8) | buf[5];
    return 0;
}

static float calculate_spo2(uint32_t red, uint32_t ir) {
    float ratio = (float)ir / (float)red;
    if (ratio <= 0.0f) return 0.0f;
    float spo2 = 110.0f - (21.1f * ratio);
    if (spo2 < 0.0f) spo2 = 0.0f;
    if (spo2 > 100.0f) spo2 = 100.0f;
    return spo2;
}

static int calculate_heart_rate(uint32_t *ir_data, int num_samples) {
    if (num_samples < 2) return 0;
    int peaks = 0;
    for (int i = 1; i < num_samples - 1; i++) {
        if (ir_data[i] > ir_data[i - 1] && ir_data[i] > ir_data[i + 1]) {
            peaks++;
        }
    }
    return (peaks > 0) ? (int)((float)peaks * 60.0f / (float)(num_samples - 1)) : 0;
}

static void log_warning(float spo2, int heart_rate) {
    FILE *fp = fopen("health_log.txt", "a");
    if (!fp) {
        fprintf(stderr, "Error opening health_log.txt for writing\n");
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(fp, "%s - SpO2: %.2f%%, Heart Rate: %d BPM\n", ts, spo2, heart_rate);
    fclose(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, MAX30102_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (init_max30102() < 0) {
        fprintf(stderr, "MAX30102 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    uint32_t ir_data[1024];
    int ir_index = 0;
    int samples_collected = 0;

    while (!terminate) {
        uint32_t red, ir;
        if (read_fifo_data(&red, &ir) < 0) {
            fprintf(stderr, "Error reading FIFO data\n");
            gpioDelay(1000000);
            continue;
        }

        ir_data[ir_index] = ir;
        ir_index = (ir_index + 1) % 1024;
        if (ir_index == 0) {
            samples_collected++;
        }

        if (samples_collected >= 1024) {
            int heart_rate = calculate_heart_rate(ir_data, samples_collected);
            float spo2 = calculate_spo2(red, ir_data[0]);
            if (spo2 < SPO2_THRESHOLD || heart_rate > HEART_RATE_THRESHOLD) {
                log_warning(spo2, heart_rate);
            }
            samples_collected = 0;
        }

        gpioDelay(1000000 / SAMPLE_RATE_HZ);
    }

    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

