#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define ADS1115_ADDR   0x48
#define ADS1115_REG_CONV 0x00
#define ADS1115_REG_CONFIG 0x01

#define RELAY_PIN      17
#define REED_PIN       27

#define LOG_FILE       "/var/log/door_events.log"
#define POLL_MS        200
#define RELAY_ON_MS    3000
#define BASELINE_MS    50
#define BASELINE_COUNT 10

#define THRESHOLD_PERCENT 80

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *msg) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "log open: %s\n", strerror(errno));
        return;
    }
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm;
    localtime_r(&ts.tv_sec, &tm);
    char tbuf[32];
    strftime(tbuf, sizeof(tbuf), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s.%03ld: %s\n", tbuf, ts.tv_nsec / 1000000, msg);
    fclose(fp);
}

static int16_t read_ads1115(int fd, uint8_t reg) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, 2) != 2) return -1;
    return (int16_t)((buf[0] << 8) | buf[1]);
}

static int16_t read_distance(int fd) {
    int16_t raw = read_ads1115(fd, ADS1115_REG_CONV);
    if (raw < 0) return -1;
    return raw;
}

static int calibrate(int fd) {
    int16_t sum = 0;
    int valid = 0;
    for (int i = 0; i < BASELINE_COUNT; i++) {
        int16_t v = read_distance(fd);
        if (v < 0) {
            fprintf(stderr, "baseline read %d failed\n", i);
            continue;
        }
        sum += v;
        valid++;
        usleep(BASLINE_MS * 1000);
    }
    if (valid == 0) return -1;
    int16_t avg = sum / valid;
    printf("Baseline avg: %d\n", avg);
    return avg;
}

static void control_relay(struct gpiod_line *relay, int on) {
    if (gpiod_line_set_value(relay, on ? 1 : 0) < 0) {
        fprintf(stderr, "relay set: %s\n", strerror(errno));
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        fprintf(stderr, "ioctl I2C_SLAVE: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "gpiod_chip_open: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }
    struct gpiod_line *relay = gpiod_chip_get_line(chip, RELAY_PIN);
    struct gpiod_line *reed = gpiod_chip_get_line(chip, REED_PIN);
    if (!relay || !reed) {
        fprintf(stderr, "gpiod get line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }
    if (gpiod_line_request_output(relay, "door-relay", 0) < 0 ||
        gpiod_line_request_input(reed, "door-reed") < 0) {
        fprintf(stderr, "gpiod request: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    int16_t avg = calibrate(i2c_fd);
    if (avg < 0) {
        fprintf(stderr, "Calibration failed\n");
        gpiod_line_set_value(relay, 0);
        gpiod_line_release(relay);
        gpiod_line_release(reed);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    int threshold = (avg * THRESHOLD_PERCENT) / 100;
    printf("Threshold: %d\n", threshold);

    while (running) {
        int16_t dist = read_distance(i2c_fd);
        if (dist < 0) {
            fprintf(stderr, "ADC read failed\n");
            log_event("ADC read failure");
            usleep(POLL_MS * 1000);
            continue;
        }
        printf("Distance: %d\n", dist);
        if (dist < threshold) {
            printf("Door opened!\n");
            log_event("Door opened");
            control_relay(relay, 1);
            usleep(RELAY_ON_MS * 1000);
            control_relay(relay, 0);
            int val = gpiod_line_get_value(reed);
            if (val < 0) {
                fprintf(stderr, "reed read: %s\n", strerror(errno));
            } else if (val == 0) {
                log_event("Door not opened");
            }
        }
        usleep(POLL_MS * 1000);
    }

    control_relay(relay, 0);
    gpiod_line_release(relay);
    gpiod_line_release(reed);
    gpiod_chip_close(chip);
    close(i2c_fd);
    printf("Exited cleanly\n");
    return 0;
}

