    struct gpiod_line *relay = gpiod_chip_get_line(chip, RELAY_PIN);
    struct gpiod_line *reed = gpiod_chip_get_line(chip, REED_PIN);
    if (!relay || !reed) {
        fprintf(stderr, "gpiod get line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }
    if (gpiod_line_request_output(relay, "door-relay", 0) < 0 ||
        gpiod_line_request_input(reed, "door-reed") < 0) {
        fprintf(stderr, "gpiod request: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    int16_t avg = calibrate(i2c_fd);
    if (avg < 0) {
        fprintf(stderr, "Calibration failed\n");
        gpiod_line_set_value(relay, 0);
        gpiod_line_release(relay);
        gpiod_line_release(reed);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    int threshold = (avg * THRESHOLD_PERCENT) / 100;
    printf("Threshold: %d\n", threshold);

    while (running) {
        int16_t dist = read_distance(i2c_fd);
        if (dist < 0) {
            fprintf(stderr, "ADC read failed\n");
            log_event("ADC read failure");
            usleep(POLL_MS * 1000);
            continue;
        }
        printf("Distance: %d\n", dist);
        if (dist < threshold) {
            printf("Door opened!\n");
            log_event("Door opened");
            control_relay(relay, 1);
            usleep(RELAY_ON_MS * 1000);
            control_relay(relay, 0);
            int val = gpiod_line_get_value(reed);
            if (val < 0) {
                fprintf(stderr, "reed read: %s\n", strerror(errno));
            } else if (val == 0) {
                log_event("Door not opened");
            }
        }
        usleep(POLL_MS * 1000);
    }

    control_relay(relay, 0);
    gpiod_line_release(relay);
    gpiod_line_release(reed);
    gpiod_chip_close(chip);
    close(i2c_fd);
    printf("Exited cleanly\n");
    return 0;
}

