    if (!chip) {
        perror("gpiod_chip_open_by_name failed");
        close(spi_fd);
        return 1;
    }

    struct gpiod_line *cs_lines[NUM_SENSORS] = {
        NULL, NULL, NULL
    };
    for (int i = 0; i < NUM_SENSORS; i++) {
        cs_lines[i] = gpiod_chip_get_line(chip, 8 + i);
        if (!cs_lines[i]) {
            fprintf(stderr, "Failed to get CS line %d\n", 8 + i);
            for (int j = 0; j < i; j++) gpiod_line_release(cs_lines[j]);
            gpiod_chip_close(chip);
            close(spi_fd);
            return 1;
        }
