            fprintf(stderr, "Failed to request CS line %d as output\n", 8 + i);
            for (int j = 0; j < i; j++) gpiod_line_release(cs_lines[j]);
            gpiod_chip_close(chip);
            close(spi_fd);
            return 1;
        }
    }

    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Failed to open log file");
        for (int i = 0; i < NUM_SENSORS; i++) gpiod_line_release(cs_lines[i]);
        gpiod_chip_close(chip);
        close(spi_fd);
        return 1;
    }

    fseek(fp, 0, SEEK_END);
    long fsize = ftell(fp);
    if (fsize == 0) {
        if (fprintf(fp, "timestamp,sensor1,sensor2,sensor3\n") < 0) {
            perror("Failed to write CSV header");
            fclose(fp);
            for (int i = 0; i < NUM_SENSORS; i++) gpiod_line_release(cs_lines[i]);
            gpiod_chip_close(chip);
            close(spi_fd);
            return 1;
        }
        if (fflush(fp) != 0) {
            perror("Failed to flush header");
            fclose(fp);
            for (int i = 0; i < NUM_SENSORS; i++) gpiod_line_release(cs_lines[i]);
            gpiod_chip_close(chip);
            close(spi_fd);
            return 1;
        }
    }

    while (running) {
        int s1 = read_mcp3008(spi_fd, cs_lines[0], 0);
        int s2 = read_mcp3008(spi_fd, cs_lines[1], 1);
        int s3 = read_mcp3008(spi_fd, cs_lines[2], 2);

        if (log_data(fp, s1, s2, s3) < 0) {
            fprintf(stderr, "Logging failed, continuing...\n");
        }

        for (int i = 0; i < SAMPLE_INTERVAL && running; i++) {
            sleep(1);
        }
    }

    if (fclose(fp) != 0) {
        perror("fclose failed");
    }
    for (int i = 0; i < NUM_SENSORS; i++) {
        gpiod_line_release(cs_lines[i]);
    }
    gpiod_chip_close(chip);
    close(spi_fd);
    return 0;
}

