#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PUMP_GPIO 18
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define ADC_CHANNEL 0
#define DEFAULT_THRESHOLD 30
#define DEFAULT_DURATION 10
#define DEFAULT_SLEEP_INTERVAL 60
#define MAX_RETRIES 3
#define LOG_FILE "irrigation.log"

static int spi_handle = -1;
static volatile sig_atomic_t running = 1;
static int threshold = DEFAULT_THRESHOLD;
static int duration = DEFAULT_DURATION;
static int sleep_interval = DEFAULT_SLEEP_INTERVAL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }
    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0, 0, 0};
    for (int attempt = 1; attempt <= MAX_RETRIES; attempt++) {
        int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
        if (ret == 3) {
            return ((rx[1] & 0x03) << 8) | rx[2];
        }
        fprintf(stderr, "SPI transfer failed (attempt %d/%d): %d\n", attempt, MAX_RETRIES, ret);
        if (attempt < MAX_RETRIES) {
            gpioDelay(100000);
        }
    }
    return -1;
}

static int map_moisture(int raw) {
    if (raw < 0) return 0;
    if (raw > 1023) raw = 1023;
    int pct = (int)(((float)(raw - 200) / (1023 - 200)) * 100.0f);
    if (pct < 0) pct = 0;
    if (pct > 100) pct = 100;
    return pct;
}

static void log_message(const char *msg) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    fprintf(fp, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
    fclose(fp);
}

static void control_pump(int on) {
    if (gpioWrite(PUMP_GPIO, on ? 1 : 0) < 0) {
        fprintf(stderr, "gpioWrite failed for pump GPIO %d\n", PUMP_GPIO);
        log_message("ERROR: gpioWrite failed for pump GPIO");
        return;
    }
    if (on) {
        log_message("Pump activated");
    } else {
        log_message("Pump deactivated");
    }
}

static void cleanup(void) {
    control_pump(0);
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    int opt;
    while ((opt = getopt(argc, argv, "t:d:s:h")) != -1) {
        switch (opt) {
            case 't': threshold = atoi(optarg); break;
            case 'd': duration = atoi(optarg); break;
            case 's': sleep_interval = atoi(optarg); break;
            case 'h':
            default:
                fprintf(stderr, "Usage: %s [-t threshold] [-d duration] [-s sleep_interval]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    if (threshold < 0 || threshold > 100) {
        fprintf(stderr, "Threshold must be 0-100\n");
        return EXIT_FAILURE;
    }
    if (duration < 0) {
        fprintf(stderr, "Duration must be >= 0\n");
        return EXIT_FAILURE;
    }
    if (sleep_interval < 0) {
        fprintf(stderr, "Sleep interval must be >= 0\n");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode failed for pump GPIO %d\n", PUMP_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    control_pump(0);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, (SPI_MODE & 3));
    if (spi_handle < 0) {
        fprintf(stderr, "spiOpen failed: %d\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_message("Irrigation system started");

    while (running) {
        int raw = read_mcp3008(ADC_CHANNEL);
        if (raw < 0) {
            log_message("ERROR: SPI read failed after retries");
            gpioDelay(sleep_interval * 1000000);
            continue;
        }

        int moisture = map_moisture(raw);
        char msg[128];
        snprintf(msg, sizeof(msg), "Moisture: %d%% (raw=%d)", moisture, raw);
        log_message(msg);

        if (moisture < threshold) {
            control_pump(1);
            for (int i = 0; i < duration && running; i++) {
                gpioDelay(1000000);
            }
            control_pump(0);
        }

        for (int i = 0; i < sleep_interval && running; i++) {
            gpioDelay(1000000);
        }
    }

    log_message("Irrigation system stopped");
    cleanup();
    return EXIT_SUCCESS;
}

