#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define ADC_CHANNEL 0
#define LOG_FILE "/var/log/sound_events.log"
#define SAMPLE_INTERVAL_US 10000
#define EMA_ALPHA 0.1
#define PEAK_MARGIN 0.2

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    if (spiXfer(spi_handle, tx, rx, 3) != 3) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static double calculate_ema(double current_value, double *ema_buffer, int *index, double *ema) {
    *ema_buffer[*index] = EMA_ALPHA * current_value + (1.0 - EMA_ALPHA) * (*ema_buffer[*index]);
    *ema = *ema_buffer[*index];
    *index = (*index + 1) % 10;
    return *ema;
}

static void log_event(int value) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
        fprintf(fp, "%s - Sound level: %d\n", ts, value);
    } else {
        fprintf(fp, "(timestamp error) - Sound level: %d\n", value);
    }

    if (fclose(fp) != 0) {
        perror("fclose log");
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    double ema_buffer[10] = {0};
    int ema_index = 0;
    double ema = 0.0;
    int first_sample = 1;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Sound event detection started. Press Ctrl+C to exit.\n");

    while (running) {
        int raw = read_adc(ADC_CHANNEL);
        if (raw < 0) {
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        if (first_sample) {
            ema = raw;
            first_sample = 0;
        } else {
            ema = calculate_ema((double)raw, ema_buffer, &ema_index, &ema);
        }

        double peak_margin = (double)raw * PEAK_MARGIN;
        if (raw > ema + peak_margin) {
            log_event(raw);
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

