#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define PCF8591_ADDR   0x48
#define CTRL_BYTE      0x40  /* single-ended, channel 0, analog output disabled */
#define SAMPLE_MS      100

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_byte(int fd, uint8_t byte)
{
    if (write(fd, &byte, 1) != 1) {
        fprintf(stderr, "i2c_write_byte(0x%02X): %s\n", byte, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_byte(int fd, uint8_t *out)
{
    uint8_t buf;
    if (read(fd, &buf, 1) != 1) {
        fprintf(stderr, "i2c_read_byte: %s\n", strerror(errno));
        return -1;
    }
    *out = buf;
    return 0;
}

int main(void)
{
    int fd = -1;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, PCF8591_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n", PCF8591_ADDR, strerror(errno));
        goto cleanup;
    }

    /* Dummy read to discard the previous conversion result */
    if (i2c_read_byte(fd, NULL) < 0) {
        goto cleanup;
    }

    while (g_running) {
        if (i2c_write_byte(fd, CTRL_BYTE) < 0) {
            goto cleanup;
        }

        /* Small delay to let the conversion complete */
        usleep(5000);

        uint8_t value;
        if (i2c_read_byte(fd, &value) < 0) {
            goto cleanup;
        }

        printf("AIN0: %3u\n", value);
        fflush(stdout);

        usleep(SAMPLE_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
        close(fd);
    }
    return ret;
}

