    for (int i = 0; i < BUFFER_SIZE; i++) cb->buffer[i] = 0.0f;
}

static void cb_push(CircularBuffer *cb, float value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) cb->count++;
}

static float cb_rolling_average(const CircularBuffer *cb) {
    if (cb->count == 0) return 0.0f;
    float sum = 0.0f;
    for (int i = 0; i < cb->count; i++) sum += cb->buffer[i];
    return sum / (float)cb->count;
}

/* ADS1115 single-ended read: write config, wait for conversion, read result */
static int ads1115_read(int handle, int channel, float *voltage_out) {
    if (channel < 0 || channel > 3) return -1;

    /* Config: single-shot, AIN0/AIN1/AIN2/AIN3, +/-4.096V, 128 SPS, continuous */
    uint16_t config = 0x8000 | (channel << 12) | 0x0200 | 0x0080 | 0x0040 | 0x0000;
    char cfg[3];
    cfg[0] = ADS1115_CONFIG;
    cfg[1] = (config >> 8) & 0xFF;
    cfg[2] = config & 0xFF;

    if (i2cWriteDevice(handle, cfg, 3) != 0) return -1;

    /* Wait for conversion: 128 SPS -> ~7.8 ms; poll up to 100 ms */
    for (int i = 0; i < 10; i++) {
        char reg = ADS1115_CONV;
        if (i2cWriteDevice(handle, &reg, 1) != 0) return -1;
        char data[2];
        if (i2cReadDevice(handle, data, 2) != 2) return -1;
        uint16_t raw = ((uint16_t)(data[0] & 0xFF) << 8) | (uint8_t)data[1];
        if (raw & 0x8000) { /* bit 15 set = new conversion ready */
            break;
        }
        gpioDelay(10000); /* 10 ms */
        if (i == 9) return -1;
    }

    /* Read conversion result */
    char reg = ADS1115_CONV;
    if (i2cWriteDevice(handle, &reg, 1) != 0) return -1;
    char data[2];
    if (i2cReadDevice(handle, data, 2) != 2) return -1;
    uint16_t raw = ((uint16_t)(data[0] & 0xFF) << 8) | (uint8_t)data[1];

    /* Convert to signed 16-bit */
    int16_t signed_raw = (int16_t)raw;
    float voltage = (float)signed_raw * (VCC / 32768.0f);

    if (voltage < 0.0f || voltage > VCC) {
        syslog(LOG_WARNING, "ADS1115 voltage out of range: %.3f V", voltage);
        return -1;
    }
    *voltage_out = voltage;
    return 0;
}

static float voltage_to_gauss(float voltage) {
    return (voltage - ZERO_FIELD_V) / SENSITIVITY;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(GPIO_SHUTDOWN, 0);
    gpioTerminate();
    closelog();
}

static void signal_handler(int sig) {
    (void)sig;
    shutdown_requested = 1;
}

int main(void) {
    openlog("hall_monitor", LOG_PID | LOG_CONS, LOG_USER);

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialization failed");
        closelog();
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        syslog(LOG_ERR, "Failed to open I2C bus %d at addr 0x%02X: %d", I2C_BUS, ADS1115_ADDR, i2c_handle);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    gpioSetMode(GPIO_SHUTDOWN, PI_OUTPUT);
    gpioWrite(GPIO_SHUTDOWN, 0);

    CircularBuffer gauss_buffer;
    cb_init(&gauss_buffer);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    syslog(LOG_INFO, "Hall monitor started (ADS1115 @ 0x%02X, GPIO27 shutdown, threshold 500 Gauss)", ADS1115_ADDR);

    while (!shutdown_requested) {
        float voltage = 0.0f;
        if (ads1115_read(i2c_handle, 0, &voltage) != 0) {
            syslog(LOG_ERR, "ADC read failed, skipping sample");
            gpioDelay(SAMPLE_US);
            continue;
        }

        float gauss = voltage_to_gauss(voltage);
        cb_push(&gauss_buffer, gauss);
        float avg = cb_rolling_average(&gauss_buffer);

        syslog(LOG_INFO, "Voltage: %.3f V, Gauss: %.3f, Avg: %.3f Gauss", voltage, gauss, avg);

        if (avg > 500.0f) {
            syslog(LOG_WARNING, "Threshold exceeded! Gauss: %.3f", avg);
            gpioWrite(GPIO_SHUTDOWN, 1);
            shutdown_requested = 1;
        }

        gpioDelay(SAMPLE_US);
    }

    syslog(LOG_INFO, "Shutting down...");
    cleanup();
    return EXIT_SUCCESS;
}

