#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>

#define SPI_CHANNEL 0          /* CE0 on SPI0 */
#define SPI_SPEED   1000000    /* 1 MHz */
#define SPI_FLAGS   0          /* Mode 0, active-low CE */
#define ADC_CHANNEL 0          /* MCP3008 CH0 */
#define ADC_MAX     1023       /* 10-bit ADC */
#define INTENSITY_MAX 10
#define SAMPLE_US   1000000    /* 1 second */

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read a single-ended sample from the MCP3008.
 * Returns 0-1023 on success, or -1 on SPI transfer failure.
 *
 * MCP3008 SPI protocol (3 bytes):
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4      (single-ended + channel, upper nibble)
 *   tx[2] = 0x00                       (clock out low bits)
 *   rx[1] bits 1:0  -> result bits 9:8
 *   rx[2]          -> result bits 7:0
 */
static int read_mcp3008(int handle, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    int ret = spiXfer(handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (spiXfer returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

static int map_adc_to_intensity(int adc_value)
{
    if (adc_value < 0) adc_value = 0;
    if (adc_value > ADC_MAX) adc_value = ADC_MAX;

    int intensity = (int)(((float)adc_value / (float)ADC_MAX) * (float)INTENSITY_MAX);
    if (intensity < 0) intensity = 0;
    if (intensity > INTENSITY_MAX) intensity = INTENSITY_MAX;
    return intensity;
}

static void log_data(int adc_value, int intensity)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    printf("%s - ADC: %4d  Intensity: %2d\n", timestamp, adc_value, intensity);
    fflush(stdout);
}

int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI0 CE0, mode 0, 1 MHz */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (handle %d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handler for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Rain sensor monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int adc_value = read_mcp3008(g_spi_handle, ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read failed; will retry next cycle\n");
        } else {
            int intensity = map_adc_to_intensity(adc_value);
            log_data(adc_value, intensity);
        }

        /* Sleep 1 second, but wake early on signal */
        for (int i = 0; i < 10 && g_running; i++) {
            gpioDelay(100000); /* 100 ms */
        }
    }

    /* Cleanup */
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
    }
    gpioTerminate();

    printf("\nRain sensor monitoring stopped.\n");
    return EXIT_SUCCESS;
}

