#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED   1000000  /* 1 MHz */
#define SPI_FLAGS   0        /* mode 0, active-low CE */
#define PWM_GPIO    18
#define PWM_FREQ    1000     /* 1 kHz */
#define PWM_RANGE   1024     /* 10-bit ADC */
#define SAMPLE_US   100000   /* 100 ms */

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int read_mcp3008(int spi_handle, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read: 3-byte transfer.
     * Byte 0: start bit (0x01)
     * Byte 1: SGL/DIFF=1 + D2 D1 D0 channel, upper nibble, then don't-care
     * Byte 2: don't-care
     *
     * Response: bits 9..0 are in the lower 2 bits of byte 1 and all of byte 2.
     */
    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
