#include <unistd.h>
#include <pigpio.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define LED_GPIO 17
#define DEFAULT_THRESHOLD 100.0
#define SAMPLE_INTERVAL_US 100000
#define BLINK_DURATION_US 1000000
#define BLINK_HALF_PERIOD_US 50000

#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG 0x01

#define ADS1115_CONFIG_OS_BEGIN (1 << 15)
#define ADS1115_CONFIG_MUX_AIN0 (0x04 << 12)
#define ADS1115_CONFIG_PGA_4_096V (0x01 << 9)
#define ADS1115_CONFIG_MODE_SINGLE (0x01 << 8)
#define ADS1115_CONFIG_DR_128SPS (0x00 << 5)
#define ADS1115_CONFIG_CQUE_NONE (0x03 << 0)

static volatile sig_atomic_t running = 1;
static double threshold = DEFAULT_THRESHOLD;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int16_t read_ads1115(int handle) {
    char config[2];
    char reg = ADS1115_REG_CONFIG;
    char buf[2];
    int16_t raw = 0;

    config[0] = ADS1115_CONFIG_OS_BEGIN | ADS1115_CONFIG_MUX_AIN0 |
                ADS1115_CONFIG_PGA_4_096V | ADS1115_CONFIG_MODE_SINGLE |
                ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_CQUE_NONE;
    config[1] = config[0] & 0xFF;

    if (i2cWriteByteData(handle, ADS1115_REG_CONFIG, config[0]) < 0) {
        fprintf(stderr, "Error writing config register: %s\n", strerror(errno));
        return -1;
    }
    if (i2cWriteByteData(handle, ADS1115_REG_CONFIG, config[1]) < 0) {
        fprintf(stderr, "Error writing config register: %s\n", strerror(errno));
        return -1;
    }

    gpioDelay(10000);

    if (i2cWriteByte(handle, ADS1115_REG_CONVERSION) < 0) {
        fprintf(stderr, "Error selecting conversion register: %s\n", strerror(errno));
        return -1;
    }

    if (i2cReadDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "Error reading conversion register: %s\n", strerror(errno));
        return -1;
    }

    raw = (int16_t)((buf[0] << 8) | buf[1]);
    return raw;
}

static double calculate_magnetic_field(int16_t raw) {
    double voltage = (raw * 4.096) / 32768.0;
    double gauss = voltage / 0.001;
    return gauss;
}

static void blink_led(int gpio, int duration_us) {
    int on = 0;
    int elapsed = 0;
    while (elapsed < duration_us && running) {
        gpioWrite(gpio, on);
        on = !on;
        elapsed += BLINK_HALF_PERIOD_US;
    }
}

int main(int argc, char *argv[]) {
    int opt;
    while ((opt = getopt(argc, argv, "t:")) != -1) {
        switch (opt) {
            case 't':
                threshold = atof(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold_gauss]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    int i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %s\n",
                I2C_BUS, ADS1115_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Monitoring magnetic field strength. Threshold: %.2f Gauss\n", threshold);

    while (running) {
        int16_t raw = read_ads1115(i2c_handle);
        if (raw < 0) {
            fprintf(stderr, "ADC read failed, retrying...\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        double gauss = calculate_magnetic_field(raw);

        printf("Magnetic Field: %.2f Gauss\n", gauss);

        if (gauss > threshold) {
            printf("Threshold exceeded! Blinking LED for 1 second.\n");
            blink_led(LED_GPIO, BLINK_DURATION_US);
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    gpioWrite(LED_GPIO, 0);
    i2cClose(i2c_handle);
    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

