#define MQTT_TOPIC_SOIL_MOISTURE "soil_moisture"
#define MQTT_TOPIC_PUMP_CONTROL "pump_control"
#define MQTT_CLIENT_ID "soil_moisture_pump"
#define SAMPLE_INTERVAL 60
#define SPI_READ_INTERVAL 5

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static struct mosquitto *mosq = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        syslog(LOG_ERR, "Invalid MCP3008 channel %d", channel);
        return -1;
    }
    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};
    if (spiXfer(spi_handle, (char *)tx, (char *)rx, 3) != 0) {
        syslog(LOG_ERR, "SPI transfer failed");
        return -1;
    }
    return ((rx[1] & 0x03) << 8) | rx[2];
}

static float calculate_moisture(int adc_value) {
    if (adc_value < 0 || adc_value > 1023) return -1.0;
    return 100.0 - ((float)adc_value / 1023.0) * 100.0;
}

static int control_relay(int state) {
    if (gpioWrite(RELAY_GPIO, state) != 0) {
        syslog(LOG_ERR, "Failed to write relay GPIO %d", RELAY_GPIO);
        return -1;
    }
    return 0;
}

static void publish_moisture(float moisture) {
    char payload[32];
    snprintf(payload, sizeof(payload), "%.2f", moisture);
    int rc = mosquitto_publish(mosq, NULL, MQTT_TOPIC_SOIL_MOISTURE,
                               (int)strlen(payload), payload, 0, false);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "MQTT publish failed: %s", mosquitto_strerror(rc));
    }
}

static void mqtt_callback(struct mosquitto *m, void *userdata,
                          const struct mosquitto_message *message) {
    (void)m; (void)userdata;
    if (message->payloadlen > 0) {
        char payload[16];
        int len = message->payloadlen < (int)sizeof(payload) - 1
                  ? message->payloadlen : (int)sizeof(payload) - 1;
        memcpy(payload, message->payload, len);
        payload[len] = '\0';
        syslog(LOG_INFO, "Received MQTT command: %s", payload);
        if (strcmp(payload, "pump_on") == 0) {
            if (control_relay(1) == 0) {
                syslog(LOG_INFO, "Pump ON");
            } else {
                syslog(LOG_ERR, "Failed to turn pump ON");
            }
        } else if (strcmp(payload, "pump_off") == 0) {
            if (control_relay(0) == 0) {
                syslog(LOG_INFO, "Pump OFF");
            } else {
                syslog(LOG_ERR, "Failed to turn pump OFF");
            }
        }
    }
}

static void cleanup(void) {
    syslog(LOG_INFO, "Cleaning up...");
    if (mosq) {
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
        mosq = NULL;
    }
    mosquitto_lib_cleanup();
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();
    closelog();
}

int main(void) {
    openlog("soil_moisture_pump", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Starting soil moisture pump controller...");

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set relay GPIO %d as output", RELAY_GPIO);
        gpioTerminate();
        closelog();
        return 1;
    }
    gpioWrite(RELAY_GPIO, 0);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        syslog(LOG_ERR, "SPI open failed: %d", spi_handle);
        gpioTerminate();
        closelog();
        return 1;
    }

    mosquitto_lib_init();
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        syslog(LOG_ERR, "MQTT client creation failed");
        spiClose(spi_handle);
        gpioTerminate();
        closelog();
        return 1;
    }
    mosquitto_connect_callback_set(mosq, mqtt_callback);
    mosquitto_subscribe(mosq, NULL, MQTT_TOPIC_PUMP_CONTROL, 0);
    int rc = mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "MQTT connect failed: %s", mosquitto_strerror(rc));
        mosquitto_destroy(mosq);
        mosq = NULL;
        spiClose(spi_handle);
        gpioTerminate();
        closelog();
        return 1;
    }
    syslog(LOG_INFO, "Connected to MQTT broker");

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int pump_on = 0;
    int last_adc = -1;

    while (running) {
        int adc = read_mcp3008(0);
        if (adc < 0) {
            syslog(LOG_ERR, "Failed to read ADC, retrying in %d s", SAMPLE_INTERVAL);
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        if (adc != last_adc) {
            float moisture = calculate_moisture(adc);
            if (moisture < 0) {
                syslog(LOG_ERR, "Invalid ADC value %d, sensor absent or wiring fault", adc);
            } else {
                syslog(LOG_INFO, "Moisture: %.2f%%", moisture);
                publish_moisture(moisture);
                if (moisture < MOISTURE_THRESHOLD_LOW && !pump_on) {
                    if (control_relay(1) == 0) {
                        pump_on = 1;
                        syslog(LOG_INFO, "Pump ON (moisture %.2f%% < %.1f%%)", moisture, MOISTURE_THRESHOLD_LOW);
                    } else {
                        syslog(LOG_ERR, "Failed to turn pump ON");
                    }
                } else if (moisture > MOISTURE_THRESHOLD_HIGH && pump_on) {
                    if (control_relay(0) == 0) {
                        pump_on = 0;
                        syslog(LOG_INFO, "Pump OFF (moisture %.2f%% > %.1f%%)", moisture, MOISTURE_THRESHOLD_HIGH);
                    } else {
                        syslog(LOG_ERR, "Failed to turn pump OFF");
                    }
                }
            }
            last_adc = adc;
        }
        sleep(SAMPLE_INTERVAL);
    }

    cleanup();
    return 0;
}

