#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000U
#define SPI_BITS        8
#define SPI_MODE        SPI_MODE_0
#define VREF            3.3f
#define ADC_CHANNEL     0
#define SAMPLE_PERIOD_US 500000U

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handler(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    return 0;
}

static int spi_init(int *fd_out)
{
    int fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "ioctl(SPI_IOC_WR_MODE): %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "ioctl(SPI_IOC_WR_BITS_PER_WORD): %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "ioctl(SPI_IOC_WR_MAX_SPEED_HZ): %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    *fd_out = fd;
    return 0;
}

static int spi_transfer(int fd, uint8_t *tx, uint8_t *rx, size_t len)
{
    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = len;
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = 0;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "ioctl(SPI_IOC_MESSAGE): %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_adc(int fd, int channel, int *out_value)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid channel %d\n", channel);
        return -1;
    }

    uint8_t tx[3] = {
        0x01,
        (uint8_t)((0x08 | channel) << 4),
        0x00
    };
    uint8_t rx[3] = {0};

    if (spi_transfer(fd, tx, rx, sizeof(tx)) < 0) {
        return -1;
    }

    *out_value = ((rx[1] & 0x03) << 8) | rx[2];
    return 0;
}

int main(void)
{
    int fd = -1;
    int rc = EXIT_FAILURE;

    if (install_signal_handler() < 0) {
        goto cleanup;
    }

    if (spi_init(&fd) < 0) {
        goto cleanup;
    }

    printf("MCP3008 ADC reader on %s (mode 0, %u Hz, %u bits)\n",
           SPI_DEVICE, SPI_SPEED_HZ, SPI_BITS);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        int adc_value = 0;
        if (read_adc(fd, ADC_CHANNEL, &adc_value) < 0) {
            fprintf(stderr, "ADC read failed; continuing.\n");
            usleep(SAMPLE_PERIOD_US);
            continue;
        }

        float voltage = (float)adc_value * VREF / 1024.0f;
        printf("Raw: %4d  Voltage: %.3f V\n", adc_value, voltage);
        fflush(stdout);

        usleep(SAMPLE_PERIOD_US);
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
        close(fd);
    }
    return rc;
}

