        }

        if (running) {
            gpioSleep(PI_TIME_RELATIVE, SAMPLE_INTERVAL, 0);
        }
    }

    printf("\nShutting down...\n");

    if (spi_handle >= 0) {
        if (spiClose(spi_handle) != 0) {
            fprintf(stderr, "Warning: spiClose failed\n");
        }
    }

    gpioTerminate();
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

