#define MOTOR1_GPIO 17
#define MOTOR2_GPIO 27
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define NOISE_THRESHOLD 500
#define PWM_FREQUENCY 100
#define SAMPLE_INTERVAL_US 10000
#define LOG_FILE "vibration_log.txt"

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0,
        .tx_nbits = 0,
        .rx_nbits = 0,
        .pad = 0
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer failed");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static void log_vibration(int adc_value) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Failed to open log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d - Vibration detected (ADC: %d)\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, adc_value);
    } else {
        fprintf(fp, "Vibration detected (ADC: %d)\n", adc_value);
    }

    fclose(fp);
}

static void set_motor_pwm(int gpio, int duty_cycle) {
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > 255) duty_cycle = 255;

    if (gpioPWM(gpio, duty_cycle) != 0) {
        fprintf(stderr, "Failed to set PWM on GPIO %d\n", gpio);
    }
}

static void cleanup(void) {
    set_motor_pwm(MOTOR1_GPIO, 0);
    set_motor_pwm(MOTOR2_GPIO, 0);
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
    gpioTerminate();
}

