    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Failed to set signal handler");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        gpioTerminate();
        return 1;
    }

    uint8_t mode = SPI_MODE_0;
    uint8_t bits = 8;
    uint32_t speed = SPI_SPEED;

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        cleanup();
        return 1;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Failed to set SPI bits per word");
        cleanup();
        return 1;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI speed");
        cleanup();
        return 1;
    }

    if (gpioSetMode(MOTOR1_GPIO, PI_OUTPUT) != 0 || gpioSetMode(MOTOR2_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        cleanup();
        return 1;
    }

    if (gpioSetPWMfrequency(MOTOR1_GPIO, PWM_FREQUENCY) < 0 ||
        gpioSetPWMfrequency(MOTOR2_GPIO, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        cleanup();
        return 1;
    }

    printf("Vibration monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int noise_level = read_mcp3008(0);
        if (noise_level < 0) {
            fprintf(stderr, "ADC read error, skipping iteration\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        if (noise_level > NOISE_THRESHOLD) {
            int duty1 = (int)(((float)noise_level / 1023.0f) * 255.0f);
            int duty2 = (int)(((float)noise_level / 1023.0f) * 255.0f);
            set_motor_pwm(MOTOR1_GPIO, duty1);
            set_motor_pwm(MOTOR2_GPIO, duty2);
            log_vibration(noise_level);
        } else {
            set_motor_pwm(MOTOR1_GPIO, 0);
            set_motor_pwm(MOTOR2_GPIO, 0);
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

