#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>
#include <linux/spi/spidev.h>
#include <sys/ioctl.h>
#include <fcntl.h>

#define RELAY_GPIO_LINE 17
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define PROXIMITY_THRESHOLD 20
#define DEBOUNCE_DELAY 1
#define POLL_INTERVAL_MS 100
#define LOG_FILE "door_events.log"

static volatile sig_atomic_t running = 1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *relay_line = NULL;
static int spi_fd = -1;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_spi(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("open SPI device");
        return -1;
    }
    int mode = SPI_MODE_0;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("ioctl SPI_IOC_WR_MODE");
        close(spi_fd); spi_fd = -1; return -1;
    }
    int bits = 8;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("ioctl SPI_IOC_WR_BITS_PER_WORD");
        close(spi_fd); spi_fd = -1; return -1;
    }
    int speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("ioctl SPI_IOC_WR_MAX_SPEED_HZ");
        close(spi_fd); spi_fd = -1; return -1;
    }
    return 0;
}

static int init_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return -1;
    }
    relay_line = gpiod_chip_get_line(chip, RELAY_GPIO_LINE);
    if (!relay_line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip); chip = NULL; return -1;
    }
    if (gpiod_line_request_output(relay_line, "door_sensor", 0) < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip); chip = NULL; relay_line = NULL; return -1;
    }
    return 0;
}

static int read_mcp3008(int channel) {
    if (spi_fd < 0) return -1;
    if (channel < 0 || channel > 7) return -1;
    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0, 0, 0};
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
        .delay_usecs = 0
    };
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("ioctl SPI_IOC_MESSAGE");
        return -1;
    }
    return ((rx[1] & 0x03) << 8) | rx[2];
}

static void log_event(const char *msg) {
    if (!log_fp) return;
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(log_fp, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
        fflush(log_fp);
    }
}

static void cleanup(void) {
    if (relay_line) {
        gpiod_line_set_value(relay_line, 0);
        gpiod_line_release(relay_line);
        relay_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
    if (log_fp) {
        fclose(log_fp);
        log_fp = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    if (init_spi() < 0) {
        cleanup();
        return 1;
    }
    if (init_gpio() < 0) {
        cleanup();
        return 1;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        perror("fopen log");
        cleanup();
        return 1;
    }

    printf("Door sensor monitoring started. Press Ctrl+C to exit.\n");
    log_event("System started");

    int last_trigger = 0;

    while (running) {
        int adc = read_mcp3008(0);
        if (adc < 0) {
            log_event("SPI read error");
            usleep(POLL_INTERVAL_MS * 1000);
            continue;
        }

        int proximity = (adc < 100) ? 1 : 0;
        if (proximity && !last_trigger) {
            if (gpiod_line_set_value(relay_line, 1) < 0) {
                perror("gpiod_line_set_value HIGH");
                log_event("Failed to energize relay");
            } else {
                log_event("Door opened");
            }
            last_trigger = 1;
            sleep(DEBOUNCE_DELAY);
        } else if (!proximity && last_trigger) {
            if (gpiod_line_set_value(relay_line, 0) < 0) {
                perror("gpiod_line_set_value LOW");
                log_event("Failed to de-energize relay");
            } else {
                log_event("Door closed");
            }
            last_trigger = 0;
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    log_event("System stopped");
    cleanup();
    return 0;
}

