#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define SOLENOID_GPIO 17
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define NUM_SENSORS 3
#define LOG_INTERVAL 5
#define LOG_FILE "irrigation.log"

static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) return -1;
    unsigned char tx[3] = {0x01, (unsigned char)(0x80 | (channel << 4)), 0x00};
    unsigned char rx[3] = {0, 0, 0};
    if (spiXfer(spi_handle, (char *)tx, (char *)rx, 3) != 3) return -1;
    return ((rx[1] & 0x03) << 8) | rx[2];
}

static int map_adc_to_valve(int adc_value) {
    if (adc_value < 0) return 0;
    int duty = 100 - (int)(((float)adc_value / 1023.0f) * 100.0f);
    if (duty < 0) duty = 0;
    if (duty > 100) duty = 100;
    return duty;
}

static void log_data(int s0, int s1, int s2, int avg_adc, int valve_pos) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(log_file, "%s, S0=%d, S1=%d, S2=%d, AvgADC=%d, Valve=%d\n",
            ts, s0, s1, s2, avg_adc, valve_pos);
    fflush(log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }

    gpioSetMode(SOLENOID_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(SOLENOID_GPIO, 100);
    gpioSetPWMrange(SOLENOID_GPIO, 100);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Cannot open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Irrigation control started. Press Ctrl+C to stop.\n");

    while (!terminate) {
        int s0 = read_mcp3008(0);
        int s1 = read_mcp3008(1);
        int s2 = read_mcp3008(2);

        if (s0 < 0 || s1 < 0 || s2 < 0) {
            fprintf(stderr, "SPI read error, skipping cycle\n");
            gpioDelay(LOG_INTERVAL * 1000000);
            continue;
        }

        int avg_adc = (s0 + s1 + s2) / 3;
        int valve_pos = map_adc_to_valve(avg_adc);

        gpioPWM(SOLENOID_GPIO, valve_pos);
        log_data(s0, s1, s2, avg_adc, valve_pos);

        gpioDelay(LOG_INTERVAL * 1000000);
    }

    gpioPWM(SOLENOID_GPIO, 0);
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();
    printf("Shutdown complete.\n");
    return 0;
}

