#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define TRIG_PIN 23
#define ECHO_PIN 24
#define PWM_PIN 18
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define CONFIG_FILE "theremin_config.txt"

#define MIN_FREQ 220
#define MAX_FREQ 880
#define MIN_VOLUME 50
#define MAX_VOLUME 200
#define ECHO_TIMEOUT_US 30000

volatile sig_atomic_t program_running = 1;

void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

int read_config(void) {
    FILE *fp = fopen(CONFIG_FILE, "r");
    if (!fp) {
        return -1;
    }
    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        char *key = strtok(line, "=\n");
        char *value = strtok(NULL, "=\n");
        if (!key || !value) continue;
        if (strcmp(key, "min_freq") == 0) {
            MIN_FREQ = atoi(value);
        } else if (strcmp(key, "max_freq") == 0) {
            MAX_FREQ = atoi(value);
        } else if (strcmp(key, "min_volume") == 0) {
            MIN_VOLUME = atoi(value);
        } else if (strcmp(key, "max_volume") == 0) {
            MAX_VOLUME = atoi(value);
        }
    }
    fclose(fp);
    return 0;
}

int write_config(void) {
    FILE *fp = fopen(CONFIG_FILE, "w");
    if (!fp) return -1;
    fprintf(fp, "min_freq=%d max_freq=%d min_volume=%d max_volume=%d\n", MIN_FREQ, MAX_FREQ, MIN_VOLUME, MAX_VOLUME);
    fclose(fp);
    return 0;
}

int read_distance(int trig_pin, int echo_pin) {
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) return -1;
    struct gpiod_line *trig = gpiod_chip_get_line(chip, trig_pin);
    struct gpiod_line *echo = gpiod_chip_get_line(chip, echo_pin);
    if (!trig || !echo) {
        gpiod_chip_close(chip);
        return -1;
    }
    if (gpiod_line_request_output(trig, "theremin", 0) < 0) return -1;
    if (gpiod_line_request_input(echo, "theremin") < 0) return -1;
    gpiod_line_set_value(trig, 0);
    usleep(2);
    gpiod_line_set_value(trig, 1);
    usleep(10);
    gpiod_line_set_value(trig, 0);
    struct timespec start, end;
    long long start_time, end_time;
    int timeout = 0;
    while (gpiod_line_get_value(echo) == 0) {
        if (++timeout > ECHO_TIMEOUT_US) return -2;
        usleep(1);
    }
    clock_gettime(CLOCK_MONOTONIC, &start);
    timeout = 0;
    while (gpiod_line_get_value(echo) == 1) {
        if (++timeout > ECHO_TIMEOUT_US) return -2;
        usleep(1);
    }
    clock_gettime(CLOCK_MONOTONIC, &end);
    start_time = start.tv_sec * 1000000LL + start.tv_nsec / 1000;
    end_time = end.tv_sec * 1000000LL + end.tv_nsec / 1000;
    long long duration = end_time - start_time;
    double distance = duration * 0.0343 / 2.0;
    if (distance < 2 || distance > 400) return -1;
    gpiod_line_release(trig);
    gpiod_line_release(echo);
    gpiod_chip_close(chip);
    return (int)distance;
}

int read_adc(int spi_fd, int channel) {
    unsigned char tx[3] = {0x01, (0x08 | channel) << 4, 0x00};
    unsigned char rx[3] = {0};
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
        .delay_usecs = 0
    };
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) return -1;
    return ((rx[1] & 0x03) << 8) | rx[2];
}

int map_distance_to_frequency(int distance) {
    if (distance < 0) return 0;
    return MIN_FREQ + (int)((double)distance / 400.0 * (MAX_FREQ - MIN_FREQ));
}

int map_adc_to_volume(int adc_value) {
    if (adc_value < 0) return 0;
    return MIN_VOLUME + (int)((double)adc_value / 1023.0 * (MAX_VOLUME - MIN_VOLUME));
}

int set_pwm_duty_cycle(int duty_cycle) {
    char path[256];
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip0/export");
    FILE *fp = fopen(path, "w");
    if (!fp) return -1;
    fprintf(fp, "0");
    fclose(fp);
    usleep(100000);
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip0/pwm0/period");
    FILE *fp2 = fopen(path, "w");
    if (!fp2) return -1;
    fprintf(fp2, "%d", 1000000 / duty_cycle);
    fclose(fp2);
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip0/pwm0/duty_cycle");
