#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FAN_GPIO 18
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define MCP3008_CHANNEL 0
#define AQI_THRESHOLD 100
#define MAX_AQI 500
#define LOG_FILE "air_quality.log"
#define SAMPLE_INTERVAL 5
#define MAX_SPI_RETRIES 3
#define RETRY_DELAY 1

static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx[3] = {0x01, (char)(0x08 | (channel << 4)), 0x00};
    char rx[3] = {0, 0, 0};

    for (int attempt = 0; attempt < MAX_SPI_RETRIES; attempt++) {
        int ret = spiXfer(spi_handle, tx, rx, 3);
        if (ret == 3) {
            int adc_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
            return adc_value;
        }
        fprintf(stderr, "SPI transfer failed (attempt %d/%d): %d\n", attempt + 1, MAX_SPI_RETRIES, ret);
        if (attempt < MAX_SPI_RETRIES - 1) {
            sleep(RETRY_DELAY);
        }
    }

    fprintf(stderr, "SPI transfer failed after %d retries. Re-initializing SPI.\n", MAX_SPI_RETRIES);
    spiClose(spi_handle);
    spi_handle = -1;
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to re-initialize SPI: %d\n", spi_handle);
        return -1;
    }
    return -1;
}

static float calculate_aqi(int adc_value) {
    if (adc_value < 0) return 0.0f;
    if (adc_value > MAX_AQI) return 100.0f;
    return (float)adc_value / (float)MAX_AQI * 100.0f;
}

static void control_fan(float aqi) {
    if (aqi > AQI_THRESHOLD) {
        gpioWrite(FAN_GPIO, 1);
        printf("Fan ON (AQI: %.2f)\n", aqi);
    } else {
        gpioWrite(FAN_GPIO, 0);
        printf("Fan OFF (AQI: %.2f)\n", aqi);
    }
}

static void log_data(float aqi) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s, AQI: %.2f\n", timestamp, aqi);
    fflush(log_file);
}

static void cleanup(void) {
    gpioWrite(FAN_GPIO, 0);
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioWrite(FAN_GPIO, 0);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Air quality monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value. Skipping sample.\n");
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        float aqi = calculate_aqi(adc_value);
        control_fan(aqi);
        log_data(aqi);

        sleep(SAMPLE_INTERVAL);
    }

    cleanup();
    printf("Air quality monitoring stopped.\n");
    return 0;
}

