#include <math.h>
#include <pigpio.h>

// Motor 1
#define MOTOR1_ENABLE 18
#define MOTOR1_DIR 23

// Motor 2
#define MOTOR2_ENABLE 24
#define MOTOR2_DIR 25

// SPI
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0

// Potentiometer channels on MCP3008
#define POT1_CHANNEL 0
#define POT2_CHANNEL 1

// Speed limits
#define MIN_SPEED 50
#define MAX_SPEED 255

// Motion profile parameters
#define ACCEL_TIME 0.1
#define HOLD_TIME 2.0
#define DECEL_TIME 0.1
#define PAUSE_TIME 5.0

// Global flag for signal handling
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_potentiometer(int channel);
int map_speed(int pot_value);
void move_motor(int enable_pin, int direction_pin, int speed);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read the value from the MCP3008 ADC
int read_potentiometer(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    // MCP3008 SPI command: start bit, single-ended mode, channel select
    unsigned char tx_buf[3] = {0x01, (0x08 | channel) << 4, 0x00};
    unsigned char rx_buf[3] = {0};

    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        return -1;
    }

    int result = spiXfer(spi_handle, tx_buf, rx_buf, 3);
    spiClose(spi_handle);

    if (result < 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    // Extract 10-bit ADC value from response
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Function to map the potentiometer value to a speed factor using a logarithmic function
int map_speed(int pot_value) {
    if (pot_value < 0) pot_value = 0;
    if (pot_value > 1023) pot_value = 1023;

    // Logarithmic mapping: maps 0-1023 to 0.5-2.5
    double log_value = log10((double)pot_value + 1);
    double speed_factor = 0.5 + (log_value / 2.0);

    // Clamp the speed factor to the valid range
    if (speed_factor < 0.5) speed_factor = 0.5;
    if (speed_factor > 2.5) speed_factor = 2.5;

    return (int)(speed_factor + 0.5);
}

// Function to move a motor
void move_motor(int enable_pin, int direction_pin, int speed) {
    if (speed < MIN_SPEED) speed = MIN_SPEED;
    if (speed > MAX_SPEED) speed = MAX_SPEED;

    // Set direction
    if (speed > 0) {
        gpioWrite(direction_pin, 1);
    } else {
        gpioWrite(direction_pin, 0);
    }

    // Set enable pin (PWM)
    gpioPWM(enable_pin, speed);
}

