#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LED_PIN 17
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define NUM_SAMPLES 5
#define DEBOUNCE_DELAY_MS 10
#define SAMPLE_DELAY_US 10000

static volatile int running = 1;
static int spi_handle = -1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }
    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0, 0, 0};
    if (spiXfer(spi_handle, tx, rx, 3) != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }
    return ((rx[1] & 0x03) << 8) | rx[2];
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0);
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }
    signal(SIGINT, signal_handler);
    printf("Calibrating for %d seconds...\n", NUM_SAMPLES);
    long sum = 0;
    for (int i = 0; i < NUM_SAMPLES; i++) {
        int val = read_mcp3008(0);
        if (val < 0) {
            fprintf(stderr, "Calibration read error\n");
            spiClose(spi_handle);
            gpioTerminate();
            return 1;
        }
        sum += val;
        gpioDelay(1000000 / NUM_SAMPLES);
    }
    long avg = sum / NUM_SAMPLES;
    printf("Calibration complete. Average: %ld\n", avg);
    printf("Noise threshold: %d\n", (int)(avg * 0.1 + 0.5));
    while (running) {
        int val = read_mcp3008(0);
        if (val < 0) {
            gpioDelay(SAMPLE_DELAY_US);
            continue;
        }
        int above = (val > (avg * 1.1));
        if (above && !gpioRead(LED_PIN)) {
            gpioWrite(LED_PIN, 1);
            gpioDelay(DEBOUNCE_DELAY_MS * 1000);
            gpioWrite(LED_PIN, 0);
        } else if (!above && gpioRead(LED_PIN)) {
            gpioWrite(LED_PIN, 0);
        }
        gpioDelay(SAMPLE_DELAY_US);
    }
    gpioWrite(LED_PIN, 0);
    spiClose(spi_handle);
    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

