#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define SENSOR1_PIN 4
#define SENSOR2_PIN 17
#define SENSOR3_PIN 27
#define VCC 3.3
#define V_QUIESCENT (VCC / 2.0)
#define SENSITIVITY (0.025)  /* 25 mV/mT */
#define LOG_FILE "magnetic_log.txt"
#define SAMPLE_INTERVAL_US 100000  /* 100 ms */
#define FIELD_MIN_MT -100.0
#define FIELD_MAX_MT 100.0

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int read_sensor(struct gpiod_line *line, int pin) {
    int val = gpiod_line_get_value(line);
    if (val < 0) {
        fprintf(stderr, "Error reading GPIO%d: %s\n", pin, strerror(errno));
        return -1;
    }
    return val;
}

static double calculate_magnetic_field(int val) {
    double voltage = (double)val * (VCC / 1023.0);
    return (voltage - V_QUIESCENT) / SENSITIVITY;
}

static int log_data(FILE *fp, int s1, int s2, int s3, double b1, double b2, double b3) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }
    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }
    if (fprintf(fp, "%s,%d,%d,%d,%.2f,%.2f,%.2f\n",
                timestamp, s1, s2, s3, b1, b2, b3) < 0) {
        fprintf(stderr, "fprintf failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[3] = {NULL, NULL, NULL};
    int pins[3] = {SENSOR1_PIN, SENSOR2_PIN, SENSOR3_PIN};
    FILE *fp = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    for (int i = 0; i < 3; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %d: %s\n", pins[i], strerror(errno));
            goto cleanup;
        }
        if (gpiod_line_request_input(lines[i], "drv5055_sensor") < 0) {
            fprintf(stderr, "Failed to request GPIO line %d as input: %s\n", pins[i], strerror(errno));
            goto cleanup;
        }
    }

    fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Failed to open %s: %s\n", LOG_FILE, strerror(errno));
        goto cleanup;
    }

    while (program_running) {
        int s1 = read_sensor(lines[0], SENSOR1_PIN);
        int s2 = read_sensor(lines[1], SENSOR2_PIN);
        int s3 = read_sensor(lines[2], SENSOR3_PIN);

        if (s1 < 0 || s2 < 0 || s3 < 0) {
            fprintf(stderr, "Skipping sample due to GPIO read error.\n");
            usleep(SAMPLE_INTERVAL_US);
            continue;
        }

        double b1 = calculate_magnetic_field(s1);
        double b2 = calculate_magnetic_field(s2);
        double b3 = calculate_magnetic_field(s3);

        if (log_data(fp, s1, s2, s3, b1, b2, b3) != 0) {
            fprintf(stderr, "Logging failed; continuing.\n");
        }

        if (b1 < FIELD_MIN_MT || b1 > FIELD_MAX_MT) {
            fprintf(stderr, "Warning: sensor1 magnetic field %.2f mT out of range.\n", b1);
        }
        if (b2 < FIELD_MIN_MT || b2 > FIELD_MAX_MT) {
            fprintf(stderr, "Warning: sensor2 magnetic field %.2f mT out of range.\n", b2);
        }
        if (b3 < FIELD_MIN_MT || b3 > FIELD_MAX_MT) {
            fprintf(stderr, "Warning: sensor3 magnetic field %.2f mT out of range.\n", b3);
        }

        usleep(SAMPLE_INTERVAL_US);
    }

    ret = EXIT_SUCCESS;

cleanup:
    for (int i = 0; i < 3; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (fp) {
        fclose(fp);
    }
    return ret;
}

