#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define PUMP_GPIO 17
#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define MOISTURE_THRESHOLD 30
#define LOG_FILE "watering.log"
#define SAMPLE_INTERVAL 60

static volatile int running = 1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }
    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0, 0, 0};
    int ret = spiXfer(SPI_CHANNEL, (char*)tx, (char*)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed: %d\n", ret);
        return -1;
    }
    return ((rx[1] & 0x03) << 8) | rx[2];
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);
    gpioWrite(PUMP_GPIO, 0);
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);
    FILE *log = fopen(LOG_FILE, "a");
    if (!log) {
        fprintf(stderr, "Failed to open log\n");
        gpioTerminate();
        return 1;
    }
    time_t now;
    struct tm *tm_info;
    char ts[64];
    fprintf(log, "Program started\n");
    fflush(log);
    while (running) {
        int moisture = read_mcp3008(0);
        if (moisture < 0) {
            time(&now);
            tm_info = localtime(&now);
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm_info);
            fprintf(log, "%s - Error reading moisture sensor\n", ts);
            fflush(log);
            sleep(SAMPLE_INTERVAL);
            continue;
        }
        int pct = (moisture / 1023.0) * 100;
        time(&now);
        tm_info = localtime(&now);
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm_info);
        if (pct < MOISTURE_THRESHOLD) {
            gpioWrite(PUMP_GPIO, 1);
            time(&now);
            tm_info = localtime(&now);
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm_info);
            fprintf(log, "%s - Moisture low (%d%%), turning pump ON\n", ts, pct);
            fflush(log);
        } else {
            gpioWrite(PUMP_GPIO, 0);
            time(&now);
            tm_info = localtime(&now);
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm_info);
            fprintf(log, "%s - Moisture high (%d%%), turning pump OFF\n", ts, pct);
            fflush(log);
        }
        sleep(SAMPLE_INTERVAL);
    }
    gpioWrite(PUMP_GPIO, 0);
    fclose(log);
    gpioTerminate();
    return 0;
}

