#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <mosquitto.h>
#include <cjson/cJSON.h>

#define MQTT_BROKER "mqtt.eclipseprojects.io"
#define MQTT_PORT 1883
#define MQTT_TOPIC "home/led_control"
#define MQTT_CLIENT_ID "rpi_led_control"
#define LED_GPIO 17
#define MAX_RECONNECT_DELAY 60
#define MAX_RECONNECT_ATTEMPTS 10

static struct mosquitto *mosq = NULL;
static volatile sig_atomic_t running = 1;
static volatile sig_atomic_t led_state = 0;

static void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(stderr, "%s: %s\n", timestamp, message);
}

static void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

static int parse_led_state(const char *payload, int *led_state_out) {
    cJSON *root = cJSON_Parse(payload);
    if (!root) {
        log_error("Failed to parse JSON payload");
        return -1;
    }

    cJSON *led_state_json = cJSON_GetObjectItem(root, "led_state");
    if (!led_state_json) {
        log_error("JSON payload missing 'led_state' key");
        cJSON_Delete(root);
        return -1;
    }

    if (!cJSON_IsBoolean(led_state_json)) {
        log_error("Invalid type for 'led_state' key");
        cJSON_Delete(root);
        return -1;
    }

    *led_state_out = (led_state_json->valued_ptr != NULL) ? (int)led_state_json->valued_ptr->valued_ptr->valued_ptr->type == 1 ? 1 : 0 : 0;
    cJSON_Delete(root);
    return 0;
}

static void led_control(int gpio_pin, int state) {
    if (gpioWrite(gpio_pin, state) != 0) {
        log_error("Failed to write to GPIO pin");
    }
}

static void on_connect(struct mosquitto *mosq, void *userdata, int result) {
    (void)userdata;
    if (result == MOSQ_ERR_SUCCESS) {
        printf("Connected to MQTT broker\n");
        int rc = mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, 0);
        if (rc != MOSQ_ERR_SUCCESS) {
            log_error("Failed to subscribe to topic");
        }
    } else {
        log_error("Failed to connect to MQTT broker");
    }
}

static void on_disconnect(struct mosquitto *mosq, void *userdata, int rc) {
    (void)mosq;
    (void)userdata;
    if (rc != MOSQ_ERR_SUCCESS) {
        log_error("Unexpected MQTT disconnect");
    }
}

static void on_message(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message) {
    (void)mosq;
    (void)userdata;

    if (message->payloadlen > 0) {
        char *payload = malloc(message->payloadlen + 1);
        if (!payload) {
            log_error("Failed to allocate memory for payload");
            return;
        }
        memcpy(payload, message->payload, message->payloadlen);
        payload[message->payloadlen] = '\0';

        int led_state;
        if (parse_led_state(payload, &led_state) == 0) {
            led_control(LED_GPIO, led_state);
            printf("LED state set to: %s\n", led_state ? "ON" : "OFF");
        } else {
            log_error("Failed to parse LED state from message");
        }
        free(payload);
    }
}

static void reconnect_handler(struct mosquitto *mosq, void *userdata, int rc) {
    (void)mosq;
    (void)userdata;
    if (rc != MOSQ_ERR_SUCCESS) {
        log_error("MQTT reconnect failed");
    }
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        log_error("pigpio initialisation failed");
        return 1;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    led_control(LED_GPIO, 0);

    mosquitto_lib_init();
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        log_error("Failed to create mosquitto instance");
        gpioTerminate();
        return 1;
    }

    mosquitto_connect_callback_set(mosq, reconnect_handler);
    mosquitto_disconnect_callback_set(mosq, on_disconnect);
    mosquitto_message_callback_set(mosq, on_message);
    mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60);

    int rc = mosquitto_loop_start(mosq);
    if (rc != MOSQ_ERR_SUCCESS) {
        log_error("Failed to start mosquitto loop");
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        gpioTerminate();
        return 1;
    }

    while (running) {
        sleep(1);
    }

    mosquitto_loop_stop(mosq, false);
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
    gpioTerminate();

    return 0;
}

