#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define SOUND_SENSOR_PIN 17
#define ALARM_LED_PIN 18
#define CONSUMER "sound_alarm"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *sound_line = NULL;
    struct gpiod_line *led_line = NULL;
    int ret;

    /* Open the default gpiochip (gpiochip0 on RPi 4) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open gpiochip0");
        return EXIT_FAILURE;
    }

    /* Get the sound sensor line (GPIO17) */
    sound_line = gpiod_chip_get_line(chip, SOUND_SENSOR_PIN);
    if (!sound_line) {
        perror("Failed to get sound sensor line (GPIO17)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Get the LED line (GPIO18) */
    led_line = gpiod_chip_get_line(chip, ALARM_LED_PIN);
    if (!led_line) {
        perror("Failed to get LED line (GPIO18)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request sound sensor line as input */
    ret = gpiod_line_request_input(sound_line, CONSUMER);
    if (ret < 0) {
        perror("Failed to request sound sensor line as input");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request LED line as output, initial value LOW */
    ret = gpiod_line_request_output(led_line, CONSUMER, 0);
    if (ret < 0) {
        perror("Failed to request LED line as output");
        gpiod_line_release(sound_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Set up signal handlers for clean exit */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Failed to set SIGINT handler");
        gpiod_line_release(led_line);
        gpiod_line_release(sound_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Failed to set SIGTERM handler");
        gpiod_line_release(led_line);
        gpiod_line_release(sound_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Sound sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int sound_level = gpiod_line_get_value(sound_line);
        if (sound_level < 0) {
            perror("Failed to read sound sensor value");
            break;
        }

        printf("Sound level: %d\n", sound_level);

        if (sound_level == 0) {
            /* Sound detected (DO = LOW) */
            printf("Sound detected! Activating alarm.\n");
            ret = gpiod_line_set_value(led_line, 1);
            if (ret < 0) {
                perror("Failed to set LED HIGH");
                break;
            }
            sleep(1);
            ret = gpiod_line_set_value(led_line, 0);
            if (ret < 0) {
                perror("Failed to set LED LOW");
                break;
            }
            printf("Alarm deactivated.\n");
        }

        usleep(100000); /* 100 ms delay */
    }

    /* Clean up: turn off LED and release lines */
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
    }
    if (sound_line) {
        gpiod_line_release(sound_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

