    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Failed to set SIGTERM handler");
        gpiod_line_release(led_line);
        gpiod_line_release(sound_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Sound sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int sound_level = gpiod_line_get_value(sound_line);
        if (sound_level < 0) {
            perror("Failed to read sound sensor value");
            break;
        }

        printf("Sound level: %d\n", sound_level);

        if (sound_level == 0) {
            /* Sound detected (DO = LOW) */
            printf("Sound detected! Activating alarm.\n");
            ret = gpiod_line_set_value(led_line, 1);
            if (ret < 0) {
                perror("Failed to set LED HIGH");
                break;
            }
            sleep(1);
            ret = gpiod_line_set_value(led_line, 0);
            if (ret < 0) {
                perror("Failed to set LED LOW");
                break;
            }
            printf("Alarm deactivated.\n");
        }

        usleep(100000); /* 100 ms delay */
    }

    /* Clean up: turn off LED and release lines */
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
    }
    if (sound_line) {
        gpiod_line_release(sound_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

