    i2c_handle = i2cOpen(I2C_BUS, BMP280_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X: %d\n", I2C_BUS, BMP280_I2C_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    int chip_id = i2cReadByteData(i2c_handle, BMP280_REG_CHIP_ID);
    if (chip_id != BMP280_CHIP_ID) {
        fprintf(stderr, "BMP280 not found (chip ID 0x%02X, expected 0x%02X)\n", chip_id, BMP280_CHIP_ID);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (i2c_write_byte(i2c_handle, BMP280_REG_RESET, 0xB6) != 0) {
        fprintf(stderr, "Error resetting BMP280\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    gpioDelay(2000);

    if (read_calibration(i2c_handle) != 0) {
        fprintf(stderr, "Error reading calibration data\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (i2c_write_byte(i2c_handle, BMP280_REG_CONFIG, 0x00) != 0) {
        fprintf(stderr, "Error writing config register\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (i2c_write_byte(i2c_handle, BMP280_REG_CTRL_MEAS, 0x27) != 0) {
        fprintf(stderr, "Error writing ctrl_meas register\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen("altitude_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (running) {
        uint8_t buf[6];
        if (i2c_read_block(i2c_handle, BMP280_REG_PRESS_MSB, buf, 6) != 0) {
            fprintf(stderr, "Error reading pressure/temperature data\n");
            gpioDelay(5000000);
            continue;
        }

        int32_t raw_pressure = ((int32_t)buf[0] << 12) | ((int32_t)buf[1] << 4) | ((int32_t)buf[2] >> 4);
        int32_t raw_temperature = ((int32_t)buf[3] << 12) | ((int32_t)buf[4] << 4) | ((int32_t)buf[5] >> 4);

        int32_t temp_int = compensate_temperature(raw_temperature);
        uint32_t press_int = compensate_pressure(raw_pressure);

        double altitude = calculate_altitude((double)press_int / 256.0);

        if (log_data(altitude) != 0) {
            fprintf(stderr, "Error logging data\n");
        }

        gpioDelay(5000000);
    }

    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

