#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define MCP4725_ADDR 0x62
#define DAC_RESOLUTION 4095.0
#define VREF 3.3
#define LOG_FILE "temperature_log.txt"
#define SAMPLE_INTERVAL_US 500000
#define MAX_RETRIES 3

static int spi_handle = -1;
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) return -1;
    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};
    if (spiXfer(spi_handle, (char *)tx, (char *)rx, 3) != 3) return -1;
    return ((rx[1] & 0x03) << 8) | rx[2];
}

static float adc_to_temperature(int adc) {
    return (adc * 500.0) / 1023.0 - 50.0;
}

static float temp_to_dac_voltage(float temp) {
    if (temp < 0.0f) temp = 0.0f;
    if (temp > 50.0f) temp = 50.0f;
    return (temp / 50.0f) * VREF;
}

static int dac_write_voltage(float voltage) {
    if (voltage < 0.0f || voltage > VREF) return -1;
    int dac_value = (int)((voltage / VREF) * DAC_RESOLUTION);
    if (dac_value < 0) dac_value = 0;
    if (dac_value > DAC_RESOLUTION) dac_value = DAC_RESOLUTION;
    unsigned char buf[2] = {0x40 | (dac_value >> 8), (unsigned char)(dac_value & 0xFF)};
    if (i2cWriteDevice(i2c_handle, (char *)buf, 2) != 2) return -1;
    return 0;
}

static void log_data(int adc, float temp, float voltage) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s, ADC: %d, Temp: %.2f C, DAC: %.2f V\n", ts, adc, temp, voltage);
    fflush(log_file);
    printf("%s, ADC: %d, Temp: %.2f C, DAC: %.2f V\n", ts, adc, temp, voltage);
}

static void cleanup(void) {
    if (spi_handle >= 0) spiClose(spi_handle);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    if (log_file) fclose(log_file);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }
    i2c_handle = i2cOpen(1, MCP4725_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }
    struct sigaction sa = {0};
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    while (!terminate) {
        int adc = -1;
        for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
            adc = read_mcp3008(0);
            if (adc >= 0) break;
            gpioDelay(10000);
        }
        if (adc < 0) {
            fprintf(stderr, "SPI read failed after %d retries\n", MAX_RETRIES);
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }
        float temp = adc_to_temperature(adc);
        float voltage = temp_to_dac_voltage(temp);
        if (dac_write_voltage(voltage) != 0) {
            fprintf(stderr, "DAC write failed\n");
        }
        log_data(adc, temp, voltage);
        gpioDelay(SAMPLE_INTERVAL_US);
    }
    cleanup();
    return 0;
}

