#define NUM_SENSORS 3
#define LOG_FILE "soil_data.txt"
#define SLEEP_INTERVAL 60

static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid channel %d\n", channel);
        return -1;
    }
    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0, 0, 0};
    if (spiXfer(spi_handle, tx, rx, 3) != 0) {
        fprintf(stderr, "SPI transfer failed on channel %d\n", channel);
        return -1;
    }
    return ((rx[1] & 0x03) << 8) | rx[2];
}

static float convert_to_moisture(int adc_value) {
    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "ADC value out of range: %d\n", adc_value);
        return -1.0f;
    }
    return (1.0f - (float)adc_value / 1023.0f) * 100.0f;
}

static void log_data(FILE *fp, int sensor_id, float moisture) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(fp, "%s, Sensor %d, Moisture: %.2f%%\n", timestamp, sensor_id, moisture);
    fflush(fp);
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

