#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- Pin assignments (BCM numbering) ---- */
#define MOTOR_IN1 17
#define MOTOR_IN2 18
#define MOTOR_ENA 27

/* ---- SPI configuration ---- */
#define SPI_CHANNEL 0
#define SPI_SPEED   1000000  /* 1 MHz */
#define SPI_FLAGS   0        /* mode 0, active-low CE handled by pigpio */

/* ---- Rain sensor channel on MCP3008 ---- */
#define RAIN_CHANNEL 0

/* ---- Motor parameters ---- */
#define MOTOR_PWM_RANGE 255
#define MOTOR_PWM_DUTY  150

/* ---- Rain threshold (rain level 0-10) ---- */
#define RAIN_THRESHOLD 5

/* ---- Motor run durations (ms) ---- */
#define MOTOR_CLOSE_MS  3000
#define MOTOR_OPEN_MS   3000

/* ---- Polling interval (ms) ---- */
#define POLL_INTERVAL_MS 1000

/* ---- Log file ---- */
#define LOG_FILE "rain_log.txt"

/* ---- Global state for signal handler ---- */
static volatile sig_atomic_t g_running = 1;
static int  g_spi_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag only; cleanup happens in main loop        */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read MCP3008 single-ended channel; returns 0-1023 or -1 on error    */
/* ------------------------------------------------------------------ */
static int read_mcp3008(int handle, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid channel %d\n", channel);
        return -1;
    }

    /* MCP3008 single-ended read: 3 bytes
     *   tx[0] = 0x01  (start bit)
     *   tx[1] = (0x08 | channel) << 4  (single-ended + channel)
     *   tx[2] = 0x00  (clock out remaining bits)
     * Result: bits 9..8 in rx[1] (masked 0x03), bits 7..0 in rx[2]
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return adc;
}

/* ------------------------------------------------------------------ */
/* Convert ADC value (0-1023) to rain level (0-10)                   */
/* Grove Rain Sensor: higher voltage = drier soil  -> rain_level 10 */
/* at ADC 1023; lower voltage = wetter soil  -> rain_level 0 at ADC 0 */
/* ------------------------------------------------------------------ */
static int adc_to_rain_level(int adc)
{
    if (adc < 0)   adc = 0;
    if (adc > 1023) adc = 1023;
    return 10 - (adc * 10) / 1023;  /* clamps to 0-10 */
}

/* ------------------------------------------------------------------ */
/* Drive motor: IN1, IN2, PWM speed (0-255)                           */
/* ------------------------------------------------------------------ */
static void motor_drive(int in1, int in2, int pwm)
{
    if (gpioWrite(MOTOR_IN1, in1) < 0)
        fprintf(stderr, "gpioWrite IN1 failed\n");
    if (gpioWrite(MOTOR_IN2, in2) < 0)
        fprintf(stderr, "gpioWrite IN2 failed\n");
    if (gpioPWM(MOTOR_ENA, pwm) < 0)
        fprintf(stderr, "gpioPWM failed\n");
}

/* ------------------------------------------------------------------ */
/* Open log file in append mode; returns 0 on success, -1 on error     */
/* ------------------------------------------------------------------ */
static int open_log_file(void)
{
    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        perror("fopen(" LOG_FILE ")");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Log a timestamped rain reading; returns 0 on success, -1 on error   */
/* ------------------------------------------------------------------ */
static int log_rain_level(int rain_level)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        perror("time()");
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        perror("localtime_r");
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(g_log_file, "%s, Rain Level: %d\n", ts, rain_level) < 0) {
        perror("fprintf");
        return -1;
    }
    if (fflush(g_log_file) != 0) {
        perror("fflush");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — called on every exit path                          */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    /* Stop motor */
    motor_drive(0, 0, 0);

    /* Close SPI */
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }

    /* Close log file */
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }

    /* Terminate pigpio */
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Configure motor GPIOs */
    if (gpioSetMode(MOTOR_IN1, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_IN2, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_ENA, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Ensure motor is off at start */
    motor_drive(0, 0, 0);

    /* Open SPI */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (handle %d)\n", g_spi_handle);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file */
    if (open_log_file() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Window state */
    int window_open = 1;  /* 1 = open, 0 = closed */

    /* Main loop */
    while (g_running) {
        int adc = read_mcp3008(g_spi_handle, RAIN_CHANNEL);
        if (adc < 0) {
            fprintf(stderr, "ADC read failed; retrying in 1 s\n");
            gpioDelay(POLL_INTERVAL_MS * 1000);
            continue;
        }

        int rain_level = adc_to_rain_level(adc);

        if (log_rain_level(rain_level) != 0) {
            fprintf(stderr, "Logging failed; continuing\n");
        }

        printf("Rain Level: %d\n", rain_level);

        if (rain_level >= RAIN_THRESHOLD && window_open) {
            printf("Rain detected — closing window\n");
            motor_drive(1, 0, MOTOR_PWM_DUTY);
            gpioDelay(MOTOR_CLOSE_MS * 1000);
            motor_drive(0, 0, 0);
            window_open = 0;
        } else if (!window_open && rain_level < RAIN_THRESHOLD) {
            printf("Rain stopped — opening window\n");
            motor_drive(0, 1, MOTOR_PWM_DUTY);
            gpioDelay(MOTOR_OPEN_MS * 1000);
            motor_drive(0, 0, 0);
            window_open = 1;
        }

        gpioDelay(POLL_INTERVAL_MS * 1000);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

