        return EXIT_FAILURE;
    }

    /* Ensure motor is off at start */
    motor_drive(0, 0, 0);

    /* Open SPI */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (handle %d)\n", g_spi_handle);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file */
    if (open_log_file() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Window state */
    int window_open = 1;  /* 1 = open, 0 = closed */

    /* Main loop */
    while (g_running) {
        int adc = read_mcp3008(g_spi_handle, RAIN_CHANNEL);
        if (adc < 0) {
            fprintf(stderr, "ADC read failed; retrying in 1 s\n");
            gpioDelay(POLL_INTERVAL_MS * 1000);
            continue;
        }

        int rain_level = adc_to_rain_level(adc);

        if (log_rain_level(rain_level) != 0) {
            fprintf(stderr, "Logging failed; continuing\n");
        }

        printf("Rain Level: %d\n", rain_level);

        if (rain_level >= RAIN_THRESHOLD && window_open) {
            printf("Rain detected — closing window\n");
            motor_drive(1, 0, MOTOR_PWM_DUTY);
            gpioDelay(MOTOR_CLOSE_MS * 1000);
            motor_drive(0, 0, 0);
            window_open = 0;
        } else if (!window_open && rain_level < RAIN_THRESHOLD) {
            printf("Rain stopped — opening window\n");
            motor_drive(0, 1, MOTOR_PWM_DUTY);
            gpioDelay(MOTOR_OPEN_MS * 1000);
            motor_drive(0, 0, 0);
            window_open = 1;
        }

        gpioDelay(POLL_INTERVAL_MS * 1000);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

