#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define MIC_GPIO 26
#define LED_GPIO 16
#define THRESHOLD 700
#define DEBOUNCE_MS 50
#define LED_ON_MS 500
#define SAMPLE_DELAY_US 1000

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_detection(void) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Failed to get local time\n");
        return;
    }
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    printf("[%s] Clap detected!\n", timestamp);
    fflush(stdout);
}

int main(void) {
    int ret;

    /* Install SIGINT handler for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio library */
    ret = gpioInitialise();
    if (ret < 0) {
        fprintf(stderr, "pigpio initialization failed (code %d)\n", ret);
        return EXIT_FAILURE;
    }

    /* Configure microphone GPIO as input */
    if (gpioSetMode(MIC_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", MIC_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure LED GPIO as output and ensure it starts OFF */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(LED_GPIO, 0) != 0) {
        fprintf(stderr, "Failed to initialize LED state on GPIO%d\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Clap detector running. Press Ctrl+C to exit.\n");
    fflush(stdout);

    uint32_t last_trigger_tick = 0;

    while (running) {
        int adc_value = gpioRead(MIC_GPIO);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read GPIO%d\n", MIC_GPIO);
            break;
        }

        if (adc_value > THRESHOLD) {
            uint32_t now = gpioTick();
            if (now - last_trigger_tick > (uint32_t)(DEBOUNCE_MS * 1000)) {
                log_detection();
                if (gpioWrite(LED_GPIO, 1) != 0) {
                    fprintf(stderr, "Failed to turn on LED on GPIO%d\n", LED_GPIO);
                    break;
                }
                gpioDelay(LED_ON_MS * 1000);
                if (gpioWrite(LED_GPIO, 0) != 0) {
                    fprintf(stderr, "Failed to turn off LED on GPIO%d\n", LED_GPIO);
                    break;
                }
                last_trigger_tick = now;
            }
        }

        gpioDelay(SAMPLE_DELAY_US);
    }

    /* Clean shutdown */
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

