#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#define GPIO_PIN 17
#define LOG_FILE "distance_log.txt"
#define PROXIMITY_THRESHOLD 200.0
#define A 26.0
#define B -6.0
#define VOLTAGE_HIGH 3.3
#define VOLTAGE_LOW 0.0

static volatile int keep_running = 1;

void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int read_gpio_value(int pin) {
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", pin);
    FILE *fp = fopen(path, "r");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", path, strerror(errno));
        return -1;
    }
    int val = fgetc(fp);
    fclose(fp);
    return val;
}

float voltage_to_distance(float voltage) {
    if (voltage <= 0.0) return 1000.0;
    return (A / voltage) + B;
}

int log_distance(float distance) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s, Distance: %.2f mm\n", timestamp, distance);
    fclose(fp);
    return 0;
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (sysfs_export_gpio(GPIO_PIN) != 0) {
        fprintf(stderr, "Failed to export GPIO %d\n", GPIO_PIN);
        return 1;
    }

    while (keep_running) {
        int val = read_gpio_value(GPIO_PIN);
        if (val < 0) {
            fprintf(stderr, "Error reading GPIO %d, retrying in 1s...\n", GPIO_PIN);
            sleep(1);
            continue;
        }

        float voltage = (val == 1) ? VOLTAGE_HIGH : VOLTAGE_LOW;
        float distance = voltage_to_distance(voltage);

        if (log_distance(distance) != 0) {
            fprintf(stderr, "Error logging distance\n");
        }

        if (distance < PROXIMITY_THRESHOLD) {
            printf("Feeder Activated\n");
        } else {
            printf("Feeder Idle\n");
        }

        sleep(1);
    }

    sysfs_unexport_gpio(GPIO_PIN);
    printf("Program terminated cleanly\n");
    return 0;
}

