#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define PUMP_GPIO_LINE 17
#define DRY_ADC_VALUE 800
#define WET_ADC_VALUE 300
#define MOISTURE_THRESHOLD 30
#define LOG_FILE "soil_moisture.log"
#define SAMPLE_INTERVAL 60

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static int spi_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *pump_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("open SPI device");
        return -1;
    }

    int mode = SPI_MODE_0;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("ioctl SPI_IOC_WR_MODE");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    int bits = 8;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("ioctl SPI_IOC_WR_BITS_PER_WORD");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    int speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("ioctl SPI_IOC_WR_MAX_SPEED_HZ");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    return 0;
}

static int read_mcp3008(int channel) {
    if (spi_fd < 0) return -1;

    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("ioctl SPI_IOC_MESSAGE");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static int read_soil_moisture(void) {
    int adc_value = read_mcp3008(0);
    if (adc_value < 0) {
        fprintf(stderr, "Error reading ADC value\n");
        return -1;
    }

    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "ADC value out of range: %d\n", adc_value);
        return -1;
    }

    int moisture_level = 100 - ((int)(((float)(adc_value - WET_ADC_VALUE) / (float)(DRY_ADC_VALUE - WET_ADC_VALUE)) * 100.0));
    if (moisture_level < 0) moisture_level = 0;
    if (moisture_level > 100) moisture_level = 100;

    return moisture_level;
}

static int control_pump(int state) {
    if (pump_line == NULL) return -1;

    int ret = gpiod_line_set_value(pump_line, state);
    if (ret < 0) {
        perror("gpiod_line_set_value");
        return -1;
    }
    return 0;
}

static void log_data(int moisture_level, int pump_state) {
    if (log_file == NULL) return;

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d, Moisture: %d%%, Pump: %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            moisture_level, pump_state ? "ON" : "OFF");
    fflush(log_file);
}

static void cleanup(void) {
    if (pump_line != NULL) {
        gpiod_line_set_value(pump_line, 0);
        gpiod_line_release(pump_line);
        pump_line = NULL;
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("fopen log file");
        return 1;
    }

    if (spi_init() < 0) {
        fprintf(stderr, "SPI initialization failed\n");
        cleanup();
        return 1;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        perror("gpiod_chip_open_by_name");
        cleanup();
        return 1;
    }

    pump_line = gpiod_chip_get_line(chip, PUMP_GPIO_LINE);
    if (pump_line == NULL) {
        perror("gpiod_chip_get_line");
        cleanup();
        return 1;
    }

    if (gpiod_line_request_output(pump_line, "soil_moisture", 0) < 0) {
        perror("gpiod_line_request_output");
        cleanup();
        return 1;
    }

    printf("Soil Moisture Monitoring System started. Press Ctrl+C to exit.\n");

    while (running) {
        int moisture_level = read_soil_moisture();
        if (moisture_level < 0) {
            fprintf(stderr, "Error reading soil moisture, skipping pump control.\n");
        } else {
            int pump_state = (moisture_level < MOISTURE_THRESHOLD) ? 1 : 0;
            if (control_pump(pump_state) < 0) {
                fprintf(stderr, "Error controlling pump.\n");
            }
            log_data(moisture_level, pump_state);
        }

        for (int i = 0; i < SAMPLE_INTERVAL && running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return 0;
}

