#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define ADC_CHANNEL 0
#define LED_GPIO 21
#define VREF 3.3
#define ADC_MAX 1023.0
#define THRESHOLD_MT 10.0
#define SENSITIVITY_MV_PER_MT 1.65
#define LOG_FILE "magnetic_log.txt"
#define SAMPLE_DELAY_US 100000

static int spi_handle = -1;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }
    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0, 0, 0};
    if (spiXfer(spi_handle, tx, rx, 3) != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }
    return ((rx[1] & 0x03) << 8) | rx[2];
}

static float voltage_to_field_mT(float voltage) {
    float quiescent = VREF / 2.0f;
    return (voltage - quiescent) * 1000.0f / SENSITIVITY_MV_PER_MT;
}

static int log_reading(float field_mT) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log");
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Field: %.2f mT\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, field_mT);
    } else {
        fprintf(fp, "timestamp_error, Field: %.2f mT\n", field_mT);
    }
    fclose(fp);
    return 0;
}

static void control_led(float field_mT) {
    if (field_mT > THRESHOLD_MT) {
        gpioWrite(LED_GPIO, 1);
    } else {
        gpioWrite(LED_GPIO, 0);
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "spiOpen failed\n");
        gpioTerminate();
        return 1;
    }
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);
    signal(SIGINT, signal_handler);
    printf("DRV5055VA Hall sensor monitoring started. Press Ctrl+C to exit.\n");
    while (running) {
        int adc = read_mcp3008(ADC_CHANNEL);
        if (adc < 0) {
            fprintf(stderr, "ADC read error, retrying...\n");
            gpioDelay(SAMPLE_DELAY_US);
            continue;
        }
        float voltage = (float)adc * VREF / ADC_MAX;
        float field_mT = voltage_to_field_mT(voltage);
        if (log_reading(field_mT) != 0) {
            fprintf(stderr, "Logging failed\n");
        }
        control_led(field_mT);
        gpioDelay(SAMPLE_DELAY_US);
    }
    gpioWrite(LED_GPIO, 0);
    spiClose(spi_handle);
    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return 0;
}

