        fprintf(fp, "timestamp_error, Field: %.2f mT\n", field_mT);
    }
    fclose(fp);
    return 0;
}

static void control_led(float field_mT) {
    if (field_mT > THRESHOLD_MT) {
        gpioWrite(LED_GPIO, 1);
    } else {
        gpioWrite(LED_GPIO, 0);
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "spiOpen failed\n");
        gpioTerminate();
        return 1;
    }
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);
    signal(SIGINT, signal_handler);
    printf("DRV5055VA Hall sensor monitoring started. Press Ctrl+C to exit.\n");
    while (running) {
        int adc = read_mcp3008(ADC_CHANNEL);
        if (adc < 0) {
            fprintf(stderr, "ADC read error, retrying...\n");
            gpioDelay(SAMPLE_DELAY_US);
            continue;
        }
        float voltage = (float)adc * VREF / ADC_MAX;
        float field_mT = voltage_to_field_mT(voltage);
        if (log_reading(field_mT) != 0) {
            fprintf(stderr, "Logging failed\n");
        }
        control_led(field_mT);
        gpioDelay(SAMPLE_DELAY_US);
    }
    gpioWrite(LED_GPIO, 0);
    spiClose(spi_handle);
    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return 0;
}

