code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---------------- Configuration ---------------- */
#define SPI_CHANNEL    0          /* CE0 on GPIO8 */
#define SPI_SPEED      1000000    /* 1 MHz */
#define SPI_FLAGS      0          /* Mode 0, active-low CE */
#define ADC_CHANNEL    0          /* MCP3008 single-ended channel 0 */
#define ADC_MAX        1023       /* 10-bit ADC */
#define VREF           5.0        /* MCP3008 VREF tied to Pi 5V */
#define VZERO          2.5        /* MLX91211 VDD/2 at 0A */
#define FULLSCALE_A    50.0       /* Full-scale current (A) */
#define LOG_FILE       "current_log.txt"
#define SAMPLE_US      100000     /* 100 ms between samples */

/* ---------------- Globals ---------------- */
static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t program_running = 1;

/* ---------------- Prototypes ---------------- */
static int  read_mcp3008(int channel, int *out_value);
static float voltage_to_current(float voltage);
static int  log_current(float current);
static void signal_handler(int sig);
static void cleanup(void);

/* ---------------- MCP3008 read ---------------- */
static int read_mcp3008(int channel, int *out_value)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }
    if (out_value == NULL) {
        fprintf(stderr, "read_mcp3008: out_value is NULL\n");
        return -1;
    }

    /*
     * MCP3008 single-ended read (3-byte transfer):
     *   tx[0] = 0x01                       start bit
     *   tx[1] = 0x80 | (channel << 4)      SGL/DIFF=1, D2 D1 D0 = channel
     *   tx[2] = 0x00                       padding
     * Result: 10-bit code in ((rx[1] & 0x03) << 8) | rx[2]
     */
    char tx[3] = { 0x01, (char)(0x80 | (channel << 4)), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "spiXfer failed (returned %d)\n", ret);
        return -1;
    }

    *out_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return 0;
}

/* ---------------- Voltage -> current ---------------- */
static float voltage_to_current(float voltage)
{
    if (voltage < 0.0f || voltage > VREF) {
        fprintf(stderr, "Warning: voltage %.3fV out of range [0, %.1fV]\n",
                voltage, VREF);
        return -1.0f;  /* sentinel: skip this sample */
    }
    return (voltage - VZERO) * (FULLSCALE_A / VZERO);
}

/* ---------------- Log current ---------------- */
static int log_current(float current)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    if (fprintf(log_file, "%s %.2f A\n", timestamp, current) < 0) {
        perror("fprintf to log file");
        return -1;
    }
    if (fflush(log_file) != 0) {
        perror("fflush log file");
        return -1;
    }
    return 0;
}

/* ---------------- Signal handler ---------------- */
static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

/* ---------------- Cleanup ---------------- */
static void cleanup(void)
{
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioTerminate();
}

/* ---------------- Main ---------------- */
int main(void)
{
    /* Initialize pigpio */
