#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define CHIP_NUMBER 0
#define SENSOR1_PIN 4
#define SENSOR2_PIN 17
#define DEBOUNCE_SAMPLES 5
#define DEBOUNCE_DELAY_MS 2
#define POLL_INTERVAL_SEC 1

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_sensor(struct gpiod_line *line) {
    int low_count = 0;
    int high_count = 0;
    for (int i = 0; i < DEBOUNCE_SAMPLES; i++) {
        int val = gpiod_line_get_value(line);
        if (val < 0) {
            fprintf(stderr, "Error reading sensor line: %s\n", strerror(errno));
            return -1;
        }
        if (val == 0) low_count++;
        else high_count++;
        usleep(DEBOUNCE_DELAY_MS * 1000);
    }
    return (low_count > high_count) ? 0 : 1;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL, *line2 = NULL;
    int ret = EXIT_FAILURE;

    signal(SIGINT, sigint_handler);

    chip = gpiod_chip_open_by_number(CHIP_NUMBER);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip %d: %s\n", CHIP_NUMBER, strerror(errno));
        return EXIT_FAILURE;
    }

    line1 = gpiod_chip_get_line(chip, SENSOR1_PIN);
    if (!line1) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", SENSOR1_PIN, strerror(errno));
        goto cleanup;
    }
    line2 = gpiod_chip_get_line(chip, SENSOR2_PIN);
    if (!line2) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", SENSOR2_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input(line1, "b5w-sensor1") < 0) {
        fprintf(stderr, "Failed to request input on GPIO %d: %s\n", SENSOR1_PIN, strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_input(line2, "b5w-sensor2") < 0) {
        fprintf(stderr, "Failed to request input on GPIO %d: %s\n", SENSOR2_PIN, strerror(errno));
        goto cleanup;
    }

    while (running) {
        int s1 = read_sensor(line1);
        int s2 = read_sensor(line2);

        if (s1 < 0 || s2 < 0) {
            fprintf(stderr, "Sensor read error, exiting.\n");
            goto cleanup;
        }

        printf("Sensor 1: %s, Sensor 2: %s\n", s1 ? "no object" : "object present",
               s2 ? "no object" : "object present");

        if (s1 == 0 && s2 == 0) {
            printf("ALERT: Both sensors detect object\n");
        }

        sleep(POLL_INTERVAL_SEC);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line1) gpiod_line_release(line1);
    if (line2) gpiod_line_release(line2);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

