#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <errno.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <pigpio.h>

#define PIR_GPIO 17
#define POLL_INTERVAL_US 50000   /* 50 ms */
#define DEBOUNCE_US 200000       /* 200 ms */
#define IMAGE_WIDTH 1280
#define IMAGE_HEIGHT 720
#define CAPTURE_DIR "/home/pi/security_cam"
#define LOG_FILE "/var/log/security_cam.log"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

static int ensure_directory(const char *path)
{
    struct stat st;
    if (stat(path, &st) == 0) {
        if (S_ISDIR(st.st_mode))
            return 0;
        syslog(LOG_ERR, "Path exists but is not a directory: %s", path);
        return -1;
    }
    if (errno != ENOENT) {
        syslog(LOG_ERR, "stat(%s) failed: %s", path, strerror(errno));
        return -1;
    }
    if (mkdir(path, 0755) != 0) {
        syslog(LOG_ERR, "mkdir(%s) failed: %s", path, strerror(errno));
        return -1;
    }
    return 0;
}

static int capture_image(const char *filename)
{
    pid_t pid = fork();
    if (pid < 0) {
        syslog(LOG_ERR, "fork() failed: %s", strerror(errno));
        return -1;
    }
    if (pid == 0) {
        /* Child: redirect stdout/stderr to /dev/null to keep syslog clean */
        freopen("/dev/null", "w", stdout);
        freopen("/dev/null", "w", stderr);
        execlp("libcamera-still", "libcamera-still",
               "--width", "1280",
               "--height", "720",
               "--encoding", "jpeg",
               "--nopreview",
               "--timeout", "1000",
               (char *)filename, (char *)NULL);
        /* If execlp returns, it failed */
        _exit(127);
    }
    /* Parent: wait for child */
    int status = 0;
    while (waitpid(pid, &status, 0) < 0) {
        if (errno == EINTR) {
            if (!running)
                return -1;
            continue;
        }
        syslog(LOG_ERR, "waitpid() failed: %s", strerror(errno));
        return -1;
    }
    if (WIFEXITED(status) && WEXITSTATUS(status) == 0)
        return 0;
    syslog(LOG_ERR, "libcamera-still failed (status=%d)", status);
    return -1;
}

static int log_event(const char *message)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
