    req.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_REQBUFS, &req) == -1) {
        fprintf(stderr, "VIDIOC_REQBUFS failed: %s\n", strerror(errno));
        goto cleanup;
    }

    if (req.count < 1) {
        fprintf(stderr, "Insufficient buffer memory\n");
        goto cleanup;
    }

    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (xioctl(fd, VIDIOC_QUERYBUF, &buf) == -1) {
        fprintf(stderr, "VIDIOC_QUERYBUF failed: %s\n", strerror(errno));
        goto cleanup;
    }

    buffer_size = buf.length;
    buffer = (unsigned char *)mmap(NULL, buffer_size, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (buffer == MAP_FAILED) {
        fprintf(stderr, "mmap failed: %s\n", strerror(errno));
        buffer = NULL;
        goto cleanup;
    }

    if (xioctl(fd, VIDIOC_QBUF, &buf) == -1) {
        fprintf(stderr, "VIDIOC_QBUF failed: %s\n", strerror(errno));
        goto cleanup;
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMON, &type) == -1) {
        fprintf(stderr, "VIDIOC_STREAMON failed: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("Streaming %s (640x480, 8-bit grey)...\n", device);

    int frame_number = 0;
    while (!stop_flag) {
        fd_set fds;
        FD_ZERO(&fds);
        FD_SET(fd, &fds);

        struct timeval tv;
        tv.tv_sec = 2;
        tv.tv_usec = 0;

        int r = select(fd + 1, &fds, NULL, NULL, &tv);
        if (r == -1) {
            if (errno == EINTR) {
                continue;
            }
            fprintf(stderr, "select() failed: %s\n", strerror(errno));
            goto cleanup;
        } else if (r == 0) {
            fprintf(stderr, "select() timeout\n");
            continue;
        }

        if (capture_frame(fd, &buffer, &buffer_size) == -1) {
            goto cleanup;
        }

        if (save_pgm(buffer, buffer_size, "image_0001.pgm") == -1) {
            goto cleanup;
        }

        frame_number++;
        if (frame_number >= MAX_FRAMES) {
            fprintf(stderr, "Max frames reached (%d). Exiting.\n", MAX_FRAMES);
            goto cleanup;
        }
    }

    printf("Received signal, stopping stream.\n");
    goto cleanup;

cleanup:
    if (fd != -1) {
        if (buffer != NULL && buffer != MAP_FAILED) {
            munmap(buffer, buffer_size);
        }
        if (xioctl(fd, VIDIOC_STREAMOFF, &type) == -1) {
            fprintf(stderr, "Failed to turn off stream on close: %s\n", strerror(errno));
        }
        close(fd);
    }
    return ret;
}

