#include <sys/mman.h>
#include <sys/select.h>
#include <time.h>
#include <signal.h>
#include <linux/videodev2.h>

#define DEVICE_NAME "/dev/video0"
#define LOG_FILE "frame_log.txt"
#define FRAME_WIDTH 640
#define FRAME_HEIGHT 480
#define NUM_BUFFERS 4

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int xioctl(int fd, unsigned long request, void *arg) {
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

static int init_camera(int *fd) {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    unsigned int n;
    unsigned int i;

    *fd = open(DEVICE_NAME, O_RDWR);
    if (*fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", DEVICE_NAME, strerror(errno));
        return -1;
    }

    if (xioctl(*fd, VIDIOC_QUERYCAP, &cap) < 0) {
        fprintf(stderr, "Error querying capabilities: %s\n", strerror(errno));
        close(*fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is not a video capture device\n", DEVICE_NAME);
        close(*fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming I/O\n", DEVICE_NAME);
        close(*fd);
        return -1;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = FRAME_WIDTH;
    fmt.fmt.pix.height = FRAME_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_MJPEG;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (xioctl(*fd, VIDIOC_S_FMT, &fmt) < 0) {
        fprintf(stderr, "Error setting format: %s\n", strerror(errno));
        close(*fd);
        return -1;
    }

    memset(&req, 0, sizeof(req));
    req.count = NUM_BUFFERS;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (xioctl(*fd, VIDIOC_REQBUFS, &req) < 0) {
        fprintf(stderr, "Error requesting buffers: %s\n", strerror(errno));
        close(*fd);
        return -1;
    }

    for (n = 0; n < req.count; n++) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = n;

        if (xioctl(*fd, VIDIOC_QUERYBUF, &buf) < 0) {
            fprintf(stderr, "Error querying buffer %u: %s\n", n, strerror(errno));
            close(*fd);
            return -1;
        }

        buf.length = buf.bytesused;

        if (buf.length < (unsigned int)buf.bytesused) {
            fprintf(stderr, "Warning: buffer %u has padding: %u bytes\n", n, buf.length - buf.bytesused);
        }

        void *map = mmap(NULL, buf.bytesused, PROT_READ | PROT_WRITE, MAP_SHARED, *fd, buf.m.offset);
        if (map == MAP_FAILED) {
            fprintf(stderr, "Error mapping buffer %u: %s\n", n, strerror(errno));
            munmap(map, buf.bytesused);
            close(*fd);
            return -1;
        }

        *(unsigned int *)map = buf.bytesused;
        buffers[n] = map;
    }

    return 0;
}

static int start_capturing(int fd) {
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    for (n = 0; n < req.count; n++) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = n;

        if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            fprintf(stderr, "Error queueing buffer %u: %s\n", n, strerror(errno));
            return -1;
        }
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        fprintf(stderr, "Error starting stream: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int capture_frame(int fd, FILE *log_file) {
    fd_set fds;
    struct timeval tv;
    int r;

    FD_ZERO(&fds);
    FD_SET(fd, &fds);

    tv.tv_sec = 2;
    tv.tv_usec = 0;

    r = select(fd + 1, &fds, NULL, NULL, &tv);

    if (r == -1) {
        if (errno == EINTR) return -1;
        fprintf(stderr, "Error in select(): %s\n", strerror(errno));
        return -1;
    }

    if (r == 0) {
        fprintf(stderr, "select() timeout\n");
        return -1;
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        fprintf(stderr, "Error dequeuing buffer: %s\n", strerror(errno));
        return -1;
    }

    if (buf.bytesused > 0) {
        struct timeval tv2;
        gettimeofday(&tv2, NULL);
        long long timestamp_us = (long long)tv2.tv_sec * 1000000LL + (long long)tv2.tv_usec;

        if (fprintf(log_file, "%lld\n", timestamp_us) < 0) {
            fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
            return -1;
        }
        fflush(log_file);
    }

    if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        fprintf(stderr, "Error re-queueing buffer: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    int fd = -1;
    FILE *log_file = NULL;
    unsigned int *buffer_sizes = NULL;
    unsigned int i;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting up signal handler: %s\n", strerror(errno));
        return 1;
    }

    log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return 1;
    }

    if (init_camera(&fd) < 0) {
        fprintf(stderr, "Camera initialization failed\n");
        fclose(log_file);
        return 1;
    }

    if (start_capturing(fd) < 0) {
        fprintf(stderr, "Camera capture start failed\n");
        munmap(buffers, buffers_size);
        fclose(log_file);
        return 1;
    }

    buffer_sizes = malloc(req.count * sizeof(unsigned int));
    if (buffer_sizes == NULL) {
        fprintf(stderr, "Error allocating buffer sizes: %s\n", strerror(errno));
        close(fd);
        fclose(log_file);
        return 1;
    }

    for (i = 0; i < req.count; i++) {
        buffer_sizes[i] = *(unsigned int *)buffers[i];
    }

    while (running) {
        if (capture_frame(fd, log_file) < 0) {
            fprintf(stderr, "Error capturing frame\n");
            break;
        }
    }

    if (close(fd) < 0) {
        fprintf(stderr, "Error closing camera device: %s\n", strerror(errno));
    }

    if (buffer_sizes != NULL) {
        for (i = 0; i < req.count; i++) {
            if (buffers[i] != NULL) {
                munmap(buffers[i], buffer_sizes[i]);
            }
        }
        free(buffer_sizes);
    }

    if (log_file != NULL) {
        fclose(log_file);
    }

    printf("Program terminated gracefully.\n");
    return 0;
}

