#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <linux/videodev2.h>

#define VIDEO_DEVICE "/dev/video0"
#define FRAME_WIDTH 640
#define FRAME_HEIGHT 480
#define NUM_BUFFERS 4
#define UDP_BUFFER_SIZE 65000
#define MAX_UDP_PAYLOAD 65536
#define UDP_HEADER_SIZE 16

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int xioctl(int fd, unsigned long request, void *arg) {
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

static int capture_frame(int fd, unsigned char *frame_data, size_t *frame_size) {
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        fprintf(stderr, "VIDIOC_DQBUF failed: %s\n", strerror(errno));
        return -1;
    }

    if (buf.index >= 0 && buf.index >= NUM_BUFFERS) {
        fprintf(stderr, "Buffer index out of range: %d\n", buf.index);
        return -1;
    }

    size_t frame_size = buf.bytesused;
    if (frame_size == 0) {
        fprintf(stderr, "Frame size is zero\n");
        return -1;
    }

    memcpy(frame_data, buf.buffer, frame_size);
    *frame_size = frame_size;

    if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        fprintf(stderr, "VIDIOC_QBUF failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int send_udp_frame(int sockfd, const unsigned char *frame_data, size_t frame_size) {
    size_t payload_size = frame_size - UDP_HEADER_SIZE;
    if (payload_size > MAX_UDP_PAYLOAD) {
        fprintf(stderr, "Payload size %zu exceeds %d\n", payload_size, MAX_UDP_PAYLOAD);
        return -1;
    }

    size_t total_size = UDP_HEADER_SIZE + payload_size;
    if (total_size > UDP_BUFFER_SIZE) {
        fprintf(stderr, "Total size %zu exceeds %d\n", total_size, UDP_BUFFER_SIZE);
        return -1;
    }

    unsigned char *udp_packet = malloc(total_size);
    if (!udp_packet) {
        fprintf(stderr, "malloc failed: %s\n", strerror(errno));
        return -1;
    }

    unsigned int offset = 0;
    memcpy(&udp_packet[offset], &offset, sizeof(offset));
    offset += sizeof(offset);
    memcpy(&udp_packet[offset], &NUM_BUFFERS, sizeof(NUM_BUFFERS));
    offset += sizeof(NUM_BUFFERS);
    memcpy(&udp_packet[offset], &frame_size, sizeof(frame_size));
    offset += sizeof(frame_size);
    memcpy(&udp_packet[offset], frame_data, payload_size);
    offset += payload_size;

    if (sendto(sockfd, udp_packet, total_size, 0, NULL, 0) < 0) {
        fprintf(stderr, "sendto failed: %s\n", strerror(errno));
        free(udp_packet);
        return -1;
    }

    free(udp_packet);
    return 0;
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <server_ip> <server_port>\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char *server_ip = argv[1];
    int server_port = atoi(argv[2]);
    if (server_port <= 0 || server_port > 65535) {
