#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define CHIP_NAME       "gpiochip0"
#define PAN_SERVO_PIN   4
#define TILT_SERVO_PIN  5
#define BUTTON_PIN_UP   6
#define BUTTON_PIN_DOWN 7
#define BUTTON_PIN_LEFT 8
#define BUTTON_PIN_RIGHT 9

#define SERVO_MIN_PULSE  1000   /* microseconds */
#define SERVO_MAX_PULSE  2000   /* microseconds */
#define SERVO_MIN_DUTY  50
#define SERVO_MAX_DUTY  100
#define SERVO_RANGE     1000
#define SERVO_MIN_VALUE 25
#define SERVO_MAX_VALUE 125
#define SERVO_STEP      5
#define SERVO_SETTLE_MS 50
#define POLL_MS         50

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    running = 0;
}

static int set_servo(struct gpiod_line *line, int value)
{
    if (value < SERVO_MIN_VALUE || value > SERVO_MAX_VALUE) {
        fprintf(stderr, "Error: servo value %d out of range [%d, %d]\n",
                value, SERVO_MIN_VALUE, SERVO_MAX_VALUE);
        return -1;
    }

    int duty = (int)(((long)value - SERVO_MIN_VALUE) *
                     (SERVO_MAX_DUTY - SERVO_MIN_DUTY) /
                     (SERVO_MAX_VALUE - SERVO_MIN_VALUE) + SERVO_MIN_DUTY);

    if (gpiod_line_set_value(line, duty) < 0) {
        perror("gpiod_line_set_value");
        return -1;
    }
    return 0;
}

static void cleanup(struct gpiod_chip *chip,
                    struct gpiod_line *pan_line,
                    struct gpiod_line *tilt_line,
                    struct gpiod_line *btn_up,
                    struct gpiod_line *btn_down,
                    struct gpiod_line *btn_left,
                    struct gpiod_line *btn_right)
{
    if (pan_line) gpiod_line_release(pan_line);
    if (tilt_line) gpiod_line_release(tilt_line);
    if (btn_up)    gpiod_line_release(btn_up);
    if (btn_down)  gpiod_line_release(btn_down);
    if (btn_left)  gpiod_line_release(btn_left);
    if (btn_right) gpiod_line_release(btn_right);
    if (chip)     gpiod_chip_close(chip);
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *pan_line = NULL;
    struct gpiod_line *tilt_line = NULL;
    struct gpiod_line *btn_up = NULL;
    struct gpiod_line *btn_down = NULL;
    struct gpiod_line *btn_left = NULL;
    struct gpiod_line *btn_right = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    pan_line = gpiod_chip_get_line(chip, PAN_SERVO_PIN);
    tilt_line = gpiod_chip_get_line(chip, TILT_SERVO_PIN);
    btn_up = gpiod_chip_get_line(chip, BUTTON_PIN_UP);
    btn_down = gpiod_chip_get_line(chip, BUTTON_PIN_DOWN);
    btn_left = gpiod_chip_get_line(chip, BUTTON_PIN_LEFT);
    btn_right = gpiod_chip_get_line(chip, BUTTON_PIN_RIGHT);

    if (!pan_line || !tilt_line || !btn_up || !btn_down ||
        !btn_left || !btn_right) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_output(pan_line, "pan-tilt", 0) < 0 ||
        gpiod_line_request_output(tilt_line, "pan-tilt", 0) < 0) {
        perror("gpiod_line_request_output");
        goto cleanup;
    }

    if (gpiod_line_request_input_flags(btn_up, "pan-tilt",
                                       GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0 ||
        gpiod_line_request_input_flags(btn_down, "pan-tilt",
                                       GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0 ||
        gpiod_line_request_input_flags(btn_left, "pan-tilt",
                                       GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0 ||
        gpiod_line_request_input_flags(btn_right, "pan-tilt",
                                       GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
        perror("gpiod_line_request_input_flags");
        goto cleanup;
    }

