    if (set_servo(pan_line, 75) < 0 || set_servo(tilt_line, 75) < 0) {
        goto cleanup;
    }

    usleep(SERVO_SETTLE_MS * 1000);

    int pan_value = 75;
    int tilt_value = 75;

    while (running) {
        int btn_up_val = gpiod_line_get_value(btn_up);
        int btn_down_val = gpiod_line_get_value(btn_down);
        int btn_left_val = gpiod_line_get_value(btn_left);
        int btn_right_val = gpiod_line_get_value(btn_right);

        if (btn_up_val < 0 || btn_down_val < 0 ||
            btn_left_val < 0 || btn_right_val < 0) {
            perror("gpiod_line_get_value");
            break;
        }

        if (btn_up_val == 0) {
            pan_value += SERVO_STEP;
            if (pan_value > SERVO_MAX_VALUE) pan_value = SERVO_MAX_VALUE;
            if (set_servo(pan_line, pan_value) < 0) break;
            usleep(SERVO_SETTLE_MS * 1000);
        }
        if (btn_down_val == 0) {
            pan_value -= SERVO_STEP;
            if (pan_value < SERVO_MIN_VALUE) pan_value = SERVO_MIN_VALUE;
            if (set_servo(pan_line, pan_value) < 0) break;
            usleep(SERVO_SETTLE_MS * 1000);
        }
        if (btn_left_val == 0) {
            tilt_value += SERVO_STEP;
            if (tilt_value > SERVO_MAX_VALUE) tilt_value = SERVO_MAX_VALUE;
            if (set_servo(tilt_line, tilt_value) < 0) break;
            usleep(SERVO_SETTLE_MS * 1000);
        }
        if (btn_right_val == 0) {
            tilt_value -= SERVO_STEP;
            if (tilt_value < SERVO_MIN_VALUE) tilt_value = SERVO_MIN_VALUE;
            if (set_servo(tilt_line, tilt_value) < 0) break;
            usleep(SERVO_SETTLE_MS * 1000);
        }

        usleep(POLL_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    cleanup(chip, pan_line, tilt_line, btn_up, btn_down, btn_left, btn_right);
    return ret;
}

