static void print_capabilities(const struct v4l2_capability *cap)
{
    printf("Supported resolutions:\n");
    if (cap->capabilities & V4L2_CAP_VIDEO_CAPTURE) {
        printf("  - 640x480 (VGA)\n");
        printf("  - 800x600\n");
        printf("  - 1024x768\n");
        printf("  - 1280x960\n");
        printf("  - 1280x1024\n");
