        printf("  - 1920x1080\n");
        printf("  - 2048x1536\n");
        printf("  - 2560x1920\n");
        printf("  - 3840x2160\n");
    } else {
        printf("  - 640x480 (VGA)\n");
        printf("  - 800x600\n");
        printf("  - 1024x768\n");
        printf("  - 1280x960\n");
        printf("  - 1280x1024\n");
        printf("  - 1600x1200\n");
        printf("  - 1920x1080\n");
        printf("  - 2048x1536\n");
        printf("  - 2560x1920\n");
        printf("  - 3840x2160\n");
    }
    printf("\nSupported frame rates:\n");
    if (cap->capabilities & V4L2_CAP_VIDEO_CAPTURE) {
        printf("  - 30 fps\n");
        printf("  - 25 fps\n");
        printf("  - 15 fps\n");
    } else {
        printf("  - 30 fps\n");
        printf("  - 25 fps\n");
        printf("  - 15 fps\n");
    }
    printf("\nFocus autofocus support: %s\n",
           (cap->capabilities & V4L2_CAP_FOCUS_AUTO) ? "yes" : "no");
}

int main(void)
{
    int fd = -1;
    struct v4l2_capability cap;
    struct v4l2_fmtdesc fmtdesc;
    struct v4l2_frmsizeenum frmsize;
    struct v4l2_fieldfieldselector field;
    struct v4l2_streamparm parm;
    unsigned int focus_auto;
    int ret;

    /* Open the device */
    fd = open(DEVICE_NAME, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", DEVICE_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Query capabilities */
    memset(&cap, 0, sizeof(cap));
    ret = ioctl(fd, VIDIOC_QUERYCAP, &cap);
    if (ret < 0) {
        fprintf(stderr, "Error querying capabilities: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    /* Print supported resolutions */
    print_capabilities(&cap);

    /* Enumerate frame sizes */
    memset(&fmtdesc, 0, sizeof(fmtdesc));
    fmtdesc.index = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmtdesc.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmtdesc.pixel_format = V4L2_PIX_FMT_MJPEG;

    ret = ioctl(fd, VIDIOC_ENUM_FRAMESIZES, &fmtdesc);
    if (ret < 0) {
        fprintf(stderr, "Error enumerating frame sizes: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    printf("Enumerated frame sizes:\n");
    for (unsigned int i = 0; i < fmtdesc.nframesizes; i++) {
        printf("  %u x %u\n", frmsize.width, frmsize.height);
    }

    /* Enumerate frame intervals */
    memset(&field, 0, sizeof(field));
    field.index = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    field.field = V4L2_FIELD_NONE;

    ret = ioctl(fd, VIDIOC_ENUM_FRAMEINTERVALS, &field);
    if (ret < 0) {
        fprintf(stderr, "Error enumerating frame intervals: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    printf("Enumerated frame intervals:\n");
    for (unsigned int i = 0; i < field.nframeintervals; i++) {
        printf("  %u/%u\n", field.intervals[i].denominator, field.intervals[i].numerator);
    }

    /* Query focus auto control */
    memset(&cap, 0, sizeof(cap));
    ret = ioctl(fd, VIDIOC_QUERYCAP, &cap);
    if (ret < 0) {
        fprintf(stderr, "Error querying capabilities for focus control: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    memset(&cap, 0, sizeof(cap));
    ret = ioctl(fd, VIDIOC_QUERYCTRL, &cap);
    if (ret < 0) {
        fprintf(stderr, "Error querying focus control control: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    focus_auto = cap.id;
    printf("Focus autofocus control ID: %u\n", focus_auto);

    close(fd);
    return EXIT_SUCCESS;
}

