#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PAN_SERVO_PIN 4
#define TILT_SERVO_PIN 5
#define UP_BUTTON_PIN 6
#define DOWN_BUTTON_PIN 7
#define LEFT_BUTTON_PIN 8
#define RIGHT_BUTTON_PIN 9

#define SERVO_MIN_PULSE 1000
#define SERVO_MAX_PULSE 2000
#define SERVO_CENTER_PULSE 1500
#define STEP_PULSE 10
#define LOOP_DELAY_US 50000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_servo_pulse(int pin, int pulse_us) {
    if (pulse_us < SERVO_MIN_PULSE || pulse_us > SERVO_MAX_PULSE) {
        fprintf(stderr, "Error: pulse %d us out of range [%d, %d]\n",
                pulse_us, SERVO_MIN_PULSE, SERVO_MAX_PULSE);
        return -1;
    }
    if (gpioServo(pin, pulse_us) < 0) {
        fprintf(stderr, "Error: gpioServo failed on pin %d\n", pin);
        return -1;
    }
    return 0;
}

static int move_servo(int pin, int direction) {
    int pulse = gpioRead(pin);
    if (pulse < 0) {
        fprintf(stderr, "Error: gpioRead failed on pin %d\n", pin);
        return -1;
    }
    int new_pulse = pulse + direction * STEP_PULSE;
    if (new_pulse < SERVO_MIN_PULSE) new_pulse = SERVO_MIN_PULSE;
    if (new_pulse > SERVO_MAX_PULSE) new_pulse = SERVO_MAX_PULSE;
    return set_servo_pulse(pin, new_pulse);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: failed to install signal handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PAN_SERVO_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(TILT_SERVO_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(UP_BUTTON_PIN, PI_INPUT) != 0 ||
        gpioSetMode(DOWN_BUTTON_PIN, PI_INPUT) != 0 ||
        gpioSetMode(LEFT_BUTTON_PIN, PI_INPUT) != 0 ||
        gpioSetMode(RIGHT_BUTTON_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(UP_BUTTON_PIN, PI_PUD_UP) != 0 ||
        gpioSetPullUpDown(DOWN_BUTTON_PIN, PI_PUD_UP) != 0 ||
        gpioSetPullUpDown(LEFT_BUTTON_PIN, PI_PUD_UP) != 0 ||
        gpioSetPullUpDown(RIGHT_BUTTON_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (set_servo_pulse(PAN_SERVO_PIN, SERVO_CENTER_PULSE) != 0 ||
        set_servo_pulse(TILT_SERVO_PIN, SERVO_CENTER_PULSE) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Pan-tilt camera control started.\n");
    printf("Pan servo: GPIO%d | Tilt servo: GPIO%d | UP: GPIO%d | DOWN: GPIO%d | LEFT: GPIO%d | RIGHT: GPIO%d\n",
           PAN_SERVO_PIN, TILT_SERVO_PIN, UP_BUTTON_PIN, DOWN_BUTTON_PIN, LEFT_BUTTON_PIN, RIGHT_BUTTON_PIN);
    printf("Center position: %d us. Press Ctrl+C to exit.\n", SERVO_CENTER_PULSE);

    while (running) {
        int up = gpioRead(UP_BUTTON_PIN);
        int down = gpioRead(DOWN_BUTTON_PIN);
        int left = gpioRead(LEFT_BUTTON_PIN);
        int right = gpioRead(RIGHT_BUTTON_PIN);

        if (up == 0) {
            if (move_servo(PAN_SERVO_PIN, 1) == 0) {
                gpioDelay(LOOP_DELAY_US);
            }
        }
        if (down == 0) {
            if (move_servo(PAN_SERVO_PIN, -1) == 0) {
                gpioDelay(LOOP_DELAY_US);
            }
        }
        if (left == 0) {
            if (move_servo(TILT_SERVO_PIN, 1) == 0) {
                gpioDelay(LOOP_DELAY_US);
            }
        }
        if (right == 0) {
            if (move_servo(TILT_SERVO_PIN, -1) == 0) {
                gpioDelay(LOOP_DELAY_US);
            }
        }
    }

    gpioServo(PAN_SERVO_PIN, 0);
    gpioServo(TILT_SERVO_PIN, 0);
    gpioTerminate();
    printf("\nClean shutdown complete.\n");
    return EXIT_SUCCESS;
}

