#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>
#include <curl/curl.h>

#define PIR_GPIO 17
#define DEBOUNCE_SEC 2
#define POLL_INTERVAL_US 100000
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define IMAGE_QUALITY 85
#define CAPTURE_DIR "motion_captures"
#define MAX_FILENAME_LEN 512
#define MAX_PAYLOAD_LEN 1024

static volatile sig_atomic_t g_running = 1;
static int g_server_port = 0;
static char g_server_ip[64] = "127.0.0.1";

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int ensure_directory(const char *path) {
    struct stat st;
    if (stat(path, &st) == 0) {
        if (S_ISDIR(st.st_mode)) return 0;
        fprintf(stderr, "Error: '%s' exists but is not a directory\n", path);
        return -1;
    }
    if (mkdir(path, 0755) != 0 && errno != EEXIST) {
        fprintf(stderr, "Error: cannot create directory '%s': %s\n", path, strerror(errno));
        return -1;
    }
    return 0;
}

static int capture_image(const char *filename) {
    char command[1024];
    snprintf(command, sizeof(command),
             "libcamera-still -o %s --width %d --height %d --quality %d 2>/dev/null",
             filename, IMAGE_WIDTH, IMAGE_HEIGHT, IMAGE_QUALITY);

    int status = system(command);
    if (status == -1) {
        fprintf(stderr, "Error: system() failed to launch libcamera-still: %s\n", strerror(errno));
        return -1;
    }
    if (!WIFEXITED(status) || WEXITSTATUS(status) != 0) {
        fprintf(stderr, "Error: libcamera-still failed (status=%d)\n", status);
        return -1;
    }
    return 0;
}

