#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define PIR_PIN 17
#define IMAGE_DIR "/home/pi/images"
#define LOG_FILE "/home/pi/motion_capture.log"
#define DEBOUNCE_MS 50
#define POLL_INTERVAL_US 100000

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    } else {
        fprintf(fp, "[timestamp error] %s\n", message);
    }
    fclose(fp);
}

static int capture_image(const char *filename) {
    char command[512];
    int ret = snprintf(command, sizeof(command),
                       "libcamera-still -o '%s' --width 640 --height 480 -q 85 --timeout 2000 --nopreview 2>/dev/null",
                       filename);
    if (ret < 0 || (size_t)ret >= sizeof(command)) {
        fprintf(stderr, "Error: command buffer too small\n");
        return -1;
    }
    int status = system(command);
    if (status == -1) {
        fprintf(stderr, "Error: system() failed: %s\n", strerror(errno));
        return -1;
    }
    if (WIFEXITED(status) && WEXITSTATUS(status) != 0) {
        fprintf(stderr, "Error: libcamera-still failed with status %d\n", WEXITSTATUS(status));
        return -1;
    }
    if (WIFSIGNALED(status)) {
        fprintf(stderr, "Error: libcamera-still killed by signal %d\n", WTERMSIG(status));
        return -1;
    }
    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *pir_line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Error: sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Error: sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Error: gpiod_chip_open_by_name(%s) failed: %s\n",
                GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    pir_line = gpiod_chip_get_line(chip, PIR_PIN);
    if (!pir_line) {
        fprintf(stderr, "Error: gpiod_chip_get_line(%d) failed: %s\n",
                PIR_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_falling_edge_events(pir_line, "pir-motion-capture") < 0) {
        fprintf(stderr, "Error: gpiod_line_request_falling_edge_events failed: %s\n",
                strerror(errno));
        goto cleanup;
    }

    printf("Motion detection started on GPIO%d. Press Ctrl+C to exit.\n", PIR_PIN);

    while (program_running) {
        struct timespec ts = {0, POLL_INTERVAL_US * 1000};
        int ev = gpiod_line_event_wait(pir_line, &ts);
        if (ev < 0) {
            if (errno == EINTR) {
                continue;
            }
            fprintf(stderr, "Error: gpiod_line_event_wait failed: %s\n", strerror(errno));
            break;
        }
        if (ev == 0) {
            continue;
        }

        struct gpiod_line_event event;
        if (gpiod_line_event_read(pir_line, &event) < 0) {
            fprintf(stderr, "Error: gpiod_line_event_read failed: %s\n", strerror(errno));
            continue;
        }

        if (event.event_type == GPIOD_LINE_EVENT_FALLING_EDGE) {
            struct timespec debounce_ts = {0, DEBOUNCE_MS * 1000000};
            int waited = 0;
            while (program_running) {
                int ev2 = gpiod_line_event_wait(pir_line, &debounce_ts);
                if (ev2 < 0) {
                    if (errno == EINTR) {
                        continue;
                    }
                    fprintf(stderr, "Error: gpiod_line_event_wait (debounce) failed: %s\n",
                            strerror(errno));
                    goto cleanup;
                }
                if (ev2 == 0) {
                    break;
                }
                if (ev2 == GPIOD_LINE_EVENT_FALLING_EDGE) {
                    break;
                }
                usleep(10000);
                waited += 10;
            }

            if (waited == 0) {
                continue;
            }

            time_t rawtime = time(NULL);
            struct tm tm;
            if (localtime_r(&rawtime, &tm) == NULL) {
                fprintf(stderr, "Error: localtime_r failed\n");
                continue;
            }

            char filename[64];
            int n = snprintf(filename, sizeof(filename), "%04d%02d%02d_%02d%02d%02d_mmm.jpg",
                             tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                             tm.tm_hour, tm.tm_min, tm.tm_sec);
            if (n < 0 || (size_t)n >= sizeof(filename)) {
                fprintf(stderr, "Error: filename buffer too small\n");
                continue;
            }

            if (capture_image(filename) == 0) {
                printf("Image captured: %s\n", filename);
                log_event(filename);
            } else {
                fprintf(stderr, "Error: image capture failed\n");
                log_event("Error: image capture failed");
            }
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (pir_line) {
        gpiod_line_release(pir_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    printf("Exiting.\n");
    return ret;
}

