#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <linux/videodev2.h>

#define DEVICE_NAME "/dev/video0"
#define OUTPUT_FILE "cropped.yuv"
#define WIDTH 640
#define HEIGHT 480
#define X_OFFSET 100
#define Y_OFFSET 50
#define CROP_WIDTH 200
#define CROP_HEIGHT 150
#define FRAME_TIMEOUT_SEC 2

static volatile sig_atomic_t g_stop = 0;

static void sig_handler(int sig) {
    (void)sig;
    g_stop = 1;
}

static int xioctl(int fd, unsigned long request, void *arg) {
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

static int capture_frame(int fd, unsigned char **frame, size_t *frame_size) {
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_DQBUF, &buf) == -1) {
        perror("VIDIOC_DQBUF");
        return -1;
    }

    if (buf.index >= 0) {
        *frame = (unsigned char *)buf.m.offset;
        *frame_size = buf.length;
    } else {
        fprintf(stderr, "No more frames available\n");
        return -1;
    }

    if (xioctl(fd, VIDIOC_QBUF, &buf) == -1) {
        perror("VIDIOC_QBUF");
        return -1;
    }
    return 0;
}

static int save_cropped_frame(const unsigned char *frame, size_t frame_size,
                              const char *output_file) {
    FILE *fp = fopen(output_file, "wb");
    if (!fp) {
        perror("fopen");
        return -1;
    }

    size_t written = fwrite(frame, 1, frame_size, fp);
    if (written != frame_size) {
        fprintf(stderr, "Short write: %zu/%zu\n", written, frame_size);
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("fclose");
        return -1;
    }
    return 0;
}

int main(void) {
    int fd = -1;
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    unsigned char *frame = NULL;
    size_t frame_size = 0;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction SIGINT");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction SIGTERM");
        return EXIT_FAILURE;
    }

    fd = open(DEVICE_NAME, O_RDWR | O_NONBLOCK, 0);
    if (fd == -1) {
        perror("open");
        return EXIT_FAILURE;
    }

    if (xioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        perror("VIDIOC_QUERYCAP");
        goto cleanup;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is not a video capture device\n", DEVICE_NAME);
        goto cleanup;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming I/O\n", DEVICE_NAME);
        goto cleanup;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = WIDTH;
    fmt.fmt.pix.height = HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (xioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        perror("VIDIOC_S_FMT");
        goto cleanup;
    }

    if (fmt.fmt.pix.pixelformat != V4L2_PIX_FMT_YUYV) {
        fprintf(stderr, "Device does not support YUYV format\n");
        goto cleanup;
    }

    memset(&req, 0, sizeof(req));
    req.count = 1;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_REQBUFS, &req) == -1) {
        perror("VIDIOC_REQBUFS");
        goto cleanup;
    }

    if (req.count < 1) {
        fprintf(stderr, "Insufficient buffer memory\n");
        goto cleanup;
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (xioctl(fd, VIDIOC_QUERYBUF, &buf) == -1) {
        perror("VIDIOC_QUERYBUF");
        goto cleanup;
    }

    frame = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (frame == MAP_FAILED) {
        perror("mmap");
        frame = NULL;
        goto cleanup;
    }

    if (xioctl(fd, VIDIOC_QBUF, &buf) == -1) {
        perror("VIDIOC_QBUF");
        frame = NULL;
        goto cleanup;
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMON, &type) == -1) {
        perror("VIDIOC_STREAMON");
        frame = NULL;
        goto cleanup;
    }

    printf("Waiting for frame...\n");
    int waited = 0;
    while (!g_stop && waited < FRAME_TIMEOUT_SEC * 10) {
        struct timeval tv = { .tv_sec = FRAME_TIMEOUT_SEC, .tv_usec = 0 };
        int r = select(0, &tv, NULL, NULL, NULL);
        if (r == -1) {
            if (errno == EINTR) continue;
            perror("select");
            goto cleanup;
        }
        if (r == 0) {
            fprintf(stderr, "Timeout waiting for frame\n");
            goto cleanup;
        }
        waited++;
    }

    if (g_stop) {
        fprintf(stderr, "Interrupted\n");
        goto cleanup;
    }

    if (capture_frame(fd, &frame, &frame_size) == -1) {
        fprintf(stderr, "Failed to capture frame\n");
        goto cleanup;
    }

    if (frame_size != (size_t)WIDTH * HEIGHT * 2) {
        fprintf(stderr, "Unexpected frame size: %zu\n", frame_size);
        goto cleanup;
    }

    unsigned char *cropped = malloc(CROP_WIDTH * CROP_HEIGHT * 2);
    if (!cropped) {
        perror("malloc");
        goto cleanup;
    }

    for (int y = 0; y < CROP_HEIGHT; y++) {
        for (int x = 0; x < CROP_WIDTH; x++) {
            int idx = ((y + Y_OFFSET) * WIDTH + (x + X_OFFSET)) * 2;
            if (idx + 2 >= (int)frame_size) {
                fprintf(stderr, "Out of bounds: %d %d\n", x, y);
                free(cropped);
                goto cleanup;
            }
            cropped[(y * CROP_WIDTH + x) * 2] = frame[idx];
            cropped[(y * CROP_WIDTH + x) * 2 + 1] = frame[idx + 1];
        }
    }

    if (save_cropped_frame(cropped, CROP_WIDTH * CROP_HEIGHT * 2, OUTPUT_FILE) == -1) {
        fprintf(stderr, "Failed to save cropped frame\n");
        free(cropped);
        goto cleanup;
    }

    printf("Cropped frame saved to %s\n", OUTPUT_FILE);
    ret = EXIT_SUCCESS;

cleanup:
    if (frame) munmap(frame, buf.length);
    if (fd >= 0) close(fd);
    free(cropped);
    return ret;
}

