int set_servo_angle(int pin, int angle) {
    if (angle < 0 || angle > 180) {
        fprintf(stderr, "Error: Angle %d out of range (0-180)\n", angle);
        return -1;
    }
    int pulse = MIN_PULSE + (angle * (MAX_PULSE - MIN_PULSE) / 180);
    if (gpioServo(pin, pulse) != 0) {
        fprintf(stderr, "Error: gpioServo failed on pin %d\n", pin);
        return -1;
    }
    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int pan_angle = 90;
    int tilt_angle = 90;

    while (running) {
        printf("Pan: %3d  Tilt: %3d\n", pan_angle, tilt_angle);
        fflush(stdout);

        char input;
        if (scanf(" %c", &input) != 1) {
            if (input == 'q' || input == 'Q') {
                running = 0;
            } else {
                input = '\n';
            }
            break;
        }

        switch (input) {
            case 'w': pan_angle += ANGLE_STEP; break;
            case 's': pan_angle -= ANGLE_STEP; break;
            case 'a': tilt_angle += ANGLE_STEP; break;
            case 'd': tilt_angle -= ANGLE_STEP; break;
            case '\n': break;
            default:
                printf("Invalid input, use w, a, s, d, or q\n");
                break;
        }

        if (set_servo_angle(PAN_SERVO_PIN, pan_angle) != 0) {
            fprintf(stderr, "Error: Failed to set pan servo\n");
        }
        if (set_servo_angle(TILT_SERVO_PIN, tilt_angle) != 0) {
            fprintf(stderr, "Error: Failed to set tilt servo\n");
        }
        gpioDelay(DELAY_MS * 1000);
    }

    set_servo_angle(PAN_SERVO_PIN, 90);
    set_servo_angle(TILT_SERVO_PIN, 90);
    gpioServo(PAN_SERVO_PIN, 0);
    gpioServo(TILT_SERVO_PIN, 0);
    gpioTerminate();
    printf("\nClean exit.\n");
    return 0;
}

