#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

#define FLOW_SENSOR_GPIO 17
#define LCD_I2C_ADDR 0x27
#define LCD_WIDTH 16
#define LCD_CHR 1
#define LCD_CMD 0
#define LCD_LINE_1 0x80
#define LCD_LINE_2 0xC0
#define LCD_BACKLIGHT 0x08
#define LCD_ENABLE 0x04
#define LCD_RW 0x02
#define LCD_RS 0x01

#define PULSES_PER_LITER 450.0
#define I2C_BUS 1

static volatile sig_atomic_t running = 1;
static volatile uint32_t pulse_count = 0;
static double total_volume = 0.0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void pulse_callback(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio; (void)tick; (void)userdata;
    if (level == 1) {
        pulse_count++;
    }
}

static int lcd_write_nibble(int handle, uint8_t nibble, uint8_t mode) {
    uint8_t data = nibble | mode | LCD_BACKLIGHT;
    if (i2cWriteByteData(handle, 0x00, data) < 0) {
        return -1;
    }
    gpioDelay(2000);
    if (i2cWriteByteData(handle, 0x00, (nibble << 4) | mode | LCD_BACKLIGHT) < 0) {
        return -1;
    }
    gpioDelay(2000);
    return 0;
}

static int lcd_send_byte(int handle, uint8_t val, uint8_t mode) {
    if (lcd_write_nibble(handle, val & 0xF0, mode) < 0) return -1;
    if (lcd_write_nibble(handle, (val << 4) & 0xF0, mode) < 0) return -1;
    return 0;
}

static int lcd_command(int handle, uint8_t val) {
    return lcd_send_byte(handle, val, LCD_CMD);
}

static int lcd_data(int handle, uint8_t val) {
    return lcd_send_byte(handle, val, LCD_CHR);
}

static int lcd_init(int handle) {
    gpioDelay(50000);
    if (lcd_write_nibble(handle, 0x30, 0) < 0) return -1;
    gpioDelay(4500);
    if (lcd_write_nibble(handle, 0x30, 0) < 0) return -1;
    gpioDelay(150);
