#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>

#define LCD_I2C_ADDR 0x27
#define LCD_WIDTH 16
#define LCD_CH0 0
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define ANEMOMETER_GPIO 17
#define SAMPLE_INTERVAL_US 500000

static volatile int pulse_count = 0;
static volatile int running = 1;
static int i2c_handle = -1;
static int spi_handle = -1;

static void pulse_callback(int gpio, int level, uint32_t tick) {
    (void)gpio; (void)level; (void)tick;
    pulse_count++;
}

static int lcd_write_nibble(uint8_t nibble, uint8_t rs) {
    uint8_t data = (nibble & 0xF0) | (rs ? 0x04 : 0x00);
    if (i2cWriteByte(i2c_handle, data) < 0) {
        fprintf(stderr, "I2C write failed (nibble 0x%02X)\n", nibble);
        return -1;
    }
    if (i2cWriteByte(i2c_handle, (nibble << 4) | (rs ? 0x04 : 0x00)) < 0) {
        fprintf(stderr, "I2C write failed (nibble 0x%02X)\n", nibble);
        return -1;
    }
    return 0;
}

static int lcd_send_byte(uint8_t val, uint8_t rs) {
    if (lcd_write_nibble(val >> 4, rs) < 0) return -1;
    if (lcd_write_nibble(val & 0x0F, rs) < 0) return -1;
    return 0;
}

static int lcd_command(uint8_t cmd) {
    if (lcd_send_byte(cmd, 0) < 0) return -1;
    gpioDelay(2000);
    return 0;
}

static int lcd_data(uint8_t data) {
    if (lcd_send_byte(data, 1) < 0) return -1;
    gpioDelay(2000);
    return 0;
}

static int lcd_init(void) {
    gpioDelay(50000);
    if (lcd_command(0x33) < 0) return -1;
    if (lcd_command(0x32) < 0) return -1;
    if (lcd_command(0x28) < 0) return -1;
    if (lcd_command(0x0C) < 0) return -1;
    if (lcd_command(0x06) < 0) return -1;
    if (lcd_command(0x01) < 0) return -1;
    gpioDelay(2000);
    return 0;
}

static int lcd_set_cursor(int col, int row) {
    uint8_t addr = (row == 0) ? 0x00 : 0x40;
    if (lcd_command(addr + col) < 0) return -1;
    return 0;
}

static int lcd_print(const char *str) {
    for (int i = 0; str[i] != '\0' && i < LCD_WIDTH; i++) {
        if (lcd_data((uint8_t)str[i]) < 0) return -1;
    }
    return 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) return -1;
    uint8_t tx[3] = {0x01, (uint8_t)((channel & 0x07) << 4 | 0x80), 0x00};
    uint8_t rx[3] = {0};
    if (spiXfer(spi_handle, (char *)tx, (char *)rx, 3) < 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }
    return ((rx[1] & 0x03) << 8) | rx[2];
}

static void update_display(float wind_speed) {
    char line1[LCD_WIDTH + 1];
    char line2[LCD_WIDTH + 1];
    snprintf(line1, sizeof(line1), "Speed: %.1f m/s", wind_speed);
    snprintf(line2, sizeof(line2), "Dir: 0 deg");
    lcd_set_cursor(0, 0);
    if (lcd_print(line1) < 0) fprintf(stderr, "Failed to print line 1\n");
    lcd_set_cursor(0, 1);
    if (lcd_print(line2) < 0) fprintf(stderr, "Failed to print line 2\n");
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioTerminate();
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, LCD_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X\n", LCD_I2C_ADDR);
        gpioTerminate();
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI device\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (lcd_init() < 0) {
        fprintf(stderr, "LCD initialization failed\n");
        cleanup();
        return 1;
    }

    if (gpioSetMode(ANEMOMETER_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", ANEMOMETER_GPIO);
        cleanup();
        return 1;
    }
    gpioSetPullUpDown(ANEMOMETER_GPIO, PI_PUD_UP);

    if (gpioSetISRFuncEx(ANEMOMETER_GPIO, RISING_EDGE, 0, pulse_callback, NULL) < 0) {
        fprintf(stderr, "Failed to set ISR for GPIO %d\n", ANEMOMETER_GPIO);
        cleanup();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int pulse_count_prev = 0;
    int consecutive_errors = 0;

    while (running) {
        gpioDelay(SAMPLE_INTERVAL_US);
        int current_pulses = pulse_count;
        pulse_count = 0;

        int pulses_delta = current_pulses - pulse_count_prev;
        float wind_speed = (float)pulses_delta * 0.5f;

        update_display(wind_speed);

        int adc_value = read_mcp3008(LCD_CH0);
        if (adc_value < 0) {
            consecutive_errors++;
            fprintf(stderr, "ADC read error (consecutive: %d)\n", consecutive_errors);
            if (consecutive_errors >= 10) {
                fprintf(stderr, "Too many consecutive ADC errors, aborting\n");
                break;
            }
        } else {
            consecutive_errors = 0;
            int valid = 1;
            if (adc_value == 0 || adc_value == 1023) {
                fprintf(stderr, "Warning: ADC reading at rail (%d)\n", adc_value);
                valid = 0;
            }
            if (valid) {
                int degrees = (adc_value * 359) / 1023;
                char dir_str[16];
                snprintf(dir_str, sizeof(dir_str), "Dir: %d deg", degrees);
                lcd_set_cursor(0, 1);
                if (lcd_print(dir_str) < 0) fprintf(stderr, "Failed to print direction\n");
            }
        }

        pulse_count_prev = current_pulses;
    }

    cleanup();
    return 0;
}

