/*
 * VL53L3CX Time-of-Flight Sensor Interface for Raspberry Pi 3 Model B+
 * Uses pigpio for I2C communication.
 *
 * NOTE: The VL53L3CX requires a proprietary firmware download (ST Ultra Lite Driver) to initialize.
 * This stub demonstrates the I2C protocol and error handling. To use the sensor, download the
 * ST Ultra Lite Driver from the ST website, configure it for the VL53L3CX, and link it with
 * this C program. The ULD will perform the sensor initialization sequence.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

#define I2C_BUS 1
#define VL53L3CX_ADDR 0x29

/* VL53L3CX ULD Register Addresses (Stubbed - ULD fills these) */
#define VL53L3CX_REG_IDENTIFICATION_MODEL_ID 0x010F
#define VL53L3CX_REG_SYSTEM_MODE_START 0x0000
#define VL53L3CX_REG_SYSTEM_INTERRUPT_CLEAR 0x0001
#define VL53L3CX_REG_SYSTEM_INTERRUPT_STATUS 0x0002
#define VL53L3CX_REG_RESULT_RANGE_STATUS 0x0089
#define VL53L3CX_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0096

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

int i2c_write_reg16(int handle, uint16_t reg, uint16_t value) {
    char buf[4];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = (value >> 8) & 0xFF;
    buf[3] = value & 0xFF;
    return i2cWriteDevice(handle, buf, 4);
}

int i2c_read_reg16(int handle, uint16_t reg, uint16_t *value) {
    char buf[2];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, buf, 2) != 0) return -1;
    if (i2cReadDevice(handle, buf, 2) != 2) return -1;
    *value = (buf[0] << 8) | buf[1];
    return 0;
}

int vl53l3cx_init(int handle) {
    uint16_t model_id = 0;
    if (i2c_read_reg16(handle, VL53L3CX_REG_IDENTIFICATION_MODEL_ID, &model_id) != 0) {
        fprintf(stderr, "Error: Failed to read model ID from sensor.\n");
        return -1;
    }
    if (model_id != 0xEA) {
        fprintf(stderr, "Error: Invalid model ID 0x%04X. Expected 0xEA.\n", model_id);
        return -1;
    }
    printf("VL53L3CX detected (Model ID: 0x%04X).\n", model_id);

    /* Stub ULD initialization sequence - ULD fills these registers */
    if (i2c_write_reg16(handle, 0x0000, 0x0001) != 0) return -1;
