#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SI1145_ADDR    0x60
#define LOG_FILE       "biometric_log.txt"
#define SAMPLE_US      500000  /* 500 ms */

/* Si1145 register addresses */
#define REG_PART_ID    0x00
#define REG_HW_KEY     0x07
#define REG_MEAS_RATE0 0x08
#define REG_MEAS_RATE1 0x09
#define REG_IRQ_ENABLE 0x0F
#define REG_IRQ_STATUS 0x21
#define REG_ALS_VIS_DATA0 0x22
#define REG_ALS_VIS_DATA1 0x23
#define REG_PS1_DATA0    0x25
#define REG_PS1_DATA1    0x26

#define EXPECTED_PART_ID 0x45
#define HW_KEY_VAL       0x17

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int write_reg(uint8_t reg, uint8_t val)
{
    int rc = i2cWriteByteData(g_i2c_handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed: reg=0x%02X, val=0x%02X, rc=%d\n",
                reg, val, rc);
        return -1;
    }
    return 0;
}

static int read_reg(uint8_t reg, uint8_t *val)
{
    int rc = i2cReadByteData(g_i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed: reg=0x%02X, rc=%d\n", reg, rc);
        return -1;
    }
    *val = (uint8_t)rc;
    return 0;
}

static int init_si1145(void)
{
    uint8_t part_id = 0;

    /* Verify PART_ID so we know the sensor is present */
    if (read_reg(REG_PART_ID, &part_id) != 0) {
        fprintf(stderr, "Cannot read PART_ID — sensor absent or bus error\n");
        return -1;
    }
    if (part_id != EXPECTED_PART_ID) {
        fprintf(stderr, "Unexpected PART_ID 0x%02X (expected 0x%02X)\n",
                part_id, EXPECTED_PART_ID);
        return -1;
    }
    printf("Si1145 detected (PART_ID=0x%02X)\n", part_id);

    /* Write HW_KEY to enable the device */
    if (write_reg(REG_HW_KEY, HW_KEY_VAL) != 0)
        return -1;

    /* Set measurement rates: 0x0A = 1 sample/sec for ALS and PS */
    if (write_reg(REG_MEAS_RATE0, 0x0A) != 0)
        return -1;
    if (write_reg(REG_MEAS_RATE1, 0x00) != 0)
        return -1;

    /* Clear any stale IRQ by writing 0x01 to IRQ_ENABLE */
    if (write_reg(REG_IRQ_ENABLE, 0x01) != 0)
        return -1;

    return 0;
}

static int read_proximity(uint16_t *prox)
{
    uint8_t lo, hi;
    if (read_reg(REG_PS1_DATA0, &lo) != 0)
        return -1;
    if (read_reg(REG_PS1_DATA1, &hi) != 0)
        return -1;
    *prox = (uint16_t)((hi << 8) | lo);
    return 0;
}

static int read_ambient_light(uint16_t *light)
{
    uint8_t lo, hi;
    if (read_reg(REG_ALS_VIS_DATA0, &lo) != 0)
        return -1;
    if (read_reg(REG_ALS_VIS_DATA1, &hi) != 0)
        return -1;
    *light = (uint16_t)((hi << 8) | lo);
    return 0;
}

static void log_data(uint16_t prox, uint16_t light)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    if (g_log_file) {
        fprintf(g_log_file, "%s, Proximity: %u, Ambient Light: %u\n",
                ts, prox, light);
        fflush(g_log_file);
    }
}

static void log_error(const char *msg)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    fprintf(stderr, "%s, ERROR: %s\n", ts, msg);
    if (g_log_file) {
        fprintf(g_log_file, "%s, ERROR: %s\n", ts, msg);
        fflush(g_log_file);
    }
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, SI1145_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed: %d\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_si1145() != 0) {
        fprintf(stderr, "Si1145 initialization failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        perror("fopen log");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Logging to %s — press Ctrl+C to stop\n", LOG_FILE);

    while (g_running) {
        uint16_t prox = 0, light = 0;
        int prox_ok = read_proximity(&prox);
        int light_ok = read_ambient_light(&light);

        if (prox_ok == 0 && light_ok == 0) {
            log_data(prox, light);
        } else if (prox_ok != 0) {
            log_error("Proximity read failed");
        } else {
            log_error("Ambient light read failed");
        }

        gpioDelay(SAMPLE_US);
    }

    printf("\nShutting down...\n");
    if (g_log_file) {
        fflush(g_log_file);
        fclose(g_log_file);
    }
    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

