/*
 * HC-SR04 Proximity Watering Reminder — Raspberry Pi Zero W
 * Trigger: GPIO 17 (BCM), Echo: GPIO 27 (BCM) via 5V->3.3V divider
 * Build: gcc -O2 -Wall -o watering watering.c -lgpiod
 */
#define _POSIX_C_SOURCE 200809L
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define TRIGGER_PIN  17
#define ECHO_PIN     27
#define LOG_FILE     "distance_log.txt"
#define TIMEOUT_SEC  30
#define POLL_SEC     60
#define MIN_CM       2
#define MAX_CM       400
#define WATER_THRESHOLD_CM 15
#define TRIGGER_US   10
#define SOUND_CM_US  0.0343

static volatile sig_atomic_t g_running = 1;

static void sighandler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void timestamp_str(char *buf, size_t len)
{
    time_t t = time(NULL);
    struct tm tmv;
    if (localtime_r(&t, &tmv))
        strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &tmv);
    else
        snprintf(buf, len, "1970-01-01T00:00:00");
}

static void log_line(FILE *fp, const char *msg)
{
    char ts[32];
    timestamp_str(ts, sizeof ts);
    fprintf(fp, "%s %s\n", ts, msg);
    fflush(fp);
}

static void log_distance(FILE *fp, int distance_cm)
{
    char ts[32];
    timestamp_str(ts, sizeof ts);
    fprintf(fp, "%s Distance: %d cm\n", ts, distance_cm);
    fflush(fp);
}

static void log_watering(FILE *fp)
{
    char ts[32];
    timestamp_str(ts, sizeof ts);
    fprintf(fp, "%s Time to water the plant!\n", ts);
    fflush(fp);
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL, *echo = NULL;
    FILE *log = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof sa);
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "gpiod_chip_open: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!trig || !echo) {
        fprintf(stderr, "gpiod_chip_get_line: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(trig, "hc-sr04-trig", 0) < 0) {
        fprintf(stderr, "request_output trig: %s\n", strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_input(echo, "hc-sr04-echo") < 0) {
        fprintf(stderr, "request_input echo: %s\n", strerror(errno));
        goto cleanup;
    }

    log = fopen(LOG_FILE, "a");
    if (!log) {
        fprintf(stderr, "fopen(%s): %s\n", LOG_FILE, strerror(errno));
        goto cleanup;
    }

    printf("HC-SR04 watering system started. Ctrl+C to exit.\n");

    while (g_running) {
        /* Ensure trigger is low */
        if (gpiod_line_set_value(trig, 0) < 0) {
            fprintf(stderr, "set trig low: %s\n", strerror(errno));
            break;
        }
        usleep(5);

        /* 10 us trigger pulse */
        if (gpiod_line_set_value(trig, 1) < 0) {
            fprintf(stderr, "set trig high: %s\n", strerror(errno));
            break;
        }
        usleep(TRIGGER_US);
        if (gpiod_line_set_value(trig, 0) < 0) {
            fprintf(stderr, "set trig low: %s\n", strerror(errno));
            break;
        }

        struct timespec t0, t1;
        clock_gettime(CLOCK_MONOTONIC, &t0);

        /* Wait for echo rising edge (timeout) */
        int waited = 0;
        while (g_running) {
            int v = gpiod_line_get_value(echo);
            if (v < 0) {
                fprintf(stderr, "read echo: %s\n", strerror(errno));
                goto cleanup;
            }
            if (v == 1) break;
            if (waited++ > TIMEOUT_SEC) {
                log_line(log, "Timeout: echo never rose (sensor absent?)");
                break;
            }
            usleep(100);
        }
        if (!g_running) break;

        clock_gettime(CLOCK_MONOTONIC, &t0);

        /* Wait for echo falling edge (timeout) */
        waited = 0;
        while (g_running) {
            int v = gpiod_line_get_value(echo);
            if (v < 0) {
                fprintf(stderr, "read echo: %s\n", strerror(errno));
                goto cleanup;
            }
            if (v == 0) break;
            if (waited++ > TIMEOUT_SEC) {
                log_line(log, "Timeout: echo stuck high (sensor error?)");
                break;
            }
            usleep(100);
        }
        if (!g_running) break;

        clock_gettime(CLOCK_MONOTONIC, &t1);

        double pulse_us = (t1.tv_sec - t0.tv_sec) * 1000000.0 +
                          (t1.tv_nsec - t0.tv_nsec) / 1000.0;
        double distance_cm = (pulse_us * SOUND_CM_US) / 2.0;

        if (distance_cm < MIN_CM || distance_cm > MAX_CM) {
            log_line(log, "Out of range: distance = %.2f cm", distance_cm);
        } else {
            log_distance(log, (int)distance_cm);
            if (distance_cm < WATER_THRESHOLD_CM)
                log_watering(log);
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (log) fclose(log);
    if (trig) gpiod_line_release(trig);
    if (echo) gpiod_line_release(echo);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

