#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define APDS9960_I2C_ADDR 0x39
#define APDS9960_ENABLE 0x80
#define APDS9960_ATIME 0x81
#define APDS9960_WTIME 0x83
#define APDS9960_PPULSE 0x8E
#define APDS9960_CONTROL 0xF1
#define APDS9960_CONFIG2 0x90
#define APDS9960_ID 0x92
#define APDS9960_STATUS 0x93
#define APDS9960_CDATAL 0x96
#define APDS9960_CDATAH 0x97
#define APDS9960_RDATAL 0x98
#define APDS9960_RDATAH 0x99
#define APDS9960_GDATAL 0x9A
#define APDS9960_GDATAH 0x9B
#define APDS9960_PDATA 0x9C

#define APDS9960_ID_VALUE 0xAB
#define PROXIMITY_THRESHOLD 200
#define LOG_FILE "color_proximity_log.csv"

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int i2c_write_reg(uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(i2c_handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing reg 0x%02X: %d\n", reg, rc);
    }
    return rc;
}

static int i2c_read_reg16(uint8_t reg, uint16_t *value) {
    int rc = i2cReadWordData(i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading reg 0x%02X: %d\n", reg, rc);
        return -1;
    }
    *value = (uint16_t)rc;
    return 0;
}

static int initialize_apds9960(void) {
    if (i2c_write_reg(APDS9960_ENABLE, 0x00) < 0) return -1;
    gpioDelay(10000);

    if (i2c_write_reg(APDS9960_ATIME, 0xDB) < 0) return -1;
    if (i2c_write_reg(APDS9960_WTIME, 0xF6) < 0) return -1;
    if (i2c_write_reg(APDS9960_PPULSE, 0x87) < 0) return -1;
    if (i2c_write_reg(APDS9960_CONTROL, 0x03) < 0) return -1;
    if (i2c_write_reg(APDS9960_CONFIG2, 0x01) < 0) return -1;

    if (i2c_write_reg(APDS9960_ENABLE, 0x03) < 0) return -1;
    gpioDelay(10000);

    uint8_t id = i2cReadByteData(i2c_handle, APDS9960_ID);
    if (id != APDS9960_ID_VALUE) {
        fprintf(stderr, "Sensor ID mismatch: 0x%02X (expected 0x%02X)\n", id, APDS9960_ID_VALUE);
        return -1;
    }

    return 0;
}

static int read_color_data(uint16_t *red, uint16_t *green, uint16_t *blue, uint8_t *proximity) {
    if (i2c_read_reg16(APDS9960_CDATAL, red) < 0) return -1;
    if (i2c_read_reg16(APDS9960_RDATAL, green) < 0) return -1;
    if (i2c_read_reg16(APDS9960_GDATAL, blue) < 0) return -1;
    if (i2c_read_reg8(APDS9960_PDATA, proximity) < 0) return -1;
    return 0;
}

static void log_data(uint16_t red, uint16_t green, uint16_t blue, uint8_t proximity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (proximity > PROXIMITY_THRESHOLD) {
        fprintf(log_file, "%s,%u,%u,%u,%u\n", timestamp, red, green, blue, proximity);
        fflush(log_file);
    }
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, APDS9960_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (initialize_apds9960() < 0) {
        fprintf(stderr, "APDS9960 initialisation failed\n");
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        cleanup();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    uint16_t red, green, blue;
    uint8_t proximity;

    while (!terminate) {
        if (read_color_data(&red, &green, &blue, &proximity) == 0) {
            log_data(red, green, blue, proximity);
        } else {
            fprintf(stderr, "I2C read error, re-initializing sensor...\n");
            i2cClose(i2c_handle);
            i2c_handle = -1;
            gpioDelay(100000);
            i2c_handle = i2cOpen(1, APDS9960_I2C_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error re-opening I2C bus: %d\n", i2c_handle);
                continue;
            }
            if (initialize_apds9960() < 0) {
                fprintf(stderr, "APDS9960 re-initialisation failed\n");
                continue;
            }
        }
        gpioDelay(100000);
    }

    cleanup();
    return 0;
}

