#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>

#define I2C_BUS        "/dev/i2c-1"
#define SI1182_ADDR    0x5A
#define CSV_FILE       "heartrate.csv"
#define SAMPLE_MS      100

/* Si1182 register addresses */
#define REG_PART_ID     0x00
#define REG_MEAS_RATE0  0x08
#define REG_COMMAND     0x47
#define REG_PS_DATA0    0x24
#define REG_PS_DATA1    0x25

/* Si1182 command opcodes */
#define CMD_RESET       0x01
#define CMD_PS_FORCE    0x0B

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    running = 0;
}

/* Write a single byte to a Si1182 register via SMBus. */
static int si1182_write_reg(int fd, uint8_t reg, uint8_t value)
{
    union i2c_smbus_data data;
    struct i2c_smbus_ioctl_data args;
    data.byte = value;
    args.read_write = I2C_SMBUS_WRITE;
    args.command = reg;
    args.size = I2C_SMBUS_BYTE_DATA;
    args.data = &data;
    if (ioctl(fd, I2C_SMBUS, &args) < 0)
        return -1;
    return 0;
}

/* Read a single byte from a Si1182 register via SMBus. */
static int si1182_read_reg(int fd, uint8_t reg, uint8_t *value)
{
    union i2c_smbus_data data;
    struct i2c_smbus_ioctl_data args;
    data.byte = 0;
    args.read_write = I2C_SMBUS_READ;
    args.command = reg;
    args.size = I2C_SMBUS_BYTE_DATA;
    args.data = &data;
    if (ioctl(fd, I2C_SMBUS, &args) < 0)
        return -1;
    *value = data.byte;
    return 0;
}

/* Read a 16-bit little-endian register pair (low=0x24, high=0x25). */
static int si1182_read_ps(int fd, uint16_t *prox)
{
    uint8_t lo, hi;
    if (si1182_read_reg(fd, REG_PS_DATA0, &lo) < 0)
        return -1;
    if (si1182_read_reg(fd, REG_PS_DATA1, &hi) < 0)
        return -1;
    *prox = (uint16_t)((hi << 8) | lo);
    return 0;
}

/* Issue a command to the Si1182 COMMAND register. */
static int si1182_command(int fd, uint8_t cmd)
{
    return si1182_write_reg(fd, REG_COMMAND, cmd);
}

/* Initialise the Si1182: verify PART_ID, set measurement rate, then reset. */
static int si1182_init(int fd)
{
    uint8_t part_id;
    if (si1182_read_reg(fd, REG_PART_ID, &part_id) < 0) {
        fprintf(stderr, "Error: failed to read PART_ID register: %s\n",
                strerror(errno));
        return -1;
    }
    if (part_id != 0x82) {
        fprintf(stderr, "Error: unexpected PART_ID 0x%02X (expected 0x82)\n",
                part_id);
        return -1;
    }
    printf("Si1182 detected (PART_ID=0x%02X)\n", part_id);

    /* Set measurement rate to 1 sample per 100 ms (0x00 = 1 Hz). */
    if (si1182_write_reg(fd, REG_MEAS_RATE0, 0x00) < 0) {
        fprintf(stderr, "Error: failed to set MEAS_RATE0: %s\n",
                strerror(errno));
        return -1;
    }

    /* Reset and start proximity measurement. */
    if (si1182_command(fd, CMD_RESET) < 0) {
        fprintf(stderr, "Error: failed to reset Si1182: %s\n",
                strerror(errno));
        return -1;
    }
    usleep(10000); /* allow reset to complete */
    if (si1182_command(fd, CMD_PS_FORCE) < 0) {
        fprintf(stderr, "Error: failed to start PS measurement: %s\n",
                strerror(errno));
        return -1;
    }
    return 0;
}

int main(void)
{
    int fd = -1;
    FILE *csv = NULL;
    int rc = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Warning: sigaction(SIGINT) failed: %s\n",
                strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Warning: sigaction(SIGTERM) failed: %s\n",
                strerror(errno));
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error: cannot open %s: %s\n",
                I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, SI1182_ADDR) < 0) {
        fprintf(stderr, "Error: ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                SI1182_ADDR, strerror(errno));
        goto cleanup;
    }

    if (si1182_init(fd) < 0) {
        fprintf(stderr, "Error: Si1182 initialization failed\n");
        goto cleanup;
    }

    csv = fopen(CSV_FILE, "a");
    if (!csv) {
        fprintf(stderr, "Error: cannot open %s: %s\n",
                CSV_FILE, strerror(errno));
        goto cleanup;
    }

    while (running) {
        uint16_t prox;
        if (si1182_read_ps(fd, &prox) < 0) {
            fprintf(stderr, "Warning: I2C read error on PS data: %s\n",
                    strerror(errno));
            usleep(SAMPLE_MS * 1000);
            continue;
        }

        time_t now = time(NULL);
        struct tm tm_buf;
        struct tm *t = localtime_r(&now, &tm_buf);
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);

        if (fprintf(csv, "%s,%.1f\n", ts, prox) < 0) {
            fprintf(stderr, "Error: fprintf to CSV failed: %s\n",
                    strerror(errno));
            break;
        }
        fflush(csv);
        usleep(SAMPLE_MS * 1000);
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (csv) {
        fflush(csv);
        fclose(csv);
    }
    if (fd >= 0)
        close(fd);
    return rc;
}

