#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x29
#define TRIGGER_PIN    17
#define LOG_FILE       "distance_log.txt"
#define MEAS_TIMEOUT   100000   /* microseconds */
#define POLL_DELAY_US  1000     /* 1 ms poll interval */

/* VL53L0X register addresses */
#define REG_SYSRANGE_START      0x00
#define REG_RESULT_INTERRUPT_STATUS 0x13
#define REG_RESULT_RANGE_STATUS   0x14
#define REG_SYSTEM_INTERRUPT_CLEAR 0x0B

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write one byte to a 16-bit register address */
static int i2c_write_reg8(int handle, uint16_t reg, uint8_t value)
{
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    return i2cWriteDevice(handle, buf, 3);
}

/* Read one byte from a 16-bit register address */
static int i2c_read_reg8(int handle, uint16_t reg, uint8_t *value)
{
    char buf[2];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, buf, 2) < 0)
        return -1;
    if (i2cReadDevice(handle, (char *)value, 1) != 1)
        return -1;
    return 0;
}

/* Read a block of bytes starting at a 16-bit register address */
static int i2c_read_block(int handle, uint16_t reg, uint8_t *buf, uint32_t len)
{
    char addr_buf[2];
    addr_buf[0] = (reg >> 8) & 0xFF;
    addr_buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, addr_buf, 2) < 0)
        return -1;
    if (i2cReadDevice(handle, (char *)buf, len) != (int)len)
        return -1;
    return 0;
}

static int init_sensor(void)
{
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        return -1;
    }

    /* Verify sensor presence by reading the model ID register (0x010F) */
    uint8_t model_id = 0;
    if (i2c_read_reg8(g_i2c_handle, 0x010F, &model_id) < 0) {
        fprintf(stderr, "Sensor not responding at 0x%02X\n", I2C_ADDR);
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        return -1;
    }
    if (model_id != 0xEA) {
        fprintf(stderr, "Unexpected model ID 0x%02X (expected 0xEA)\n", model_id);
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        return -1;
    }

    /* Clear any pending interrupt */
    if (i2c_write_reg8(g_i2c_handle, REG_SYSTEM_INTERRUPT_CLEAR, 0x01) < 0) {
        fprintf(stderr, "Warning: failed to clear interrupt\n");
    }

    return 0;
}

static int read_distance(uint16_t *distance_mm)
{
    /* Start a single range measurement */
    if (i2c_write_reg8(g_i2c_handle, REG_SYSRANGE_START, 0x01) < 0) {
        fprintf(stderr, "Error writing SYSRANGE_START\n");
        return -1;
    }

    /* Poll RESULT_INTERRUPT_STATUS bit 0 until it sets (data ready) */
    uint8_t status = 0;
    int elapsed = 0;
    do {
        if (i2c_read_reg8(g_i2c_handle, REG_RESULT_INTERRUPT_STATUS, &status) < 0) {
            fprintf(stderr, "Error reading RESULT_INTERRUPT_STATUS\n");
            return -1;
        }
        if (status & 0x01)
            break;
        gpioDelay(POLL_DELAY_US);
        elapsed += POLL_DELAY_US;
    } while (elapsed < MEAS_TIMEOUT);

    if (elapsed >= MEAS_TIMEOUT) {
        fprintf(stderr, "Timeout waiting for measurement\n");
        return -1;
    }

    /* Read 14-byte result block starting at RESULT_RANGE_STATUS */
    uint8_t data[14];
    if (i2c_read_block(g_i2c_handle, REG_RESULT_RANGE_STATUS, data, sizeof(data)) < 0) {
        fprintf(stderr, "Error reading distance data block\n");
        return -1;
    }

    /* Distance is 16-bit, big-endian, in bytes 10-11 */
    *distance_mm = ((uint16_t)data[10] << 8) | data[11];

    /* Clear the interrupt so the next measurement can signal */
    if (i2c_write_reg8(g_i2c_handle, REG_SYSTEM_INTERRUPT_CLEAR, 0x01) < 0) {
        fprintf(stderr, "Warning: failed to clear interrupt after read\n");
    }

    return 0;
}

