#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define I2C_BUS 1
#define ICU20201_ADDR 0x6A
#define LED_GPIO 17
#define DEFAULT_THRESHOLD 100
#define LOG_FILE "tof_log.txt"
#define POLL_DELAY_US 50000

#define ICU20201_WHO_AM_I 0x0F
#define ICU20201_WHO_AM_I_VAL 0x02
#define ICU20201_CTRL_REG1 0x10
#define ICU20201_CTRL_REG2 0x11
#define ICU20201_RESULT_REG 0x22
#define ICU20201_RANGE_STATUS 0x01
#define ICU20201_RANGE_STATUS_READY 0x01
#define ICU20201_RANGE_STATUS_VALID 0x02
#define ICU20201_RANGE_STATUS_ERROR 0x04

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static int threshold = DEFAULT_THRESHOLD;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int write_reg(int handle, uint8_t reg, uint8_t val) {
    int rc = i2cWriteByteData(handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed: reg=0x%02X, val=0x%02X, rc=%d\n", reg, val, rc);
    }
    return rc;
}

static int read_reg(int handle, uint8_t reg) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed: reg=0x%02X, rc=%d\n", reg, rc);
    }
    return rc;
}

static int init_icu20201(int handle) {
    int who = read_reg(handle, ICU20201_WHO_AM_I);
    if (who < 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register\n");
        return -1;
    }
    if (who != ICU20201_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n", who, ICU20201_WHO_AM_I_VAL);
        return -1;
    }
    printf("ICU-20201 detected (WHO_AM_I=0x%02X)\n", who);

    if (write_reg(handle, ICU20201_CTRL_REG1, 0x00) < 0) return -1;
    if (write_reg(handle, ICU20201_CTRL_REG2, 0x00) < 0) return -1;
    return 0;
}

static int read_distance(int handle) {
    if (write_reg(handle, ICU20201_CTRL_REG1, 0x01) < 0) return -1;
    gpioDelay(1000);

    int status = read_reg(handle, ICU20201_RESULT_REG);
    if (status < 0) return -1;

    if ((status & ICU20201_RANGE_STATUS_READY) == 0) {
        return -1;
    }

    int distance = read_reg(handle, ICU20201_RESULT_REG);
    if (distance < 0) return -1;

    if ((distance & ICU20201_RANGE_STATUS_ERROR) != 0) {
        return -1;
    }

    return distance;
}

static void log_distance(int distance) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, Distance: %d mm\n", timestamp, distance);
    fclose(fp);
}

static void control_led(int distance, int threshold) {
    if (distance < threshold) {
        gpioWrite(LED_GPIO, 1);
    } else {
        gpioWrite(LED_GPIO, 0);
    }
}

int main(int argc, char *argv[]) {
    if (argc > 1) {
        threshold = atoi(argv[1]);
        if (threshold <= 0) {
            fprintf(stderr, "Invalid threshold value: %s\n", argv[1]);
            return 1;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, ICU20201_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at bus %d addr 0x%02X: %d\n", I2C_BUS, ICU20201_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (init_icu20201(i2c_handle) < 0) {
        fprintf(stderr, "ICU-20201 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    printf("Starting distance measurements. Threshold: %d mm. Press Ctrl+C to exit.\n", threshold);

    while (running) {
        int distance = read_distance(i2c_handle);
        if (distance >= 0) {
            log_distance(distance);
            control_led(distance, threshold);
        } else {
            fprintf(stderr, "Error reading distance. Retrying...\n");
        }
        gpioDelay(POLL_DELAY_US);
    }

    printf("\nExiting gracefully...\n");
    gpioWrite(LED_GPIO, 0);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

