#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_DEVICE "/dev/i2c-1"
#define B5L_LD50_ADDR 0x50
#define CMD_LEN 4
#define RESP_LEN 15
#define NUM_SAMPLES 10
#define THRESHOLD_MM 1000
#define LOG_FILE "intrusion_log.txt"
#define SAMPLE_DELAY_MS 100
#define CMD_DELAY_MS 10

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_cmd(int fd, const uint8_t *cmd, size_t len) {
    if (write(fd, cmd, len) != (ssize_t)len) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_resp(int fd, uint8_t *buf, size_t len) {
    ssize_t n = read(fd, buf, len);
    if (n != (ssize_t)len) {
        fprintf(stderr, "I2C read failed: expected %zu bytes, got %zd (%s)\n",
                len, n, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_distance(int fd, int *distance_mm) {
    uint8_t cmd[CMD_LEN] = {B5L_LD50_ADDR, 0x0A, 0x00, 0x01};
    uint8_t resp[RESP_LEN];

    if (i2c_write_cmd(fd, cmd, CMD_LEN) < 0) {
        return -1;
    }
    usleep(CMD_DELAY_MS * 1000);

    if (i2c_read_resp(fd, resp, RESP_LEN) < 0) {
        return -1;
    }

    if (resp[0] != B5L_LD50_ADDR) {
        fprintf(stderr, "Sensor not responding (header byte mismatch: 0x%02X)\n", resp[0]);
        return -1;
    }

    *distance_mm = (resp[11] << 8) | resp[12];
    return 0;
}

static void log_intrusion(int avg_mm) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[64];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
        fprintf(fp, "%s - Intrusion detected! Average distance: %d mm\n", ts, avg_mm);
    } else {
        fprintf(fp, "Intrusion detected! Average distance: %d mm\n", avg_mm);
    }

    fclose(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_DEVICE, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, B5L_LD50_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                B5L_LD50_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    printf("B5L-LD50 intrusion detection started. Press Ctrl+C to exit.\n");

    while (running) {
        long sum = 0;
        int valid = 0;

        for (int i = 0; i < NUM_SAMPLES; i++) {
            int dist;
            if (read_distance(i2c_fd, &dist) == 0) {
                sum += dist;
                valid++;
            } else {
                fprintf(stderr, "Sample %d failed\n", i);
            }
            usleep(SAMPLE_DELAY_MS * 1000);
        }

        if (valid > 0) {
            int avg = (int)(sum / valid);
            printf("Average distance: %d mm\n", avg);
            if (avg < THRESHOLD_MM) {
                log_intrusion(avg);
            }
        } else {
            fprintf(stderr, "All samples failed; skipping log entry.\n");
        }
    }

    printf("\nShutting down...\n");
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    return 0;
}

