#define VL53L0X_ADDR 0x29
#define MODEL_ID_REG 0xC0
#define MODEL_ID_VALUE 0xEE
#define SYSRANGE_START_REG 0x00
#define RESULT_INTERRUPT_STATUS_REG 0x13
#define RESULT_RANGE_STATUS_REG 0x14
#define SYSTEM_INTERRUPT_CLEAR_REG 0x0B
#define POLL_TIMEOUT_MS 100
#define LOOP_DELAY_MS 500

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Warning: i2cWriteByteData(reg=0x%02X, val=0x%02X) failed: %s\n",
                reg, value, strerror(errno));
    }
    return rc;
}

static int i2c_read_byte(int handle, uint8_t reg) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Warning: i2cReadByteData(reg=0x%02X) failed: %s\n",
                reg, strerror(errno));
    }
    return rc;
}

static int i2c_read_word(int handle, uint8_t reg) {
    int rc = i2cReadWordData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Warning: i2cReadWordData(reg=0x%02X) failed: %s\n",
                reg, strerror(errno));
    }
    return rc;
}

static int vl53l0x_init(int handle) {
    int model_id = i2c_read_byte(handle, MODEL_ID_REG);
    if (model_id < 0) {
        fprintf(stderr, "Error: Failed to read model ID register.\n");
        return -1;
    }
    if (model_id != MODEL_ID_VALUE) {
        fprintf(stderr, "Error: Unexpected model ID 0x%02X (expected 0x%02X).\n",
                model_id, MODEL_ID_VALUE);
        return -1;
    }
    printf("VL53L0X detected (model ID 0x%02X).\n", model_id);
    return 0;
}

static int vl53l0x_read_distance(int handle) {
    if (i2c_write_byte(handle, SYSRANGE_START_REG, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to start ranging.\n");
        return -1;
    }

    for (int i = 0; i < POLL_TIMEOUT_MS; i++) {
        int status = i2c_read_byte(handle, RESULT_INTERRUPT_STATUS_REG);
        if (status < 0) {
            fprintf(stderr, "Error: Failed to read interrupt status.\n");
            return -1;
        }
        if (status & 0x01) {
            break;
        }
        gpioDelay(1000);
        if (i == POLL_TIMEOUT_MS - 1) {
            fprintf(stderr, "Error: Ranging timeout.\n");
            return -1;
        }
    }

    int distance = i2c_read_word(handle, RESULT_RANGE_STATUS_REG);
    if (distance < 0) {
        fprintf(stderr, "Error: Failed to read distance register.\n");
        return -1;
    }

    if (i2c_write_byte(handle, SYSTEM_INTERRUPT_CLEAR_REG, 0x01) < 0) {
        fprintf(stderr, "Warning: Failed to clear interrupt.\n");
    }

    return distance;
}

static void get_timestamp(char *buf, size_t len) {
    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(buf, len, "%Y-%m-%d %H:%M:%S", timeinfo);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, VL53L0X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen(bus=%d, addr=0x%02X) failed: %s\n",
                I2C_BUS, VL53L0X_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (vl53l0x_init(i2c_handle) < 0) {
        fprintf(stderr, "Error: VL53L0X initialisation failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Starting distance readings every %d ms. Press Ctrl+C to exit.\n",
           LOOP_DELAY_MS);

    while (running) {
        int distance = vl53l0x_read_distance(i2c_handle);
        if (distance >= 0) {
            char timestamp[32];
            get_timestamp(timestamp, sizeof(timestamp));
            printf("%s Distance: %d mm\n", timestamp, distance);
            fflush(stdout);
        }
        gpioDelay(LOOP_DELAY_MS * 1000);
    }

    printf("\nExiting...\n");
    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

