#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SI1182_ADDR 0x39
#define REG_IRQ_STATUS 0x25
#define REG_PROX_LSB  0x2A
#define REG_PROX_MSB  0x2B
#define REG_CONFIG    0x18
#define CONFIG_PROX_ON 0x01

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_proximity(int handle, uint16_t *prox) {
    int lsb = i2cReadByteData(handle, REG_PROX_LSB);
    if (lsb < 0) return -1;
    int msb = i2cReadByteData(handle, REG_PROX_MSB);
    if (msb < 0) return -1;
    *prox = (uint16_t)((msb << 8) | lsb);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(1, SI1182_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed (addr 0x%02X): %d\n", SI1182_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Probe: a NACK here usually means the sensor is absent or the bus is
       not responding. */
    int probe = i2cReadByteData(i2c_handle, REG_IRQ_STATUS);
    if (probe < 0) {
        fprintf(stderr, "Error: Si1182 not detected on bus 1, addr 0x%02X (NACK)\n", SI1182_ADDR);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (i2cWriteByteData(i2c_handle, REG_CONFIG, CONFIG_PROX_ON) < 0) {
        fprintf(stderr, "Error: failed to write CONFIG register\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Si1182 proximity sensor reader started. Press Ctrl+C to exit.\n");

    while (running) {
        int irq = i2cReadByteData(i2c_handle, REG_IRQ_STATUS);
        if (irq < 0) {
            fprintf(stderr, "Warning: I2C read error on IRQ status\n");
            gpioDelay(500000);
            continue;
        }
        if (irq & 0x01) {
            uint16_t prox;
