#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define MLX75030_ADDR  0x4C
#define DISTANCE_REG   0x00
#define DISTANCE_FACTOR 0.125f   /* mm per count (MLX75030 datasheet) */
#define POLL_MS        500

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int i2c_open(int *fd_out)
{
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", I2C_BUS, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, MLX75030_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n",
                MLX75030_ADDR, strerror(errno));
        close(fd);
        return -1;
    }
    *fd_out = fd;
    return 0;
}

/*
 * Read a 16-bit little-endian register from the MLX75030.
 * Returns 0 on success and stores the distance in mm in *out_mm.
 * Returns -1 on I2C error.
 */
static int read_distance_mm(int fd, float *out_mm)
{
    uint8_t reg = DISTANCE_REG;
    uint8_t buf[2];

    /* Write the register pointer */
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "write(reg 0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }

    /* Read two bytes (low byte first) */
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "read(distance): %s\n", strerror(errno));
        return -1;
    }

    int16_t raw = (int16_t)((uint16_t)buf[0] | ((uint16_t)buf[1] << 8));
    *out_mm = (float)raw * DISTANCE_FACTOR;
    return 0;
}

int main(void)
{
    int fd = -1;
    int rc = EXIT_FAILURE;

    if (install_signal_handlers() != 0)
        goto cleanup;

    if (i2c_open(&fd) != 0)
        goto cleanup;

    /* Verify the sensor is present by reading the distance register */
    float test_mm;
    if (read_distance_mm(fd, &test_mm) != 0) {
        fprintf(stderr, "MLX75030 not responding at 0x%02X on %s\n",
                MLX75030_ADDR, I2C_BUS);
        goto cleanup;
    }

    printf("MLX75030 distance sensor on %s (addr 0x%02X)\n", I2C_BUS, MLX75030_ADDR);
    printf("Press Ctrl-C to exit.\n");

    while (g_running) {
        float distance_mm;
        if (read_distance_mm(fd, &distance_mm) == 0) {
            printf("Distance: %.2f mm\n", distance_mm);
            fflush(stdout);
        } else {
            fprintf(stderr, "I2C read error — will retry next cycle\n");
        }
        struct timespec ts = { 0, POLL_MS * 1000000L };
        nanosleep(&ts, NULL);
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (fd >= 0)
        close(fd);
    return rc;
}

