#define OPT3101_ADDR 0x44
#define I2C_BUS 1

#define REG_CH0_DATA 0x00
#define REG_AMBIENT 0x04
#define REG_ERROR 0x0A

#define ERROR_VALUE -1

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

int read_register(int handle, uint8_t reg, uint8_t *value) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    *value = (uint8_t)result;
    return 0;
}

int read_word(int handle, uint8_t reg, uint16_t *value) {
    int result = i2cReadWordData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading word from register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    *value = (uint16_t)result;
    return 0;
}

int read_channel0_distance(int handle, int *distance) {
    uint8_t data;
    if (read_register(handle, REG_CH0_DATA, &data) != 0) {
        return -1;
    }
    *distance = (int)data;
    return 0;
}

int read_ambient_light(int handle, int *ambient_light) {
    uint8_t data;
    if (read_register(handle, REG_AMBIENT, &data) != 0) {
        return -1;
    }
    *ambient_light = (int)data;
    return 0;
}

int read_error_flag(int handle, int *error_flag) {
    uint8_t data;
    if (read_register(handle, REG_ERROR, &data) != 0) {
        return -1;
    }
    *error_flag = (int)data;
    return 0;
}

void log_data(int distance, int ambient_light, int error_flag) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s - Distance: %d mm, Ambient Light: %d, Error: %d\n", timestamp, distance, ambient_light, error_flag);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, OPT3101_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    printf("OPT3101 Distance Sensor Interface\n");
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        int distance, ambient_light, error_flag;

        if (read_channel0_distance(i2c_handle, &distance) != 0) {
            fprintf(stderr, "Error reading distance data.\n");
            distance = ERROR_VALUE;
        }

        if (read_ambient_light(i2c_handle, &ambient_light) != 0) {
            fprintf(stderr, "Error reading ambient light data.\n");
            ambient_light = ERROR_VALUE;
        }

        if (read_error_flag(i2c_handle, &error_flag) != 0) {
            fprintf(stderr, "Error reading error flag.\n");
            error_flag = ERROR_VALUE;
        }

        log_data(distance, ambient_light, error_flag);

        gpioDelay(500000);
    }

    printf("\nExiting gracefully...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return 0;
}

