/*
 * HC-SR04 Ultrasonic Distance Sensor - Raspberry Pi 3 Model B+
 * Library: pigpio (not wiringPi)
 *
 * Wiring:
 *   HC-SR04 VCC -> 5V (external 5V supply recommended; sensor module has 5V pin)
 *   HC-SR04 GND -> GND
 *   HC-SR04 TRIG -> GPIO 17 (BCM)
 *   HC-SR04 ECHO -> GPIO 18 (BCM) via 1 kOhm series resistor (protection)
 *
 * Note: The HC-SR04 operates at 5V, but the Raspberry Pi GPIO pins are
 * only 3.3V tolerant. Use a 5V-to-3.3V level shifter or a module that
 * supports 5V on its GND/3.3V pin. The 1 kOhm resistor on the echo
 * line protects the Pi against a short to GND when the sensor is
 * disconnected.
 *
 * Build: gcc -Wall -Wextra -O2 -o hcsr04 hcsr04.c -lpigpio -lrt
 * Run:   sudo ./hcsr04
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define TRIGGER_PIN      17
#define ECHO_PIN         18

#define TRIGGER_PULSE_US 10          /* 10 us trigger pulse */
#define ECHO_TIMEOUT_US  200000      /* 200 ms timeout for echo rising edge */
#define PULSE_TIMEOUT_US 38000       /* 38 ms timeout for echo falling edge
                                     * (HC-SR04 max range ~400 cm) */
#define SAMPLE_PERIOD_US 1000000     /* 1 second between readings */
#define MAX_DISTANCE_CM 400.0       /* HC-SR04 maximum rated range */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Measure the echo pulse width in microseconds.
 * Returns:
 *   > 0  : valid pulse duration in microseconds
 *   -1  : echo rising-edge timeout
 *   -2  : echo falling-edge timeout
 *   -3  : invalid pulse duration (<= 0 or > 38 ms)
 */
static int measure_echo_pulse(void)
{
    uint32_t start_tick = 0, end_tick = 0;
    uint32_t timeout_tick = gpioTick() + ECHO_TIMEOUT_US;

    /* Wait for echo rising edge */
    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            return -1;                 /* timeout */
        }
    }
    start_tick = gpioTick();

    /* Wait for echo falling edge */
    timeout_tick = gpioTick() + PULSE_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            return -2;                 /* timeout */
        }
    }
    end_tick = gpioTick();

    uint32_t pulse_us = end_tick - start_tick;
    if (pulse_us <= 0 || pulse_us > PULSE_TIMEOUT_US) {
        return -3;                     /* invalid duration */
    }
    return (int)pulse_us;
}

static float calculate_distance_cm(uint32_t pulse_us)
{
    return (float)pulse_us * 0.0343f / 2.0f;
}

static void log_distance(float distance_cm)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    printf("[%s] Distance: %.2f cm\n", timestamp, distance_cm);
    fflush(stdout);
}

int main(void)
{
    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO pins */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", TRIGGER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input.\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low */
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(1000);  /* 1 ms settle */

    printf("HC-SR04 distance sensor started. Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (g_running) {
        /* Send 10 us trigger pulse */
        gpioWrite(TRIGGER_PIN, 1);
        gpioDelay(TRIGGER_PULSE_US);
        gpioWrite(TRIGGER_PIN, 0);

        int ret = measure_echo_pulse();
        if (ret == -1) {
            fprintf(stderr, "Warning: echo rising-edge timeout.\n");
        } else if (ret == -2) {
            fprintf(stderr, "Warning: echo falling-edge timeout.\n");
        } else if (ret == -3) {
            fprintf(stderr, "Warning: invalid pulse duration.\n");
        } else {
            float distance = calculate_distance_cm((uint32_t)ret);
            if (distance > MAX_DISTANCE_CM) {
                fprintf(stderr, "Warning: distance %.2f cm exceeds max range.\n",
                        distance);
            } else {
                log_distance(distance);
            }
        }

        /* Wait 1 second before next reading */
        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* Clean shutdown */
    gpioWrite(TRIGGER_PIN, 0);
    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

