#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <pigpio.h>

#define UART_DEVICE "/dev/serial0"
#define GPIO_LED 17
#define INTRUSION_THRESHOLD 1.0
#define RANGE_RESOLUTION 0.0486
#define NUM_RANGE_BINS 64
#define DATA_FRAME_SIZE (NUM_RANGE_BINS * 2 + 8)
#define LOG_FILE "intrusion_log.csv"
#define ALERT_DURATION_MS 2000
#define POLL_DELAY_MS 100

static volatile sig_atomic_t running = 1;
static int uart_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_uart(const char *device) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_NDELAY);
    if (fd < 0) {
        fprintf(stderr, "Error opening UART %s: %s\n", device, strerror(errno));
        return -1;
    }

    if (fcntl(fd, F_SETFL, 0) < 0) {
        fprintf(stderr, "Error clearing O_NDELAY: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        fprintf(stderr, "Error getting termios attributes: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    cfsetospeed(&tty, B9600);
    cfsetispeed(&tty, B9600);

    tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8;
    tty.c_iflag &= ~IGNBRK;
    tty.c_lflag = 0;
    tty.c_oflag = 0;
    tty.c_cc[VMIN] = 0;
    tty.c_cc[VTIME] = 1;

    tty.c_iflag &= ~(IXON | IXOFF | IXANY);
    tty.c_cflag |= (CLOCAL | CREAD);
    tty.c_cflag &= ~(PARENB | PARODD);
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CRTSCTS;

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "Error setting termios attributes: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    tcflush(fd, TCIOFLUSH);
    return fd;
}

static int read_frame(int fd, uint8_t *buf, size_t expected_len) {
    size_t total = 0;
    while (total < expected_len) {
        ssize_t n = read(fd, buf + total, expected_len - total);
        if (n < 0) {
            if (errno == EAGAIN || errno == EWOULDBLOCK) continue;
            fprintf(stderr, "UART read error: %s\n", strerror(errno));
            return -1;
        }
        if (n == 0) {
            fprintf(stderr, "UART read returned 0 bytes (sensor absent or disconnected)\n");
            return -1;
        }
        total += n;
    }
    return 0;
}

static float calculate_distance(const uint16_t *data) {
    float min_dist = 1e9f;
    for (int i = 0; i < NUM_RANGE_BINS; i++) {
        float dist = (float)data[i] * RANGE_RESOLUTION;
        if (dist < min_dist) min_dist = dist;
    }
    return min_dist;
}

static void trigger_alert(int gpio) {
    gpioWrite(gpio, 1);
    gpioDelay(ALERT_DURATION_MS * 1000);
    gpioWrite(gpio, 0);
}

static void log_intrusion(float distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

    if (log_file) {
        fprintf(log_file, "%s,%.2f\n", timestamp, distance);
        fflush(log_file);
    } else {
        fprintf(stderr, "Error: Log file not open.\n");
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting up signal handlers: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    if (gpioSetMode(GPIO_LED, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", GPIO_LED);
        gpioTerminate();
        return 1;
    }
    gpioWrite(GPIO_LED, 0);

    uart_fd = init_uart(UART_DEVICE);
    if (uart_fd < 0) {
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        close(uart_fd);
        gpioTerminate();
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,Distance (m)\n");
        fflush(log_file);
    }

    uint8_t frame_buf[DATA_FRAME_SIZE];
    uint16_t range_data[NUM_RANGE_BINS];

    while (running) {
        if (read_frame(uart_fd, frame_buf, DATA_FRAME_SIZE) == 0) {
            memcpy(range_data, frame_buf + 8, NUM_RANGE_BINS * 2);
            float distance = calculate_distance(range_data);

            if (distance <= INTRUSION_THRESHOLD) {
                trigger_alert(GPIO_LED);
                log_intrusion(distance);
            }
        } else {
            fprintf(stderr, "Failed to read frame, retrying...\n");
        }
        gpioDelay(POLL_DELAY_MS * 1000);
    }

    fprintf(stderr, "\nShutting down gracefully...\n");
    gpioWrite(GPIO_LED, 0);
    if (uart_fd >= 0) close(uart_fd);
    if (log_file) fclose(log_file);
    gpioTerminate();
    return 0;
}

