#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x69
#define DISTANCE_REG_H 0x31
#define DISTANCE_REG_L 0x32
#define ALERT_PIN      17
#define DISTANCE_THRESHOLD 10.0f
#define SAMPLE_DELAY_US 100000
#define LOG_FILE       "distance_log.txt"

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int init_i2c(void) {
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        return -1;
    }
    return 0;
}

static int read_distance(uint16_t *distance) {
    int hi = i2cReadByteData(g_i2c_handle, DISTANCE_REG_H);
    if (hi < 0) {
        fprintf(stderr, "Error reading distance register 0x%02X: %d\n",
                DISTANCE_REG_H, hi);
        return -1;
    }
    int lo = i2cReadByteData(g_i2c_handle, DISTANCE_REG_L);
    if (lo < 0) {
        fprintf(stderr, "Error reading distance register 0x%02X: %d\n",
                DISTANCE_REG_L, lo);
        return -1;
    }
    *distance = ((uint16_t)hi << 8) | (uint16_t)lo;
    return 0;
}

static float convert_to_cm(uint16_t raw) {
    /* TDK ICU-20201: distance in cm = raw / 10 */
    return (float)raw / 10.0f;
}

static int log_distance(float distance) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
        fprintf(fp, "%s, Distance: %.2f cm\n", ts, distance);
    } else {
        fprintf(fp, "<unknown-time>, Distance: %.2f cm\n", distance);
    }
    fclose(fp);
    return 0;
}

static void trigger_alert(void) {
    gpioWrite(ALERT_PIN, 1);
    gpioDelay(500000);
    gpioWrite(ALERT_PIN, 0);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(ALERT_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", ALERT_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(ALERT_PIN, 0);

    if (init_i2c() < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("ICU-20201 distance monitor started. Press Ctrl+C to exit.\n");

    while (g_running) {
        uint16_t raw;
        if (read_distance(&raw) < 0) {
            gpioDelay(SAMPLE_DELAY_US);
            continue;
        }

        float distance = convert_to_cm(raw);
        if (log_distance(distance) < 0) {
            fprintf(stderr, "Logging failed; continuing.\n");
        }

        if (distance < DISTANCE_THRESHOLD) {
            trigger_alert();
        }

        gpioDelay(SAMPLE_DELAY_US);
    }

    printf("\nShutting down...\n");
    gpioWrite(ALERT_PIN, 0);
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

