#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define VL53L1X_ADDR   0x29
#define LOG_FILE       "distance_log.csv"
#define POLL_DELAY_US  100000   /* 100 ms */
#define RESET_DELAY_US 2000     /* 2 ms  */
#define RANGING_TIMEOUT_MS 100

/* VL53L1X register addresses (16-bit, big-endian on bus) */
#define REG_SOFT_RESET              0x0000
#define REG_MODEL_ID                0x010F
#define REG_SYSTEM__MODE_START     0x007
#define REG_SYSRANGE__START        0x000
#define REG_RESULT__INTERRUPT_STATUS 0x013
#define REG_RESULT__RANGE_STATUS    0x078
#define REG_SYSTEM__INTERRUPT_CLEAR 0x014

#define EXPECTED_MODEL_ID 0xEA

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write16(int handle, uint16_t reg, uint8_t value)
{
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    return i2cWriteDevice(handle, buf, 3);
}

static int i2c_read16(int handle, uint16_t reg, uint8_t *buf, uint32_t len)
{
    char addr[2];
    addr[0] = (reg >> 8) & 0xFF;
    addr[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, addr, 2) < 0)
        return -1;
    return i2cReadDevice(handle, (char *)buf, len);
}

static int vl53l1x_init(int handle)
{
    uint8_t model_id = 0;
    if (i2c_read16(handle, REG_MODEL_ID, &model_id, 1) < 0) {
        fprintf(stderr, "Error: failed to read model ID register\n");
        return -1;
    }
    if (model_id != EXPECTED_MODEL_ID) {
        fprintf(stderr, "Error: unexpected model ID 0x%02X (expected 0x%02X)\n",
                model_id, EXPECTED_MODEL_ID);
        return -1;
    }

    /* Software reset: write 0x00 to SOFT_RESET register */
    if (i2c_write16(handle, REG_SOFT_RESET, 0x00) < 0) {
        fprintf(stderr, "Error: failed to write soft reset\n");
        return -1;
    }
    gpioDelay(RESET_DELAY_US);

    /* Start continuous back-to-back ranging */
    if (i2c_write16(handle, REG_SYSTEM__MODE_START, 0x01) < 0) {
        fprintf(stderr, "Error: failed to start ranging\n");
        return -1;
    }

    /* Poll SYSRANGE__START bit 0 until it self-clears (data ready) */
    uint8_t mode = 0;
    for (int i = 0; i < RANGING_TIMEOUT_MS; i++) {
        if (i2c_read16(handle, REG_SYSRANGE__START, &mode, 1) < 0) {
            fprintf(stderr, "Error: failed to read range status\n");
            return -1;
        }
        if ((mode & 0x01) == 0)
            break;
        gpioDelay(1000);
    }
    if (mode & 0x01) {
        fprintf(stderr, "Error: ranging start timeout\n");
        return -1;
    }

    return 0;
}

static int read_distance_mm(int handle, int *distance_mm)
{
    uint8_t status = 0;
    if (i2c_read16(handle, REG_RESULT__INTERRUPT_STATUS, &status, 1) < 0) {
        fprintf(stderr, "Error: failed to read interrupt status\n");
        return -1;
    }
    if ((status & 0x01) == 0)
        return 1;  /* no new data yet */

    uint8_t range_buf[2];
    if (i2c_read16(handle, REG_RESULT__RANGE_STATUS, range_buf, 2) < 0) {
        fprintf(stderr, "Error: failed to read range status\n");
        return -1;
    }
    *distance_mm = ((int)range_buf[0] << 8) | range_buf[1];

    /* Clear interrupt by writing 0x01 to SYSTEM__INTERRUPT_CLEAR */
    if (i2c_write16(handle, REG_SYSTEM__INTERRUPT_CLEAR, 0x01) < 0) {
        fprintf(stderr, "Warning: failed to clear interrupt\n");
        return 1;
    }
    return 0;
}

static void log_distance(FILE *fp, int distance_mm)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(fp, "%s,%d\n", timestamp, distance_mm);
    fflush(fp);
}

static void print_parking_message(int distance_mm)
{
    if (distance_mm < 300) {
        printf("Parking Guidance: STOP! Object %d mm away\n", distance_mm);
    } else if (distance_mm < 600) {
        printf("Parking Guidance: APPROACH! Object %d mm away\n", distance_mm);
    } else if (distance_mm < 1200) {
        printf("Parking Guidance: SLOW! Object %d mm away\n", distance_mm);
    } else {
        printf("Parking Guidance: CLEAR! Object %d mm away\n", distance_mm);
    }
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d)\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (vl53l1x_init(g_i2c_handle) < 0) {
        fprintf(stderr, "Error: VL53L1X initialisation failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode; write header if empty */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("Error opening log file");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fseek(g_log_file, 0, SEEK_END);
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "timestamp,distance_mm\n");
        fflush(g_log_file);
    }

    printf("Parking assistance system started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int distance_mm = 0;
        int rc = read_distance_mm(g_i2c_handle, &distance_mm);

        if (rc == 0) {
            log_distance(g_log_file, distance_mm);
            print_parking_message(distance_mm);
        } else if (rc < 0) {
            fprintf(stderr, "Warning: read failed, continuing...\n");
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");

    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

