        return -1;
    }
    if ((status & 0x01) == 0)
        return 1;  /* no new data yet */

    uint8_t range_buf[2];
    if (i2c_read16(handle, REG_RESULT__RANGE_STATUS, range_buf, 2) < 0) {
        fprintf(stderr, "Error: failed to read range status\n");
        return -1;
    }
    *distance_mm = ((int)range_buf[0] << 8) | range_buf[1];

    /* Clear interrupt by writing 0x01 to SYSTEM__INTERRUPT_CLEAR */
    if (i2c_write16(handle, REG_SYSTEM__INTERRUPT_CLEAR, 0x01) < 0) {
        fprintf(stderr, "Warning: failed to clear interrupt\n");
        return 1;
    }
    return 0;
}

static void log_distance(FILE *fp, int distance_mm)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(fp, "%s,%d\n", timestamp, distance_mm);
    fflush(fp);
}

static void print_parking_message(int distance_mm)
{
    if (distance_mm < 300) {
        printf("Parking Guidance: STOP! Object %d mm away\n", distance_mm);
    } else if (distance_mm < 600) {
        printf("Parking Guidance: APPROACH! Object %d mm away\n", distance_mm);
    } else if (distance_mm < 1200) {
        printf("Parking Guidance: SLOW! Object %d mm away\n", distance_mm);
    } else {
        printf("Parking Guidance: CLEAR! Object %d mm away\n", distance_mm);
    }
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d)\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (vl53l1x_init(g_i2c_handle) < 0) {
        fprintf(stderr, "Error: VL53L1X initialisation failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode; write header if empty */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("Error opening log file");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fseek(g_log_file, 0, SEEK_END);
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "timestamp,distance_mm\n");
        fflush(g_log_file);
    }

    printf("Parking assistance system started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int distance_mm = 0;
        int rc = read_distance_mm(g_i2c_handle, &distance_mm);

        if (rc == 0) {
            log_distance(g_log_file, distance_mm);
            print_parking_message(distance_mm);
        } else if (rc < 0) {
            fprintf(stderr, "Warning: read failed, continuing...\n");
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");

    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

