#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define CH201_ADDR     0x45
#define LED_GPIO       18
#define SAMPLE_US      100000   /* 100 ms between samples */
#define MAX_RETRIES    3
#define RETRY_DELAY_US 10000    /* 10 ms between retries */

/* CH201 register addresses */
#define CH201_REG_DIST  0x00
#define CH201_REG_CTRL  0x01

/* Control register bits */
#define CH201_CTRL_RESET 0x01
#define CH201_CTRL_START 0x02

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write a byte to a CH201 register; returns 0 on success, -1 on failure. */
static int ch201_write_reg(int handle, uint8_t reg, uint8_t value)
{
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int rc = i2cWriteByteData(handle, reg, value);
        if (rc == 0)
            return 0;
        fprintf(stderr, "I2C write failed (reg 0x%02X, val 0x%02X), attempt %d/%d, rc=%d\n",
                reg, value, attempt + 1, MAX_RETRIES, rc);
        if (attempt < MAX_RETRIES - 1)
            gpioDelay(RETRY_DELAY_US);
    }
    return -1;
}

/* Read a byte from a CH201 register; returns 0 on success, -1 on failure. */
static int ch201_read_reg(int handle, uint8_t reg, uint8_t *value)
{
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int rc = i2cReadByteData(handle, reg);
        if (rc >= 0) {
            *value = (uint8_t)rc;
            return 0;
        }
        fprintf(stderr, "I2C read failed (reg 0x%02X), attempt %d/%d, rc=%d\n",
                reg, attempt + 1, MAX_RETRIES, rc);
        if (attempt < MAX_RETRIES - 1)
            gpioDelay(RETRY_DELAY_US);
    }
    return -1;
}

/* Trigger a single measurement and read the 16-bit distance. */
static int ch201_read_distance(int handle, uint16_t *distance_mm)
{
    /* Reset the device */
    if (ch201_write_reg(handle, CH201_REG_CTRL, CH201_CTRL_RESET) != 0)
        return -1;
    gpioDelay(2000); /* 2 ms reset settling */

    /* Start a single measurement */
    if (ch201_write_reg(handle, CH201_REG_CTRL, CH201_CTRL_START) != 0)
        return -1;
    gpioDelay(2000); /* 2 ms measurement settling */

    /* Poll the control register for data-ready (bit 0) */
    for (int i = 0; i < 20; i++) {
        uint8_t ctrl;
        if (ch201_read_reg(handle, CH201_REG_CTRL, &ctrl) != 0)
            return -1;
        if (ctrl & 0x01)
            break;
        gpioDelay(1000); /* 1 ms */
    }

    uint8_t lo, hi;
    if (ch201_read_reg(handle, CH201_REG_DIST, &lo) != 0)
        return -1;
    if (ch201_read_reg(handle, CH201_REG_DIST, &hi) != 0)
        return -1;

    *distance_mm = ((uint16_t)hi << 8) | lo;
    return 0;
}

static void set_led_frequency(int frequency)
{
    if (frequency > 0) {
        gpioSetMode(LED_GPIO, PI_OUTPUT);
        gpioSetPWMfrequency(LED_GPIO, frequency);
        gpioPWM(LED_GPIO, 128); /* 50% duty cycle */
    } else {
        gpioWrite(LED_GPIO, 0);
    }
}

int main(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, CH201_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%02X (rc=%d)\n",
                I2C_BUS, CH201_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Probe sensor: try a register read to confirm the device is present */
    uint8_t probe;
    if (ch201_read_reg(g_i2c_handle, CH201_REG_CTRL, &probe) != 0) {
        fprintf(stderr, "CH201 not responding at address 0x%02X on bus %d\n",
                CH201_ADDR, I2C_BUS);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Start with LED off */
    gpioWrite(LED_GPIO, 0);

    while (g_running) {
        uint16_t distance;
        if (ch201_read_distance(g_i2c_handle, &distance) != 0) {
            fprintf(stderr, "Sensor read error; continuing\n");
            gpioDelay(SAMPLE_US);
            continue;
        }

        /* Map distance (0-65535 mm) to frequency: 50 mm -> 10 Hz, 500 mm -> 1 Hz */
        float normalized = (float)distance / 65535.0f;
        float freq = 10.0f + (500.0f - 50.0f) * normalized;
        if (freq < 1.0f) freq = 1.0f;
        if (freq > 10.0f) freq = 10.0f;
        int frequency = (int)(freq + 0.5f);

        set_led_frequency(frequency);

        time_t now = time(NULL);
        struct tm tm_info;
        localtime_r(&now, &tm_info);
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);
        printf("%s  Distance: %u mm  Frequency: %d Hz\n", ts, distance, frequency);
        fflush(stdout);

        gpioDelay(SAMPLE_US);
    }

    /* Clean shutdown */
    gpioWrite(LED_GPIO, 0);
    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

