#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define CH101_ADDR     0x49
#define CSV_FILE       "distance_log.csv"
#define SAMPLE_MS      500
#define MEAS_TIMEOUT_MS 50

/* CH-101 register addresses */
#define REG_MEAS_TRIGGER   0x04
#define REG_MEAS_STATUS    0x06
#define REG_DIST_HIGH      0x08
#define REG_DIST_LOW       0x09

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_csv   = NULL;

static void sighandler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "i2c_write_reg8(0x%02X, 0x%02X): %s\n",
                reg, val, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *out)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_reg8 write(0x%02X): %s\n",
                reg, strerror(errno));
        return -1;
    }
    uint8_t val;
    if (read(fd, &val, 1) != 1) {
        fprintf(stderr, "i2c_read_reg8 read(0x%02X): %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = val;
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_reg16 write(0x%02X): %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "i2c_read_reg16 read(0x%02X): %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static int ch101_read_distance(int fd, uint16_t *distance_mm)
{
    if (i2c_write_reg8(fd, REG_MEAS_TRIGGER, 0x01) < 0)
        return -1;

    for (int waited = 0; waited < MEAS_TIMEOUT_MS; waited += 5) {
        uint8_t status;
        if (i2c_read_reg8(fd, REG_MEAS_STATUS, &status) < 0)
            return -1;
        if (status & 0x01)
            break;
        usleep(5000);
    }

    if (!(status & 0x01)) {
        fprintf(stderr, "CH-101 measurement timeout\n");
        return -1;
    }

    if (i2c_read_reg16(fd, REG_DIST_HIGH, distance_mm) < 0)
        return -1;

    return 0;
}

static int log_distance(FILE *fp, uint16_t distance_mm)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }
    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }
    if (fprintf(fp, "%s,%u\n", ts, distance_mm) < 0) {
        fprintf(stderr, "fprintf to CSV failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush CSV failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static void cleanup(void)
{
    if (g_csv) {
        fflush(g_csv);
        fclose(g_csv);
        g_csv = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT): %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM): %s\n", strerror(errno));
        return 1;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(%s): %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, CH101_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n",
                CH101_ADDR, strerror(errno));
        cleanup();
        return 1;
    }

    g_csv = fopen(CSV_FILE, "a");
    if (!g_csv) {
        fprintf(stderr, "fopen(%s): %s\n", CSV_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    printf("CH-101 parking sensor logging started. Ctrl+C to stop.\n");

    while (g_running) {
        uint16_t distance_mm;
        if (ch101_read_distance(g_i2c_fd, &distance_mm) == 0) {
            if (log_distance(g_csv, distance_mm) < 0) {
                fprintf(stderr, "Logging failed; continuing.\n");
            }
        } else {
            fprintf(stderr, "Sensor read failed; skipping sample.\n");
        }
        usleep(SAMPLE_MS * 1000);
    }

    printf("\nShutting down cleanly.\n");
    cleanup();
    return 0;
}

