#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define VL53L5CX_ADDR 0x29

#define REG_SOFT_RESET 0x00
#define REG_SYSTEM_START 0x01
#define REG_PHASECAL 0x02
#define REG_RANGE_CONFIG 0x03
#define REG_RANGE_STATUS 0x04
#define REG_DISTANCE_DATA 0x08

#define NUM_ZONES 64

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *value) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read 16-bit from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *value = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

static int vl53l5cx_init(int fd) {
    uint8_t soft_reset_val;
    if (i2c_read_reg8(fd, REG_SOFT_RESET, &soft_reset_val) < 0) {
        return -1;
    }
    if (soft_reset_val != 0x00) {
        fprintf(stderr, "Warning: Soft reset value is 0x%02X, expected 0x00\n", soft_reset_val);
    }
    if (i2c_write_reg8(fd, REG_SOFT_RESET, 0x00) < 0) {
