#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS 1
#define MLX75030_ADDR 0x4C
#define MEASUREMENT_INTERVAL_MS 100
#define MAX_RETRIES 3
#define RETRY_DELAY_US 10000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_distance(int handle, int *distance_out) {
    char cmd = 0x01;
    char buf[2];
    int result;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        result = i2cWriteDevice(handle, &cmd, 1);
        if (result != 0) {
            fprintf(stderr, "I2C write error (attempt %d/%d): %s\n",
                    retries + 1, MAX_RETRIES, strerror(errno));
            retries++;
            if (retries < MAX_RETRIES) {
                gpioDelay(RETRY_DELAY_US);
            }
            continue;
        }

        gpioDelay(1000);

        result = i2cReadDevice(handle, buf, 2);
        if (result != 2) {
            fprintf(stderr, "I2C read error (attempt %d/%d): %s\n",
                    retries + 1, MAX_RETRIES, strerror(errno));
            retries++;
            if (retries < MAX_RETRIES) {
                gpioDelay(RETRY_DELAY_US);
            }
            continue;
        }

        *distance_out = (buf[0] << 8) | buf[1];
        return 0;
    }

    fprintf(stderr, "Failed to read distance after %d retries.\n", MAX_RETRIES);
    return -1;
}

static void log_distance(int distance) {
    struct timespec ts;
    struct tm tm_info;
    char timestamp[32];

    clock_gettime(CLOCK_REALTIME, &ts);
    localtime_r(&ts.tv_sec, &tm_info);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp),
             ".%03ld", ts.tv_nsec / 1000000);

    printf("%s Distance: %d mm\n", timestamp, distance);
    fflush(stdout);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, MLX75030_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at bus %d, addr 0x%02X: %s\n",
                I2C_BUS, MLX75030_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("MLX75030 ToF sensor reader started. Press Ctrl+C to exit.\n");

    while (running) {
        int distance;
        if (read_distance(i2c_handle, &distance) == 0) {
            log_distance(distance);
        } else {
            fprintf(stderr, "Sensor read failed; continuing.\n");
        }
        gpioDelay(MEASUREMENT_INTERVAL_MS * 1000);
    }

    printf("\nShutting down...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

