#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

/* VL53L4CX I2C default address */
#define VL53L4CX_ADDR 0x29

/* VL53L4CX register addresses */
#define REG_SOFT_RESET              0x7FFF
#define REG_SYSTEM_START            0x0009
#define REG_INTERRUPT_STATUS        0x0046
#define REG_RESULT_DISTANCE_HIGH    0x0096
#define REG_RESULT_DISTANCE_LOW     0x0097

#define I2C_BUS 1
#define POLL_DELAY_US 500000
#define SOFT_RESET_DELAY_US 10000

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_byte(int handle, uint16_t reg, uint8_t value)
{
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    if (i2cWriteDevice(handle, buf, 3) != 3) {
        fprintf(stderr, "I2C write failed (reg 0x%04X, val 0x%02X)\n", reg, value);
        return -1;
    }
    return 0;
}

static int i2c_read_byte(int handle, uint16_t reg, uint8_t *value)
{
    char buf[2];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "I2C write (reg select 0x%04X) failed\n", reg);
        return -1;
    }
    if (i2cReadDevice(handle, buf, 1) != 1) {
        fprintf(stderr, "I2C read (reg 0x%04X) failed\n", reg);
        return -1;
    }
    *value = (uint8_t)buf[0];
    return 0;
}

static int vl53l4cx_init(int handle)
{
    if (i2c_write_byte(handle, REG_SOFT_RESET, 0x00) != 0) {
        fprintf(stderr, "Failed to write soft reset\n");
        return -1;
    }
    gpioDelay(SOFT_RESET_DELAY_US);

    if (i2c_write_byte(handle, REG_SYSTEM_START, 0x00) != 0) {
        fprintf(stderr, "Failed to start ranging\n");
        return -1;
    }
    return 0;
}

static int read_distance(int handle, uint16_t *distance_mm)
{
    uint8_t status;
    if (i2c_read_byte(handle, REG_INTERRUPT_STATUS, &status) != 0) {
        return -1;
    }
    if ((status & 0x01) == 0) {
        return 1; /* no new data yet */
    }
    if (i2c_read_byte(handle, REG_RESULT_DISTANCE_HIGH, &status) != 0) {
        return -1;
    }
    if (i2c_read_byte(handle, REG_RESULT_DISTANCE_LOW, &status) != 0) {
        return -1;
    }
    *distance_mm = ((uint16_t)status & 0xFF00) >> 8;
    return 0;
}

static void log_distance(uint16_t distance_mm)
{
    struct timespec ts;
    struct tm tm_info;
    char timestamp[40];

    clock_gettime(CLOCK_REALTIME, &ts);
    localtime_r(&ts.tv_sec, &tm_info);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp),
             ".%06ld", ts.tv_nsec / 1000);

    printf("Timestamp: %s, Distance: %u mm\n", timestamp, distance_mm);
    fflush(stdout);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, VL53L4CX_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%02X: %d\n",
                I2C_BUS, VL53L4CX_ADDR, g_i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (vl53l4cx_init(g_i2c_handle) != 0) {
        fprintf(stderr, "VL53L4CX initialization failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("VL53L4CX ranging started. Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (g_running) {
        uint16_t distance;
        int rc = read_distance(g_i2c_handle, &distance);
        if (rc == 0) {
            log_distance(distance);
        } else if (rc < 0) {
            fprintf(stderr, "I2C read error, continuing...\n");
        }
        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    i2cClose(g_i2c_handle);
    gpioTerminate();
    return 0;
}

