#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define BUZZER_GPIO 22
#define DISTANCE_THRESHOLD 100
#define POLL_DELAY_US 500000

/* VL53L1X register addresses (16-bit, big-endian on bus) */
#define REG_SOFT_RESET              0x0001
#define REG_I2C_SLAVE__DEVICE_ADDRESS 0x0001
#define REG_SYSTEM__MODE_START      0x0007
#define REG_RESULT__FINAL_CROSSTALK_CORRECTED_DISTANCE_MM 0x0096

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_word(int handle, uint16_t reg, uint16_t value) {
    char buf[4];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = (value >> 8) & 0xFF;
    buf[3] = value & 0xFF;
    return i2cWriteDevice(handle, buf, 4);
}

static int i2c_read_word(int handle, uint16_t reg, uint16_t *value) {
    char reg_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, reg_buf, 2) != 0) return -1;
    char data[2];
    if (i2cReadDevice(handle, data, 2) != 2) return -1;
    *value = ((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1];
    return 0;
}

static int vl53l1x_init(int handle) {
    if (i2c_write_word(handle, REG_SOFT_RESET, 0x00) != 0) {
        fprintf(stderr, "Error: Failed to write SOFT_RESET (sensor absent or bus error)\n");
        return -1;
    }
    gpioDelay(10000);
    if (i2c_write_word(handle, REG_SOFT_RESET, 0x01) != 0) {
        fprintf(stderr, "Error: Failed to write SOFT_RESET (sensor absent or bus error)\n");
        return -1;
    }
    gpioDelay(10000);
    if (i2c_write_word(handle, REG_I2C_SLAVE__DEVICE_ADDRESS, VL53L1X_ADDR) != 0) {
        fprintf(stderr, "Error: Failed to write I2C_SLAVE__DEVICE_ADDRESS\n");
        return -1;
    }
    if (i2c_write_word(handle, REG_SYSTEM__MODE_START, 0x00) != 0) {
        fprintf(stderr, "Error: Failed to write SYSTEM__MODE_START\n");
        return -1;
    }
    return 0;
}

static int vl53l1x_read_distance(int handle, uint16_t *distance_mm) {
    if (i2c_write_word(handle, REG_SYSTEM__MODE_START, 0x01) != 0) {
        fprintf(stderr, "Error: Failed to start ranging\n");
        return -1;
    }
    gpioDelay(10000);
    uint16_t raw;
    if (i2c_read_word(handle, REG_RESULT__FINAL_CROSSTALK_CORRECTED_DISTANCE_MM, &raw) != 0) {
        fprintf(stderr, "Error: Failed to read distance register\n");
        return -1;
    }
    *distance_mm = raw;
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(BUZZER_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d at address 0x%02X (code %d)\n",
                I2C_BUS, VL53L1X_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (vl53l1x_init(i2c_handle) != 0) {
        fprintf(stderr, "Error: VL53L1X initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);
    gpioWrite(BUZZER_GPIO, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("VL53L1X ranging started. Press Ctrl+C to exit.\n");

    while (running) {
        uint16_t distance;
        if (vl53l1x_read_distance(i2c_handle, &distance) == 0) {
            printf("Distance: %u mm\n", distance);
            if (distance < DISTANCE_THRESHOLD) {
                gpioWrite(BUZZER_GPIO, 1);
            } else {
                gpioWrite(BUZZER_GPIO, 0);
            }
        } else {
            fprintf(stderr, "Warning: I2C read error, re-initialising sensor...\n");
            i2cClose(i2c_handle);
            i2c_handle = -1;
            gpioDelay(100000);
            i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error: Failed to re-open I2C bus (code %d)\n", i2c_handle);
                break;
            }
            if (vl53l1x_init(i2c_handle) != 0) {
                fprintf(stderr, "Error: VL53L1X re-initialisation failed\n");
                break;
            }
        }
        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

