#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/ipc.h>
#include <sys/msg.h>
#include <pigpio.h>

#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define BUZZER_GPIO 23
#define MSG_QUEUE_NAME "/vl53l1x_queue"
#define DISTANCE_THRESHOLD 100
#define POLL_INTERVAL_US 50000

/* VL53L1X register addresses */
#define VL53L1X_REG_SOFT_RESET      0x0000
#define VL53L1X_REG_MODEL_ID        0x010F
#define VL53L1X_REG_SYSTEM_THRESH   0x0089
#define VL53L1X_REG_RANGE_STATUS    0x0089
#define VL53L1X_REG_RESULT_DIST     0x0096
#define VL53L1X_REG_SYSTEM_START    0x0080

#define VL53L1X_MODEL_ID_EXPECTED  0xEA

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static int mq_id = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg16(int handle, uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    if (i2cWriteDevice(handle, buf, 3) != 3) {
        fprintf(stderr, "I2C write to reg 0x%04X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int handle, uint16_t reg, uint8_t *buf, int len) {
    char reg_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, reg_buf, 2) != 2) {
        fprintf(stderr, "I2C write (reg select 0x%04X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (i2cReadDevice(handle, (char *)buf, len) != len) {
        fprintf(stderr, "I2C read from reg 0x%04X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int vl53l1x_init(int handle) {
    uint8_t model_id = 0;
    if (i2c_read_reg16(handle, VL53L1X_REG_MODEL_ID, &model_id, 1) != 0) {
        fprintf(stderr, "Failed to read model ID\n");
        return -1;
    }
    if (model_id != VL53L1X_MODEL_ID_EXPECTED) {
        fprintf(stderr, "Unexpected model ID: 0x%02X (expected 0x%02X)\n", model_id, VL53L1X_MODEL_ID_EXPECTED);
        return -1;
    }
    printf("VL53L1X detected (model ID 0x%02X)\n", model_id);

    /* Software reset: write 0x00 then 0x01 to register 0x0000 */
    if (i2c_write_reg16(handle, VL53L1X_REG_SOFT_RESET, 0x00) != 0) return -1;
    gpioDelay(1000);
    if (i2c_write_reg16(handle, VL53L1X_REG_SOFT_RESET, 0x01) != 0) return -1;
    gpioDelay(1000);

    /* Timing budget: 50 ms (0x0034) */
    if (i2c_write_reg16(handle, 0x0001, 0x34) != 0) return -1;

    /* Start ranging */
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_START, 0x01) != 0) return -1;

    return 0;
}

static int read_distance(int handle) {
    uint8_t status = 0;
    if (i2c_read_reg16(handle, VL53L1X_REG_RANGE_STATUS, &status, 1) != 0) return -1;
    if ((status & 0x01) == 0) {
        return -1; /* Not ready yet */
    }

    uint8_t dist_buf[2];
    if (i2c_read_reg16(handle, VL53L1X_REG_RESULT_DIST, dist_buf, 2) != 0) return -1;
    return (dist_buf[0] << 8) | dist_buf[1];
}

static void log_distance(int distance) {
    char msg[128];
    snprintf(msg, sizeof(msg), "Distance: %d mm", distance);
    if (msgq_send(mq_id, msg, strlen(msg), 0) == -1) {
        fprintf(stderr, "msgq_send failed: %s\n", strerror(errno));
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X: %s\n", I2C_BUS, VL53L1X_ADDR, strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (vl53l1x_init(i2c_handle) != 0) {
        fprintf(stderr, "VL53L1X initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    mq_id = msgq_open(MSG_QUEUE_NAME, IPC_CREAT | 0666, 0666, 0);
    if (mq_id == -1) {
        fprintf(stderr, "Failed to create message queue: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);
    gpioWrite(BUZZER_GPIO, 0);

    printf("Starting distance monitoring (threshold: %d mm)...\n", DISTANCE_THRESHOLD);

    while (running) {
        int distance = read_distance(i2c_handle);
        if (distance >= 0) {
            log_distance(distance);
            if (distance < DISTANCE_THRESHOLD) {
                gpioWrite(BUZZER_GPIO, 1);
            } else {
                gpioWrite(BUZZER_GPIO, 0);
            }
        } else {
            fprintf(stderr, "Failed to read distance\n");
            gpioWrite(BUZZER_GPIO, 0);
        }
        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    gpioWrite(BUZZER_GPIO, 0);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    if (mq_id >= 0) msgq_close(mq_id);
    gpioTerminate();
    return 0;
}

