#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    27
#define BUZZER_PIN  22

#define SPEED_OF_SOUND 34300.0   /* cm/s */
#define MIN_DISTANCE   2.0       /* cm */
#define MAX_DISTANCE  400.0     /* cm */
#define DISTANCE_THRESHOLD 30.0 /* cm */
#define TRIGGER_PULSE_US 10
#define ECHO_TIMEOUT_US  30000   /* 30 ms max echo wait */
#define LOOP_DELAY_US   100000  /* 100 ms */

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

/*
 * pigpio alert callback for the echo pin.
 * level: 0 = falling edge, 1 = rising edge, 2 = timeout
 * tick:  32-bit microsecond counter that wraps every ~71.6 min
 */
static void echo_callback(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)userdata;

    static uint32_t start_tick = 0;
    static int      have_start = 0;

    if (level == 1) {
        /* Rising edge: echo pulse starts */
        start_tick = tick;
        have_start = 1;
    } else if (level == 0) {
        /* Falling edge: echo pulse ends */
        if (have_start) {
            uint32_t duration = tick - start_tick;  /* handles wraparound */
            double distance = (duration * SPEED_OF_SOUND) / 2000000.0;

            printf("Distance: %.2f cm\n", distance);

            if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
                printf("Warning: distance out of range (%.2f cm)\n", distance);
            }

            if (distance < DISTANCE_THRESHOLD) {
                gpioWrite(BUZZER_PIN, 1);
            } else {
                gpioWrite(BUZZER_PIN, 0);
            }
            have_start = 0;
        }
    }
}

int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO modes --- */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set TRIGGER_PIN %d as output.\n", TRIGGER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set ECHO_PIN %d as input.\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set BUZZER_PIN %d as output.\n", BUZZER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts LOW */
    gpioWrite(TRIGGER_PIN, 0);
    gpioWrite(BUZZER_PIN, 0);

    /* --- Register echo interrupt callback --- */
    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) != 0) {
        fprintf(stderr, "Error: failed to register alert function on ECHO_PIN %d.\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Install signal handler for graceful shutdown --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Parking sensor started. Press Ctrl+C to exit.\n");

