/*
 * HC-SR04 Ultrasonic Distance Measurement — Raspberry Pi 4 Model B
 * Library: pigpio (modern, actively maintained)
 *
 * Wiring:
 *   TRIG -> GPIO 23 (physical pin 16, BCM 23, output)
 *   ECHO -> GPIO 24 (physical pin 18, BCM 24, input) via voltage divider
 *   3.3 V supply, 5 V ECHO output assumed to be on a 5 V-to-3.3 V divider
 *
 * Build:  gcc -O2 -Wall -o hcsr04 hcsr04.c -lpigpio -lrt
 * Run:    sudo ./hcsr04
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define TRIG_PIN          23
#define ECHO_PIN          24
#define SPEED_OF_SOUND_CM_PER_US 0.0343   /* 343 m/s in cm/us */
#define MIN_PULSE_US       100          /* noise / timeout floor */
#define MAX_PULSE_US       30000        /* HC-SR04 max range ~400 cm */
#define LOG_FILE          "distance_log.txt"
#define SAMPLE_PERIOD_US  200000       /* 5 Hz */
#define TRIGGER_PULSE_US  10           /* 10 us trigger pulse */
#define ECHO_TIMEOUT_US   60000        /* 60 ms max echo wait */

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Echo alert callback (rising/falling edge)                            */
/* ------------------------------------------------------------------ */
static void echo_callback(int gpio, int level, uint32_t tick)
{
    (void)gpio;

    static uint32_t last_tick = 0;
    static bool      have_rising = false;
    static bool      have_falling = false;

    if (level == 1) {
        /* Rising edge — start of echo pulse */
        have_rising = true;
        last_tick   = tick;
    } else if (level == 0) {
        /* Falling edge — end of echo pulse */
        have_falling = true;
    }

    /* If both edges are captured, compute and validate the pulse */
    if (have_rising && have_falling) {
        uint32_t pulse_us = falling_tick - last_tick;   /* handles 32-bit wrap */
        have_rising   = false;
        have_falling  = false;

        if (pulse_us >= MIN_PULSE_US && pulse_us <= MAX_PULSE_US) {
            double distance_cm = (double)pulse_us * SPEED_OF_SOUND_CM_PER_US / 2.0;
            time_t now = time(NULL);
            struct tm tm_buf;
            struct tm *t = localtime_r(&now, &tm_buf);
            char ts[32];
            if (t) {
                strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
            } else {
                snprintf(ts, sizeof(ts), "unknown-time");
            }

            printf("[%s] Distance: %.2f cm\n", ts, distance_cm);

            if (g_log_fp) {
                fprintf(g_log_fp, "%s,%.2f\n", ts, distance_cm);
                fflush(g_log_fp);
            }
        } else {
            fprintf(stderr, "Warning: invalid pulse %u us (out of range %d-%d)\n",
                    pulse_us, MIN_PULSE_US, MAX_PULSE_US);
            if (g_log_fp) {
                fprintf(g_log_fp, "%s,INVALID\n", ts);
                fflush(g_log_fp);
            }
        }
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (code %d).\n",
                gpioInitialise());
        return EXIT_FAILURE;
    }

    /* --- open log file --- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        perror("Error: cannot open log file '" LOG_FILE "'");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- configure GPIO --- */
    if (gpioSetMode(TRIG_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: cannot set TRIG_PIN %d as output.\n", TRIG_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: cannot set ECHO_PIN %d as input.\n", ECHO_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Warning: cannot set pull-down on ECHO_PIN %d.\n", ECHO_PIN);
    }

    /* Ensure trigger starts LOW */
    if (gpioWrite(TRIG_PIN, 0) < 0) {
        fprintf(stderr, "Error: cannot initialise TRIG_PIN %d LOW.\n", TRIG_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioDelay(1000);  /* 1 ms settle */

    /* --- register alert callback --- */
    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) < 0) {
        fprintf(stderr, "Error: cannot register alert on ECHO_PIN %d.\n", ECHO_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("HC-SR04 distance measurement started.\n");
    printf("TRIG=GPIO%d, ECHO=GPIO%d, log= '%s'\n", TRIG_PIN, ECHO_PIN, LOG_FILE);
    printf("Press Ctrl+C to exit.\n");

    /* --- main loop --- */
    while (g_running) {
        /* Generate 10 us trigger pulse */
        if (gpioWrite(TRIG_PIN, 1) < 0) {
            fprintf(stderr, "Error: gpioWrite(TRIG, 1) failed.\n");
            break;
        }
        gpioDelay(TRIGGER_PULSE_US);
        if (gpioWrite(TRIG_PIN, 0) < 0) {
            fprintf(stderr, "Error: gpioWrite(TRIG, 0) failed.\n");
            break;
        }

        /* Wait for echo with timeout (poll every 1 ms) */
        uint32_t start_tick = gpioTick();
        bool got_rising = false;
        bool got_falling = false;

        for (int i = 0; i < ECHO_TIMEOUT_US / 1000 && g_running; i++) {
            gpioDelay(1000);  /* 1 ms */
            if (gpioRead(ECHO_PIN) == 1) {
                got_rising = true;
            }
        }

        if (!got_rising) {
            fprintf(stderr, "Warning: echo never went HIGH (timeout).\n");
            if (g_log_fp) {
                fprintf(g_log_fp, "TIMEOUT\n");
                fflush(g_log_fp);
            }
            continue;
        }

        /* Wait for falling edge with timeout */
        for (int i = 0; i < ECHO_TIMEOUT_US / 1000 && g_running; i++) {
            gpioDelay(1000);
            if (gpioRead(ECHO_PIN) == 0) {
                got_falling = true;
                break;
            }
        }

        if (!got_falling) {
            fprintf(stderr, "Warning: echo stuck HIGH (timeout).\n");
            if (g_log_fp) {
                fprintf(g_log_fp, "TIMEOUT\n");
                fflush(g_log_fp);
            }
            continue;
        }

        /* Compute pulse width (handles 32-bit tick wraparound) */
        uint32_t pulse_us = gpioTick() - start_tick;  /* pigpio tick is uint32_t */
        if (pulse_us < MIN_PULSE_US || pulse_us > MAX_PULSE_US) {
            fprintf(stderr, "Warning: pulse %u us out of range [%d, %d].\n",
                    pulse_us, MIN_PULSE_US, MAX_PULSE_US);
            if (g_log_fp) {
                fprintf(g_log_fp, "INVALID\n");
                fflush(g_log_fp);
            }
            continue;
        }

        /* Valid reading — already logged by callback */
    }

    /* --- graceful shutdown --- */
    printf("\nShutting down...\n");
    gpioSetAlertFuncEx(ECHO_PIN, NULL, NULL);   /* unregister callback */
    gpioWrite(TRIG_PIN, 0);
    cleanup();
    return EXIT_SUCCESS;
}

