#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define SERVO_PIN 18
#define SHUTDOWN_PIN 23
#define INTERRUPT_PIN 24
#define DISTANCE_THRESHOLD_CLOSE 50
#define DISTANCE_THRESHOLD_OPEN 60
#define LOG_FILE "parking_log.txt"

#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x010F
#define VL53L1X_REG_SYSRANGE_START 0x0000
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0089
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0096

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg16(int handle, uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    return i2cWriteDevice(handle, buf, 3);
}

static int i2c_read_reg16(int handle, uint16_t reg, uint8_t *buf, uint32_t len) {
    char reg_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, reg_buf, 2) < 0) return -1;
    return i2cReadDevice(handle, (char *)buf, len);
}

static int vl53l1x_init(int handle) {
    uint8_t model_id = 0;
    if (i2c_read_reg16(handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID, &model_id, 1) < 0) {
        fprintf(stderr, "Error: Failed to read VL53L1X model ID.\n");
        return -1;
    }
    if (model_id != 0xEA) {
        fprintf(stderr, "Error: Invalid VL53L1X model ID: 0x%02X (expected 0xEA).\n", model_id);
        return -1;
    }
    if (i2c_write_reg16(handle, 0x0000, 0x00) < 0) return -1;
    gpioDelay(10000);
    return 0;
}

static int vl53l1x_read_distance(int handle, int *distance_mm) {
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSRANGE_START, 0x01) < 0) return -1;
    gpioDelay(10000);
    uint8_t status = 0;
    if (i2c_read_reg16(handle, VL53L1X_REG_RESULT_RANGE_STATUS, &status, 1) < 0) return -1;
    if (status & 0x01) {
        uint8_t data[2];
        if (i2c_read_reg16(handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0, data, 2) < 0) return -1;
        *distance_mm = (data[0] << 8) | data[1];
