#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define TRIGGER_PIN 24
#define MOTOR_FORWARD_PIN 17
#define MOTOR_BACKWARD_PIN 18
#define DISTANCE_THRESHOLD_LOW 100   /* mm (10 cm) */
#define DISTANCE_THRESHOLD_HIGH 300 /* mm (30 cm) */
#define POLL_TIMEOUT_MS 100
#define I2C_RETRY_COUNT 3
#define I2C_RETRY_DELAY_BASE_US 1000
#define MEASUREMENT_WAIT_US 5000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/* Write a 16-bit register address and an 8-bit value via I2C retry. */
static int vl53l1x_write_reg8(int handle, uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    for (int attempt = 0; attempt < I2C_RETRY_COUNT; attempt++) {
        int rc = i2cWriteDevice(handle, buf, 3);
        if (rc == 0) return 0;
        fprintf(stderr, "I2C write to reg 0x%04X failed (attempt %d): rc=%d\n",
                reg, attempt + 1, rc);
        if (attempt < I2C_RETRY_COUNT - 1)
            gpioDelay(I2C_RETRY_DELAY_BASE_US * (1 << attempt));
    }
    return -1;
}

/* Read an 8-bit register via I2C retry. */
static int vl53l1x_read_reg8(int handle, uint16_t reg, uint8_t *value) {
    char reg_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;
    for (int attempt = 0; attempt < I2C_RETRY_COUNT; attempt++) {
        if (i2cWriteDevice(handle, reg_buf, 2) != 0) {
            fprintf(stderr, "I2C write (reg select 0x%04X) failed (attempt %d)\n",
                    reg, attempt + 1);
            if (attempt < I2C_RETRY_COUNT - 1)
                gpioDelay(I2C_RETRY_DELAY_BASE_US * (1 << attempt));
            continue;
        }
        char data;
        if (i2cReadDevice(handle, &data, 1) != 1) {
            fprintf(stderr, "I2C read from reg 0x%04X failed (attempt %d)\n",
                    reg, attempt + 1);
            if (attempt < I2C_RETRY_COUNT - 1)
                gpioDelay(I2C_RETRY_DELAY_BASE_US * (1 << attempt));
            continue;
        }
        *value = (uint8_t)data;
        return 0;
    }
    return -1;
}

/* Read a 16-bit register (little-endian) via I2C retry. */
static int vl53l1x_read_reg16(int handle, uint16_t reg, uint16_t *value) {
    char reg_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;
    for (int attempt = 0; attempt < I2C_RETRY_COUNT; attempt++) {
        if (i2cWriteDevice(handle, reg_buf, 2) != 0) {
            fprintf(stderr, "I2C write (reg select 0x%04X) failed (attempt %d)\n",
                    reg, attempt + 1);
            if (attempt < I2C_RETRY_COUNT - 1)
                gpioDelay(I2C_RETRY_DELAY_BASE_US * (1 << attempt));
            continue;
        }
        char data[2];
        if (i2cReadDevice(handle, data, 2) != 2) {
            fprintf(stderr, "I2C read from reg 0x%04X failed (attempt %d)\n",
                    reg, attempt + 1);
            if (attempt < I2C_RETRY_COUNT - 1)
                gpioDelay(I2C_RETRY_DELAY_BASE_US * (1 << attempt));
            continue;
        }
        *value = (uint16_t)((uint8_t)data[1] << 8) | (uint8_t)data[0];
        return 0;
    }
    return -1;
}

/* Trigger a single distance measurement on the VL53L1X. */
static int vl53l1x_trigger_measurement(int handle) {
    if (vl53l1x_write_reg8(handle, 0x0000, 0x00) != 0) {
        fprintf(stderr, "Error: failed to write soft reset register\n");
        return -1;
    }
    gpioDelay(1000); /* 1 ms */

    if (vl53l1x_write_reg8(handle, 0x0000, 0x01) != 0) {
        fprintf(stderr, "Error: failed to start measurement\n");
        return -1;
    }
    return 0;
}

/* Poll the data-ready bit (register 0x0089) until it is set. */
static int vl53l1x_wait_data_ready(int handle) {
    uint8_t ready = 0xFF;
    for (int i = 0; i < POLL_TIMEOUT_MS; i++) {
        if (vl53l1x_read_reg8(handle, 0x0089, &ready) != 0) {
            fprintf(stderr, "Error: failed to poll data-ready bit\n");
            return -1;
        }
        if (ready & 0x01) return 0;
        gpioDelay(1000); /* 1 ms */
    }
    fprintf(stderr, "Error: data-ready timeout\n");
    return -1;
}

/* Read the 16-bit distance register (0x0096-0x0097). */
static int vl53l1x_read_distance(int handle, uint16_t *distance_mm) {
    if (vl53l1x_wait_data_ready(handle) != 0) return -1;
    if (vl53l1x_read_reg16(handle, 0x0096, distance_mm) != 0) {
        fprintf(stderr, "Error: failed to read distance register\n");
        return -1;
    }
    return 0;
}

static void motor_forward(void) {
    gpioWrite(MOTOR_FORWARD_PIN, 1);
    gpioWrite(MOTOR_BACKWARD_PIN, 0);
}

static void motor_backward(void) {
    gpioWrite(MOTOR_FORWARD_PIN, 0);
    gpioWrite(MOTOR_BACKWARD_PIN, 1);
}

static void motor_stop(void) {
    gpioWrite(MOTOR_FORWARD_PIN, 0);
    gpioWrite(MOTOR_BACKWARD_PIN, 0);
}

static void motor_control(uint16_t distance_mm) {
    if (distance_mm < DISTANCE_THRESHOLD_LOW) {
        motor_forward();
        printf("Distance: %u mm - Motor: FORWARD\n", distance_mm);
    } else if (distance_mm > DISTANCE_THRESHOLD_HIGH) {
        motor_backward();
        printf("Distance: %u mm - Motor: BACKWARD\n", distance_mm);
    } else {
        motor_stop();
        printf("Distance: %u mm - Motor: STOP\n", distance_mm);
    }
}

static void trigger_callback(int gpio, int level, uint32_t tick) {
    (void)gpio; (void)tick;
    if (level == 1) {
        printf("Triggered - Starting measurement...\n");
        if (vl53l1x_trigger_measurement(i2c_handle) != 0) {
            motor_stop();
            fprintf(stderr, "Sensor error - stopping motor\n");
            return;
        }
        uint16_t distance = 0;
        if (vl53l1x_read_distance(i2c_handle, &distance) != 0) {
