int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at bus %d addr 0x%02X: %d\n",
                I2C_BUS, VL53L1X_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
