        gpioTerminate();
        return EXIT_FAILURE;
    }
    motor_stop();

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioSetISRFuncEx(TRIGGER_PIN, RISING_EDGE, 0, trigger_callback, NULL) != 0) {
        fprintf(stderr, "Error setting ISR for trigger pin\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("VL53L1X distance sensor interface started. Press Ctrl+C to exit.\n");

    while (running) {
        gpioDelay(100000); /* 100 ms */
    }

    printf("\nShutting down...\n");
    motor_stop();
    gpioSetISRFuncEx(TRIGGER_PIN, RISING_EDGE, 0, NULL, NULL);
