#include <linux/i2c-dev.h>
#include <gpiod.h>

#define MPR121_ADDR 0x5A
#define I2C_BUS "/dev/i2c-1"
#define GPIO_CHIP "gpiochip0"
#define LED1_PIN 17
#define LED2_PIN 18
#define LED3_PIN 27
#define LED4_PIN 22

#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ELECONFIG0 0x5E
#define MPR121_MHDR 0x2B
#define MPR121_NHDR 0x2C
#define MPR121_NCLR 0x2D
#define MPR121_FDLR 0x2E
#define MPR121_NHDF 0x2F
#define MPR121_NHDF2 0x30
#define MPR121_NHDF3 0x31
#define MPR121_NHDT 0x32
#define MPR121_NHDT2 0x33
#define MPR121_NHDT3 0x34
#define MPR121_FDLF 0x35
#define MPR121_FDLF2 0x36
#define MPR121_FDLF3 0x37
#define MPR121_NHDT 0x38
#define MPR121_NHDT2 0x39
#define MPR121_NHDT3 0x3A
#define MPR121_NCLR2 0x3B
#define MPR121_NCLR3 0x3C
#define MPR121_FDLR2 0x3D
#define MPR121_E0TTH 0x41
#define MPR121_E0RTH 0x42
#define MPR121_DEBOUNCE 0x5B
#define MPR121_CONFIG1 0x5C
#define MPR121_CONFIG2 0x5D
#define MPR121_CONFIG3 0x5E
#define MPR121_CONFIG4 0x5F
#define MPR121_SOFTRESET 0x80

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *led_lines[4] = {NULL};
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *msg) {
    if (!log_fp) return;
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    fprintf(log_fp, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
    fflush(log_fp);
}

static int i2c_write_reg(uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(i2c_fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg(uint8_t reg, uint8_t *val) {
    if (write(i2c_fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(i2c_fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int mpr121_init(void) {
    if (i2c_write_reg(MPR121_SOFTRESET, 0x63) < 0) return -1;
    usleep(10000);

    uint8_t part_id;
    if (i2c_read_reg(0x00, &part_id) < 0) return -1;
    if (part_id != 0x5A) {
        fprintf(stderr, "MPR121 not found (part_id=0x%02X, expected 0x%02X)\n", part_id, MPR121_ADDR);
        return -1;
    }

    if (i2c_write_reg(MPR121_ELECONFIG0, 0x00) < 0) return -1;
    if (i2c_write_reg(MPR121_MHDR, 0x01) < 0) return -1;
    if (i2c_write_reg(MPR121_NHDR, 0x01) < 0) return -1;
    if (i2c_write_reg(MPR121_NCLR, 0x0E) < 0) return -1;
    if (i2c_write_reg(MPR121_FDLR, 0x00) < 0) return -1;
    if (i2c_write_reg(MPR121_NHDF, 0x01) < 0) return -1;
    if (i2c_write_reg(MPR121_NHDF2, 0x01) < 0) return -1;
    if (i2c_write_reg(MPR121_NHDF3, 0x00) < 0) return -1;
    if (i2c_write_reg(MPR121_NHDT, 0x00) < 0) return -1;
    if (i2c_write_reg(MPR121_NHDT2, 0x00) < 0) return -1;
    if (i2c_write_reg(MPR121_NHDT3, 0x00) < 0) return -1;
    if (i2c_write_reg(MPR121_FDLF, 0x00) < 0) return -1;
    if (i2c_write_reg(MPR121_FDLF2, 0x00) < 0) return -1;
    if (i2c_write_reg(MPR121_FDLF3, 0x00) < 0) return -1;
    if (i2c_write_reg(MPR121_NHDT, 0x00) < 0) return -1;
    if (i2c_write_reg(MPR121_NHDT2, 0x00) < 0) return -1;
    if (i2c_write_reg(MPR121_NHDT3, 0x00) < 0) return -1;
    if (i2c_write_reg(MPR121_NCLR2, 0x00) < 0) return -1;
    if (i2c_write_reg(MPR121_NCLR3, 0x00) < 0) return -1;
    if (i2c_write_reg(MPR121_FDLR2, 0x00) < 0) return -1;

    if (i2c_write_reg(MPR121_E0TTH, 0x0B) < 0) return -1;
    if (i2c_write_reg(MPR121_E0RTH, 0xC8) < 0) return -1;
    if (i2c_write_reg(MPR121_DEBOUNCE, 0x00) < 0) return -1;
    if (i2c_write_reg(MPR121_CONFIG1, 0x10) < 0) return -1;
    if (i2c_write_reg(MPR121_CONFIG2, 0x20) < 0) return -1;
    if (i2c_write_reg(MPR121_CONFIG3, 0x04) < 0) return -1;
    if (i2c_write_reg(MPR121_CONFIG4, 0x02) < 0) return -1;

    if (i2c_write_reg(MPR121_ELECONFIG0, 0x0C) < 0) return -1;
    return 0;
}

static void set_led_pattern(uint8_t pattern) {
    for (int i = 0; i < 4; i++) {
        if (led_lines[i]) {
            gpiod_line_set_value(led_lines[i], (pattern >> i) & 1);
        }
    }
}

static void cleanup(void) {
    for (int i = 0; i < 4; i++) {
        if (led_lines[i]) {
            gpiod_line_set_value(led_lines[i], 0);
            gpiod_line_release(led_lines[i]);
            led_lines[i] = NULL;
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (log_fp) {
        log_event("Program terminated.");
        fclose(log_fp);
        log_fp = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    log_fp = fopen("art_log.txt", "a");
    if (!log_fp) {
        perror("fopen art_log.txt");
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("open I2C bus");
        cleanup();
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPR121_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
