            cleanup();
            return 1;
        }
        if (gpiod_line_request_output(led_lines[i], "mpr121_art", 0) < 0) {
            fprintf(stderr, "gpiod_line_request_output(%d) failed\n", led_pins[i]);
            cleanup();
            return 1;
        }
    }

    if (mpr121_init() < 0) {
        fprintf(stderr, "MPR121 initialization failed.\n");
        cleanup();
        return 1;
    }

    log_event("MPR121 initialized successfully.");

    while (running) {
        uint8_t lo, hi;
        if (i2c_read_reg(MPR121_TOUCHSTATUS_L, &lo) < 0 ||
            i2c_read_reg(MPR121_TOUCHSTATUS_H, &hi) < 0) {
            log_event("I2C read error from touch status registers.");
            usleep(100000);
            continue;
        }

        uint16_t touch_status = (hi << 8) | lo;
        char msg[128];
        snprintf(msg, sizeof(msg), "Touch status: 0x%04X", touch_status);
        log_event(msg);

        if (touch_status == 0) {
            snprintf(msg, sizeof(msg), "No electrodes touched.");
            log_event(msg);
        }

        uint8_t pattern = 0;
        for (int i = 0; i < 12; i++) {
            if (touch_status & (1 << i)) {
                pattern |= (1 << i);
            }
        }

        set_led_pattern(pattern);
        usleep(50000);
    }

    cleanup();
    return 0;
}

