#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18
#define LOG_FILE    "distance_log.txt"
#define TIMEOUT_US  30000   /* 30 ms timeout for echo rising/falling edges */
#define TRIGGER_US  10      /* 10 us trigger pulse width */
#define ECHO_US     5       /* 5 us echo pulse width */
#define MIN_DISTANCE_CM 2.0
#define MAX_DISTANCE_CM 400.0
#define SPEED_OF_SOUND_CM_PER_US 0.0343

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static int log_distance(FILE *fp, double distance_cm)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (gmtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "gmtime_r failed: %s\n", strerror(errno));
        return -1;
    }
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s, Distance: %.2f cm\n", timestamp, distance_cm) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int wait_for_value(struct gpiod_line *line, int value, int timeout_us)
{
    struct timespec start, now;
    int ret;

    clock_gettime(CLOCK_MONOTONIC, &start);
    do {
        ret = gpiod_line_get_value(line);
        if (ret < 0) {
            fprintf(stderr, "gpiod_line_get_value failed: %s\n", strerror(errno));
            return -1;
        }
        if (clock_gettime(CLOCK_MONOTONIC, &now) == -1) {
            fprintf(stderr, "clock_gettime failed: %s\n", strerror(errno));
            return -1;
        }
        long elapsed_us = (now.tv_sec - start.tv_sec) * 1000000L +
                          (now.tv_nsec - start.tv_nsec) / 1000L;
        if (elapsed_us >= timeout_us)
            return 0;  /* timeout */
    } while (ret == value);
    return -1;  /* never reached */
}

static double measure_distance(struct gpiod_line *trigger, struct gpiod_line *echo)
{
    int ret;

    /* Ensure trigger is low before starting */
    ret = gpiod_line_set_value(trigger, 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to set trigger low: %s\n", strerror(errno));
        return -1.0;
    }
    usleep(5);

    /* 10 us trigger pulse */
    ret = gpiod_line_set_value(trigger, 1);
    if (ret < 0) {
        fprintf(stderr, "Failed to set trigger high: %s\n", strerror(errno));
        return -1.0;
    }
    usleep(TRIGGER_US);
    ret = gpiod_line_set_value(trigger, 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to set trigger low: %s\n", strerror(errno));
        return -1.0;
    }

    /* Wait for echo rising edge */
    if (wait_for_value(echo, 1, TIMEOUT_US) < 0) {
        fprintf(stderr, "Timeout waiting for echo rising edge (sensor absent?)\n");
        return -1.0;
    }

    /* Measure echo pulse width */
    struct timespec start, end;
    clock_gettime(CLOCK_MONOTONIC, &start);
    if (wait_for_value(echo, 0, TIMEOUT_US) < 0) {
        fprintf(stderr, "Timeout waiting for echo falling edge\n");
        return -1.0;
    }
    clock_gettime(CLOCK_MONOTONIC, &end);

    long pulse_us = (end.tv_sec - start.tv_sec) * 1000000L +
                    (end.tv_nsec - start.tv_nsec) / 1000L;
    double distance_cm = (double)pulse_us * SPEED_OF_SOUND_CM_PER_US / 2.0;

    if (distance_cm < MIN_DISTANCE_CM || distance_cm > MAX_DISTANCE_CM) {
        fprintf(stderr, "Distance %.2f cm out of range [%.1f, %.1f]\n",
                distance_cm, MIN_DISTANCE_CM, MAX_DISTANCE_CM);
        return -1.0;
    }
    return distance_cm;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trigger = NULL;
    struct gpiod_line *echo = NULL;
    FILE *log_fp = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    trigger = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (trigger == NULL) {
        fprintf(stderr, "Failed to get trigger line %d: %s\n", TRIGGER_PIN, strerror(errno));
        goto cleanup;
    }

    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (echo == NULL) {
        fprintf(stderr, "Failed to get echo line %d: %s\n", ECHO_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(trigger, "hc-sr04-trigger", 0) < 0) {
        fprintf(stderr, "Failed to request trigger line as output: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input(echo, "hc-sr04-echo") < 0) {
        fprintf(stderr, "Failed to request echo line as input: %s\n", strerror(errno));
        goto cleanup;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        fprintf(stderr, "Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        goto cleanup;
    }

    printf("HC-SR04 distance measurement started. Press Ctrl+C to exit.\n");

    while (program_running) {
        double distance = measure_distance(trigger, echo);

        if (distance < 0.0) {
            fprintf(stderr, "Measurement failed; logging error.\n");
            if (log_distance(log_fp, -1.0) < 0)
                fprintf(stderr, "Failed to log error.\n");
        } else {
            if (log_distance(log_fp, distance) < 0)
                fprintf(stderr, "Failed to log distance.\n");
        }

        sleep(1);
    }

    printf("\nExiting cleanly.\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (trigger != NULL)
        gpiod_line_release(trigger);
    if (echo != NULL)
        gpiod_line_release(echo);
    if (chip != NULL)
        gpiod_chip_close(chip);
    if (log_fp != NULL)
        fclose(log_fp);

    return ret;
}

