#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18
#define LOG_FILE    "distance_log.txt"
#define TRIGGER_US  10
#define SAMPLE_US   1000000
#define MIN_PULSE_US 58
#define MAX_PULSE_US 25000

static volatile sig_atomic_t g_running = 1;
static volatile uint32_t g_start_tick = 0;
static volatile uint32_t g_pulse_us    = 0;
static volatile int      g_echo_seen   = 0;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void echo_callback(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)userdata;

    if (level == 1) {
        g_start_tick = tick;
        g_echo_seen  = 0;
    } else if (level == 0 && g_start_tick != 0) {
        uint32_t diff = tick - g_start_tick; /* handles 32-bit wrap */
        g_pulse_us  = diff;
        g_start_tick = 0;
        g_echo_seen  = 1;
    }
}

static void trigger_pulse(void)
{
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_US);
    gpioWrite(TRIGGER_PIN, 0);
}

static float calculate_distance(uint32_t pulse_us)
{
    return (float)pulse_us * 343.0f / 2000000.0f;
}

static void log_distance(float distance)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(g_log_fp, "%s, Distance: %.2f meters\n", timestamp, distance);
    fflush(g_log_fp);
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set TRIGGER_PIN %d as output.\n", TRIGGER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set ECHO_PIN %d as input.\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low */
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(50000);

    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, echo_callback, NULL) != 0) {
        fprintf(stderr, "Error: failed to register ISR on ECHO_PIN %d.\n", ECHO_PIN);
        fclose(g_log_fp);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Error: failed to install signal handler");
        gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, NULL, NULL);
        fclose(g_log_fp);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("HC-SR04 distance measurement started. Press Ctrl+C to exit.\n");

    while (g_running) {
        trigger_pulse();

        /* Wait for echo with a 100 ms timeout so we don't block indefinitely */
        uint32_t waited = 0;
        while (!g_echo_seen && waited < 100000) {
            gpioDelay(1000);
            waited += 1000;
        }

        if (g_echo_seen) {
            float distance = calculate_distance(g_pulse_us);
            log_distance(distance);
            printf("Distance: %.2f meters (pulse: %u us)\n", distance, g_pulse_us);
        } else {
            fprintf(stderr, "Warning: echo timeout (no valid pulse received).\n");
        }

        /* Wait for the remainder of the 1-second sample window */
        uint32_t elapsed = 0;
        while (elapsed < SAMPLE_US && g_running) {
            gpioDelay(1000);
            elapsed += 1000;
        }
    }

    printf("\nShutting down...\n");
    gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, NULL, NULL);
    fclose(g_log_fp);
    gpioTerminate();
    return EXIT_SUCCESS;
}

