#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define GATE_GPIO 24
#define DISTANCE_THRESHOLD_CM 20.0f
#define LOG_FILE "gate_log.txt"
#define POLL_DELAY_US 100000

/* VL53L1X register addresses */
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x010F
#define VL53L1X_REG_SYSTEM_RANGE_START 0x0015
#define VL53L1X_REG_SYSTEM_RANGE_MODE 0x0021
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0089
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID_EXPECTED 0xEA

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int i2c_write_byte(int handle, uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    if (i2cWriteDevice(handle, buf, 3) != 3) {
        return -1;
    }
    return 0;
}

static int i2c_read_word(int handle, uint16_t reg, uint16_t *out) {
    char reg_buf[2];
    char data_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, reg_buf, 2) != 2) {
        return -1;
    }
    if (i2cReadDevice(handle, data_buf, 2) != 2) {
        return -1;
    }
    *out = ((uint16_t)(data_buf[0] & 0xFF) << 8) | (uint8_t)data_buf[1];
    return 0;
}

static int vl53l1x_init(int handle) {
    uint16_t model_id = 0;
    if (i2c_read_word(handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID, &model_id) != 0) {
        fprintf(stderr, "Error: Failed to read model ID from VL53L1X.\n");
        return -1;
    }
    if (model_id != VL53L1X_REG_IDENTIFICATION_MODEL_ID_EXPECTED) {
        fprintf(stderr, "Error: Invalid model ID 0x%04X (expected 0x%02X). Sensor not present?\n",
                model_id, VL53L1X_REG_IDENTIFICATION_MODEL_ID_EXPECTED);
        return -1;
    }
    if (i2c_write_byte(handle, VL53L1X_REG_SYSTEM_RANGE_MODE, 0x00) != 0) {
        fprintf(stderr, "Error: Failed to set short ranging mode.\n");
        return -1;
    }
    if (i2c_write_byte(handle, VL53L1X_REG_SYSTEM_RANGE_START, 0x01) != 0) {
        fprintf(stderr, "Error: Failed to start ranging.\n");
        return -1;
    }
    return 0;
}

static int read_distance_cm(int handle, float *distance_cm) {
    uint16_t raw = 0;
    if (i2c_read_word(handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0, &raw) != 0) {
        fprintf(stderr, "Error: Failed to read distance register.\n");
        return -1;
    }
    *distance_cm = (float)raw / 10.0f;
    return 0;
}

static void control_gate(int gpio_pin, int distance_cm) {
    static int gate_open = 0;
    if (distance_cm < DISTANCE_THRESHOLD_CM && !gate_open) {
        gpioWrite(gpio_pin, 1);
        gate_open = 1;
        printf("Gate opened (distance: %.1f cm)\n", distance_cm);
    } else if (distance_cm >= DISTANCE_THRESHOLD_CM && gate_open) {
        gpioWrite(gpio_pin, 0);
        gate_open = 0;
        printf("Gate closed (distance: %.1f cm)\n", distance_cm);
    }
}

static void log_event(const char *message) {
    if (!log_file) return;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fflush(log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d at address 0x%02X.\n", I2C_BUS, VL53L1X_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (vl53l1x_init(i2c_handle) != 0) {
        fprintf(stderr, "Error: VL53L1X initialisation failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetMode(GATE_GPIO, PI_OUTPUT);
    gpioWrite(GATE_GPIO, 0);

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error: Failed to open log file '%s'.\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Gate control system started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        float distance_cm = 0.0f;
        if (read_distance_cm(i2c_handle, &distance_cm) == 0) {
            char log_msg[128];
            snprintf(log_msg, sizeof(log_msg), "Distance: %.1f cm", distance_cm);
            log_event(log_msg);
            control_gate(GATE_GPIO, distance_cm);
        } else {
            log_event("Error: Failed to read distance.");
        }
        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    gpioWrite(GATE_GPIO, 0);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    if (log_file) fclose(log_file);
    gpioTerminate();
    return EXIT_SUCCESS;
}

