#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 23
#define ECHO_PIN    24
#define SERVO_PIN   18

#define SPEED_OF_SOUND 34300.0
#define MIN_DISTANCE   2.0
#define MAX_DISTANCE   400.0
#define MIN_ANGLE      0
#define MAX_ANGLE      180
#define MIN_PULSE_US   500
#define MAX_PULSE_US   2500
#define SERVO_SETTLE_MS 500
#define SAMPLES        5
#define TIMEOUT_US     30000
#define TRIGGER_US     10
#define LOOP_DELAY_US  100000
#define CSV_FILE       "distance_log.csv"

static volatile sig_atomic_t running = 1;
static volatile sig_atomic_t echo_state = 0;
static volatile uint32_t echo_start_tick = 0;
static volatile uint32_t echo_end_tick   = 0;
static volatile int      pulse_width    = 0;
static volatile int      valid_reading = 0;
static FILE            *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void echo_callback(int gpio, int level, uint32_t tick) {
    (void)gpio;
    if (level == 1) {
        echo_start_tick = tick;
    } else if (level == 0) {
        echo_end_tick = tick;
        uint32_t diff = echo_end_tick - echo_start_tick;
        pulse_width  = (int)(diff / 1000000.0 * SPEED_OF_SOUND / 2.0);
        valid_reading = 1;
    }
}

static int set_servo_angle(int angle) {
    if (angle < MIN_ANGLE || angle > MAX_ANGLE) {
        fprintf(stderr, "Error: angle %d out of range [%d, %d]\n", angle, MIN_ANGLE, MAX_ANGLE);
        return -1;
    }
    int pulse = MIN_PULSE_US + (int)((long)(angle - MIN_ANGLE) * (MAX_PULSE_US - MIN_PULSE_US) / (MAX_ANGLE - MIN_ANGLE));
    if (gpioServo(SERVO_PIN, pulse) < 0) {
        fprintf(stderr, "Error: gpioServo failed for pulse %d\n", pulse);
        return -1;
    }
    return 0;
}

static double calculate_distance(int pulse_width) {
    if (pulse_width < 0) return -1.0;
    if (pulse_width > (int)(SPEED_OF_SOUND * 1000000.0 / 2.0)) {
        return -1.0;
    }
    return (double)pulse_width * 0.0343 / 2.0;
}

static int map_distance_to_angle(double distance) {
    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
        return -1;
    }
    double ratio = (distance - MIN_DISTANCE) / (MAX_DISTANCE - MIN_DISTANCE);
    double angle = MIN_ANGLE + ratio * (MAX_ANGLE - MIN_ANGLE);
    if (angle < MIN_ANGLE) angle = MIN_ANGLE;
    if (angle > MAX_ANGLE) angle = MAX_ANGLE;
    return (int)angle;
}

static void log_data(double distance, int angle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(log_file, "%s,%.2f,%d\n", timestamp, distance, angle);
    fflush(log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set trigger pin mode\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set echo pin mode\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set servo pin mode\n");
        gpioTerminate();
        return 1;
    }

    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(SERVO_SETTLE_MS * 1000);

    log_file = fopen(CSV_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error: cannot open %s\n", CSV_FILE);
        gpioTerminate();
        return 1;
    }
    fprintf(log_file, "Timestamp,Distance_cm,Servo_angle\n");
    fflush(log_file);

    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) < 0) {
        fprintf(stderr, "Error: failed to register echo alert\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error: failed to register SIGINT handler\n");
        gpioSetAlertFuncEx(ECHO_PIN, NULL, NULL);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    printf("Starting HC-SR04 distance measurement and servo tracking...\n");

    while (running) {
        echo_state = 0;
        pulse_width = 0;
        valid_reading = 0;

        gpioWrite(TRIGGER_PIN, 1);
        gpioDelay(TRIGGER_US);
        gpioWrite(TRIGGER_PIN, 0);

        uint32_t start = gpioTick();
        while (!valid_reading && running) {
            if ((gpioTick() - start) > TIMEOUT_US) {
                fprintf(stderr, "Warning: timeout waiting for echo\n");
                break;
            }
            gpioDelay(100);
        }

        if (valid_reading) {
            double distance = calculate_distance(pulse_width);
            int angle = map_distance_to_angle(distance);
            if (angle < 0) {
                fprintf(stderr, "Warning: invalid distance %f, defaulting servo to 90\n", distance);
                angle = 90;
            }
            if (set_servo_angle(angle) < 0) {
                fprintf(stderr, "Warning: failed to set servo angle\n");
            }
            log_data(distance, angle);
        } else {
            fprintf(stderr, "Warning: no valid reading, servo set to default 90\n");
            if (set_servo_angle(90) < 0) {
                fprintf(stderr, "Warning: failed to set servo angle\n");
            }
        }

        gpioDelay(LOOP_DELAY_US);
    }

    printf("\nShutting down...\n");
    gpioServo(SERVO_PIN, 0);
    gpioSetAlertFuncEx(ECHO_PIN, NULL, NULL);
    if (log_file) {
        fclose(log_file);
    }
    gpioTerminate();
    return 0;
}

