#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <errno.h>

#define I2C_BUS 1
#define SI1102_ADDR 0x60
#define INTERRUPT_GPIO 27
#define PROXIMITY_REG_HIGH 0x08
#define PROXIMITY_REG_LOW 0x09
#define LOG_FILE "proximity.log"

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;
static volatile sig_atomic_t interrupt_flag = 0;
static volatile int proximity_value = 0;
static volatile int threshold = 1000;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %s\n", bus, addr, strerror(errno));
        return -1;
    }
    return handle;
}

static int read_proximity(int handle) {
    int high = i2cReadByteData(handle, PROXIMITY_REG_HIGH);
    if (high < 0) {
        fprintf(stderr, "Error reading proximity high byte: %s\n", strerror(errno));
        return -1;
    }
    int low = i2cReadByteData(handle, PROXIMITY_REG_LOW);
    if (low < 0) {
        fprintf(stderr, "Error reading proximity low byte: %s\n", strerror(errno));
        return -1;
    }
    return (high << 8) | low;
}

static void log_event(int proximity, const char *status) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s, Proximity: %d, Status: %s\n", timestamp, proximity, status);
    fflush(log_file);
}

static void interrupt_handler(int gpio, int level, uint32_t tick, void *user) {
    (void)gpio; (void)level; (void)tick; (void)user;
    interrupt_flag = 1;
    proximity_value = read_proximity(i2c_handle);
    if (proximity_value < 0) {
        fprintf(stderr, "Error reading proximity during interrupt\n");
    }
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    int opt;
    while ((opt = getopt(argc, argv, "a:t:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_handle = init_i2c(I2C_BUS, (int)strtol(optarg, NULL, 0));
                if (i2c_handle < 0) {
                    fprintf(stderr, "Invalid I2C address: %s\n", optarg);
                    return 1;
                }
                break;
            case 't':
                threshold = (int)strtol(optarg, NULL, 0);
                if (threshold < 0) {
                    fprintf(stderr, "Threshold must be non-negative\n");
                    return 1;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address] [-t threshold]\n", argv[0]);
                return 1;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(INTERRUPT_GPIO, PI_INPUT);
    gpioSetPullUpDown(INTERRUPT_GPIO, PI_PUD_DOWN);
    gpioSetISRFuncEx(INTERRUPT_GPIO, RISING_EDGE, 0, interrupt_handler, NULL);

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Proximity sensor monitoring started. Threshold: %d\n", threshold);

    while (running) {
        if (interrupt_flag) {
            interrupt_flag = 0;
            const char *status = "SAFE";
            if (proximity_value > threshold) {
                status = "ALERT";
            }
            log_event(proximity_value, status);
        }
        gpioDelay(100000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

