#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define TRIGGER_PIN 23
#define ECHO_PIN    24
#define PWM_PIN     18

#define MIN_FREQUENCY 200
#define MAX_FREQUENCY 2000
#define PWM_DUTY      128   /* 50% of 255 */

#define MIN_DISTANCE 2.0
#define MAX_DISTANCE 200.0
#define TRIGGER_PULSE_US 10
#define ECHO_TIMEOUT_US  200000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/*
 * Measure distance using the HC-SR04.
 * Returns distance in cm on success, or -1.0 on timeout/error.
 */
static float measure_distance(void) {
    uint32_t start_tick, end_tick;

    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(trigger, 0) failed\n");
        return -1.0;
    }
    gpioDelay(5);

    /* 10 us trigger pulse */
    if (gpioTrigger(TRIGGER_PIN, TRIGGER_PULSE_US, 1) < 0) {
        fprintf(stderr, "Error: gpioTrigger failed\n");
        return -1.0;
    }

    /* Wait for echo rising edge (timeout 200 ms) */
    start_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        if ((gpioTick() - start_tick) > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Error: Echo start timeout\n");
            return -1.0;
        }
    }
    start_tick = gpioTick();

    /* Wait for echo falling edge (timeout 200 ms) */
    while (gpioRead(ECHO_PIN) == 1) {
        if ((gpioTick() - start_tick) > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Error: Echo end timeout\n");
            return -1.0;
        }
    }
    end_tick = gpioTick();

    uint32_t diff = end_tick - start_tick;
    float distance = (diff / 1000000.0) * 34300.0 / 2.0;
    return distance;
}

/*
 * Map distance to frequency using a logarithmic curve.
 * Returns -1.0 on invalid distance.
 */
static int map_distance_to_frequency(float distance) {
