#define TRIGGER_PIN 23
#define ECHO_PIN    24
#define BUZZER_PIN  18

#define MIN_FREQ   200
#define MAX_FREQ   2000
#define MIN_DIST   5.0
#define MAX_DIST   50.0
#define TIMEOUT_US 100000  /* 100 ms timeout for echo */
#define LOOP_DELAY_US 10000 /* 10 ms between readings */

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

/*
 * Measure distance (cm) from HC-SR04.
 * Returns distance on success, or -1.0 on timeout / error.
 */
static float measure_distance(void) {
    /* Ensure trigger is low */
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(5);

    /* 10 us trigger pulse */
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10);
    gpioWrite(TRIGGER_PIN, 0);

    uint32_t start_tick = 0, end_tick = 0;
    int timeout = 0;

    /* Wait for echo rising edge */
    while (gpioRead(ECHO_PIN) == 0) {
        if (++timeout > TIMEOUT_US) {
            fprintf(stderr, "Error: Echo pin did not go high (timeout).\n");
            return -1.0;
        }
        gpioDelay(1);
    }
    start_tick = gpioTick();

    /* Wait for echo falling edge */
    timeout = 0;
    while (gpioRead(ECHO_PIN) == 1) {
        if (++timeout > TIMEOUT_US) {
            fprintf(stderr, "Error: Echo pin did not go low (timeout).\n");
            return -1.0;
        }
        gpioDelay(1);
    }
    end_tick = gpioTick();

    uint32_t pulse_us = end_tick - start_tick;
    float distance = (pulse_us / 1000000.0) * 34300.0 / 2.0;

    if (distance < MIN_DIST || distance > MAX_DIST) {
        fprintf(stderr, "Warning: Distance %.2f cm out of valid range [%.1f, %.1f].\n",
                distance, MIN_DIST, MAX_DIST);
        return -1.0;
    }
    return distance;
}

static int set_pwm_frequency(int gpio, int frequency) {
    if (frequency <= 0) {
        gpioHardwarePWM(gpio, 0, 0);
        return 0;
    }
    if (gpioHardwarePWM(gpio, frequency, 500000) != 0) {
        fprintf(stderr, "Error: gpioHardwarePWM failed for GPIO %d at %d Hz.\n",
                gpio, frequency);
        return -1;
    }
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO modes */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set TRIGGER_PIN %d as output.\n", TRIGGER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set ECHO_PIN %d as input.\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set BUZZER_PIN %d as output.\n", BUZZER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Pull-down on echo to avoid floating when sensor is disconnected */
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    /* Ensure trigger starts low */
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(100000); /* 100 ms settle */

    /* Install SIGINT handler for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Failed to install SIGINT handler.\n");
    }

    printf("Theremin started. Press Ctrl+C to exit.\n");

    float last_distance = MIN_DIST;
    int last_freq = MIN_FREQ;

    while (running) {
        float distance = measure_distance();

        if (distance < 0.0) {
            fprintf(stderr, "Sensor read failed; using last valid distance %.2f cm.\n",
                    last_distance);
            distance = last_distance;
        } else {
            last_distance = distance;
        }

        /* Map distance to frequency */
        float freq = MIN_FREQ +
                     (MAX_FREQ - MIN_FREQ) *
                     (MAX_DIST - distance) /
                     (MAX_DIST - MIN_DIST);

        if (freq < MIN_FREQ) freq = MIN_FREQ;
        if (freq > MAX_FREQ) freq = MAX_FREQ;

        if (set_pwm_frequency(BUZZER_PIN, (int)freq) != 0) {
            fprintf(stderr, "Warning: Failed to set PWM frequency.\n");
        }

        printf("Distance: %.2f cm, Frequency: %d Hz\n", distance, freq);
        gpioDelay(LOOP_DELAY_US);
    }

    /* Graceful shutdown */
    gpioHardwarePWM(BUZZER_PIN, 0, 0);
    gpioWrite(TRIGGER_PIN, 0);
    gpioTerminate();
    printf("\nTheremin stopped.\n");
    return EXIT_SUCCESS;
}

