#define MAX_DISTANCE 400.0
#define MIN_DISTANCE_ALERT 10.0
#define TIMEOUT_US 50000
#define TRIGGER_PULSE_US 10
#define LOOP_DELAY_US 500000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioWrite(TRIGGER_PIN, 0);
    return 0;
}

static void trigger_sensor(void) {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(TRIGGER_PIN, 0);
}

static float measure_distance(void) {
    uint32_t start_tick, end_tick;
    int timeout;

    trigger_sensor();

    timeout = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        if (gpioTick() - timeout > TIMEOUT_US) {
            return -1.0;
        }
    }
    start_tick = gpioTick();

    timeout = start_tick;
    while (gpioRead(ECHO_PIN) == 1) {
        if (gpioTick() - timeout > TIMEOUT_US) {
            return -1.0;
        }
    }
    end_tick = gpioTick();

    uint32_t pulse_width = end_tick - start_tick;
    return (float)pulse_width / 2.0 / SPEED_OF_SOUND;
}

