    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return 1;
    }

    if (init_gpio() != 0) {
        return 1;
    }

    while (running) {
        float distance = measure_distance();

        if (distance < 0.0) {
            fprintf(stderr, "Error: timeout waiting for echo pulse\n");
        } else if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
            fprintf(stderr, "Invalid reading: %.2f cm\n", distance);
