#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define CS_PIN 8
#define LOG_FILE "distance_log.csv"

#define REG_MODE 0x01
#define REG_RANGE 0x02
#define REG_DISTANCE_LOW 0x0C
#define REG_DISTANCE_HIGH 0x0D

#define MODE_CONTINUOUS 0x01
#define RANGE_5M 0x00
#define TRIGGER_MEASURE 0x01

static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int spi_write_reg(uint8_t reg, uint8_t value) {
    char tx[2] = { (char)(reg & 0x7F), (char)value };
    char rx[2] = {0};
    if (spiXfer(spi_handle, tx, rx, 2) != 2) {
        fprintf(stderr, "SPI write failed for reg 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

static int spi_read_reg(uint8_t reg, uint8_t *value) {
    char tx[2] = { (char)(reg | 0x80), 0x00 };
    char rx[2] = {0};
