#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define SI1175_ADDR 0x60
#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "proximity_log.csv"
#define SAMPLE_INTERVAL_SEC 5

/* Si1175 register addresses */
#define REG_ALS_VIS_DATA0 0x22
#define REG_ALS_VIS_DATA1 0x23
#define REG_ALS_VIS_CONFIG 0x2E
#define REG_PROX_DATA0    0x24
#define REG_PROX_DATA1    0x25
#define REG_COMMAND       0x30

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, 2) != 2) {
        return -1;
    }
    return 0;
}

static int i2c_read_byte(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        return -1;
    }
    return 0;
}

static int i2c_read_word(int fd, uint8_t reg_low, uint16_t *value) {
    uint8_t low, high;
    if (i2c_read_byte(fd, reg_low, &low) < 0) {
        return -1;
    }
    if (i2c_read_byte(fd, reg_low + 1, &high) < 0) {
        return -1;
    }
    *value = (uint16_t)((high << 8) | low);
    return 0;
}

static int init_si1175(int fd) {
    /* Put Si1175 into power-down mode to allow configuration changes */
    if (i2c_write_byte(fd, REG_COMMAND, 0x00) < 0) {
        return -1;
    }
    usleep(10000);

    /* Configure ALS visible channel: enable it, set gain to 1 (0x01) */
    if (i2c_write_byte(fd, REG_ALS_VIS_CONFIG, 0x01) < 0) {
        return -1;
    }

    /* Enable proximity sensing */
    if (i2c_write_byte(fd, REG_COMMAND, 0x01) < 0) {
        return -1;
    }
    usleep(10000);

    /* Start measurements */
    if (i2c_write_byte(fd, REG_COMMAND, 0x02) < 0) {
        return -1;
    }
    usleep(10000);

    return 0;
}

static int read_als_data(int fd, uint16_t *als_value) {
    return i2c_read_word(fd, REG_ALS_VIS_DATA0, als_value);
}

static void log_data(FILE *fp, uint16_t als_value) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    fprintf(fp, "%s,%u\n", timestamp, als_value);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        perror("Failed to open I2C bus " I2C_BUS);
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SI1175_ADDR) < 0) {
        perror("Failed to acquire I2C bus access / talk to Si1175");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* Probe the sensor by reading the command register */
    uint8_t probe;
    if (i2c_read_byte(g_i2c_fd, REG_COMMAND, &probe) < 0) {
        fprintf(stderr, "Si1175 not detected at address 0x%02X (sensor absent or bus error)\n", SI1175_ADDR);
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    if (init_si1175(g_i2c_fd) < 0) {
        fprintf(stderr, "Failed to initialize Si1175 sensor\n");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        perror("Failed to open log file " LOG_FILE);
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* Write header if file is empty */
    fseek(g_log_fp, 0, SEEK_END);
    if (ftell(g_log_fp) == 0) {
        fprintf(g_log_fp, "timestamp,als_visible\n");
        fflush(g_log_fp);
    }

    printf("Si1175 initialized. Logging to %s every %d seconds. Press Ctrl+C to stop.\n",
           LOG_FILE, SAMPLE_INTERVAL_SEC);

    while (g_running) {
        uint16_t als_value;
        if (read_als_data(g_i2c_fd, &als_value) < 0) {
            fprintf(stderr, "Error reading ALS data (I2C bus error)\n");
        } else {
            log_data(g_log_fp, als_value);
            printf("ALS: %u\n", als_value);
        }

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL_SEC && g_running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
    }

    return EXIT_SUCCESS;
}

