#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define SI1145_ADDR 0x60

#define REG_HW_KEY      0x07
#define REG_MEAS_RATE   0x06
#define REG_NO_INT      0x1A
#define REG_ALS_VIS_IR_ADC_COUNTER 0x21
#define REG_ALS_VIS_ADC_GAIN 0x24
#define REG_PS_ADC_COUNTER 0x22
#define REG_PS_LED21 0x0C
#define REG_PS_LED3 0x0F
#define REG_PS_ADC_MISC 0x0D
#define REG_PS_ADC_GAIN 0x0C
#define REG_COMMAND 0x80
#define REG_PS1_DATA0 0x16
#define REG_PS1_DATA1 0x17

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int write_register(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing 0x%02X to register 0x%02X (pigpio rc=%d)\n", value, reg, rc);
        return -1;
    }
    return 0;
}

static int read_register(int handle, uint8_t reg) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading register 0x%02X (pigpio rc=%d)\n", reg, rc);
        return -1;
    }
    return rc;
}

static int init_si1145(int handle) {
    if (write_register(handle, REG_HW_KEY, 0x03) < 0) return -1;
    if (write_register(handle, REG_MEAS_RATE, 0x02) < 0) return -1;
    if (write_register(handle, REG_NO_INT, 0x00) < 0) return -1;
    if (write_register(handle, REG_ALS_VIS_IR_ADC_COUNTER, 0x00) < 0) return -1;
    if (write_register(handle, REG_ALS_VIS_ADC_GAIN, 0x00) < 0) return -1;
    if (write_register(handle, REG_PS_ADC_COUNTER, 0x49) < 0) return -1;
    if (write_register(handle, REG_PS_LED21, 0x03) < 0) return -1;
    if (write_register(handle, REG_PS_LED3, 0x0F) < 0) return -1;
    if (write_register(handle, REG_PS_ADC_MISC, 0x07) < 0) return -1;
    if (write_register(handle, REG_PS_ADC_GAIN, 0x03) < 0) return -1;
    if (write_register(handle, REG_COMMAND, 0x03) < 0) return -1;
    return 0;
}

static int read_proximity(int handle) {
    int low = read_register(handle, REG_PS1_DATA0);
    if (low < 0) return -1;
    int high = read_register(handle, REG_PS1_DATA1);
    if (high < 0) return -1;
    return (high << 8) | low;
}

static void log_data(FILE *fp, int proximity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s, %d\n", timestamp, proximity);
    fflush(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02X: pigpio rc=%d\n", SI1145_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (init_si1145(i2c_handle) < 0) {
        fprintf(stderr, "Si1145 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
