#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define BUZZER_PIN 27
#define DISTANCE_THRESHOLD 20.0f
#define SPEED_OF_SOUND 0.0343f
#define TRIGGER_PULSE_US 10
#define LOOP_DELAY_US 1000000

static volatile uint32_t start_tick = 0;
static volatile uint32_t end_tick = 0;
static volatile int echo_received = 0;

static void echo_callback(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)userdata;

    if (level == 1) {
        start_tick = tick;
    } else if (level == 0) {
        end_tick = tick;
        echo_received = 1;
    }
}

static void trigger_pulse(void)
{
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(TRIGGER_PIN, 0);
}

static float calculate_distance(uint32_t start, uint32_t end)
{
    uint32_t diff = end - start;
    return (float)diff * SPEED_OF_SOUND / 2.0f;
}

static void control_buzzer(float distance)
{
    if (distance < DISTANCE_THRESHOLD) {
        gpioWrite(BUZZER_PIN, 1);
    } else {
        gpioWrite(BUZZER_PIN, 0);
    }
}

static void cleanup(void)
{
    gpioWrite(BUZZER_PIN, 0);
    gpioTerminate();
}

static void signal_handler(int sig)
{
    (void)sig;
    cleanup();
    exit(0);
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set trigger pin mode\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set echo pin mode\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set buzzer pin mode\n");
        gpioTerminate();
        return 1;
    }

    if (gpioWrite(TRIGGER_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise trigger pin low\n");
        gpioTerminate();
        return 1;
    }
    if (gpioWrite(BUZZER_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise buzzer pin low\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) != 0) {
        fprintf(stderr, "Error: failed to set echo alert function\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);

    while (1) {
        echo_received = 0;
        start_tick = 0;
        end_tick = 0;

        trigger_pulse();

        while (!echo_received) {
            gpioDelay(1000);
        }

        float distance = calculate_distance(start_tick, end_tick);
        control_buzzer(distance);

        printf("Distance: %.2f cm\n", distance);
        fflush(stdout);

        gpioDelay(LOOP_DELAY_US);
    }

    cleanup();
    return 0;
}

