#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SI7005_ADDR 0x40
#define TEMP_REG 0x01
#define HUMID_REG 0x02
#define CONFIG_REG 0x03
#define CONFIG_TEMP_EN 0x00
#define CONV_DELAY_US 10000
#define LOOP_DELAY_US 2000000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_i2c(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    i2c_handle = i2cOpen(I2C_BUS, SI7005_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %d\n",
                I2C_BUS, SI7005_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

static int write_reg(uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(i2c_handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing 0x%02X to reg 0x%02X: %d\n",
                value, reg, rc);
        return -1;
    }
    return 0;
}

static int read_reg(uint8_t reg, uint8_t *value) {
    int rc = i2cReadByteData(i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading reg 0x%02X: %d\n", reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

static int read_reg16(uint8_t reg, uint16_t *value) {
    int rc = i2cReadWordData(i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading reg 0x%02X: %d\n", reg, rc);
        return -1;
    }
    *value = (uint16_t)rc;
    return 0;
}

static int read_temperature(float *temp) {
    if (write_reg(CONFIG_REG, CONFIG_TEMP_EN) != 0) return -1;
    gpioDelay(CONV_DELAY_US);
    uint16_t raw;
    if (read_reg16(TEMP_REG, &raw) != 0) return -1;
    *temp = (175.72f * raw) / 65536.0f - 46.85f;
    return 0;
}

static int read_humidity(float *hum) {
    if (write_reg(CONFIG_REG, CONFIG_TEMP_EN) != 0) return -1;
    gpioDelay(CONV_DELAY_US);
    uint16_t raw;
    if (read_reg16(HUMID_REG, &raw) != 0) return -1;
    *hum = (125.0f * raw) / 65536.0f - 6.0f;
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        float temperature, humidity;
        if (read_temperature(&temperature) == 0 && read_humidity(&humidity) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
        } else {
            fprintf(stderr, "Sensor read failed; re-initialising I2C...\n");
            if (init_i2c() != 0) {
                fprintf(stderr, "Re-initialisation failed; exiting.\n");
                break;
            }
        }
        gpioDelay(LOOP_DELAY_US);
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

