/*
 * MPU-6050 raw data logger for Raspberry Pi 3 Model B+
 * Library: pigpio (I2C bus 1, address 0x68)
 * Build:  gcc -O2 -Wall -o mpu6050 mpu6050.c -lpigpio -lrt
 * Run:    sudo ./mpu6050
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- MPU-6050 constants (verified against datasheet) ---- */
#define MPU6050_ADDR        0x68
#define WHO_AM_I            0x75
#define WHO_AM_I_VAL        0x68
#define PWR_MGMT_1          0x6B
#define ACCEL_CONFIG        0x1C
#define GYRO_CONFIG         0x1B
#define ACCEL_XOUT_H        0x3B
#define GYRO_XOUT_H         0x43
#define SAMPLE_RATE_DIV     0x19
#define I2C_BUS             1

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;          /* let main loop exit cleanly */
}

/* ------------------------------------------------------------------ */
static int mpu6050_init(int handle)
{
    int rc;

    /* 1. Verify device identity */
    rc = i2cReadByteData(handle, WHO_AM_I);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] I2C read of WHO_AM_I failed (rc=%d).\n", rc);
        return -1;
    }
    if (rc != WHO_AM_I_VAL) {
        fprintf(stderr, "[ERROR] WHO_AM_I mismatch: got 0x%02X, expected 0x%02X.\n",
                rc, WHO_AM_I_VAL);
        return -1;
    }

    /* 2. Software reset via PWR_MGMT_1 */
    rc = i2cWriteByteData(handle, PWR_MGMT_1, 0x80);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] Failed to write PWR_MGMT_1 (rc=%d).\n", rc);
        return -1;
    }
    gpioDelay(100000);       /* 100 ms reset settling time */

    /* 3. Clear SLEEP bit so the device enters normal operation */
    rc = i2cWriteByteData(handle, PWR_MGMT_1, 0x00);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] Failed to clear SLEEP bit (rc=%d).\n", rc);
        return -1;
    }
    gpioDelay(10000);        /* 10 ms for oscillator to stabilise */

    /* 4. Sample rate divider = 7 -> 1 kHz / (1 + 7) = 125 Hz output */
    rc = i2cWriteByteData(handle, SAMPLE_RATE_DIV, 7);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] Failed to write SAMPLE_RATE_DIV (rc=%d).\n", rc);
        return -1;
    }

    /* 5. Accelerometer range ±2 g (AFS_SEL = 0) */
    rc = i2cWriteByteData(handle, ACCEL_CONFIG, 0x00);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] Failed to write ACCEL_CONFIG (rc=%d).\n", rc);
        return -1;
    }

    /* 6. Gyroscope range ±250 °/s (FS_SEL = 0) */
    rc = i2cWriteByteData(handle, GYRO_CONFIG, 0x00);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] Failed to write GYRO_CONFIG (rc=%d).\n", rc);
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
static int mpu6050_read_block(int handle,
                              int16_t *ax, int16_t *ay, int16_t *az,
                              int16_t *gx, int16_t *gy, int16_t *gz)
{
    char buf[14];
    int rc;

    rc = i2cReadI2CBlockData(handle, ACCEL_XOUT_H, buf, sizeof(buf));
    if (rc != (int)sizeof(buf)) {
        fprintf(stderr, "[ERROR] i2cReadI2CBlockData returned %d (expected %zu).\n",
                rc, sizeof(buf));
        return -1;
    }

    /* MPU-6050 data is big-endian: MSB first */
    *ax = (int16_t)(((uint8_t)buf[0]  << 8) | (uint8_t)buf[1]);
    *ay = (int16_t)(((uint8_t)buf[2]  << 8) | (uint8_t)buf[3]);
    *az = (int16_t)(((uint8_t)buf[4]  << 8) | (uint8_t)buf[5]);
    /* buf[6..7] = temperature (skipped) */
    *gx = (int16_t)(((uint8_t)buf[8]  << 8) | (uint8_t)buf[9]);
    *gy = (int16_t)(((uint8_t)buf[10] << 8) | (uint8_t)buf[11]);
    *gz = (int16_t)(((uint8_t)buf[12] << 8) | (uint8_t)buf[13]);

    return 0;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    int rc;
    int16_t ax, ay, az, gx, gy, gz;

    /* ---- Install signal handlers for graceful shutdown ---- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("[WARN] sigaction(SIGINT)");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("[WARN] sigaction(SIGTERM)");
    }

    /* ---- Initialise pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus 1 at MPU-6050 default address ---- */
    g_i2c_handle = i2cOpen(I2C_BUS, MPU6050_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %d.\n",
                I2C_BUS, MPU6050_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Initialise sensor ---- */
    if (mpu6050_init(g_i2c_handle) != 0) {
        fprintf(stderr, "[FATAL] MPU-6050 initialisation failed.\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("MPU-6050 initialised on I2C bus %d at address 0x%02X.\n",
           I2C_BUS, MPU6050_ADDR);
    printf("Logging raw accelerometer (ax,ay,az) and gyroscope (gx,gy,gz) every 100 ms.\n");
    printf("Press Ctrl+C to stop.\n\n");

    /* ---- Main sampling loop ---- */
    while (g_running) {
        rc = mpu6050_read_block(g_i2c_handle, &ax, &ay, &az, &gx, &gy, &gz);
        if (rc == 0) {
            printf("Accel: X=%6d  Y=%6d  Z=%6d  |  Gyro: X=%6d  Y=%6d  Z=%6d\n",
                   ax, ay, az, gx, gy, gz);
        } else {
            fprintf(stderr, "[WARN] Read error — continuing.\n");
        }
        gpioDelay(100000);   /* 100 ms */
    }

    /* ---- Graceful shutdown ---- */
    printf("\nShutting down...\n");
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

