    *ax = (int16_t)(((uint8_t)buf[0]  << 8) | (uint8_t)buf[1]);
    *ay = (int16_t)(((uint8_t)buf[2]  << 8) | (uint8_t)buf[3]);
    *az = (int16_t)(((uint8_t)buf[4]  << 8) | (uint8_t)buf[5]);
    /* buf[6..7] = temperature (skipped) */
    *gx = (int16_t)(((uint8_t)buf[8]  << 8) | (uint8_t)buf[9]);
    *gy = (int16_t)(((uint8_t)buf[10] << 8) | (uint8_t)buf[11]);
    *gz = (int16_t)(((uint8_t)buf[12] << 8) | (uint8_t)buf[13]);

    return 0;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    int rc;
    int16_t ax, ay, az, gx, gy, gz;

    /* ---- Install signal handlers for graceful shutdown ---- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("[WARN] sigaction(SIGINT)");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("[WARN] sigaction(SIGTERM)");
    }

    /* ---- Initialise pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus 1 at MPU-6050 default address ---- */
    g_i2c_handle = i2cOpen(I2C_BUS, MPU6050_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %d.\n",
                I2C_BUS, MPU6050_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Initialise sensor ---- */
    if (mpu6050_init(g_i2c_handle) != 0) {
        fprintf(stderr, "[FATAL] MPU-6050 initialisation failed.\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("MPU-6050 initialised on I2C bus %d at address 0x%02X.\n",
           I2C_BUS, MPU6050_ADDR);
    printf("Logging raw accelerometer (ax,ay,az) and gyroscope (gx,gy,gz) every 100 ms.\n");
    printf("Press Ctrl+C to stop.\n\n");

    /* ---- Main sampling loop ---- */
    while (g_running) {
        rc = mpu6050_read_block(g_i2c_handle, &ax, &ay, &az, &gx, &gy, &gz);
        if (rc == 0) {
            printf("Accel: X=%6d  Y=%6d  Z=%6d  |  Gyro: X=%6d  Y=%6d  Z=%6d\n",
                   ax, ay, az, gx, gy, gz);
        } else {
            fprintf(stderr, "[WARN] Read error — continuing.\n");
        }
        gpioDelay(100000);   /* 100 ms */
    }

    /* ---- Graceful shutdown ---- */
    printf("\nShutting down...\n");
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

