#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#define I2C_BUS 1
#define STS30_ADDR 0x4A
#define LOG_FILE "enclosure_temp_log.txt"
#define ERROR_LOG_FILE "error_log.txt"
#define SAMPLE_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;
static FILE *error_log_file = NULL;

void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

void log_error(const char *message) {
    if (error_log_file == NULL) {
        error_log_file = fopen(ERROR_LOG_FILE, "a");
        if (error_log_file == NULL) {
            fprintf(stderr, "Error opening error log file: %s\n", strerror(errno));
            return;
        }
    }
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(error_log_file, "%s: %s\n", timestamp, message);
    fflush(error_log_file);
}

int read_temperature(float *temperature) {
    char buf[2];
    int result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        log_error("I2C read failed");
        return -1;
    }
    int raw_temp = (buf[0] << 8) | buf[1];
    *temperature = (float)raw_temp / 10.0f;
    return 0;
}

int log_temperature(float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            log_error("Failed to open log file");
            return -1;
        }
    }
    fprintf(log_file, "%s, %.2f\n", timestamp, temperature);
    fflush(log_file);
    return 0;
}

void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    if (error_log_file != NULL) {
        fclose(error_log_file);
        error_log_file = NULL;
    }
    gpioTerminate();
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, STS30_ADDR, 0);
    if (i2c_handle < 0) {
        log_error("Failed to open I2C device");
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    float temperature;
    while (running) {
        if (read_temperature(&temperature) == 0) {
            if (log_temperature(temperature) != 0) {
                log_error("Failed to log temperature");
            }
        } else {
            log_error("Failed to read temperature");
        }
        sleep(SAMPLE_INTERVAL_SEC);
    }

    cleanup();
    return 0;
}

