    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at address 0x%02X on bus %d.\n", SDP810_ADDR, I2C_BUS);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    FILE *fp = fopen(LOG_FILE, "r");
    int file_exists = (fp != NULL);
    if (fp) fclose(fp);

    while (running) {
        float pressure, temperature;
        if (read_sdp810(i2c_handle, &pressure, &temperature) == 0) {
            if (log_data(LOG_FILE, pressure, temperature) != 0) {
                fprintf(stderr, "Warning: Failed to log data.\n");
            }
        } else {
            fprintf(stderr, "Warning: Sensor read failed, skipping log entry.\n");
        }
        gpioDelay(POLL_INTERVAL_US);
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

