#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SDP31_ADDR     0x28
#define LOG_FILE       "airflow.log"
#define SAMPLE_US      100000   /* 100 ms */
#define MEAS_DELAY_US  2000     /* 2 ms  (datasheet: typ 1 ms) */
#define MAX_RETRIES    3
#define RETRY_BASE_US  1000     /* 1 ms */

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers with retry and exponential backoff                     */
/* ------------------------------------------------------------------ */
static int i2c_write_retry(int handle, const char *buf, int len)
{
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int rc = i2cWriteDevice(handle, buf, len);
        if (rc == 0)
            return 0;
        fprintf(stderr, "I2C write attempt %d/%d failed (rc=%d)\n",
                attempt + 1, MAX_RETRIES, rc);
        if (attempt < MAX_RETRIES - 1)
            gpioDelay(RETRY_BASE_US * (1 << attempt));
    }
    return -1;
}

static int i2c_read_retry(int handle, char *buf, int len)
{
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int rc = i2cReadDevice(handle, buf, len);
        if (rc == len)
            return 0;
        fprintf(stderr, "I2C read attempt %d/%d failed (rc=%d)\n",
                attempt + 1, MAX_RETRIES, rc);
        if (attempt < MAX_RETRIES - 1)
            gpioDelay(RETRY_BASE_US * (1 << attempt));
    }
    return -1;
}

/* ------------------------------------------------------------------ */
/* SDP31 conversion                                                    */
/* ------------------------------------------------------------------ */
static int sdp31_read(int handle, float *pressure_pa, float *temperature_c)
{
    char cmd[2] = {0x21, 0x96};   /* continuous measurement, mass flow */
    char data[6];

    if (i2c_write_retry(handle, cmd, 2) != 0) {
        fprintf(stderr, "Failed to trigger SDP31 measurement\n");
        return -1;
    }

    gpioDelay(MEAS_DELAY_US);

    if (i2c_read_retry(handle, data, 6) != 0) {
        fprintf(stderr, "Failed to read 6 bytes from SDP31\n");
        return -1;
    }

    /* CRC-8 polynomial 0x31, init 0xFF */
    uint8_t crc = 0xFF;
    for (int i = 0; i < 2; i++) {
        crc ^= (uint8_t)data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    if (crc != (uint8_t)data[2]) {
        fprintf(stderr, "Pressure CRC mismatch (calc=0x%02X recv=0x%02X)\n",
                crc, (uint8_t)data[2]);
        return -1;
    }

    crc = 0xFF;
