        fprintf(stderr, "Temperature CRC mismatch (calc=0x%02X recv=0x%02X)\n",
                crc, (uint8_t)data[5]);
        return -1;
    }

    int16_t raw_pressure = (int16_t)(((uint8_t)data[0] << 8) | (uint8_t)data[1]);
    int16_t raw_temp      = (int16_t)(((uint8_t)data[3] << 8) | (uint8_t)data[4]);

    *pressure_pa    = (float)raw_pressure / 60.0f;
    *temperature_c  = (float)raw_temp / 200.0f;
    return 0;
}

