#define I2C_BUS        1
#define SI7015_ADDR    0x40
#define CMD_TEMP       0xF3
#define CMD_HUMID      0xF5
#define MEAS_DELAY_US  20000   /* 20 ms max wait for conversion */
#define SAMPLE_PERIOD  5       /* seconds between readings */
#define LOG_FILE       "sensor_data.txt"

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write a single command byte to the Si7015 (No Hold Master mode). */
static int si7015_write_cmd(int handle, uint8_t cmd)
{
    if (i2cWriteByte(handle, cmd) < 0) {
        fprintf(stderr, "Error: i2cWriteByte(0x%02X) failed: %s\n",
                cmd, pigpio_error(i2cWriteByte(handle, cmd)));
        return -1;
    }
    return 0;
}

/* Read two bytes from the Si7015; returns 0 on success, -1 on error. */
static int si7015_read_data(int handle, uint8_t *buf)
{
    int bytes = i2cReadDevice(handle, (char *)buf, 2);
    if (bytes != 2) {
        fprintf(stderr, "Error: i2cReadDevice returned %d (expected 2): %s\n",
                bytes, bytes < 0 ? pigpio_error(bytes) : strerror(errno));
        return -1;
    }
    return 0;
}

/* Trigger a measurement and read the two-byte result. Returns 0 on success. */
static int si7015_read_measurement(int handle, uint16_t *raw)
{
    if (si7015_write_cmd(handle, CMD_TEMP) < 0)
        return -1;
    gpioDelay(MEAS_DELAY_US);

    uint8_t buf[2];
    if (si7015_read_data(handle, buf) < 0)
        return -1;

    *raw = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static float convert_temperature(uint16_t raw)
{
    return (175.72f * (float)raw / 65536.0f) - 46.85f;
}

static float convert_humidity(uint16_t raw)
{
    float rh = (125.0f * (float)raw / 65536.0f) - 6.0f;
    if (rh < 0.0f)   rh = 0.0f;
    if (rh > 100.0f) rh = 100.0f;
    return rh;
}

static int log_data(float temperature, float humidity)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error: cannot open %s: %s\n",
                LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error: localtime_r failed\n");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s, Temperature: %.2f C, Humidity: %.2f %%RH\n",
            timestamp, temperature, humidity);
    fclose(fp);
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, SI7015_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen(bus=%d, addr=0x%02X) failed: %s\n",
                I2C_BUS, SI7015_ADDR, pigpio_error(g_i2c_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Si7015 sensor reader started. Logging to %s every %d s.\n",
           LOG_FILE, SAMPLE_PERIOD);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        uint16_t raw_temp = 0, raw_hum = 0;
        int ok = 1;

        if (si7015_read_measurement(g_i2c_handle, &raw_temp) < 0) {
            fprintf(stderr, "Warning: temperature read failed; retrying next cycle.\n");
            ok = 0;
        } else if (si7015_read_measurement(g_i2c_handle, &raw_hum) < 0) {
            fprintf(stderr, "Warning: humidity read failed; retrying next cycle.\n");
            ok = 0;
        } else {
            float temperature = convert_temperature(raw_temp);
            float humidity    = convert_humidity(raw_hum);

            if (log_data(temperature, humidity) < 0) {
                fprintf(stderr, "Warning: logging failed.\n");
            } else {
                printf("Temperature: %.2f C, Humidity: %.2f %%RH\n",
                       temperature, humidity);
            }
        }

        /* Sleep in 100 ms increments so SIGINT is caught promptly. */
        for (int i = 0; i < SAMPLE_PERIOD * 10 && g_running; i++)
            gpioDelay(100000);
    }

    printf("\nShutting down...\n");

    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

