#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x40
#define FAN_GPIO       18
#define TEMP_THRESHOLD_HIGH  28.0f
#define TEMP_THRESHOLD_LOW   27.0f
#define BUFFER_SIZE       60
#define SAMPLE_INTERVAL_S  2
#define MEAS_DELAY_US     10000   /* 10 ms */
#define MAX_RETRIES       3

/* Si7021 Hold Master commands */
#define CMD_MEASURE_TEMP_HOLD   0xE3
#define CMD_MEASURE_HUMID_HOLD  0xE5

typedef struct {
    time_t timestamp;
    float  temperature;
    float  humidity;
} SensorData;

static SensorData data_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int i2c_handle = -1;
static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

/* Write a 16-bit command to the Si7021 */
static int si7021_write_cmd(uint8_t cmd)
{
    char buf[2] = { (char)cmd, 0x00 };
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (i2cWriteDevice(i2c_handle, buf, 2) == 0)
            return 0;
        gpioDelay(1000); /* 1 ms backoff */
    }
    return -1;
}

/* Read 2 bytes from the Si7021 (no command prefix) */
static int si7021_read_data(uint8_t *buf, int len)
{
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (i2cReadDevice(i2c_handle, (char *)buf, len) == len)
            return 0;
        gpioDelay(1000);
    }
    return -1;
}

/* Trigger a Hold Master measurement and read the 16-bit result */
static int si7021_measure(uint8_t cmd, uint16_t *raw)
{
    if (si7021_write_cmd(cmd) != 0)
        return -1;

    gpioDelay(MEAS_DELAY_US);

    uint8_t buf[2];
    if (si7021_read_data(buf, 2) != 0)
        return -1;

    *raw = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static float convert_temperature(uint16_t raw)
{
    return (175.72f * (float)raw / 65536.0f) - 46.85f;
}

static float convert_humidity(uint16_t raw)
{
    return (125.0f * (float)raw / 65536.0f) - 6.0f;
}

static void add_to_buffer(float temp, float hum)
{
    data_buffer[buffer_index].timestamp = time(NULL);
    data_buffer[buffer_index].temperature = temp;
    data_buffer[buffer_index].humidity = hum;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

static void print_buffer(void)
{
    printf("\n--- Sensor Data Buffer ---\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int idx = (buffer_index + i) % BUFFER_SIZE;
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S",
                 localtime(&data_buffer[idx].timestamp));
        printf("[%s] Temp: %.2f C, Hum: %.2f %%\n",
               ts, data_buffer[idx].temperature, data_buffer[idx].humidity);
    }
    printf("--- End of Buffer ---\n\n");
}

static void control_fan(float temp)
{
    static bool fan_on = false;
    if (temp > TEMP_THRESHOLD_HIGH && !fan_on) {
        if (gpioWrite(FAN_GPIO, 1) == 0) {
            fan_on = true;
            printf("Fan ON  (Temp: %.2f C)\n", temp);
        } else {
            fprintf(stderr, "Failed to turn fan ON\n");
        }
    } else if (temp < TEMP_THRESHOLD_LOW && fan_on) {
        if (gpioWrite(FAN_GPIO, 0) == 0) {
            fan_on = false;
            printf("Fan OFF (Temp: %.2f C)\n", temp);
        } else {
            fprintf(stderr, "Failed to turn fan OFF\n");
        }
    }
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %d\n",
                I2C_BUS, I2C_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", FAN_GPIO);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(FAN_GPIO, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Si7021 monitoring started (I2C bus %d, addr 0x%02X, fan GPIO%d)\n",
           I2C_BUS, I2C_ADDR, FAN_GPIO);
    printf("Threshold: ON > %.1f C, OFF < %.1f C\n", TEMP_THRESHOLD_HIGH, TEMP_THRESHOLD_LOW);
    printf("Press Ctrl+C to exit.\n\n");

    while (program_running) {
        uint16_t raw_temp = 0, raw_hum = 0;
        float temp = 0.0f, hum = 0.0f;

        if (si7021_measure(CMD_MEASURE_TEMP_HOLD, &raw_temp) != 0) {
            fprintf(stderr, "Temperature measurement failed (sensor absent or bus error)\n");
            gpioDelay(SAMPLE_INTERVAL_S * 1000000);
            continue;
        }
        if (si7021_measure(CMD_MEASURE_HUMID_HOLD, &raw_hum) != 0) {
            fprintf(stderr, "Humidity measurement failed (sensor absent or bus error)\n");
            gpioDelay(SAMPLE_INTERVAL_S * 1000000);
            continue;
        }

        temp = convert_temperature(raw_temp);
        hum  = convert_humidity(raw_hum);

        add_to_buffer(temp, hum);
        print_buffer();
        control_fan(temp);

        printf("Temp: %.2f C, Hum: %.2f %%\n", temp, hum);
        printf("Fan: %s\n", fan_on ? "ON" : "OFF");

        gpioDelay(SAMPLE_INTERVAL_S * 1000000);
    }

    /* Graceful shutdown */
    gpioWrite(FAN_GPIO, 0);
    if (i2c_handle >= 0)
        i2cClose(i2c_handle);
    gpioTerminate();
    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

