    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Si7021 monitoring started (I2C bus %d, addr 0x%02X, fan GPIO%d)\n",
           I2C_BUS, I2C_ADDR, FAN_GPIO);
    printf("Threshold: ON > %.1f C, OFF < %.1f C\n", TEMP_THRESHOLD_HIGH, TEMP_THRESHOLD_LOW);
    printf("Press Ctrl+C to exit.\n\n");

    while (program_running) {
        uint16_t raw_temp = 0, raw_hum = 0;
        float temp = 0.0f, hum = 0.0f;

        if (si7021_measure(CMD_MEASURE_TEMP_HOLD, &raw_temp) != 0) {
            fprintf(stderr, "Temperature measurement failed (sensor absent or bus error)\n");
            gpioDelay(SAMPLE_INTERVAL_S * 1000000);
            continue;
        }
        if (si7021_measure(CMD_MEASURE_HUMID_HOLD, &raw_hum) != 0) {
            fprintf(stderr, "Humidity measurement failed (sensor absent or bus error)\n");
            gpioDelay(SAMPLE_INTERVAL_S * 1000000);
            continue;
        }

        temp = convert_temperature(raw_temp);
        hum  = convert_humidity(raw_hum);

        add_to_buffer(temp, hum);
        print_buffer();
        control_fan(temp);

        printf("Temp: %.2f C, Hum: %.2f %%\n", temp, hum);
        printf("Fan: %s\n", fan_on ? "ON" : "OFF");

        gpioDelay(SAMPLE_INTERVAL_S * 1000000);
    }

    /* Graceful shutdown */
    gpioWrite(FAN_GPIO, 0);
    if (i2c_handle >= 0)
        i2cClose(i2c_handle);
    gpioTerminate();
    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

