#define STOP_PERIODIC_MEASUREMENT_CMD 0x3F86
#define DATA_READY_CMD 0xE4B8
#define READ_MEASUREMENT_CMD 0xEC05
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INIT 0xFF
#define SCD40_DATA_LENGTH 9
#define SCD40_DATA_BYTES 6
#define SCD40_CRC_BYTES 3

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = CRC8_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int send_command(uint16_t cmd) {
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (i2cWriteDevice(i2c_handle, (char *)buf, 2) != 0) {
        fprintf(stderr, "Error: Failed to send command 0x%04X\n", cmd);
        return -1;
    }
    return 0;
}

static int read_data(uint8_t *data) {
    if (i2cReadDevice(i2c_handle, (char *)data, SCD40_DATA_LENGTH) != SCD40_DATA_LENGTH) {
        fprintf(stderr, "Error: Failed to read data from SCD40\n");
        return -1;
    }
    return 0;
}

static int verify_crc(const uint8_t *data, int len) {
    for (int i = 0; i < len; i++) {
        if (crc8(&data[i * 2], 2) != data[i * 2 + 2]) {
            fprintf(stderr, "Error: CRC mismatch at byte %d\n", i * 2);
            return -1;
        }
    }
    return 0;
}

static int read_measurement(uint16_t *co2, float *temperature, float *humidity) {
    uint8_t data[SCD40_DATA_LENGTH];
    if (send_command(READ_MEASUREMENT_CMD) != 0)
        return -1;
    gpioDelay(1000);
    if (read_data(data) != 0)
        return -1;
    if (verify_crc(data, SCD40_DATA_BYTES) != 0)
        return -1;
    *co2 = (uint16_t)((data[0] << 8) | data[1]);
    uint16_t temp_raw = (uint16_t)((data[2] << 8) | data[3]);
    uint16_t hum_raw = (uint16_t)((data[4] << 8) | data[5]);
    *temperature = -45.0f + 175.0f * (float)temp_raw / 65535.0f;
    *humidity = 100.0f * (float)hum_raw / 65535.0f;
    return 0;
}

