    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at address 0x%02X on bus %d\n", SCD40_I2C_ADDR, I2C_BUS);
        gpioTerminate();
        return 1;
    }
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file %s\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    if (send_command(START_PERIODIC_MEASUREMENT_CMD) != 0) {
        fprintf(stderr, "Error: Failed to start periodic measurement\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    gpioDelay(1000000);
    while (!terminate) {
        if (send_command(DATA_READY_CMD) != 0) {
            fprintf(stderr, "Error: Failed to check data ready status\n");
            gpioDelay(MEASUREMENT_INTERVAL * 1000000);
            continue;
        }
        gpioDelay(1000);
        if (send_command(READ_MEASUREMENT_CMD) != 0) {
            fprintf(stderr, "Error: Failed to read measurement\n");
            gpioDelay(MEASUREMENT_INTERVAL * 1000000);
            continue;
        }
        gpioDelay(1000);
        uint8_t data[SCD40_DATA_LENGTH];
        if (read_data(data) != 0) {
            fprintf(stderr, "Error: Failed to read data from SCD40\n");
            gpioDelay(MEASUREMENT_INTERVAL * 1000000);
            continue;
        }
        if (verify_crc(data, SCD40_DATA_BYTES) != 0) {
            fprintf(stderr, "Error: CRC check failed for measurement data\n");
            gpioDelay(MEASUREMENT_INTERVAL * 1000000);
            continue;
        }
        uint16_t co2;
        float temperature, humidity;
        if (read_measurement(&co2, &temperature, &humidity) == 0) {
            log_data(co2, temperature, humidity);
        } else {
            fprintf(stderr, "Error: Failed to read measurement data\n");
        }
        gpioDelay(MEASUREMENT_INTERVAL * 1000000);
    }
    send_command(STOP_PERIODIC_MEASUREMENT_CMD);
    i2cClose(i2c_handle);
    gpioTerminate();
    if (log_file) fclose(log_file);
    return 0;
}

