#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SCD40_I2C_ADDR 0x62
#define I2C_BUS 1
#define LED_GPIO 17
#define CO2_THRESHOLD 1000
#define BUFFER_SIZE 20
#define MEASUREMENT_INTERVAL 5
#define MAX_RETRIES 10

#define CMD_START_PERIODIC_MEASUREMENT 0x21B1
#define CMD_STOP_PERIODIC_MEASUREMENT 0x3F86
#define CMD_GET_DATA_READY_STATUS 0xE4B8
#define CMD_READ_MEASUREMENT 0xEC05

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static int led_gpio = LED_GPIO;
static int buffer_index = 0;
static int buffer_count = 0;
static int32_t co2_buffer[BUFFER_SIZE];
static int temp_buffer[BUFFER_SIZE];
static int hum_buffer[BUFFER_SIZE];

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int scd40_write_cmd(int handle, uint16_t cmd) {
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (i2cWriteDevice(handle, (char *)buf, 2) != 0) {
        fprintf(stderr, "I2C write failed for command 0x%04X\n", cmd);
        return -1;
    }
    return 0;
}

static int scd40_read_data(int handle, uint8_t *data, int len) {
    if (i2cReadDevice(handle, (char *)data, len) != len) {
        fprintf(stderr, "I2C read failed (expected %d bytes)\n", len);
        return -1;
    }
    return 0;
}

static int scd40_start_periodic_measurement(int handle) {
    if (scd40_write_cmd(handle, CMD_START_PERIODIC_MEASUREMENT) != 0)
        return -1;
    gpioDelay(2000);
    return 0;
}

static int scd40_stop_periodic_measurement(int handle) {
    if (scd40_write_cmd(handle, CMD_STOP_PERIODIC_MEASUREMENT) != 0)
        return -1;
    gpioDelay(2000);
    return 0;
}

static int scd40_get_data_ready_status(int handle, uint16_t *status) {
    if (scd40_write_cmd(handle, CMD_GET_DATA_READY_STATUS) != 0)
        return -1;
    gpioDelay(2000);
    uint8_t data[3];
    if (scd40_read_data(handle, data, 3) != 0)
        return -1;
    if (crc8(data, 2) != data[2]) {
        fprintf(stderr, "CRC mismatch on data ready status\n");
        return -1;
    }
    *status = ((uint16_t)data[0] << 8) | data[1];
    return 0;
}

static int scd40_read_measurement(int handle, int32_t *co2, float *temp, float *hum) {
    if (scd40_write_cmd(handle, CMD_READ_MEASUREMENT) != 0)
        return -1;
    gpioDelay(2000);
    uint8_t data[9];
    if (scd40_read_data(handle, data, 9) != 0)
        return -1;
    for (int i = 0; i < 3; i++) {
        if (crc8(&data[i * 3], 2) != data[i * 3 + 2]) {
            fprintf(stderr, "CRC mismatch on measurement word %d\n", i);
            return -1;
        }
    }
    *co2 = ((int32_t)data[0] << 8) | data[1];
    uint16_t t_raw = ((uint16_t)data[3] << 8) | data[4];
    uint16_t h_raw = ((uint16_t)data[6] << 8) | data[7];
    *temp = -45.0f + 175.0f * (float)t_raw / 65535.0f;
    *hum = 100.0f * (float)h_raw / 65535.0f;
    return 0;
}

static void buffer_add(int32_t co2, float temp, float hum) {
    co2_buffer[buffer_index] = co2;
    temp_buffer[buffer_index] = (int32_t)(temp + 0.5f);
    hum_buffer[buffer_index] = (int32_t)(hum + 0.5f);
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE)
        buffer_count++;
}

static void buffer_print(void) {
    printf("\n--- CO2 Buffer ---\n");
    int start = (buffer_count < BUFFER_SIZE) ? 0 : buffer_index;
    for (int i = 0; i < buffer_count; i++) {
        int idx = (start + i) % BUFFER_SIZE;
        printf("CO2: %d ppm, Temp: %.1f C, Hum: %.1f %%\n",
               co2_buffer[idx], temp_buffer[idx] / 100.0f, hum_buffer[idx] / 100.0f);
    }
    printf("--- End of Buffer ---\n\n");
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        scd40_stop_periodic_measurement(i2c_handle);
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(led_gpio, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SCD40_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X\n", I2C_BUS, SCD40_I2C_ADDR);
        gpioTerminate();
        return 1;
    }

    if (scd40_start_periodic_measurement(i2c_handle) != 0) {
        fprintf(stderr, "Failed to start periodic measurement\n");
        cleanup();
        return 1;
    }

    gpioSetMode(led_gpio, PI_OUTPUT);
    gpioWrite(led_gpio, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    uint16_t ready = 0;
    int consecutive_errors = 0;

    while (running) {
        if (scd40_get_data_ready_status(i2c_handle, &ready) != 0) {
            consecutive_errors++;
            if (consecutive_errors > MAX_RETRIES) {
                fprintf(stderr, "Too many consecutive I2C errors, aborting\n");
                break;
            }
            gpioDelay(100000);
            continue;
        }
        consecutive_errors = 0;

        if (ready & 0x0001) {
            int32_t co2;
            float temp, hum;
            if (scd40_read_measurement(i2c_handle, &co2, &temp, &hum) == 0) {
                buffer_add(co2, temp, hum);
                printf("CO2: %d ppm, Temp: %.1f C, Hum: %.1f %%\n", co2, temp, hum);
                if (co2 > CO2_THRESHOLD)
                    gpioWrite(led_gpio, 1);
                else
                    gpioWrite(led_gpio, 0);
            } else {
                fprintf(stderr, "Failed to read measurement\n");
            }
            ready = 0;
        } else {
            gpioDelay(100000);
        }
    }

    buffer_print();
    cleanup();
    return 0;
}

