#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define GPIO_PIN 4
#define LOG_FILE "temperature_log.txt"
#define SAMPLE_INTERVAL_US 5000000
#define TIMEOUT_US 50000
#define MIN_TEMP -40.0f
#define MAX_TEMP 150.0f
#define MAX_CONSECUTIVE_ERRORS 3

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);
    return 0;
}

static int read_temperature(float *temperature) {
    uint32_t start_tick, end_tick, th_tick, tl_tick;
    int timeout;

    /* Wait for rising edge (sensor starts outputting) */
    timeout = 0;
    while (gpioRead(GPIO_PIN) == 0) {
        if (gpioTick() - start_tick > TIMEOUT_US) {
            fprintf(stderr, "Error: No rising edge detected (sensor absent or stuck)\n");
            return -1;
        }
        gpioDelay(100);
    }
    start_tick = gpioTick();

    /* Wait for falling edge (sensor completes cycle) */
    timeout = 0;
    while (gpioRead(GPIO_PIN) == 1) {
        if (gpioTick() - start_tick > TIMEOUT_US) {
            fprintf(stderr, "Error: No falling edge detected (stuck line or sensor fault)\n");
            return -1;
        }
        gpioDelay(100);
    }
    end_tick = gpioTick();

    th_tick = end_tick - start_tick;
    tl_tick = gpioTick() - start_tick;

    if (tl_tick == 0) {
        fprintf(stderr, "Error: Division by zero (sensor not cycling)\n");
        return -1;
    }

    float ratio = (float)th_tick / (float)tl_tick;
    *temperature = 4215.0f - (2143.0f * ratio);

    if (*temperature < MIN_TEMP || *temperature > MAX_TEMP) {
        fprintf(stderr, "Warning: Temperature out of range: %.2f C\n", *temperature);
        return -1;
    }

    return 0;
}

static void log_temperature(float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: localtime failed\n");
        return;
    }
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, %.2f\n", timestamp, temperature);
        fflush(log_file);
    } else {
        fprintf(stderr, "Error: Log file not open\n");
    }
}

static void log_error(const char *message) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: localtime failed\n");
        return;
    }
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, ERROR: %s\n", timestamp, message);
        fflush(log_file);
    } else {
        fprintf(stderr, "Error: Log file not open\n");
    }
}

int main(void) {
    float temperature;
    int consecutive_errors = 0;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    if (init_gpio() != 0) {
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Cannot open log file '%s': %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return 1;
    }

    printf("Temperature monitoring started on GPIO%d. Press Ctrl+C to exit.\n", GPIO_PIN);

    while (running) {
        if (read_temperature(&temperature) == 0) {
            log_temperature(temperature);
            consecutive_errors = 0;
        } else {
            consecutive_errors++;
            log_error("Failed to read temperature");
            if (consecutive_errors >= MAX_CONSECUTIVE_ERRORS) {
                log_error("Sensor malfunction after 3 consecutive failures");
            }
        }

        /* Sleep in small increments to allow signal handler to interrupt promptly */
        for (int i = 0; i < 50 && running; i++) {
            gpioDelay(100000);
        }
    }

    printf("\nShutting down...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    return 0;
}

