#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SHT35_ADDR 0x44
#define MEASURE_CMD_HIGH 0x24
#define MEASURE_CMD_LOW 0x00
#define MEASUREMENT_DELAY_US 15000
#define RETRY_COUNT 3
#define RETRY_DELAY_S 1
#define LOG_INTERVAL_S 5
#define LOG_FILE_NAME "environmental_data.txt"

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int bit = 0; bit < 8; bit++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

static int read_sht35(int handle, float *temperature, float *humidity) {
    uint8_t cmd[2] = {MEASURE_CMD_HIGH, MEASURE_CMD_LOW};
    uint8_t buf[6];
    int result;

    for (int attempt = 0; attempt < RETRY_COUNT; attempt++) {
        result = i2cWriteDevice(handle, (char *)cmd, 2);
        if (result != 0) {
            fprintf(stderr, "I2C write failed (attempt %d): %d\n", attempt + 1, result);
            gpioDelay(RETRY_DELAY_S * 1000000);
            continue;
        }

        gpioDelay(MEASUREMENT_DELAY_US);

        result = i2cReadDevice(handle, (char *)buf, 6);
        if (result != 6) {
            fprintf(stderr, "I2C read failed (attempt %d): got %d bytes\n", attempt + 1, result);
            gpioDelay(RETRY_DELAY_S * 1000000);
            continue;
        }

        if (crc8(&buf[0], 2) != buf[2]) {
            fprintf(stderr, "Temperature CRC mismatch (attempt %d)\n", attempt + 1);
            gpioDelay(RETRY_DELAY_S * 1000000);
            continue;
        }

        if (crc8(&buf[3], 2) != buf[5]) {
            fprintf(stderr, "Humidity CRC mismatch (attempt %d)\n", attempt + 1);
            gpioDelay(RETRY_DELAY_S * 1000000);
            continue;
        }

        uint16_t temp_raw = (buf[0] << 8) | buf[1];
        uint16_t hum_raw = (buf[3] << 8) | buf[4];

        *temperature = -45.0f + 175.0f * (float)temp_raw / 65535.0f;
        *humidity = 100.0f * (float)hum_raw / 65535.0f;

        return 0;
    }

    fprintf(stderr, "All %d retries failed for SHT35 read\n", RETRY_COUNT);
    *temperature = NAN;
    *humidity = NAN;
    return -1;
}

static void simulate_offset(float *temperature, float *humidity, float t_offset, float h_offset) {
    time_t now = time(NULL);
    float t = (float)now / 3600.0f * 2.0f * M_PI * 2.0f;
    *temperature += t_offset * sinf(t);
    *humidity += h_offset * sinf(t);
}

static int log_data(FILE *fp, float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm *utc = gmtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", utc);

    if (isnan(temperature) || isnan(humidity)) {
        fprintf(fp, "%s, NaN, NaN\n", timestamp);
    } else {
        fprintf(fp, "%s, %.2f, %.2f\n", timestamp, temperature, humidity);
    }

    fflush(fp);
    return 0;
}

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SHT35_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at bus %d, addr 0x%02X: %d\n", I2C_BUS, SHT35_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE_NAME, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file '%s'\n", LOG_FILE_NAME);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    float temperature, humidity;
    float t_offset = 2.0f;
    float h_offset = 5.0f;

    while (!terminate) {
        if (read_sht35(i2c_handle, &temperature, &humidity) == 0) {
            simulate_offset(&temperature, &humidity, t_offset, h_offset);
            log_data(log_file, temperature, humidity);
        } else {
            fprintf(stderr, "Sensor read failed; logging NaN values\n");
        }

        for (int i = 0; i < LOG_INTERVAL_S && !terminate; i++) {
            sleep(1);
        }
    }

    cleanup();
    return 0;
}

