    } else {
        fprintf(fp, "%s, %.2f, %.2f\n", timestamp, temperature, humidity);
    }

    fflush(fp);
    return 0;
}

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SHT35_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at bus %d, addr 0x%02X: %d\n", I2C_BUS, SHT35_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE_NAME, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file '%s'\n", LOG_FILE_NAME);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    float temperature, humidity;
    float t_offset = 2.0f;
    float h_offset = 5.0f;

    while (!terminate) {
        if (read_sht35(i2c_handle, &temperature, &humidity) == 0) {
            simulate_offset(&temperature, &humidity, t_offset, h_offset);
            log_data(log_file, temperature, humidity);
        } else {
            fprintf(stderr, "Sensor read failed; logging NaN values\n");
        }

        for (int i = 0; i < LOG_INTERVAL_S && !terminate; i++) {
            sleep(1);
        }
    }

    cleanup();
    return 0;
}

