#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define SI7021_ADDR        0x40
#define I2C_BUS            "/dev/i2c-1"
#define LOG_FILE           "environment.log"
#define POLL_TIMEOUT_MS    100
#define SAMPLE_INTERVAL_S  5

/* No-Hold Master commands */
#define CMD_MEASURE_RH_NOHOLD   0xF5
#define CMD_MEASURE_TEMP_NOHOLD 0xF3
#define CMD_RESET               0xFE
#define CMD_READ_TEMP_PREV_RH   0xE0

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

/* CRC-8 as used by Sensirion: poly 0x31, init 0x00 */
static uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0x00;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static int i2c_write_cmd(int fd, uint8_t cmd) {
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "I2C write failed (cmd 0x%02X): %s\n", cmd, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len) {
    ssize_t n = read(fd, buf, len);
    if (n < 0) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    if ((size_t)n != len) {
        fprintf(stderr, "I2C read short: got %zd of %zu bytes\n", n, len);
        return -1;
    }
    return 0;
}

static int read_measurement(int fd, uint8_t cmd, uint16_t *raw) {
    uint8_t buf[3];
    int attempts = 0;

    while (attempts < POLL_TIMEOUT_MS) {
        if (i2c_write_cmd(fd, cmd) < 0) {
            attempts++;
            usleep(1000);
