#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define I2C_BUS 1
#define I2C_ADDR 0x28
#define FAN_GPIO 18
#define PWM_FREQ 25000
#define SAMPLE_INTERVAL_US 100000
#define LOG_FILE "flow_log.txt"

#define STATUS_MASK 0xC000
#define FLOW_SCALE_FACTOR 1638.0f
#define FLOW_MAX 14745.0f
#define FLOW_MAX_SLPM 10.0f

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_sensor(int handle, float *pressure_pa) {
    char buf[2];
    int bytes_read = i2cReadDevice(handle, buf, 2);
    if (bytes_read != 2) {
        fprintf(stderr, "I2C read failed: expected 2 bytes, got %d\n", bytes_read);
        return -1;
    }
    uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    uint16_t flow_raw = (raw & STATUS_MASK) >> 2;
    *pressure_pa = (float)flow_raw * 0.1f;
    return 0;
}

static int set_fan_speed(float flow_rate) {
    if (flow_rate < 0.0f) flow_rate = 0.0f;
    if (flow_rate > FLOW_MAX_SLPM) flow_rate = FLOW_MAX_SLPM;
    float duty = (flow_rate / FLOW_MAX_SLPM) * 255.0f;
    if (duty < 0.0f) duty = 0.0f;
    if (duty > 255.0f) duty = 255.0f;
    if (gpioPWM(FAN_GPIO, (int)duty) != 0) {
        fprintf(stderr, "gpioPWM failed\n");
        return -1;
    }
    return 0;
}

static void log_data(FILE *fp, float pressure_pa) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%.2f\n", ts, pressure_pa);
    fflush(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed: %d\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioSetPWMfrequency(FAN_GPIO, PWM_FREQ);
    gpioPWM(FAN_GPIO, 0);

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Flow control started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        float pressure_pa;
        if (read_sensor(i2c_handle, &pressure_pa) == 0) {
            log_data(log_file, pressure_pa);
            set_fan_speed(pressure_pa);
        } else {
            fprintf(stderr, "Sensor read error, continuing...\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    gpioPWM(FAN_GPIO, 0);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    if (log_file) fclose(log_file);
    gpioTerminate();
    printf("Flow control stopped.\n");
    return EXIT_SUCCESS;
}

