#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define LPS33HW_ADDR 0x5D
#define WHO_AM_I_REG 0x0F
#define WHO_AM_I_VAL 0xB1
#define CTRL_REG1 0x10
#define CTRL_REG1_VAL 0xB0
#define PRESS_OUT_XL 0x28
#define TEMP_OUT_L 0x2B

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_reg8(int handle, uint8_t reg, uint8_t *val) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read error on reg 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    *val = (uint8_t)rc;
    return 0;
}

static int write_reg8(int handle, uint8_t reg, uint8_t val) {
    int rc = i2cWriteByteData(handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "I2C write error on reg 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len) {
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc < 0) {
        fprintf(stderr, "I2C block read error on reg 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    if ((uint32_t)rc != len) {
        fprintf(stderr, "I2C block read short: got %d, expected %u\n", rc, len);
        return -1;
    }
    return 0;
}

static int init_lps33hw(int handle) {
    uint8_t whoami;
    if (read_reg8(handle, WHO_AM_I_REG, &whoami) != 0) {
        fprintf(stderr, "Cannot read WHO_AM_I\n");
        return -1;
    }
    if (whoami != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n", whoami, WHO_AM_I_VAL);
        return -1;
    }
    if (write_reg8(handle, CTRL_REG1, CTRL_REG1_VAL) != 0) {
        fprintf(stderr, "Cannot write CTRL_REG1\n");
        return -1;
    }
    return 0;
}

static int read_pressure(int handle, float *pressure) {
    uint8_t buf[3];
    if (read_block(handle, PRESS_OUT_XL, buf, 3) != 0) {
        return -1;
    }
    int32_t raw = ((int32_t)buf[2] << 16) | ((int32_t)buf[1] << 8) | buf[0];
    if (raw & 0x800000) {
        raw |= 0xFF000000;
    }
    *pressure = (float)raw / 4096.0f;
    return 0;
}

static int read_temperature(int handle, float *temperature) {
    uint8_t buf[2];
    if (read_block(handle, TEMP_OUT_L, buf, 2) != 0) {
        return -1;
    }
    int16_t raw = (int16_t)((buf[1] << 8) | buf[0]);
    *temperature = 42.5f + (float)raw / 480.0f;
    return 0;
}

static void log_data(float pressure, float temperature) {
    time_t now = time(NULL);
    struct tm tm_info;
    localtime_r(&now, &tm_info);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    fprintf(log_file, "%s, Pressure: %.2f hPa, Temperature: %.2f °C\n", timestamp, pressure, temperature);
    fflush(log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, LPS33HW_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (init_lps33hw(i2c_handle) != 0) {
        fprintf(stderr, "LPS33HW initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen("environmental_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    while (!terminate) {
        float pressure, temperature;
        if (read_pressure(i2c_handle, &pressure) == 0 && read_temperature(i2c_handle, &temperature) == 0) {
            log_data(pressure, temperature);
        } else {
            time_t now = time(NULL);
            struct tm tm_info;
            localtime_r(&now, &tm_info);
            char timestamp[64];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
            fprintf(stderr, "%s, Error reading sensor data\n", timestamp);
            fprintf(log_file, "%s, Error reading sensor data\n", timestamp);
            fflush(log_file);
        }
        gpioDelay(1000000);
    }

    fprintf(stderr, "Shutting down...\n");
    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

