#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

#define SDP32_ADDR 0x21
#define I2C_BUS 1
#define DEFAULT_INTERVAL_MS 1000
#define MEASUREMENT_DELAY_US 10000
#define READ_LEN 9

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

static int init_sdp32(void) {
    uint8_t cmd[2] = {0x36, 0x2F};
    int result = i2cWriteDevice(i2c_handle, (char *)cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Error: Failed to write continuous-measurement command to SDP32 (pigpio error %d).\n", result);
        return -1;
    }
    gpioDelay(2000);
    return 0;
}

static int read_sdp32(float *pressure_pa) {
    uint8_t buf[READ_LEN];
    int result = i2cReadDevice(i2c_handle, (char *)buf, READ_LEN);
    if (result != READ_LEN) {
        fprintf(stderr, "Error: I2C read failed (pigpio error %d).\n", result);
        return -1;
    }

    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "Error: Pressure CRC mismatch.\n");
        return -1;
    }
    if (crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "Error: Temperature CRC mismatch.\n");
        return -1;
    }
    if (crc8(&buf[6], 2) != buf[8]) {
        fprintf(stderr, "Error: Scale-factor CRC mismatch.\n");
        return -1;
    }

    int16_t raw_pressure = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t scale_factor = (int16_t)((buf[6] << 8) | buf[7]);

    if (scale_factor == 0) {
        fprintf(stderr, "Error: Invalid scale factor (0).\n");
        return -1;
    }

    *pressure_pa = (float)raw_pressure / (float)scale_factor;
    return 0;
}

static void log_data(float pressure_pa) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("[%s] Differential Pressure: %.2f Pa\n", timestamp, pressure_pa);
    fflush(stdout);
}

int main(int argc, char *argv[]) {
    int interval_ms = DEFAULT_INTERVAL_MS;

    if (argc > 1) {
        interval_ms = atoi(argv[1]);
        if (interval_ms <= 0) {
            fprintf(stderr, "Error: Invalid interval '%s'. Using default %d ms.\n", argv[1], DEFAULT_INTERVAL_MS);
            interval_ms = DEFAULT_INTERVAL_MS;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SDP32_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d at address 0x%02X (pigpio error %d).\n", I2C_BUS, SDP32_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (init_sdp32() != 0) {
        fprintf(stderr, "Error: SDP32 sensor not detected or communication failed. Check wiring and I2C address.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("SDP32 differential pressure sensor logging started. Interval: %d ms. Press Ctrl+C to exit.\n", interval_ms);

    while (running) {
        float pressure_pa;
        if (read_sdp32(&pressure_pa) == 0) {
            log_data(pressure_pa);
        } else {
            fprintf(stderr, "Warning: Sensor read failed, retrying in %d ms...\n", interval_ms);
        }
        gpioDelay(interval_ms * 1000);
    }

    printf("\nExiting gracefully...\n");
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

