#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SDP810_ADDR    0x25
#define MEASURE_CMD    0x3615
#define CONV_DELAY_US  45000   /* 45 ms conversion time */
#define SAMPLE_US      1000000 /* 1 second between samples */
#define READ_LEN       9

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* CRC-8 as used by Sensirion: poly 0x31, init 0xFF, no final XOR */
static uint8_t crc8(const uint8_t *data, int len)
{
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static int sdp810_read(int handle, float *pressure, float *temperature)
{
    uint8_t cmd[2] = { (uint8_t)(MEASURE_CMD >> 8), (uint8_t)(MEASURE_CMD & 0xFF) };
    uint8_t buf[READ_LEN];

    if (i2cWriteDevice(handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "Error: failed to write measurement command to I2C device.\n");
        return -1;
    }

    gpioDelay(CONV_DELAY_US);

    if (i2cReadDevice(handle, (char *)buf, READ_LEN) != READ_LEN) {
        fprintf(stderr, "Error: failed to read 9 bytes from I2C device (sensor may be absent).\n");
        return -1;
    }

    /* Validate CRC for each 3-byte word */
    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "Error: CRC mismatch on pressure word.\n");
        return -1;
    }
    if (crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "Error: CRC mismatch on temperature word.\n");
        return -1;
    }
    if (crc8(&buf[6], 2) != buf[8]) {
        fprintf(stderr, "Error: CRC mismatch on scale-factor word.\n");
        return -1;
    }

    int16_t raw_pressure    = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_temperature = (int16_t)((buf[3] << 8) | buf[4]);
    uint16_t scale_factor   = (uint16_t)((buf[6] << 8) | buf[7]);

    if (scale_factor == 0) {
        fprintf(stderr, "Error: invalid scale factor (0) from sensor.\n");
        return -1;
    }

    *pressure    = (float)raw_pressure    / (float)scale_factor;
    *temperature = (float)raw_temperature / 200.0f;

    return 0;
}

int main(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: failed to open I2C bus %d at address 0x%02X (handle=%d).\n",
                I2C_BUS, SDP810_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("SDP810-125Pa sensor reader started on I2C bus %d, address 0x%02X.\n",
           I2C_BUS, SDP810_ADDR);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        float pressure, temperature;

        if (sdp810_read(g_i2c_handle, &pressure, &temperature) == 0) {
            printf("Pressure: %.2f Pa, Temperature: %.2f C\n", pressure, temperature);
        } else {
            fprintf(stderr, "Warning: sensor read failed, will retry next cycle.\n");
        }

        gpioDelay(SAMPLE_US);
    }

    printf("\nShutting down...\n");
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

