#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define HDC1000_ADDR        0x40
#define I2C_BUS             "/dev/i2c-1"
#define CONFIG_REG          0x02
#define TEMP_REG            0x00
#define CONV_DELAY_MS       20
#define POLL_INTERVAL_S     5

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "i2c_write_reg8(0x%02X, 0x%02X) failed: %s\n",
                reg, value, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_reg16: write pointer 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    uint8_t buf[2];
    ssize_t n = read(fd, buf, 2);
    if (n != 2) {
        fprintf(stderr, "i2c_read_reg16: read from 0x%02X failed (got %zd bytes): %s\n",
                reg, n, n < 0 ? strerror(errno) : "short read");
        return -1;
    }
    *out = (uint16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int init_hdc1000(int fd)
{
    /* Configuration Register (0x02):
     *   Bit 12: DRDYn (1 = enable combined measurement)
     *   Bits 11:10 = TRES (0 = 14-bit)
     *   Bit  9  = ODR (0 = 1 Hz)
     *   Bit  8  = MEAS (1 = start measurement)
     *   Bits 7:5 = TRES (0 = 14-bit)
     *   Bit  4  = HRES (0 = 14-bit)
     *   Bit  3  = HINT (0 = no hint)
     *   Bit  2  = HINT (0 = no hint)
     *   Bit  1  = HINT (0 = no hint)
     *   Bit  0  = HINT (0 = no hint)
     * => 0x0000 | (1 << 12) | (1 << 9) | (1 << 5) = 0x4000
     */
    if (i2c_write_reg8(fd, CONFIG_REG, 0x4000) < 0)
        return -1;
    return 0;
}

static int read_hdc1000(int fd, float *temp_c, float *rh)
{
    /* Trigger a temperature measurement by writing the temperature register pointer */
    if (write(fd, &TEMP_REG, 1) != 1) {
        fprintf(stderr, "Failed to write temperature register pointer: %s\n",
                strerror(errno));
        return -1;
    }

    /* Wait for the 14-bit conversion to complete (DRDYn is not connected) */
    usleep(CONV_DELAY_MS * 1000);

    uint16_t raw_t, raw_h;
    if (i2c_read_reg16(fd, TEMP_REG, &raw_t) < 0)
        return -1;
    if (i2c_read_reg16(fd, TEMP_REG + 2, &raw_h) < 0)
        return -1;

    *temp_c = ((float)raw_t / 65536.0f) * 165.0f - 40.0f;
    *rh     = ((float)raw_h / 65536.0f) * 100.0f;
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, HDC1000_ADDR) < 0) {
        fprintf(stderr, "ioctl I2C_SLAVE 0x%02X failed: %s\n",
                HDC1000_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    if (init_hdc1000(fd) < 0) {
        fprintf(stderr, "HDC1000 initialization failed (sensor absent or bus error).\n");
        close(fd);
        return EXIT_FAILURE;
    }

    printf("HDC1000 initialized on %s at 0x%02X. Polling every %d s.\n",
           I2C_BUS, HDC1000_ADDR, POLL_INTERVAL_S);
    fflush(stdout);

    while (g_running) {
        float temp_c, rh;
        if (read_hdc1000(fd, &temp_c, &rh) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temp_c, rh);
            fflush(stdout);
        } else {
            fprintf(stderr, "Read failed; will retry next cycle.\n");
        }
        sleep(POLL_INTERVAL_S);
    }

    printf("\nExiting cleanly.\n");
    close(fd);
    return EXIT_SUCCESS;
}

