#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS 1
#define SI7051_ADDR 0x40
#define TEMP_REG 0x00
#define MEASUREMENT_INTERVAL 5
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_temperature(float *temperature) {
    char buf[2];
    int result;

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        result = i2cReadI2CBlockData(i2c_handle, TEMP_REG, buf, 2);
        if (result == 2) {
            uint16_t raw_temp = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
            *temperature = (float)raw_temp / 100.0f;
            return 0;
        }
        fprintf(stderr, "I2C read failed (attempt %d/%d): %s\n",
                attempt + 1, MAX_RETRIES, strerror(errno));
        if (attempt < MAX_RETRIES - 1) {
            gpioDelay(100000);
        }
    }
    return -1;
}

static void log_temperature(float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    printf("[%s] Temperature: %.2f °C\n", timestamp, temperature);
    fflush(stdout);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI7051_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at bus %d, addr 0x%02X: %s\n",
                I2C_BUS, SI7051_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Si7051 temperature logger started. Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (running) {
        float temperature;
        if (read_temperature(&temperature) == 0) {
            log_temperature(temperature);
        } else {
            fprintf(stderr, "Failed to read temperature after %d attempts.\n", MAX_RETRIES);
        }
        for (int i = 0; i < MEASUREMENT_INTERVAL && running; i++) {
            gpioDelay(1000000);
        }
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    printf("\nProgram terminated gracefully.\n");
    return EXIT_SUCCESS;
}

