/*
 * MLX90833 Absolute Pressure Sensor Reader for Raspberry Pi 4 Model B
 * Uses pigpio for I2C communication.
 *
 * Wiring:
 *   MLX90833 SDA -> GPIO 2 (I2C bus 1 SDA)
 *   MLX90833 SCL -> GPIO 3 (I2C bus 1 SCL)
 *   MLX90833 VDD -> 3.3 V
 *   MLX90833 GND -> GND
 *
 * Build: gcc -Wall -Wextra -O2 -o mlx90833_reader mlx90833_reader.c -lpigpio -lrt
 * Run:   sudo ./mlx90833_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x60
#define READ_INTERVAL  500000   /* microseconds (500 ms) */
#define MAX_RETRIES    3

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void install_signal_handlers(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0)
        perror("sigaction(SIGINT)");
    if (sigaction(SIGTERM, &sa, NULL) != 0)
        perror("sigaction(SIGTERM)");
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_byte(int handle, uint8_t byte)
{
    if (i2cWriteByte(handle, byte) < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByte(0x%02X) failed\n", byte);
        return -1;
    }
    return 0;
}

static int i2c_read_block(int handle, uint8_t *buf, uint32_t len)
{
    int bytes = i2cReadDevice(handle, (char *)buf, len);
    if (bytes != (int)len) {
        fprintf(stderr, "[ERROR] i2cReadDevice: expected %u bytes, got %d\n",
                len, bytes);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor abstraction                                                  */
/* ------------------------------------------------------------------ */
/*
 * The MLX90833 is a 16-bit absolute pressure sensor.
 * A typical 3-byte read sequence (MSB, LSB, CRC) might look like:
 *   [0x80, 0x0A, 0x0B]  ->  pressure = (0x80 << 8) | 0x0A = 0x807A
 * The exact register/command sequence depends on the MLX90833
 * firmware/software configuration.  This implementation uses a
 * generic 3-byte read of the latest two data bytes from the
 * device's default address.
 */
static int read_pressure(int handle, uint16_t *pressure_out)
{
    uint8_t buf[3];
