/* Sensor abstraction                                                  */
/* ------------------------------------------------------------------ */
/*
 * The MLX90833 is a 16-bit absolute pressure sensor.
 * A typical 3-byte read sequence (MSB, LSB, CRC) might look like:
 *   [0x80, 0x0A, 0x0B]  ->  pressure = (0x80 << 8) | 0x0A = 0x807A
 * The exact register/command sequence depends on the MLX90833
 * firmware/software configuration.  This implementation uses a
 * generic 3-byte read of the latest two data bytes from the
 * device's default address.
 */
static int read_pressure(int handle, uint16_t *pressure_out)
{
    uint8_t buf[3];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2c_read_block(handle, buf, sizeof(buf)) == 0) {
            /* Bytes 0 and 1 are the two most recent data bytes.
             * Bytes 2 is the CRC; we ignore it. */
            uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
            *pressure_out = raw;
            return 0;
        }
        retries++;
        if (retries < MAX_RETRIES)
            gpioDelay(10000); /* 10 ms backoff before retry */
    }

    fprintf(stderr, "[ERROR] Failed to read pressure after %d retries\n",
            MAX_RETRIES);
