    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("MLX90833 Pressure Sensor Reader\n");
    printf("I2C bus %d, address 0x%02X, interval %d ms\n",
           I2C_BUS, I2C_ADDR, READ_INTERVAL / 1000);
    printf("Press Ctrl+C to exit.\n\n");

    while (g_running) {
        uint16_t pressure = 0;

        if (read_pressure(g_i2c_handle, &pressure) == 0) {
            time_t now = time(NULL);
            struct tm tm_info;
            char ts[32];

            if (localtime_r(&now, &tm_info) != NULL) {
                strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);
                printf("[%s] Pressure: %u\n", ts, pressure);
            } else {
                printf("[UNKNOWN TIME] Pressure: %u\n", pressure);
            }
            fflush(stdout);
        } else {
            fprintf(stderr, "[WARN] Skipping sample due to read failure\n");
        }

        /* Sleep in small increments so signals are caught promptly. */
        for (int i = 0; i < (READ_INTERVAL + 1000) / 1000 && g_running; i++)
            gpioDelay(1000);
    }

