#include <pigpio.h>

#define I2C_BUS        1
#define ICP10101_ADDR  0x63
#define MEAS_CMD_HIGH  0x40
#define OTP_READ_CMD   0x50
#define OTP_READ_LEN   8
#define MEAS_DELAY_US  7000
#define SAMPLE_PERIOD  5

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int read_otp_coefficients(int handle, uint16_t *c0, uint16_t *c1,
                                 uint16_t *c00, uint16_t *c01)
{
    char cmd[1] = { OTP_READ_CMD };
    char buf[OTP_READ_LEN];

    if (i2cWriteDevice(handle, cmd, 1) != 0) {
        fprintf(stderr, "Error: failed to write OTP read command\n");
        return -1;
    }
    gpioDelay(2000);

    int n = i2cReadDevice(handle, buf, OTP_READ_LEN);
    if (n != OTP_READ_LEN) {
        fprintf(stderr, "Error: OTP read returned %d bytes (expected %d)\n",
                n, OTP_READ_LEN);
        return -1;
    }

    *c0  = (uint16_t)((buf[0] << 8) | buf[1]);
    *c1  = (uint16_t)((buf[2] << 8) | buf[3]);
    *c00 = (uint16_t)((buf[4] << 8) | buf[5]);
    *c01 = (uint16_t)((buf[6] << 8) | buf[7]);
    return 0;
}

static int read_raw_measurement(int handle, int32_t *raw_temp, int32_t *raw_press)
{
    char cmd[1] = { MEAS_CMD_HIGH };
    char buf[6];

    if (i2cWriteDevice(handle, cmd, 1) != 0) {
        fprintf(stderr, "Error: failed to trigger measurement\n");
        return -1;
    }
    gpioDelay(MEAS_DELAY_US);

    int n = i2cReadDevice(handle, buf, 6);
    if (n != 6) {
        fprintf(stderr, "Error: measurement read returned %d bytes (expected 6)\n",
                n);
        return -1;
    }

    *raw_press = (int32_t)(((uint8_t)buf[0] << 8) | (uint8_t)buf[1]);
    *raw_temp  = (int32_t)(((uint8_t)buf[3] << 8) | (uint8_t)buf[4]);
    return 0;
}

static void compensate(int32_t raw_t, int32_t raw_p,
                        uint16_t c0, uint16_t c1,
                        uint16_t c00, uint16_t c01,
                        float *temp_c, float *press_pa)
{
    float t = (float)raw_t;
    float p = (float)raw_p;

    float t_comp = t - 32768.0f;
    float p_comp = p - 32768.0f;

    float t_lut = (float)c0 * 0.5f + (float)c1 * t_comp / 65536.0f;
    float p_lut = (float)c00 * 0.5f + (float)c01 * t_comp / 65536.0f;

    *temp_c = t_lut * 0.5f;
    *press_pa = p_lut * 100.0f;
}

static void log_data(float temp_c, float press_pa)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
    printf("%s - Temperature: %.2f C, Pressure: %.2f Pa\n", ts, temp_c, press_pa);
    fflush(stdout);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, ICP10101_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d)\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    uint16_t c0, c1, c00, c01;
    if (read_otp_coefficients(g_i2c_handle, &c0, &c1, &c00, &c01) != 0) {
        fprintf(stderr, "Error: cannot read OTP coefficients — sensor may be absent\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("ICP-10101 initialised. Sampling every %d s. Press Ctrl+C to stop.\n",
           SAMPLE_PERIOD);

    while (g_running) {
        int32_t raw_t = 0, raw_p = 0;
        if (read_raw_measurement(g_i2c_handle, &raw_t, &raw_p) == 0) {
            float temp_c, press_pa;
            compensate(raw_t, raw_p, c0, c1, c00, c01, &temp_c, &press_pa);
            log_data(temp_c, press_pa);
        } else {
            fprintf(stderr, "Warning: measurement read failed\n");
        }
        sleep(SAMPLE_PERIOD);
    }

    printf("\nShutting down...\n");
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

