#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define MLX90819_ADDR  0x60
#define MEASUREMENT_REG 0x0A
#define PRESS_MSB_REG   0xAA
#define PRESS_LSB_REG   0xAB
#define PRESS_SCALE     0.1f
#define SAMPLE_PERIOD_S 1

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_byte(int fd, uint8_t reg)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_byte(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_pressure(int fd, float *pressure_out)
{
    uint8_t msb = 0, lsb = 0;

    if (i2c_write_byte(fd, MEASUREMENT_REG) < 0)
        return -1;

    /* Small delay to let the sensor complete the measurement */
    usleep(10000);

    if (i2c_read_byte(fd, PRESS_MSB_REG, &msb) < 0)
        return -1;
    if (i2c_read_byte(fd, PRESS_LSB_REG, &lsb) < 0)
        return -1;

    uint16_t raw = ((uint16_t)msb << 8) | lsb;
    *pressure_out = (float)raw * PRESS_SCALE;
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, MLX90819_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                MLX90819_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    printf("MLX90819 pressure sensor on %s (addr 0x%02X). Press Ctrl+C to exit.\n",
           I2C_BUS, MLX90819_ADDR);

    while (g_running) {
        float pressure;
        if (read_pressure(fd, &pressure) == 0) {
            time_t now = time(NULL);
            struct tm tm_info;
            char ts[32];
            if (localtime_r(&now, &tm_info) != NULL) {
                strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);
                printf("%s Pressure: %.2f kPa\n", ts, pressure);
            } else {
                printf("Pressure: %.2f kPa\n", pressure);
            }
        } else {
            fprintf(stderr, "Failed to read pressure from sensor.\n");
        }
        sleep(SAMPLE_PERIOD_S);
    }

    printf("\nExiting cleanly.\n");
    close(fd);
    return EXIT_SUCCESS;
}

