/*
 * SDP800-500Pa differential pressure sensor reader for Raspberry Pi 3 B+
 * Uses Linux i2c-dev (no wiringPi).
 *
 * Wiring:
 *   SDP800 SDA  -> GPIO 2 (pin 3)
 *   SDP800 SCL  -> GPIO 3 (pin 5)
 *   SDP800 VDD  -> 3.3 V
 *   SDP800 GND  -> GND
 *   SDP800 SDA/SDC -> I2C bus 1 (SDA=GPIO2, SCL=GPIO3)
 *   SDP800 ADDR -> GND (I2C address 0x25)
 *
 * Build: gcc -O2 -Wall -o sdp800_log sdp800_log.c
 */

#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SDP800_ADDR    0x25
#define LOG_FILE       "pressure_log.txt"
#define SAMPLE_PERIOD  1          /* seconds */
#define MEAS_DELAY_MS  45         /* SDP800 needs >= 45 ms after 0x362F */
#define READ_LEN       9          /* 3 words × (2 data + 1 CRC) */

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* CRC-8 as used by Sensirion: poly 0x31, init 0xFF, no final XOR */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

static int i2c_write_cmd(int fd, uint16_t cmd)
{
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "i2c write(0x%04X) failed: %s\n", cmd, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "i2c read failed: %s (got %zd of %zu)\n",
                strerror(errno), n, len);
        return -1;
    }
    return 0;
}

static int read_sdp800(int fd, float *pressure, float *temperature)
{
    uint8_t data[READ_LEN];

    if (i2c_write_cmd(fd, 0x362F) < 0)
        return -1;

    usleep(MEAS_DELAY_MS * 1000);

    if (i2c_read_bytes(fd, data, READ_LEN) < 0)
        return -1;

    /* Validate CRC for each 2-byte word */
    for (int i = 0; i < 3; i++) {
        if (crc8(&data[i * 3], 2) != data[i * 3 + 2]) {
            fprintf(stderr, "CRC mismatch on word %d\n", i);
            return -1;
        }
    }

    int16_t raw_p = (int16_t)((data[0] << 8) | data[1]);
    int16_t raw_t = (int16_t)((data[3] << 8) | data[4]);

    *pressure    = (float)raw_p / 60.0f;   /* Pa */
    *temperature = (float)raw_t / 200.0f;  /* °C */

    return 0;
}

static void log_data(float pressure, float temperature)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
        fprintf(fp, "%s,%.2f,%.2f\n", ts, pressure, temperature);
    } else {
        fprintf(fp, "timestamp_error,%.2f,%.2f\n", pressure, temperature);
    }

    if (fclose(fp) != 0)
        fprintf(stderr, "Warning: fclose(%s) failed: %s\n",
                LOG_FILE, strerror(errno));
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, SDP800_ADDR) < 0) {
        fprintf(stderr, "ioctl I2C_SLAVE 0x%02X failed: %s\n",
                SDP800_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    printf("SDP800 HVAC monitor started. Logging to %s every %d s.\n",
           LOG_FILE, SAMPLE_PERIOD);
    printf("Press Ctrl+C to stop.\n");

    while (g_running) {
        float pressure, temperature;

        if (read_sdp800(fd, &pressure, &temperature) == 0) {
            log_data(pressure, temperature);
            printf("Pressure: %.2f Pa, Temperature: %.2f C\n",
                   pressure, temperature);
        } else {
            fprintf(stderr, "Sensor read failed; will retry next cycle.\n");
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_PERIOD * 10 && g_running; i++)
            usleep(100 * 1000);
    }

    printf("\nShutting down cleanly.\n");
    close(fd);
    return EXIT_SUCCESS;
}

