#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SDP800_ADDR 0x25
#define LOG_FILE "airflow_log.csv"
#define MEASUREMENT_DELAY_US 10000  /* 10 ms (datasheet: min 8 ms) */
#define SAMPLE_INTERVAL_US 1000000 /* 1 second */

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static int log_fd = -1;

/* CRC-8 Sensirion: polynomial 0x31, initial value 0xFF */
static uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int open_log_file(void) {
    int fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (fd < 0) {
        perror("open log file");
        return -1;
    }
    if (fseek(fd, 0, SEEK_END) != 0) {
        perror("fseek");
        close(fd);
        return -1;
    }
    long sz = ftell(fd);
    if (sz < 0) {
        perror("ftell");
        close(fd);
        return -1;
    }
    if (sz == 0) {
        if (ftruncate(fd, 0) != 0) {
            perror("ftruncate");
            close(fd);
            return -1;
        }
        if (ftruncate(fd, 1) != 0) {
            perror("ftruncate header");
            close(fd);
            return -1;
        }
    }
    return fd;
}

static int log_data(float pressure) {
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        perror("time");
        return -1;
    }
    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        perror("localtime_r");
        return -1;
    }
    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }
    if (dprintf(log_fd, "%s,%.2f\n", ts, pressure) < 0) {
        perror("dprintf");
        return -1;
    }
    if (fflush(log_fd) != 0) {
        perror("fflush");
        return -1;
    }
    return 0;
}

static int read_sdp800(float *pressure) {
    uint8_t cmd[2] = {0x36, 0x2F};
    uint8_t buf[3];

    if (i2cWriteDevice(i2c_handle, (char *)cmd, 2) != 2) {
        fprintf(stderr, "i2cWriteDevice failed\n");
        return -1;
    }

    gpioDelay(MEASUREMENT_DELAY_US);

    if (i2cReadDevice(i2c_handle, (char *)buf, 3) != 3) {
        fprintf(stderr, "i2cReadDevice failed\n");
        return -1;
    }

    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "CRC mismatch: calc=0x%02X recv=0x%02X\n",
                crc8(buf, 2), buf[2]);
        return -1;
    }

    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *pressure = (float)raw / 60.0f;
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction SIGINT");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction SIGTERM");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SDP800_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_fd = open_log_file();
    if (log_fd < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("SDP800 logging started. Press Ctrl+C to stop.\n");

    while (running) {
        float pressure;
        if (read_sdp800(&pressure) == 0) {
            if (log_data(pressure) != 0) {
                fprintf(stderr, "Logging failed\n");
            }
        } else {
            fprintf(stderr, "Sensor read failed\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    if (log_fd >= 0) {
        close(log_fd);
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return 0;
}

