        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SDP800_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_fd = open_log_file();
    if (log_fd < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("SDP800 logging started. Press Ctrl+C to stop.\n");

    while (running) {
        float pressure;
        if (read_sdp800(&pressure) == 0) {
            if (log_data(pressure) != 0) {
                fprintf(stderr, "Logging failed\n");
            }
        } else {
            fprintf(stderr, "Sensor read failed\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    if (log_fd >= 0) {
        close(log_fd);
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return 0;
}

