#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define MLX90821_ADDR  0x40
#define PRESSURE_REG   0x00
#define PRESSURE_SCALE 0.01f
#define SAFE_MIN_KPA   200.0f
#define SAFE_MAX_KPA   250.0f
#define LOG_FILE       "pressure_log.csv"
#define SAMPLE_US      1000000  /* 1 second */

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int init_i2c(void)
{
    int handle = i2cOpen(I2C_BUS, MLX90821_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (bus=%d, addr=0x%02X): %d\n",
                I2C_BUS, MLX90821_ADDR, handle);
        return -1;
    }
    return handle;
}

static int read_pressure_raw(int handle, uint16_t *raw_out)
{
    char buf[2];
    int  n = i2cReadI2CBlockData(handle, PRESSURE_REG, buf, 2);
    if (n != 2) {
        fprintf(stderr, "Error: i2cReadI2CBlockData returned %d (expected 2)\n", n);
        return -1;
    }
    *raw_out = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

static float convert_to_kpa(uint16_t raw)
{
    return (float)raw * PRESSURE_SCALE;
}

static void log_pressure(float pressure_kpa)
{
    time_t now = time(NULL);
    struct tm tm_utc;
    char ts[32];

    if (gmtime_r(&now, &tm_utc) == NULL) {
        fprintf(stderr, "Error: gmtime_r failed\n");
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc);

    if (g_log_file == NULL) {
        g_log_file = fopen(LOG_FILE, "a");
        if (g_log_file == NULL) {
            fprintf(stderr, "Error: cannot open %s for append\n", LOG_FILE);
            return;
        }
        /* Write header only if file is empty */
        fseek(g_log_file, 0, SEEK_END);
        if (ftell(g_log_file) == 0) {
            fprintf(g_log_file, "timestamp,pressure_kPa\n");
            fflush(g_log_file);
        }
    }

    fprintf(g_log_file, "%s,%.2f\n", ts, pressure_kpa);
    fflush(g_log_file);
}

static void check_tire_pressure(float pressure_kpa)
{
    if (pressure_kpa < SAFE_MIN_KPA || pressure_kpa > SAFE_MAX_KPA) {
        fprintf(stderr, "WARNING: tire pressure %.2f kPa out of safe range [%.0f-%.0f] kPa\n",
                pressure_kpa, SAFE_MIN_KPA, SAFE_MAX_KPA);
    }
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = init_i2c();
    if (g_i2c_handle < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (g_running) {
        uint16_t raw;
        if (read_pressure_raw(g_i2c_handle, &raw) != 0) {
            fprintf(stderr, "Warning: I2C read failed, re-opening bus...\n");
            i2cClose(g_i2c_handle);
            g_i2c_handle = -1;
            gpioDelay(100000); /* 100 ms backoff */
            g_i2c_handle = init_i2c();
            if (g_i2c_handle < 0) {
                fprintf(stderr, "Fatal: I2C re-init failed, exiting\n");
                break;
            }
            continue;
        }

        float pressure_kpa = convert_to_kpa(raw);
        log_pressure(pressure_kpa);
        check_tire_pressure(pressure_kpa);

        gpioDelay(SAMPLE_US);
    }

    /* Clean shutdown */
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

