#include <errno.h>
#include <pigpio.h>

#define HIH6130_ADDR 0x27
#define I2C_BUS 1
#define LOG_FILE "environmental_data.log"
#define LOG_SIZE_LIMIT 1048576
#define SAMPLE_INTERVAL_SEC 5
#define MEASUREMENT_DELAY_US 40000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

static int read_hih6130(int handle, float *temperature, float *humidity) {
    unsigned char cmd = 0x00;
    unsigned char buf[4];
    int rc;

    rc = i2cWriteDevice(handle, (char *)&cmd, 1);
    if (rc < 0) {
        fprintf(stderr, "Error writing measurement command: %s\n", pigpio_error(rc));
        return -1;
    }

    gpioDelay(MEASUREMENT_DELAY_US);

    rc = i2cReadDevice(handle, (char *)buf, 4);
    if (rc < 0) {
        fprintf(stderr, "Error reading sensor data: %s\n", pigpio_error(rc));
        return -1;
    }
    if (rc != 4) {
        fprintf(stderr, "Short read: got %d bytes, expected 4\n", rc);
        return -1;
    }

    unsigned int status = (buf[0] & 0x80) ? 0xFF : 0x00;
    if (status != 0x00) {
        fprintf(stderr, "Sensor status error: 0x%02X\n", status);
        return -1;
    }

    unsigned int raw_temperature = ((unsigned int)buf[0] << 8) | buf[1];
    unsigned int raw_humidity = ((unsigned int)buf[2] << 8) | buf[3];

    *temperature = ((float)raw_temperature / 16383.0f) * 165.0f - 40.0f;
    *humidity = ((float)raw_humidity / 16383.0f) * 100.0f;

    return 0;
}

static void log_data(FILE *fp, float temperature, float humidity) {
    time_t t = time(NULL);
    struct tm tm;
    char timestamp[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm);

    fprintf(fp, "%s, Temperature: %.2f C, Humidity: %.2f %%\n",
            timestamp, temperature, humidity);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, HIH6130_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at 0x%02X: %s\n",
                HIH6130_ADDR, pigpio_error(i2c_handle));
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    long file_size = 0;
    fseek(log_file, 0, SEEK_END);
    if (file_size < 0) {
        fprintf(stderr, "Error seeking to end of log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    while (running) {
        float temperature, humidity;

        if (read_hih6130(i2c_handle, &temperature, &humidity) == 0) {
            log_data(log_file, temperature, humidity);
            file_size = ftell(log_file);
            if (file_size < 0) {
                fprintf(stderr, "Error seeking in log file: %s\n", strerror(errno));
            } else if (file_size > LOG_SIZE_LIMIT) {
                fprintf(stderr, "Log file exceeds %d bytes. Truncating.\n",
                        LOG_SIZE_LIMIT);
                fseek(log_file, 0, SEEK_END);
                if (ftell(log_file) > 0) {
                    truncate(log_file, 0);
                }
            }
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }

        if (running) {
            sleep(SAMPLE_INTERVAL_SEC);
        }
    }

    fprintf(stderr, "\nShutting down cleanly.\n");
    cleanup();
    return 0;
}

