#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <stdint.h>

#define GPIO_PIN 4
#define TICK_US 3
#define SYNC_TICKS 56
#define NIBBLE_MIN_TICKS 12
#define NIBBLE_MAX_TICKS 271
#define MAX_PULSE_TICKS 1000
#define LOG_FILE "pressure_log.txt"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_pressure(float *pressure) {
    uint32_t start_tick, end_tick, pulse_ticks;
    int nibble_ticks[5];
    int nibble_idx = 0;
    int nibble_val;
    uint32_t sum_nibbles;
    uint32_t raw_pressure;
    int timeout;

    /* --- Synchronization pulse --- */
    timeout = 0;
    while (gpioRead(GPIO_PIN) == 0) {
        gpioDelay(TICK_US);
        timeout++;
        if (timeout > MAX_PULSE_TICKS) {
            fprintf(stderr, "Error: Timeout waiting for sync pulse start.\n");
            return -1;
        }
    }
    start_tick = gpioTick();

    timeout = 0;
    while (gpioRead(GPIO_PIN) == 1) {
        gpioDelay(TICK_US);
        timeout++;
        if (timeout > MAX_PULSE_TICKS) {
            fprintf(stderr, "Error: Timeout waiting for sync pulse end.\n");
            return -1;
        }
    }
    end_tick = gpioTick();
    pulse_ticks = end_tick - start_tick;

    if (pulse_ticks < SYNC_TICKS * 0.8 || pulse_ticks > SYNC_TICKS * 1.2) {
        fprintf(stderr, "Error: Invalid sync pulse width: %u ticks\n", pulse_ticks);
        return -1;
    }

    /* --- Read 5 nibbles --- */
    for (nibble_idx = 0; nibble_idx < 5; nibble_idx++) {
        timeout = 0;
