#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define TMP117_ADDR 0x48
#define TEMP_REG 0x00
#define DEVICE_ID_REG 0x01
#define DEVICE_ID 0x0117
#define FILENAME "greenhouse_temps.dat"
#define SLEEP_SECONDS 60

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_device_id(int handle, uint16_t *id) {
    int rc = i2cReadWordData(handle, DEVICE_ID_REG);
    if (rc < 0) {
        fprintf(stderr, "Error reading device ID register: %d\n", rc);
        return -1;
    }
    *id = (uint16_t)rc;
    return 0;
}

static int read_temperature(int handle, float *temp) {
    int rc = i2cReadWordData(handle, TEMP_REG);
    if (rc < 0) {
        fprintf(stderr, "Error reading temperature register: %d\n", rc);
        return -1;
    }
    int16_t raw = (int16_t)rc;
    *temp = (float)raw * 0.0078125f;
    return 0;
}

static int log_temperature(float temp) {
    if (fwrite(&temp, sizeof(float), 1, fp) != 1) {
        fprintf(stderr, "Error writing temperature to file\n");
        return -1;
    }
    fflush(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %d\n", I2C_BUS, TMP117_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    uint16_t device_id = 0;
    if (read_device_id(i2c_handle, &device_id) != 0) {
        fprintf(stderr, "Failed to verify TMP117 device ID\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (device_id != DEVICE_ID) {
        fprintf(stderr, "Unexpected device ID: 0x%04X (expected 0x%04X)\n", device_id, DEVICE_ID);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fp = fopen(FILENAME, "ab");
    if (fp == NULL) {
        perror("Error opening file");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Greenhouse monitoring started. Logging to %s every %d seconds.\n", FILENAME, SLEEP_SECONDS);

    while (running) {
        float temperature;
        if (read_temperature(i2c_handle, &temperature) == 0) {
            if (log_temperature(temperature) != 0) {
                fprintf(stderr, "Failed to log temperature\n");
            } else {
                printf("Temperature: %.2f °C\n", temperature);
            }
        } else {
            fprintf(stderr, "Failed to read temperature\n");
        }
        sleep(SLEEP_SECONDS);
    }

    printf("\nShutting down...\n");
    if (fp != NULL) {
        fclose(fp);
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

