#define TMP117_ADDR    0x48
#define TEMP_REG       0x00
#define LOG_FILE       "temperature_log.dat"
#define SAMPLE_PERIOD  5
#define BUFFER_SIZE    10

typedef struct {
    time_t timestamp;
    float  temperature;
} TemperatureReading;

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int read_temperature(float *temperature) {
    int raw = i2cReadWordData(g_i2c_handle, TEMP_REG);
    if (raw < 0) {
        fprintf(stderr, "Error reading temperature register: %d\n", raw);
        return -1;
    }
    int16_t raw16 = (int16_t)raw;
    *temperature = (float)raw16 * 0.0078125f;
    return 0;
}

static void log_temperature(const TemperatureReading *reading) {
    FILE *fp = fopen(LOG_FILE, "ab");
    if (!fp) {
        perror("Error opening log file");
        return;
    }
    fwrite(reading, sizeof(TemperatureReading), 1, fp);
    fclose(fp);
}

static void add_to_buffer(TemperatureReading *buffer, int *index, int size,
                           const TemperatureReading *reading) {
    buffer[*index] = *reading;
    *index = (*index + 1) % size;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at bus %d addr 0x%02X: %d\n",
                I2C_BUS, TMP117_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    TemperatureReading buffer[BUFFER_SIZE];
    int buffer_index = 0;

    while (g_running) {
        float temperature;
        if (read_temperature(&temperature) == 0) {
            TemperatureReading reading;
            reading.timestamp  = time(NULL);
            reading.temperature = temperature;
            add_to_buffer(buffer, &buffer_index, BUFFER_SIZE, &reading);
            log_temperature(&reading);
            printf("Temperature: %.2f °C\n", reading.temperature);
        } else {
            fprintf(stderr, "Skipping sample due to read error\n");
        }
        sleep(SAMPLE_PERIOD);
    }

    /* Graceful shutdown: flush buffer to file and release resources */
    log_temperature(&buffer[buffer_index]);
    for (int i = 0; i < BUFFER_SIZE; i++) {
        log_temperature(&buffer[i]);
    }
    i2cClose(g_i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

