#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define I2C_BUS 1
#define I2C_ADDR 0x49
#define LOG_FILE "flow_log.txt"
#define SAMPLE_INTERVAL_US 1000000
#define FLOW_REG 0x00
#define TEMP_REG 0x02

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    float flow_rate;
    float temperature;
} sensor_data_t;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_sensor_data(int handle, sensor_data_t *data) {
    char buf[4];
    int bytes_read = i2cReadDevice(handle, buf, 4);
    if (bytes_read != 4) {
        fprintf(stderr, "Error: I2C read failed (got %d bytes, expected 4)\n", bytes_read);
        return -1;
    }

    uint16_t raw_flow = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    uint16_t raw_temp = ((uint16_t)(uint8_t)buf[2] << 8) | (uint8_t)buf[3];

    if (raw_flow == 0xFFFF || raw_temp == 0xFFF) {
        fprintf(stderr, "Warning: Sensor returned invalid data (flow=0xFFFF, temp=0xFFF)\n");
        return -1;
    }

    data->flow_rate = ((float)raw_flow / 16384.0f - 0.1f) / 0.8f * 25.0f;
    data->temperature = ((float)raw_temp / 4096.0f - 0.1f) / 0.8f * 80.0f - 40.0f;
    return 0;
}

static int log_data(FILE *fp, float flow_rate, float temperature) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s, Flow: %.2f SLPM, Temp: %.2f C\n", timestamp, flow_rate, temperature) < 0) {
        fprintf(stderr, "Error: Failed to write to log file\n");
        return -1;
    }
    fflush(fp);
    return 0;
}

static int init_i2c(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at 0x%02X on bus %d\n", I2C_ADDR, I2C_BUS);
        return -1;
    }
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error: Failed to open log file %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    if (init_i2c() != 0) {
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Flow sensor monitoring started. Press Ctrl+C to exit.\n");

    int consecutive_errors = 0;

    while (!terminate) {
        sensor_data_t data;
        if (read_sensor_data(i2c_handle, &data) == 0) {
            if (log_data(log_file, data.flow_rate, data.temperature) != 0) {
                fprintf(stderr, "Error: Logging failed\n");
            }
            consecutive_errors = 0;
        } else {
            consecutive_errors++;
            fprintf(stderr, "Error: Sensor read failed (consecutive: %d)\n", consecutive_errors);

            if (consecutive_errors >= 2) {
                fprintf(stderr, "Fatal: Re-initializing I2C after 2 consecutive failures\n");
                if (init_i2c() != 0) {
                    fprintf(stderr, "Fatal: I2C re-initialization failed, exiting\n");
                    break;
                }
                consecutive_errors = 0;
            }
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file) {
        fclose(log_file);
    }
    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return 0;
}

