#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define DHT11_GPIO 4
#define DHT11_TIMEOUT_US 200
#define DHT11_START_LOW_US 18000
#define DHT11_BIT_LOW_US 50
#define DHT11_BIT_HIGH_THRESHOLD_US 60
#define DHT11_MAX_PULSE_US 100
#define DHT11_READ_INTERVAL_S 2
#define DHT11_LOG_FILE "dht11_readings.txt"

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void log_error(int status, const char *msg) {
    if (!g_log_fp) return;
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(g_log_fp, "%s - ERROR: %s (status: %d)\n", ts, msg, status);
    fflush(g_log_fp);
}

static int wait_level(int gpio, int level, uint32_t timeout_us) {
    uint32_t start = gpioTick();
    while (gpioRead(gpio) != level) {
        if ((gpioTick() - start) > timeout_us) return -1;
    }
    return 0;
}

static int read_dht11(float *temperature, float *humidity) {
    uint8_t data[5] = {0};
    int bit_idx = 0;
    int status = 0;

    /* --- Start signal: pull low for >= 18 ms, then release --- */
    if (gpioSetMode(DHT11_GPIO, PI_OUTPUT) < 0) return -2;
    if (gpioWrite(DHT11_GPIO, 0) < 0) return -2;
    gpioDelay(DHT11_START_LOW_US);
    if (gpioWrite(DHT11_GPIO, 1) < 0) return -2;
    gpioDelay(30); /* release line, wait for sensor to pull low */

    /* --- Sensor response: ~80 us low, ~80 us high --- */
    if (wait_level(DHT11_GPIO, 0, DHT11_TIMEOUT_US) < 0) return -3;
    if (wait_level(DHT11_GPIO, 1, DHT11_TIMEOUT_US) < 0) return -3;
    if (wait_level(DHT11_GPIO, 0, DHT11_TIMEOUT_US) < 0) return -3;

    /* --- Read 40 data bits --- */
    for (bit_idx = 0; bit_idx < 40; bit_idx++) {
        /* Each bit starts with a 50 us low pulse */
        if (wait_level(DHT11_GPIO, 0, DHT11_TIMEOUT_US) < 0) return -4;
        if (wait_level(DHT11_GPIO, 1, DHT11_TIMEOUT_US) < 0) return -4;

        uint32_t high_start = gpioTick();
        if (wait_level(DHT11_GPIO, 0, DHT11_TIMEOUT_US) < 0) return -5;

        uint32_t high_duration = gpioTick() - high_start;
        if (high_duration > DHT11_MAX_PULSE_US) return -6;

        data[bit_idx / 8] <<= 1;
        if (high_duration > DHT11_BIT_HIGH_THRESHOLD_US) {
            data[bit_idx / 8] |= 1;
        }
    }

    /* --- Checksum --- */
    uint8_t checksum = (uint8_t)(data[0] + data[1] + data[2] + data[3]);
    if (checksum != data[4]) {
        return -7;
    }

    /* --- DHT11: integer values only --- */
    *humidity = (float)data[0];
    *temperature = (float)data[2];
    return 0;
}

static void log_reading(float temperature, float humidity, int status) {
    if (!g_log_fp) return;
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(g_log_fp, "%s - Temperature: %.1f C, Humidity: %.1f %%RH, Status: %d\n",
            ts, temperature, humidity, status);
    fflush(g_log_fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    g_log_fp = fopen(DHT11_LOG_FILE, "a");
    if (!g_log_fp) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    float temperature, humidity;
    int status;

    while (g_running) {
        status = read_dht11(&temperature, &humidity);
        if (status == 0) {
            log_reading(temperature, humidity, status);
        } else {
            log_error(status, "DHT11 read failed");
        }
        sleep(DHT11_READ_INTERVAL_S);
    }

    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    gpioTerminate();
    return 0;
}

