static int read_register(int handle, uint8_t reg, uint8_t *value) {
    int rc = i2cWriteByte(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error writing register address 0x%02X: %d\n", reg, rc);
        return -1;
    }
    int b = i2cReadByte(handle);
    if (b < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, b);
        return -1;
    }
    *value = (uint8_t)b;
    return 0;
}

static int read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len) {
    int rc = i2cWriteI2CBlockData(handle, reg, NULL, 0);
    if (rc < 0) {
        fprintf(stderr, "Error setting register 0x%02X: %d\n", reg, rc);
        return -1;
    }
    rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc < 0) {
        fprintf(stderr, "Error reading block from 0x%02X: %d\n", reg, rc);
        return -1;
    }
    return 0;
}

static int read_sensor_data(int handle, uint16_t *red, uint16_t *green, uint16_t *blue) {
    uint8_t buf[6];
    if (read_block(handle, REG_RED_DATA, buf, 6) < 0) return -1;
    *red = (uint16_t)(buf[0] | (buf[1] << 8));
    *green = (uint16_t)(buf[2] | (buf[3] << 8));
    *blue = (uint16_t)(buf[4] | (buf[5] << 8));
    return 0;
}

static float calculate_cct(uint16_t r, uint16_t g, uint16_t b) {
    float rf = (float)r / 1000.0f;
    float gf = (float)g / 1000.0f;
    float bf = (float)b / 1000.0f;
    float sum = rf + gf + bf;
    if (sum <= 0.0f) return 0.0f;
    float cct = 449.0f * (1.0f - gf) - 548.0f * (1.0f - rf) - 354.2f * (1.0f - bf);
    cct = cct / (cct + 100.0f);
    if (cct < 0.0f) cct = 0.0f;
    if (cct > 1.0f) cct = 1.0f;
    return cct * 1000.0f;
}

static void log_cct(float cct) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s,%.2f\n", ts, cct);
    fflush(log_file);
}

static void cleanup(void) {
    if (i2c_handle1 >= 0) i2cClose(i2c_handle1);
    if (i2c_handle2 >= 0) i2cClose(i2c_handle2);
    if (log_file) fclose(log_file);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle1 = i2cOpen(I2C_BUS, SENSOR1_ADDR, 0);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Error opening I2C for sensor 1 (0x%02X): %d\n", SENSOR1_ADDR, i2c_handle1);
        gpioTerminate();
        return 1;
    }

    i2c_handle2 = i2cOpen(I2C_BUS, SENSOR2_ADDR, 0);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Error opening I2C for sensor 2 (0x%02X): %d\n", SENSOR2_ADDR, i2c_handle2);
        i2cClose(i2c_handle1);
        gpioTerminate();
        return 1;
    }

    uint8_t dev_id1 = 0, dev_id2 = 0;
    if (read_register(i2c_handle1, REG_DEVICE_ID, &dev_id1) < 0 || dev_id1 != EXPECTED_DEVICE_ID) {
        fprintf(stderr, "Sensor 1 (0x%02X) not detected or wrong device ID: 0x%02X\n", SENSOR1_ADDR, dev_id1);
        cleanup();
        return 1;
    }
    if (read_register(i2c_handle2, REG_DEVICE_ID, &dev_id2) < 0 || dev_id2 != EXPECTED_DEVICE_ID) {
        fprintf(stderr, "Sensor 2 (0x%02X) not detected or wrong device ID: 0x%02X\n", SENSOR2_ADDR, dev_id2);
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,Average_CCT\n");
        fflush(log_file);
    }

    uint16_t r1, g1, b1, r2, g2, b2;
    while (running) {
        if (read_sensor_data(i2c_handle1, &r1, &g1, &b1) == 0 &&
            read_sensor_data(i2c_handle2, &r2, &g2, &b2) == 0) {
            float cct1 = calculate_cct(r1, g1, b1);
            float cct2 = calculate_cct(r2, g2, b2);
            float avg = (cct1 + cct2) / 2.0f;
            log_cct(avg);
        } else {
            fprintf(stderr, "Error reading sensor data, skipping log entry\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return 0;
}

