static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static uint8_t sensirion_crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %s\n",
                I2C_BUS, SDP810_ADDR, pigpio_error(i2c_handle));
        return -1;
    }
    return 0;
}

static int read_sdp810(float *pressure, float *temperature) {
    uint8_t cmd[2] = {0x36, 0x2F};
    uint8_t buf[9];
    int16_t raw_pressure, raw_temperature;
    int ret;

    ret = i2cWriteDevice(i2c_handle, (char *)cmd, 2);
    if (ret != 0) {
        fprintf(stderr, "I2C write failed: %s\n", pigpio_error(ret));
        return -1;
    }

    gpioDelay(MEASUREMENT_DELAY_MS * 1000);

    ret = i2cReadDevice(i2c_handle, (char *)buf, 9);
    if (ret != 9) {
        fprintf(stderr, "I2C read failed: expected 9 bytes, got %d\n", ret);
        return -1;
    }

    if (sensirion_crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "Pressure CRC mismatch\n");
        return -1;
    }
    if (sensirion_crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "Temperature CRC mismatch\n");
        return -1;
    }
    if (sensirion_crc8(&buf[6], 2) != buf[8]) {
        fprintf(stderr, "Status CRC mismatch\n");
        return -1;
    }

    raw_pressure = (int16_t)((buf[0] << 8) | buf[1]);
    raw_temperature = (int16_t)((buf[3] << 8) | buf[4]);

    *pressure = (float)raw_pressure / 60.0f;
    *temperature = (float)raw_temperature / 200.0f;

    return 0;
}

