#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define STTS2004_ADDR  0x4A
#define TEMP_REG       0x00
#define LED_PIN        17
#define TEMP_THRESHOLD_HIGH 28.0f
#define TEMP_THRESHOLD_LOW   27.0f
#define POLL_INTERVAL_SEC  1

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, int16_t *out)
{
    uint8_t buf[2];
    struct i2c_msg msgs[2];
    struct i2c_rdwr_ioctl_data data;

    msgs[0].addr  = STTS2004_ADDR;
    msgs[0].flags = 0;
    msgs[0].len   = 1;
    msgs[0].buf   = &reg;

    msgs[1].addr  = STTS2004_ADDR;
    msgs[1].flags = I2C_M_RD;
    msgs[1].len   = 2;
    msgs[1].buf   = buf;

    data.msgs = msgs;
    data.nmsgs = 2;

    if (ioctl(fd, I2C_RDWR, &data) < 0) {
        fprintf(stderr, "I2C_RDWR failed for reg 0x%02X: %s\n",
                reg, strerror(errno));
        return -1;
    }

    *out = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

int main(void)
{
    int i2c_fd = -1;
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *led_line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "open(%s): %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, STTS2004_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n",
                STTS2004_ADDR, strerror(errno));
        goto cleanup;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "gpiod_chip_open_by_name: %s\n", strerror(errno));
        goto cleanup;
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        fprintf(stderr, "gpiod_chip_get_line(%d): %s\n",
                LED_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(led_line, "stts2004-led", 0) < 0) {
        fprintf(stderr, "gpiod_line_request_output: %s\n", strerror(errno));
        goto cleanup;
    }

    int consecutive_errors = 0;

    while (g_running) {
        int16_t raw;
        if (i2c_read_reg16(i2c_fd, TEMP_REG, &raw) < 0) {
            consecutive_errors++;
            if (consecutive_errors >= 5) {
                fprintf(stderr, "Too many I2C errors; aborting.\n");
                goto cleanup;
            }
            sleep(POLL_INTERVAL_SEC);
            continue;
        }

        consecutive_errors = 0;

        float temperature = (float)raw / 16.0f;

        if (temperature > TEMP_THRESHOLD_HIGH) {
            if (gpiod_line_set_value(led_line, 1) < 0) {
                fprintf(stderr, "gpiod_line_set_value(1): %s\n",
                        strerror(errno));
            }
        } else if (temperature < TEMP_THRESHOLD_LOW) {
            if (gpiod_line_set_value(led_line, 0) < 0) {
                fprintf(stderr, "gpiod_line_set_value(0): %s\n",
                        strerror(errno));
            }
        } else {
            if (gpiod_line_set_value(led_line, 0) < 0) {
                fprintf(stderr, "gpiod_line_set_value(0): %s\n",
                        strerror(errno));
            }
        }

        printf("Temperature: %.2f C\n", temperature);
        fflush(stdout);

        sleep(POLL_INTERVAL_SEC);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    return ret;
}

