#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define I2C_BUS 1
#define SDP800_ADDR 0x25
#define MEASUREMENT_COMMAND 0x362F
#define MEASUREMENT_DELAY_US 45000
#define LOG_FILE "flow_data.txt"
#define MAX_RETRIES 3

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    float differential_pressure;
    float temperature;
} sensor_data_t;

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int bit = 0; bit < 8; bit++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

static void signal_handler(int signal) {
    (void)signal;
    terminate = 1;
}

static int initialize_i2c(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SDP800_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at address 0x%02X: %d\n", SDP800_ADDR, i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static int read_sensor_data(uint8_t *data) {
    int result = i2cWriteByteData(i2c_handle, (MEASUREMENT_COMMAND >> 8) & 0xFF, MEASUREMENT_COMMAND & 0xFF);
    if (result != 0) {
        fprintf(stderr, "Failed to send measurement command: %d\n", result);
        return -1;
    }

    gpioDelay(MEASUREMENT_DELAY_US);

    result = i2cReadDevice(i2c_handle, (char *)data, 9);
    if (result != 9) {
        fprintf(stderr, "Failed to read 9 bytes from sensor: %d\n", result);
        return -1;
    }

    if (crc8(&data[0], 2) != data[2]) {
        fprintf(stderr, "CRC check failed for pressure data\n");
        return -1;
    }
    if (crc8(&data[3], 2) != data[5]) {
        fprintf(stderr, "CRC check failed for temperature data\n");
        return -1;
    }

    return 0;
}

static sensor_data_t process_sensor_data(const uint8_t *data) {
    sensor_data_t result = {0.0f, 0.0f};
    int16_t scale_factor = (data[6] << 8) | data[7];
    int16_t raw_pressure = (data[0] << 8) | data[1];
    int16_t raw_temperature = (data[3] << 8) | data[4];

    result.differential_pressure = (float)raw_pressure / (float)scale_factor;
    result.temperature = (float)raw_temperature / 200.0f;

    return result;
}

static void log_data(const sensor_data_t *data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data->differential_pressure, data->temperature);
    fflush(log_file);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    uint8_t data[9];
    sensor_data_t sensor_data;
    int retries;

    signal(SIGINT, signal_handler);

    if (initialize_i2c() != 0) {
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", LOG_FILE);
        cleanup();
