#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SI7021_ADDR    0x40
#define LOG_FILE       "environment.log"
#define SAMPLE_INTERVAL 60
#define MAX_RETRIES    3

/* Si7021 single-byte commands (no register addressing) */
#define CMD_MEASURE_RH_NOHOLD   0xF5
#define CMD_READ_TEMP_FROM_RH  0xE0
#define CMD_MEASURE_TEMP_NOHOLD 0xF3

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write a single command byte to the sensor */
static int si7021_write_cmd(int handle, uint8_t cmd)
{
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (i2cWriteDevice(handle, (char *)&cmd, 1) == 0)
            return 0;
        fprintf(stderr, "[WARN] i2cWriteDevice(0x%02X) failed (attempt %d/%d)\n",
                cmd, attempt + 1, MAX_RETRIES);
        gpioDelay(10000); /* 10 ms backoff */
    }
    return -1;
}

/* Read 2 bytes (big-endian) from the sensor after a no-hold command */
static int si7021_read_raw(int handle, uint16_t *raw)
{
    char buf[2];
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (i2cReadDevice(handle, buf, 2) == 2) {
            *raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
            return 0;
        }
        fprintf(stderr, "[WARN] i2cReadDevice failed (attempt %d/%d)\n",
                attempt + 1, MAX_RETRIES);
        gpioDelay(10000);
    }
    return -1;
}

/* Read temperature from the previous RH measurement (0xE0 then read 2 bytes) */
static int si7021_read_temp_from_rh(int handle, float *temp_c)
{
    if (si7021_write_cmd(handle, CMD_READ_TEMP_FROM_RH) != 0)
        return -1;
    gpioDelay(20000); /* 20 ms conversion time */

    uint16_t raw;
    if (si7021_read_raw(handle, &raw) != 0)
        return -1;

    *temp_c = (175.72f * (float)raw) / 65536.0f - 46.85f;
    return 0;
}

/* Read relative humidity from the previous temperature measurement (0xF5) */
static int si7021_read_rh(int handle, float *rh)
{
    if (si7021_write_cmd(handle, CMD_MEASURE_RH_NOHOLD) != 0)
        return -1;
    gpioDelay(20000); /* 20 ms conversion time */

    uint16_t raw;
    if (si7021_read_raw(handle, &raw) != 0)
        return -1;

    *rh = (125.0f * (float)raw) / 65536.0f - 6.0f;
    if (*rh < 0.0f)   *rh = 0.0f;
    if (*rh > 100.0f) *rh = 100.0f;
    return 0;
}

/* Validate sensor presence by reading the electronic ID (0xFA) */
static int si7021_present(int handle)
{
    if (si7021_write_cmd(handle, 0xFA) != 0)
        return -1;
    gpioDelay(10000);
    char buf[3];
    if (i2cReadDevice(handle, buf, 3) != 3)
        return -1;
    /* ID is the 3-byte payload; presence is confirmed if we read at least 1 byte */
    return 0;
}

static void log_data(float temp_c, float rh)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "[ERROR] Cannot open %s for append\n", LOG_FILE);
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02dT%02d:%02d:%02d,%.2f,%.2f\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, temp_c, rh);
    } else {
        fprintf(fp, "UNKNOWN,%.2f,%.2f\n", temp_c, rh);
    }
    fflush(fp);
    fclose(fp);
}

static void log_error(const char *msg)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp) {
        time_t t = time(NULL);
        struct tm tm;
        if (localtime_r(&t, &tm)) {
            fprintf(fp, "%04d-%02d-%02dT%02d:%02d:%02d,ERROR,%s\n",
                    tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                    tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
        } else {
            fprintf(fp, "UNKNOWN,ERROR,%s\n", msg);
        }
        fflush(fp);
        fclose(fp);
    }
    fprintf(stderr, "[ERROR] %s\n", msg);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, SI7021_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, SI7021_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Validate sensor presence */
    if (si7021_present(g_i2c_handle) != 0) {
        fprintf(stderr, "[FATAL] Si7021 not detected at 0x%02X on bus %d\n",
                SI7021_ADDR, I2C_BUS);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Si7021 detected. Logging to %s every %d seconds. Press Ctrl+C to stop.\n",
           LOG_FILE, SAMPLE_INTERVAL);

    while (g_running) {
        float temp_c, rh;

        if (si7021_read_temp_from_rh(g_i2c_handle, &temp_c) != 0) {
            log_error("Failed to read temperature from previous RH measurement");
        } else if (si7021_read_rh(g_i2c_handle, &rh) != 0) {
            log_error("Failed to read relative humidity");
        } else {
            log_data(temp_c, rh);
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temp_c, rh);
        }

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL && g_running; i++)
            gpioDelay(1000000);
    }

    printf("\nShutting down...\n");
    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

