#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define HDC1080_ADDR 0x40
#define HDC1080_TEMP_REG 0x00
#define HDC1080_CONFIG_REG 0x02
#define CONFIG_14BIT_TEMP 0x00
#define CONFIG_14BIT_HUMID 0x00
#define CONVERSION_DELAY_US 20000
#define LOG_INTERVAL_S 5

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_hdc1080(void) {
    char config[2] = {CONFIG_14BIT_TEMP, CONFIG_14BIT_HUMID};
    if (i2cWriteDevice(i2c_handle, config, 2) != 0) {
        fprintf(stderr, "Error: Failed to write HDC1080 config register\n");
        return -1;
    }
    return 0;
}

static int read_hdc1080(float *temperature, float *humidity) {
    char reg = HDC1080_TEMP_REG;
    if (i2cWriteDevice(i2c_handle, &reg, 1) != 0) {
        fprintf(stderr, "Error: Failed to set HDC1080 pointer register\n");
        return -1;
    }
    gpioDelay(CONVERSION_DELAY_US);

    char data[4];
    if (i2cReadDevice(i2c_handle, data, 4) != 4) {
        fprintf(stderr, "Error: Failed to read HDC1080 data register\n");
        return -1;
    }

    unsigned int raw_temp = ((unsigned char)data[0] << 8) | (unsigned char)data[1];
    unsigned int raw_humidity = ((unsigned char)data[2] << 8) | (unsigned char)data[3];

    *temperature = ((float)raw_temp / 65536.0f) * 165.0f - 40.0f;
    *humidity = ((float)raw_humidity / 65536.0f) * 100.0f;
    return 0;
}

static void log_data(float temperature, float humidity) {
    FILE *fp = fopen("enviro_log.txt", "a");
    if (!fp) {
        fprintf(stderr, "Error: Failed to open enviro_log.txt for writing\n");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fclose(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, HDC1080_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus 1 at address 0x%02X\n", HDC1080_ADDR);
        gpioTerminate();
        return 1;
    }

    if (init_hdc1080() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    float temperature, humidity;

    while (!terminate) {
        if (read_hdc1080(&temperature, &humidity) == 0) {
            log_data(temperature, humidity);
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
        } else {
            fprintf(stderr, "Warning: Sensor read failed, skipping log entry\n");
        }
        sleep(LOG_INTERVAL_S);
    }

    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

