#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_ADAPTER   "/dev/i2c-1"
#define STS40_ADDR    0x44
#define LOG_FILE      "temperature_log.txt"
#define SAMPLE_PERIOD 5
#define CONV_DELAY_US 10000

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static int read_sts40(int fd, float *temp) {
    uint8_t cmd[2] = {0x2C, 0xE0};
    if (write(fd, cmd, 2) != 2) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    usleep(CONV_DELAY_US);
    uint8_t buf[3];
    ssize_t n = read(fd, buf, 3);
    if (n != 3) {
        fprintf(stderr, "I2C read failed: got %zd bytes, expected 3: %s\n", n, strerror(errno));
        return -1;
    }
    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "CRC mismatch on temperature data\n");
        return -1;
    }
    uint16_t raw = (uint16_t)((buf[0] << 8) | buf[1]);
    *temp = -45.0f + 175.0f * (float)raw / 65535.0f;
    return 0;
}

static void log_temperature(FILE *fp, float temp) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(fp, "%s, %.2f\n", ts, temp);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    int fd = open(I2C_ADAPTER, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_ADAPTER, strerror(errno));
        return 1;
    }
    if (ioctl(fd, I2C_SLAVE, STS40_ADDR) < 0) {
        fprintf(stderr, "ioctl I2C_SLAVE 0x%02X failed: %s\n", STS40_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        close(fd);
        return 1;
    }

    while (g_running) {
        float temp;
        if (read_sts40(fd, &temp) == 0) {
            log_temperature(fp, temp);
        }
        sleep(SAMPLE_PERIOD);
    }

    fclose(fp);
    close(fd);
    return 0;
}

