#define I2C_BUS 1
#define I2C_ADDR 0x25
#define LOG_FILE "hvac_pressure_log.txt"
#define SAMPLE_INTERVAL_US 1000000
#define MEASUREMENT_DELAY_US 50000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int init_i2c(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (bus=%d, addr=0x%02X): %s\n",
                I2C_BUS, I2C_ADDR, strerror(errno));
        gpioTerminate();
        return -1;
    }
    return 0;
}

static int read_sensor(float *pressure, float *temperature) {
    uint8_t cmd[2] = {0x36, 0x15};
    uint8_t buf[9];

    if (i2cWriteDevice(i2c_handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "Error: I2C write failed\n");
        return -1;
    }

    gpioDelay(MEASUREMENT_DELAY_US);

    if (i2cReadDevice(i2c_handle, (char *)buf, 9) != 9) {
        fprintf(stderr, "Error: I2C read failed\n");
        return -1;
    }

    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "Error: pressure CRC mismatch\n");
        return -1;
    }
    if (crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "Error: temperature CRC mismatch\n");
        return -1;
    }

    int16_t raw_pressure = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_temperature = (int16_t)((buf[3] << 8) | buf[4]);
    int16_t scale_factor = (int16_t)((buf[6] << 8) | buf[7]);

    if (scale_factor == 0) {
        fprintf(stderr, "Error: invalid scale factor (0)\n");
        return -1;
    }

    *pressure = (float)raw_pressure / (float)scale_factor;
    *temperature = (float)raw_temperature / 200.0f;

    return 0;
}

static void log_data(float pressure, float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", ts, pressure, temperature);
    fflush(log_file);
}

static void log_error(const char *msg) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,ERROR,%s\n", ts, msg);
    fflush(log_file);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (init_i2c() != 0) {
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: cannot open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    fprintf(log_file, "# HVAC pressure monitor started\n");
    fflush(log_file);

    while (running) {
        float pressure, temperature;

        if (read_sensor(&pressure, &temperature) == 0) {
            log_data(pressure, temperature);
        } else {
            log_error("I2C read or CRC error");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return 0;
}

