#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define SCD40_I2C_ADDR 0x62
#define I2C_BUS 1
#define BUFFER_SIZE 100
#define LOG_DIR "/var/log/scd40_data/"
#define ERROR_LOG_DIR "/var/log/scd40_error.log"
#define MEASUREMENT_INTERVAL_SEC 5
#define LOGGING_INTERVAL_SEC 60
#define START_PERIODIC_MEASUREMENT_CMD 0x21B1
#define STOP_PERIODIC_MEASUREMENT_CMD 0x3F86
#define READ_MEASUREMENT_CMD 0xE000

typedef struct {
    time_t timestamp;
    int co2;
    float temperature;
    float humidity;
} sensor_data_t;

typedef struct {
    sensor_data_t data[BUFFER_SIZE];
    int head;
    int count;
    pthread_mutex_t mutex;
} circular_buffer_t;

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static circular_buffer_t buffer;
static pthread_t logging_thread;

static void log_error(const char *message) {
    FILE *fp = fopen(ERROR_LOG_DIR, "a");
    if (!fp) {
        fprintf(stderr, "Error opening error log: %s\n", strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int send_command(uint16_t cmd) {
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (i2cWriteDevice(i2c_handle, (char *)buf, 2) != 0) {
        log_error("Failed to send command to SCD40");
        return -1;
    }
    return 0;
}

static int read_measurement(uint16_t *co2, float *temperature, float *humidity) {
    uint8_t buf[9];
    if (i2cReadDevice(i2c_handle, (char *)buf, 9) != 9) {
        log_error("Failed to read measurement from SCD40");
        return -1;
    }
    if (crc8(&buf[0], 2) != buf[2]) {
        log_error("CO2 CRC mismatch");
        return -1;
    }
    if (crc8(&buf[3], 2) != buf[5]) {
        log_error("Temperature CRC mismatch");
        return -1;
    }
    if (crc8(&buf[6], 2) != buf[8]) {
        log_error("Humidity CRC mismatch");
        return -1;
    }
    uint16_t co2_raw = (buf[0] << 8) | buf[1];
    uint16_t temp_raw = (buf[3] << 8) | buf[4];
    uint16_t hum_raw = (buf[6] << 8) | buf[7];
    *co2 = co2_raw;
    *temperature = -45.0f + 175.0f * (float)temp_raw / 65535.0f;
    *humidity = 100.0f * (float)hum_raw / 65535.0f;
