#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define I2C_BUS 1
#define ICP10110_ADDR 0x63
#define WHO_AM_I_REG 0x08
#define WHO_AM_I_VAL 0x08
#define CALIB_REG 0x05
#define MEAS_TRIG_REG 0x00
#define MEAS_DELAY_US 10000
#define SAMPLE_INTERVAL_S 5
#define LOG_FILE "environmental_data.txt"

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_calibration(uint16_t cal[4]) {
    char buf[8];
    if (i2cReadI2CBlockData(i2c_handle, CALIB_REG, buf, 8) != 8) {
        fprintf(stderr, "Error: failed to read calibration coefficients\n");
        return -1;
    }
    for (int i = 0; i < 4; i++) {
        cal[i] = ((uint16_t)(buf[2 * i]) << 8) | (uint8_t)buf[2 * i + 1];
    }
    return 0;
}

static int read_sensor_data(uint16_t *pressure, uint16_t *temperature) {
    char buf[6];
    if (i2cWriteByteData(i2c_handle, MEAS_TRIG_REG, 0x00) < 0) {
        fprintf(stderr, "Error: failed to trigger measurement\n");
        return -1;
    }
    gpioDelay(MEAS_DELAY_US);
    if (i2cReadI2CBlockData(i2c_handle, MEAS_TRIG_REG, buf, 6) != 6) {
        fprintf(stderr, "Error: failed to read sensor data\n");
        return -1;
    }
    *pressure = ((uint16_t)(buf[0]) << 8) | (uint8_t)buf[1];
    *temperature = ((uint16_t)(buf[3]) << 8) | (uint8_t)buf[4];
    return 0;
}

static float convert_pressure(uint16_t raw, uint16_t cal[4]) {
    float p = (float)raw;
    float c0 = (float)cal[0];
    float c1 = (float)cal[1];
    float c2 = (float)cal[2];
    float c3 = (float)cal[3];
    return c0 + c1 * p + c2 * p * p + c3 * p * p * p;
}

static float convert_temperature(uint16_t raw) {
    return (float)raw / 100.0f;
}

static void log_data(float pressure, float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
    fprintf(log_file, "%s,%.2f,%.2f\n", ts, pressure, temperature);
    fflush(log_file);
    printf("%s,%.2f,%.2f\n", ts, pressure, temperature);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, ICP10110_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: failed to open I2C device at 0x%02X\n", ICP10110_ADDR);
        gpioTerminate();
        return 1;
    }

    uint16_t cal[4];
    if (read_calibration(cal) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error: failed to open log file %s\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);

    while (!terminate) {
        uint16_t raw_p, raw_t;
        if (read_sensor_data(&raw_p, &raw_t) == 0) {
            float pressure = convert_pressure(raw_p, cal);
            float temperature = convert_temperature(raw_t);
            log_data(pressure, temperature);
        }
        sleep(SAMPLE_INTERVAL_S);
    }

    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

