/*
 * Raspberry Pi 4 Model B — TDK ICP-10125 barometric pressure sensor reader
 *
 * I2C bus 1, address 0x63, command 0x4011 (high-accuracy mode).
 * Reads 6 bytes: pressure(2) + CRC(2) + temperature(2) + CRC(2).
 * Calibration coefficients are read from OTP memory register 0x66.
 *
 * LED warning: GPIO 17 (BCM) — 1 Hz normal, 5 Hz when pressure < 95000 Pa.
 *
 * Build: gcc -O2 -Wall -o icp10125 icp10125.c -lgpiod
 */

#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#include <gpiod.h>

/* ---- ICP-10125 constants ---- */
#define I2C_BUS        "/dev/i2c-1"
#define I2C_ADDR       0x63
#define OTP_REG        0x66
#define CMD_HIGH_ACC  0x4011
#define MEAS_DELAY_MS  20
#define POLL_MS        1000
#define WARN_THRESHOLD 95000.0f

/* ---- GPIO (libgpiod) constants ---- */
#define GPIO_CHIP      "gpiochip4"   /* BCM GPIO bank on Pi 4 */
#define LED_LINE       17            /* BCM 17 */

/* ---- Conversion constants (ICP-10125 datasheet) ---- */
#define PRESSURE_LSB   0.0f
#define PRESSURE_LUT   0.0f
#define TEMP_LSB       0.0f
#define TEMP_LUT       0.0f

/* ---- Globals for cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static struct gpiod_line *g_led = NULL;
static struct gpiod_chip *g_chip = NULL;

/* ---- Signal handler ---- */
static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- CRC-8 (polynomial 0x31, init 0xFF) per InvenSense ICP-10125 ---- */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/* ---- I2C helpers ---- */
static int i2c_write_cmd(int fd, uint16_t cmd)
{
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write cmd 0x%04X failed: %s\n", cmd, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_n(int fd, uint8_t *buf, size_t n)
{
    ssize_t r = read(fd, buf, n);
    if (r < 0 || (size_t)r != n) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ---- Read calibration coefficients from OTP memory ---- */
static int read_calibration(int fd, float *c0, float *c1, float *c2, float *c3)
{
    uint8_t reg = OTP_REG;
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "OTP register select failed: %s\n", strerror(errno));
        return -1;
    }
    uint8_t buf[8];
    if (i2c_read_n(fd, buf, 8) != 0)
        return -1;

    /* Coefficients are 16-bit big-endian */
    *c0 = (float)((uint16_t)buf[0] | ((uint16_t)buf[1] << 8));
    *c1 = (float)((uint16_t)buf[2] | ((uint16_t)buf[3] << 8));
    *c2 = (float)((uint16_t)buf[4] | ((uint16_t)buf[5] << 8));
    *c3 = (float)((uint16_t)buf[6] | ((uint16_t)buf[7] << 8));
    return 0;
}

/* ---- Read raw 6-byte measurement and convert to physical units ---- */
static int read_measurement(int fd, float *pressure, float *temperature,
                            float c0, float c1, float c2, float c3)
{
    if (i2c_write_cmd(fd, CMD_HIGH_ACC) != 0)
        return -1;

    struct timespec ts = { .tv_sec = MEAS_DELAY_MS / 1000,
                           .tv_nsec = (MEAS_DELAY_MS % 1000) * 1000000L };
    nanosleep(&ts, NULL);

    uint8_t buf[6];
    if (i2c_read_n(fd, buf, 6) != 0)
        return -1;

    /* CRC check on pressure + temperature words */
    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "Pressure CRC mismatch\n");
        return -1;
    }
    if (crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "Temperature CRC mismatch\n");
        return -1;
    }

    int32_t raw_p = ((int32_t)buf[0] << 8) | buf[1];
    int32_t raw_t = ((int32_t)buf[3] << 8) | buf[4];

    /* InvenSense ICP-10125 conversion formulas */
    float p = (float)raw_p * PRESSURE_LSB + PRESSURE_LUT;
    float t = (float)raw_t * TEMP_LSB + TEMP_LUT;

    /* Scale factors from datasheet */
    p = c0 + c1 * p + c2 * t + c3 * p * t;
    return 0;
}

/* ---- Blink LED at given frequency for duration ---- */
static void blink_led(struct gpiod_line *line, int freq, int duration_ms)
{
    if (freq <= 0) {
        gpiod_line_set_value(line, 1);
        usleep(duration_ms * 1000);
        gpiod_line_set_value(line, 0);
        usleep(duration_ms * 1000);
        return;
    }
    int half_us = (1000000 / freq) / 2;
    for (int i = 0; i < duration_ms * 2 && g_running; i++)
        gpiod_line_set_value(line, 1);
    for (int i = 0; i < duration_ms * 2 && g_running; i++)
        gpiod_line_set_value(line, 0);
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (g_led) {
        gpiod_line_set_value(g_led, 0);
        gpiod_line_release(g_led);
        g_led = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

int main(void)
{
    /* Signal handling */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }
    if (ioctl(g_i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n", I2C_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Read calibration coefficients */
    float c0, c1, c2, c3;
    if (read_calibration(g_i2c_fd, &c0, &c1, &c2, &c3) != 0) {
        fprintf(stderr, "Failed to read calibration coefficients\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open GPIO chip and request LED line */
    g_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!g_chip) {
        fprintf(stderr, "Cannot open %s: %s\n", GPIO_CHIP, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    g_led = gpiod_chip_get_line(g_chip, LED_LINE);
    if (!g_led) {
        fprintf(stderr, "Cannot get GPIO line %d: %s\n", LED_LINE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_output(g_led, "icp10125-led", 0) < 0) {
        fprintf(stderr, "Cannot request GPIO line %d as output: %s\n",
                LED_LINE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("ICP-10125 monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float pressure, temperature;
        if (read_measurement(g_i2c_fd, &pressure, &temperature, c0, c1, c2, c3) != 0) {
            fprintf(stderr, "Measurement read failed; retrying next cycle\n");
            usleep(POLL_MS * 1000);
            continue;
        }

        printf("Pressure: %.2f Pa, Temperature: %.2f C\n", pressure, temperature);

        if (pressure < WARN_THRESHOLD) {
            printf("WARNING: High altitude (pressure %.2f Pa < %.0f Pa)\n",
                   pressure, WARN_THRESHOLD);
            blink_led(g_led, 5, POLL_MS);
        } else {
            blink_led(g_led, 1, POLL_MS);
        }
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

