#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define I2C_BUS        1
#define MLX90614_ADDR  0x5A
#define AMBIENT_TEMP_REG 0x06
#define OBJECT_TEMP_REG  0x07
#define FAN_GPIO        18
#define AMBIENT_THRESHOLD 30.0f
#define OBJECT_THRESHOLD  28.0f
#define LOG_FILE        "temperature_log.txt"
#define MAX_RETRIES     3
#define RETRY_DELAY_US  10000
#define SAMPLE_INTERVAL_S 2

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int read_temperature(int handle, uint8_t reg, float *out_temp) {
    int raw;
    int rc;

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        rc = i2cReadWordData(handle, reg);
        if (rc >= 0) {
            raw = (int16_t)rc;
            *out_temp = (float)raw * 0.02f - 273.15f;
            return 0;
        }
        if (attempt < MAX_RETRIES - 1) {
            gpioDelay(RETRY_DELAY_US);
        }
    }
    return -1;
}

static void log_temperature(float ambient, float object) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Ambient: %.2f C, Object: %.2f C\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec,
                ambient, object);
    }
    fclose(fp);
}

static void control_fan(float object_temp) {
    static int fan_on = 0;
    if (object_temp > AMBIENT_THRESHOLD && !fan_on) {
        if (gpioWrite(FAN_GPIO, 1) == 0) {
            fan_on = 1;
