#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define SHT40_ADDR 0x44
#define I2C_BUS 1
#define SERVER_PORT 8080
#define MAX_RETRIES 3
#define MEASUREMENT_DELAY_US 10000
#define HTML_BUFFER_SIZE 256

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static int server_fd = -1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int read_sht40(int handle, float *temperature, float *humidity) {
    unsigned char cmd = 0xFD;
    unsigned char data[6];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2cWriteDevice(handle, (char *)&cmd, 1) != 0) {
            fprintf(stderr, "Error: Failed to write measurement command (attempt %d)\n", retries + 1);
            retries++;
            gpioDelay(100000);
            continue;
        }

        gpioDelay(MEASUREMENT_DELAY_US);

        if (i2cReadDevice(handle, (char *)data, 6) != 6) {
            fprintf(stderr, "Error: Failed to read sensor data (attempt %d)\n", retries + 1);
            retries++;
            gpioDelay(100000);
            continue;
        }

        unsigned int raw_temperature = (data[0] << 8) | data[1];
        unsigned int raw_humidity = (data[3] << 8) | data[4];

        *temperature = -45.0f + 175.0f * (float)raw_temperature / 65535.0f;
        *humidity = -6.0f + 125.0f * (float)raw_humidity / 65535.0f;

        if (*humidity < 0.0f) *humidity = 0.0f;
        if (*humidity > 100.0f) *humidity = 100.0f;

        return 0;
    }

    fprintf(stderr, "Error: Failed to read SHT40 after %d retries\n", MAX_RETRIES);
    return -1;
}

void handle_client(int client_socket) {
    char buffer[HTML_BUFFER_SIZE];
    float temperature, humidity;

    if (read_sht40(i2c_handle, &temperature, &humidity) == 0) {
        snprintf(buffer, sizeof(buffer),
                 "<!DOCTYPE html><html><head><title>SHT40 Sensor</title>"
                 "<meta http-equiv=\"refresh\" content=\"5\"></head><body>"
                 "<h1>SHT40 Sensor Data</h1>"
                 "<p>Temperature: %.2f &deg;C</p>"
                 "<p>Humidity: %.2f %%</p>"
                 "</body></html>",
                 temperature, humidity);
    } else {
        snprintf(buffer, sizeof(buffer),
                 "<!DOCTYPE html><html><head><title>SHT40 Sensor</title>"
                 "<meta http-equiv=\"refresh\" content=\"5\"></head><body>"
                 "<h1>SHT40 Sensor</h1>"
                 "<p>Error: Failed to read sensor data</p>"
                 "</body></html>");
    }

    if (send(client_socket, buffer, strlen(buffer), 0) < 0) {
        perror("send");
    }
    close(client_socket);
}

int setup_server(int port) {
    int server_fd, opt = 1;
    struct sockaddr_in address;

    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        perror("socket");
        return -1;
    }

    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        perror("setsockopt");
        close(server_fd);
        return -1;
    }

    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(port);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind");
        close(server_fd);
        return -1;
    }

    if (listen(server_fd, 3) < 0) {
        perror("listen");
        close(server_fd);
        return -1;
    }

    return server_fd;
}

void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (server_fd >= 0) {
        close(server_fd);
        server_fd = -1;
    }
    gpioTerminate();
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SHT40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at address 0x%02X on bus %d\n", SHT40_ADDR, I2C_BUS);
        gpioTerminate();
        return 1;
    }

    server_fd = setup_server(SERVER_PORT);
    if (server_fd < 0) {
        fprintf(stderr, "Error: Failed to setup server\n");
        cleanup();
        return 1;
    }

    printf("Server listening on port %d\n", SERVER_PORT);

    while (running) {
        struct sockaddr_in address;
        socklen_t addrlen = sizeof(address);
        int client_socket = accept(server_fd, (struct sockaddr *)&address, &addrlen);
        if (client_socket < 0) {
            if (errno == EINTR && !running) break;
            perror("accept");
            continue;
        }
        handle_client(client_socket);
    }

    cleanup();
    return 0;
}

