#define HUM_REG_H  0x03
#define MEAS_CONFIG 0x0E
#define CONFIG_REG  0x0F
#define MEAS_TIMEOUT_MS 500
#define MAX_RETRIES 5

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int write_reg(uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(i2c_handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing 0x%02X to reg 0x%02X (rc=%d)\n", value, reg, rc);
        return -1;
    }
    return 0;
}

static int read_reg(uint8_t reg, uint8_t *value) {
    int rc = i2cReadByteData(i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading reg 0x%02X (rc=%d)\n", reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

static int wait_measurement(void) {
    for (int i = 0; i < MEAS_TIMEOUT_MS; i++) {
        uint8_t cfg;
        if (read_reg(CONFIG_REG, &cfg) < 0) return -1;
        if ((cfg & 0x01) == 0) return 0;
        gpioDelay(1000);
    }
    fprintf(stderr, "Measurement timeout\n");
    return -1;
}

static int read_temperature(float *temp) {
    if (write_reg(MEAS_CONFIG, 0x01) < 0) return -1;
    if (wait_measurement() < 0) return -1;
    uint8_t t_l, t_h;
    if (read_reg(TEMP_REG_L, &t_l) < 0) return -1;
    if (read_reg(TEMP_REG_H, &t_h) < 0) return -1;
    uint16_t raw = ((uint16_t)t_h << 8) | t_l;
    *temp = (raw / 65536.0f) * 165.0f - 40.0f;
    return 0;
}

static int read_humidity(float *hum) {
    if (write_reg(MEAS_CONFIG, 0x01) < 0) return -1;
    if (wait_measurement() < 0) return -1;
    uint8_t h_l, h_h;
    if (read_reg(HUM_REG_L, &h_l) < 0) return -1;
    if (read_reg(HUM_REG_H, &h_h) < 0) return -1;
    uint16_t raw = ((uint16_t)h_h << 8) | h_l;
    *hum = (raw / 65536.0f) * 100.0f;
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, HDC2010_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus 1 at 0x%02X (rc=%d)\n", HDC2010_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (running) {
        float temperature, humidity;
        int ok = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && running; attempt++) {
            if (read_temperature(&temperature) == 0 && read_humidity(&humidity) == 0) {
                ok = 1;
                break;
            }
            gpioDelay(100000);
        }

        if (ok) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
        } else {
            fprintf(stderr, "Failed to read sensor after %d attempts\n", MAX_RETRIES);
        }

        for (int s = 0; s < 50 && running; s++) {
            gpioDelay(100000);
        }
    }

    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

