#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_CHIP "gpiochip0"
#define RELAY_PIN 17
#define LOG_FILE "reflow_log.csv"
#define PROFILE_FILE "profile.txt"
#define SAMPLE_INTERVAL_SEC 1
#define MAX_RETRIES 3

volatile sig_atomic_t program_running = 1;

void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

int spi_init(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    unsigned int mode = SPI_MODE_0;
    unsigned int bits = 8;
    unsigned int speed = 1000000;

    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(fd);
        return -1;
    }
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Failed to set SPI bits per word");
        close(fd);
        return -1;
    }
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI max speed");
        close(fd);
        return -1;
    }

    return fd;
}

int read_max6675(int spi_fd, int *temperature) {
    unsigned char tx[4] = {0x01, 0x00, 0x00, 0x00};
    unsigned char rx[4] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 4,
        .speed_hz = 1000000,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer failed");
        return -1;
    }

    if (rx[0] & 0x01) {
        fprintf(stderr, "MAX6675 open circuit detected\n");
        return -2;
    }

    int raw = ((rx[1] & 0x0F) << 8) | rx[2];
    if (raw & 0x1000) {
        fprintf(stderr, "MAX6675 overflow\n");
        return -3;
    }

    *temperature = (int)(raw >> 2);
    return 0;
}

int read_profile(const char *filename, float *profile, int *num_points) {
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        perror("Failed to open profile file");
        return -1;
    }

    char line[256];
    *num_points = 0;
    while (fgets(line, sizeof(line), fp)) {
        *num_points++;
    }
    rewind(fp);

    int i = 0;
    while (i < *num_points && fgets(line, sizeof(line), fp)) {
        float temp;
        if (sscanf(line, "%f", &temp) == 1) {
            profile[i] = temp;
        } else {
            fprintf(stderr, "Invalid profile data: %s", line);
        }
        i++;
    }
    fclose(fp);

    if (i == 0) {
        fprintf(stderr, "No valid profile data found\n");
        return -1;
    }
    return 0;
}

float pid_control(float setpoint, float actual, float kp, float ki, float kd, float *integral, float *prev_error) {
    float error = setpoint - actual;
    *integral += error;
    float derivative = error - *prev_error;
    float output = kp * error + ki * (*integral) + kd * derivative;

    *prev_error = error;
    if (output < 0.0f) output = 0.0f;
    if (output > 1.0f) output = 1.0f;
    return output;
}

int log_data(float temperature, float duty_cycle) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Failed to open log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char s[64];
    strftime(s, sizeof(s), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%.2f,%.2f\n", s, temperature, duty_cycle);
    fclose(fp);
    return 0;
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int spi_fd = spi_init(SPI_DEVICE);
    if (spi_fd < 0) {
        return 1;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(spi_fd);
        return 1;
    }

    struct gpiod_line *relay_line = gpiod_chip_get_line(chip, RELAY_PIN);
    if (!relay_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        close(spi_fd);
        return 1;
    }

    if (gpiod_line_request_output(relay_line, "reflow_oven", 0) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_chip_close(chip);
        close(spi_fd);
        return 1;
    }

    float profile[100];
    int num_points;
    if (read_profile(PROFILE_FILE, profile, &num_points) < 0) {
        gpiod_line_release(relay_line);
        gpiod_chip_close(chip);
        close(spi_fd);
        return 1;
    }

    float kp = 1.0f, ki = 0.1f, kd = 0.01f;
    float integral = 0.0f, prev_error = 0.0f;

    while (program_running) {
        int temperature = -1;
        int retries = 0;
        while (retries < MAX_RETRIES && program_running) {
            int ret = read_max6675(spi_fd, &temperature);
            if (ret == 0) break;
            retries++;
