#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define HEATER_GPIO 17
#define PWM_GPIO 18
#define TEMP_SENSOR_GPIO 4
#define LOG_FILE "greenhouse.log"
#define SAMPLE_INTERVAL_SEC 5

#define MAX_SENSORS 2
#define MAX_RETRIES 3

#define TEMP_ERROR -1000.0f

typedef struct {
    float Kp;
    float Ki;
    float Kd;
} PIDParameters;

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *heater_line = NULL;
static struct gpiod_line *pwm_line = NULL;
static struct gpiod_line *temp_lines[MAX_SENSORS];
static int num_sensors = 0;
static char sensor_ids[MAX_SENSORS][32];
static PIDParameters pid_params;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_temperature(const char *sensor_id, float *temperature) {
    char path[128];
    snprintf(path, sizeof(path), "/sys/bus/w1/devices/%s/w1_slave", sensor_id);
    FILE *fp = fopen(path, "r");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", path, strerror(errno));
        return -1;
    }
    char line1[256], line2[256];
    if (!fgets(line1, sizeof(line1), fp) || !fgets(line2, sizeof(line2), fp)) {
        fprintf(stderr, "Error reading from %s: %s\n", path, strerror(errno));
        fclose(fp);
        return -1;
    }
    fclose(fp);
    if (strstr(line1, "YES") == NULL) {
        fprintf(stderr, "CRC check failed for sensor %s\n", sensor_id);
        return -1;
    }
    char *temp_str = strstr(line2, "t=");
    if (!temp_str) {
        fprintf(stderr, "Temperature data not found in %s\n", path);
        return -1;
    }
    long temp_raw = strtol(temp_str + 2, NULL, 10);
    *temperature = (float)temp_raw / 1000.0f;
    return 0;
}

static float calculate_pid(float setpoint, float current_temp, float *integral, float last_error, float Kp, float Ki, float Kd) {
    float error = setpoint - current_temp;
    *integral += error;
    float derivative = error - last_error;
    float output = Kp * error + Ki * (*integral) + Kd * derivative;
    last_error = error;
    return output;
}

static int set_pwm_duty_cycle(float duty_cycle) {
    if (duty_cycle < 0.0f) duty_cycle = 0.0f;
    if (duty_cycle > 1.0f) duty_cycle = 1.0f;
    int pwm_value = (int)(duty_cycle * 255.0f);
    if (gpiod_line_set_value(pwm_line, pwm_value) < 0) {
        fprintf(stderr, "Error setting PWM value: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static void log_data(float avg_temp, float setpoint, float pid_output, float pwm_duty) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(log_file, "%s, Avg Temp: %.2f, Setpoint: %.2f, PID Out: %.2f, PWM: %.2f\n",
            timestamp, avg_temp, setpoint, pid_output, pwm_duty);
    fflush(log_file);
}

static void cleanup(void) {
    if (heater_line) {
        gpiod_line_set_value(heater_line, 0);
        gpiod_line_release(heater_line);
        heater_line = NULL;
    }
    if (pwm_line) {
        gpiod_line_set_value(pwm_line, 0);
        gpiod_line_release(pwm_line);
        pwm_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main(int argc, char *argv[]) {
    if (argc != 5) {
        fprintf(stderr, "Usage: %s <setpoint> <Kp> <Ki> <Kd>\n", argv[0]);
        return 1;
    }
    float setpoint = atof(argv[1]);
    float Kp = atof(argv[2]);
    float Ki = atof(argv[3]);
    float Kd = atof(argv[4]);
    pid_params = (PIDParameters){Kp, Ki, Kd};

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return 1;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening gpiochip0: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    heater_line = gpiod_chip_get_line(chip, HEATER_GPIO);
    pwm_line = gpiod_chip_get_line(chip, PWM_GPIO);
    if (!heater_line || !pwm_line) {
        fprintf(stderr, "Error getting GPIO lines: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    if (gpiod_line_request_output(heater_line, "greenhouse_heater", 0) < 0 ||
        gpiod_line_request_output(pwm_line, "greenhouse_pwm", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO lines as output: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    for (int i = 0; i < MAX_SENSORS; i++) {
        printf("Enter sensor ID for sensor %d (max %d chars): ", i + 1, MAX_RETRIES);
        fflush(stdout);
        if (fgets(sensor_ids[i], MAX_RETRIES, stdin) == NULL) {
            fprintf(stderr, "Error reading sensor ID\n");
            cleanup();
            return 1;
        }
        sensor_ids[i][strcspn(sensor_ids[i], "\n")] = 0;
        if (sensor_ids[i][0] == '\0') {
            fprintf(stderr, "Invalid sensor ID, skipping\n");
            sensor_ids[i][0] = '\0';
        }
    }
    num_sensors = (int)(strcspn(sensor_ids[0], '\0') > 0 ? 1 : 0);
    for (int i = 1; i < MAX_SENSORS; i++) {
        if (sensor_ids[i][0] != '\0') {
            num_sensors++;
        }
    }

    float integral = 0.0f;
    float last_error = 0.0f;
    float avg_temp = 0.0f;
    int valid_readings = 0;
    int sensor_count = 0;

    while (running) {
        float temps[MAX_SENSORS];
        int valid = 0;
        for (int i = 0; i < num_sensors; i++) {
            float temp;
            if (read_temperature(sensor_ids[i], &temp) == 0) {
                temps[sensor_count] = temp;
                valid++;
            } else {
                fprintf(stderr, "Error reading sensor %s\n", sensor_ids[i]);
            }
        }
        if (valid > 0) {
            avg_temp = avg_temp * (valid - 1) / (float)(valid - 1) + temps[sensor_count] / (float)valid;
            sensor_count = (sensor_count + 1) % num_sensors;
        }

        float pid_output = calculate_pid(setpoint, avg_temp, &integral, last_error, pid_params.Kp, pid_params.Ki, pid_params.Kd);
        float pwm_duty = pid_output;

        if (set_pwm_duty_cycle(pwm_duty) < 0) {
            fprintf(stderr, "Error setting PWM duty cycle\n");
        }

        log_data(avg_temp, setpoint, pid_output, pwm_duty);
        last_error = setpoint - avg_temp;

        for (int i = 0; i < SAMPLE_INTERVAL_SEC && running; i++) {
            sleep(1);
        }
    }

    cleanup();
    return 0;
}

