#define I2C_BUS "/dev/i2c-1"
#define AHT20_ADDR 0x38
#define GPIO_CHIP "gpiochip4"
#define GPIO_LINE 17
#define HUMIDITY_HIGH 60.0
#define HUMIDITY_LOW 55.0
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10
#define POLL_INTERVAL_S 5

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_cmd(int fd, uint8_t cmd1, uint8_t cmd2, uint8_t cmd3) {
    uint8_t buf[3] = {cmd1, cmd2, cmd3};
    for (int i = 0; i < RETRY_COUNT; i++) {
        if (write(fd, buf, 3) == 3) return 0;
        fprintf(stderr, "I2C write failed (attempt %d/%d): %s\n", i + 1, RETRY_COUNT, strerror(errno));
        usleep(RETRY_DELAY_MS * 1000);
    }
    return -1;
}

static int i2c_read_data(int fd, uint8_t *buf, int len) {
    for (int i = 0; i < RETRY_COUNT; i++) {
        if (read(fd, buf, len) == len) return 0;
        fprintf(stderr, "I2C read failed (attempt %d/%d): %s\n", i + 1, RETRY_COUNT, strerror(errno));
        usleep(RETRY_DELAY_MS * 1000);
    }
    return -1;
}

static int aht20_init(int fd) {
    if (i2c_write_cmd(fd, 0xBE, 0x08, 0x00) < 0) {
        fprintf(stderr, "AHT20 init failed\n");
        return -1;
    }
    usleep(10000);
    return 0;
}

static int aht20_read_humidity(int fd, float *humidity) {
    if (i2c_write_cmd(fd, 0xAC, 0x33, 0x00) < 0) {
        fprintf(stderr, "AHT20 trigger failed\n");
        return -1;
    }
    usleep(80000);

    uint8_t status;
    if (i2c_read_data(fd, &status, 1) < 0) {
        fprintf(stderr, "AHT20 status read failed\n");
        return -1;
    }

    if ((status & 0x80) != 0) {
        fprintf(stderr, "AHT20 busy, status=0x%02X\n", status);
        return -1;
    }

    uint8_t data[6];
    if (i2c_read_data(fd, data, 6) < 0) {
        fprintf(stderr, "AHT20 data read failed\n");
        return -1;
    }

    uint32_t hum_raw = ((uint32_t)data[1] << 12) | ((uint32_t)data[2] << 4) | ((uint32_t)data[3] >> 4);
    *humidity = (float)hum_raw / 1024.0;
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, AHT20_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", AHT20_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    if (aht20_init(i2c_fd) < 0) {
        fprintf(stderr, "AHT20 initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    struct gpiod_line *relay = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!relay) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    if (gpiod_line_request_output(relay, "aht20-relay", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as output: %s\n", GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    printf("AHT20 dehumidifier control started. Press Ctrl+C to exit.\n");

    while (running) {
        float humidity;
        if (aht20_read_humidity(i2c_fd, &humidity) == 0) {
            time_t now = time(NULL);
            struct tm *tm_info = localtime(&now);
            char timestamp[64];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

            printf("%s - Humidity: %.2f%%\n", timestamp, humidity);

            if (humidity > HUMIDITY_HIGH) {
                gpiod_line_set_value(relay, 1);
                printf("Humidity above %.1f%% - Dehumidifier ON\n", HUMIDITY_HIGH);
            } else if (humidity < HUMIDITY_LOW) {
                gpiod_line_set_value(relay, 0);
                printf("Humidity below %.1f%% - Dehumidifier OFF\n", HUMIDITY_LOW);
            }
        } else {
            fprintf(stderr, "Sensor read failed, continuing...\n");
        }

        sleep(POLL_INTERVAL_S);
    }

    printf("\nShutting down...\n");
    gpiod_line_set_value(relay, 0);
    gpiod_line_release(relay);
    gpiod_chip_close(chip);
    close(i2c_fd);
    printf("Cleanup complete.\n");
    return 0;
}

