#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <syslog.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <time.h>

#define I2C_DEVICE "/dev/i2c-1"
#define HTU21D_ADDR 0x40
#define HTTP_ENDPOINT "http://api.example.com/humidity"
#define READ_INTERVAL 60
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static int sockfd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, unsigned char data) {
    if (write(fd, &data, 1) != 1) {
        syslog(LOG_ERR, "I2C write failed: %s", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, unsigned char *buf, int len) {
    int total = 0;
    while (total < len) {
        ssize_t n = read(fd, buf + total, len - total);
        if (n < 0) {
            if (errno == EINTR) continue;
            syslog(LOG_ERR, "I2C read failed: %s", strerror(errno));
            return -1;
        }
        if (n == 0) {
            syslog(LOG_ERR, "I2C read: unexpected EOF");
            return -1;
        }
        total += n;
    }
    return 0;
}

static int read_humidity(int fd, float *humidity) {
    unsigned char cmd = 0xE5;
    unsigned char data[3];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2c_write_byte(fd, cmd) < 0) {
            retries++;
            sleep(1);
            continue;
        }
        usleep(20000);

        if (i2c_read_bytes(fd, data, 3) < 0) {
            retries++;
            sleep(1);
            continue;
        }

        if (data[0] == 0x00) {
            syslog(LOG_WARNING, "HTU21D returned 0x00, sensor may be absent");
            return -1;
        }

        unsigned int raw = ((unsigned int)data[0] << 8) | data[1];
        raw &= 0xFFFC;
        *humidity = -6.0f + 125.0f * (float)raw / 65536.0f;
        if (*humidity < 0.0f) *humidity = 0.0f;
        if (*humidity > 100.0f) *humidity = 100.0f;
        return 0;
    }
    syslog(LOG_ERR, "Failed to read humidity after %d retries", MAX_RETRIES);
    return -1;
}

static int post_data(const char *json) {
    struct sockaddr_in addr;
    char request[512];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        sockfd = socket(AF_INET, SOCK_STREAM, 0);
        if (sockfd < 0) {
            syslog(LOG_ERR, "Socket creation failed: %s", strerror(errno));
            retries++;
            sleep(1);
            continue;
        }

        memset(&addr, 0, sizeof(addr));
        addr.sin_family = AF_INET;
        addr.sin_port = htons(80);
        if (inet_pton(AF_INET, "api.example.com", &addr.sin_addr) <= 0) {
            syslog(LOG_ERR, "Invalid address: %s", strerror(errno));
            close(sockfd);
            sockfd = -1;
            retries++;
            sleep(1);
            continue;
        }

        if (connect(sockfd, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
            syslog(LOG_ERR, "Connect failed: %s", strerror(errno));
            close(sockfd);
            sockfd = -1;
            retries++;
            sleep(1);
            continue;
        }

        int written = snprintf(request, sizeof(request),
            "POST %s HTTP/1.1\r\n"
            "Host: %s\r\n"
            "Content-Type: application/json\r\n"
            "Content-Length: %zu\r\n"
            "Connection: close\r\n"
            "\r\n"
            "%s",
            HTTP_ENDPOINT, "api.example.com", strlen(json), json);

        if (written < 0 || (size_t)written >= sizeof(request)) {
            syslog(LOG_ERR, "Request buffer too small");
            close(sockfd);
            sockfd = -1;
            retries++;
            sleep(1);
            continue;
        }

        if (send(sockfd, request, written, 0) < 0) {
            syslog(LOG_ERR, "Send failed: %s", strerror(errno));
            close(sockfd);
            sockfd = -1;
            retries++;
            sleep(1);
            continue;
        }

        char response[1024];
        ssize_t r = recv(sockfd, response, sizeof(response) - 1, 0);
        if (r > 0) {
            response[r] = '\0';
            syslog(LOG_INFO, "HTTP response: %s", response);
            close(sockfd);
            sockfd = -1;
            return 0;
        } else if (r == 0) {
            syslog(LOG_INFO, "Server closed connection");
            close(sockfd);
            sockfd = -1;
            return 0;
        } else {
            syslog(LOG_ERR, "Receive failed: %s", strerror(errno));
            close(sockfd);
            sockfd = -1;
            retries++;
            sleep(1);
        }
    }
    syslog(LOG_ERR, "Failed to post data after %d retries", MAX_RETRIES);
    return -1;
}

int main(void) {
    openlog("humidity_monitor", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        syslog(LOG_ERR, "Failed to open %s: %s", I2C_DEVICE, strerror(errno));
        closelog();
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, HTU21D_ADDR) < 0) {
        syslog(LOG_ERR, "Failed to set I2C slave address 0x%02X: %s", HTU21D_ADDR, strerror(errno));
        close(i2c_fd);
        closelog();
        return 1;
    }

    syslog(LOG_INFO, "Starting humidity monitoring on %s (addr 0x%02X)", I2C_DEVICE, HTU21D_ADDR);

    while (running) {
        float humidity = 0.0f;
        if (read_humidity(i2c_fd, &humidity) == 0) {
            char json[64];
            snprintf(json, sizeof(json), "{\"humidity\": %.2f}", humidity);
            syslog(LOG_INFO, "Humidity: %.2f%%, JSON: %s", humidity, json);
            if (post_data(json) == 0) {
                syslog(LOG_INFO, "Data posted successfully");
            } else {
                syslog(LOG_ERR, "Failed to post data");
            }
        } else {
            syslog(LOG_ERR, "Failed to read humidity");
        }

        for (int i = 0; i < READ_INTERVAL && running; i++) {
            sleep(1);
        }
    }

    syslog(LOG_INFO, "Shutting down");
    if (i2c_fd >= 0) close(i2c_fd);
    if (sockfd >= 0) close(sockfd);
    closelog();
    return 0;
}

