#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define TMP117_ADDR    0x48
#define AHT20_ADDR     0x38
#define PIR_GPIO_LINE  17
#define GPIO_CHIP      "gpiochip4"

#define TMP117_TEMP_REG 0x00
#define TMP117_CONFIG_REG 0x01
#define TMP117_CONFIG_DEFAULT 0x00
#define TMP117_TEMP_LSB 0.0078125f

#define AHT20_INIT_CMD 0xBE 0x08 0x00
#define AHT20_MEASURE_CMD 0xAC 0x33 0x00
#define AHT20_BUSY_BIT  0x80
#define AHT20_DATA_LEN 7

#define SAMPLE_INTERVAL_SEC 1
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_cmd(int fd, uint8_t cmd0, uint8_t cmd1, uint8_t cmd2) {
    uint8_t buf[3] = {cmd0, cmd1, cmd2};
    if (write(fd, buf, 3) != 3) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, int len) {
    if (read(fd, buf, len) != len) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int tmp117_init(int fd) {
    if (i2c_write_cmd(fd, 0x80, 0x00, 0x00) < 0) return -1;
    usleep(10000);
    return 0;
}

static int tmp117_read_temp(int fd, float *temp) {
    if (i2c_write_cmd(fd, 0x80, 0x00, 0x00) < 0) return -1;
    usleep(10000);
    uint8_t buf[2];
    if (i2c_read_bytes(fd, buf, 2) < 0) return -1;
    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *temp = raw * TMP117_TEMP_LSB;
    return 0;
}

static int aht20_init(int fd) {
    if (i2c_write_cmd(fd, AHT20_INIT_CMD[0], AHT20_INIT_CMD[1], AHT20_INIT_CMD[2]) < 0) return -1;
    usleep(10000);
    return 0;
}

static int aht20_read_humidity(int fd, float *humidity) {
