#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define RAIN_SENSOR_PIN 17
#define MOTOR_ENABLE_PIN 22
#define MOTOR_IN1_PIN 23
#define MOTOR_IN2_PIN 24

#define POLL_INTERVAL_SEC 2
#define MOTOR_RUN_SEC 5

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    printf("[%s] %s\n", timestamp, message);
    fflush(stdout);
}

static int set_motor_direction(struct gpiod_line *en, struct gpiod_line *in1,
                                struct gpiod_line *in2, int forward) {
    int val;
    if (forward) {
        val = 1;
    } else {
        val = 0;
    }
    if (gpiod_line_set_value(in1, val) < 0) {
        log_event("Error: failed to set IN1");
        return -1;
    }
    if (gpiod_line_set_value(in2, 0) < 0) {
        log_event("Error: failed to set IN2");
        return -1;
    }
    if (gpiod_line_set_value(en, 1) < 0) {
        log_event("Error: failed to set ENA");
        return -1;
    }
    return 0;
}

static void stop_motor(struct gpiod_line *en, struct gpiod_line *in1,
                       struct gpiod_line *in2) {
    gpiod_line_set_value(en, 0);
    gpiod_line_set_value(in1, 0);
    gpiod_line_set_value(in2, 0);
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *rain_line = NULL;
    struct gpiod_line *en_line = NULL;
    struct gpiod_line *in1_line = NULL;
    struct gpiod_line *in2_line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        log_event("Error: failed to open gpiochip4");
        return EXIT_FAILURE;
    }

    rain_line = gpiod_chip_get_line(chip, RAIN_SENSOR_PIN);
    en_line = gpiod_chip_get_line(chip, MOTOR_ENABLE_PIN);
    in1_line = gpiod_chip_get_line(chip, MOTOR_IN1_PIN);
    in2_line = gpiod_chip_get_line(chip, MOTOR_IN2_PIN);

    if (!rain_line || !en_line || !in1_line || !in2_line) {
        log_event("Error: failed to get GPIO lines");
        goto cleanup;
    }

    if (gpiod_line_request_input(rain_line, "rain_sensor") < 0) {
        log_event("Error: failed to request rain sensor line as input");
        goto cleanup;
    }

    if (gpiod_line_request_output(en_line, "motor_enable", 0) < 0) {
        log_event("Error: failed to request motor enable line as output");
        goto cleanup;
    }

    if (gpiod_line_request_output(in1_line, "motor_in1", 0) < 0) {
        log_event("Error: failed to request motor IN1 line as output");
        goto cleanup;
    }

    if (gpiod_line_request_output(in2_line, "motor_in2", 0) < 0) {
        log_event("Error: failed to request motor IN2 line as output");
        goto cleanup;
    }

    log_event("Program started: monitoring rain sensor on GPIO17, motor on GPIO22/23/24");

    while (program_running) {
        int val = gpiod_line_get_value(rain_line);
        if (val < 0) {
            log_event("Error: failed to read rain sensor");
            sleep(POLL_INTERVAL_SEC);
            continue;
        }

        if (val == 0) {
            log_event("Rain detected! Closing window.");
            if (set_motor_direction(en_line, in1_line, in2_line, 1) < 0) {
                log_event("Error: failed to start motor");
            } else {
                sleep(MOTOR_RUN_SEC);
                stop_motor(en_line, in1_line, in2_line);
                log_event("Motor stopped.");
            }
        }

        sleep(POLL_INTERVAL_SEC);
    }

    log_event("Program exiting gracefully.");
    ret = EXIT_SUCCESS;

cleanup:
    stop_motor(en_line, in1_line, in2_line);
    if (rain_line) gpiod_line_release(rain_line);
    if (en_line) gpiod_line_release(en_line);
    if (in1_line) gpiod_line_release(in1_line);
    if (in2_line) gpiod_line_release(in2_line);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

