#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <errno.h>
#include <pigpio.h>

#define RED_PIN    17
#define GREEN_PIN  22
#define BLUE_PIN   27

#define PWM_RANGE  255
#define PWM_FREQ   1000
#define SAMPLE_MS  500

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int read_cpu_load(void)
{
    FILE *fp;
    unsigned long long prev_idle, prev_total;
    unsigned long long cur_idle, cur_total;
    unsigned long long prev_nonidle, prev_total_nonidle;
    unsigned long long cur_nonidle, cur_total_nonidle;
    unsigned long long prev_totald, prev_total;
    unsigned long long cur_totald, cur_total;

    fp = fopen("/proc/stat", "r");
    if (!fp) {
        fprintf(stderr, "Error opening /proc/stat: %s\n", strerror(errno));
        return -1;
    }

    if (fscanf(fp, "cpu  %llu %llu %llu %llu",
               &prev_idle, &prev_nonidle, &prev_total, &prev_totald) != 4) {
        fprintf(stderr, "Error parsing /proc/stat\n");
        fclose(fp);
        return -1;
    }

    fclose(fp);

    usleep(SAMPLE_MS * 1000);

    fp = fopen("/proc/stat", "r");
    if (!fp) {
        fprintf(stderr, "Error opening /proc/stat: %s\n", strerror(errno));
        return -1;
    }

    if (fscanf(fp, "cpu  %llu %llu %llu %llu",
               &cur_idle, &cur_nonidle, &cur_total, &cur_totald) != 4) {
        fprintf(stderr, "Error parsing /proc/stat\n");
        fclose(fp);
        return -1;
    }

    fclose(fp);

    unsigned long long prev_idle_total = prev_idle + prev_nonidle;
    unsigned long long cur_idle_total = cur_idle + cur_nonidle;
    unsigned long long prev_totald_total = prev_totald + prev_total;
    unsigned long long cur_totald_total = cur_totald + cur_total;

    unsigned long long prev_total = prev_totald_total + prev_idle_total;
    unsigned long long cur_total = cur_totald_total + cur_idle_total;

    unsigned long long totald = cur_totald_total - prev_totald_total;
    unsigned long long idled = prev_idle_total - cur_idle_total;

    unsigned long long delta_total = cur_total - prev_total;
    unsigned long long delta_idle = idled;

    unsigned long long load = 0;
    if (delta_total > 0) {
        load = (delta_totald - delta_idle) / (double)delta_total * 100.0;
    }

    return (unsigned long long)load;
}

static void set_rgb_color(unsigned char r, unsigned char g, unsigned char b)
{
    if (gpioPWM(RED_PIN,   r) < 0) fprintf(stderr, "Warning: gpioPWM(RED) failed\n");
    if (gpioPWM(GREEN_PIN, g) < 0) fprintf(stderr, "Warning: gpioPWM(GREEN) failed\n");
    if (gpioPWM(BLUE_PIN,  b) < 0) fprintf(stderr, "Warning: gpioPWM(BLUE) failed\n");
}

static void map_cpu_to_color(unsigned long long cpu_load, unsigned char *r, unsigned char *g, unsigned char *b)
{
    if (cpu_load == 0) {
        *r = 0; *g = 255; *b = 0;
    } else if (cpu_load <= 50) {
        *r = 255; *g = 255; *b = 0;
    } else {
        *r = 255; *g = 0; *b = 0;
    }
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(RED_PIN,   PI_OUTPUT) < 0 ||
        gpioSetMode(GREEN_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(BLUE_PIN,  PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMrange(RED_PIN,   PWM_RANGE) < 0 ||
        gpioSetPWMrange(GREEN_PIN, PWM_RANGE) < 0 ||
        gpioSetPWMrange(BLUE_PIN,  PWM_RANGE) < 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMfrequency(RED_PIN,   PWM_FREQ) < 0 ||
        gpioSetPWMfrequency(GREEN_PIN, PWM_FREQ) < 0 ||
        gpioSetPWMfrequency(BLUE_PIN,  PWM_FREQ) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install signal handlers: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    unsigned char r, g, b;
    unsigned long long prev_load = read_cpu_load();

    while (g_running) {
        unsigned long long load = read_cpu_load();

        if (load == -1) {
            fprintf(stderr, "Error reading CPU load, exiting.\n");
            break;
        }

        map_cpu_to_color(load, &r, &g, &b);
        set_rgb_color(r, g, b);

        prev_load = load;
        usleep(SAMPLE_MS * 1000);
    }

    /* Turn LED off (common-anode: full off = 0) */
    gpioPWM(RED_PIN,   0);
    gpioPWM(GREEN_PIN, 0);
    gpioPWM(BLUE_PIN,  0);

    gpioTerminate();
    return 0;
}

