int bmp280_init(int handle) {
    uint8_t id;
    if (i2c_read_reg(handle, BMP280_REG_ID, &id, 1) < 0) {
        fprintf(stderr, "Error: Failed to read chip ID register.\n");
        return -1;
    }
    if (id != BMP280_CHIP_ID) {
        fprintf(stderr, "Error: Invalid chip ID 0x%02X (expected 0x%02X). Sensor not present.\n", id, BMP280_CHIP_ID);
        return -1;
    }
    if (i2c_write_reg(handle, BMP280_REG_RESET, 0xB6) < 0) {
        fprintf(stderr, "Error: Failed to reset sensor.\n");
        return -1;
    }
    gpioDelay(2000);
    if (read_calibration_data(handle, &calib) < 0) {
        fprintf(stderr, "Error: Failed to read calibration data.\n");
        return -1;
    }
    if (i2c_write_reg(handle, BMP280_REG_CONFIG, 0x00) < 0) return -1;
    if (i2c_write_reg(handle, BMP280_REG_CTRL_MEAS, 0x27) < 0) return -1;
    return 0;
}

int bmp280_read_raw(int handle, int32_t *temperature, int32_t *pressure) {
    uint8_t buf[6];
    if (i2c_write_reg(handle, BMP280_REG_CTRL_MEAS, 0x27) < 0) return -1;
    gpioDelay(10000);
    if (i2c_read_reg(handle, BMP280_REG_PRESS_MSB, buf, 6) < 0) return -1;
    *pressure = (int32_t)((buf[0] << 12) | (buf[1] << 4) | (buf[2] >> 4));
    *temperature = (int32_t)((buf[3] << 12) | (buf[4] << 4) | (buf[5] >> 4));
    return 0;
}

double compensate_temperature(int32_t raw_temp, bmp280_calib_data cal) {
    double var1 = ((double)raw_temp / 16384.0 - (double)cal.dig_T1 / 1024.0) * (double)cal.dig_T2;
    double var2 = ((double)raw_temp / 131072.0 - (double)cal.dig_T1 / 8192.0) * ((double)raw_temp / 131072.0 - (double)cal.dig_T1 / 8192.0) * (double)cal.dig_T3;
    t_fine = (int32_t)(var1 + var2);
    return (var1 + var2) / 5120.0;
}

double compensate_pressure(int32_t raw_pressure, bmp280_calib_data cal, int32_t t_fine) {
    double var1 = (double)t_fine / 2.0 - 64000.0;
    double var2 = var1 * var1 * (double)cal.dig_P6 / 32768.0;
    var2 = var2 + var1 * (double)cal.dig_P5 * 2.0;
    var2 = (var2 / 4.0) + ((double)cal.dig_P4 * 65536.0);
    var1 = ((double)cal.dig_P3 * var1 * var1 / 524288.0 + (double)cal.dig_P2 * var1) / 524288.0;
    var1 = (1.0 + var1 / 32768.0) * (double)cal.dig_P1;
    if (var1 == 0.0) return 0.0;
    double p = 1048576.0 - (double)raw_pressure;
    p = (p - (var2 / 4096.0)) * 6250.0 / var1;
    var1 = (double)cal.dig_P9 * p * p / 2147483648.0;
    var2 = p * (double)cal.dig_P8 / 32768.0;
    p = p + (var1 + var2 + (double)cal.dig_P7) / 16.0;
    return p;
}

int send_udp_data(const char *data) {
    struct sockaddr_in server_addr;
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(UDP_SERVER_PORT);
    if (inet_pton(AF_INET, UDP_SERVER_IP, &server_addr.sin_addr) <= 0) {
        fprintf(stderr, "Error: Invalid address: %s\n", UDP_SERVER_IP);
        return -1;
    }
    if (sendto(udp_socket, data, strlen(data), 0, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        fprintf(stderr, "Error: Failed to send UDP data: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }
    i2c_handle = i2cOpen(1, BMP280_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }
    if (bmp280_init(i2c_handle) < 0) {
        fprintf(stderr, "Error: BMP280 initialisation failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    udp_socket = socket(AF_INET, SOCK_DGRAM, 0);
    if (udp_socket < 0) {
        fprintf(stderr, "Error: Failed to create UDP socket: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    while (running) {
        int32_t raw_temp, raw_pressure;
        if (bmp280_read_raw(i2c_handle, &raw_temp, &raw_pressure) < 0) {
            fprintf(stderr, "Error: Failed to read sensor data.\n");
        } else {
            double temperature = compensate_temperature(raw_temp, calib);
            double pressure = compensate_pressure(raw_pressure, calib, t_fine);
            char json_string[128];
            snprintf(json_string, sizeof(json_string), "{\"temperature\": %.2f, \"pressure\": %.2f}", temperature, pressure);
            if (send_udp_data(json_string) < 0) {
                fprintf(stderr, "Error: Failed to send UDP data.\n");
            }
        }
        sleep(SAMPLE_INTERVAL_SEC);
    }
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    if (udp_socket >= 0) close(udp_socket);
    gpioTerminate();
    return 0;
}

