#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FAN_GPIO          18
#define SPI_CHANNEL       0
#define SPI_SPEED         500000
#define SPI_FLAGS         0
#define PWM_FREQUENCY     1000
#define PWM_RANGE         255
#define BUFFER_SIZE       20
#define SAMPLE_INTERVAL_S 1

/* MAX31855 register: 32 bits, MSB first */
#define REG_TEMP          0x00
#define REG_OSC           0x01
#define REG_FAULT         0x02

#define FAULT_NONE         0x0000
#define FAULT_OPEN_CIRCUIT 0x0001
#define FAULT_SHORT_TO_GND 0x0002
#define FAULT_SHORT_TO_VCC 0x0004

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

typedef struct {
    time_t timestamp;
    float  temperature;
    int    pwm_duty;
} Reading;

static Reading g_buffer[BUFFER_SIZE];
static int     g_head = 0;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void add_reading(float temp, int duty)
{
    g_buffer[g_head].timestamp   = time(NULL);
    g_buffer[g_head].temperature = temp;
    g_buffer[g_head].pwm_duty    = duty;
    g_head = (g_head + 1) % BUFFER_SIZE;
}

static void print_buffer(void)
{
    printf("\n--- Reading Log (%d entries) ---\n", BUFFER_SIZE);
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int idx = (g_head - 1 - i + BUFFER_SIZE) % BUFFER_SIZE;
        char ts[32];
        struct tm *tm = localtime(&g_buffer[idx].timestamp);
        if (tm)
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
        else
            snprintf(ts, sizeof(ts), "unknown");
        printf("[%s] Temp: %.2f C, PWM: %d\n",
               ts, g_buffer[idx].temperature, g_buffer[idx].pwm_duty);
    }
    printf("--- End of Log ---\n");
}

/*
 * MAX31855 32-bit register layout (MSB first):
 *   D[31:18]  Thermocouple temperature, signed 14-bit, 0.25 C/LSB
 *   D[17]     Reserved
 *   D[16]     Fault bit
 *   D[15:4]   SCV, SCG, SCF, reserved
 *   D[3]      Reserved
 *   D[2]      SCV fault
 *   D[1]      SCG fault
 *   D[0]      OC fault
 */
static int read_max31855(int handle, float *temp_out)
{
    char tx[4] = { REG_TEMP, 0x00, 0x00, 0x00 };
    char rx[4] = { 0, 0, 0, 0 };

    if (spiXfer(handle, tx, rx, 4) != 4) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    uint32_t raw = ((uint32_t)(uint8_t)rx[0] << 24) |
                   ((uint32_t)(uint8_t)rx[1] << 16) |
                   ((uint32_t)(uint8_t)rx[2] <<  8) |
                   ((uint32_t)(uint8_t)rx[3]);

    if (raw & 0x00010000) {
        uint32_t fault = raw & 0x00007FF;
        if (fault & 0x0001)
            fprintf(stderr, "MAX31855 fault: Open circuit\n");
        if (fault & 0x0002)
            fprintf(stderr, "MAX31855 fault: Short to GND\n");
        if (fault & 0x0004)
            fprintf(stderr, "MAX31855 fault: Short to VCC\n");
        return -2;
    }

    int16_t thermocouple = (int16_t)((raw >> 18) & 0x3FFF);
    if (thermocouple & 0x2000)
        thermocouple |= 0xC000; /* sign-extend 14-bit to 16-bit */

    *temp_out = (float)thermocouple * 0.25f;
    return 0;
}

static int calculate_pwm(float temp)
{
    if (temp < 25.0f) return 0;
    if (temp < 40.0f) return (int)((temp - 25.0f) * 2.0f);
    if (temp < 60.0f) return 50 + (int)(((temp - 40.0f) * 5.0f) / 20.0f);
    return 255;
}

static int set_fan_pwm(int duty)
{
    if (gpioPWM(FAN_GPIO, duty) != 0) {
        fprintf(stderr, "gpioPWM failed for duty %d\n", duty);
        return -1;
    }
    return 0;
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", FAN_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO%d\n", FAN_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(FAN_GPIO, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range on GPIO%d\n", FAN_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (channel %d, %d Hz): %d\n",
                SPI_CHANNEL, SPI_SPEED, g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Fan control started. SPI0 CE0 @ %d Hz, MAX31855 on GPIO18 PWM.\n",
           SPI_SPEED);
    printf("Press Ctrl+C to stop.\n");

    while (g_running) {
        float temp;
        int rc = read_max31855(g_spi_handle, &temp);

        if (rc == 0) {
            int duty = calculate_pwm(temp);
            if (set_fan_pwm(duty) == 0)
                add_reading(temp, duty);
            else
                fprintf(stderr, "Failed to update fan PWM\n");
        } else if (rc == -2) {
            fprintf(stderr, "MAX31855 fault detected — skipping fan update\n");
        } else {
            fprintf(stderr, "SPI transfer error — skipping fan update\n");
        }

        sleep(SAMPLE_INTERVAL_S);
    }

    /* Graceful shutdown */
    printf("\nShutting down...\n");
    set_fan_pwm(0);
    spiClose(g_spi_handle);
    g_spi_handle = -1;
    print_buffer();
    gpioTerminate();
    printf("Fan control stopped.\n");
    return EXIT_SUCCESS;
}

