#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_CHIP "gpiochip4"
#define CS_LINE 8
#define SPI_SPEED 1000000
#define LOG_FILE "rtd_log.csv"
#define SAMPLE_INTERVAL 5

#define MAX31865_RTD_MSB 0x01
#define MAX31865_RTD_LSB 0x02
#define MAX31865_FAULT 0x00
#define MAX31865_RTD_CONFIG 0x01
#define MAX31865_RTD_CONFIG_VALUE 0x0F
#define MAX31865_RTD_A 0x02
#define MAX31865_RTD_B 0x03
#define MAX31865_RTD_C 0x04
#define MAX31865_RTD_D 0x05
#define MAX31865_RTD_T 0x06
#define MAX31865_RTD_TL 0x07
#define MAX31865_RTD_TU 0x08
#define MAX31865_RTD_TL_CONFIG 0x09
#define MAX31865_RTD_TU_CONFIG 0x0A
#define MAX31865_RTD_TL_VALUE 0x0B
#define MAX31865_RTD_TU_VALUE 0x0C
#define MAX31865_RTD_TL_CONFIG_VALUE 0x0D
#define MAX31865_RTD_TU_CONFIG_VALUE 0x0E
#define MAX31865_RTD_TL_CONFIG_VALUE_2 0x0F

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *cs_line = NULL;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    uint8_t mode = SPI_MODE_3;
    uint8_t bits = 8;
    uint32_t speed = SPI_SPEED;

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    return 0;
}

int gpio_init(void) {
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    cs_line = gpiod_chip_get_line(chip, CS_LINE);
    if (!cs_line) {
        perror("Failed to get CS line");
        gpiod_chip_close(chip);
        chip = NULL;
        return -1;
    }

    if (gpiod_line_request_output(cs_line, "max31865_cs", 1) < 0) {
        perror("Failed to request CS line as output");
        gpiod_chip_close(chip);
        chip = NULL;
        cs_line = NULL;
        return -1;
    }

    return 0;
}

int max31865_write_register(uint8_t reg, uint8_t value) {
    uint8_t tx[2] = {reg & 0x7F, value};
    uint8_t rx[2] = {0};

    if (gpiod_line_set_value(cs_line, 0) < 0) {
        perror("Failed to assert CS");
        return -1;
    }

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 2,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer failed");
        gpiod_line_set_value(cs_line, 1);
        return -1;
    }

    if (gpiod_line_set_value(cs_line, 1) < 0) {
        perror("Failed to deassert CS");
        return -1;
    }

    return 0;
}

int max31865_read_register(uint8_t reg, uint8_t *value) {
    if (!value) return -1;

    uint8_t tx[2] = {reg | 0x80, 0x00};
    uint8_t rx[2] = {0};

    if (gpiod_line_set_value(cs_line, 0) < 0) {
        perror("Failed to assert CS");
        return -1;
    }

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 2,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer failed");
        gpiod_line_set_value(cs_line, 1);
        return -1;
    }

    if (gpiod_line_set_value(cs_line, 1) < 0) {
        perror("Failed to deassert CS");
        return -1;
    }

    *value = rx[1];
    return 0;
}

int max31865_read_rtd(uint16_t *rtd_value) {
    uint8_t msb, lsb;
    if (max31865_read_register(MAX31865_RTD_MSB, &msb) < 0) return -1;
    if (max31865_read_register(MAX31865_RTD_LSB, &lsb) < 0) return -1;

    *rtd_value = ((uint16_t)msb << 8) | lsb;
    return 0;
}

int max31865_read_fault(uint8_t *fault) {
    return max31865_read_register(MAX31865_FAULT, fault);
}

int max31865_read_rtd_config(uint8_t *config) {
    return max31865_read_register(MAX31865_RTD_CONFIG, config);
}

int max31865_read_rtd_a(uint8_t *a) {
    return max31865_read_register(MAX31865_RTD_A, a);
}

int max31865_read_rtd_b(uint8_t *b) {
    return max31865_read_register(MAX31865_RTD_B, b);
}

int max31865_read_rtd_c(uint8_t *c) {
    return max31865_read_register(MAX31865_RTD_C, c);
}

int max31865_read_rtd_d(uint8_t *d) {
    return max31865_read_register(MAX31865_RTD_D, d);
}

int max31865_read_rtd_tl(uint8_t *tl) {
    return max31865_read_register(MAX31865_RTD_TL_CONFIG, tl);
}

int max31865_read_rtd_tu(uint8_t *tu) {
    return max31865_read_register(MAX31865_RTD_TU_CONFIG, tu);
}

int max31865_read_rtd_tl_value(uint8_t *value) {
    return max31865_read_register(MAX31865_RTD_TL_VALUE, value);
}

int max31865_read_rtd_tu_value(uint8_t *value) {
    return max31865_read_register(MAX31865_RTD_TU_VALUE, value);
}

int max31865_read_rtd_tl_config(uint8_t *value) {
    return max31865_read_register(MAX31865_RTD_TL_CONFIG_VALUE, value);
}

int max31865_read_rtd_tu_config(uint8_t *value) {
    return max31865_read_register(MAX31865_RTD_TU_CONFIG_VALUE, value);
}

int max31865_read_rtd_tl_config_2(uint8_t *value) {
    return max31865_read_register(MAX31865_RTD_TL_CONFIG_VALUE_2, value);
}

int max31865_init(void) {
    uint8_t config = MAX31865_RTD_CONFIG_VALUE;
    uint8_t a, b, c, d, tl, tu, tl_val, tu_val, tl_cfg, tu_cfg;

    if (max31865_write_register(MAX31865_RTD_CONFIG, config) < 0) {
        fprintf(stderr, "Failed to write config register\n");
        return -1;
    }

    if (max31865_read_register(MAX31865_RTD_CONFIG, &config) < 0) {
        fprintf(stderr, "Failed to read config register\n");
        return -1;
    }

    if (max31865_read_register(MAX31865_RTD_A, &a) < 0) {
        fprintf(stderr, "Failed to read RTD A register\n");
        return -1;
    }
    if (max31865_read_register(MAX31865_RTD_B, &b) < 0) {
        fprintf(stderr, "Failed to read RTD B register\n");
        return -1;
    }
    if (max31865_read_register(MAX31865_RTD_C, &c) < 0) {
        fprintf(stderr, "Failed to read RTD C register\n");
        return -1;
    }
    if (max31865_read_register(MAX31865_RTD_D, &d) < 0) {
        fprintf(stderr, "Failed to read RTD D register\n");
        return -1;
    }
    if (max31865_read_register(MAX31865_RTD_TL_CONFIG, &tl_cfg) < 0) {
        fprintf(stderr, "Failed to read RTD TL config register\n");
        return -1;
    }
    if (max31865_read_register(MAX31865_RTD_TU_CONFIG, &tu_cfg) < 0) {
        fprintf(stderr, "Failed to read RTD TU config register\n");
        return -1;
    }
    if (max31865_read_register(MAX31865_RTD_TL_VALUE, &tl_val) < 0) {
        fprintf(stderr, "Failed to read RTD TL value register\n");
        return -1;
    }
    if (max31865_read_register(MAX31865_RTD_TU_VALUE, &tu_val) < 0) {
        fprintf(stderr, "Failed to read RTD TU value register\n");
        return -1;
    }

    if (max31865_read_register(MAX31865_RTD_TL_CONFIG_VALUE_2, &tl_cfg_2) < 0) {
        fprintf(stderr, "Failed to read RTD TL config register 2\n");
        return -1;
    }

    if (max31865_read_fault(&tl) < 0) {
        fprintf(stderr, "Failed to read fault register\n");
        return -1;
    }

    if (tl) {
        fprintf(stderr, "MAX31865 fault detected: 0x%02X\n", tl);
        return -1;
    }

    if (max31865_write_register(MAX31865_RTD_TL_CONFIG, tl_cfg) < 0) {
        fprintf(stderr, "Failed to write RTD TL config register\n");
        return -1;
    }
    if (max31865_write_register(MAX31865_RTD_TU_CONFIG, tu_cfg) < 0) {
        fprintf(stderr, "Failed to write RTD TU config register\n");
        return -1;
    }
    if (max31865_write_register(MAX31865_RTD_TL_VALUE, tl_val) < 0) {
        fprintf(stderr, "Failed to write RTD TL value register\n");
        return -1;
    }
    if (max31865_write_register(MAX31865_RTD_TU_VALUE, tu_val) < 0) {
        fprintf(stderr, "Failed to write RTD TU value register\n");
        return -1;
    }
    if (max31865_write_register(MAX31865_RTD_TL_CONFIG_VALUE_2, tl_cfg_2) < 0) {
        fprintf(stderr, "Failed to write RTD TL config register 2\n");
        return -1;
    }

    return 0;
}

float calculate_temperature(uint16_t rtd_value) {
    float rtd_resistance = (float)rtd_value * 430.0 / 32768.0;
    float temperature = -45.0 + 165.0 * (rtd_resistance - 100.0) / 430.0;
    return temperature;
}

int log_data(float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            perror("Failed to open log file");
            return -1;
        }
    }

    fprintf(log_file, "%s,%.2f\n", timestamp, temperature);
    fflush(log_file);
    return 0;
}

void cleanup(void) {
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
    if (cs_line != NULL) {
        gpiod_line_release(cs_line);
        cs_line = NULL;
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (spi_init() < 0) {
        fprintf(stderr, "SPI initialization failed\n");
        return 1;
    }

    if (gpio_init() < 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        close(spi_fd);
        return 1;
    }

    if (max31865_init() < 0) {
