#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>

#define BMP180_ADDR 0x77
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_OSS 0
#define ALERT_GPIO 24
#define BUFFER_SIZE 3600
#define SAMPLE_INTERVAL_MS 50
#define ALERT_THRESHOLD_HPA 5.0

typedef struct {
    time_t timestamp;
    float pressure;
} PressureData;

typedef struct {
    PressureData data[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
static uint16_t ac4, ac5, ac6;

static void circular_buffer_init(CircularBuffer *cb) {
    cb->head = 0;
    cb->count = 0;
}

static void circular_buffer_add(CircularBuffer *cb, float pressure) {
    cb->data[cb->head].timestamp = time(NULL);
    cb->data[cb->head].pressure = pressure;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) cb->count++;
}

static float circular_buffer_average(const CircularBuffer *cb) {
    if (cb->count == 0) return 0.0f;
    float sum = 0.0f;
    for (int i = 0; i < cb->count; i++) sum += cb->data[i].pressure;
    return sum / (float)cb->count;
}

static int read_calibration_data(void) {
    int rc = i2cReadWordData(i2c_handle, BMP180_REG_CAL_AC1);
    if (rc < 0) return -1;
    ac1 = (int16_t)rc;
    rc = i2cReadWordData(i2c_handle, BMP180_REG_CAL_AC1 + 2);
    if (rc < 0) return -1;
    ac2 = (int16_t)rc;
    rc = i2cReadWordData(i2c_handle, BMP180_REG_CAL_AC1 + 4);
    if (rc < 0) return -1;
    ac3 = (int16_t)rc;
    rc = i2cReadWordData(i2c_handle, BMP180_REG_CAL_AC1 + 6);
    if (rc < 0) return -1;
    ac4 = (uint16_t)rc;
    rc = i2cReadWordData(i2c_handle, BMP180_REG_CAL_AC1 + 8);
    if (rc < 0) return -1;
    ac5 = (uint16_t)rc;
    rc = i2cReadWordData(i2c_handle, BMP180_REG_CAL_AC1 + 10);
    if (rc < 0) return -1;
    ac6 = (uint16_t)rc;
    rc = i2cReadWordData(i2c_handle, BMP180_REG_CAL_AC1 + 12);
    if (rc < 0) return -1;
    b1 = (int16_t)rc;
    rc = i2cReadWordData(i2c_handle, BMP180_REG_CAL_AC1 + 14);
    if (rc < 0) return -1;
    b2 = (int16_t)rc;
    rc = i2cReadWordData(i2c_handle, BMP180_REG_CAL_AC1 + 16);
    if (rc < 0) return -1;
    mb = (int16_t)rc;
    rc = i2cReadWordData(i2c_handle, BMP180_REG_CAL_AC1 + 18);
    if (rc < 0) return -1;
    mc = (int16_t)rc;
    rc = i2cReadWordData(i2c_handle, BMP180_REG_CAL_AC1 + 20);
    if (rc < 0) return -1;
    md = (int16_t)rc;
    return 0;
}

static int read_raw_temperature(int32_t *ut) {
    if (i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, 0x2E) < 0) return -1;
    gpioDelay(5000);
    int msb = i2cReadByteData(i2c_handle, BMP180_REG_MSB);
    if (msb < 0) return -1;
    int lsb = i2cReadByteData(i2c_handle, BMP180_REG_LSB);
    if (lsb < 0) return -1;
    *ut = (msb << 8) | lsb;
    return 0;
}

static int read_raw_pressure(int32_t *up) {
    if (i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, 0x34 + (BMP180_OSS << 6)) < 0) return -1;
    gpioDelay(5000);
    int msb = i2cReadByteData(i2c_handle, BMP180_REG_MSB);
    if (msb < 0) return -1;
    int lsb = i2cReadByteData(i2c_handle, BMP180_REG_LSB);
    if (lsb < 0) return -1;
    int xlsb = i2cReadByteData(i2c_handle, BMP180_REG_XLSB);
    if (xlsb < 0) return -1;
