    x1 = ((int32_t)ac3 * b6) >> 13;
    x2 = ((int32_t)b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    uint32_t b4 = ((uint32_t)ac4 * (uint32_t)(x3 + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)up - b3) * (50000 >> BMP180_OSS);
    int32_t p;
    if (b7 < 0x80000000) p = (b7 * 2) / b4;
    else p = (b7 / b4) * 2;
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p = p + ((x1 + x2 + 3791) >> 4);
    return (float)p;
}

static void timer_callback(void *userdata) {
    (void)userdata;
    int32_t ut, up;
    if (read_raw_temperature(&ut) < 0) {
        fprintf(stderr, "Error: Failed to read raw temperature.\n");
        return;
    }
    if (read_raw_pressure(&up) < 0) {
        fprintf(stderr, "Error: Failed to read raw pressure.\n");
        return;
    }
    float pressure = calculate_pressure(ut, up);
    circular_buffer_add(&buffer, pressure);
    float avg = circular_buffer_average(&buffer);
    if (fabsf(pressure - avg) > ALERT_THRESHOLD_HPA) {
        time_t now = time(NULL);
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", localtime(&now));
        printf("ALERT: Pressure deviation detected at %s. Current: %.2f hPa, Average: %.2f hPa\n", ts, pressure, avg);
        gpioWrite(ALERT_GPIO, 1);
    } else {
        gpioWrite(ALERT_GPIO, 0);
    }
}

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(ALERT_GPIO, 0);
    gpioSetTimerFuncEx(0, 0, NULL, NULL);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at 0x%02X.\n", BMP180_ADDR);
        gpioTerminate();
        return 1;
    }
    if (read_calibration_data() < 0) {
        fprintf(stderr, "Error: Failed to read calibration data. Sensor may be absent or unresponsive.\n");
        cleanup();
        return 1;
    }
    if (gpioSetMode(ALERT_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output.\n", ALERT_GPIO);
        cleanup();
        return 1;
    }
    gpioWrite(ALERT_GPIO, 0);
    circular_buffer_init(&buffer);
    signal(SIGINT, signal_handler);
    if (gpioSetTimerFuncEx(0, SAMPLE_INTERVAL_MS, timer_callback, NULL) < 0) {
        fprintf(stderr, "Error: Failed to set up timer.\n");
        cleanup();
        return 1;
    }
    printf("BMP180 monitoring started. Sampling every %d ms. Press Ctrl+C to exit.\n", SAMPLE_INTERVAL_MS);
    while (!terminate) gpioDelay(100000);
    cleanup();
    printf("Program terminated gracefully.\n");
    return 0;
}

