    if (rc < 0) return -1;
    ac5 = (uint16_t)rc;
    rc = i2cReadWordData(i2c_handle, BMP180_REG_CAL_AC1 + 10);
    if (rc < 0) return -1;
    ac6 = (uint16_t)rc;
    rc = i2cReadWordData(i2c_handle, BMP180_REG_CAL_AC1 + 12);
    if (rc < 0) return -1;
    b1 = (int16_t)rc;
    rc = i2cReadWordData(i2c_handle, BMP180_REG_CAL_AC1 + 14);
    if (rc < 0) return -1;
    b2 = (int16_t)rc;
    rc = i2cReadWordData(i2c_handle, BMP180_REG_CAL_AC1 + 16);
    if (rc < 0) return -1;
    mb = (int16_t)rc;
    rc = i2cReadWordData(i2c_handle, BMP180_REG_CAL_AC1 + 18);
    if (rc < 0) return -1;
    mc = (int16_t)rc;
    rc = i2cReadWordData(i2c_handle, BMP180_REG_CAL_AC1 + 20);
    if (rc < 0) return -1;
    md = (int16_t)rc;
    return 0;
}

static int read_raw_temperature(int32_t *ut) {
    if (i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, 0x2E) < 0) return -1;
    gpioDelay(5000);
    int msb = i2cReadByteData(i2c_handle, BMP180_REG_MSB);
    if (msb < 0) return -1;
    int lsb = i2cReadByteData(i2c_handle, BMP180_REG_LSB);
    if (lsb < 0) return -1;
    *ut = (msb << 8) | lsb;
    return 0;
}

static int read_raw_pressure(int32_t *up) {
    if (i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, 0x34 + (BMP180_OSS << 6)) < 0) return -1;
    gpioDelay(5000);
    int msb = i2cReadByteData(i2c_handle, BMP180_REG_MSB);
    if (msb < 0) return -1;
    int lsb = i2cReadByteData(i2c_handle, BMP180_REG_LSB);
    if (lsb < 0) return -1;
    int xlsb = i2cReadByteData(i2c_handle, BMP180_REG_XLSB);
    if (xlsb < 0) return -1;
    *up = ((msb << 16) | (lsb << 8) | xlsb) >> (8 - BMP180_OSS);
    return 0;
}

static float calculate_pressure(int32_t ut, int32_t up) {
    int32_t x1 = ((ut - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t x2 = ((int32_t)mc << 11) / (x1 + (int32_t)md);
    int32_t b5 = x1 + x2;
    int32_t b6 = b5 - 4000;
    x1 = ((int32_t)b2 * ((b6 * b6) >> 12)) >> 11;
    x2 = ((int32_t)ac2 * b6) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((((int32_t)ac1) * 4 + x3) << BMP180_OSS) + 2) >> 2;
    x1 = ((int32_t)ac3 * b6) >> 13;
    x2 = ((int32_t)b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    uint32_t b4 = ((uint32_t)ac4 * (uint32_t)(x3 + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)up - b3) * (50000 >> BMP180_OSS);
    int32_t p;
    if (b7 < 0x80000000) p = (b7 * 2) / b4;
    else p = (b7 / b4) * 2;
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p = p + ((x1 + x2 + 3791) >> 4);
    return (float)p;
}

static void timer_callback(void *userdata) {
    (void)userdata;
