}

static int i2c_write_reg(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "i2c_write_reg(0x%02X, 0x%02X) failed: %s\n", reg, val, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_regs(int fd, uint8_t reg, uint8_t *dst, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_regs: write reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, dst, len) != (ssize_t)len) {
        fprintf(stderr, "i2c_read_regs: read %zu bytes from 0x%02X failed: %s\n", len, reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int bmp280_init(int fd) {
    uint8_t chip_id;
    if (i2c_read_regs(fd, BMP280_CHIP_ID_REG, &chip_id, 1) < 0) return -1;
    if (chip_id != BMP280_CHIP_ID) {
        fprintf(stderr, "BMP280 chip ID mismatch: got 0x%02X, expected 0x%02X\n", chip_id, BMP280_CHIP_ID);
        return -1;
    }
    if (i2c_write_reg(fd, BMP280_RESET_REG, BMP280_RESET_CMD) < 0) return -1;
