    *dig_P4 = (int32_t)((cal[13] << 8) | cal[12]);
    *dig_P5 = (int32_t)((cal[15] << 8) | cal[14]);
    *dig_P6 = (int32_t)((cal[17] << 8) | cal[16]);
    *dig_P7 = (int32_t)((cal[19] << 8) | cal[18]);
    *dig_P8 = (int32_t)((cal[21] << 8) | cal[20]);
    *dig_P9 = (int32_t)((cal[23] << 8) | cal[22]);
    return 0;
}

static int bmp280_read_raw(int fd, int32_t *raw_t, int32_t *raw_p) {
    uint8_t status;
    for (int i = 0; i < POLL_TIMEOUT_MS; i++) {
        if (i2c_read_regs(fd, BMP280_STATUS_REG, &status, 1) < 0) return -1;
        if ((status & 0x08) == 0) break;
