    var1 = ((var1 * var1 * (int64_t)dig_P4) >> 15) + ((var1 * (int64_t)dig_P5) << 19);
    var1 = var1 + (((int64_t)dig_P6) << 31);
    var1 = var1 >> 17;
    var1 = var1 + (((int64_t)dig_P7) << 23);
    var1 = var1 >> 16;
    var1 = var1 + (((int64_t)dig_P8) << 15);
    var1 = var1 >> 15;
    var1 = var1 + (((int64_t)dig_P9) << 7);
    var1 = var1 >> 8;
    if (var1 == 0) return 0;
    p = 1048576 - adc_P;
