    return (uint32_t)p;
}

static int log_data(float temp_c, float press_hpa) {
    FILE *fp = fopen("weather_data.txt", "a");
    if (!fp) {
        fprintf(stderr, "fopen weather_data.txt failed: %s\n", strerror(errno));
        return -1;
    }
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s, Temperature: %.2f °C, Pressure: %.2f hPa\n", ts, temp_c, press_hpa);
    fclose(fp);
    return 0;
}

int main(void) {
    int fd = -1;
    int addr = BMP280_ADDR_DEFAULT;
    int32_t dig_T1, dig_T2, dig_T3, dig_P1, dig_P2, dig_P3, dig_P4, dig_P5, dig_P6, dig_P7, dig_P8, dig_P9;
    int alt = 0;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    fd = open(BMP280_I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open %s failed: %s\n", BMP280_I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "ioctl I2C_SLAVE 0x%02X failed: %s\n", addr, strerror(errno));
        close(fd);
        return 1;
    }

    if (bmp280_init(fd) < 0) {
        fprintf(stderr, "BMP280 init failed\n");
        close(fd);
        return 1;
    }

    if (bmp280_read_calibration(fd, &dig_T1, &dig_T2, &dig_T3, &dig_P1, &dig_P2, &dig_P3,
                                &dig_P4, &dig_P5, &dig_P6, &dig_P7, &dig_P8, &dig_P9) < 0) {
        fprintf(stderr, "BMP280 calibration read failed\n");
        close(fd);
        return 1;
    }

    while (g_running) {
        if (i2c_write_reg(fd, BMP280_CTRL_MEAS_REG, BMP280_FORCED_MODE | BMP280_TEMP_OSS_1 | BMP280_PRESS_OSS_1) < 0) {
            fprintf(stderr, "ctrl_meas write failed\n");
            break;
        }
        usleep(2000);
        int32_t raw_t, raw_p;
        if (bmp280_read_raw(fd, &raw_t, &raw_p) < 0) {
            fprintf(stderr, "raw read failed\n");
            break;
        }
        int32_t t_centi = compensate_temperature(raw_t, dig_T1, dig_T2, dig_T3);
        uint32_t p_pa = compensate_pressure(raw_p, dig_P1, dig_P2, dig_P3, dig_P4, dig_P5, dig_P6, dig_P7, dig_P8, dig_P9);
        float temp_c = t_centi / 100.0f;
        float press_hpa = p_pa / 100.0f;
        if (log_data(temp_c, press_hpa) < 0) {
            fprintf(stderr, "log failed\n");
        }
        sleep(LOG_INTERVAL_S);
    }

    if (fd >= 0) close(fd);
    return 0;
}

