#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pthread.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define LM75_ADDR      0x48
#define TEMP_REG       0x00
#define GPIO_CHIP       "gpiochip4"
#define LED_PIN         18
#define TEMP_THRESHOLD  28.0f
#define BUFFER_SIZE     60
#define SAMPLE_PERIOD_S 1

typedef struct {
    float buffer[BUFFER_SIZE];
    int   head;
    int   count;
    pthread_mutex_t mutex;
} CircularBuffer;

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *led_line = NULL;
static CircularBuffer temp_buffer = {0};

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_init(void) {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", I2C_BUS, strerror(errno));
        return -1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, LM75_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave 0x%02X: %s\n", LM75_ADDR, strerror(errno));
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, int16_t *out) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *out = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static float read_temperature(void) {
    int16_t raw;
    if (i2c_read_reg16(i2c_fd, TEMP_REG, &raw) < 0) {
        return -273.15f;
    }
    return (float)raw / 256.0f;
}

static void buffer_init(CircularBuffer *cb) {
    memset(cb, 0, sizeof(*cb));
    pthread_mutex_init(&cb->mutex, NULL);
}

static void buffer_add(CircularBuffer *cb, float temp) {
    pthread_mutex_lock(&cb->mutex);
    cb->buffer[cb->head] = temp;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) cb->count++;
    pthread_mutex_unlock(&cb->mutex);
}

static float buffer_average(const CircularBuffer *cb) {
    float sum = 0.0f;
    int n = cb->count;
    if (n == 0) return 0.0f;
    pthread_mutex_lock(&cb->mutex);
    for (int i = 0; i < n; i++) sum += cb->buffer[i];
    pthread_mutex_unlock(&cb->mutex);
    return sum / (float)n;
}

static void cleanup(void) {
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
        led_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    pthread_mutex_destroy(&temp_buffer.mutex);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    buffer_init(&temp_buffer);

    if (i2c_init() < 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        cleanup();
        return 1;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening %s: %s\n", GPIO_CHIP, strerror(errno));
        cleanup();
        return 1;
    }
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", LED_PIN, strerror(errno));
        cleanup();
        return 1;
    }
    if (gpiod_line_request_output(led_line, "lm75-temp", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %s\n", LED_PIN, strerror(errno));
        cleanup();
        return 1;
    }

    printf("LM75 temperature monitor started. Press Ctrl+C to exit.\n");

    while (running) {
        float temp = read_temperature();
        if (temp < -273.0f) {
            fprintf(stderr, "Temperature read failed; attempting re-init.\n");
            i2c_init();
            sleep(1);
            continue;
        }

        buffer_add(&temp_buffer, temp);
        float avg = buffer_average(&temp_buffer);

        pthread_mutex_lock(&temp_buffer.mutex);
        int over = 0;
        for (int i = 0; i < temp_buffer.count; i++) {
            if (temp_buffer.buffer[i] > TEMP_THRESHOLD) over = 1;
        }
        pthread_mutex_unlock(&temp_buffer.mutex);

        int val = gpiod_line_get_value(led_line);
        if (val < 0) {
            fprintf(stderr, "Error reading LED state: %s\n", strerror(errno));
        } else {
            if (over) {
                if (gpiod_line_set_value(led_line, 1) < 0) {
                    fprintf(stderr, "Error setting LED on: %s\n", strerror(errno));
                }
            } else {
                if (gpiod_line_set_value(led_line, 0) < 0) {
                    fprintf(stderr, "Error setting LED off: %s\n", strerror(errno));
                }
            }
        }

        printf("Temperature: %.2f C, Average: %.2f C, LED: %s\n",
               temp, avg, over ? "ON" : "OFF");

        sleep(SAMPLE_PERIOD_S);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

