#define RTD_MAX_RESISTANCE (R_RTD_MAX - R_RTD_MIN) / (RTD_MAX_CODE - RTD_MIN_CODE)
#define RTD_MIN_RESISTANCE (R_RTD_MIN - R_RTD_MAX) / (RTD_MIN_CODE - RTD_MAX_CODE)
#define MAX31865_CONFIG_REG 0x80
#define MAX31865_RTD_MSB_REG 0x01
#define MAX31865_RTD_LSB_REG 0x02
#define MAX31865_FAULT_STATUS_REG 0x07
#define MAX31865_FAULT_OPEN 0x01
#define MAX31865_FAULT_VBIAS 0x02
#define MAX31865_FAULT_OV 0x04
#define MAX31865_FAULT_UV 0x08
#define MAX31865_CONFIG_DEFAULT 0xC1
#define MAX31865_FAULT_D0 0x01

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static double target_temperature = 25.0;
static double Kp = 1.0, Ki = 0.1, Kd = 0.01;
static double integral = 0.0, previous_error = 0.0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_write_byte(uint8_t reg, uint8_t value) {
    char tx[2] = { (char)reg, (char)value };
    char rx[2] = {0};
    if (spiXfer(spi_handle, tx, rx, 2) != 2) return -1;
    return 0;
}

static int spi_read_byte(uint8_t reg, uint8_t *value) {
    char tx[2] = { (char)reg, 0x00 };
    char rx[2] = {0};
    if (spiXfer(spi_handle, tx, rx, 2) != 2) return -1;
    *value = (uint8_t)rx[1];
    return 0;
}

static int read_rtd_code(uint16_t *code) {
    uint8_t msb, lsb;
    if (spi_read_byte(MAX31865_RTD_MSB_REG, &msb) != 0) return -1;
    if (spi_read_byte(MAX31865_RTD_LSB_REG, &lsb) != 0) return -1;
    *code = ((uint16_t)msb << 8) | lsb;
    if (*code & MAX31865_FAULT_D0) return -1;
    return 0;
}

static int read_max31865_fault(uint8_t *fault) {
    uint8_t status;
    if (spi_read_byte(MAX31865_FAULT_STATUS_REG, &status) != 0) return -1;
    *fault = status;
    return 0;
}

static double rtd_to_temperature(uint16_t rtd_code) {
    double rtd_resistance = (double)rtd_code / 32768.0 * R_REF;
    if (rtd_resistance < R_RTD_MIN_RESISTANCE || rtd_resistance > R_RTD_MAX_RESISTANCE) {
        fprintf(stderr, "Warning: RTD resistance out of range (%.2f ohms)\n", rtd_resistance);
        return -1.0;
    }
    double t = (log(rtd_resistance / R0) - A * 0.5) / (B * 0.5);
    if (t < 0.0) t = 0.0;
    return t;
}

static double pid_control(double current_temperature) {
    double error = target_temperature - current_temperature;
    integral += error;
    double derivative = error - previous_error;
    double output = Kp * error + Ki * integral + Kd * derivative;
    previous_error = error;
    if (output < 0.0) output = 0.0;
    if (output > 100.0) output = 100.0;
    return output;
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spi_write_byte(MAX31865_CONFIG_REG, MAX31865_CONFIG_DEFAULT);
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioPWM(GPIO_HEATER, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(GPIO_HEATER, PI_OUTPUT);
    gpioSetPWMfrequency(GPIO_HEATER, PWM_FREQ);
    gpioSetPWMrange(GPIO_HEATER, PWM_RANGE);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    if (spi_write_byte(MAX31865_CONFIG_REG, MAX31865_CONFIG_DEFAULT) != 0) {
        fprintf(stderr, "Error: Failed to configure MAX31865\n");
        cleanup();
        return 1;
    }

    FILE *fp = fopen(CONFIG_FILE, "r");
    if (fp == NULL) {
        fprintf(stderr, "Warning: Config file not found, using defaults\n");
    } else {
        if (fscanf(fp, "%lf,%lf,%lf", &target_temperature, &Kp, &Ki) != 3) {
            fprintf(stderr, "Warning: Invalid config, using defaults\n");
        } else {
            printf("Loaded config: target=%.2f°C, Kp=%.2f, Ki=%.2f, Kd=%.2f\n",
                   target_temperature, Kp, Ki, Kd);
        }
        fclose(fp);
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Starting temperature regulation. Target: %.2f°C\n", target_temperature);

    while (running) {
        uint16_t rtd_code;
        uint8_t fault = 0;

        if (read_rtd_code(&rtd_code) != 0) {
            fprintf(stderr, "Error: SPI read failed (sensor disconnected or bus error)\n");
            gpioPWM(GPIO_HEATER, 0);
            cleanup();
            return 1;
        }

        if (read_max31865_fault(&fault) != 0) {
            fprintf(stderr, "Error: Failed to read fault status\n");
            gpioPWM(GPIO_HEATER, 0);
            cleanup();
            return 1;
        }

        if (fault & MAX31865_FAULT_OPEN) {
            fprintf(stderr, "Error: MAX31865 open fault (RTD disconnected or wiring fault)\n");
            gpioPWM(GPIO_HEATER, 0);
            cleanup();
            return 1;
        }
        if (fault & MAX31865_FAULT_VBIAS) {
            fprintf(stderr, "Error: MAX31865 VBIAS fault (internal power supply issue)\n");
            gpioPWM(GPIO_HEATER, 0);
            cleanup();
            return 1;
        }
        if (fault & MAX31865_FAULT_OV) {
            fprintf(stderr, "Error: MAX31865 over-voltage fault\n");
            gpioPWM(GPIO_HEATER, 0);
            cleanup();
            return 1;
        }
        if (fault & MAX31865_FAULT_UV) {
            fprintf(stderr, "Error: MAX31865 under-voltage fault\n");
            gpioPWM(GPIO_HEATER, 0);
            cleanup();
            return 1;
        }

        double current_temperature = rtd_to_temperature(rtd_code);
        if (current_temperature < 0.0) {
            fprintf(stderr, "Error: Invalid temperature reading\n");
            gpioPWM(GPIO_HEATER, 0);
            cleanup();
            return 1;
        }

        double pwm_duty = pid_control(current_temperature);
        gpioPWM(GPIO_HEATER, (int)(pwm_duty * PWM_RANGE));

        if (current_temperature > MAX_TEMP) {
            fprintf(stderr, "Warning: Temperature %.2f°C exceeds limit %.2f°C, shutting down heater\n",
                    current_temperature, MAX_TEMP);
            gpioPWM(GPIO_HEATER, 0);
            cleanup();
            return 1;
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    gpioPWM(GPIO_HEATER, 0);
    cleanup();
    return 0;
}

