#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define BMP180_ADDR 0x77
#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "breach_log.txt"
#define SAMPLE_INTERVAL_SEC 1
#define MAX_RETRIES 3

#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8
#define BMP180_REG_CAL_AC1 0xAA

#define TEMP_THRESHOLD 30.0f
#define PRESSURE_THRESHOLD 950.0f

typedef struct {
    int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
    uint16_t ac4, ac5, ac6;
} bmp180_cal_t;

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_fp = NULL;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    for (int i = 0; i < MAX_RETRIES; i++) {
        if (write(i2c_fd, buf, 2) == 2) return 0;
        usleep(10000);
    }
    return -1;
}

static int i2c_read_bytes(uint8_t reg, uint8_t *buf, int len) {
    for (int i = 0; i < MAX_RETRIES; i++) {
        if (write(i2c_fd, &reg, 1) == 1) {
            if (read(i2c_fd, buf, len) == len) return 0;
        }
        usleep(10000);
    }
    return -1;
}

static int read_calibration(bmp180_cal_t *cal) {
    uint8_t buf[22];
    if (i2c_read_bytes(BMP180_REG_CAL_AC1, buf, 22) != 0) return -1;
    cal->ac1 = (int16_t)((buf[0] << 8) | buf[1]);
    cal->ac2 = (int16_t)((buf[2] << 8) | buf[3]);
    cal->ac3 = (int16_t)((buf[4] << 8) | buf[5]);
    cal->ac4 = (uint16_t)((buf[6] << 8) | buf[7]);
    cal->ac5 = (uint16_t)((buf[8] << 8) | buf[9]);
    cal->ac6 = (uint16_t)((buf[10] << 8) | buf[11]);
    cal->b1 = (int16_t)((buf[12] << 8) | buf[13]);
    cal->b2 = (int16_t)((buf[14] << 8) | buf[15]);
    cal->mb = (int16_t)((buf[16] << 8) | buf[17]);
    cal->mc = (int16_t)((buf[18] << 8) | buf[19]);
    cal->md = (int16_t)((buf[20] << 8) | buf[21]);
    return 0;
}

static int read_raw_temp(int32_t *ut) {
    if (i2c_write_byte(BMP180_REG_CONTROL, 0x2E) != 0) return -1;
    usleep(5000);
    uint8_t buf[2];
    if (i2c_read_bytes(BMP180_REG_MSB, buf, 2) != 0) return -1;
    *ut = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int read_raw_pressure(int32_t *up) {
    if (i2c_write_byte(BMP180_REG_CONTROL, 0x34) != 0) return -1;
    usleep(5000);
    uint8_t buf[3];
    if (i2c_read_bytes(BMP180_REG_MSB, buf, 3) != 0) return -1;
    *up = ((int16_t)buf[0] << 16 | (int16_t)buf[1] << 8 | buf[2]) >> 8;
    return 0;
}

static int32_t compute_b5(int32_t ut, const bmp180_cal_t *c) {
    int32_t x1 = ((ut - (int32_t)c->ac6) * (int32_t)c->ac5) >> 15;
    int32_t x2 = ((int32_t)c->mc << 11) / (x1 + (int32_t)c->md);
    return x1 + x2;
}

static float calc_temp(int32_t ut, const bmp180_cal_t *c) {
    int32_t b5 = compute_b5(ut, c);
    return ((b5 + 8) >> 4) / 10.0f;
}

static float calc_pressure(int32_t up, int32_t ut, const bmp180_cal_t *c) {
    int32_t b5 = compute_b5(ut, c);
    int32_t b6 = b5 - 4000;
    int32_t x1 = ((int32_t)c->b2 * ((b6 * b6) >> 12)) >> 11;
    int32_t x2 = ((int32_t)c->ac2 * b6) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((((int32_t)c->ac1 * 4 + x3) << 0) + 2) >> 2);
    uint32_t b4 = ((uint32_t)c->ac4 * (uint32_t)(x3 + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)up - b3) * (uint32_t)(50000UL >> 0);
    int32_t p;
    if (b7 < 0x80000000UL) p = (b7 * 2) / b4;
    else p = (b7 / b4) * 2;
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p += (x1 + x2 + 3791) >> 4;
    return (float)p / 100.0f;
}

static void log_breach(float temp, float press) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(log_fp, "%s - Temp: %.2f C, Pressure: %.2f hPa - BREACH\n", ts, temp, press);
    fflush(log_fp);
}

int main(void) {
    struct sigaction sa = {0};
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "open(%s): %s\n", I2C_BUS, strerror(errno));
        return 1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, BMP180_ADDR) < 0) {
        fprintf(stderr, "ioctl I2C_SLAVE 0x%02X: %s\n", BMP180_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    bmp180_cal_t cal;
    if (read_calibration(&cal) != 0) {
        fprintf(stderr, "Failed to read BMP180 calibration data\n");
        close(i2c_fd);
        return 1;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "fopen(%s): %s\n", LOG_FILE, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    printf("BMP180 monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int32_t ut, up;
        if (read_raw_temp(&ut) != 0 || read_raw_pressure(&up) != 0) {
            fprintf(stderr, "I2C read error: %s\n", strerror(errno));
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }

        float temp = calc_temp(ut, &cal);
        float press = calc_pressure(up, ut, &cal);

        if (temp > TEMP_THRESHOLD || press < PRESSURE_THRESHOLD) {
            log_breach(temp, press);
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nShutting down...\n");
    if (log_fp) fclose(log_fp);
    if (i2c_fd >= 0) close(i2c_fd);
    return 0;
}

