#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define BMP180_ADDR             0x77
#define BMP180_REG_CALIB        0xAA
#define BMP180_REG_CONTROL      0xF4
#define BMP180_REG_DATA         0xF6
#define BMP180_REG_TEMP        0xF6
#define BMP180_REG_PRESSURE    0xF6
#define BMP180_OSS             0
#define FAN_GPIO                18
#define BUFFER_SIZE             60
#define SAMPLE_INTERVAL_US      500000
#define TEMP_THRESHOLD          30.0f
#define I2C_BUS                 1

typedef struct {
    time_t timestamp;
    float  temperature;
    float  pressure;
} Reading;

static Reading buffer[BUFFER_SIZE];
static int   buffer_index = 0;
static int   buffer_count = 0;
static volatile sig_atomic_t running = 1;
static int   i2c_handle = -1;

static int16_t  ac1, ac2, ac3, b1, b2, mb, mc, md;
static uint16_t ac4, ac5, ac6;

static void timer_callback(void *user_data) {
    (void)user_data;
    if (!running) return;

    char buf[2];
    int rc;

    /* --- Read uncompensated temperature (UT) --- */
    buf[0] = BMP180_REG_CONTROL;
    buf[1] = 0x2E;  /* temp measurement, no wait */
    rc = i2cWriteDevice(i2c_handle, buf, 2);
