#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define HEATER_GPIO 17
#define SPI_CHANNEL 0
#define SPI_SPEED 2000000
#define PWM_RANGE 1000
#define PWM_FREQ 1000
#define MAX_DUTY_CYCLE 800
#define LOG_FILE "heater_log.csv"
#define SAMPLE_INTERVAL_US 1000000

#define MAX31855_FAULT_OPEN 0x01
#define MAX31855_FAULT_GND  0x02
#define MAX31855_FAULT_VCC  0x04

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_max31855(int handle, float *temperature) {
    unsigned char tx[4] = {0x00, 0x00, 0x00, 0x00};
    unsigned char rx[4] = {0};

    if (spiXfer(handle, (char *)tx, (char *)rx, 4) != 4) {
        return -1;
    }

    if (rx[0] & 0x01) {
        return MAX31855_FAULT_OPEN;
    }
    if (rx[0] & 0x02) {
        return MAX31855_FAULT_GND;
    }
    if (rx[0] & 0x04) {
        return MAX31855_FAULT_VCC;
    }

    int16_t raw = (rx[2] << 8) | rx[3];
    *temperature = (float)raw * 0.25f;
    return 0;
}

static int set_heater_pwm(int gpio, int duty_cycle) {
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > MAX_DUTY_CYCLE) duty_cycle = MAX_DUTY_CYCLE;
    if (gpioPWM(gpio, duty_cycle) != 0) {
        fprintf(stderr, "Error: gpioPWM failed on GPIO %d\n", gpio);
        return -1;
    }
    return 0;
}

static void log_data(float temperature, int duty_cycle) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%d\n", ts, temperature, duty_cycle);
    fflush(log_file);
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(HEATER_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(HEATER_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(HEATER_GPIO, PWM_FREQ);
    gpioSetPWMrange(HEATER_GPIO, PWM_RANGE);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error: cannot open log file %s\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    float target_temperature = 25.0f;
    float integral = 0.0f;
    float prev_error = 0.0f;

    while (running) {
        float temperature = 0.0f;
        int rc = read_max31855(spi_handle, &temperature);

        if (rc != 0) {
            fprintf(stderr, "MAX31855 fault detected: %d\n", rc);
            set_heater_pwm(HEATER_GPIO, 0);
            log_data(temperature, 0);
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        float error = target_temperature - temperature;
        integral += error;
        float derivative = error - prev_error;
        float output = integral + 0.1f * derivative;

        if (output < 0.0f) output = 0.0f;
        if (output > MAX_DUTY_CYCLE) output = MAX_DUTY_CYCLE;

        set_heater_pwm(HEATER_GPIO, (int)output);
        log_data(temperature, (int)output);

        prev_error = error;
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return 0;
}

