#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define RED_PIN   17
#define GREEN_PIN 18
#define BLUE_PIN  27

#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define PWM_RANGE 255
#define PWM_FREQ 1000

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int read_cpu_temp(void)
{
    FILE *fp = fopen(TEMP_FILE, "r");
    if (!fp) {
        perror("fopen temperature file");
        return -1;
    }

    int temp_milliC;
    if (fscanf(fp, "%d", &temp_milliC) != 1) {
        fprintf(stderr, "fscanf temperature failed\n");
        fclose(fp);
        return -1;
    }

    if (ferror(fp)) {
        fprintf(stderr, "temperature read error\n");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return temp_milliC;
}

static void set_rgb(int r, int g, int b)
{
    /* Common-anode: 0 duty = fully on, 255 duty = fully off.
       Invert the desired brightness so that duty 0 = full brightness,
       duty 255 = full off. */
    gpioPWM(RED_PIN,   PWM_RANGE - r);
    gpioPWM(GREEN_PIN, PWM_RANGE - g);
    gpioPWM(BLUE_PIN,  PWM_RANGE - b);
}

static void cleanup(void)
{
    /* Turn off all three channels (common-anode: duty 255 = off). */
    gpioPWM(RED_PIN,   PWM_RANGE);
    gpioPWM(GREEN_PIN, PWM_RANGE);
    gpioPWM(BLUE_PIN,  PWM_RANGE);
    gpioTerminate();
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Set PWM frequency for all three channels. */
    gpioSetPWMfrequency(RED_PIN,   PWM_FREQ);
    gpioSetPWMfrequency(GREEN_PIN, PWM_FREQ);
    gpioSetPWMfrequency(BLUE_PIN,  PWM_FREQ);

    /* Set PWM range to 0-255 for all three channels. */
    gpioSetPWMrange(RED_PIN,   PWM_RANGE);
    gpioSetPWMrange(GREEN_PIN, PWM_RANGE);
    gpioSetPWMrange(BLUE_PIN,  PWM_RANGE);

    /* Ensure all channels start off (common-anode: duty 255 = off). */
    gpioPWM(RED_PIN,   PWM_RANGE);
    gpioPWM(GREEN_PIN, PWM_RANGE);
    gpioPWM(BLUE_PIN,  PWM_RANGE);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction SIGINT");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction SIGTERM");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Mood light started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int temp_milliC = read_cpu_temp();
        if (temp_milliC < 0) {
            fprintf(stderr, "Temperature read failed; skipping cycle.\n");
        } else {
            printf("CPU temperature: %d m°C\n", temp_milliC);

            if (temp_milliC < 40000) {
                set_rgb(0, 0, 255);
                printf("RGB: Blue\n");
            } else if (temp_milliC < 60000) {
                set_rgb(0, 255, 0);
                printf("RGB: Green\n");
            } else {
                set_rgb(255, 0, 0);
                printf("RGB: Red\n");
            }
        }

        time_sleep(0.5);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

