#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <curl/curl.h>

#define DHT22_GPIO 4
#define SERVER_URL "http://yourserver.com/api/humidity"
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 1000
#define DHT22_START_LOW_US 1000
#define DHT22_START_HIGH_US 30
#define DHT22_TIMEOUT_US 100000
#define DHT22_BIT_THRESHOLD 50

typedef struct {
    float temperature;
    float humidity;
    int error;
} DHT22Data;

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
