        .tv_nsec = (us % 1000000) * 1000
    };
    nanosleep(&ts, NULL);
}

static int wait_for_level(int gpio, int level, unsigned int timeout_us) {
    unsigned int elapsed = 0;
    while (gpioRead(gpio) != level) {
        if (elapsed >= timeout_us) return -1;
        sleep_us(1);
        elapsed++;
    }
    return 0;
}

