    gpioWrite(DHT22_GPIO, 1);
    sleep_us(DHT22_START_HIGH_US);

    gpioSetMode(DHT22_GPIO, PI_INPUT);

    if (wait_for_level(DHT22_GPIO, 0, DHT22_TIMEOUT_US) != 0) {
        fprintf(stderr, "DHT22: Timeout waiting for sensor response low\n");
        return -1;
    }
    if (wait_for_level(DHT22_GPIO, 1, DHT22_TIMEOUT_US) != 0) {
