#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <math.h>

#define BMP180_ADDR 0x77
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_DATA 0xF6
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8
#define BMP180_OSS 3
#define DEBOUNCE_US 200000
#define SAMPLE_INTERVAL_US 2000000
#define LOG_FILE "pressure_log.txt"

static volatile sig_atomic_t running = 1;
static volatile sig_atomic_t logging_enabled = 0;
static int i2c_handle = -1;

static int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
static uint16_t ac4, ac5, ac6;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_calibration_data(void) {
    char buf[22];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_CAL_AC1, buf, 22) != 22) {
        fprintf(stderr, "Error: Failed to read BMP180 calibration data\n");
        return -1;
    }
    ac1 = (int16_t)((buf[0] << 8) | buf[1]);
    ac2 = (int16_t)((buf[2] << 8) | buf[3]);
    ac3 = (int16_t)((buf[4] << 8) | buf[5]);
    ac4 = (uint16_t)((buf[6] << 8) | buf[7]);
    ac5 = (uint16_t)((buf[8] << 8) | buf[9]);
    ac6 = (uint16_t)((buf[10] << 8) | buf[11]);
    b1  = (int16_t)((buf[12] << 8) | buf[13]);
    b2  = (int16_t)((buf[14] << 8) | buf[15]);
    mb  = (int16_t)((buf[16] << 8) | buf[17]);
    mc  = (int16_t)((buf[18] << 8) | buf[19]);
    md  = (int16_t)((buf[20] << 8) | buf[21]);
    if (ac1 == 0 && ac2 == 0 && ac3 == 0 && ac4 == 0 && ac5 == 0 && ac6 == 0) {
        fprintf(stderr, "Error: BMP180 calibration data is all zeros - sensor not present?\n");
        return -1;
    }
    return 0;
}

static int read_raw_temperature(int32_t *ut) {
    char buf[2];
    buf[0] = BMP180_REG_CONTROL;
    buf[1] = 0x2E;
    if (i2cWriteI2CBlockData(i2c_handle, BMP180_REG_CONTROL, buf, 1) != 0) {
        fprintf(stderr, "Error: Failed to write temperature command\n");
        return -1;
    }
    gpioDelay(5000);
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_DATA, buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to read raw temperature\n");
        return -1;
    }
    *ut = (int32_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int read_raw_pressure(int32_t *up) {
    char buf[3];
    buf[0] = BMP180_REG_CONTROL;
    buf[1] = 0x34 + (BMP180_OSS << 6);
    if (i2cWriteI2CBlockData(i2c_handle, BMP180_REG_CONTROL, buf, 1) != 0) {
        fprintf(stderr, "Error: Failed to write pressure command\n");
        return -1;
    }
    gpioDelay(26000);
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, buf, 3) != 3) {
        fprintf(stderr, "Error: Failed to read raw pressure\n");
        return -1;
    }
    *up = ((int32_t)buf[0] << 16 | (int32_t)buf[1] << 8 | (int32_t)buf[2]) >> (8 - BMP180_OSS);
    return 0;
}

static int32_t compute_b5(int32_t ut) {
    int32_t x1 = ((ut - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t x2 = ((int32_t)mc << 11) / (x1 + (int32_t)md);
    return x1 + x2;
}

static double calculate_pressure(int32_t up, int32_t b5) {
    int32_t b6 = b5 - 4000;
    int32_t x1 = ((int32_t)b2 * ((b6 * b6) >> 12)) >> 11;
    int32_t x2 = ((int32_t)ac2 * b6) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((((int32_t)ac1) * 4 + x3) << BMP180_OSS) + 2) >> 2;
    x1 = ((int32_t)ac3 * b6) >> 13;
    x2 = ((int32_t)b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    uint32_t b4 = ((uint32_t)ac4 * (uint32_t)(x3 + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)up - b3) * (50000 >> BMP180_OSS);
    int32_t p;
    if (b7 < 0x80000000) {
        p = (b7 * 2) / b4;
    } else {
        p = (b7 / b4) * 2;
    }
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p = p + ((x1 + x2 + 3791) >> 4);
    return (double)p / 100.0;
}

static void log_pressure(double pressure) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error: Could not open log file %s\n", LOG_FILE);
        return;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s, %.2f hPa\n", timestamp, pressure);
    fclose(fp);
}

static void button_interrupt_handler(int gpio, int level, uint32_t tick, void *user_data) {
    (void)gpio; (void)level; (void)user_data;
    static uint32_t last_tick = 0;
    if (tick - last_tick > DEBOUNCE_US) {
        logging_enabled = !logging_enabled;
        printf("Logging %s\n", logging_enabled ? "enabled" : "disabled");
        last_tick = tick;
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C device at 0x%02X\n", BMP180_ADDR);
        gpioTerminate();
        return 1;
    }
    if (read_calibration_data() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    gpioSetMode(4, PI_INPUT);
    gpioSetPullUpDown(4, PI_PUD_UP);
    if (gpioSetISRFuncEx(4, FALLING_EDGE, 0, button_interrupt_handler, NULL) != 0) {
        fprintf(stderr, "Error: Could not set ISR on GPIO4\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    signal(SIGINT, signal_handler);
    printf("BMP180 pressure logger started. Press button on GPIO4 to toggle logging.\n");
    while (running) {
        if (logging_enabled) {
            int32_t ut, up;
            if (read_raw_temperature(&ut) == 0 && read_raw_pressure(&up) == 0) {
                int32_t b5 = compute_b5(ut);
                double pressure = calculate_pressure(up, b5);
                log_pressure(pressure);
            } else {
                fprintf(stderr, "Warning: Sensor read failed, skipping log entry\n");
            }
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }
    printf("\nShutting down...\n");
    gpioSetISRFuncEx(4, FALLING_EDGE, 0, NULL, NULL);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

