#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <getopt.h>
#include <time.h>
#include <pigpio.h>
#include <curl/curl.h>

#define DHT22_PIN 4
#define MAX_RETRIES 3
#define READ_INTERVAL 10
#define DHT22_START_LOW_US 1000
#define DHT22_START_HIGH_US 30
#define DHT22_TIMEOUT_US 1000
#define DHT22_BIT_THRESHOLD 50
#define DHT22_MAX_BITS 85

typedef struct {
    float humidity;
    int error;
} DHT22Data;

static volatile sig_atomic_t running = 1;
static char *server_url = "http://your-server.com/api/humidity";

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_dht22(DHT22Data *data) {
    int bits[5] = {0, 0, 0, 0, 0};
    int i, j;
    uint32_t start, end, duration;
    int last_state = 1;
    int state;

    for (i = 0; i < 5; i++) {
        bits[i] = 0;
    }

    gpioSetMode(DHT22_PIN, PI_OUTPUT);
    gpioWrite(DHT22_PIN, 0);
    gpioDelay(DHT22_START_LOW_US);
    gpioWrite(DHT22_PIN, 1);
    gpioDelay(DHT22_START_HIGH_US);
    gpioSetMode(DHT22_PIN, PI_INPUT);

    for (i = 0; i < DHT22_TIMEOUT_US; i++) {
        start = gpioTick();
        if (gpioRead(DHT22_PIN) != last_state) {
            break;
        }
        if (i == DHT22_TIMEOUT_US - 1) {
            syslog(LOG_ERR, "DHT22: timeout waiting for response");
            return -1;
        }
    }

    for (i = 0; i < DHT22_TIMEOUT_US; i++) {
        start = gpioTick();
        if (gpioRead(DHT22_PIN) != 0) {
            break;
        }
        if (i == DHT22_TIMEOUT_US - 1) {
            syslog(LOG_ERR, "DHT22: timeout waiting for bit 0 low");
            return -1;
        }
    }

    for (i = 0; i < DHT22_MAX_BITS; i++) {
        for (j = 0; j < DHT22_TIMEOUT_US; j++) {
            start = gpioTick();
            if (gpioRead(DHT22_PIN) != 1) {
                break;
            }
            if (j == DHT22_TIMEOUT_US - 1) {
                syslog(LOG_ERR, "DHT22: timeout waiting for bit %d high", i);
                return -1;
            }
        }
        end = gpioTick();
        duration = end - start;

        for (j = 0; j < DHT22_TIMEOUT_US; j++) {
            start = gpioTick();
            if (gpioRead(DHT22_PIN) != 0) {
                break;
            }
            if (j == DHT22_TIMEOUT_US - 1) {
                syslog(LOG_ERR, "DHT22: timeout waiting for bit %d low", i);
                return -1;
            }
        }

        bits[i / 8] |= (duration > DHT22_BIT_THRESHOLD ? 1 : 0);
    }

    if (bits[4] != ((bits[0] + bits[1] + bits[2] + bits[3]) & 0xFF)) {
        syslog(LOG_ERR, "DHT22: checksum error");
        return -1;
    }

    data->humidity = (float)((bits[0] << 8) | bits[1]) / 10.0f;
    data->error = 0;
    return 0;
}

static int post_humidity(float humidity) {
    CURL *curl;
    CURLcode res;
    char json_string[64];
    int ret = -1;

    snprintf(json_string, sizeof(json_string), "{\"humidity\":%.2f}", humidity);

    curl_global_init(CURL_GLOBAL_ALL);
    curl = curl_easy_init();
    if (!curl) {
        syslog(LOG_ERR, "curl_easy_init() failed");
        curl_global_cleanup();
        return -1;
    }

    curl_easy_setopt(curl, CURLOPT_URL, server_url);
    curl_easy_setopt(curl, CURLOPT_POST, 1L);
    curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_string);
    curl_easy_setopt(curl, CURLOPT_POSTFIELDSIZE, (long)strlen(json_string));
    curl_easy_setopt(curl, CURLOPT_HTTPHEADER, NULL);
    curl_easy_setopt(curl, CURLOPT_TIMEOUT, 10L);
    curl_easy_setopt(curl, CURLOPT_CONNECTTIMEOUT, 5L);

    res = curl_easy_perform(curl);
    if (res != CURLE_OK) {
        syslog(LOG_ERR, "curl_easy_perform() failed: %s", curl_easy_strerror(res));
    } else {
        long http_code = 0;
        curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &http_code);
        if (http_code >= 200 && http_code < 300) {
            syslog(LOG_INFO, "POST successful, HTTP %ld", http_code);
            ret = 0;
        } else {
            syslog(LOG_ERR, "HTTP %ld", http_code);
        }
    }

    curl_easy_cleanup(curl);
    curl_global_cleanup();
    return ret;
}

int main(int argc, char *argv[]) {
    int opt;
    int retry_count = 0;

    openlog("humidity_monitor", LOG_PID | LOG_CONS, LOG_USER);

    while ((opt = getopt(argc, argv, "s:")) != -1) {
        switch (opt) {
            case 's':
                server_url = optarg;
                break;
            default:
                fprintf(stderr, "Usage: %s [-s <url>]\n", argv[0]);
                closelog();
                return EXIT_FAILURE;
        }
    }

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    syslog(LOG_INFO, "Starting humidity monitoring on BCM GPIO %d", DHT22_PIN);

    while (running) {
        DHT22Data dht22_data;
        int read_result = -1;

        while (read_result != 0 && retry_count < MAX_RETRIES) {
            read_result = read_dht22(&dht22_data);
            if (read_result != 0) {
                syslog(LOG_ERR, "DHT22 read failed, retry %d/%d", retry_count + 1, MAX_RETRIES);
                retry_count++;
                if (retry_count < MAX_RETRIES) {
                    sleep(2);
                }
            }
        }

        if (read_result == 0) {
            retry_count = 0;
            if (post_humidity(dht22_data.humidity) != 0) {
                syslog(LOG_ERR, "Failed to post humidity data");
            } else {
                syslog(LOG_INFO, "Humidity: %.2f%%", dht22_data.humidity);
            }
        } else {
            syslog(LOG_ERR, "Failed to read humidity after %d retries", MAX_RETRIES);
        }

        for (int i = 0; i < READ_INTERVAL && running; i++) {
            sleep(1);
        }
    }

    syslog(LOG_INFO, "Shutting down");
    gpioTerminate();
    closelog();
    return EXIT_SUCCESS;
}

