#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>

#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define FAN_STATE_FILE "/sys/class/thermal/cooling_device0/cur_state"
#define LOG_FILE "/var/log/fan_control.log"
#define POLL_INTERVAL_SEC 5

#define TEMP_MIN 45
#define TEMP_MID 55
#define TEMP_HIGH 65

#define MAX_STATE 3

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    } else {
        fprintf(fp, "[timestamp error] %s\n", message);
    }
    fclose(fp);
    return 0;
}

static int read_temperature(void) {
    FILE *fp = fopen(TEMP_FILE, "r");
    if (!fp) {
        fprintf(stderr, "Error opening temperature file %s: %s\n", TEMP_FILE, strerror(errno));
        return -1;
    }
    int temp = -1;
    if (fscanf(fp, "%d", &temp) != 1) {
        fprintf(stderr, "Error reading temperature from %s\n", TEMP_FILE);
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return temp;
}

static int set_fan_state(int state) {
    FILE *fp = fopen(FAN_STATE_FILE, "w");
    if (!fp) {
        fprintf(stderr, "Error opening fan state file %s: %s\n", FAN_STATE_FILE, strerror(errno));
        return -1;
    }
    if (fprintf(fp, "%d", state) < 0) {
        fprintf(stderr, "Error writing fan state to %s\n", FAN_STATE_FILE);
        fclose(fp);
        return -1;
    }
    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing fan state file %s: %s\n", FAN_STATE_FILE, strerror(errno));
        return -1;
    }
    return 0;
}

static int validate_max_state(void) {
    FILE *fp = fopen(FAN_STATE_FILE, "r");
    if (!fp) {
        fprintf(stderr, "Error opening fan state file %s for max-state check: %s\n", FAN_STATE_FILE, strerror(errno));
        return -1;
    }
    int max_state = -1;
    if (fscanf(fp, "%d", &max_state) != 1) {
        fprintf(stderr, "Error reading max_state from %s\n", FAN_STATE_FILE);
        fclose(fp);
        return -1;
    }
    fclose(fp);
    if (max_state < 0 || max_state > MAX_STATE) {
        fprintf(stderr, "Invalid max_state value: %d (must be 0-%d)\n", max_state, MAX_STATE);
        return -1;
    }
    return max_state;
}

static int determine_fan_speed(int temperature) {
    if (temperature < TEMP_MIN) return 0;
    if (temperature < TEMP_MID) return 1;
    if (temperature < TEMP_HIGH) return 2;
    return 3;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    int max_state = validate_max_state();
    if (max_state < 0) {
        fprintf(stderr, "Failed to validate max_state. Exiting.\n");
        return EXIT_FAILURE;
    }
    if (max_state > MAX_STATE) {
        fprintf(stderr, "Invalid max_state: %d. Exiting.\n", max_state);
        return EXIT_FAILURE;
    }

    int current_state = 0;
    if (set_fan_state(current_state) != 0) {
        fprintf(stderr, "Failed to set initial fan state.\n");
        return EXIT_FAILURE;
    }
    log_event("Fan control service started. Initial state: 0");

    while (running) {
        int temperature = read_temperature();
        if (temperature < 0) {
            fprintf(stderr, "Failed to read temperature. Retrying in %d seconds.\n", POLL_INTERVAL_SEC);
            sleep(POLL_INTERVAL_SEC);
            continue;
        }

        int new_state = determine_fan_speed(temperature);
