            sleep(POLL_INTERVAL_SEC);
            continue;
        }

        if (set_fan_state(new_state) != 0) {
            fprintf(stderr, "Failed to set fan state to %d.\n", new_state);
            sleep(POLL_INTERVAL_SEC);
            continue;
        }
        current_state = new_state;
        log_event("Fan speed changed to state: " + (new_state + 1));

        sleep(POLL_INTERVAL_SEC);
    }

    if (set_fan_state(0) != 0) {
        fprintf(stderr, "Failed to set fan to stop during shutdown.\n");
    }
    log_event("Fan control service shutting down. Fan stopped.");
    return EXIT_SUCCESS;
}

