#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define HEATER_GPIO 18
#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define PWM_FREQUENCY 1000
#define PWM_RANGE 100
#define LOG_FILE "heater_log.txt"

#define MAX31855_FAULT_OPEN 0x01
#define MAX31855_FAULT_GND  0x02
#define MAX31855_FAULT_VCC  0x04

#define KP 1.0
#define KI 0.1
#define KD 0.01
#define TARGET_TEMP 50.0
#define MAX_TEMP 100.0
#define MIN_TEMP 0.0

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static FILE *log_file = NULL;

static double integral = 0.0;
static double previous_error = 0.0;
static int pigpio_initialized = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (pigpio_initialized) {
        gpioPWM(HEATER_GPIO, 0);
        gpioTerminate();
        pigpio_initialized = 0;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

static int read_max31855(int handle, double *temperature) {
    char rx[4] = {0, 0, 0, 0};
    int bytes = spiRead(handle, rx, 4);
    if (bytes != 4) {
        fprintf(stderr, "SPI read error: expected 4 bytes, got %d\n", bytes);
        return -1;
    }

    uint32_t raw = ((uint32_t)(uint8_t)rx[0] << 24) |
                   ((uint32_t)(uint8_t)rx[1] << 16) |
                   ((uint32_t)(uint8_t)rx[2] << 8)  |
                   ((uint32_t)(uint8_t)rx[3]);

    if (raw & 0x00010000) {
        uint8_t faults = raw & 0x07;
        if (faults & MAX31855_FAULT_OPEN) fprintf(stderr, "MAX31855 fault: open circuit\n");
        if (faults & MAX31855_FAULT_GND)  fprintf(stderr, "MAX31855 fault: short to GND\n");
        if (faults & MAX31855_FAULT_VCC)  fprintf(stderr, "MAX31855 fault: short to VCC\n");
        return -2;
    }

    int16_t temp_raw = (int16_t)(raw >> 18);
    *temperature = temp_raw * 0.25;
    return 0;
}

static double pid_control(double setpoint, double actual) {
    double error = setpoint - actual;
    integral += error;
    double derivative = error - previous_error;
    double output = KP * error + KI * integral + KD * derivative;
    previous_error = error;
    if (output < 0.0) output = 0.0;
    if (output > 100.0) output = 100.0;
    return output;
}

static void log_data(double temp, double duty, double pid_out) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s, Temp: %.2f, Duty: %.2f, PID: %.2f\n", ts, temp, duty, pid_out);
    fflush(log_file);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }
    pigpio_initialized = 1;

    gpioSetMode(HEATER_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(HEATER_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(HEATER_GPIO, PWM_RANGE);
    gpioPWM(HEATER_GPIO, 0);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    fprintf(log_file, "--- Heater PID session started ---\n");
    fflush(log_file);

    while (running) {
        double temp = 0.0;
        int rc = read_max31855(spi_handle, &temp);

        if (rc == -2) {
            fprintf(stderr, "MAX31855 fault detected, disabling heater\n");
            gpioPWM(HEATER_GPIO, 0);
            integral = 0.0;
            previous_error = 0.0;
            log_data(-999.0, 0.0, 0.0);
            sleep(1);
            continue;
        }

        if (rc < 0) {
            fprintf(stderr, "SPI read error, disabling heater\n");
            gpioPWM(HEATER_GPIO, 0);
            integral = 0.0;
            previous_error = 0.0;
            log_data(-999.0, 0.0, 0.0);
            sleep(1);
            continue;
        }

        if (temp > MAX_TEMP || temp < MIN_TEMP) {
            fprintf(stderr, "Temperature out of range (%.2f), disabling heater\n", temp);
            gpioPWM(HEATER_GPIO, 0);
            integral = 0.0;
            previous_error = 0.0;
            log_data(-999.0, 0.0, 0.0);
            sleep(1);
            continue;
        }

        double duty = pid_control(TARGET_TEMP, temp);
        gpioPWM(HEATER_GPIO, (int)duty);
        log_data(temp, duty, 0.0);
        sleep(1);
    }

    cleanup();
    return 0;
}

