#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FAN_GPIO 18
#define PWM_FREQUENCY 25000
#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define LOG_FILE "cooling_log.csv"
#define POLL_INTERVAL 5

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_cpu_temp(void) {
    FILE *fp = fopen(TEMP_FILE, "r");
    if (!fp) {
        perror("fopen temperature file");
        return -1;
    }
    int temp_milli;
    if (fscanf(fp, "%d", &temp_milli) != 1) {
        fprintf(stderr, "Failed to parse temperature from %s\n", TEMP_FILE);
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return temp_milli / 1000;
}

static int calculate_duty_cycle(int temp_celsius) {
    if (temp_celsius <= 40) return 0;
    if (temp_celsius >= 70) return 100;
    return (int)(((float)(temp_celsius - 40) / 30.0) * 100.0);
}

static int log_data(int temp_celsius, int duty_cycle) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log file");
        return -1;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s,%d,%d\n", timestamp, temp_celsius, duty_cycle);
    fclose(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY);
    gpioPWM(FAN_GPIO, 0);

    FILE *fp = fopen(LOG_FILE, "r");
    if (!fp) {
        if (access(LOG_FILE, F_OK) == 0) {
            fclose(fp);
        } else {
            fp = fopen(LOG_FILE, "w");
            if (fp) {
                fprintf(fp, "timestamp,temperature_celsius,duty_cycle_percent\n");
                fclose(fp);
            }
        }
    }

    while (running) {
        int temp = read_cpu_temp();
        if (temp < 0) {
            fprintf(stderr, "Temperature read failed, retrying in %d seconds\n", POLL_INTERVAL);
            sleep(POLL_INTERVAL);
            continue;
        }

        int duty = calculate_duty_cycle(temp);
        if (gpioPWM(FAN_GPIO, duty) != 0) {
            fprintf(stderr, "Failed to set PWM duty cycle to %d\n", duty);
        }

        if (log_data(temp, duty) != 0) {
            fprintf(stderr, "Failed to log data\n");
        }

        sleep(POLL_INTERVAL);
    }

    gpioPWM(FAN_GPIO, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

