        if (log_data(temp, duty) != 0) {
            fprintf(stderr, "Failed to log data\n");
        }

        sleep(POLL_INTERVAL);
    }

    gpioPWM(FAN_GPIO, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

