#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>

#define I2C_BUS 1
#define SLF3S_ADDR_1 0x08
#define SLF3S_ADDR_2 0x09
#define LOG_FILE "flow_log.txt"
#define MEAS_CMD_MSB 0x36
#define MEAS_CMD_LSB 0x08
#define RETRY_COUNT 3
#define POLL_INTERVAL_US 1000000

static volatile sig_atomic_t running = 1;
static int i2c_handle1 = -1;
static int i2c_handle2 = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int bit = 0; bit < 8; bit++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

static int read_flow_rate(int handle, float *flow_rate) {
    uint8_t cmd[2] = {MEAS_CMD_MSB, MEAS_CMD_LSB};
    uint8_t buf[3];
    int result;

    for (int attempt = 0; attempt < RETRY_COUNT; attempt++) {
        result = i2cWriteDevice(handle, (char *)cmd, 2);
        if (result != 0) {
            fprintf(stderr, "I2C write error (attempt %d): %d\n", attempt + 1, result);
            gpioDelay(10000);
            continue;
        }

        gpioDelay(20000);

        result = i2cReadDevice(handle, (char *)buf, 3);
        if (result != 3) {
            fprintf(stderr, "I2C read error (attempt %d): %d\n", attempt + 1, result);
            gpioDelay(10000);
            continue;
        }

        if (crc8(buf, 2) != buf[2]) {
            fprintf(stderr, "CRC mismatch on attempt %d\n", attempt + 1);
            gpioDelay(10000);
            continue;
        }

        uint16_t raw = (buf[0] << 8) | buf[1];
        *flow_rate = (float)raw * 0.01f;
        return 0;
    }

    return -1;
}

static int log_flow_rates(float flow1, float flow2) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen");
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, flow1, flow2);
    fclose(fp);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle1 = i2cOpen(I2C_BUS, SLF3S_ADDR_1, 0);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X: %d\n", SLF3S_ADDR_1, i2c_handle1);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    i2c_handle2 = i2cOpen(I2C_BUS, SLF3S_ADDR_2, 0);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X: %d\n", SLF3S_ADDR_2, i2c_handle2);
        i2cClose(i2c_handle1);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Starting flow monitoring. Press Ctrl+C to stop.\n");

    while (running) {
        float flow1 = 0.0f, flow2 = 0.0f;
        int ok1 = (read_flow_rate(i2c_handle1, &flow1) == 0);
        int ok2 = (read_flow_rate(i2c_handle2, &flow2) == 0);

        if (ok1 && ok2) {
            if (log_flow_rates(flow1, flow2) != 0) {
                fprintf(stderr, "Failed to log flow rates\n");
            } else {
                printf("Flow1: %.2f ml/min, Flow2: %.2f ml/min\n", flow1, flow2);
            }
        } else {
            fprintf(stderr, "Error reading flow rates (sensor1=%s, sensor2=%s)\n",
                    ok1 ? "OK" : "FAIL",
                    ok2 ? "OK" : "FAIL");
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    if (i2c_handle1 >= 0) i2cClose(i2c_handle1);
    if (i2c_handle2 >= 0) i2cClose(i2c_handle2);
    gpioTerminate();
    return EXIT_SUCCESS;
}

