#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SENSOR_A_PIN 17
#define SENSOR_B_PIN 18
#define LOG_FILE "encoder_log.txt"
#define PULSES_PER_REV 360.0

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

typedef struct {
    int a_pin;
    int b_pin;
    double pulses_per_rev;
    double current_angle;
    int last_state;
    int current_state;
} Encoder;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int initialize_encoder(Encoder *enc, int a_pin, int b_pin, double pulses_per_rev) {
    enc->a_pin = a_pin;
    enc->b_pin = b_pin;
    enc->pulses_per_rev = pulses_per_rev;
    enc->current_angle = 0.0;
    enc->last_state = 0;
    enc->current_state = 0;
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return -1;
    }
    gpioSetMode(a_pin, PI_INPUT);
    gpioSetMode(b_pin, PI_INPUT);
    gpioSetPullUpDown(a_pin, PI_PUD_UP);
    gpioSetPullUpDown(b_pin, PI_PUD_UP);
    return 0;
}

static void cleanup(Encoder *enc) {
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

static int log_data(FILE *fp, double angle) {
    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        return -1;
    }
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return -1;
    }
    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }
    if (fprintf(fp, "%s, %.2f\n", timestamp, angle) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int update_encoder(Encoder *enc) {
    int a = gpioRead(enc->a_pin);
    int b = gpioRead(enc->b_pin);
    if (a < 0 || b < 0) {
        fprintf(stderr, "gpioRead failed (a=%d, b=%d)\n", a, b);
        return -1;
    }
    int new_state = (a << 1) | b;
    if (new_state != enc->current_state) {
        enc->current_state = new_state;
        if (new_state == 0) {
            enc->current_angle += 360.0 / PULSES_PER_REV;
            if (enc->current_angle >= 360.0) enc->current_angle -= 360.0;
        } else if (new_state == 3) {
            enc->current_angle -= 360.0 / PULSES_PER_REV;
            if (enc->current_angle < 0.0) enc->current_angle += 360.0;
        }
        if (log_data(log_file, enc->current_angle) != 0) {
            fprintf(stderr, "Failed to log data\n");
            return -1;
        }
        return 0;
    }
    return 0;
}

int main(void) {
    Encoder encoder;
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return 1;
    }
    if (initialize_encoder(&encoder, SENSOR_A_PIN, SENSOR_B_PIN, PULSES_PER_REV) != 0) {
        return 1;
    }
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        cleanup(&encoder);
        return 1;
    }
    printf("Encoder monitoring started. Press Ctrl+C to exit.\n");
    while (running) {
        if (update_encoder(&encoder) != 0) {
            break;
        }
    }
    cleanup(&encoder);
    printf("Encoder monitoring stopped.\n");
    return 0;
}

