/*
 * ADPD144RI Red/IR Photometric Sensor Reader
 * Board:  Raspberry Pi 3 Model B+
 * Library: libgpiod (modern GPIO API)
 * Bus:     /dev/i2c-1  Address: 0x39 (7-bit)
 * LED:     GPIO 17 (active-high)
 *
 * Build:  gcc -O2 -Wall -Wextra -o adpd144ri adpd144ri.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#include <gpiod.h>

/* ---- ADPD144RI constants (from datasheet) ---- */
#define ADPD144RI_ADDR        0x39
#define ADPD144RI_REG_FIFO    0x60
#define ADPD144RI_REG_CONFIG  0x70
#define ADPD144RI_REG_INTEN   0x72
#define ADPD144RI_REG_INTSTC  0x73
#define ADPD144RI_REG_CHLIST  0x74
#define ADPD144RI_REG_CHLIST_EN 0x80
#define ADPD144RI_REG_CHLIST_EN_RIR 0x40
#define ADPD144RI_REG_CHLIST_EN_IR 0x20
#define ADPD144RI_REG_CHLIST_EN_RED 0x10
#define ADPD144RI_REG_CHLIST_EN_GIR 0x08
#define ADPD144RI_REG_CHLIST_EN_GIR2 0x04
#define ADPD144RI_REG_CHLIST_EN_GIR3 0x02
#define ADPD144RI_REG_CHLIST_EN_GIR4 0x01

#define ADPD144RI_CHLIST_EN_RIR 0x03
#define ADPD144RI_CHLIST_EN_RED 0x01

#define ADPD144RI_CONFIG_DEFAULT 0x00
#define ADPD144RI_INTEN_DEFAULT 0x00
#define ADPD144RI_INTSTC_DEFAULT 0x00
#define ADPD144RI_CHLIST_DEFAULT 0x00

#define I2C_BUS        "/dev/i2c-1"
#define GPIO_CHIP      "gpiochip4"   /* BCM GPIO bank on Pi 3B+ */
#define LED_PIN        17
#define IR_THRESHOLD   2000
#define LOG_FILE       "adpd144ri_log.txt"
#define SAMPLE_MS      100

/* ---- Globals for cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_fd = -1;
static FILE    *g_log_fp = NULL;
static struct gpiod_chip  *g_chip = NULL;
static struct gpiod_line  *g_led  = NULL;

/* ------------------------------------------------------------------ */
static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static void cleanup(void)
{
    if (g_led) {
        gpiod_line_set_value(g_led, 0);
        gpiod_line_release(g_led);
        g_led = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    if (g_log_fp) {
        fflush(g_log_fp);
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
}

/* ------------------------------------------------------------------ */
/* Write a single byte to an ADPD144RI register.                       */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int adpd_write_reg(uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    ssize_t n = write(g_i2c_fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit little-endian word from an ADPD144RI register.        */
/* Returns 0 on success and stores the value in *out; -1 on error.     */
/* ------------------------------------------------------------------ */
static int adpd_read_reg16(uint8_t reg, uint16_t *out)
{
    uint8_t buf[2];
    ssize_t n = read(g_i2c_fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Configure the ADPD144RI for red+IR photometric mode.                 */
/* ------------------------------------------------------------------ */
static int adpd_init(void)
{
    /* Software reset: write 0x00 to CONFIG (also clears INTEN).        */
