#define ADPD144RI_REG_CHLIST_EN_RIR 0x40
#define ADPD144RI_REG_CHLIST_EN_IR 0x20
#define ADPD144RI_REG_CHLIST_EN_RED 0x10
#define ADPD144RI_REG_CHLIST_EN_GIR 0x08
#define ADPD144RI_REG_CHLIST_EN_GIR2 0x04
#define ADPD144RI_REG_CHLIST_EN_GIR3 0x02
#define ADPD144RI_REG_CHLIST_EN_GIR4 0x01

#define ADPD144RI_CHLIST_EN_RIR 0x03
#define ADPD144RI_CHLIST_EN_RED 0x01

