#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <pthread.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <errno.h>

#define GPIO_PIN 18
#define LOG_FILE "rpm_log.txt"
#define PULSES_PER_REVOLUTION 1
#define SAMPLE_INTERVAL_SEC 1

static volatile int pulse_count = 0;
static FILE *log_file = NULL;
static pthread_mutex_t pulse_mutex;
static volatile sig_atomic_t running = 1;

static void pulse_counter(int gpio, int level, uint32_t tick, void *user_data) {
    (void)gpio; (void)level; (void)tick; (void)user_data;
    pthread_mutex_lock(&pulse_mutex);
    pulse_count++;
    pthread_mutex_unlock(&pulse_mutex);
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cleanup(void) {
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
    pthread_mutex_destroy(&pulse_mutex);
}

int main(void) {
    if (pthread_mutex_init(&pulse_mutex, NULL) != 0) {
        fprintf(stderr, "Mutex initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        pthread_mutex_destroy(&pulse_mutex);
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", GPIO_PIN);
        gpioTerminate();
        pthread_mutex_destroy(&pulse_mutex);
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set pull-down on GPIO %d\n", GPIO_PIN);
        gpioTerminate();
        pthread_mutex_destroy(&pulse_mutex);
        return EXIT_FAILURE;
    }

    if (gpioSetISRFuncEx(GPIO_PIN, RISING_EDGE, 0, pulse_counter, NULL) != 0) {
        fprintf(stderr, "Failed to register ISR on GPIO %d\n", GPIO_PIN);
        gpioTerminate();
        pthread_mutex_destroy(&pulse_mutex);
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        gpioSetISRFuncEx(GPIO_PIN, RISING_EDGE, 0, NULL, NULL);
        gpioTerminate();
        pthread_mutex_destroy(&pulse_mutex);
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install signal handlers: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("RPM logging started on GPIO %d. Press Ctrl+C to stop.\n", GPIO_PIN);

    while (running) {
        sleep(SAMPLE_INTERVAL_SEC);
        if (!running) break;

        pthread_mutex_lock(&pulse_mutex);
        int pulses = pulse_count;
        pulse_count = 0;
        pthread_mutex_unlock(&pulse_mutex);

        double rpm = (double)pulses * 60.0 / (double)PULSES_PER_REVOLUTION;

        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[32];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        if (fprintf(log_file, "%s, RPM: %.2f\n", timestamp, rpm) < 0) {
            fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        } else {
            fflush(log_file);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

