#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip4"
#define GPIO_INPUT_PIN 17
#define GPIO_OUTPUT_PIN 18
#define LOG_FILE "audio_log.txt"
#define POLL_INTERVAL_US 10000

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int log_event(const char *filename, int level) {
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n", filename, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "Error getting local time: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s %d\n", timestamp, level) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *input_line = NULL;
    struct gpiod_line *output_line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Error registering SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Error registering SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip '%s': %s\n", GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    input_line = gpiod_chip_get_line(chip, GPIO_INPUT_PIN);
    if (!input_line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_INPUT_PIN, strerror(errno));
        goto cleanup;
    }

    output_line = gpiod_chip_get_line(chip, GPIO_OUTPUT_PIN);
    if (!output_line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_OUTPUT_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input(input_line, "max9814-input") < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as input: %s\n", GPIO_INPUT_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(output_line, "max9814-output", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %s\n", GPIO_OUTPUT_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_set_value(output_line, 0) < 0) {
        fprintf(stderr, "Error setting GPIO line %d to LOW: %s\n", GPIO_OUTPUT_PIN, strerror(errno));
        goto cleanup;
    }

    printf("Audio logging started. Press Ctrl+C to exit.\n");

    int last_value = 0;
    while (program_running) {
        int value = gpiod_line_get_value(input_line);
        if (value < 0) {
            fprintf(stderr, "Error reading GPIO line %d: %s\n", GPIO_INPUT_PIN, strerror(errno));
            break;
        }

        if (value == 1 && last_value == 0) {
            if (log_event(LOG_FILE, 1) == 0) {
                printf("Peak detected and logged.\n");
            } else {
                fprintf(stderr, "Failed to log event.\n");
            }
        }

        last_value = value;
        usleep(POLL_INTERVAL_US);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (output_line) {
        gpiod_line_set_value(output_line, 0);
        gpiod_line_release(output_line);
    }
    if (input_line) {
        gpiod_line_release(input_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    printf("Audio logging stopped.\n");
    return ret;
}

