#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x70
#define STATE_REG 0x00
#define STATE_LEN 7
#define LOG_FILE "air_quality_log.csv"
#define SAMPLE_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_sensor_data(int handle, uint8_t *data) {
    int result = i2cReadI2CBlockData(handle, STATE_REG, (char *)data, STATE_LEN);
    if (result != STATE_LEN) {
        fprintf(stderr, "Error: I2C block read failed (returned %d, expected %d)\n",
                result, STATE_LEN);
        return -1;
    }
    return 0;
}

static int parse_sensor_data(const uint8_t *data, float *tvoc, float *eco2) {
    uint16_t tvoc_raw = ((uint16_t)data[1] << 8) | data[2];
    uint16_t eco2_raw = ((uint16_t)data[5] << 8) | data[6];

    *tvoc = (float)tvoc_raw / 10.0f;
    *eco2 = (float)eco2_raw;
    return 0;
}

static float calculate_iaq(float tvoc, float eco2) {
    float iaq = 100.0f - (tvoc / 10.0f) - ((eco2 - 400.0f) / 50.0f);
    if (iaq < 0.0f) iaq = 0.0f;
    if (iaq > 100.0f) iaq = 100.0f;
    return iaq;
}

static int log_data(FILE *fp, float iaq, float tvoc, float eco2) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error: localtime_r failed\n");
        return -1;
    }
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s,%.2f,%.2f,%.2f\n", timestamp, iaq, tvoc, eco2) < 0) {
        fprintf(stderr, "Error: fprintf to log file failed\n");
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "Error: fflush failed\n");
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle %d)\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error: fopen log file");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,IAQ,TVOC (ppb),eCO2 (ppm)\n");
        fflush(log_file);
    }

    uint8_t sensor_data[STATE_LEN];
    float tvoc, eco2, iaq;

    while (running) {
        if (read_sensor_data(i2c_handle, sensor_data) != 0) {
            fprintf(stderr, "Warning: sensor read failed, retrying in %d seconds\n",
                    SAMPLE_INTERVAL_SEC);
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }

        if (parse_sensor_data(sensor_data, &tvoc, &eco2) != 0) {
            fprintf(stderr, "Warning: parse failed, retrying in %d seconds\n",
                    SAMPLE_INTERVAL_SEC);
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }

        iaq = calculate_iaq(tvoc, eco2);

        if (log_data(log_file, iaq, tvoc, eco2) != 0) {
            fprintf(stderr, "Warning: log write failed\n");
        }

        printf("TVOC: %.2f ppb, eCO2: %.2f ppm, IAQ: %.2f%%\n",
               tvoc, eco2, iaq);

        sleep(SAMPLE_INTERVAL_SEC);
    }

    fprintf(stderr, "\nShutting down gracefully...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
    }
    gpioTerminate();
    return 0;
}

