#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME  "gpiochip0"
#define GPIO_LINE_OFFSET 17
#define POLL_INTERVAL_MS 100
#define INTRUSION_THRESHOLD_S 5

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static int setup_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static void print_intrusion_alert(void)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) != NULL) {
        if (strftime(timestamp, sizeof(timestamp),
                     "%Y-%m-%d %H:%M:%S", &timeinfo) > 0) {
            printf("INTRUSION DETECTED: Touch on GPIO %d at %s\n",
                   GPIO_LINE_OFFSET, timestamp);
            fflush(stdout);
        }
    }
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    struct timespec poll_ts;
    struct timespec intrusion_start;
    int ret;

    if (setup_signal_handlers() != 0) {
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip by name */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        fprintf(stderr, "Failed to open %s: %s\n",
                GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Get the line for GPIO 17 */
    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (line == NULL) {
        fprintf(stderr, "Failed to get line %d: %s\n",
                GPIO_LINE_OFFSET, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request the line as input with the consumer label */
    ret = gpiod_line_request_input(line, "ttp223_tamper");
    if (ret != 0) {
        fprintf(stderr, "Failed to request line %d as input: %s\n",
                GPIO_LINE_OFFSET, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Seed the intrusion timer at the start of the first poll */
    clock_gettime(CLOCK_MONOTONIC, &intrusion_start);

    printf("Monitoring GPIO %d for touch (threshold %d s). Press Ctrl+C to exit.\n",
           GPIO_LINE_OFFSET, INTRUSION_THRESHOLD_S);
    fflush(stdout);

    while (program_running) {
        int value = gpiod_line_get_value(line);
        if (value < 0) {
            fprintf(stderr, "Failed to read GPIO %d: %s\n",
                    GPIO_LINE_OFFSET, strerror(errno));
            gpiod_line_release(line);
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }

        if (value == 1) {
            /* Touch detected — start the intrusion timer */
            clock_gettime(CLOCK_MONOTONIC, &intrusion_start);
        } else {
            /* Released — check if the touch exceeded the threshold */
            struct timespec now;
            clock_gettime(CLOCK_MONOTONIC, &now);
            double elapsed = (now.tv_sec - intrusion_start.tv_sec)
                            + (now.tv_nsec - intrusion_start.tv_nsec) / 1e9;

            if (elapsed > INTRUSION_THRESHOLD_S) {
                print_intrusion_alert();
                intrusion_start.tv_sec = now.tv_sec;
                intrusion_start.tv_nsec = now.tv_nsec;
            }
        }

        poll_ts.tv_sec  = POLL_INTERVAL_MS / 1000;
        poll_ts.tv_nsec = (POLL_INTERVAL_MS % 1000) * 1000000L;
        nanosleep(&poll_ts, NULL);
    }

    /* Graceful shutdown */
    printf("\nShutting down...\n");
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

