#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/soundcard.h>
#include <gpiod.h>

#define PCM_DEVICE "/dev/snd/pcmC0D0c"
#define GPIO_CHIP "gpiochip0"
#define L/R_PIN 17
#define SAMPLE_RATE 16000
#define BITS_PER_SAMPLE 16
#define NUM_CHANNELS 1
#define BUFFER_SIZE 1024

static volatile sig_atomic_t running = 1;

void handle_signal(int sig) {
    (void)sig;
    running = 0;
}

int main() {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int pcm_fd = -1;
    FILE *fp = NULL;
    int ret = EXIT_FAILURE;

    signal(SIGINT, handle_signal);

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        goto cleanup;
    }

    line = gpiod_chip_get_line(chip, L/R_PIN);
    if (!line) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_output(line, "inmp441-l/r", 0) < 0) {
        perror("gpiod_line_request_output");
        goto cleanup;
    }

    // Initialize I2S via ALSA
    pcm_fd = open(PCM_DEVICE, O_WRONLY);
    if (pcm_fd < 0) {
        perror("open pcm device");
        goto cleanup;
    }

    int format = AFMT_S16_LE;
    if (ioctl(pcm_fd, SNDCTL_DSP_SETFMT, &format) < 0) {
        perror("ioctl SNDCTL_DSP_SETFMT");
        goto cleanup;
    }

    int rate = SAMPLE_RATE;
    if (ioctl(pcm_fd, SNDCTL_DSP_SETRATE, &rate) < 0) {
        perror("ioctl SNDCTL_DSP_SETRATE");
        goto cleanup;
    }

    int channels = NUM_CHANNELS;
    if (ioctl(pcm_fd, SNDCTL_DSP_CHANNELS, &channels) < 0) {
        perror("ioctl SNDCTL_DSP_CHANNELS");
        goto cleanup;
    }

    // Write header to file
    fp = fopen("audio_capture.pcm", "wb");
    if (!fp) {
        perror("fopen");
        goto cleanup;
    }

    uint32_t header_size = 36 + (BUFFER_SIZE * 2);
    uint32_t subchunk1_size = 16;
    uint32_t subchunk2_size = BUFFER_SIZE * 2;
    uint16_t audio_format = 1;
    uint16_t num_channels = NUM_CHANNELS;
    uint32_t sample_rate = SAMPLE_RATE;
    uint32_t byte_rate = SAMPLE_RATE * NUM_CHANNELS * BITS_PER_SAMPLE / 8;
    uint16_t block_align = NUM_CHANNELS * BITS_PER_SAMPLE / 8;
    uint16_t bits_per_sample = BITS_PER_SAMPLE;

    if (fwrite("RIFF", 1, 4, fp) != 4) goto cleanup;
    if (fwrite(&header_size, 4, 1, fp) != 1) goto cleanup;
    if (fwrite("WAVE", 1, 4, fp) != 4) goto cleanup;
    if (fwrite("fmt ", 1, 4, fp) != 4) goto cleanup;
    if (fwrite(&subchunk1_size, 4, 1, fp) != 1) goto cleanup;
    if (fwrite(&audio_format, 2, 1, fp) != 1) goto cleanup;
    if (fwrite(&num_channels, 2, 1, fp) != 1) goto cleanup;
    if (fwrite(&sample_rate, 4, 1, fp) != 1) goto cleanup;
    if (fwrite(&byte_rate, 4, 1, fp) != 1) goto cleanup;
    if (fwrite(&block_align, 2, 1, fp) != 1) goto cleanup;
    if (fwrite(&bits_per_sample, 2, 1, fp) != 1) goto cleanup;
    if (fwrite("data", 1, 4, fp) != 4) goto cleanup;
    if (fwrite(&subchunk2_size, 4, 1, fp) != 1) goto cleanup;

    // Main loop
    while (running) {
        uint8_t buffer[BUFFER_SIZE * 4];
        ssize_t bytes_read = read(pcm_fd, buffer, sizeof(buffer));
        if (bytes_read < 0) {
            perror("read pcm");
            break;
        }
        if (bytes_read == 0) {
            continue;
        }

        for (ssize_t i = 0; i < bytes_read; i += 4) {
            int32_t raw = (int32_t)((buffer[i] << 24) | (buffer[i+1] << 16) | (buffer[i+2] << 8) | buffer[i+3]);
            // INMP441 is 24-bit left-justified in 32-bit frame
            int16_t sample = (int16_t)(raw >> 8);
            if (fwrite(&sample, 2, 1, fp) != 1) {
                perror("fwrite");
                break;
            }
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (fp) fclose(fp);
    if (pcm_fd >= 0) close(pcm_fd);
    if (line) gpiod_line_release(line);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

