#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FLAME_SENSOR_PIN 4
#define FAN_PIN 18
#define PWM_FREQUENCY 100
#define PWM_RANGE 100
#define DEBOUNCE_DELAY_MS 50
#define POLL_INTERVAL_MS 50
#define LOG_FILE "flame_log.txt"
#define FLAME_TIMEOUT_MS 5000

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void log_event(const char *message) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", t);
    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file);
}

static int read_flame_sensor(void) {
    int value = gpioRead(FLAME_SENSOR_PIN);
    if (value < 0) {
        log_event("Error: Failed to read flame sensor GPIO");
        return -1;
    }
    gpioDelay(DEBOUNCE_DELAY_MS * 1000);
    int confirmed = gpioRead(FLAME_SENSOR_PIN);
    if (confirmed < 0) {
        log_event("Error: Failed to read flame sensor GPIO after debounce");
        return -1;
    }
    return (confirmed == 0) ? 1 : 0;
}

static void control_fan(int flame_detected) {
    if (flame_detected) {
        int duty_cycle = (int)(100.0 * (double)flame_detected / 2.0);
        if (duty_cycle > PWM_RANGE) duty_cycle = PWM_RANGE;
        if (gpioPWM(FAN_PIN, duty_cycle) != 0) {
            log_event("Error: Failed to set PWM duty cycle");
        }
    } else {
        if (gpioPWM(FAN_PIN, 0) != 0) {
            log_event("Error: Failed to turn off PWM");
        }
    }
}

static void cleanup(void) {
    gpioPWM(FAN_PIN, 0);
    gpioSetMode(FAN_PIN, PI_INPUT);
    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);
    gpioTerminate();
    if (log_file) {
        log_event("Program terminated");
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_event("Program started");

    if (gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT) != 0) {
        log_event("Error: Failed to set flame sensor pin mode");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(FAN_PIN, PI_OUTPUT) != 0) {
        log_event("Error: Failed to set fan pin mode");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(FAN_PIN, PWM_FREQUENCY) < 0) {
        log_event("Error: Failed to set PWM frequency");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(FAN_PIN, PWM_RANGE) != 0) {
        log_event("Error: Failed to set PWM range");
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        log_event("Error: Failed to set signal handlers");
        cleanup();
        return EXIT_FAILURE;
    }

    int flame_active = 0;
    time_t flame_start_time = 0;

    while (program_running) {
        int flame_detected = read_flame_sensor();
        if (flame_detected < 0) {
            gpioDelay(POLL_INTERVAL_MS * 1000);
            continue;
        }

        if (flame_detected) {
            if (!flame_active) {
                flame_active = 1;
                flame_start_time = time(NULL);
                log_event("Flame detected");
            }
        } else {
            if (flame_active) {
                int elapsed = time(NULL) - flame_start_time;
                if (elapsed > FLAME_TIMEOUT_MS) {
                    log_event("Flame timeout");
                    flame_active = 0;
                }
            }
        }

        control_fan(flame_active);
        gpioDelay(POLL_INTERVAL_MS * 1000);
    }

    cleanup();
    return EXIT_SUCCESS;
}

