#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED   1000000
#define SPI_MODE    0
#define TRIGGER_PIN 23
#define DATA_READY_PIN 24
#define FRAME_SIZE  32768
#define FRAME_PERIOD_MS 100

#define MAGIC_NUMBER 0x52444144

typedef struct {
    uint64_t magic;
    uint32_t version;
    uint32_t num_chirps;
    uint32_t num_samples;
    uint32_t frame_period_ms;
    uint32_t start_freq_gigahz;
    uint32_t end_freq_gigahz;
    uint32_t num_frames;
    uint32_t num_channels;
    uint32_t num_subframes;
} __attribute__((packed)) FrameHeader;

typedef struct {
    uint32_t start_freq;
    uint32_t end_freq;
    uint32_t num_chirps;
    uint32_t num_samples;
    uint32_t frame_period_ms;
} __attribute__((packed)) Config;

static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int spi_init(void) {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: spiOpen failed: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

static int gpio_init(void) {
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode trigger failed\n");
        return -1;
    }
    if (gpioSetMode(DATA_READY_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode data_ready failed\n");
        return -1;
    }
    if (gpioSetPullUpDown(DATA_READY_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown failed\n");
        return -1;
    }
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite trigger failed\n");
        return -1;
    }
    return 0;
}

static int spi_transfer(const uint8_t *tx, uint8_t *rx, int len) {
    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, len);
    if (ret != len) {
        fprintf(stderr, "Error: spiXfer returned %d, expected %d\n", ret, len);
        return -1;
    }
    return 0;
}

static int read_frame(uint8_t *data) {
    if (gpioWrite(TRIGGER_PIN, 1) < 0) return -1;
    gpioDelay(1000);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) return -1;

    int ready = 0;
    while (!ready && !terminate) {
        if (gpioRead(DATA_READY_PIN) == 1) ready = 1;
        gpioDelay(1000);
    }
    if (!ready) {
        fprintf(stderr, "Error: Data ready pin never went high\n");
        return -1;
    }

    int bytes_read = spi_transfer(data, data, FRAME_SIZE);
    if (bytes_read != FRAME_SIZE) {
        fprintf(stderr, "Error: SPI transfer returned %d bytes\n", bytes_read);
        return -1;
    }
