#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define OPT3001_ADDR 0x44
#define REG_RESULT 0x00
#define REG_CONFIG 0x01
#define CONFIG_CONTINUOUS 0x01
#define CONFIG_100MS 0x00
#define CONFIG_AUTO_FULLSCALE 0x00
#define LOG_FILE "light_data.txt"
#define MAX_RETRIES 3
#define RETRY_DELAY_US 100000

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int opt3001_init(void) {
    i2c_handle = i2cOpen(1, OPT3001_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus 1 at 0x%02X: %d\n", OPT3001_ADDR, i2c_handle);
        return -1;
    }

    int config = CONFIG_CONTINUOUS | CONFIG_100MS | CONFIG_AUTO_FULLSCALE;
    int status = i2cWriteByteData(i2c_handle, REG_CONFIG, config);
    if (status < 0) {
        fprintf(stderr, "Error writing config register: %d\n", status);
        i2cClose(i2c_handle);
        i2c_handle = -1;
        return -1;
    }

    return 0;
}

static int opt3001_read_lux(float *lux) {
    char buf[2];
    int status = i2cReadI2CBlockData(i2c_handle, REG_RESULT, buf, 2);
    if (status < 0) {
        fprintf(stderr, "Error reading result register: %d\n", status);
        return -1;
    }
    if (status != 2) {
        fprintf(stderr, "Short read from result register: %d bytes\n", status);
        return -1;
    }

    uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    uint16_t exponent = (raw >> 12) & 0x0F;
    uint16_t mantissa = raw & 0x0FFF;
    *lux = 0.01f * (float)(1 << exponent) * (float)mantissa;
    return 0;
}

static void log_data(float lux) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char timestamp[64];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm);
        fprintf(fp, "%s,%.2f\n", timestamp, lux);
    } else {
        fprintf(fp, "(timestamp error),%.2f\n", lux);
    }

    fclose(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (opt3001_init() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("OPT3001 initialized. Logging to %s. Press Ctrl+C to stop.\n", LOG_FILE);

    while (!terminate) {
        float lux;
        int success = 0;
        for (int attempt = 0; attempt < MAX_RETRIES && !terminate; attempt++) {
            if (opt3001_read_lux(&lux) == 0) {
                success = 1;
                break;
            }
            fprintf(stderr, "Read attempt %d/%d failed, retrying...\n", attempt + 1, MAX_RETRIES);
            gpioDelay(RETRY_DELAY_US);
        }

        if (success) {
            log_data(lux);
            printf("Lux: %.2f\n", lux);
        } else {
            fprintf(stderr, "Failed to read lux after %d attempts.\n", MAX_RETRIES);
        }

        gpioDelay(500000);
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
    printf("\nProgram terminated cleanly.\n");
    return EXIT_SUCCESS;
}

