#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define LEFT_SENSOR 17
#define CENTER_SENSOR 18
#define RIGHT_SENSOR 27
#define POLL_INTERVAL_US 50000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    int pins[] = {LEFT_SENSOR, CENTER_SENSOR, RIGHT_SENSOR};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); i++) {
        if (gpioSetMode(pins[i], PI_INPUT) != 0) {
            fprintf(stderr, "Error: gpioSetMode failed for GPIO %d\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: sigaction failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        int left = gpioRead(LEFT_SENSOR);
        int center = gpioRead(CENTER_SENSOR);
        int right = gpioRead(RIGHT_SENSOR);

        if (left < 0 || center < 0 || right < 0) {
            fprintf(stderr, "Error: gpioRead failed (L=%d, C=%d, R=%d)\n", left, center, right);
            break;
        }

        printf("Left: %d, Center: %d, Right: %d\n", left, center, right);
        fflush(stdout);

        usleep(POLL_INTERVAL_US);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

