#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_CHANNELS 8
#define POLL_INTERVAL_US 100000  /* 100 ms */

static const unsigned int touch_pins[NUM_CHANNELS] = {2, 3, 4, 5, 6, 7, 8, 9};

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_CHANNELS];
    int ret;
    int i;

    /* Install SIGINT handler for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on Pi Zero W) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Acquire each line and request it as input */
    for (i = 0; i < NUM_CHANNELS; i++) {
        lines[i] = gpiod_chip_get_line(chip, touch_pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %u\n", touch_pins[i]);
            goto cleanup;
        }
        ret = gpiod_line_request_input(lines[i], "ttp226-touch");
        if (ret < 0) {
            fprintf(stderr, "Failed to request GPIO line %u as input: %s\n",
                    touch_pins[i], strerror(-ret));
            goto cleanup;
        }
    }

    printf("TTP226 8-channel touch sensor reader started.\n");
    printf("Channels: BCM GPIO 2,3,4,5,6,7,8,9\n");
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    /* Main polling loop */
    while (running) {
        for (i = 0; i < NUM_CHANNELS; i++) {
            int val = gpiod_line_get_value(lines[i]);
            if (val < 0) {
                fprintf(stderr, "Error reading GPIO line %u: %s\n",
                        touch_pins[i], strerror(-val));
                goto cleanup;
            }
            printf("Channel %d (GPIO %u): %d\n", i, touch_pins[i], val);
        }
        fflush(stdout);
        usleep(POLL_INTERVAL_US);
    }

    printf("\nExiting gracefully...\n");

cleanup:
    /* Release all lines and close chip */
    for (i = 0; i < NUM_CHANNELS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return EXIT_SUCCESS;
}

