#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define NUM_CHANNELS 8
#define POLL_DELAY_US 100000  /* 100 ms */

static const int gpio_pins[NUM_CHANNELS] = {2, 3, 4, 5, 6, 7, 8, 9};

static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

static void print_timestamp_ms(void)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) == 0) {
        printf("[%ld.%03ld] ", (long)ts.tv_sec, ts.tv_nsec / 1000000);
    } else {
        printf("[?ms] ");
    }
}

int main(void)
{
    int ret;
    int i;

    /* --- Initialize pigpio --- */
    ret = gpioInitialise();
    if (ret < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (code %d).\n", ret);
        return EXIT_FAILURE;
    }

    /* --- Install signal handlers --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO pins as inputs with pull-down --- */
    for (i = 0; i < NUM_CHANNELS; i++) {
        ret = gpioSetMode(gpio_pins[i], PI_INPUT);
        if (ret != 0) {
            fprintf(stderr, "Error: gpioSetMode failed for GPIO %d (code %d).\n",
                    gpio_pins[i], ret);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        ret = gpioSetPullUpDown(gpio_pins[i], PI_PUD_DOWN);
        if (ret != 0) {
            fprintf(stderr, "Error: gpioSetPullUpDown failed for GPIO %d (code %d).\n",
                    gpio_pins[i], ret);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    printf("TTP226 8-channel touch sensor reader started.\n");
    printf("Pins: OUT1=GPIO%d OUT2=GPIO%d ... OUT8=GPIO%d\n",
           gpio_pins[0], gpio_pins[1], gpio_pins[NUM_CHANNELS - 1]);
    printf("Press Ctrl+C to exit.\n");

    /* --- Main polling loop --- */
    while (!terminate) {
        print_timestamp_ms();

        for (i = 0; i < NUM_CHANNELS; i++) {
            int level = gpioRead(gpio_pins[i]);
            if (level < 0) {
                fprintf(stderr, "Warning: gpioRead failed for GPIO %d.\n",
                        gpio_pins[i]);
                level = 0;
            }
            printf("CH%d=%d ", i + 1, level);
        }
        printf("\n");

        gpioDelay(POLL_DELAY_US);
    }

    /* --- Clean shutdown --- */
    printf("\nShutting down...\n");
    gpioTerminate();
    return EXIT_SUCCESS;
}

