#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_CHANNELS 8
#define POLL_INTERVAL_US 50000  /* 50 ms */

static const unsigned int gpio_pins[NUM_CHANNELS] = {2, 3, 4, 17, 27, 22, 10, 9};

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static void get_timestamp(char *buf, size_t len)
{
    time_t rawtime;
    struct tm timeinfo;

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) != NULL) {
        strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &timeinfo);
    } else {
        snprintf(buf, len, "1970-01-01T00:00:00");
    }
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_CHANNELS];
    int ret;
    int exit_code = EXIT_FAILURE;

    for (int i = 0; i < NUM_CHANNELS; i++) {
        lines[i] = NULL;
    }

    /* Install signal handler for graceful shutdown */
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Error: cannot install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on Raspberry Pi 4) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "Error: cannot open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire each GPIO line as input */
    for (int i = 0; i < NUM_CHANNELS; i++) {
        lines[i] = gpiod_chip_get_line(chip, gpio_pins[i]);
        if (lines[i] == NULL) {
            fprintf(stderr, "Error: cannot get GPIO line %u: %s\n",
                    gpio_pins[i], strerror(errno));
            goto cleanup;
        }

        ret = gpiod_line_request_input(lines[i], "ttp226_touch");
        if (ret < 0) {
            fprintf(stderr, "Error: cannot request GPIO line %u as input: %s\n",
                    gpio_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    printf("TTP226 touch sensor polling started. Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (program_running) {
        char timestamp[32];
        get_timestamp(timestamp, sizeof(timestamp));

        for (int i = 0; i < NUM_CHANNELS; i++) {
            int val = gpiod_line_get_value(lines[i]);
            if (val < 0) {
                fprintf(stderr, "Error: read failed on GPIO %u: %s\n",
                        gpio_pins[i], strerror(errno));
                goto cleanup;
            }
            printf("%s,%d", timestamp, val);
        }
        printf("\n");
        fflush(stdout);

        usleep(POLL_INTERVAL_US);
    }

    printf("\nExiting gracefully...\n");
    exit_code = EXIT_SUCCESS;

cleanup:
    /* Release each line request */
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (lines[i] != NULL) {
            gpiod_line_release(lines[i]);
        }
    }

    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    return exit_code;
}

