#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define SI1145_ADDR 0x60
#define SI1145_REG_PART_ID 0x00
#define SI1145_REG_HW_KEY 0x07
#define SI1145_REG_CHLIST 0x01
#define SI1145_REG_ALS_VIS_DATA0 0x22
#define SI1145_REG_UV_INDEX 0x2C
#define SI1145_REG_COMMAND 0x18
#define SI1145_CMD_ALS_FORCE 0x06
#define SI1145_CMD_RESET 0x01
#define SI1145_PART_ID 0x45
#define SI1145_HW_KEY_VAL 0x17

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

int si1145_write_reg(uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(i2c_handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing to register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

int si1145_read_reg(uint8_t reg, uint8_t *value) {
    int result = i2cReadByteData(i2c_handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading from register 0x%02X: %d\n", reg, result);
        return -1;
    }
    *value = (uint8_t)result;
    return 0;
}

int si1145_init() {
    uint8_t part_id = 0;
    if (si1145_read_reg(SI1145_REG_PART_ID, &part_id) < 0) {
        fprintf(stderr, "Failed to read PART ID\n");
        return -1;
    }
    if (part_id != SI1145_PART_ID) {
        fprintf(stderr, "Unexpected PART ID: 0x%02X (expected 0x%02X)\n", part_id, SI1145_PART_ID);
        return -1;
    }

    if (si1145_write_reg(SI1145_REG_COMMAND, SI1145_CMD_RESET) < 0) return -1;
    gpioDelay(10000);

    if (si1145_write_reg(SI1145_REG_HW_KEY, SI1145_HW_KEY_VAL) < 0) return -1;

    if (si1145_write_reg(SI1145_REG_CHLIST, 0x03) < 0) return -1;

    return 0;
}

int read_uv_index(float *uv_index) {
    uint8_t uv_index_reg = 0;
    if (si1145_read_reg(SI1145_REG_UV_INDEX, &uv_index_reg) < 0) return -1;
    *uv_index = (float)uv_index_reg;
    return 0;
}

int read_als_visible(uint16_t *als_visible) {
    uint8_t als_data[2];
    if (si1145_read_reg(SI1145_REG_ALS_VIS_DATA0, &als_data[0]) < 0) return -1;
    if (si1145_read_reg(SI1145_REG_ALS_VIS_DATA0 + 1, &als_data[1]) < 0) return -1;
    *als_visible = (uint16_t)((als_data[0] << 8) | als_data[1]);
    return 0;
}

void log_data(float uv_index, uint16_t als_visible) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%u\n", timestamp, uv_index, als_visible);
    fflush(log_file);
}

void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (si1145_init() < 0) {
        fprintf(stderr, "Si1145 initialization failed\n");
        cleanup();
        return 1;
    }

    log_file = fopen("uv_als_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,uv_index,als_visible\n");
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (!terminate) {
        float uv_index = 0.0;
        uint16_t als_visible = 0;

        if (read_uv_index(&uv_index) < 0 || read_als_visible(&als_visible) < 0) {
            fprintf(stderr, "Error reading sensor data\n");
        } else {
            log_data(uv_index, als_visible);
            printf("UV Index: %.2f, ALS Visible: %u\n", uv_index, als_visible);
        }

        gpioDelay(1000000);
    }

    cleanup();
    return 0;
}

