#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define SENSOR1_ADDR   0x36
#define SENSOR2_ADDR   0x37
#define GPIO_CHIP       "gpiochip4"
#define GPIO_LINE       17
#define FLOW_SCALE      0.036f
#define FLOW_THRESHOLD  0.5f
#define LOG_FILE        "flow_log.txt"
#define MEAS_DELAY_MS   100
#define LOOP_DELAY_MS   1000

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static uint8_t sensirion_crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int i2c_write_cmd(int fd, uint8_t reg, uint16_t cmd) {
    uint8_t buf[3] = { reg, (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (write(fd, buf, 3) != 3) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_flow_rate(int fd, uint8_t addr, float *flow_out) {
    uint8_t buf[9];
    int16_t raw_flow;

    if (i2c_write_cmd(fd, 0x08, 0x3608) < 0)
        return -1;

    usleep(MEAS_DELAY_MS * 1000);

    if (i2c_read_bytes(fd, 0x00, buf, sizeof(buf)) < 0)
        return -1;

    if (sensirion_crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "CRC mismatch on sensor 0x%02X\n", addr);
        return -1;
    }
    if (sensirion_crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "CRC mismatch on sensor 0x%02X\n", addr);
        return -1;
    }
    if (sensirion_crc8(&buf[6], 2) != buf[8]) {
        fprintf(stderr, "CRC mismatch on sensor 0x%02X\n", addr);
        return -1;
    }

    raw_flow = (int16_t)((buf[0] << 8) | buf[1]);
    *flow_out = (float)raw_flow * FLOW_SCALE;
    return 0;
}

static void log_flow_rates(FILE *fp, float f1, float f2, float avg) {
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Sensor1: %.3f ml/min, Sensor2: %.3f ml/min, Average: %.3f ml/min\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, f1, f2, avg);
    fflush(fp);
}

int main(void) {
    int fd1 = -1, fd2 = -1;
    FILE *fp = NULL;
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        goto cleanup;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_output(line, "flow_alarm", 0) < 0) {
        perror("gpiod_line_request_output");
        goto cleanup;
    }

    fd1 = open(I2C_BUS, O_RDWR);
    if (fd1 < 0) {
        perror("open I2C bus");
        goto cleanup;
    }

    if (ioctl(fd1, I2C_SLAVE, SENSOR1_ADDR) < 0) {
        perror("ioctl SENSOR1");
        goto cleanup;
    }

    fd2 = open(I2C_BUS, O_RDWR);
    if (fd2 < 0) {
        perror("open I2C bus");
        goto cleanup;
    }

    if (ioctl(fd2, I2C_SLAVE, SENSOR2_ADDR) < 0) {
        perror("ioctl SENSOR2");
        goto cleanup;
    }

    if (i2c_write_cmd(fd1, 0x08, 0x3608) < 0 || i2c_write_cmd(fd2, 0x08, 0x3608) < 0) {
        fprintf(stderr, "Failed to start sensors\n");
        goto cleanup;
    }

    usleep(MEAS_DELAY_MS * 1000);

    while (running) {
        float f1 = 0.0f, f2 = 0.0f;
        int ok1 = read_flow_rate(fd1, SENSOR1_ADDR, &f1);
        int ok2 = read_flow_rate(fd2, SENSOR2_ADDR, &f2);

        if (ok1 == 0 && ok2 == 0) {
            float avg = (f1 + f2) / 2.0f;
            log_flow_rates(fp, f1, f2, avg);
            gpiod_line_set_value(line, avg < FLOW_THRESHOLD ? 1 : 0);
        } else {
            fprintf(stderr, "Sensor read error; skipping cycle\n");
        }

        usleep(LOOP_DELAY_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line) gpiod_line_release(line);
    if (chip) gpiod_chip_close(chip);
    if (fd1 >= 0) close(fd1);
    if (fd2 >= 0) close(fd2);
    if (fp) fclose(fp);
    return ret;
}

