#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR_1_PIN 23
#define SENSOR_2_PIN 24
#define LED_PIN     25
#define POLL_DELAY_US 100000  /* 100 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int setup_gpio(void)
{
    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(SENSOR_1_PIN) failed\n");
        return -1;
    }
    if (gpioSetMode(SENSOR_2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(SENSOR_2_PIN) failed\n");
        return -1;
    }
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(LED_PIN) failed\n");
        return -1;
    }
    return 0;
}

static int read_sensor(int pin)
{
    int v = gpioRead(pin);
    if (v < 0) {
        fprintf(stderr, "Error: gpioRead(%d) failed\n", pin);
        return -1;
    }
    return v;
}

static int control_led(int state)
{
    if (gpioWrite(LED_PIN, state) != 0) {
        fprintf(stderr, "Error: gpioWrite(LED_PIN, %d) failed\n", state);
        return -1;
    }
    return 0;
}

int main(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (setup_gpio() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int led_state = 0;

    while (g_running) {
        int s1 = read_sensor(SENSOR_1_PIN);
        int s2 = read_sensor(SENSOR_2_PIN);

        if (s1 < 0 || s2 < 0) {
            /* Sensor read error — turn LED off for safety */
            if (control_led(0) != 0) {
                fprintf(stderr, "Warning: failed to turn LED off on error\n");
            }
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        /* KY-032 is active-LOW: 0 = obstacle detected */
        int obstacle = (s1 == 0) || (s2 == 0);

        if (obstacle && !led_state) {
            if (control_led(1) != 0) {
                fprintf(stderr, "Warning: failed to turn LED on\n");
            } else {
                led_state = 1;
            }
        } else if (!obstacle && led_state) {
            if (control_led(0) != 0) {
                fprintf(stderr, "Warning: failed to turn LED off\n");
            } else {
                led_state = 0;
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* Clean shutdown */
    control_led(0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

