#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* TMAG5170-Q1 I2C address (A0=A1=0) */
#define TMAG5170_ADDR 0x0E

/* TMAG5170-Q1 register addresses */
#define REG_DEVICE_ID      0x00
#define REG_X_LSB         0x04
#define REG_X_MSB         0x05
#define REG_Y_LSB         0x06
#define REG_Y_MSB         0x07
#define REG_Z_LSB         0x08
#define REG_Z_MSB         0x09
#define REG_CONFIG        0x0A

/* Expected device ID */
#define TMAG5170_ID      0x8D

/* Config: 50 mT range, continuous conversion, all three axes enabled */
#define CONFIG_50MT_CONT 0x0C

/* I2C bus on Raspberry Pi 4 */
#define I2C_BUS 1

/* Sampling interval in microseconds (100 ms) */
#define SAMPLE_INTERVAL_US 100000

/* Global resources for signal handler */
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits cleanly               */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* ------------------------------------------------------------------ */
/* Write a single byte to a TMAG5170 register; return 0 on success, -1 on error */
/* ------------------------------------------------------------------ */
static int tmag_write_reg(uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(i2c_handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed: reg=0x%02X, val=0x%02X, rc=%d\n",
                reg, value, rc);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a single byte from a TMAG5170 register; return 0 on success, -1 on error */
/* ------------------------------------------------------------------ */
static int tmag_read_reg(uint8_t reg, uint8_t *value)
{
    int rc = i2cReadByteData(i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed: reg=0x%02X, rc=%d\n", reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit two's-complement value from two consecutive registers */
/* ------------------------------------------------------------------ */
static int tmag_read_axis(uint8_t lsb_reg, uint8_t msb_reg, int16_t *out)
{
    uint8_t lsb, msb;
    if (tmag_read_reg(lsb_reg, &lsb) < 0)
        return -1;
    if (tmag_read_reg(msb_reg, &msb) < 0)
        return -1;
    uint16_t raw = (uint16_t)((msb << 8) | lsb);
    *out = (int16_t)raw;          /* two's complement */
    return 0;
}

/* ------------------------------------------------------------------ */
/* Verify device ID and configure the sensor for 50 mT continuous mode */
/* ------------------------------------------------------------------ */
static int configure_sensor(void)
{
    uint8_t id;
    if (tmag_read_reg(REG_DEVICE_ID, &id) < 0) {
        fprintf(stderr, "Cannot read device ID — sensor may be absent\n");
        return -1;
    }
    if (id != TMAG5170_ID) {
        fprintf(stderr, "Device ID mismatch: got 0x%02X, expected 0x%02X\n",
                id, TMAG5170_ID);
        return -1;
    }
    printf("TMAG5170 detected (ID=0x%02X)\n", id);

    /* Configure: 50 mT range, continuous conversion, XYZ axes enabled */
    if (tmag_write_reg(REG_CONFIG, CONFIG_50MT_CONT) < 0) {
        fprintf(stderr, "Failed to write config register\n");
        return -1;
    }
    printf("Sensor configured for 50 mT continuous mode\n");
    return 0;
}

/* ------------------------------------------------------------------ */
/* Log one CSV row: timestamp, X_mT, Y_mT, Z_mT                            */
/* ------------------------------------------------------------------ */
static void log_data(float x_mT, float y_mT, float z_mT)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", ts, x_mT, y_mT, z_mT);
    fflush(log_file);
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — safe to call multiple times                         */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at TMAG5170 address */
    i2c_handle = i2cOpen(I2C_BUS, TMAG5170_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X: rc=%d\n",
                I2C_BUS, TMAG5170_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure sensor */
    if (configure_sensor() < 0) {
        fprintf(stderr, "Sensor configuration failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode; write header if file is empty */
    log_file = fopen("magnetic_log.csv", "a");
    if (!log_file) {
        perror("Failed to open magnetic_log.csv");
        cleanup();
        return EXIT_FAILURE;
    }
    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "timestamp,X_mT,Y_mT,Z_mT\n");
        fflush(log_file);
    }

    /* Register signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Logging magnetic field data to magnetic_log.csv (Ctrl+C to stop)\n");

    /* Main sampling loop */
    while (!terminate) {
        int16_t raw_x, raw_y, raw_z;

        if (tmag_read_axis(REG_X_LSB, REG_X_MSB, &raw_x) < 0 ||
            tmag_read_axis(REG_Y_LSB, REG_Y_MSB, &raw_y) < 0 ||
            tmag_read_axis(REG_Z_LSB, REG_Z_MSB, &raw_z) < 0) {
            fprintf(stderr, "I2C read error — skipping sample\n");
        } else {
            /* 50 mT range, 16-bit two's-complement → LSB = 0.0000625 mT */
            float x_mT = (float)raw_x * 0.0000625f;
            float y_mT = (float)raw_y * 0.0000625f;
            float z_mT = (float)raw_z * 0.0000625f;
            log_data(x_mT, y_mT, z_mT);
        }

        gpioDelay(SAMPLE_INTERVAL_US);   /* 100 ms */
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

