#define REINIT_DELAY_SEC 60

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_message(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

static void check_water_level(void) {
    int level = gpioRead(SENSOR_GPIO);
    if (level < 0) {
        fprintf(stderr, "Error reading GPIO %d\n", SENSOR_GPIO);
        log_message("ERROR: Failed to read sensor GPIO");
        return;
    }

    if (level == 1) {
        printf("Water detected!\n");
        log_message("ALERT: Water detected");
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
