#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>
#include <stdatomic.h>

#define SENSOR_A_PIN 17
#define SENSOR_B_PIN 27
#define LOG_FILE "rotation_log.txt"

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;
static atomic_int sensor_a_state = 0;
static atomic_int sensor_b_state = 0;
static atomic_int last_sensor_a_state = 0;
static atomic_int last_sensor_b_state = 0;
static atomic_int rotation_detected = 0;
static pthread_cond_t rotation_cond = PTHREAD_COND_INITIALIZER;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_rotation(const char *direction) {
    struct timespec ts;
    struct tm tm_info;
    char timestamp[64];

    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return;
    }

    localtime_r(&ts.tv_sec, &tm_info);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%03ld", ts.tv_nsec / 1000000);

    pthread_mutex_lock(&log_mutex);
    if (log_file) {
        fprintf(log_file, "%s: %s\n", timestamp, direction);
        fflush(log_file);
    }
    pthread_mutex_unlock(&log_mutex);
}

static void quadrature_isr(int gpio, int level, uint32_t tick, void *userdata) {
    (void)tick;
    (void)userdata;

    if (gpio == SENSOR_A_PIN) {
        atomic_store(&sensor_a_state, level);
    } else if (gpio == SENSOR_B_PIN) {
        atomic_store(&sensor_b_state, level);
    }
}

static void quadrature_callback(int gpio, int level, uint32_t tick, void *userdata) {
    (void)tick;
    (void)userdata;

    if (gpio == SENSOR_A_PIN) {
        atomic_store(&sensor_a_state, level);
    } else if (gpio == SENSOR_B_PIN) {
        atomic_store(&sensor_b_state, level);
    }
}

static void quadrature_state_machine(void) {
    int a = atomic_load(&sensor_a_state);
    int b = atomic_load(&sensor_b_state);
    int last_a = atomic_load(&last_sensor_a_state);
    int last_b = atomic_load(&last_sensor_b_state);

    if (a != last_a || b != last_b) {
        if (a != b) {
            if (a > b) {
                log_rotation("CW");
            } else {
                log_rotation("CCW");
            }
            atomic_store(&rotation_detected, 1);
            pthread_cond_signal(&rotation_cond);
        }
    }
    atomic_store(&last_sensor_a_state, a);
    atomic_store(&last_sensor_b_state, b);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_A_PIN, PI_INPUT) != 0 || gpioSetMode(SENSOR_B_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(SENSOR_A_PIN, PI_PUD_UP) != 0 || gpioSetPullUpDown(SENSOR_B_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "gpioSetPullUpDown failed\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetAlertFunc(SENSOR_A_PIN, quadrature_callback) != 0 || gpioSetAlertFunc(SENSOR_B_PIN, quadrature_callback) != 0) {
        fprintf(stderr, "gpioSetAlertFunc failed\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Quadrature rotation detection started. Press Ctrl+C to exit.\n");

    while (running) {
        if (atomic_load(&rotation_detected)) {
            rotation_detected = 0;
            pthread_cond_wait(&rotation_cond, &log_mutex);
        }
        usleep(10000);
    }

    printf("\nShutting down...\n");

    pthread_mutex_lock(&log_mutex);
    if (log_file) {
        fflush(log_file);
        fclose(log_file);
        log_file = NULL;
    }
    pthread_mutex_unlock(&log_mutex);

    gpioSetAlertFunc(SENSOR_A_PIN, NULL);
    gpioSetAlertFunc(SENSOR_B_PIN, NULL);
    gpioTerminate();

    pthread_mutex_destroy(&log_mutex);
    pthread_cond_destroy(&rotation_cond);

    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

