#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <errno.h>
#include <gpiod.h>

#define TOUCH_SENSOR_PIN 23
#define LED_PIN 18
#define POLL_INTERVAL_MS 50
#define GPIO_CHIP_NAME "gpiochip0"

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int signum) {
    (void)signum;
    program_running = 0;
}

static void log_message(int priority, const char *message) {
    syslog(priority, "%s", message);
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *touch_line = NULL;
    struct gpiod_line *led_line = NULL;
    int ret = EXIT_FAILURE;

    openlog("touch_led", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        syslog(LOG_ERR, "Failed to register SIGINT handler: %s", strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        syslog(LOG_ERR, "Failed to register SIGTERM handler: %s", strerror(errno));
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        syslog(LOG_ERR, "Failed to open GPIO chip '%s': %s", GPIO_CHIP_NAME, strerror(errno));
        goto cleanup;
    }

    touch_line = gpiod_chip_get_line(chip, TOUCH_SENSOR_PIN);
    if (!touch_line) {
        syslog(LOG_ERR, "Failed to get touch sensor line %d: %s", TOUCH_SENSOR_PIN, strerror(errno));
        goto cleanup;
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        syslog(LOG_ERR, "Failed to get LED line %d: %s", LED_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input(touch_line, "touch_sensor") < 0) {
        syslog(LOG_ERR, "Failed to request touch sensor line as input: %s", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(led_line, "led_control", 0) < 0) {
        syslog(LOG_ERR, "Failed to request LED line as output: %s", strerror(errno));
        goto cleanup;
    }

    log_message(LOG_INFO, "Touch sensor and LED control program started.");

    while (program_running) {
        int touch_value = gpiod_line_get_value(touch_line);
        if (touch_value < 0) {
            syslog(LOG_ERR, "Failed to read touch sensor value: %s", strerror(errno));
            break;
        }

        if (gpiod_line_set_value(led_line, touch_value) < 0) {
            syslog(LOG_ERR, "Failed to write LED value: %s", strerror(errno));
            break;
        }

        log_message(LOG_INFO, "Touch sensor value: %d", touch_value);
        usleep(POLL_INTERVAL_MS * 1000);
    }

    log_message(LOG_INFO, "Touch sensor and LED control program shutting down.");
    ret = EXIT_SUCCESS;

cleanup:
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
    }
    if (touch_line) {
        gpiod_line_release(touch_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    closelog();
    return ret;
}

