#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define SENSOR_1_PIN 4
#define SENSOR_2_PIN 17
#define LED_1_PIN   27
#define LED_2_PIN   22
#define BUFFER_SIZE 100
#define DEBOUNCE_MS 50

typedef struct {
    int sensor_pin;
    time_t timestamp;
    int state;          /* 0 = released, 1 = touched */
} Event;

static Event log_buffer[BUFFER_SIZE];
static int  log_index = 0;
static int  overflow_count = 0;

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void add_event(int sensor_pin, time_t timestamp, int state) {
    log_buffer[log_index].sensor_pin = sensor_pin;
    log_buffer[log_index].timestamp  = timestamp;
    log_buffer[log_index].state      = state;
    log_index = (log_index + 1) % BUFFER_SIZE;
    if (log_index == 0) {
        overflow_count++;
    }
}

static void print_log_buffer(void) {
    printf("\n--- Log Buffer Contents ---\n");
    int start = (log_index == 0) ? BUFFER_SIZE - 1 : 0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int idx = (start + i) % BUFFER_SIZE;
        printf("  Sensor %d: %ld ms (state=%d)\n",
               idx, (long)timestamp(log_buffer[idx].timestamp),
               log_buffer[idx].state);
    }
    printf("--- End of Log Buffer ---\n");
    printf("Overflow count: %d\n", overflow_count);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install signal handlers\n");
    }

    /* Configure sensor pins as inputs */
    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input\n", SENSOR_1_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SENSOR_2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input\n", SENSOR_2_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure LED pins as outputs and initialise to OFF */
    if (gpioSetMode(LED_1_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output\n", LED_1_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(LED_2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output\n", LED_2_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(LED_1_PIN, 0) != 0 || gpioWrite(LED_2_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise LED pins to OFF\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int prev1 = gpioRead(SENSOR_1_PIN);
    int prev2 = gpioRead(SENSOR_2_PIN);
    if (prev1 < 0 || prev2 < 0) {
        fprintf(stderr, "Error: initial sensor read failed\n");
        gpioWrite(LED_1_PIN, 0);
        gpioWrite(LED_2_PIN, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Touch sensor program started. Press Ctrl+C to exit.\n");

    while (running) {
        int cur1 = gpioRead(SENSOR_1_PIN);
        int cur2 = gpioRead(SENSOR_2_PIN);

        if (cur1 < 0) {
            fprintf(stderr, "Error: failed to read GPIO %d\n", SENSOR_1_PIN);
            break;
        }
        if (cur2 < 0) {
            fprintf(stderr, "Error: failed to read GPIO %d\n", SENSOR_2_PIN);
            break;
        }

        if (cur1 != prev1) {
            if (gpioWrite(LED_1_PIN, cur1) != 0) {
                fprintf(stderr, "Error: failed to write GPIO %d\n", LED_1_PIN);
                break;
            }
            add_event(SENSOR_1_PIN, time(NULL), cur1);
            prev1 = cur1;
        }

        if (cur2 != prev2) {
            if (gpioWrite(LED_2_PIN, cur2) != 0) {
                fprintf(stderr, "Error: failed to write GPIO %d\n", LED_2_PIN);
                break;
            }
            add_event(SENSOR_2_PIN, time(NULL), cur2);
            prev2 = cur2;
        }

        gpioDelay(DEBOUNCE_MS * 1000); /* pigpio delay in microseconds */
    }

    /* Graceful shutdown: turn off LEDs and release pigpio resources */
    gpioWrite(LED_1_PIN, 0);
    gpioWrite(LED_2_PIN, 0);
    gpioTerminate();

    print_log_buffer();
    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

