#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define RAIN_SENSOR_GPIO 17
#define LOG_FILE "/var/log/rain_events.log"
#define POLL_INTERVAL_US 500000

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(int rain_detected) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    if (log_file != NULL) {
        if (rain_detected) {
            fprintf(log_file, "%s - Rain Detected\n", timestamp);
        } else {
            fprintf(log_file, "%s - No Rain\n", timestamp);
        }
        fflush(log_file);
    } else {
        fprintf(stderr, "Log file is not open.\n");
    }
}

int main(void) {
    int last_state = -1;
    int ret;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (signal(SIGTERM, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    ret = gpioSetMode(RAIN_SENSOR_GPIO, PI_INPUT);
    if (ret != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input: %s\n", RAIN_SENSOR_GPIO, pigpio_error(ret));
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    ret = gpioSetPullUpDown(RAIN_SENSOR_GPIO, PI_PUD_UP);
    if (ret != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d: %s\n", RAIN_SENSOR_GPIO, pigpio_error(ret));
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Rain sensor monitoring started on GPIO %d. Press Ctrl+C to exit.\n", RAIN_SENSOR_GPIO);

    while (running) {
        int sensor_value = gpioRead(RAIN_SENSOR_GPIO);
        if (sensor_value < 0) {
            fprintf(stderr, "Failed to read GPIO %d: %s\n", RAIN_SENSOR_GPIO, pigpio_error(sensor_value));
            break;
        }

        if (sensor_value != last_state) {
            log_event(sensor_value == 0);
            last_state = sensor_value;
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");

    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }

    gpioTerminate();

    return EXIT_SUCCESS;
}

