        fprintf(stderr, "Log file is not open.\n");
    }
}

int main(void) {
    int last_state = -1;
    int ret;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (signal(SIGTERM, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    ret = gpioSetMode(RAIN_SENSOR_GPIO, PI_INPUT);
    if (ret != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input: %s\n", RAIN_SENSOR_GPIO, pigpio_error(ret));
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    ret = gpioSetPullUpDown(RAIN_SENSOR_GPIO, PI_PUD_UP);
    if (ret != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d: %s\n", RAIN_SENSOR_GPIO, pigpio_error(ret));
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Rain sensor monitoring started on GPIO %d. Press Ctrl+C to exit.\n", RAIN_SENSOR_GPIO);

    while (running) {
        int sensor_value = gpioRead(RAIN_SENSOR_GPIO);
        if (sensor_value < 0) {
            fprintf(stderr, "Failed to read GPIO %d: %s\n", RAIN_SENSOR_GPIO, pigpio_error(sensor_value));
            break;
        }

        if (sensor_value != last_state) {
            log_event(sensor_value == 0);
            last_state = sensor_value;
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");

    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }

    gpioTerminate();

    return EXIT_SUCCESS;
}

