#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define I2C_BUS 1
#define SI1182_ADDR 0x28
#define LOG_FILE "biometric_log.txt"
#define SAMPLE_INTERVAL_US 1000000  /* 1 second */

/* Si1182 register addresses */
#define REG_PART_ID      0x00
#define REG_HW_KEY       0x01
#define REG_MEAS_RATE0  0x08
#define REG_MEAS_RATE1  0x09
#define REG_CONFIG      0x30
#define REG_HR_DATA     0x02
#define REG_SPO2_DATA   0x04

/* Expected PART_ID for Si1182 */
#define SI1182_PART_ID 0x82

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int write_reg(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing 0x%02X to register 0x%02X (rc=%d)\n", value, reg, rc);
        return -1;
    }
    return 0;
}

static int read_reg(int handle, uint8_t reg, uint8_t *value) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading register 0x%02X (rc=%d)\n", reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

static int init_si1182(int handle) {
    uint8_t part_id = 0;
    if (read_reg(handle, REG_PART_ID, &part_id) != 0) {
        fprintf(stderr, "Failed to read PART_ID\n");
        return -1;
    }
    if (part_id != SI1182_PART_ID) {
        fprintf(stderr, "Unexpected PART_ID: 0x%02X (expected 0x%02X)\n", part_id, SI1182_PART_ID);
        return -1;
    }
    printf("Si1182 detected (PART_ID=0x%02X)\n", part_id);

    /* Write HW_KEY to enable the device */
    if (write_reg(handle, REG_HW_KEY, 0x17) != 0) return -1;

    /* Configure measurement rate: 0x0A = 100ms per sample */
    if (write_reg(handle, REG_MEAS_RATE0, 0x0A) != 0) return -1;
    if (write_reg(handle, REG_MEAS_RATE1, 0x00) != 0) return -1;

    /* Configure: enable HR and SpO2, continuous mode */
    if (write_reg(handle, REG_CONFIG, 0x0F) != 0) return -1;

    return 0;
}

static int read_hr_spo2(int handle, int *heart_rate, int *spo2) {
    uint8_t hr_raw = 0, spo2_raw = 0;
    if (read_reg(handle, REG_HR_DATA, &hr_raw) != 0) return -1;
    if (read_reg(handle, REG_SPO2_DATA, &spo2_raw) != 0) return -1;

    *heart_rate = (int)hr_raw;
    *spo2 = (int)spo2_raw;
    return 0;
}

static void log_data(FILE *fp, int heart_rate, int spo2) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error getting local time\n");
        return;
    }
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Heart Rate: %d BPM, SpO2: %d%%\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            heart_rate, spo2);
    fflush(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI1182_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X (rc=%d)\n", I2C_BUS, SI1182_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_si1182(i2c_handle) != 0) {
        fprintf(stderr, "Si1182 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s'\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler\n");
    }

    printf("Logging heart rate and SpO2 data to %s. Press Ctrl+C to stop.\n", LOG_FILE);

    while (!terminate) {
        int heart_rate = 0, spo2 = 0;
        if (read_hr_spo2(i2c_handle, &heart_rate, &spo2) == 0) {
            log_data(log_file, heart_rate, spo2);
        } else {
            fprintf(stderr, "Failed to read HR/SPO2 data\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

