#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 18
#define ALARM_GPIO 27
#define LOG_FILE "bridge_integrity.log"
#define POLL_DELAY_US 100000  /* 100 ms */
#define THRESHOLD_SECONDS 2

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *event) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    if (t && strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t)) {
        fprintf(log_file, "%s: %s\n", ts, event);
    } else {
        fprintf(log_file, "[timestamp-error]: %s\n", event);
    }
    fflush(log_file);
}

static void cleanup(void) {
    if (log_file) {
        log_event("Program terminated");
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(ALARM_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_1_GPIO, PI_INPUT) != 0 ||
        gpioSetMode(SENSOR_2_GPIO, PI_INPUT) != 0 ||
        gpioSetMode(ALARM_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

