/*
 * Seismic vibration monitor using Omron D7S-A0011 on Raspberry Pi 3 Model B+.
 *
 * Wiring:
 *   D7S SDA  -> GPIO2 (I2C bus 1 SDA, pin 3)
 *   D7S SCL  -> GPIO3 (I2C bus 1 SCL, pin 5)
 *   D7S VDD  -> 3.3 V
 *   D7S GND  -> GND
 *   LED anode -> GPIO17 (pin 11) through 330 ohm resistor -> GND
 *
 * Build: gcc -O2 -Wall -o seismic seismic.c -lpigpio -lm -lrt
 * Run:   sudo ./seismic
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- Configuration ---- */
#define I2C_BUS              1
#define D7S_ADDR             0x1D   /* D7S-A0011 default 7-bit I2C address */
#define LED_GPIO             17
#define VIBRATION_THRESHOLD  500
#define POLL_INTERVAL_US     100000  /* 100 ms */
#define LED_ON_DURATION_US   1000000 /* 1 s */
#define MAX_RETRIES          3
#define LOG_FILE             "seismic_events.log"

/* D7S-A0011 register addresses */
#define REG_CTRL1            0x1F  /* Control register 1 */
#define REG_ACCEL_X_LSB      0x28  /* Acceleration X low byte (6-byte block) */

/* CTRL1 bit masks */
#define CTRL1_POW_DOWN       0x01  /* Power-down bit (1 = powered down) */
#define CTRL1_WHO_AM_I        0x01  /* Read-only identity bit (0 = D7S-A0011) */

/* ---- Globals ---- */
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* ---- Timestamped logging ---- */
static void log_event(int magnitude)
{
    if (!log_file)
        return;

    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);

    fprintf(log_file, "%s - Vibration magnitude: %d\n", ts, magnitude);
    fflush(log_file);
}

/* ---- I2C helpers ---- */
static int i2c_read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len)
{
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc != (int)len) {
        fprintf(stderr, "I2C block read failed (reg 0x%02X, len %u): rc=%d\n",
                reg, len, rc);
        return -1;
    }
    return 0;
}

static int i2c_write_byte(int handle, uint8_t reg, uint8_t val)
{
    int rc = i2cWriteByteData(handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg 0x%02X, val 0x%02X): rc=%d\n",
                reg, val, rc);
        return -1;
    }
    return 0;
}

/* ---- Sensor initialization ---- */
static int init_d7s(void)
{
    /* Verify device identity */
    int who = i2cReadByteData(i2c_handle, REG_CTRL1);
    if (who < 0) {
        fprintf(stderr, "Cannot read WHO_AM_I register.\n");
        return -1;
    }
    if ((who & CTRL1_WHO_AM_I) != CTRL1_WHO_AM_I) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X.\n",
                who & CTRL1_WHO_AM_I, CTRL1_WHO_AM_I);
        return -1;
    }

    /* Clear power-down bit to enable normal operation */
    if (i2c_write_byte(i2c_handle, REG_CTRL1, CTRL1_POW_DOWN ^ CTRL1_POW_DOWN) < 0)
        return -1;

    /* Allow sensor to settle after power-up */
    gpioDelay(10000); /* 10 ms */
    return 0;
}

/* ---- Read 3-axis acceleration (little-endian) ---- */
static int read_acceleration(int16_t *x, int16_t *y, int16_t *z)
{
    uint8_t buf[6];
    int ok = 0;

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (i2c_read_block(i2c_handle, REG_ACCEL_X_LSB, buf, sizeof(buf)) == 0) {
            *x = (int16_t)((buf[1] << 8) | buf[0]);
            *y = (int16_t)((buf[3] << 8) | buf[2]);
            *z = (int16_t)((buf[5] << 8) | buf[4]);
            ok = 1;
            break;
        }
        gpioDelay(10000); /* 10 ms backoff */
    }

    if (!ok) {
        fprintf(stderr, "Failed to read acceleration after %d retries.\n", MAX_RETRIES);
        return -1;
    }
    return 0;
}

/* ---- Compute Euclidean magnitude ---- */
static int compute_magnitude(int16_t x, int16_t y, int16_t z)
{
    double dx = (double)x;
    double dy = (double)y;
    double dz = (double)z;
    return (int)sqrt(dx * dx + dy * dy + dz * dz);
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    i2c_handle = i2cOpen(I2C_BUS, D7S_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X: rc=%d\n",
                I2C_BUS, D7S_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (init_d7s() < 0) {
        fprintf(stderr, "D7S initialization failed. Check wiring and address.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure LED GPIO */
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    /* Open log file */
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Warning: cannot open log file '%s'. Events will not be logged.\n",
                LOG_FILE);
    }

    /* Signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Seismic monitoring started. Threshold=%d, LED on GPIO%d.\n",
           VIBRATION_THRESHOLD, LED_GPIO);
    printf("Press Ctrl+C to exit.\n");

    int16_t x, y, z;
    int mag;

    while (!terminate) {
        if (read_acceleration(&x, &y, &z) < 0) {
            /* Sensor error: wait and retry rather than crash */
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        mag = compute_magnitude(x, y, z);

        if (mag > VIBRATION_THRESHOLD) {
            printf("Vibration magnitude: %d\n", mag);
            log_event(mag);

            gpioWrite(LED_GPIO, 1);
            gpioDelay(LED_ON_DURATION_US);
            gpioWrite(LED_GPIO, 0);
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

