#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <errno.h>
#include <string.h>

#define NUM_SENSORS 4
#define LED_PIN 18
#define POLL_INTERVAL_US 50000

static const unsigned int sensor_pins[NUM_SENSORS] = {4, 17, 27, 22};
static const char *chip_name = "gpiochip4";

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *sensor_lines[NUM_SENSORS];
    struct gpiod_line *led_line = NULL;
    int ret = EXIT_FAILURE;

    for (int i = 0; i < NUM_SENSORS; i++) {
        sensor_lines[i] = NULL;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(chip_name);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", chip_name, strerror(errno));
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_SENSORS; i++) {
        sensor_lines[i] = gpiod_chip_get_line(chip, sensor_pins[i]);
        if (!sensor_lines[i]) {
            fprintf(stderr, "Failed to get line %u: %s\n", sensor_pins[i], strerror(errno));
            goto cleanup;
        }
        if (gpiod_line_request_input(sensor_lines[i], "ky032_sensor") < 0) {
            fprintf(stderr, "Failed to request line %u as input: %s\n", sensor_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        fprintf(stderr, "Failed to get line %u: %s\n", LED_PIN, strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_output(led_line, "ky032_led", 0) < 0) {
        fprintf(stderr, "Failed to request line %u as output: %s\n", LED_PIN, strerror(errno));
        goto cleanup;
    }

    printf("Obstacle detection started. Press Ctrl+C to exit.\n");

    while (running) {
        int object_detected = 0;

        for (int i = 0; i < NUM_SENSORS; i++) {
            int val = gpiod_line_get_value(sensor_lines[i]);
            if (val < 0) {
                fprintf(stderr, "Failed to read sensor %d: %s\n", i, strerror(errno));
                goto cleanup;
            }
            if (val == 0) {
                object_detected = 1;
                break;
            }
        }

