/*
 * flame_monitor.c — KY-026 flame sensor monitor for Raspberry Pi 3 Model B+
 * Uses libgpiod (v1.6+).  Compile: gcc -O2 -Wall -Wextra -o flame_monitor flame_monitor.c -lgpiod
 *
 * Build:  solder KY-026 DO pins to BCM 2, 3, 4, 17, 27 (physical 3, 5, 7, 11, 13)
 *         VCC -> 3.3 V, GND -> GND, DO -> KY-026 DO
 * Run:    ./flame_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <syslog.h>
#include <gpiod.h>

#define NUM_SENSORS      5
#define POLL_INTERVAL_S  1
#define DEBOUNCE_MS      50
#define LOG_FILE         "/var/log/flame_events.log"

static const unsigned int sensor_pins[NUM_SENSORS] = {2, 3, 4, 17, 27};

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_event(int sensor_id, const char *message)
{
    time_t now = time(NULL);
    struct tm tm_utc;
    char ts[32];

    if (gmtime_r(&now, &tm_utc) == NULL) {
        syslog(LOG_ERR, "gmtime_r failed: %s", strerror(errno));
        return;
    }
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc) == 0) {
        syslog(LOG_ERR, "strftime failed");
        return;
    }

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        syslog(LOG_ERR, "Cannot open %s: %s", LOG_FILE, strerror(errno));
        return;
    }

    if (flock(fileno(fp), LOCK_EX) == -1) {
        syslog(LOG_ERR, "flock(LOCK_EX) failed: %s", strerror(errno));
        fclose(fp);
        return;
    }

    fprintf(fp, "%s - Sensor ID: %d (GPIO %u) - %s\n",
            ts, sensor_id, sensor_pins[sensor_id],
            message ? message : "UNKNOWN");
    fflush(fp);
    if (flock(fileno(fp), LOCK_UN) == -1)
        syslog(LOG_ERR, "flock(LOCK_UN) failed: %s", strerror(errno));

    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_SENSORS];
    int prev_state[NUM_SENSORS];
    int ret = EXIT_FAILURE;

    for (int i = 0; i < NUM_SENSORS; i++)
        lines[i] = NULL;

    openlog("flame_monitor", LOG_PID | LOG_CONS, LOG_USER);

    /* Signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        syslog(LOG_ERR, "sigaction(SIGINT) failed: %s", strerror(errno));
        goto cleanup;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        syslog(LOG_ERR, "sigaction(SIGTERM) failed: %s", strerror(errno));
        goto cleanup;
    }

    /* Open the default gpiochip (gpiochip0 on RPi 3B+) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        syslog(LOG_ERR, "gpiod_chip_open_by_name failed: %s", strerror(errno));
        goto cleanup;
    }

    /* Acquire each line as input */
    for (int i = 0; i < NUM_SENSORS; i++) {
        lines[i] = gpiod_chip_get_line(chip, sensor_pins[i]);
        if (lines[i] == NULL) {
            syslog(LOG_ERR, "gpiod_chip_get_line(%u) failed: %s",
                   sensor_pins[i], strerror(errno));
            goto cleanup;
        }
        if (gpiod_line_request_input(lines[i], "flame_monitor") < 0) {
            syslog(LOG_ERR, "gpiod_line_request_input(%u) failed: %s",
                   sensor_pins[i], strerror(errno));
            goto cleanup;
        }
        prev_state[i] = gpiod_line_get_value(lines[i]);
        if (prev_state[i] < 0) {
            syslog(LOG_ERR, "Initial gpiod_line_get_value(%u) failed: %s",
                   sensor_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    syslog(LOG_INFO, "Flame sensor monitoring started (GPIO %u, %u, %u, %u, %u)",
           sensor_pins[0], sensor_pins[1], sensor_pins[2], sensor_pins[3], sensor_pins[4]);

    /* Main polling loop */
    while (g_running) {
        for (int i = 0; i < NUM_SENSORS; i++) {
            int val = gpiod_line_get_value(lines[i]);
            if (val < 0) {
                syslog(LOG_ERR, "gpiod_line_get_value(%u) failed: %s",
                       sensor_pins[i], strerror(errno));
                continue;  /* skip this sensor this cycle */
            }

            /* Rising edge: no-flame -> flame */
            if (val == 1 && prev_state[i] == 0) {
                /* Debounce: wait 50 ms and re-read */
                usleep(DEBOUNCE_MS * 1000);
                int debounced = gpiod_line_get_value(lines[i]);
                if (debounced < 0) {
                    syslog(LOG_ERR, "gpiod_line_get_value(%u) debounce failed: %s",
                           sensor_pins[i], strerror(errno));
                } else if (debounced == 1) {
                    log_event(i + 1, "Flame Detected");
                }
            }
            prev_state[i] = val;
        }
        sleep(POLL_INTERVAL_S);
    }

    syslog(LOG_INFO, "Flame sensor monitoring stopped.");
    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip */
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (lines[i] != NULL)
            gpiod_line_release(lines[i]);
    }
    if (chip != NULL)
        gpiod_chip_close(chip);
    closelog();
    return ret;
}

