    struct gpiod_line_settings *settings = NULL;
    struct gpiod_line_config *line_cfg = NULL;
    struct gpiod_request_config *req_cfg = NULL;
    int ret = EXIT_FAILURE;

    /* ---- Signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Open default GPIO chip ---- */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Configure line settings: input, pull-down (optional) ---- */
    settings = gpiod_line_settings_new();
    if (settings == NULL) {
        fprintf(stderr, "gpiod_line_settings_new failed: %s\n", strerror(errno));
        goto cleanup;
    }
    gpiod_line_settings_set_direction(settings, GPIOD_LINE_DIRECTION_INPUT);
    gpiod_line_settings_set_bias(settings, GPIOD_LINE_BIAS_PULL_DOWN);

    /* ---- Build line list ---- */
    gpiod_line_bulk_init(&lines);
    for (int i = 0; i < NUM_CHANNELS; i++) {
        unsigned int pin = touch_pins[i];
        struct gpiod_line *line = gpiod_chip_get_line(chip, pin);
        if (line == NULL) {
            fprintf(stderr, "Failed to get line for BCM GPIO %u: %s\n",
                    pin, strerror(errno));
            goto cleanup;
        }
        gpiod_line_bulk_add(&lines, line);
    }

    /* ---- Build line config ---- */
    line_cfg = gpiod_line_config_new();
    if (line_cfg == NULL) {
        fprintf(stderr, "gpiod_line_config_new failed: %s\n", strerror(errno));
        goto cleanup;
    }
    gpiod_line_config_reset(line_cfg);
    gpiod_line_config_add_line_settings(line_cfg, &lines, 1, settings);

    /* ---- Build request config ---- */
    req_cfg = gpiod_request_config_new();
    if (req_cfg == NULL) {
        fprintf(stderr, "gpiod_request_config_new failed: %s\n", strerror(errno));
        goto cleanup;
    }
    gpiod_request_config_set_consumer(req_cfg, "ttp226-reader");

    /* ---- Request the lines ---- */
    req = gpiod_chip_request_lines(chip, req_cfg, line_cfg);
    if (req == NULL) {
        fprintf(stderr, "Failed to request lines: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("TTP226 touch sensor monitoring started.\n");
    printf("  OUT0 -> BCM GPIO5 | OUT1 -> BCM GPIO6 | OUT2 -> BCM GPIO13 | OUT3 -> BCM GPIO19\n");
    printf("  OUT4 -> BCM GPIO26 | OUT5 -> BCM GPIO12 | OUT6 -> BCM GPIO16 | OUT7 -> BCM GPIO20\n");
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    /* ---- Main polling loop ---- */
    while (g_running) {
        enum gpiod_line_value values[NUM_CHANNELS];
        int read_failed = 0;

        if (gpiod_line_request_get_values(req, values) < 0) {
            fprintf(stderr, "Failed to read line values: %s\n", strerror(errno));
            read_failed = 1;
            break;
        }

        for (int i = 0; i < NUM_CHANNELS; i++) {
            int prev = (values[i] == GPIOD_LINE_VALUE_ACTIVE) ? 1 : 0;
            int cur  = (values[i] == GPIOD_LINE_VALUE_ACTIVE) ? 1 : 0;

            if (prev != cur) {
                print_timestamp();
                printf("Sensor %d (BCM GPIO %u) %s\n",
                       i + 1, touch_pins[i],
                       (cur == 1) ? "Touched" : "Released");
                fflush(stdout);
            }
        }

        if (!read_failed) {
            usleep(POLL_MS * 1000);
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (req != NULL) {
        gpiod_line_request_release(req);
    }
    if (req_cfg != NULL) {
        gpiod_request_config_free(req_cfg);
    }
    if (line_cfg != NULL) {
        gpiod_line_config_free(line_cfg);
    }
    if (settings != NULL) {
        gpiod_line_settings_free(settings);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    if (ret == EXIT_SUCCESS) {
        printf("\nExiting gracefully.\n");
    }
    return ret;
}

