#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define VEML7700_ADDR 0x10
#define VEML7700_CONFIG_REG 0x00
#define VEML7700_ALS_REG 0x04
#define LED_GPIO 18
#define PWM_FREQUENCY 1000
#define PWM_RANGE 100
#define LOG_FILE "grow_log.txt"
#define SAMPLE_INTERVAL_US 1000000
#define LUX_THRESHOLD_1 100.0
#define LUX_THRESHOLD_2 500.0
#define LUX_THRESHOLD_3 1000.0

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int veml7700_init(int handle) {
    uint16_t config = 0x0000; /* ALS gain 1/8, integration time 100 ms */
    char buf[2];
    buf[0] = (config >> 8) & 0xFF;
    buf[1] = config & 0xFF;
    if (i2cWriteI2CBlockData(handle, VEML7700_CONFIG_REG, buf, 2) < 0) {
        fprintf(stderr, "Error writing VEML7700 config: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int veml7700_read_lux(int handle, float *lux_out) {
    char buf[2];
    if (i2cReadI2CBlockData(handle, VEML7700_ALS_REG, buf, 2) != 2) {
        fprintf(stderr, "Error reading VEML7700 ALS data: %s\n", strerror(errno));
        return -1;
    }
    uint16_t raw = (uint16_t)((uint8_t)buf[0] | ((uint8_t)buf[1] << 8));
    *lux_out = (float)raw * 0.0576f;
    return 0;
}

static int set_led_brightness(int gpio, int brightness) {
    if (gpioPWM(gpio, brightness) < 0) {
        fprintf(stderr, "Error setting PWM on GPIO %d: %s\n", gpio, strerror(errno));
        return -1;
    }
    return 0;
}

static void log_data(FILE *fp, float lux, int brightness, int error_code) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error getting local time\n");
        return;
    }
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s, Lux: %.2f, Brightness: %d, Error: %d\n", timestamp, lux, brightness, error_code);
    fflush(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, VEML7700_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus 1 at 0x%02X: %s\n", VEML7700_ADDR, strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (veml7700_init(i2c_handle) < 0) {
        fprintf(stderr, "VEML7700 initialization failed (sensor absent or bus error)\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(LED_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(LED_GPIO, PWM_RANGE);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    float lux;
    int error_code = 0;

    while (!terminate) {
        if (veml7700_read_lux(i2c_handle, &lux) == 0) {
            error_code = 0;
            int brightness;
            if (lux < LUX_THRESHOLD_1) {
                brightness = PWM_RANGE;
            } else if (lux < LUX_THRESHOLD_2) {
                brightness = PWM_RANGE * 75 / 100;
            } else if (lux < LUX_THRESHOLD_3) {
                brightness = PWM_RANGE * 50 / 100;
            } else {
                brightness = PWM_RANGE * 25 / 100;
            }
            if (set_led_brightness(LED_GPIO, brightness) < 0) {
                error_code = -2;
            }
            log_data(log_file, lux, brightness, error_code);
        } else {
            error_code = -3;
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    set_led_brightness(LED_GPIO, 0);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    if (log_file) fclose(log_file);
    gpioTerminate();
    return 0;
}

