#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define NUM_CHANNELS 8
#define LED_GPIO 17
#define POLL_DELAY_US 50000  /* 50 ms */
#define LOG_FILE "touch_log.txt"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_touch_event(int channel) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    struct tm tm;
    if (!localtime_r(&t, &tm)) {
        fprintf(stderr, "localtime_r() failed\n");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime() failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s - Channel %d Touched\n", timestamp, channel + 1) < 0) {
        fprintf(stderr, "Error writing to %s: %s\n", LOG_FILE, strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Configure touch sensor channels as inputs with pull-down */
    for (int i = 0; i < NUM_CHANNELS; i++) {
        int gpio = 2 + i;
        if (gpioSetMode(gpio, PI_INPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as input\n", gpio);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPullUpDown(gpio, PI_PUD_DOWN) != 0) {
            fprintf(stderr, "Failed to set pull-down on GPIO %d\n", gpio);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    /* Configure LED as output and ensure it starts off */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(LED_GPIO, 0) != 0) {
        fprintf(stderr, "Failed to initialize LED GPIO %d to 0\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Security keypad running. Press Ctrl+C to exit.\n");

    /* Track previous state for debouncing and LED control */
    int prev_state[NUM_CHANNELS];
    for (int i = 0; i < NUM_CHANNELS; i++) {
        prev_state[i] = 0;
    }

    int led_state = 0;

    while (running) {
        int any_touched = 0;

        for (int i = 0; i < NUM_CHANNELS; i++) {
            int level = gpioRead(2 + i);
            if (level < 0) {
                fprintf(stderr, "Error reading GPIO %d\n", 2 + i);
                continue;
            }

            /* Detect rising edge: transition from 0 to 1 */
            if (level == 1 && prev_state[i] == 0) {
                if (log_touch_event(i) == 0) {
                    printf("Channel %d touched\n", i + 1);
                }
                any_touched = 1;
            }
            prev_state[i] = level;
        }

        /* Update LED based on current state */
        if (any_touched && !led_state) {
            if (gpioWrite(LED_GPIO, 1) != 0) {
                fprintf(stderr, "Failed to turn on LED on GPIO %d\n", LED_GPIO);
            } else {
                led_state = 1;
            }
        } else if (!any_touched && led_state) {
            if (gpioWrite(LED_GPIO, 0) != 0) {
                fprintf(stderr, "Failed to turn off LED on GPIO %d\n", LED_GPIO);
            } else {
                led_state = 0;
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* Clean shutdown */
    printf("\nShutting down...\n");
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

