            }
        } else if (!any_touched && led_state) {
            if (gpioWrite(LED_GPIO, 0) != 0) {
                fprintf(stderr, "Failed to turn off LED on GPIO %d\n", LED_GPIO);
            } else {
                led_state = 0;
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* Clean shutdown */
    printf("\nShutting down...\n");
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

