#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define OPT3001_ADDR        0x44
#define REG_RESULT          0x00
#define REG_CONFIG          0x01
#define CONFIG_CONTINUOUS   0xC810  /* auto-range, 100 ms, continuous */
#define I2C_BUS             1
#define LOG_FILE            "light_data.txt"
#define SAMPLE_INTERVAL_US  1000000 /* 1 second */
#define CONV_WAIT_US        100000  /* 100 ms for first conversion */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* pigpio's i2cReadWordData returns a 16-bit word in little-endian form
 * (low byte first, high byte second).  The OPT3001 sends/receives
 * big-endian (MSB first), so we byte-swap the value. */
static int opt3001_read_lux(int handle, float *lux_out)
{
    int raw = i2cReadWordData(handle, REG_RESULT);
    if (raw < 0) {
        fprintf(stderr, "i2cReadWordData(reg 0x%02X) failed: %s\n",
                REG_RESULT, strerror(errno));
        return -1;
    }

    uint16_t swapped = (uint16_t)((raw & 0xFF) << 8 | (raw >> 8));
    uint16_t exponent = (swapped >> 12) & 0x0F;
    uint16_t mantissa = swapped & 0x0FFF;

    *lux_out = (float)mantissa * 0.01f * (float)(1u << exponent);
    return 0;
}

static int opt3001_write_config(int handle, uint16_t config)
{
    int rc = i2cWriteWordData(handle, REG_CONFIG, config);
    if (rc < 0) {
        fprintf(stderr, "i2cWriteWordData(reg 0x%02X, 0x%04X) failed: %s\n",
                REG_CONFIG, config, strerror(errno));
        return -1;
    }
    return 0;
}

static int log_data(float lux)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        fclose(fp);
        return -1;
    }

    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s, %.2f\n", ts, lux) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "fclose(%s) failed: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "gpioInitialise() failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, OPT3001_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen(bus=%d, addr=0x%02X) failed: %s\n",
                I2C_BUS, OPT3001_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (opt3001_write_config(g_i2c_handle, CONFIG_CONTINUOUS) != 0) {
        fprintf(stderr, "Failed to configure OPT3001\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Allow first conversion to complete before first reading */
    gpioDelay(CONV_WAIT_US);

    while (g_running) {
        float lux;
        if (opt3001_read_lux(g_i2c_handle, &lux) == 0) {
            printf("Lux: %.2f\n", lux);
            if (log_data(lux) != 0) {
                fprintf(stderr, "Logging failed; continuing\n");
            }
        } else {
            fprintf(stderr, "Sensor read failed; will retry next cycle\n");
        }

        /* Sleep in small increments so SIGINT is caught promptly */
        for (int i = 0; i < 10 && g_running; i++) {
            gpioDelay(100000); /* 100 ms */
        }
    }

    fprintf(stderr, "\nShutting down cleanly...\n");
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

