#include <signal.h>
#include <string.h>
#include <errno.h>

#define FLAME_SENSOR_GPIO 4
#define ALERT_GPIO 17
#define LOG_FILE "fire_events.log"
#define POLL_INTERVAL_MS 500
#define ALERT_DURATION_MS 1000

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cleanup(void) {
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(ALERT_GPIO, 0);
    gpioTerminate();
}

static int log_event(int flame_detected) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: localtime() failed\n");
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s - Flame %s\n", timestamp, flame_detected ? "detected" : "not detected") < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int trigger_alert(void) {
    if (gpioWrite(ALERT_GPIO, 1) != 0) {
        fprintf(stderr, "Error setting ALERT_GPIO HIGH\n");
        return -1;
    }

    gpioDelay(ALERT_DURATION_MS * 1000);

    if (gpioWrite(ALERT_GPIO, 0) != 0) {
        fprintf(stderr, "Error setting ALERT_GPIO LOW\n");
        return -1;
    }

    return 0;
}

int main(void) {
    int ret = EXIT_SUCCESS;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting FLAME_SENSOR_GPIO mode\n");
        ret = EXIT_FAILURE;
        goto cleanup;
    }

    if (gpioSetMode(ALERT_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting ALERT_GPIO mode\n");
        ret = EXIT_FAILURE;
        goto cleanup;
    }

    if (gpioWrite(ALERT_GPIO, 0) != 0) {
        fprintf(stderr, "Error initializing ALERT_GPIO to LOW\n");
        ret = EXIT_FAILURE;
        goto cleanup;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        ret = EXIT_FAILURE;
        goto cleanup;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error registering SIGINT handler: %s\n", strerror(errno));
        ret = EXIT_FAILURE;
        goto cleanup;
    }

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int sensor_value = gpioRead(FLAME_SENSOR_GPIO);

        if (sensor_value < 0) {
            fprintf(stderr, "Error reading FLAME_SENSOR_GPIO\n");
            log_event(0);
        } else {
            int flame_detected = (sensor_value == 0);
            if (log_event(flame_detected) != 0) {
                ret = EXIT_FAILURE;
                break;
            }

            if (flame_detected) {
                printf("Flame detected!\n");
                if (trigger_alert() != 0) {
                    ret = EXIT_FAILURE;
                    break;
                }
            }
        }

        gpioDelay(POLL_INTERVAL_MS * 1000);
    }

cleanup:
    cleanup();
    return ret;
}

