#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip4"
#define GPIO_LINE_OFFSET 4
#define LOG_FILE "touch_log.txt"
#define DEBOUNCE_MS 50

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static int log_touch_event(FILE *fp, int touched)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s: Touch %s\n", timestamp, touched ? "Detected" : "Released") < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    FILE *log_fp = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (line == NULL) {
        fprintf(stderr, "Failed to get line %d: %s\n", GPIO_LINE_OFFSET, strerror(errno));
        goto cleanup_chip;
    }

    if (gpiod_line_request_input_flags(line, "ttp223-touch",
                                        GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_DOWN) != 0) {
        fprintf(stderr, "Failed to request line %d as input with pull-down: %s\n",
                GPIO_LINE_OFFSET, strerror(errno));
        goto cleanup_chip;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        fprintf(stderr, "Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        goto cleanup_line;
    }

    int prev_touched = 0;
    int first_read = 1;

    while (program_running) {
        int val = gpiod_line_get_value(line);
        if (val < 0) {
            fprintf(stderr, "Failed to read line %d: %s\n", GPIO_LINE_OFFSET, strerror(errno));
            break;
        }

        int touched = (val == 1);

        if (first_read || (touched != prev_touched)) {
            if (log_touch_event(log_fp, touched) != 0) {
                fprintf(stderr, "Logging failed; aborting.\n");
                break;
            }
            prev_touched = touched;
            first_read = 0;
        }

        usleep(DEBOUNCE_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup_line:
    if (line != NULL) {
        gpiod_line_release(line);
    }

cleanup_chip:
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    if (log_fp != NULL) {
        if (fclose(log_fp) != 0) {
            fprintf(stderr, "fclose failed: %s\n", strerror(errno));
            ret = EXIT_FAILURE;
        }
    }

    return ret;
}

