#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x08
#define FLOW_CMD_MSB   0x36
#define FLOW_CMD_LSB   0x08
#define FLOW_SCALE     90.0f
#define SAMPLE_PERIOD  1.0
#define LOG_FILE       "cooling_log.csv"
#define MAX_FLOW       100.0f
#define MIN_FLOW       0.0f
#define MAX_RAW        10000
#define MIN_RAW        0

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %d\n", I2C_BUS, I2C_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

static int start_measurement(void) {
    uint8_t cmd[2] = { FLOW_CMD_MSB, FLOW_CMD_LSB };
    int rc = i2cWriteDevice(i2c_handle, (char *)cmd, 2);
    if (rc < 0) {
        fprintf(stderr, "Error writing measurement command: %d\n", rc);
        return -1;
    }
    time_sleep(0.002);
    return 0;
}

static int read_flow_rate(float *flow_rate, uint16_t *raw, const char *status) {
    uint8_t buf[3];
    int rc = i2cReadDevice(i2c_handle, (char *)buf, 3);
    if (rc != 3) {
        fprintf(stderr, "Error reading flow data: %d\n", rc);
        return -1;
    }
    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "CRC mismatch on flow data\n");
        return -1;
    }
    int16_t raw_signed = (int16_t)((buf[0] << 8) | buf[1]);
    *raw = (uint16_t)raw_signed;
    *flow_rate = (float)raw_signed / FLOW_SCALE;
    if (*flow_rate < MIN_FLOW || *flow_rate > MAX_FLOW) {
        snprintf(status, sizeof(status), "OUT_OF_RANGE");
        return -1;
    }
    snprintf(status, sizeof(status), "OK");
    return 0;
}

static void log_data(float flow_rate, const char *status) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s,%.2f,%s\n", ts, flow_rate, status);
    fflush(log_file);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    signal(SIGINT, signal_handler);
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }
    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,Flow Rate (ml/min),Status\n");
        fflush(log_file);
    }
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }
    if (start_measurement() != 0) {
        cleanup();
        return 1;
    }
    while (!terminate) {
        float flow_rate;
        uint16_t raw;
        char status[64];
        if (read_flow_rate(&flow_rate, &raw, status) == 0) {
            log_data(flow_rate, status);
        } else {
            fprintf(stderr, "Re-initializing I2C...\n");
            i2cClose(i2c_handle);
            i2c_handle = -1;
            if (init_i2c() != 0) {
                fprintf(stderr, "I2C re-init failed, exiting\n");
                break;
            }
            if (start_measurement() != 0) {
                fprintf(stderr, "Measurement re-init failed, exiting\n");
                break;
            }
        }
        time_sleep(SAMPLE_PERIOD);
    }
    cleanup();
    return 0;
}

