#define CHIP_NAME "gpiochip4"
#define LOG_FILE "flame_events.txt"
#define POLL_TIMEOUT_MS 1000

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void log_event(const char *timestamp) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }
    fprintf(fp, "%s\n", timestamp);
    fclose(fp);
}

static void print_alert(const char *timestamp) {
    printf("ALERT: Flame detected at %s\n", timestamp);
    fflush(stdout);
    log_event(timestamp);
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    struct gpiod_line_event event;
    struct timespec ts;
    char timestamp[32];
    int ret;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
