#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define FLAME_SENSOR_PIN  17   /* KY-026 digital out -> GPIO17 (physical pin 11) */
#define BUZZER_PIN        18   /* Active buzzer control -> GPIO18 (physical pin 12) */
#define POLL_INTERVAL_MS  500
#define BUZZER_DURATION_MS 2000
#define BUZZER_STEP_MS    100
#define LOG_FILE          "alert_log.txt"

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void log_event(const char *msg)
{
    if (!g_log_fp)
        return;

    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    if (t)
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    else
        snprintf(ts, sizeof(ts), "unknown-time");

    fprintf(g_log_fp, "[%s] %s\n", ts, msg);
    fflush(g_log_fp);
}

static void cleanup(void)
{
    /* Ensure buzzer is off */
    if (gpiod_line_set_value(g_buzzer_line, 0) < 0)
        fprintf(stderr, "Warning: failed to turn off buzzer during cleanup: %s\n",
                strerror(errno));

    if (g_buzzer_line)
        gpiod_line_release(g_buzzer_line);

    if (g_flame_line)
        gpiod_line_release(g_flame_line);

    if (g_chip)
        gpiod_chip_close(g_chip);

    if (g_log_fp) {
        log_event("System stopped");
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *flame_line = NULL;
    struct gpiod_line *buzzer_line = NULL;
    int ret = EXIT_FAILURE;

    /* --- Signal handling --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Open log file --- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        return EXIT_FAILURE;
    }

    log_event("System started");

    /* --- Open gpiochip0 --- */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "gpiod_chip_open_by_name: %s\n", strerror(errno));
        goto cleanup;
    }

    /* --- Get lines --- */
    flame_line = gpiod_chip_get_line(chip, FLAME_SENSOR_PIN);
    if (!flame_line) {
        fprintf(stderr, "gpiod_chip_get_line(%d): %s\n", FLAME_SENSOR_PIN, strerror(errno));
        goto cleanup;
    }

    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (!buzzer_line) {
        fprintf(stderr, "gpiod_chip_get_line(%d): %s\n", BUZZER_PIN, strerror(errno));
        goto cleanup;
    }

    /* --- Request flame line as input --- */
    if (gpiod_line_request_input(flame_line, "flame-alert") < 0) {
        fprintf(stderr, "gpiod_line_request_input(flame): %s\n", strerror(errno));
        goto cleanup;
    }

    /* --- Request buzzer line as output, initial value LOW (off) --- */
    if (gpiod_line_request_output(buzzer_line, "flame-alert", 0) < 0) {
        fprintf(stderr, "gpiod_line_request_output(buzzer): %s\n", strerror(errno));
        goto cleanup;
    }

    log_event("Flame sensor monitoring started");

    /* --- Main loop: edge-detect flame transition --- */
    int prev_flame = gpiod_line_get_value(flame_line);
    if (prev_flame < 0) {
        fprintf(stderr, "Initial gpiod_line_get_value(flame): %s\n", strerror(errno));
        goto cleanup;
    }

    while (g_running) {
        int flame = gpiod_line_get_value(flame_line);
        if (flame < 0) {
            fprintf(stderr, "gpiod_line_get_value(flame): %s\n", strerror(errno));
            break;
        }

        /* Detect HIGH->LOW transition: flame just detected */
        if (prev_flame == 1 && flame == 0) {
            char msg[128];
            snprintf(msg, sizeof(msg), "Flame detected!");
            log_event(msg);
            printf("%s\n", msg);

            /* Activate buzzer for 2 s in 100 ms slices so we can respond to signals */
            for (int i = 0; i < BUZZER_DURATION_MS / BUZZER_STEP_MS && g_running; i++) {
                if (gpiod_line_set_value(buzzer_line, 1) < 0) {
                    fprintf(stderr, "gpiod_line_set_value(buzzer ON): %s\n", strerror(errno));
                    goto cleanup;
                }
                usleep(BUZZER_STEP_MS * 1000);
                if (gpiod_line_set_value(buzzer_line, 0) < 0) {
                    fprintf(stderr, "gpiod_line_set_value(buzzer OFF): %s\n", strerror(errno));
                    goto cleanup;
                }
                usleep(BUZZER_STEP_MS * 1000);
            }
        }

        prev_flame = flame;
        usleep(POLL_INTERVAL_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    cleanup();
    return ret;
}

