    int last_state = 0;
    uint32_t last_event_tick = 0;
    int ret = EXIT_SUCCESS;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input\n", TOUCH_SENSOR_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output\n", LED_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioWrite(LED_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise LED state on GPIO%d\n", LED_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: cannot open log file '%s': %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction(SIGINT) failed: %s\n", strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction(SIGTERM) failed: %s\n", strerror(errno));
    }

    printf("Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int current_state = gpioRead(TOUCH_SENSOR_PIN);
        if (current_state < 0) {
            fprintf(stderr, "Error: gpioRead failed on GPIO%d\n", TOUCH_SENSOR_PIN);
            ret = EXIT_FAILURE;
            break;
        }

        uint32_t now = gpioTick();

        if (current_state == 1 && last_state == 0) {
            if (now - last_event_tick >= DEBOUNCE_MS * 1000) {
                last_event_tick = now;
                log_touch_event();
                if (gpioWrite(LED_PIN, !gpioRead(LED_PIN)) != 0) {
                    fprintf(stderr, "Error: gpioWrite failed on LED\n");
                    ret = EXIT_FAILURE;
                    break;
                }
            }
        }

        last_state = current_state;
        gpioDelay(POLL_INTERVAL_US);
    }

    cleanup();
    return ret;
}

