#include <errno.h>

#define SENSOR1_PIN 4
#define SENSOR2_PIN 17
#define SENSOR3_PIN 27
#define LOG_FILE "magnet_log.txt"
#define POLL_DELAY_US 100000  /* 100 ms */

/* TMAG5110A1 latch: OUT is open-drain, internal pull-up enabled.
 *   LOW  = magnet present (south pole)
 *   HIGH = magnet absent (north pole or no magnet)
 */
typedef enum { STATE_MAGNET_PRESENT = 0, STATE_MAGNET_ABSENT = 1 } sensor_state_t;

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static void log_event(FILE *fp, int sensor_id, sensor_state_t state)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    if (fprintf(fp, "%s - Sensor %d: %s\n",
                timestamp, sensor_id,
                state == STATE_MAGNET_PRESENT ? "Magnet Present" : "Magnet Absent") < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
    }
}

static int initialize_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    int pins[] = { SENSOR1_PIN, SENSOR2_PIN, SENSOR3_PIN };
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
        if (gpioSetMode(pins[i], PI_INPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as input\n", pins[i]);
            return -1;
        }
        if (gpioSetPullUpDown(pins[i], PI_PUD_UP) != 0) {
            fprintf(stderr, "Failed to set pull-up on GPIO %d\n", pins[i]);
            return -1;
        }
    }
    return 0;
}

static void cleanup(void)
{
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Magnet sensor monitoring started. Press Ctrl+C to exit.\n");

    int prev_state[3];
    for (int i = 0; i < 3; ++i) {
        prev_state[i] = gpioRead(i + 1);  /* BCM numbering: 1=GPIO4, 2=GPIO17, 3=GPIO27 */
    }

    while (program_running) {
        for (int i = 0; i < 3; ++i) {
            int current = gpioRead(i + 1);
            if (current < 0) {
                fprintf(stderr, "Error reading GPIO %d\n", i + 1);
                continue;
            }

            if (current != prev_state[i]) {
                log_event(log_file, i + 1, current);
                prev_state[i] = current;
            }
        }
        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

