#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SI1182_ADDR 0x4A

#define REG_PART_ID 0x00
#define REG_HW_REV 0x01
#define REG_LED_CURRENT 0x3F
#define REG_AVG_RATE 0x04
#define REG_ENABLE 0x01
#define REG_HR_DATA 0x2A

#define MOVING_AVG_SIZE 5
#define MIN_BPM 30
#define MAX_BPM 220

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_register(int handle, uint8_t reg, uint8_t *value) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, result);
        return -1;
    }
    *value = (uint8_t)result;
    return 0;
}

static int write_register(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

static int initialize_sensor(int handle) {
    uint8_t part_id, hw_rev;

    if (read_register(handle, REG_PART_ID, &part_id) != 0) {
        fprintf(stderr, "Failed to read PART_ID\n");
        return -1;
    }
    if (part_id != 0x02) {
        fprintf(stderr, "Unexpected PART_ID: 0x%02X (expected 0x02)\n", part_id);
        return -1;
    }

    if (read_register(handle, REG_HW_REV, &hw_rev) != 0) {
        fprintf(stderr, "Failed to read HW_REV\n");
        return -1;
    }
    if (hw_rev != 0x01) {
        fprintf(stderr, "Unexpected HW_REV: 0x%02X (expected 0x01)\n", hw_rev);
        return -1;
    }

    if (write_register(handle, REG_LED_CURRENT, 0x0F) != 0) return -1;
    if (write_register(handle, REG_AVG_RATE, 0x04) != 0) return -1;
    if (write_register(handle, REG_ENABLE, 0x01) != 0) return -1;

    return 0;
}

static int read_heart_rate(int handle, int *bpm) {
    int raw = i2cReadWordData(handle, REG_HR_DATA);
    if (raw < 0) {
        fprintf(stderr, "Error reading heart-rate data: %d\n", raw);
        return -1;
    }
    *bpm = (int)(raw * 0.5);
    return 0;
}

static int moving_average(int new_value, int *buffer, int size, int *index, int *sum) {
    *sum -= buffer[*index];
    buffer[*index] = new_value;
    *sum += new_value;
    *index = (*index + 1) % size;
    return 0;
}

static int validate_bpm(int bpm) {
    return (bpm >= MIN_BPM && bpm <= MAX_BPM);
}

static int log_data(int bpm) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s,%d\n", timestamp, bpm) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }
    fflush(log_file);
    return 0;
}

int main(void) {
    int buffer[MOVING_AVG_SIZE] = {0};
    int buffer_index = 0;
    int buffer_sum = 0;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI1182_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (initialize_sensor(i2c_handle) != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen("heart_rate.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    printf("Heart-rate monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int bpm = 0;
        if (read_heart_rate(i2c_handle, &bpm) != 0) {
            fprintf(stderr, "Error reading heart-rate, retrying...\n");
            gpioDelay(100000);
            continue;
        }

        moving_average(bpm, buffer, MOVING_AVG_SIZE, &buffer_index, &buffer_sum);

        if (validate_bpm(buffer_sum / MOVING_AVG_SIZE)) {
