/*
 * TTP226 8-channel capacitive touch sensor -> 8-bit binary counter display.
 *
 * Board:  Raspberry Pi Zero W
 * Sensor: TTP226 module (active-high, 3.3 V touched, 0 V idle)
 *   OUT1 -> GPIO 5   OUT2 -> GPIO 6   OUT3 -> GPIO 7
 *   OUT4 -> GPIO 8   OUT5 -> GPIO 9   OUT6 -> GPIO 10
 *   OUT7 -> GPIO 11  OUT8 -> GPIO 12
 *   Counter MSB (bit 7) -> GPIO 17
 *   Counter LSB (bit 0) -> GPIO 24
 *
 * Build:  gcc -O2 -Wall -Wextra -o touch_counter touch_counter.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_CHANNELS 8
#define STABILIZE_MS  200
#define POLL_MS       10
#define LOG_FILE      "touch_log.txt"

static const unsigned int sensor_pins[NUM_CHANNELS] = {5, 6, 7, 8, 9, 10, 11, 12};
static const unsigned int counter_output_pins[NUM_CHANNELS] = {17, 18, 19, 20, 21, 22, 23, 24};

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void log_touch_event(int channel, int counter)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Warning: cannot open %s: %s\n",
                LOG_FILE, strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02dT%02d:%02d:%02dZ, Channel: %d, Counter: %d\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, channel, counter);
        fflush(fp);
    } else {
        fprintf(stderr, "Warning: localtime_r failed: %s\n", strerror(errno));
    }
}

static void print_touch_event(int channel, int counter)
{
    printf("Touch on channel %d | Counter: %d\n", channel, counter);
    fflush(stdout);
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line_request *sensor_req = NULL;
    struct gpiod_line_request *counter_req = NULL;
    struct gpiod_line_settings *settings = NULL;
    struct gpiod_line_config *line_cfg = NULL;
    struct gpiod_request_config *req_cfg = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "gpiod_chip_open(/dev/gpiochip0): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    settings = gpiod_line_settings_new();
    if (!settings) {
        fprintf(stderr, "gpiod_line_settings_new: %s\n", strerror(errno));
        goto cleanup;
    }
    gpiod_line_settings_set_direction(settings, GPIOD_LINE_DIRECTION_INPUT);

    line_cfg = gpiod_line_config_new();
    if (!line_cfg) {
        fprintf(stderr, "gpiod_line_config_new: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_config_add_line_settings(line_cfg, sensor_pins, NUM_CHANNELS,
                                            settings) < 0) {
        fprintf(stderr, "gpiod_line_config_add_line_settings: %s\n",
                strerror(errno));
        goto cleanup;
    }

    req_cfg = gpiod_request_config_new();
    if (!req_cfg) {
        fprintf(stderr, "gpiod_request_config_new: %s\n", strerror(errno));
        goto cleanup;
    }
    gpiod_request_config_set_consumer(req_cfg, "ttp226-sensor");

    sensor_req = gpiod_chip_request_lines(chip, req_cfg, line_cfg);
    if (!sensor_req) {
        fprintf(stderr, "gpiod_chip_request_lines(sensor): %s\n",
                strerror(errno));
        goto cleanup;
    }

    settings = gpiod_line_settings_new();
    if (!settings) {
        fprintf(stderr, "gpiod_line_settings_new: %s\n", strerror(errno));
        goto cleanup;
    }
    gpiod_line_settings_set_direction(settings, GPIOD_LINE_DIRECTION_OUTPUT);

    line_cfg = gpiod_line_config_new();
    if (!line_cfg) {
        fprintf(stderr, "gpiod_line_config_new: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_config_add_line_settings(line_cfg, counter_output_pins,
                                            NUM_CHANNELS, settings) < 0) {
        fprintf(stderr, "gpiod_line_config_add_line_settings(counter): %s\n",
                strerror(errno));
        goto cleanup;
    }

    req_cfg = gpiod_request_config_new();
    if (!req_cfg) {
        fprintf(stderr, "gpiod_request_config_new: %s\n", strerror(errno));
        goto cleanup;
    }
    gpiod_request_config_set_consumer(req_cfg, "ttp226-counter");

    counter_req = gpiod_chip_request_lines(chip, req_cfg, line_cfg);
    if (!counter_req) {
        fprintf(stderr, "gpiod_chip_request_lines(counter): %s\n",
                strerror(errno));
        goto cleanup;
    }

    /* Stabilize the sensor lines before starting polling */
    if (gpiod_line_request_set_value(counter_req, 0, 0) < 0) {
        fprintf(stderr, "Initial counter reset: %s\n", strerror(errno));
    }
    if (gpiod_line_request_set_value(sensor_req, 0, 0) < 0) {
        fprintf(stderr, "Initial sensor reset: %s\n", strerror(errno));
    }
    usleep(STABILIZE_MS * 1000);

    int counter = 0;
    int prev_state[NUM_CHANNELS];
    for (int i = 0; i < NUM_CHANNELS; i++)
        prev_state[i] = 0;

    while (g_running) {
        int touched = 0;
        for (int i = 0; i < NUM_CHANNELS; i++) {
            int val = gpiod_line_request_get_value(sensor_req, sensor_pins[i]);
            if (val < 0) {
                fprintf(stderr, "gpiod_line_request_get_value(channel %d): %s\n",
                        i + 1, strerror(errno));
                continue;
            }
            if (val == 1 && prev_state[i] == 0) {
                counter++;
                if (counter > 255) counter = 0;
                if (gpiod_line_request_set_value(counter_req, counter_output_pins[i], 1) < 0) {
                    fprintf(stderr, "gpiod_line_request_set_value(counter %d): %s\n",
                            i + 1, strerror(errno));
                }
                touched = 1;
            }
            prev_state[i] = val;
        }

        if (touched) {
            log_touch_event(touched, counter);
            print_touch_event(touched, counter);
        }

        usleep(POLL_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (counter_req)
        gpiod_line_request_set_value(counter_req, 0, 0);
    if (counter_req)
        gpiod_line_request_release(counter_req);
    if (req_cfg)
        gpiod_request_config_free(req_cfg);
    if (line_cfg)
        gpiod_line_config_free(line_cfg);
    if (settings)
        gpiod_line_settings_free(settings);
    if (sensor_req)
        gpiod_line_request_release(sensor_req);
    if (chip)
        gpiod_chip_close(chip);

    if (ret == EXIT_SUCCESS)
        printf("Exiting cleanly.\n");
    return ret;
}

