#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip4"
#define GPIO_17 17
#define GPIO_18 18
#define LOG_FILE "/var/log/tilt_events.log"
#define POLL_INTERVAL_US 100000
#define DEBOUNCE_US 50000

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line17 = NULL;
static struct gpiod_line *line18 = NULL;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void log_event(int sensor_number) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: localtime failed\n");
        return;
    }
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Sensor %d tilted\n", timestamp, sensor_number);
        fflush(log_file);
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

static void cleanup(void) {
    if (line17 != NULL) {
        gpiod_line_release(line17);
        line17 = NULL;
    }
    if (line18 != NULL) {
        gpiod_line_release(line18);
        line18 = NULL;
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    int ret;
    int prev17 = 1, prev18 = 1;
    struct timespec ts = {0, POLL_INTERVAL_US * 1000};

    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        perror("gpiod_chip_open_by_name");
        cleanup();
        return EXIT_FAILURE;
    }

    line17 = gpiod_chip_get_line(chip, GPIO_17);
    if (line17 == NULL) {
        perror("gpiod_chip_get_line(17)");
        cleanup();
        return EXIT_FAILURE;
    }

    line18 = gpiod_chip_get_line(chip, GPIO_18);
    if (line18 == NULL) {
        perror("gpiod_chip_get_line(18)");
        cleanup();
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_input_flags(line17, "tilt-monitor",
                                          GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP);
    if (ret < 0) {
        perror("gpiod_line_request_input_flags(17)");
        cleanup();
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_input_flags(line18, "tilt-monitor",
                                          GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP);
    if (ret < 0) {
        perror("gpiod_line_request_input_flags(18)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Tilt sensor monitoring started on GPIO17 and GPIO18. Press Ctrl+C to exit.\n");

    while (program_running) {
        int val17 = gpiod_line_get_value(line17);
        int val18 = gpiod_line_get_value(line18);

        if (val17 < 0) {
            perror("gpiod_line_get_value(17)");
            break;
        }
        if (val18 < 0) {
            perror("gpiod_line_get_value(18)");
            break;
        }

        if (val17 == 0 && prev17 == 1) {
            log_event(1);
        }
        if (val18 == 0 && prev18 == 1) {
            log_event(2);
        }

        prev17 = val17;
        prev18 = val18;

        nanosleep(&ts, NULL);
    }

    cleanup();
    printf("Tilt sensor monitoring stopped.\n");
    return EXIT_SUCCESS;
}

