#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define SENSOR1_PIN 17
#define SENSOR2_PIN 27
#define LED_PIN     22
#define LOG_FILE    "obstacle_log.csv"
#define POLL_MS     100

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    running = 0;
}

static int log_sample(FILE *fp, int s1, int s2, int led)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (!localtime_r(&t, &tm)) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%d,%d,%d\n", ts, s1, s2, led) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *s1 = NULL, *s2 = NULL, *led = NULL;
    FILE *fp = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "gpiod_chip_open_by_name failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    s1 = gpiod_chip_get_line(chip, SENSOR1_PIN);
    s2 = gpiod_chip_get_line(chip, SENSOR2_PIN);
    led = gpiod_chip_get_line(chip, LED_PIN);
    if (!s1 || !s2 || !led) {
        fprintf(stderr, "gpiod_chip_get_line failed: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input(s1, "tcrt5000") != 0) {
        fprintf(stderr, "request_input sensor1 failed: %s\n", strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_input(s2, "tcrt5000") != 0) {
        fprintf(stderr, "request_input sensor2 failed: %s\n", strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_output(led, "obstacle_led", 0) != 0) {
        fprintf(stderr, "request_output led failed: %s\n", strerror(errno));
        goto cleanup;
    }

    fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        goto cleanup;
    }

    printf("Logging started. Press Ctrl+C to stop.\n");

    while (running) {
        int v1 = gpiod_line_get_value(s1);
        int v2 = gpiod_line_get_value(s2);
        int led_state = (v1 == 0 && v2 == 0) ? 1 : 0;

        if (gpiod_line_set_value(led, led_state) != 0) {
            fprintf(stderr, "set_value led failed: %s\n", strerror(errno));
            break;
        }

        if (log_sample(fp, v1, v2, led_state) != 0) {
            fprintf(stderr, "Logging failed; aborting.\n");
            break;
        }

        usleep(POLL_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (led) gpiod_line_set_value(led, 0);
    if (s1)  gpiod_line_release(s1);
    if (s2)  gpiod_line_release(s2);
    if (led) gpiod_line_release(led);
    if (chip) gpiod_chip_close(chip);
    if (fp)  fclose(fp);
    return ret;
}

