#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define MIC_GPIO 4
#define LED_GPIO 17
#define SAMPLE_PERIOD_US 125000  /* 8 kHz sampling */
#define LED_ON_US 100000         /* 100 ms LED pulse */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

static void print_timestamp_ms(void)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) == 0) {
        struct tm tm_info;
        localtime_r(&ts.tv_sec, &tm_info);
        printf("%04d-%02d-%02d %02d:%02d:%02d.%03ld",
               tm_info.tm_year + 1900, tm_info.tm_mon + 1, tm_info.tm_mday,
               tm_info.tm_hour, tm_info.tm_min, tm_info.tm_sec,
               ts.tv_nsec / 1000000);
    } else {
        printf("[timestamp-error]");
    }
    printf("\n");
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(MIC_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", MIC_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(LED_GPIO, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise LED GPIO%d LOW.\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install SIGINT handler.\n");
    }

    printf("Monitoring ICS-40180 microphone on GPIO%d. Press Ctrl+C to exit.\n",
           MIC_GPIO);

    while (running) {
        int mic_value = gpioRead(MIC_GPIO);
        if (mic_value < 0) {
            fprintf(stderr, "Error: gpioRead failed on GPIO%d.\n", MIC_GPIO);
            break;
        }

        if (mic_value == 1) {
            print_timestamp_ms();
            if (gpioWrite(LED_GPIO, 1) != 0) {
                fprintf(stderr, "Error: gpioWrite failed to turn LED on.\n");
                break;
            }
            gpioDelay(LED_ON_US);
            if (gpioWrite(LED_GPIO, 0) != 0) {
                fprintf(stderr, "Error: gpioWrite failed to turn LED off.\n");
                break;
            }
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* Clean shutdown */
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

