#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <errno.h>
#include <string.h>

#define LEFT_SENSOR_PIN 17
#define CENTER_SENSOR_PIN 27
#define RIGHT_SENSOR_PIN 22
#define POLL_INTERVAL_MS 100

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *left_line = NULL;
    struct gpiod_line *center_line = NULL;
    struct gpiod_line *right_line = NULL;
    int ret = EXIT_FAILURE;

    /* Register signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on Raspberry Pi 4) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Get the GPIO lines */
    left_line = gpiod_chip_get_line(chip, LEFT_SENSOR_PIN);
    center_line = gpiod_chip_get_line(chip, CENTER_SENSOR_PIN);
    right_line = gpiod_chip_get_line(chip, RIGHT_SENSOR_PIN);

    if (!left_line || !center_line || !right_line) {
        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Request each line as input with pull-up enabled */
    if (gpiod_line_request_input_flags(left_line, "tracing-sensor", GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
        fprintf(stderr, "Failed to request left line as input: %s\n", strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_input_flags(center_line, "tracing-sensor", GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
        fprintf(stderr, "Failed to request center line as input: %s\n", strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_input_flags(right_line, "tracing-sensor", GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
        fprintf(stderr, "Failed to request right line as input: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("Tracing sensor monitoring started. Press Ctrl+C to exit.\n");

    /* Main polling loop */
    while (program_running) {
        int left_val, center_val, right_val;

        left_val = gpiod_line_get_value(left_line);
        if (left_val < 0) {
            fprintf(stderr, "Error reading left sensor: %s\n", strerror(errno));
            goto cleanup;
        }

        center_val = gpiod_line_get_value(center_line);
        if (center_val < 0) {
            fprintf(stderr, "Error reading center sensor: %s\n", strerror(errno));
            goto cleanup;
        }

        right_val = gpiod_line_get_value(right_line);
        if (right_val < 0) {
            fprintf(stderr, "Error reading right sensor: %s\n", strerror(errno));
            goto cleanup;
        }

        printf("Left: %d, Center: %d, Right: %d\n", left_val, center_val, right_val);

        usleep(POLL_INTERVAL_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip */
    if (left_line) gpiod_line_release(left_line);
    if (center_line) gpiod_line_release(center_line);
    if (right_line) gpiod_line_release(right_line);
    if (chip) gpiod_chip_close(chip);

    if (ret == EXIT_SUCCESS) {
        printf("\nExiting gracefully.\n");
    }
    return ret;
}

