#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

#define LEFT_PIN 2
#define MIDDLE_PIN 3
#define RIGHT_PIN 4
#define POLL_INTERVAL_MS 100

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *left_line = NULL;
    struct gpiod_line *middle_line = NULL;
    struct gpiod_line *right_line = NULL;
    int ret = EXIT_FAILURE;

    /* Install SIGINT handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on RPi 3B+) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Get lines for the three GPIO pins */
    left_line = gpiod_chip_get_line(chip, LEFT_PIN);
    if (!left_line) {
        fprintf(stderr, "Failed to get line %d: %s\n", LEFT_PIN, strerror(errno));
        goto cleanup;
    }
    middle_line = gpiod_chip_get_line(chip, MIDDLE_PIN);
    if (!middle_line) {
        fprintf(stderr, "Failed to get line %d: %s\n", MIDDLE_PIN, strerror(errno));
        goto cleanup;
    }
    right_line = gpiod_chip_get_line(chip, RIGHT_PIN);
    if (!right_line) {
        fprintf(stderr, "Failed to get line %d: %s\n", RIGHT_PIN, strerror(errno));
        goto cleanup;
    }

    /* Request each line individually as input */
    if (gpiod_line_request_input(left_line, "3way_sensor_left") < 0) {
        fprintf(stderr, "Failed to request line %d as input: %s\n", LEFT_PIN, strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_input(middle_line, "3way_sensor_middle") < 0) {
        fprintf(stderr, "Failed to request line %d as input: %s\n", MIDDLE_PIN, strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_input(right_line, "3way_sensor_right") < 0) {
        fprintf(stderr, "Failed to request line %d as input: %s\n", RIGHT_PIN, strerror(errno));
        goto cleanup;
    }

    printf("3-Way Tracking Sensor Reader\n");
    printf("Left  (GPIO%d) | Middle (GPIO%d) | Right (GPIO%d)\n",
           LEFT_PIN, MIDDLE_PIN, RIGHT_PIN);
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    /* Main polling loop */
    while (running) {
        int left_val = gpiod_line_get_value(left_line);
        int middle_val = gpiod_line_get_value(middle_line);
        int right_val = gpiod_line_get_value(right_line);

        if (left_val < 0 || middle_val < 0 || right_val < 0) {
            fprintf(stderr, "Error reading sensor values: %s\n", strerror(errno));
            break;
        }

        printf("L:%d M:%d R:%d\n", left_val, middle_val, right_val);
        fflush(stdout);

        usleep(POLL_INTERVAL_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines individually (safe to call even if request failed) */
    if (left_line) gpiod_line_release(left_line);
    if (middle_line) gpiod_line_release(middle_line);
    if (right_line) gpiod_line_release(right_line);
    if (chip) gpiod_chip_close(chip);

    if (ret == EXIT_SUCCESS) {
        printf("\nExiting gracefully.\n");
    }
    return ret;
}

