/* HSV -> RGB (saturated, fully saturated, value = 1.0). */
static void hsv_to_rgb(float h, float s, float v, int *r, int *g, int *b)
{
    if (s <= 0.0f) {
        *r = (int)(v * 255.0f);
        *g = (int)(v * 255.0f);
        *b = (int)(v * 255.0f);
        return;
    }

    h = fmodf(h, 360.0f);
    if (h < 0.0f) h += 360.0f;

    float hh = h / 60.0f;
    int   i  = (int)hh;
    float f  = hh - (float)i;
    float p  = v * (1.0f - s);
    float q  = v * (1.0f - s * f);
    float t  = v * (1.0f - s * (1.0f - f));

    switch (i) {
    case 0: { *r = (int)(v * 255.0f); *g = (int)(t * 255.0f); *b = (int)(p * 255.0f); break; }
    case 1: { *r = (int)(q * 255.0f); *g = (int)(v * 255.0f); *b = (int)(p * 255.0f); break; }
    case 2: { *r = (int)(p * 255.0f); *g = (int)(v * 255.0f); *b = (int)(t * 255.0f); break; }
    case 3: { *r = (int)(p * 255.0f); *g = (int)(q * 255.0f); *b = (int)(v * 255.0f); break; }
    case 4: { *r = (int)(t * 255.0f); *g = (int)(p * 255.0f); *b = (int)(v * 255.0f); break; }
    default: { *r = (int)(v * 255.0f); *g = (int)(p * 255.0f); *b = (int)(q * 255.0f); break; }
    }
}

static int set_led_color(int r, int g, int b)
{
    int inv_r = 255 - r;
    int inv_g = 255 - g;
    int inv_b = 255 - b;

    if (gpioPWM(RED_PIN, inv_r) < 0) {
        syslog(LOG_ERR, "gpioPWM(RED) failed: %s", pigpio_error(gpioGetMode(RED_PIN)));
        return -1;
    }
    if (gpioPWM(GREEN_PIN, inv_g) < 0) {
        syslog(LOG_ERR, "gpioPWM(GREEN) failed: %s", pigpio_error(gpioGetMode(GREEN_PIN)));
        return -1;
    }
    if (gpioPWM(BLUE_PIN, inv_b) < 0) {
        syslog(LOG_ERR, "gpioPWM(BLUE) failed: %s", pigpio_error(gpioGetMode(BLUE_PIN)));
        return -1;
    }
    return 0;
}

static int fade_step(int r, int g, int b, int *cur_r, int *cur_g, int *cur_b, int step)
{
    int dr = (r - *cur_r) / FADE_STEP;
    int dg = (g - *cur_g) / FADE_STEP;
    int db = (b - *cur_b) / FADE_STEP;

    if (dr > 0)  *cur_r += dr;
    else        *cur_r -= dr;
    if (dr > 255) *cur_r = 255;
    if (dr < 0)  *cur_r = 0;

    if (dg > 0)  *cur_g += dg;
    else        *cur_g -= dg;
    if (dg > 255) *cur_g = 255;
    if (dg < 0)  *cur_g = 0;

    if (db > 0)  *cur_b += db;
    else        *cur_b -= db;
    if (db > 255) *cur_b = 255;
    if (db < 0)  *cur_b = 0;

    return set_led_color(*cur_r, *cur_g, *cur_b);
}

int main(void)
{
    openlog("mood_lamp", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "sigaction failed: %s", pigpio_error(sigaction(SIGINT, &sa, NULL)));
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    int pins[3] = { RED_PIN, GREEN_PIN, BLUE_PIN };
    for (int i = 0; i < 3; i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) < 0) {
            syslog(LOG_ERR, "gpioSetMode(%d) failed", pins[i]);
            gpioTerminate();
            closelog();
            return EXIT_FAILURE;
        }
    }

    if (gpioSetPWMfrequency(RED_PIN, PWM_FREQ) < 0 ||
        gpioSetPWMfrequency(GREEN_PIN, PWM_FREQ) < 0 ||
        gpioSetPWMfrequency(BLUE_PIN, PWM_FREQ) < 0) {
        syslog(LOG_ERR, "gpioSetPWMfrequency failed");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(RED_PIN, PWM_RANGE) < 0 ||
        gpioSetPWMrange(GREEN_PIN, PWM_RANGE) < 0 ||
        gpioSetPWMrange(BLUE_PIN, PWM_RANGE) < 0) {
        syslog(LOG_ERR, "gpioSetPWMrange failed");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    srand((unsigned int)time(NULL));

    int cur_r = 0, cur_g = 0, cur_b = 0;
    int hue = (rand() % 360) + 1;

    syslog(LOG_INFO, "Mood lamp started (pins %d/%d/%d, PWM %d Hz, range %d)",
           RED_PIN, GREEN_PIN, BLUE_PIN, PWM_FREQ, PWM_RANGE);

    while (g_running) {
        int r, g, b;
        hsv_to_rgb((float)hue, 1.0f, 1.0f, &r, &g, &b);

        syslog(LOG_INFO, "Fading to hue %d (R=%d G=%d B=%d)", hue, r, g, b);

        for (int i = 0; i < FADE_STEP && g_running; i++) {
            if (fade_step(r, g, b, &cur_r, &cur_g, &cur_b, FADE_STEP - i) != 0) {
                syslog(LOG_ERR, "LED update failed during fade");
                break;
            }
        }

        if (g_running) {
            usleep(STEP_DELAY);
        }
    }

    syslog(LOG_INFO, "Shutting down...");
    set_led_color(0, 0, 0);
    gpioTerminate();
    closelog();
    return EXIT_SUCCESS;
}

