/*
 * TCS34725 color sensor reader for Raspberry Pi 4 Model B
 * Uses libgpiod for GPIO and Linux i2c-dev for I2C.
 *
 * Wiring:
 *   TCS34725 SDA -> GPIO2 (pin 3, I2C bus 1)
 *   TCS34725 SCL -> GPIO3 (pin 5, I2C bus 1)
 *   TCS34725 VDD -> 3.3 V
 *   TCS34725 GND -> GND
 *   LED anode   -> GPIO17 (pin 11) through 330 ohm resistor -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o tcs34725 tcs34725.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define TCS34725_ADDR  0x29

#define TCS34725_CMD_BIT  0x80
#define TCS34725_REG     0x00
#define TCS34725_ENABLE  0x01
#define TCS34725_ATIME   0x0E
#define TCS34725_ID      0x12
#define TCS34725_CDATA   0x14
#define TCS34725_RDATA   0x16
#define TCS34725_GDATA   0x18
#define TCS34725_BDATA   0x1A
#define TCS34725_CONTROL 0x0F

#define LED_PIN          17
#define RED_THRESHOLD    200
#define POLL_MS          200

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write16(int fd, uint8_t reg, uint16_t val)
{
    uint8_t buf[3];
    buf[0] = reg | TCS34725_CMD_BIT;
    buf[1] = (uint8_t)(val & 0xFF);
    buf[2] = (uint8_t)((val >> 8) & 0xFF);
    if (write(fd, buf, 3) != 3) {
        fprintf(stderr, "i2c_write16(0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read16(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t cmd = reg | TCS34725_CMD_BIT;
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "i2c_read16 write(0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "i2c_read16 read(0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    *out = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

static int tcs34725_init(int fd)
{
    uint16_t id = 0;
    if (i2c_read16(fd, TCS34725_ID, &id) < 0)
        return -1;
    if (id != 0x44) {
        fprintf(stderr, "Unexpected ID 0x%04X (expected 0x44)\n", id);
        return -1;
    }

    if (i2c_write16(fd, TCS34725_ENABLE, 0x00) < 0)
        return -1;
    if (i2c_write16(fd, TCS34725_ATIME, 0x00) < 0)
        return -1;
    if (i2c_write16(fd, TCS34725_CONTROL, 0x00) < 0)
        return -1;
    if (i2c_write16(fd, TCS34725_ENABLE, 0x01) < 0)
        return -1;
    return 0;
}

static int tcs34725_read(int fd, uint16_t *c, uint16_t *r, uint16_t *g, uint16_t *b)
{
    if (i2c_read16(fd, TCS34725_CDATA, c) < 0) return -1;
    if (i2c_read16(fd, TCS34725_RDATA, r) < 0) return -1;
    if (i2c_read16(fd, TCS34725_GDATA, g) < 0) return -1;
    if (i2c_read16(fd, TCS34725_BDATA, b) < 0) return -1;
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "open(%s): %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, TCS34725_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n", TCS34725_ADDR, strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (tcs34725_init(i2c_fd) < 0) {
        fprintf(stderr, "TCS34725 initialization failed\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        chip = gpiod_chip_open_by_name("gpiochip0");
    }
    if (!chip) {
        fprintf(stderr, "gpiod_chip_open: %s\n", strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }
    struct gpiod_line *led = gpiod_chip_get_line(chip, LED_PIN);
    if (!led) {
        fprintf(stderr, "gpiod_chip_get_line(%d): %s\n", LED_PIN, strerror(errno));
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_output(led, "tcs34725-led", 0) < 0) {
        fprintf(stderr, "gpiod_line_request_output: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    printf("TCS34725 initialized. Reading every %d ms. Press Ctrl+C to exit.\n", POLL_MS);

    while (g_running) {
        uint16_t c, r, g, b;
        if (tcs34725_read(i2c_fd, &c, &r, &g, &b) < 0) {
            fprintf(stderr, "Read error, re-initializing sensor...\n");
            if (tcs34725_init(i2c_fd) < 0) {
                fprintf(stderr, "Re-init failed, exiting.\n");
                break;
            }
            continue;
        }

        /* Per-channel calibration (typical values for TCS34725, gain=1) */
        float r_cal = (float)r * 0.5f - 50.0f;
        float g_cal = (float)g * 0.5f - 50.0f;
        float b_cal = (float)b * 0.5f - 50.0f;
        float c_cal = (float)c * 0.5f - 50.0f;

        printf("C: %5.1f  R: %5.1f  G: %5.1f  B: %5.1f\n", c_cal, r_cal, g_cal, b_cal);

        int led_val = (r_cal > RED_THRESHOLD) ? 1 : 0;
        if (gpiod_line_set_value(led, led_val) < 0) {
            fprintf(stderr, "gpiod_line_set_value: %s\n", strerror(errno));
        }

        struct timespec ts = { .tv_sec = 0, .tv_nsec = POLL_MS * 1000000L };
        nanosleep(&ts, NULL);
    }

    /* Cleanup */
    gpiod_line_set_value(led, 0);
    gpiod_line_release(led);
    gpiod_chip_close(chip);
    close(i2c_fd);
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

