    if (i2c_read16(fd, TCS34725_ID, &id) < 0)
        return -1;
    if (id != 0x44) {
        fprintf(stderr, "Unexpected ID 0x%04X (expected 0x44)\n", id);
        return -1;
    }

    if (i2c_write16(fd, TCS34725_ENABLE, 0x00) < 0)
        return -1;
    if (i2c_write16(fd, TCS34725_ATIME, 0x00) < 0)
        return -1;
    if (i2c_write16(fd, TCS34725_CONTROL, 0x00) < 0)
        return -1;
    if (i2c_write16(fd, TCS34725_ENABLE, 0x01) < 0)
        return -1;
    return 0;
}

static int tcs34725_read(int fd, uint16_t *c, uint16_t *r, uint16_t *g, uint16_t *b)
{
    if (i2c_read16(fd, TCS34725_CDATA, c) < 0) return -1;
    if (i2c_read16(fd, TCS34725_RDATA, r) < 0) return -1;
    if (i2c_read16(fd, TCS34725_GDATA, g) < 0) return -1;
    if (i2c_read16(fd, TCS34725_BDATA, b) < 0) return -1;
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "open(%s): %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, TCS34725_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n", TCS34725_ADDR, strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (tcs34725_init(i2c_fd) < 0) {
        fprintf(stderr, "TCS34725 initialization failed\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        chip = gpiod_chip_open_by_name("gpiochip0");
    }
    if (!chip) {
        fprintf(stderr, "gpiod_chip_open: %s\n", strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }
    struct gpiod_line *led = gpiod_chip_get_line(chip, LED_PIN);
    if (!led) {
        fprintf(stderr, "gpiod_chip_get_line(%d): %s\n", LED_PIN, strerror(errno));
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_output(led, "tcs34725-led", 0) < 0) {
        fprintf(stderr, "gpiod_line_request_output: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    printf("TCS34725 initialized. Reading every %d ms. Press Ctrl+C to exit.\n", POLL_MS);

    while (g_running) {
        uint16_t c, r, g, b;
        if (tcs34725_read(i2c_fd, &c, &r, &g, &b) < 0) {
            fprintf(stderr, "Read error, re-initializing sensor...\n");
            if (tcs34725_init(i2c_fd) < 0) {
                fprintf(stderr, "Re-init failed, exiting.\n");
                break;
            }
            continue;
        }

        /* Per-channel calibration (typical values for TCS34725, gain=1) */
        float r_cal = (float)r * 0.5f - 50.0f;
        float g_cal = (float)g * 0.5f - 50.0f;
        float b_cal = (float)b * 0.5f - 50.0f;
        float c_cal = (float)c * 0.5f - 50.0f;

        printf("C: %5.1f  R: %5.1f  G: %5.1f  B: %5.1f\n", c_cal, r_cal, g_cal, b_cal);

        int led_val = (r_cal > RED_THRESHOLD) ? 1 : 0;
        if (gpiod_line_set_value(led, led_val) < 0) {
            fprintf(stderr, "gpiod_line_set_value: %s\n", strerror(errno));
        }

        struct timespec ts = { .tv_sec = 0, .tv_nsec = POLL_MS * 1000000L };
        nanosleep(&ts, NULL);
    }

    /* Cleanup */
    gpiod_line_set_value(led, 0);
    gpiod_line_release(led);
    gpiod_chip_close(chip);
    close(i2c_fd);
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

