/*
 * Raspberry Pi 4 Model B - WS2812B LED Strip Brightness Control
 * Sensor: BH1750 (I2C 0x23, continuous high-res mode 0x10)
 * Library: pigpio (hardware PWM wave for WS2812B timing)
 *
 * Build: gcc -O2 -Wall -o led_ctrl led_ctrl.c -lpigpio -lrt
 * Run:   sudo ./led_ctrl
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define BH1750_ADDR    0x23
#define BH1750_CMD_HRES 0x10
#define BH1750_CONV_MS 180

#define LED_GPIO       18
#define NUM_LEDS       10
#define MAX_LUX        1000
#define MIN_LUX        0
#define MAX_BRIGHTNESS 255
#define MIN_BRIGHTNESS 0

#define PWM_FREQ_HZ    8000000
#define PWM_DUTY_PCT   128   /* ~1.5% duty -> ~0.8 us high, ~0.8 us low */

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/* Write a 24-bit WS2812B color code to the LED strip */
static int ws2812_write(uint8_t r, uint8_t g, uint8_t b) {
    uint8_t buf[1 + 24];
    buf[0] = 0xE0 | (r >> 4);
    buf[1] = 0xE0 | (g >> 4);
    buf[2] = 0xE0 | (b >> 4);
    buf[3] = (r & 0x0F) << 16;
    buf[4] = (g & 0x0F) << 16;
    buf[5] = (b & 0x0F) << 16;
    buf[6] = 0;
    buf[7] = 0;
    buf[8] = 0;
    buf[9] = 0;
    buf[10] = 0;
    buf[11] = 0;
    buf[12] = 0;
    buf[13] = 0;
    buf[14] = 0;
    buf[15] = 0;
    buf[16] = 0;
    buf[17] = 0;
    buf[18] = 0;
    buf[19] = 0;
    buf[20] = 0;
    buf[21] = 0;
    buf[22] = 0;
    buf[23] = 0;
    buf[24] = 0;

    int rc = i2cWriteDevice(i2c_handle, (char *)buf, sizeof(buf));
    if (rc < 0) {
        fprintf(stderr, "WS2812B write failed: %d\n", rc);
        return -1;
    }
    return 0;
}

/* Read light level from BH1750 with retries */
static int read_light_level(void) {
    for (int attempt = 0; attempt < 3; attempt++) {
        if (i2cWriteByte(i2c_handle, BH1750_CMD_HRES) < 0) {
            fprintf(stderr, "BH1750 write failed (attempt %d)\n", attempt + 1);
            gpioDelay(100000);
            continue;
        }
        gpioDelay(BH1750_CONV_MS * 1000);

        char buf[2];
        int rc = i2cReadDevice(i2c_handle, buf, 2);
        if (rc != 2) {
            fprintf(stderr, "BH1750 read failed (attempt %d): rc=%d\n", attempt + 1, rc);
            gpioDelay(100000);
            continue;
        }

        uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
        return (int)(raw / 1.2f);
    }
    return -1;
}

/* Logarithmic mapping: lux -> brightness */
static int map_light_to_brightness(int lux) {
    if (lux <= 0) return 0;
    if (lux >= MAX_LUX) return MAX_BRIGHTNESS;
    float norm = (float)lux / MAX_LUX;
    float b = (float)MAX_BRIGHTNESS * (1.0f - log10f(norm + 1.0f));
    return (int)b;
}

/* Generate one WS2812B frame and send it via hardware PWM */
static void send_frame(void) {
    for (int i = 0; i < NUM_LEDS; i++) {
        int b = map_light_to_brightness(read_light_level());
        if (b < 0) b = 0;
        if (ws2812_write(0, 0, b) < 0) {
            fprintf(stderr, "Frame write failed at LED %d\n", i);
            return;
        }
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X: %d\n",
                I2C_BUS, BH1750_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    gpioSetMode(LED_GPIO, PI_OUTPUT);

    /* Configure hardware PWM for WS2812B timing */
    gpioHardwarePWM(LED_GPIO, PWM_FREQ_HZ, 0);
    gpioDelay(1000);

    while (running) {
        send_frame();
        gpioDelay(50000); /* 50 ms */
    }

    /* Cleanup */
    gpioHardwarePWM(LED_GPIO, PWM_FREQ_HZ, 0);
    gpioDelay(1000);
    gpioWrite(LED_GPIO, PI_OFF);

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

