#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/spi/spidev.h>

#define BH1750_ADDR 0x23
#define BH1750_CMD_OT_HRES 0x20
#define BH1750_CONV_MS 120
#define SPI_DEVICE "/dev/spidev0.0"
#define I2C_DEVICE "/dev/i2c-1"
#define NUM_LEDS 10
#define LUX_MIN 10.0f
#define LUX_MAX 300.0f
#define BRIGHTNESS_MAX 31
#define SPI_SPEED_HZ 1000000

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static int spi_fd = -1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t byte) {
    if (write(fd, &byte, 1) != 1) {
        fprintf(stderr, "I2C write error: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len) {
    size_t total = 0;
    while (total < len) {
        ssize_t n = read(fd, buf + total, len - total);
        if (n < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "I2C read error: %s\n", strerror(errno));
            return -1;
        }
        if (n == 0) {
            fprintf(stderr, "I2C read error: unexpected EOF\n");
            return -1;
        }
        total += (size_t)n;
    }
    return 0;
}

static int bh1750_init(int fd) {
    if (i2c_write_byte(fd, BH1750_CMD_OT_HRES) < 0) return -1;
    usleep(BH1750_CONV_MS * 1000);
    return 0;
}

static int bh1750_read_lux(int fd, float *lux) {
    uint8_t buf[2];
    if (i2c_read_bytes(fd, buf, 2) < 0) return -1;
    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *lux = (float)raw / 1.2f;
    return 0;
}

static int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "SPI open failed: %s\n", strerror(errno));
        return -1;
    }
    uint8_t mode = SPI_MODE_0;
    uint8_t bits = 8;
    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI mode set failed: %s\n", strerror(errno));
        close(spi_fd); spi_fd = -1; return -1;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI bits set failed: %s\n", strerror(errno));
        close(spi_fd); spi_fd = -1; return -1;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI speed set failed: %s\n", strerror(errno));
        close(spi_fd); spi_fd = -1; return -1;
    }
    return 0;
}

static int apa102_send_frame(uint8_t brightness) {
    uint8_t zeros[4] = {0, 0, 0, 0};
    uint8_t led_data[4];
    led_data[0] = 0xE0 | brightness;
    led_data[1] = 0x00; led_data[2] = 0x00; led_data[3] = 0x00;
    uint8_t end[4] = {0xFF, 0xFF, 0xFF, 0xFF};

    uint8_t tx[32];
    for (int i = 0; i < 4; i++) tx[i*4] = zeros[i];
    for (int i = 0; i < NUM_LEDS; i++) {
        tx[i*4+4] = led_data[i];
    }
    for (int i = 0; i < 4; i++) tx[NUM_LEDS*4+4+i*4] = end[i];

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx;
    tr.rx_buf = 0;
    tr.len = 32;
    tr.speed_hz = SPI_SPEED_HZ;
    tr.bits_per_word = 8;
    tr.delay_usecs = 0;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "I2C open failed: %s\n", strerror(errno));
        return 1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        fprintf(stderr, "I2C slave set failed: %s\n", strerror(errno));
        close(i2c_fd); return 1;
    }

    if (spi_init() < 0) {
        close(i2c_fd); return 1;
    }

    if (bh1750_init(i2c_fd) < 0) {
        fprintf(stderr, "BH1750 init failed (sensor absent or bus error)\n");
        goto cleanup;
    }

    while (running) {
        float lux;
        if (bh1750_read_lux(i2c_fd, &lux) < 0) {
            fprintf(stderr, "BH1750 read error, retrying...\n");
            usleep(100000);
            continue;
        }

        if (lux < LUX_MIN) lux = LUX_MIN;
        if (lux > LUX_MAX) lux = LUX_MAX;

        int brightness = (int)(((lux - LUX_MIN) / (LUX_MAX - LUX_MIN)) * BRIGHTNESS_MAX);
        if (brightness < 0) brightness = 0;
        if (brightness > BRIGHTNESS_MAX) brightness = BRIGHTNESS_MAX;

        if (apa102_send_frame(brightness) < 0) {
            fprintf(stderr, "APA102 send failed, retrying...\n");
        }

        printf("Lux: %.2f, Brightness: %d\n", lux, brightness);
        usleep(500000);
    }

cleanup:
    if (spi_fd >= 0) {
        apa102_send_frame(0);
        close(spi_fd);
    }
    if (i2c_fd >= 0) close(i2c_fd);
    return 0;
}

