#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define BH1750_ADDR_LOW 0x23
#define BH1750_ADDR_HIGH 0x5C
#define BH1750_CMD_OT_HRES2 0x21
#define BH1750_CONV_MS 180
#define APA102_SPI_CHANNEL 0
#define APA102_SPI_SPEED 1000000
#define FADE_DELAY_MS 500
#define LOOP_DELAY_MS 100
#define MAX_SENSORS 3

static volatile sig_atomic_t running = 1;
static int i2c_handle_low = -1;
static int i2c_handle_high = -1;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_bh1750(int handle) {
    if (i2cWriteByte(handle, BH1750_CMD_OT_HRES2) < 0) {
        fprintf(stderr, "Error: Failed to write measurement command to BH1750 handle %d\n", handle);
        return -1;
    }
    gpioDelay(BH1750_CONV_MS * 1000);
    return 0;
}

static int read_bh1750(int handle, uint16_t *lux) {
    char buf[2];
    int bytes = i2cReadDevice(handle, buf, 2);
    if (bytes != 2) {
        fprintf(stderr, "Error: Failed to read 2 bytes from BH1750 handle %d (got %d)\n", handle, bytes);
        return -1;
    }
    *lux = ((uint16_t)(buf[0] << 8)) | (uint8_t)buf[1];
    return 0;
}

static int init_spi(void) {
    spi_handle = spiOpen(APA102_SPI_CHANNEL, APA102_SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: Failed to open SPI channel %d (pigpio error %d)\n", APA102_SPI_CHANNEL, spi_handle);
        return -1;
    }
    return 0;
}

static void set_apa102_brightness(int brightness) {
    if (brightness < 0) brightness = 0;
    if (brightness > 31) brightness = 31;
    uint8_t data[4] = {0x00, 0x00, (uint8_t)(0x7F << brightness), 0xFF};
    if (spiWrite(spi_handle, (char *)data, 4) != 4) {
        fprintf(stderr, "Warning: SPI write failed for strip brightness %d\n", brightness);
    }
}

static void fade_apa102_brightness(int target, int current) {
    int steps = FADE_DELAY_MS / 10;
    if (steps <= 0) steps = 1;
    int increment = (target - current) / steps;
    if (increment > 1) increment = 1;
    if (increment < 0) increment = -1;
    for (int i = 0; i < steps && running; i++) {
        current += increment;
        if (current < 0) current = 0;
        if (current > 31) current = 31;
        set_apa102_brightness(current);
        gpioDelay(10000);
    }
    set_apa102_brightness(target);
}

static int init_sensors(void) {
    i2c_handle_low = i2cOpen(1, BH1750_ADDR_LOW, 0);
    if (i2c_handle_low < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at 0x%02X (pigpio error %d)\n", BH1750_ADDR_LOW, i2c_handle_low);
        return -1;
    }
    i2c_handle_high = i2cOpen(1, BH1750_ADDR_HIGH, 0);
    if (i2c_handle_high < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at 0x%02X (pigpio error %d)\n", BH1750_ADDR_HIGH, i2c_handle_high);
        i2cClose(i2c_handle_low);
        i2c_handle_low = -1;
        return -1;
    }
    return 0;
}

static int read_lux_sensors(void) {
    int lux_values[MAX_SENSORS];
    int num_sensors = 0;
    int valid = 1;

    if (init_bh1750(i2c_handle_low) == 0) {
        uint16_t lux;
        if (read_bh1750(i2c_handle_low, &lux) == 0) {
            lux_values[num_sensors++] = (int)lux;
        } else {
            valid = 0;
        }
    }

    if (init_bh1750(i2c_handle_high) == 0) {
        uint16_t lux;
        if (read_bh1750(i2c_handle_high, &lux) == 0) {
            lux_values[num_sensors++] = (int)lux;
        } else {
            valid = 0;
        }
    }

    if (num_sensors > 0) {
        int avg = 0;
        for (int i = 0; i < num_sensors; i++) avg += lux_values[i];
        return avg / num_sensors;
    }
    return -1;
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        set_apa102_brightness(0);
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (i2c_handle_low >= 0) {
        i2cClose(i2c_handle_low);
        i2c_handle_low = -1;
    }
    if (i2c_handle_high >= 0) {
        i2cClose(i2c_handle_high);
        i2c_handle_high = -1;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (init_spi() != 0) {
        cleanup();
        return 1;
    }

    if (init_sensors() != 0) {
        cleanup();
        return 1;
    }

    int current_brightness = 0;
    int target_brightness = 0;
    int lux = -1;

    while (running) {
        lux = read_lux_sensors();
        if (lux < 0) {
            fprintf(stderr, "Warning: No valid lux readings, skipping cycle\n");
        } else {
            int brightness = 31 - (lux / 10);
            if (brightness < 0) brightness = 0;
            if (brightness > 31) brightness = 31;
            target_brightness = brightness;
            fade_apa102_brightness(target_brightness, current_brightness);
            current_brightness = target_brightness;
        }
        gpioDelay(LOOP_DELAY_MS * 1000);
    }

    cleanup();
    return 0;
}

