#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <math.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_DEVICE "/dev/i2c-1"
#define VEML7700_ADDR 0x10
#define VEML7700_CONFIG_REG 0x00
#define VEML7700_ALS_DATA_REG 0x04
#define WS2812B_GPIO_LINE 18
#define WS2812B_FREQ 800000
#define WS2812B_T0H 0.4
#define WS2812B_T0L 0.8
#define WS2812B_T1H 0.4
#define WS2812B_T1L 0.8
#define MAX_LUX 120000.0
#define MAX_BRIGHTNESS 255
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 100
#define LOOP_DELAY_MS 200

// Global variables
static int i2c_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static volatile sig_atomic_t running = 1;

// Function prototypes
int i2c_init(void);
int veml7700_init(void);
int veml7700_read_lux(float *lux);
int ws2812b_init(void);
void ws2812b_set_brightness(int brightness);
void ws2812b_off(void);
void cleanup(void);
void signal_handler(int sig);

// I2C initialization function
int i2c_init(void) {
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device %s: %s\n", I2C_DEVICE, strerror(errno));
        return -1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, VEML7700_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", VEML7700_ADDR, strerror(errno));
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    return 0;
}

// VEML7700 initialization function
int veml7700_init(void) {
    uint8_t config = 0x0000; // Integration time 100ms, gain 1/8
    uint8_t buf[3];
    buf[0] = VEML7700_CONFIG_REG;
    buf[1] = config & 0xFF;
    buf[2] = (config >> 8) & 0xFF;
    if (write(i2c_fd, buf, 3) != 3) {
        fprintf(stderr, "Error writing to VEML7700 config register: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// VEML7700 read lux function with retry
int veml7700_read_lux(float *lux) {
    uint8_t reg = VEML7700_ALS_DATA_REG;
    uint8_t data[2];
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        // Write register address
        if (write(i2c_fd, &reg, 1) != 1) {
            fprintf(stderr, "Error writing register address to VEML7700: %s\n", strerror(errno));
            retries++;
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }
        // Read 2 bytes
        result = read(i2c_fd, data, 2);
        if (result != 2) {
            fprintf(stderr, "Error reading from VEML7700 (attempt %d): %s\n", retries + 1, strerror(errno));
            retries++;
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }
        // Combine bytes (little-endian)
        uint16_t raw = (data[1] << 8) | data[0];
        // Convert to lux: lux = raw * 0.0036 * (1/gain) * (100ms/integration_time)
        // For default settings: gain = 1/8, integration time = 100ms
        // lux = raw * 0.0036 * 8 * (100/100) = raw * 0.0288
        *lux = raw * 0.0288f;
        return 0;
    }
    fprintf(stderr, "Failed to read lux after %d retries\n", MAX_RETRIES);
    return -1;
}

// WS2812B initialization function
int ws2812b_init(void) {
    chip = gpiod_chip_open_by_name("gpiochip4"); // RP1 GPIO controller on Raspberry Pi 5
    if (!chip) {
        chip = gpiod_chip_open_by_name("gpiochip0"); // Fallback
        if (!chip) {
            fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
            return -1;
        }
    }
    line = gpiod_chip_get_line(chip, WS2812B_GPIO_LINE);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", WS2812B_GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        chip = NULL;
        return -1;
    }
    return 0;
}

// WS2812B set brightness function
void ws2812b_set_brightness(int brightness) {
    if (brightness < 0) brightness = 0;
    if (brightness > 255) brightness = 255;
    // Calculate on-time and off-time for each bit
    // For WS2812B, we use a simple on/off approach with threshold
    // If bit is 1, turn on for T0H + T1H; if 0, turn on for T0L
    // This is a simplified threshold-based approach; for high-speed bit-banging
    // we would use precise timing. Here we use a simple threshold to approximate.
    // In production, use precise timing via bit-banging or hardware PWM.
    // For this example, we use a simple threshold: if brightness > 128, turn on.
    if (brightness > 128) {
        gpiod_line_set_value(line, 1);
        usleep(WS2812B_T1H * 1000);
        gpiod_line_set_value(line, 0);
        usleep(WS2812B_T1L * 1000);
    } else {
        gpiod_line_set_value(line, 1);
        usleep(WS2812B_T0H * 1000);
        gpiod_line_set_value(line, 0);
        usleep(WS2812B_T0L * 1000);
    }
}

// WS2812B off function
void ws2812b_off(void) {
    gpiod_line_set_value(line, 0);
    usleep(1000); // Small delay to ensure line is low
}

// Cleanup function
void cleanup(void) {
    ws2812b_off();
    if (line) {
        gpiod_line_release(line);
        line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

// Signal handler
void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (i2c_init() < 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        return 1;
    }

    // Initialize VEML7700
    if (veml7700_init() < 0) {
        fprintf(stderr, "VEML7700 initialization failed. Exiting.\n");
        cleanup();
        return 1;
    }

    // Initialize WS2812B
    if (ws2812b_init() < 0) {
        fprintf(stderr, "WS2812B initialization failed. Exiting.\n");
        cleanup();
        return 1;
    }

    printf("Starting VEML7700 + WS2812B control. Press Ctrl+C to exit.\n");

    while (running) {
        float lux;
        if (veml7700_read_lux(&lux) == 0) {
            // Gamma correction: brightness = 255 * pow(lux / 120000.0, 1/2.2)
            float gamma = 2.2f;
            int brightness = (int)(255.0f * powf(lux / MAX_LUX, 1.0f / gamma));
            if (brightness < 0) brightness = 0;
            if (brightness > 255) brightness = 255;
            ws2812b_set_brightness(brightness);
            printf("Lux: %.2f, Brightness: %d\n", lux, brightness);
        } else {
            fprintf(stderr, "Failed to read lux. Continuing...\n");
        }
