#include <gpiod.h>

#define FLAME_SENSOR_PIN 4
#define BUZZER_PIN 17
#define LED_PIN 18
#define NUM_READINGS 5
#define POLL_INTERVAL_MS 50
#define BLINK_ON_MS 500
#define BLINK_OFF_MS 500
#define RAPID_BLINK_MS 100
#define RAPID_BLINK_CYCLES 5
#define BUZZER_PATTERN_MS 200
#define BUZZER_SHORT_MS 200
#define BUZZER_LONG_MS 600
#define BUZZER_REPEATS 3

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *msg) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    printf("[%s] %s\n", ts, msg);
    fflush(stdout);
}

static void sleep_ms(unsigned int ms) {
    struct timespec ts = { ms / 1000, (long)(ms % 1000) * 1000000L };
    nanosleep(&ts, NULL);
}

static void blink_led_rapid(void) {
    for (int i = 0; i < RAPID_BLINK_CYCLES && running; i++) {
        if (gpiod_line_set_value(LED_PIN, 1) < 0) {
            log_event("LED set high failed");
            return;
        }
        sleep_ms(RAPID_BLINK_MS);
        if (gpiod_line_set_value(LED_PIN, 0) < 0) {
            log_event("LED set low failed");
            return;
        }
        sleep_ms(RAPID_BLINK_MS);
    }
}

static void buzzer_pattern(void) {
    for (int i = 0; i < BUZZER_REPEATS && running; i++) {
        if (gpiod_line_set_value(BUZZER_PIN, 1) < 0) {
            log_event("Buzzer set high failed");
            return;
        }
        sleep_ms(BUZZER_SHORT_MS);
        if (gpiod_line_set_value(BUZZER_PIN, 0) < 0) {
            log_event("Buzzer set low failed");
            return;
        }
        sleep_ms(BUZZER_SHORT_MS);
        if (gpiod_line_set_value(BUZZER_PIN, 1) < 0) {
            log_event("Buzzer set high failed");
            return;
        }
        sleep_ms(BUZZER_LONG_MS);
    }
}

static void self_test(void) {
    log_event("Starting self-test...");
    if (gpiod_line_request_output(LED_PIN, "flame_sensor", 0) < 0) {
        log_event("Failed to request LED line");
        return;
    }
    if (gpiod_line_request_output(BUZZER_PIN, "flame_sensor", 0) < 0) {
        log_event("Failed to request buzzer line");
        return;
    }
    if (gpiod_line_request_input(FLAME_SENSOR_PIN, "flame_sensor") < 0) {
        log_event("Failed to request flame sensor line");
        return;
    }
    log_event("LED blinking self-test pattern...");
    for (int i = 0; i < 2 && running; i++) {
        if (gpiod_line_set_value(LED_PIN, 1) < 0) {
            log_event("LED set high failed");
            return;
        }
        sleep_ms(BLINK_ON_MS);
        if (gpiod_line_set_value(LED_PIN, 0) < 0) {
            log_event("LED set low failed");
            return;
        }
        sleep_ms(BLINK_OFF_MS);
    }
    int readings[NUM_READINGS];
    int fault = 0;
    log_event("Reading flame sensor...");
    for (int i = 0; i < NUM_READINGS && running; i++) {
        int val = gpiod_line_get_value(FLAME_SENSOR_PIN);
        if (val < 0) {
            log_event("Flame sensor read failed");
            return;
        }
        readings[i] = val;
        if (val == 0) {
            log_event("Flame detected!");
            fault = 1;
        }
        sleep_ms(100);
    }
    if (fault) {
        log_event("Sensor fault: flame detected every reading.");
        blink_led_rapid();
        buzzer_pattern();
        return;
    }
    log_event("Self-test passed.");
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        chip = gpiod_chip_open_by_name("gpiochip0");
    }
    if (!chip) {
        perror("gpiod_chip_open");
        return 1;
    }
    struct gpiod_line *flame_line = gpiod_chip_get_line(chip, FLAME_SENSOR_PIN);
    struct gpiod_line *buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    struct gpiod_line *led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!flame_line || !buzzer_line || !led_line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_request_output(buzzer_line, "flame_sensor", 0) < 0) {
        perror("request buzzer line");
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_request_output(led_line, "flame_sensor", 0) < 0) {
        perror("request LED line");
        gpiod_line_release(buzzer_line);
        gpiod_chip_close(chip);
        return 1;
    }
    self_test();
    log_event("Entering main loop...");
    while (running) {
        int val = gpiod_line_get_value(flame_line);
        if (val < 0) {
            log_event("Flame sensor read failed");
            sleep_ms(1000);
            continue;
        }
        if (val == 0) {
            log_event("Flame detected!");
            if (gpiod_line_set_value(buzzer_line, 1) < 0) {
                log_event("Buzzer set high failed");
            }
            if (gpiod_line_set_value(led_line, 1) < 0) {
                log_event("LED set high failed");
            }
            while (running) {
                val = gpiod_line_get_value(flame_line);
                if (val < 0) {
                    log_event("Flame sensor read failed");
                    break;
                }
                if (val == 1) {
                    break;
                }
                sleep_ms(POLL_INTERVAL_MS);
            }
            if (gpiod_line_set_value(buzzer_line, 0) < 0) {
                log_event("Buzzer set low failed");
            }
            if (gpiod_line_set_value(led_line, 0) < 0) {
                log_event("LED set low failed");
            }
            log_event("Flame gone.");
        } else {
            sleep_ms(POLL_INTERVAL_MS);
        }
    }
    log_event("Shutting down...");
    gpiod_line_set_value(buzzer_line, 0);
    gpiod_line_set_value(led_line, 0);
    gpiod_line_release(flame_line);
    gpiod_line_release(buzzer_line);
    gpiod_line_release(led_line);
    gpiod_chip_close(chip);
    return 0;
}

