#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <gpiod.h>
#include <errno.h>
#include <string.h>

#define DATA_PIN 17
#define CLOCK_PIN 18
#define LATCH_PIN 27

#define BLINK_DELAY_MS 500

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *data_line = NULL;
static struct gpiod_line *clock_line = NULL;
static struct gpiod_line *latch_line = NULL;

static void cleanup(void) {
    if (data_line) gpiod_line_release(data_line);
    if (clock_line) gpiod_line_release(clock_line);
    if (latch_line) gpiod_line_release(latch_line);
    if (chip) gpiod_chip_close(chip);
}

static int setup(void) {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return -1;
    }

    data_line = gpiod_chip_get_line(chip, DATA_PIN);
    clock_line = gpiod_chip_get_line(chip, CLOCK_PIN);
    latch_line = gpiod_chip_get_line(chip, LATCH_PIN);
    if (!data_line || !clock_line || !latch_line) {
        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        cleanup();
        return -1;
    }

    if (gpiod_line_request_output(data_line, "seven-seg", 0) < 0 ||
        gpiod_line_request_output(clock_line, "seven-seg", 0) < 0 ||
        gpiod_line_request_output(latch_line, "seven-seg", 0) < 0) {
        fprintf(stderr, "Failed to request output lines: %s\n", strerror(errno));
        cleanup();
        return -1;
    }

    return 0;
}

static void shift_out(unsigned char data) {
    for (int i = 7; i >= 0; i--) {
        int bit = (data >> i) & 1;
        gpiod_line_set_value(data_line, bit);
        gpiod_line_set_value(clock_line, 1);
        usleep(1);
        gpiod_line_set_value(clock_line, 0);
        usleep(1);
    }
    gpiod_line_set_value(latch_line, 1);
    usleep(1);
    gpiod_line_set_value(latch_line, 0);
    usleep(1);
}

static void display_digit(int digit) {
    switch (digit) {
        case 0: shift_out(0x3F); break;
        case 1: shift_out(0x06); break;
        case 2: shift_out(0x5B); break;
        case 3: shift_out(0x4F); break;
        case 4: shift_out(0x66); break;
        case 5: shift_out(0x5B); break;
        case 6: shift_out(0x4F); break;
        case 7: shift_out(0x10); break;
        case 8: shift_out(0x7F); break;
        case 9: shift_out(0x60); break;
        default: shift_out(0x00); break;
    }
}

int main(void) {
    if (setup() < 0) {
        return EXIT_FAILURE;
    }

    while (1) {
        display_digit(5);
        usleep(BLINK_DELAY_MS * 1000);
        gpiod_line_set_value(data_line, 0);
        usleep(BLINK_DELAY_MS * 1000);
    }

    cleanup();
    return EXIT_SUCCESS;
}

