#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

#define RED_PIN 24
#define GREEN_PIN 23
#define BLUE_PIN 18
#define PWM_PERIOD_NS 10000000  // 10 ms = 100 Hz
#define PWM_STEPS 100

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *red_line = NULL;
static struct gpiod_line *green_line = NULL;
static struct gpiod_line *blue_line = NULL;

static volatile sig_atomic_t keep_running = 1;

void cleanup_and_exit(int signum) {
    (void)signum;
    keep_running = 0;
}

void release_resources(void) {
    if (red_line) {
        gpiod_line_release(red_line);
        red_line = NULL;
    }
    if (green_line) {
        gpiod_line_release(green_line);
        green_line = NULL;
    }
    if (blue_line) {
        gpiod_line_release(blue_line);
        blue_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = cleanup_and_exit;
    sigaction(SIGINT, &sa, NULL);

    chip = gpiod_chip_open_by_number(0);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip 0: %s\n", strerror(errno));
        return 1;
    }

    red_line = gpiod_chip_get_line(chip, RED_PIN);
    green_line = gpiod_chip_get_line(chip, GREEN_PIN);
    blue_line = gpiod_chip_get_line(chip, BLUE_PIN);
    if (!red_line || !green_line || !blue_line) {
        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        release_resources();
        return 1;
    }

    if (gpiod_line_request_output(red_line, "rgb_led", 0) < 0 ||
        gpiod_line_request_output(green_line, "rgb_led", 0) < 0 ||
        gpiod_line_request_output(blue_line, "rgb_led", 0) < 0) {
        fprintf(stderr, "Failed to request output lines: %s\n", strerror(errno));
        release_resources();
        return 1;
    }

    srand(time(NULL));

    while (keep_running) {
        int r = rand() % 101;
        int g = rand() % 101;
        int b = rand() % 101;

        int red_duty = (r * PWM_STEPS) / 100;
        int green_duty = (g * PWM_STEPS) / 100;
        int blue_duty = (b * PWM_STEPS) / 100;

        // Software PWM loop for one period
        for (int i = 0; i < PWM_STEPS && keep_running; i++) {
            int red_val = (i < red_duty) ? 1 : 0;
            int green_val = (i < green_duty) ? 1 : 0;
            int blue_val = (i < blue_duty) ? 1 : 0;

            if (gpiod_line_set_value(red_line, red_val) < 0 ||
                gpiod_line_set_value(green_line, green_val) < 0 ||
                gpiod_line_set_value(blue_line, blue_val) < 0) {
                fprintf(stderr, "PWM write failed: %s\n", strerror(errno));
                break;
            }

            struct timespec ts;
            ts.tv_sec = 0;
            ts.tv_nsec = 1000000 / PWM_STEPS;  // ~1 ms per step
            clock_nanosleep(CLOCK_MONOTONIC, 0, &ts, NULL);
        }
    }

    release_resources();
    return 0;
}

