#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

/* LSM303DLHC Accelerometer I2C address (SA0 tied to GND) */
#define LSM303_ACCEL_ADDR 0x19

/* LSM303DLHC Accelerometer register addresses */
#define LSM303_ACCEL_CTRL_REG1_A 0x20
#define LSM303_ACCEL_CTRL_REG4_A 0x23
#define LSM303_ACCEL_OUT_X_L_A   0x28

/* GPIO pin for alert output */
#define ALERT_GPIO 17

/* Default impact threshold in G */
#define DEFAULT_IMPACT_THRESHOLD 2.0

/* I2C bus on Raspberry Pi Zero W */
#define I2C_BUS 1

/* Global variables */
static int i2c_handle = -1;
static volatile sig_atomic_t program_running = 1;

/* Function prototypes */
static int initialize_i2c(void);
static int initialize_accelerometer(void);
static int read_accelerometer_data(int16_t *x, int16_t *y, int16_t *z);
static double calculate_g_force(int16_t x, int16_t y, int16_t z);
static void trigger_alert(void);
static void log_data(int16_t x, int16_t y, int16_t z, double g_force);
static void signal_handler(int signal);
static void cleanup(void);

/* Signal handler for graceful shutdown */
static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

/* Initialize I2C communication */
static int initialize_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, LSM303_ACCEL_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02X on bus %d: %d\n",
                LSM303_ACCEL_ADDR, I2C_BUS, i2c_handle);
        return -1;
    }
    return 0;
}

/* Initialize the LSM303DLHC accelerometer */
static int initialize_accelerometer(void) {
    /* CTRL_REG1_A: 100 Hz data rate, enable all axes, normal mode */
    if (i2cWriteByteData(i2c_handle, LSM303_ACCEL_CTRL_REG1_A, 0x27) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1_A\n");
        return -1;
    }

    /* CTRL_REG4_A: 2G full-scale, +/- 2G range, normal mode */
    if (i2cWriteByteData(i2c_handle, LSM303_ACCEL_CTRL_REG4_A, 0x00) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG4_A\n");
        return -1;
    }

    return 0;
}

/* Read raw accelerometer data (6 bytes starting at OUT_X_L_A) */
static int read_accelerometer_data(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];

    /* Read 6 bytes starting from OUT_X_L_A with auto-increment */
    if (i2cReadI2CBlockData(i2c_handle, LSM303_ACCEL_OUT_X_L_A | 0x80, buffer, 6) != 6) {
        fprintf(stderr, "Error reading accelerometer data\n");
        return -1;
    }

