#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define I2C_BUS 1
#define ADPD188BI_ADDR 0x39
#define MODE_REG 0x0D
#define ALS_LSB_REG 0x64
#define ALS_MSB_REG 0x65
#define RED_REG 0x66
#define GREEN_REG 0x68
#define BLUE_REG 0x6A
#define LED_GPIO 18
#define PWM_RANGE 255
#define SAMPLE_INTERVAL_US 500000
#define RETRY_DELAY_US 100000

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int write_register(uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(i2c_handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg 0x%02X, val 0x%02X): %s\n",
                reg, value, strerror(errno));
    }
    return rc;
}

static int read_register16(uint8_t reg_lsb, uint16_t *out) {
    int lsb = i2cReadByteData(i2c_handle, reg_lsb);
    if (lsb < 0) {
        fprintf(stderr, "I2C read LSB failed (reg 0x%02X): %s\n",
                reg_lsb, strerror(errno));
        return -1;
    }
    int msb = i2cReadByteData(i2c_handle, reg_lsb + 1);
    if (msb < 0) {
        fprintf(stderr, "I2C read MSB failed (reg 0x%02X): %s\n",
                reg_lsb + 1, strerror(errno));
        return -1;
    }
    *out = (uint16_t)((msb << 8) | lsb);
    return 0;
}

static int initialize_sensor(void) {
    if (write_register(MODE_REG, 0x01) < 0) {
        fprintf(stderr, "Failed to set ADPD188BI normal operation mode\n");
        return -1;
    }
    return 0;
}

static int read_sensor_data(uint16_t *als, uint16_t *red, uint16_t *green, uint16_t *blue) {
    if (read_register16(ALS_LSB_REG, als) < 0) return -1;
    if (read_register16(ALS_MSB_REG, als) < 0) return -1;
    if (read_register16(RED_REG, red) < 0) return -1;
    if (read_register16(GREEN_REG, green) < 0) return -1;
    if (read_register16(BLUE_REG, blue) < 0) return -1;
    return 0;
}

static void log_data(uint16_t als, uint16_t red, uint16_t green, uint16_t blue) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%u,%u,%u,%u\n", timestamp, als, red, green, blue);
    fflush(log_file);
}

static void set_led_brightness(uint16_t als) {
    int duty = (int)(((float)als / 65535.0f) * PWM_RANGE);
    if (duty < 0) duty = 0;
    if (duty > PWM_RANGE) duty = PWM_RANGE;
    gpioPWM(LED_GPIO, duty);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioPWM(LED_GPIO, 0);
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, ADPD188BI_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X: %s\n",
                I2C_BUS, ADPD188BI_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (initialize_sensor() < 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioSetPWMrange(LED_GPIO, PWM_RANGE);
    gpioPWM(LED_GPIO, 0);

    log_file = fopen("color_log.csv", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,ALS,Red,Green,Blue\n");
        fflush(log_file);
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint16_t als, red, green, blue;
    while (!terminate) {
        if (read_sensor_data(&als, &red, &green, &blue) == 0) {
            log_data(als, red, green, blue);
            set_led_brightness(als);
        } else {
            fprintf(stderr, "Sensor read error, retrying...\n");
            gpioDelay(RETRY_DELAY_US);
            continue;
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

