static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int verify_sensor(int handle)
{
    int who = i2cReadByteData(handle, FXOS8700_WHO_AM_I);
    if (who < 0) {
        fprintf(stderr, "Error: failed to read WHO_AM_I register (pigpio error %d)\n", who);
        return -1;
    }
    if (who != FXOS8700_WHO_AM_I_VAL) {
        fprintf(stderr, "Error: WHO_AM_I mismatch (got 0x%02X, expected 0x%02X). Wrong sensor?\n",
                who, FXOS8700_WHO_AM_I_VAL);
        return -1;
