#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define GYRO_ADDR        0x69
#define WHO_AM_I_REG     0x0F
#define WHO_AM_I_VAL     0xD3
#define CTRL_REG1        0x20
#define CTRL_REG4        0x23
#define OUT_X_L          0x28
#define I2C_BUS          "/dev/i2c-1"
#define LOG_FILE         "gyro_log.txt"
#define SAMPLE_PERIOD_US 50000
#define CALIB_SAMPLES    100
#define THRESHOLD_DPS    50.0f

static volatile sig_atomic_t g_running = 1;
static int g_fd = -1;
static FILE *g_log = NULL;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_gyro(void) {
    g_fd = open(I2C_BUS, O_RDWR);
    if (g_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return -1;
    }
    if (ioctl(g_fd, I2C_SLAVE, GYRO_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n", GYRO_ADDR, strerror(errno));
        return -1;
    }
    uint8_t who = 0;
    if (i2c_read_block(g_fd, WHO_AM_I_REG, &who, 1) < 0) {
        return -1;
    }
    if (who != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n", who, WHO_AM_I_VAL);
        return -1;
    }
    if (i2c_write_reg(g_fd, CTRL_REG1, 0x0F) < 0) return -1;
    if (i2c_write_reg(g_fd, CTRL_REG4, 0x00) < 0) return -1;
    return 0;
}

static int read_gyro(float *x, float *y, float *z) {
    uint8_t buf[6];
    if (i2c_read_block(g_fd, OUT_X_L | 0x80, buf, 6) < 0) return -1;
    int16_t rx = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t ry = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t rz = (int16_t)((buf[5] << 8) | buf[4]);
    *x = (float)rx * 0.00875f;
    *y = (float)ry * 0.00875f;
    *z = (float)rz * 0.00875f;
    return 0;
}

static void calibrate_gyro(float *x_off, float *y_off, float *z_off) {
    float sx = 0.0f, sy = 0.0f, sz = 0.0f;
    int ok = 0;
    for (int i = 0; i < CALIB_SAMPLES; i++) {
        float x, y, z;
        if (read_gyro(&x, &y, &z) == 0) {
            sx += x; sy += y; sz += z;
            ok++;
        }
        usleep(10000);
    }
    if (ok == 0) {
        fprintf(stderr, "Calibration failed: no samples\n");
        return;
    }
    *x_off = sx / ok;
    *y_off = sy / ok;
    *z_off = sz / ok;
    printf("Calibration offsets: X=%.3f, Y=%.3f, Z=%.3f\n", *x_off, *y_off, *z_off);
}

static void log_data(float x, float y, float z) {
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(g_log, "%s,%.3f,%.3f,%.3f\n", ts, x, y, z);
    fflush(g_log);
}

static void check_threshold(float x, float y, float z) {
    if (fabsf(x) > THRESHOLD_DPS) fprintf(stderr, "X-axis alert: %.3f dps\n", x);
    if (fabsf(y) > THRESHOLD_DPS) fprintf(stderr, "Y-axis alert: %.3f dps\n", y);
    if (fabsf(z) > THRESHOLD_DPS) fprintf(stderr, "Z-axis alert: %.3f dps\n", z);
}

static void cleanup(void) {
    if (g_log) { fclose(g_log); g_log = NULL; }
    if (g_fd >= 0) { close(g_fd); g_fd = -1; }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    g_log = fopen(LOG_FILE, "a");
    if (!g_log) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        return 1;
    }

    if (init_gyro() < 0) {
        fprintf(stderr, "Gyroscope initialization failed\n");
        cleanup();
        return 1;
    }

    float x_off = 0.0f, y_off = 0.0f, z_off = 0.0f;
    calibrate_gyro(&x_off, &y_off, &z_off);

    printf("Gyroscope ready. Sampling at 20 Hz. Press Ctrl+C to stop.\n");

    while (g_running) {
        float x, y, z;
        if (read_gyro(&x, &y, &z) == 0) {
            x -= x_off;
            y -= y_off;
            z -= z_off;
            log_data(x, y, z);
            check_threshold(x, y, z);
        } else {
            fprintf(stderr, "Read error, continuing...\n");
        }
        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

