#include <signal.h>
#include <math.h>
#include <pigpio.h>

/* ADXL345 I2C address (ALT ADDRESS tied to GND) */
#define ADXL345_ADDR 0x53

/* ADXL345 register addresses */
#define ADXL345_DEVID       0x00
#define ADXL345_POWER_CTL   0x2D
#define ADXL345_DATA_FORMAT 0x31
#define ADXL345_DATAX0      0x32

/* Expected device ID */
#define ADXL345_DEVID_VAL   0xE5

/* Full-resolution, ±2g range -> 4 mg/LSB -> 4096 LSB/g */
#define ADXL345_FULL_RES_2G  0x00
#define ADXL345_RANGE_2G     0x00

/* LED GPIO pin */
#define LED_GPIO 17

/* Acceleration threshold (g) */
#define ACCEL_THRESHOLD 2.0f

/* Sampling interval (microseconds) */
#define SAMPLE_INTERVAL_US 100000

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    float x, y, z;
} accel_data_t;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int adxl345_init(void) {
    int devid = i2cReadByteData(i2c_handle, ADXL345_DEVID);
    if (devid < 0) {
        fprintf(stderr, "Error: I2C read failed for DEVID (pigpio error %d)\n", devid);
        return -1;
    }
    if (devid != ADXL345_DEVID_VAL) {
        fprintf(stderr, "Error: DEVID mismatch (got 0x%02X, expected 0x%02X)\n",
                devid & 0xFF, ADXL345_DEVID_VAL);
        return -1;
    }

    /* Set data format: full resolution, ±2g, right-justified */
    if (i2cWriteByteData(i2c_handle, ADXL345_DATA_FORMAT,
                         ADXL345_FULL_RES_2G | ADXL345_RANGE_2G) < 0) {
        fprintf(stderr, "Error: Failed to write DATA_FORMAT register\n");
        return -1;
    }

    /* Clear standby bit (bit 3) and enable measurement (bit 1) */
    if (i2cWriteByteData(i2c_handle, ADXL345_POWER_CTL, 0x02) < 0) {
        fprintf(stderr, "Error: Failed to write POWER_CTL register\n");
        return -1;
    }

    return 0;
}

static int read_acceleration(accel_data_t *data) {
    char raw[6];
    int16_t x, y, z;

    if (i2cReadI2CBlockData(i2c_handle, ADXL345_DATAX0, raw, 6) != 6) {
        fprintf(stderr, "Error: I2C block read failed\n");
        return -1;
    }

    x = (int16_t)((raw[1] << 8) | raw[0]);
    y = (int16_t)((raw[3] << 8) | raw[2]);
    z = (int16_t)((raw[5] << 8) | raw[4]);

    data->x = (float)x / 4096.0f;
    data->y = (float)y / 4096.0f;
    data->z = (float)z / 4096.0f;

    return 0;
}

static void log_data(const accel_data_t *data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.3f,%.3f,%.3f\n", timestamp, data->x, data->y, data->z);
    fflush(log_file);
}

static void control_led(int state) {
    if (gpioWrite(LED_GPIO, state) < 0) {
        fprintf(stderr, "Warning: gpioWrite failed for LED GPIO %d\n", LED_GPIO);
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(1, ADXL345_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (pigpio error %d)\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (adxl345_init() < 0) {
        fprintf(stderr, "Error: ADXL345 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for GPIO %d\n", LED_GPIO);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    log_file = fopen("accel_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open accel_log.txt\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("ADXL345 logging started. Press Ctrl+C to stop.\n");

    while (!terminate) {
        accel_data_t data;

        if (read_acceleration(&data) == 0) {
            log_data(&data);

            if (fabsf(data.x) > ACCEL_THRESHOLD ||
                fabsf(data.y) > ACCEL_THRESHOLD ||
                fabsf(data.z) > ACCEL_THRESHOLD) {
                control_led(1);
            } else {
                control_led(0);
            }
        } else {
            fprintf(stderr, "Warning: read_acceleration failed, continuing\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    control_led(0);
    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

