#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <math.h>
#include <pigpio.h>

/* LSM303DLHC I2C addresses */
#define LSM303_ACCEL_ADDR 0x19
#define LSM303_MAG_ADDR   0x1E

/* LSM303DLHC register addresses */
#define LSM303_ACCEL_CTRL_REG1_A 0x20
#define LSM303_ACCEL_OUT_X_L_A   0x28
#define LSM303_MAG_MR_REG_M      0x02
#define LSM303_MAG_OUT_X_H_M     0x03

/* Scaling factors */
#define ACCEL_SCALE 0.000244f  /* g/LSB at 50 Hz */
#define MAG_SCALE   0.00014f   /* gauss/LSB at 80 Hz */

static volatile sig_atomic_t running = 1;
static int i2c_handle_accel = -1;
static int i2c_handle_mag    = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_lsm303(void) {
    i2c_handle_accel = i2cOpen(1, LSM303_ACCEL_ADDR, 0);
    if (i2c_handle_accel < 0) {
        fprintf(stderr, "Error opening I2C for accelerometer (0x%02X): %d\n",
                LSM303_ACCEL_ADDR, i2c_handle_accel);
        return -1;
    }

    i2c_handle_mag = i2cOpen(1, LSM303_MAG_ADDR, 0);
    if (i2c_handle_mag < 0) {
        fprintf(stderr, "Error opening I2C for magnetometer (0x%02X): %d\n",
                LSM303_MAG_ADDR, i2c_handle_mag);
        i2cClose(i2c_handle_accel);
        i2c_handle_accel = -1;
        return -1;
    }

    /* Accelerometer: 50 Hz, all axes enabled */
    if (i2cWriteByteData(i2c_handle_accel, LSM303_ACCEL_CTRL_REG1_A, 0x27) < 0) {
        fprintf(stderr, "Error writing accelerometer CTRL_REG1_A\n");
        return -1;
    }

    /* Magnetometer: continuous-conversion mode */
    if (i2cWriteByteData(i2c_handle_mag, LSM303_MAG_MR_REG_M, 0x00) < 0) {
        fprintf(stderr, "Error writing magnetometer MR_REG_M\n");
        return -1;
    }

    return 0;
}

static int read_accelerometer(float *x, float *y, float *z) {
    char buf[6];
    int16_t raw_x, raw_y, raw_z;

    if (i2cReadI2CBlockData(i2c_handle_accel, LSM303_ACCEL_OUT_X_L_A | 0x80, buf, 6) != 6) {
        fprintf(stderr, "Error reading accelerometer data\n");
        return -1;
    }

    raw_x = (int16_t)((buf[1] << 8) | (uint8_t)buf[0]);
    raw_y = (int16_t)((buf[3] << 8) | (uint8_t)buf[2]);
    raw_z = (int16_t)((buf[5] << 8) | (uint8_t)buf[4]);

    *x = (float)raw_x * ACCEL_SCALE;
    *y = (float)raw_y * ACCEL_SCALE;
    *z = (float)raw_z * ACCEL_SCALE;
    return 0;
}

static int read_magnetometer(float *x, float *y, float *z) {
    char buf[6];
    int16_t raw_x, raw_y, raw_z;

    if (i2cReadI2CBlockData(i2c_handle_mag, LSM303_MAG_OUT_X_H_M, buf, 6) != 6) {
        fprintf(stderr, "Error reading magnetometer data\n");
        return -1;
    }

    raw_x = (int16_t)((buf[0] << 8) | (uint8_t)buf[1]);
    raw_y = (int16_t)((buf[2] << 8) | (uint8_t)buf[3]);
    raw_z = (int16_t)((buf[4] << 8) | (uint8_t)buf[5]);

    *x = (float)raw_x * MAG_SCALE;
    *y = (float)raw_y * MAG_SCALE;
    *z = (float)raw_z * MAG_SCALE;
    return 0;
}

static float calculate_heading(float ax, float ay, float az,
                                float mx, float my, float mz) {
    float roll = atan2f(ax, sqrtf(ay * ay + az * az));
    float pitch = atan2f(-ay, az);

    float cos_roll = cosf(roll);
    float sin_roll = sinf(roll);
    float cos_pitch = cosf(pitch);
    float sin_pitch = sinf(pitch);

    float mx_comp = mx * cos_pitch + mz * sin_pitch;
    float my_comp = mx * sin_roll * sin_pitch + my * cos_roll - mz * sin_roll * cos_pitch;

    float heading = atan2f(my_comp, mx_comp) * 180.0f / M_PI;
    if (heading < 0.0f) heading += 360.0f;
    return heading;
}

static void log_data(float heading, float ax, float ay, float az,
                     float mx, float my, float mz) {
    FILE *fp = fopen("compass_log.txt", "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file\n");
        return;
    }

    fseek(fp, 0, SEEK_END);
    if (ftell(fp) == 0) {
        fprintf(fp, "Timestamp,Heading,AccX,AccY,AccZ,MagX,MagY,MagZ\n");
    }

    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%.2f,%.4f,%.4f,%.4f,%.4f,%.4f,%.4f\n",
            ts, heading, ax, ay, az, mx, my, mz);
    fclose(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (init_lsm303() != 0) {
        gpioTerminate();
        return 1;
    }

    float ax, ay, az, mx, my, mz;
    int consecutive_errors = 0;

    while (running) {
        if (read_accelerometer(&ax, &ay, &az) == 0 &&
            read_magnetometer(&mx, &my, &mz) == 0) {
            consecutive_errors = 0;
            float heading = calculate_heading(ax, ay, az, mx, my, mz);
            log_data(heading, ax, ay, az, mx, my, mz);
        } else {
            consecutive_errors++;
            fprintf(stderr, "Read error #%d\n", consecutive_errors);
            if (consecutive_errors >= 10) {
                fprintf(stderr, "Too many consecutive errors, aborting\n");
                break;
            }
        }

        gpioDelay(100000); /* 100 ms */
    }

    if (i2c_handle_accel >= 0) i2cClose(i2c_handle_accel);
    if (i2c_handle_mag >= 0) i2cClose(i2c_handle_mag);
    gpioTerminate();
    return 0;
}

