    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%.2f,%.4f,%.4f,%.4f,%.4f,%.4f,%.4f\n",
            ts, heading, ax, ay, az, mx, my, mz);
    fclose(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (init_lsm303() != 0) {
        gpioTerminate();
        return 1;
    }

    float ax, ay, az, mx, my, mz;
    int consecutive_errors = 0;

    while (running) {
        if (read_accelerometer(&ax, &ay, &az) == 0 &&
            read_magnetometer(&mx, &my, &mz) == 0) {
            consecutive_errors = 0;
            float heading = calculate_heading(ax, ay, az, mx, my, mz);
            log_data(heading, ax, ay, az, mx, my, mz);
        } else {
            consecutive_errors++;
            fprintf(stderr, "Read error #%d\n", consecutive_errors);
            if (consecutive_errors >= 10) {
                fprintf(stderr, "Too many consecutive errors, aborting\n");
                break;
            }
        }

        gpioDelay(100000); /* 100 ms */
    }

    if (i2c_handle_accel >= 0) i2cClose(i2c_handle_accel);
    if (i2c_handle_mag >= 0) i2cClose(i2c_handle_mag);
    gpioTerminate();
    return 0;
}

