#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SENSOR1_ADDR 0x68
#define SENSOR2_ADDR 0x69
#define I2C_BUS 1
#define SAMPLE_INTERVAL_US 10000
#define DATA_REG 0x01
#define CTRL_REG 0x00
#define CTRL_ENABLE 0x80
#define LOG_FILE "audio_log.dat"

static volatile sig_atomic_t running = 1;
static int i2c_handle1 = -1;
static int i2c_handle2 = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_sensor(int handle) {
    if (i2cWriteByteData(handle, CTRL_REG, CTRL_ENABLE) < 0) {
        fprintf(stderr, "Error writing control register: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_sensor_data(int handle, int16_t *data) {
    int raw = i2cReadWordData(handle, DATA_REG);
    if (raw < 0) {
        fprintf(stderr, "Error reading data register: %s\n", strerror(errno));
        return -1;
    }
    *data = (int16_t)(raw & 0xFFFF);
    return 0;
}

static double calculate_tdoa(int16_t s1, int16_t s2) {
    return (double)s1 - (double)s2;
}

static void log_data(FILE *fp, double sec, double nsec, int16_t s1, int16_t s2, double tdoa) {
    fprintf(fp, "%.6f,%.6f,%d,%d,%.6f\n", sec, nsec, s1, s2, tdoa);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    i2c_handle1 = i2cOpen(I2C_BUS, SENSOR1_ADDR, 0);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Error opening I2C for sensor 1 (0x%02X): %s\n", SENSOR1_ADDR, strerror(errno));
        gpioTerminate();
        return 1;
    }

    i2c_handle2 = i2cOpen(I2C_BUS, SENSOR2_ADDR, 0);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Error opening I2C for sensor 2 (0x%02X): %s\n", SENSOR2_ADDR, strerror(errno));
        i2cClose(i2c_handle1);
        gpioTerminate();
        return 1;
    }

    if (init_sensor(i2c_handle1) != 0 || init_sensor(i2c_handle2) != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return 1;
    }

    fprintf(log_file, "timestamp_sec,timestamp_nsec,sensor1,sensor2,todoa\n");

    while (running) {
        int16_t s1 = 0, s2 = 0;
        struct timespec ts;
        int ret1 = read_sensor_data(i2c_handle1, &s1);
        int ret2 = read_sensor_data(i2c_handle2, &s2);

        if (ret1 != 0 || ret2 != 0) {
            fprintf(stderr, "Sensor read error, retrying...\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        clock_gettime(CLOCK_REALTIME, &ts);
        double tdoa = calculate_tdoa(s1, s2);
        log_data(log_file, ts.tv_sec, ts.tv_nsec, s1, s2, tdoa);

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    fprintf(stderr, "\nShutting down gracefully...\n");
    if (log_file) fclose(log_file);
    if (i2c_handle1 >= 0) i2cClose(i2c_handle1);
    if (i2c_handle2 >= 0) i2cClose(i2c_handle2);
    gpioTerminate();
    return 0;
}

