#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL    0
#define SPI_SPEED      1000000
#define SPI_FLAGS      0x2000  /* mode 3: CPOL=1, CPHA=1 */
#define SAMPLE_PERIOD  100000  /* microseconds (100 ms) */
#define STALL_US       40000   /* 40 us between request and data transfer */
#define CSV_FILENAME   "imu_data.csv"

static volatile sig_atomic_t g_running = 1;
static int  g_spi_handle = -1;
static FILE *g_csv_file  = NULL;

/* ADIS16488A register addresses (7-bit, MSB=0) */
#define REG_X_GYRO   0x04
#define REG_Y_GYRO   0x06
#define REG_Z_GYRO   0x08
#define REG_X_ACCEL  0x0A
#define REG_Y_ACCEL  0x0C
#define REG_Z_ACCEL  0x0E

/* Sensitivities (LSB -> units) */
#define GYRO_LSB_PER_DEG  0.005f
#define ACCEL_LSB_PER_G   0.00025f

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void cleanup(void)
{
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    if (g_csv_file != NULL) {
        fclose(g_csv_file);
        g_csv_file = NULL;
    }
    gpioTerminate();
}

/*
 * Read a 16-bit register from the ADIS16488A.
 * The device returns data on the next 16-bit transfer after a dummy request.
 * A 40 us stall between the request and the data transfer is required.
 * Returns 0 on success, -1 on SPI error.
 */
static int read_register(uint8_t reg, int16_t *out)
{
    char tx[2], rx[2];
    int  ret;

    tx[0] = (char)(reg & 0x7F);          /* MSB = 0, 7-bit address */
    tx[1] = 0x00;

    /* Request the register; data is returned on the next transfer */
    ret = spiXfer(g_spi_handle, tx, rx, 2);
    if (ret != 2) {
        fprintf(stderr, "spiXfer (request) failed for reg 0x%02X: returned %d\n",
                reg, ret);
        return -1;
    }

    gpioDelay(STALL_US);

    /* Dummy transfer to clock out the data */
    tx[0] = 0x00;
    tx[1] = 0x00;
    ret = spiXfer(g_spi_handle, tx, rx, 2);
    if (ret != 2) {
        fprintf(stderr, "spiXfer (data) failed for reg 0x%02X: returned %d\n",
                reg, ret);
        return -1;
    }

    *out = (int16_t)(((uint8_t)rx[0] << 8) | (uint8_t)rx[1]);
    return 0;
}

static int read_gyro(int16_t *x, int16_t *y, int16_t *z)
{
    if (read_register(REG_X_GYRO, x) != 0) return -1;
    if (read_register(REG_Y_GYRO, y) != 0) return -1;
    if (read_register(REG_Z_GYRO, z) != 0) return -1;
    return 0;
}

static int read_accel(int16_t *x, int16_t *y, int16_t *z)
{
    if (read_register(REG_X_ACCEL, x) != 0) return -1;
    if (read_register(REG_Y_ACCEL, y) != 0) return -1;
