#include <gpiod.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000
#define SPI_MODE        SPI_MODE_3
#define SPI_BITS        8
#define CS_PIN          8
#define CHIP_NAME       "gpiochip4"
#define GYRO_SCALE      0.02f
#define ACCEL_SCALE     0.00025f
#define SAMPLE_PERIOD_US 100000

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int spi_transfer(int fd, uint8_t *tx, uint8_t *rx, size_t len) {
    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx;
    tr.rx_buf = (unsigned long)rx;
    tr.len = len;
    tr.speed_hz = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs = 0;
    tr.cs_change = 0;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_register(int fd, uint8_t reg, uint16_t *value) {
    uint8_t tx[2] = { (uint8_t)(reg | 0x80), 0x00 };
    uint8_t rx[2] = { 0 };

    if (spi_transfer(fd, tx, rx, 2) < 0) {
        return -1;
    }

    uint8_t read_tx[2] = { 0x00, 0x00 };
    uint8_t read_rx[2] = { 0 };

    if (spi_transfer(fd, read_tx, read_rx, 2) < 0) {
        return -1;
    }

    *value = ((uint16_t)rx[0] << 8) | rx[1];
    return 0;
}

static int read_gyro(int fd, float *x, float *y, float *z) {
    uint16_t raw;
    if (read_register(fd, 0x04, &raw) < 0) return -1;
    *x = (float)raw * GYRO_SCALE;
    if (read_register(fd, 0x06, &raw) < 0) return -1;
    *y = (float)raw * GYRO_SCALE;
    if (read_register(fd, 0x08, &raw) < 0) return -1;
    *z = (float)raw * GYRO_SCALE;
    return 0;
}

static int read_accel(int fd, float *x, float *y, float *z) {
    uint16_t raw;
    if (read_register(fd, 0x0A, &raw) < 0) return -1;
    *x = (float)raw * ACCEL_SCALE;
    if (read_register(fd, 0x0C, &raw) < 0) return -1;
    *y = (float)raw * ACCEL_SCALE;
    if (read_register(fd, 0x0E, &raw) < 0) return -1;
    *z = (float)raw * ACCEL_SCALE;
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set signal handler: %s\n", strerror(errno));
        return 1;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", CHIP_NAME, strerror(errno));
        return 1;
    }

    struct gpiod_line *cs_line = gpiod_chip_get_line(chip, CS_PIN);
    if (!cs_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", CS_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output(cs_line, "adis16448-cs", 1) < 0) {
        fprintf(stderr, "Failed to request CS line as output: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    int spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", SPI_DEVICE, strerror(errno));
        gpiod_line_release(cs_line);
        gpiod_chip_close(chip);
        return 1;
    }

    uint8_t mode = SPI_MODE;
    uint8_t bits = SPI_BITS;
    uint32_t speed = SPI_SPEED_HZ;

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        goto cleanup;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Failed to set SPI bits per word: %s\n", strerror(errno));
        goto cleanup;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Failed to set SPI max speed: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("ADIS16448 IMU reader started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float gx, gy, gz, ax, ay, az;

        if (read_gyro(spi_fd, &gx, &gy, &gz) < 0) {
            fprintf(stderr, "Gyro read error\n");
        } else if (read_accel(spi_fd, &ax, &ay, &az) < 0) {
            fprintf(stderr, "Accel read error\n");
        } else {
            printf("Gyro: X=%.2f, Y=%.2f, Z=%.2f dps | Accel: X=%.6f, Y=%.6f, Z=%.6f g\n",
                   gx, gy, gz, ax, ay, az);
        }

        usleep(SAMPLE_PERIOD_US);
    }

cleanup:
    if (spi_fd >= 0) close(spi_fd);
    gpiod_line_release(cs_line);
    gpiod_chip_close(chip);
    printf("\nExiting cleanly.\n");
    return 0;
}

