#include <errno.h>

/* ICM-20602 I2C address (SA0 tied to GND) */
#define ICM20602_ADDR 0x68

/* ICM-20602 register addresses */
#define WHO_AM_I      0x75
#define WHO_AM_I_VAL  0x12
#define PWR_MGMT_1    0x6B
#define ACCEL_CONFIG  0x1C
#define GYRO_CONFIG   0x1B
#define ACCEL_XOUT_H  0x3B
#define GYRO_XOUT_H   0x43

/* Expected number of bytes for a burst read of 6 consecutive registers */
#define REG_BYTES 6

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    int16_t x, y, z;
} sensor_data_t;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_icm20602(void) {
    int who = i2cReadByteData(i2c_handle, WHO_AM_I);
    if (who < 0) {
        fprintf(stderr, "Error reading WHO_AM_I: %s\n", strerror(errno));
        return -1;
    }
    if (who != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who, WHO_AM_I_VAL);
        return -1;
    }

    /* Wake up the device (clear SLEEP bit) */
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error writing PWR_MGMT_1: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(10000); /* 10 ms settle */

    /* Set accelerometer range to +/- 2g (AFS_SEL = 0) */
    if (i2cWriteByteData(i2c_handle, ACCEL_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error writing ACCEL_CONFIG: %s\n", strerror(errno));
        return -1;
    }

    /* Set gyroscope range to +/- 250 dps (FS_SEL = 0) */
    if (i2cWriteByteData(i2c_handle, GYRO_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error writing GYRO_CONFIG: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int read_sensor_data(sensor_data_t *accel, sensor_data_t *gyro) {
    char buf[REG_BYTES];

    /* Burst read 6 bytes starting at ACCEL_XOUT_H (0x3B) for accelerometer */
    if (i2cReadI2CBlockData(i2c_handle, ACCEL_XOUT_H, buf, REG_BYTES) != REG_BYTES) {
        fprintf(stderr, "Error reading accelerometer data: %s\n", strerror(errno));
        return -1;
    }
    accel->x = (int16_t)((buf[0] << 8) | buf[1]);
    accel->y = (int16_t)((buf[2] << 8) | buf[3]);
    accel->z = (int16_t)((buf[4] << 8) | buf[5]);

    /* Burst read 6 bytes starting at GYRO_XOUT_H (0x43) for gyroscope */
    if (i2cReadI2CBlockData(i2c_handle, GYRO_XOUT_H, buf, REG_BYTES) != REG_BYTES) {
        fprintf(stderr, "Error reading gyroscope data: %s\n", strerror(errno));
        return -1;
    }
    gyro->x = (int16_t)((buf[0] << 8) | buf[1]);
    gyro->y = (int16_t)((buf[2] << 8) | buf[3]);
    gyro->z = (int16_t)((buf[4] << 8) | buf[5]);

    return 0;
}

static int log_data(sensor_data_t accel, sensor_data_t gyro) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error getting local time\n");
        return -1;
    }
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s,%d,%d,%d,%d,%d,%d\n",
                timestamp, accel.x, accel.y, accel.z,
                gyro.x, gyro.y, gyro.z) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(log_file);
    return 0;
}

int main(void) {
    sensor_data_t accel, gyro;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(1, ICM20602_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus 1 at 0x%02X: %s\n",
                ICM20602_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_icm20602() != 0) {
        fprintf(stderr, "ICM-20602 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen("imu_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "timestamp,accel_x,accel_y,accel_z,gyro_x,gyro_y,gyro_z\n");
        fflush(log_file);
    }

    signal(SIGINT, signal_handler);

    while (!terminate) {
        if (read_sensor_data(&accel, &gyro) == 0) {
            if (log_data(accel, gyro) != 0) {
                fprintf(stderr, "Logging failed, continuing...\n");
            }
        } else {
            fprintf(stderr, "Sensor read failed, continuing...\n");
        }
        gpioDelay(100000); /* 100 ms = 10 Hz */
    }

    fprintf(stderr, "\nShutting down...\n");
    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

