static int read_accel(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buf[6];
    if (write(fd, (uint8_t[]){OUT_X_L}, 1) != 1) {
        fprintf(stderr, "I2C write (reg select) failed: %s\n", strerror(errno));
        return -1;
