    double xg = x / SCALE_FACTOR;
    double yg = y / SCALE_FACTOR;
    double zg = z / SCALE_FACTOR;
    return (fabs(xg) > IMPACT_THRESHOLD || fabs(yg) > IMPACT_THRESHOLD || fabs(zg) > IMPACT_THRESHOLD);
}

static void log_impact(void) {
