#include <math.h>
#include <pigpio.h>

#define LSM6DSR_ADDR 0x6A
#define WHO_AM_I 0x0F
#define WHO_AM_I_VAL 0x6A
#define CTRL1_XL 0x10
#define CTRL2_G 0x11
#define OUTX_L_G 0x22
#define OUTX_H_G 0x23
#define OUTY_L_G 0x24
#define OUTY_H_G 0x25
#define OUTZ_L_G 0x26
#define OUTZ_H_G 0x27
#define OUTX_L_XL 0x28
#define OUTX_H_XL 0x29
#define OUTY_L_XL 0x2A
#define OUTY_H_XL 0x2B
#define OUTZ_L_XL 0x2C
#define OUTZ_H_XL 0x2D

#define ACCEL_RANGE 2.0f
#define GYRO_RANGE 250.0f
#define ACCEL_THRESHOLD 0.2f
#define IMPACT_THRESHOLD 2.5f
#define IMPACT_WINDOW 1.0f
#define SAMPLE_RATE 104.0f
#define SAMPLE_PERIOD_US (1000000.0 / SAMPLE_RATE)

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;

typedef struct {
    float accel_x, accel_y, accel_z;
    float gyro_x, gyro_y, gyro_z;
} sensor_data_t;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_lsm6dsr(void) {
    if (i2cWriteByteData(i2c_handle, CTRL1_XL, 0x80) < 0) {
        fprintf(stderr, "Error: Failed to write CTRL1_XL\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, CTRL2_G, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write CTRL2_G\n");
        return -1;
    }
    return 0;
}

static int read_sensor_data(sensor_data_t *data) {
    char buffer[12];
    if (i2cReadI2CBlockData(i2c_handle, OUTX_L_G, buffer, 12) != 12) {
        fprintf(stderr, "Error: Failed to read sensor data\n");
        return -1;
    }
    int16_t raw_gx = (int16_t)((buffer[1] << 8) | buffer[0]);
    int16_t raw_gy = (int16_t)((buffer[3] << 8) | buffer[2]);
    int16_t raw_gz = (int16_t)((buffer[5] << 8) | buffer[4]);
    int16_t raw_ax = (int16_t)((buffer[7] << 8) | buffer[6]);
    int16_t raw_ay = (int16_t)((buffer[9] << 8) | buffer[8]);
    int16_t raw_az = (int16_t)((buffer[11] << 8) | buffer[10]);

    data->gyro_x = (float)raw_gx / GYRO_RANGE;
    data->gyro_y = (float)raw_gy / GYRO_RANGE;
    data->gyro_z = (float)raw_gz / GYRO_RANGE;
    data->accel_x = (float)raw_ax / (ACCEL_RANGE * 9.81f);
    data->accel_y = (float)raw_ay / (ACCEL_RANGE * 9.81f);
    data->accel_z = (float)raw_az / (ACCEL_RANGE * 9.81f);
    return 0;
}

static float calc_accel_mag(const sensor_data_t *data) {
    return sqrtf(data->accel_x * data->accel_x +
                 data->accel_y * data->accel_y +
                 data->accel_z * data->accel_z);
}

static void log_data(const sensor_data_t *data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(log_file, "%s,%.3f,%.3f,%.3f,%.3f,%.3f,%.3f\n",
            timestamp,
            data->accel_x, data->accel_y, data->accel_z,
            data->gyro_x, data->gyro_y, data->gyro_z);
    fflush(log_file);
}

static void detect_fall(const sensor_data_t *data) {
    static time_t last_impact_time = 0.0f;
    static int in_freefall = 0;
    static int in_impact = 0;
    float accel_mag = calc_accel_mag(data);

    if (accel_mag < ACCEL_THRESHOLD) {
        if (!in_freefall) {
            in_freefall = 1;
            printf("Freefall detected!\n");
        }
    } else if (accel_mag > IMPACT_THRESHOLD) {
        if (!in_impact) {
            in_impact = 1;
            time_t now = time(NULL);
            if (difftime(now, last_impact_time) >= IMPACT_WINDOW) {
                printf("Impact detected!\n");
                last_impact_time = now;
            }
        }
    } else {
        in_freefall = 0;
        in_impact = 0;
    }
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, LSM6DSR_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at 0x%02X\n", LSM6DSR_ADDR);
        gpioTerminate();
        return 1;
    }

    int who = i2cReadByteData(i2c_handle, WHO_AM_I);
    if (who != WHO_AM_I_VAL) {
        fprintf(stderr, "Error: LSM6DSR not found (WHO_AM_I=0x%02X, expected 0x%02X)\n", who, WHO_AM_I_VAL);
        cleanup();
        return 1;
    }

    if (init_lsm6dsr() < 0) {
        fprintf(stderr, "Error: LSM6DSR initialisation failed\n");
        cleanup();
        return 1;
    }

    log_file = fopen("motion_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        cleanup();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    sensor_data_t sensor_data;
    while (running) {
        if (read_sensor_data(&sensor_data) == 0) {
            log_data(&sensor_data);
            detect_fall(&sensor_data);
        }
        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return 0;
}

