#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <pigpio.h>

/* L3G4200D I2C address (SA0 tied to GND) */
#define GYRO_ADDR 0x69

/* L3G4200D register addresses */
#define WHO_AM_I   0x0F
#define CTRL_REG1  0x20
#define CTRL_REG4  0x23
#define OUT_X_L    0x28

/* Expected device ID */
#define WHO_AM_I_VAL 0xD3

/* Sensitivity for +/-250 dps range: 8.75 mdps/LSB = 114.285 dps/°C */
#define SENSITIVITY 114.285f

/* Sampling interval in microseconds */
#define SAMPLE_INTERVAL_US 10000

/* Retry count for I2C writes */
#define I2C_RETRY_COUNT 3

/* Global state for signal handler */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler for graceful shutdown (Ctrl+C)                        */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a byte to an I2C register with retry                            */
/* ------------------------------------------------------------------ */
static int i2c_write_reg_retry(int handle, uint8_t reg, uint8_t value)
{
    for (int attempt = 0; attempt < I2C_RETRY_COUNT; attempt++) {
        int rc = i2cWriteByteData(handle, reg, value);
        if (rc == 0)
            return 0;
        fprintf(stderr, "I2C write attempt %d failed (reg=0x%02X, val=0x%02X, rc=%d)\n",
                attempt + 1, reg, value, rc);
        gpioDelay(1000); /* 1 ms backoff */
    }
    return -1;
}

/* ------------------------------------------------------------------ */
/* Read a byte from an I2C register with retry                            */
/* ------------------------------------------------------------------ */
static int i2c_read_reg_retry(int handle, uint8_t reg)
{
    for (int attempt = 0; attempt < I2C_RETRY_COUNT; attempt++) {
        int rc = i2cReadByteData(handle, reg);
        if (rc >= 0)
            return rc;
        fprintf(stderr, "I2C read attempt %d failed (reg=0x%02X, rc=%d)\n",
                attempt + 1, reg, rc);
        gpioDelay(1000);
    }
    return -1;
}

/* ------------------------------------------------------------------ */
/* Initialize the L3G4200D gyroscope                                      */
/* ------------------------------------------------------------------ */
static int init_gyro(int handle)
{
    /* Verify device identity */
    int who = i2c_read_reg_retry(handle, WHO_AM_I);
    if (who < 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register\n");
        return -1;
    }
    if (who != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who, WHO_AM_I_VAL);
        return -1;
    }

    /* CTRL_REG1: normal mode, all axes enabled */
    if (i2c_write_reg_retry(handle, CTRL_REG1, 0x0F) != 0) {
        fprintf(stderr, "Failed to write CTRL_REG1\n");
        return -1;
    }

    /* CTRL_REG4: +/-250 dps full-scale range, high-resolution disabled */
    if (i2c_write_reg_retry(handle, CTRL_REG4, 0x00) != 0) {
        fprintf(stderr, "Failed to write CTRL_REG4\n");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read 6 bytes of gyroscope data (X, Y, Z) in one block read            */
/* ------------------------------------------------------------------ */
static int read_gyro_data(int handle, float *x, float *y, float *z)
{
    char buffer[6];
    int rc = i2cReadI2CBlockData(handle, OUT_X_L, buffer, 6);
    if (rc != 6) {
        fprintf(stderr, "I2C block read failed (rc=%d)\n", rc);
        return -1;
    }

    int16_t raw_x = (int16_t)((buffer[1] << 8) | (uint8_t)buffer[0]);
    int16_t raw_y = (int16_t)((buffer[3] << 8) | (uint8_t)buffer[2]);
    int16_t raw_z = (int16_t)((buffer[5] << 8) | (uint8_t)buffer[4]);

    *x = (float)raw_x / SENSITIVITY;
    *y = (float)raw_y / SENSITIVITY;
    *z = (float)raw_z / SENSITIVITY;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Log a timestamped gyroscope reading to CSV                            */
/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, float x, float y, float z)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return;
    }

    fprintf(fp, "%ld.%09ld,%.6f,%.6f,%.6f\n",
            (long)ts.tv_sec, (long)ts.tv_nsec, x, y, z);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at GYRO_ADDR */
    g_i2c_handle = i2cOpen(1, GYRO_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus 1 at 0x%02X (rc=%d)\n",
                GYRO_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize gyroscope */
    if (init_gyro(g_i2c_handle) != 0) {
        fprintf(stderr, "Gyroscope initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    g_log_file = fopen("gyro_log.csv", "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Failed to open gyro_log.csv: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write header if file is empty */
    fseek(g_log_file, 0, SEEK_END);
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "Timestamp,X,Y,Z\n");
        fflush(g_log_file);
    }

    /* Register signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Gyroscope logging started. Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (g_running) {
        float x, y, z;
        if (read_gyro_data(g_i2c_handle, &x, &y, &z) == 0) {
            log_data(g_log_file, x, y, z);
        } else {
            fprintf(stderr, "Error reading gyroscope data\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

