#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define MMA8452Q_ADDR  0x1D
#define WHO_AM_I       0x0D
#define WHO_AM_I_VAL   0x2A
#define CTRL_REG1      0x2A
#define OUT_X_MSB      0x01
#define OUT_X_LSB      0x02
#define OUT_Y_MSB      0x03
#define OUT_Y_LSB      0x04
#define OUT_Z_MSB      0x05
#define OUT_Z_LSB      0x06
#define LOG_FILE       "fall_log.txt"
#define TILT_THRESHOLD 45.0f
#define SAMPLE_PERIOD_US 10000

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C block read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_mma8452q(int fd) {
    uint8_t who_am_i = 0;
    if (i2c_read_reg(fd, WHO_AM_I, &who_am_i) < 0) {
        return -1;
    }
    if (who_am_i != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n", who_am_i, WHO_AM_I_VAL);
        return -1;
    }
    printf("MMA8452Q detected (WHO_AM_I = 0x%02X)\n", who_am_i);

    uint8_t ctrl1 = 0;
    if (i2c_read_reg(fd, CTRL_REG1, &ctrl1) < 0) {
        return -1;
    }
    ctrl1 &= ~(1 << 0);  /* standby */
    ctrl1 |= (2 << 5);   /* 100 Hz data rate */
    if (i2c_write_reg(fd, CTRL_REG1, ctrl1) < 0) {
        return -1;
    }
    if (i2c_write_reg(fd, CTRL_REG1, ctrl1 | (1 << 0)) < 0) {
        return -1;
    }
    return 0;
}

static int read_accel(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buf[6];
    if (i2c_read_block(fd, OUT_X_MSB, buf, 6) < 0) {
        return -1;
    }
    int16_t x_raw = (int16_t)((buf[0] << 8) | buf[1]) >> 4;
    int16_t y_raw = (int16_t)((buf[2] << 8) | buf[3]) >> 4;
    int16_t z_raw = (int16_t)((buf[4] << 8) | buf[5]) >> 4;
    *x = x_raw;
    *y = y_raw;
    *z = z_raw;
    return 0;
}

static void log_fall(int16_t x, int16_t y, int16_t z) {
    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];
    localtime_r(&now, &tm_info);
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);
    fprintf(g_log_fp, "%s, X=%d, Y=%d, Z=%d\n", ts, x, y, z);
    fflush(g_log_fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        return 1;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        fclose(g_log_fp);
        return 1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, MMA8452Q_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n", MMA8452Q_ADDR, strerror(errno));
        close(g_i2c_fd);
        fclose(g_log_fp);
        return 1;
    }

    if (init_mma8452q(g_i2c_fd) < 0) {
        fprintf(stderr, "MMA8452Q initialization failed\n");
        close(g_i2c_fd);
        fclose(g_log_fp);
        return 1;
    }

    printf("Monitoring for falls (threshold %.0f degrees)...\n", TILT_THRESHOLD);

    while (g_running) {
        int16_t x, y, z;
        if (read_accel(g_i2c_fd, &x, &y, &z) < 0) {
            usleep(SAMPLE_PERIOD_US);
            continue;
        }

        float tilt = atan2f((float)x, sqrtf((float)y * y + (float)z * z)) * 180.0f / (float)M_PI;
        if (fabsf(tilt) > TILT_THRESHOLD) {
            log_fall(x, y, z);
        }
        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    if (g_i2c_fd >= 0) close(g_i2c_fd);
    if (g_log_fp) fclose(g_log_fp);
    return 0;
}

