    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (burst reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != len) {
        fprintf(stderr, "I2C burst read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int lis3mdl_init(int fd) {
    uint8_t who;
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (i2c_read_reg(fd, WHO_AM_I, &who) == 0 && who == WHO_AM_I_VAL) {
            printf("LIS3MDL detected (WHO_AM_I=0x%02X)\n", who);
            break;
        }
        fprintf(stderr, "WHO_AM_I mismatch (got 0x%02X, expected 0x%02X), attempt %d/%d\n",
                who, WHO_AM_I_VAL, attempt + 1, MAX_RETRIES);
        usleep(10000);
    }
    if (who != WHO_AM_I_VAL) {
        fprintf(stderr, "LIS3MDL not detected after %d attempts\n", MAX_RETRIES);
        return -1;
    }
    if (i2c_write_reg(fd, CTRL_REG1, 0x70) != 0) return -1;
    if (i2c_write_reg(fd, CTRL_REG2, 0x00) != 0) return -1;
    if (i2c_write_reg(fd, CTRL_REG3, 0x00) != 0) return -1;
    if (i2c_write_reg(fd, CTRL_REG4, 0x0C) != 0) return -1;
    return 0;
}

static int read_magnetometer(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buf[6];
    if (i2c_read_burst(fd, OUT_X_L, buf, 6) != 0) return -1;
    *x = (int16_t)((buf[1] << 8) | buf[0]);
    *y = (int16_t)((buf[3] << 8) | buf[2]);
    *z = (int16_t)((buf[5] << 8) | buf[4]);
    return 0;
}

static void apply_calibration(int16_t raw_x, int16_t raw_y, int16_t raw_z,
                              float *x_mg, float *y_mg, float *z_mg) {
    const float x_offset = 0.0f, x_scale = 0.146f;
    const float y_offset = 0.0f, y_scale = 0.146f;
    const float z_offset = 0.0f, z_scale = 0.146f;
    *x_mg = ((float)raw_x - x_offset) * x_scale;
    *y_mg = ((float)raw_y - y_offset) * y_scale;
    *z_mg = ((float)raw_z - z_offset) * z_scale;
}

static void log_data(FILE *fp, float x_mg, float y_mg, float z_mg) {
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f,%.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, x_mg, y_mg, z_mg);
    fflush(fp);
}

static void check_metal_threshold(float x_mg, float y_mg, float z_mg) {
    float mag = sqrtf(x_mg * x_mg + y_mg * y_mg + z_mg * z_mg);
    if (mag > METAL_THRESHOLD) {
        fprintf(stderr, "MAGNETIC FIELD ALERT: %.2f mG (X=%.2f Y=%.2f Z=%.2f)\n",
                mag, x_mg, y_mg, z_mg);
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("open " I2C_BUS);
        return 1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, LIS3MDL_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(i2c_fd);
        return 1;
    }
    if (lis3mdl_init(i2c_fd) != 0) {
        fprintf(stderr, "LIS3MDL initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    log_fp = fopen("magnetic_log.txt", "a");
    if (!log_fp) {
        perror("fopen magnetic_log.txt");
        close(i2c_fd);
        return 1;
    }

    printf("Logging magnetic data to magnetic_log.txt at 10 Hz. Press Ctrl+C to stop.\n");

    while (running) {
        int16_t raw_x, raw_y, raw_z;
        if (read_magnetometer(i2c_fd, &raw_x, &raw_y, &raw_z) != 0) {
            fprintf(stderr, "Read error, continuing...\n");
            usleep(SAMPLE_PERIOD_US);
            continue;
        }
        float x_mg, y_mg, z_mg;
        apply_calibration(raw_x, raw_y, raw_z, &x_mg, &y_mg, &z_mg);
        log_data(log_fp, x_mg, y_mg, z_mg);
        check_metal_threshold(x_mg, y_mg, z_mg);
        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down cleanly...\n");
    if (log_fp) fclose(log_fp);
    if (i2c_fd >= 0) close(i2c_fd);
    return 0;
}

