#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SAMPLE_INTERVAL_US 100000
#define RETRY_COUNT 3
#define RETRY_DELAY_US 1000

#define ADXL354_REG_PARTID 0x01
#define ADXL354_REG_XDATA 0x08
#define ADXL354_REG_YDATA 0x0B
#define ADXL354_REG_ZDATA 0x0E
#define ADXL354_REG_STATUS 0x04
#define ADXL354_REG_POWER_CTL 0x2D
#define ADXL354_REG_RESET 0x1F

#define ADXL354_PARTID 0x1D
#define ADXL354_SENSITIVITY 0.0000039f

static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int spi_write_byte(uint8_t reg, uint8_t value) {
    char tx[2] = { (char)(reg & 0x7F), (char)value };
    char rx[2] = {0};
    int ret = spiXfer(spi_handle, tx, rx, 2);
    if (ret != 2) {
        fprintf(stderr, "SPI write error: reg=0x%02X, ret=%d\n", reg, ret);
        return -1;
    }
    return 0;
}

static int spi_read_byte(uint8_t reg, uint8_t *value) {
    char tx[2] = { (char)(reg | 0x80), 0x00 };
    char rx[2] = {0};
    int ret = spiXfer(spi_handle, tx, rx, 2);
    if (ret != 2) {
        fprintf(stderr, "SPI read error: reg=0x%02X, ret=%d\n", reg, ret);
        return -1;
    }
    *value = (uint8_t)rx[1];
    return 0;
}

static int spi_read_block(uint8_t reg, uint8_t *buf, uint32_t len) {
    char tx[32] = {0};
    char rx[32] = {0};
    int ret = spiXfer(spi_handle, tx, rx, len + 1);
    if (ret != (int)(len + 1)) {
        fprintf(stderr, "SPI block read error: reg=0x%02X, ret=%d\n", reg, ret);
        return -1;
    }
    memcpy(buf, rx + 1, len);
    return 0;
}

static int adxl354_reset(void) {
    if (spi_write_byte(ADXL354_REG_RESET, 0x52) != 0) return -1;
    gpioDelay(1000);
    return 0;
}

static int adxl354_init(void) {
    uint8_t partid = 0;
    if (spi_read_byte(ADXL354_REG_PARTID, &partid) != 0) {
        fprintf(stderr, "Failed to read PARTID\n");
        return -1;
    }
    if (partid != ADXL354_PARTID) {
        fprintf(stderr, "Unexpected PARTID: 0x%02X (expected 0x%02X)\n", partid, ADXL354_PARTID);
        return -1;
    }
    if (adxl354_reset() != 0) return -1;
    gpioDelay(1000);
    if (spi_write_byte(ADXL354_REG_POWER_CTL, 0x00) != 0) return -1;
    uint8_t status = 0;
    for (int i = 0; i < 10; i++) {
        if (spi_read_byte(ADXL354_REG_STATUS, &status) != 0) return -1;
        if ((status & 0x01) == 0) break;
        gpioDelay(1000);
    }
    if ((status & 0x01) != 0) {
        fprintf(stderr, "ADXL354 not ready after reset\n");
        return -1;
    }
    if (spi_write_byte(ADXL354_REG_POWER_CTL, 0x02) != 0) return -1;
    return 0;
}

static int read_axis(uint8_t reg, int16_t *out) {
    uint8_t buf[3];
    for (int attempt = 0; attempt < RETRY_COUNT; attempt++) {
        if (spi_read_block(reg, buf, 3) == 0) {
            int32_t raw = ((int32_t)buf[0] << 16) | ((int32_t)buf[1] << 8) | buf[2];
            raw >>= 5;
            *out = (int16_t)raw;
            return 0;
        }
        gpioDelay(RETRY_DELAY_US);
    }
    return -1;
}

static int log_data(int16_t x, int16_t y, int16_t z) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    if (fprintf(log_file, "%s, X: %d, Y: %d, Z: %d\n", ts, x, y, z) < 0) {
        fprintf(stderr, "Failed to write to log file\n");
        return -1;
    }
    fflush(log_file);
    return 0;
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, (1 << 8) | SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }
    if (adxl354_init() != 0) {
        fprintf(stderr, "ADXL354 initialisation failed\n");
        cleanup();
        return 1;
    }
    log_file = fopen("vibration_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);
    printf("ADXL354 logging started. Press Ctrl+C to stop.\n");
    while (!terminate) {
        int16_t x = 0, y = 0, z = 0;
        if (read_axis(ADXL354_REG_XDATA, &x) != 0 ||
            read_axis(ADXL354_REG_YDATA, &y) != 0 ||
            read_axis(ADXL354_REG_ZDATA, &z) != 0) {
            fprintf(stderr, "Read error, continuing...\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }
        if (log_data(x, y, z) != 0) {
            fprintf(stderr, "Logging error\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }
    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

