#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// ADIS16362 Register Addresses
#define X_GYRO_REG 0x04
#define Y_GYRO_REG 0x06
#define Z_GYRO_REG 0x08
#define X_ACCL_REG 0x0A
#define Y_ACCL_REG 0x0C
#define Z_ACCL_REG 0x0E

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define SPI_FLAGS 0x0003 // Mode 3 (CPOL=1, CPHA=1)

// Scaling factors
#define GYRO_SCALE 0.05f // deg/sec/LSB
#define ACCL_SCALE 0.0025f // g/LSB

// Global variables for cleanup
static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_read_register(int handle, uint8_t reg_addr, uint16_t *data);
int read_gyro_data(int handle, float *x, float *y, float *z);
int read_accel_data(int handle, float *x, float *y, float *z);
int log_data(FILE *fp, float x_gyro, float y_gyro, float z_gyro, float x_accel, float y_accel, float z_accel);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

// Read a 16-bit register from the ADIS16362
int spi_read_register(int handle, uint8_t reg_addr, uint16_t *data) {
    char tx_buf[2];
    char rx_buf[2];

    // ADIS16362 SPI read: send address with MSB set, then dummy byte
    tx_buf[0] = reg_addr | 0x80; // MSB set for read
    tx_buf[1] = 0x00;            // Dummy byte

    int result = spiXfer(handle, tx_buf, rx_buf, 2);
    if (result != 2) {
        fprintf(stderr, "SPI read error: spiXfer returned %d\n", result);
        return -1;
    }

    // Data is returned on the next transfer (stall = 0)
    tx_buf[0] = 0x00;
    tx_buf[1] = 0x00;
    result = spiXfer(handle, tx_buf, rx_buf, 2);
    if (result != 2) {
        fprintf(stderr, "SPI read error: spiXfer returned %d\n", result);
        return -1;
    }

    *data = ((uint16_t)(rx_buf[0] << 8)) | (uint16_t)(rx_buf[1] & 0xFF);
    return 0;
}

// Read gyroscope data from the ADIS16362
int read_gyro_data(int handle, float *x, float *y, float *z) {
    uint16_t raw_x, raw_y, raw_z;

    if (spi_read_register(handle, X_GYRO_REG, &raw_x) != 0) return -1;
    if (spi_read_register(handle, Y_GYRO_REG, &raw_y) != 0) return -1;
    if (spi_read_register(handle, Z_GYRO_REG, &raw_z) != 0) return -1;

    *x = (float)raw_x * GYRO_SCALE;
    *y = (float)raw_y * GYRO_SCALE;
    *z = (float)raw_z * GYRO_SCALE;

    return 0;
}

// Read accelerometer data from the ADIS16362
int read_accel_data(int handle, float *x, float *y, float *z) {
    uint16_t raw_x, raw_y, raw_z;

    if (spi_read_register(handle, X_ACCL_REG, &raw_x) != 0) return -1;
    if (spi_read_register(handle, Y_ACCL_REG, &raw_y) != 0) return -1;
    if (spi_read_register(handle, Z_ACCL_REG, &raw_z) != 0) return -1;

    *x = (float)raw_x * ACCL_SCALE;
    *y = (float)raw_y * ACCL_SCALE;
    *z = (float)raw_z * ACCL_SCALE;

    return 0;
}

// Log data to a CSV file
int log_data(FILE *fp, float x_gyro, float y_gyro, float z_gyro, float x_accel, float y_accel, float z_accel) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    double timestamp = ts.tv_sec + ts.tv_nsec / 1e9;

    if (fprintf(fp, "%.9f,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f\n",
                timestamp, x_gyro, y_gyro, z_gyro, x_accel, y_accel, z_accel) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }
