#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip4"
#define GPIO_LINE_OFFSET 17
#define POLL_INTERVAL_SEC 1

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void log_timestamped(const char *msg) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char buf[32];
    strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", t);
    printf("[%s] %s\n", buf, msg);
    fflush(stdout);
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handler for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the GPIO line for pin 17 */
    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (!line) {
        perror("gpiod_chip_get_line");
        goto cleanup_chip;
    }

    /* Request the line as input */
    if (gpiod_line_request_input(line, "ir-obstacle") < 0) {
        perror("gpiod_line_request_input");
        goto cleanup_chip;
    }

    log_timestamped("Obstacle detection system started. Monitoring GPIO17.");

    while (program_running) {
        int val = gpiod_line_get_value(line);
        if (val < 0) {
            perror("gpiod_line_get_value");
            log_timestamped("Error reading GPIO value.");
            break;
        }

        /* E18-D80NK: LOW (0) means obstacle detected */
        if (val == 0) {
            log_timestamped("Obstacle detected! Initiating self-parking sequence.");
            sleep(2);
            log_timestamped("Self-parking sequence completed.");
        }

        sleep(POLL_INTERVAL_SEC);
    }

    log_timestamped("Obstacle detection system stopped.");
    ret = EXIT_SUCCESS;

cleanup_chip:
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

