/*
 * KY-032 IR obstacle avoidance collision avoidance system
 * Board:  Raspberry Pi 3 Model B+
 * Library: libgpiod v2 API
 *
 * Wiring:
 *   KY-032 #1  -> GPIO17 (BCM 17, physical pin 11)
 *   KY-032 #2  -> GPIO27 (BCM 27, physical pin 13)
 *   KY-032 VCC -> 3.3 V (physical pin 1)
 *   KY-032 GND -> GND  (physical pin 6)
 *
 * The KY-032 output is active-low: 0 = obstacle detected, 1 = clear.
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o ky032_av ky032_av.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME  "gpiochip0"
#define GPIO_PIN_1      17
#define GPIO_PIN_2      27
#define POLL_INTERVAL_MS 100

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static void print_timestamp(void)
{
    time_t now = time(NULL);
    struct tm tm_info;
    char buf[32];

    if (localtime_r(&now, &tm_info) != NULL &&
        strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", &tm_info) > 0) {
        printf("[%s] ", buf);
    }
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line_request *req = NULL;
    struct gpiod_line_settings *settings = NULL;
    struct gpiod_line_config *line_cfg = NULL;
    struct gpiod_request_config *req_cfg = NULL;
    struct gpiod_line_bulk *bulk = NULL;
    int ret = EXIT_FAILURE;

    /* --- Signal handling for clean shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Open the GPIO chip --- */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Configure both lines as inputs --- */
    settings = gpiod_line_settings_new();
    if (settings == NULL) {
        fprintf(stderr, "gpiod_line_settings_new failed: %s\n", strerror(errno));
        goto cleanup;
    }

    gpiod_line_settings_set_direction(settings, GPIOD_LINE_DIRECTION_INPUT);

    line_cfg = gpiod_line_config_new();
    if (line_cfg == NULL) {
        fprintf(stderr, "gpiod_line_config_new failed: %s\n", strerror(errno));
        goto cleanup;
    }

    unsigned int offsets[2] = { GPIO_PIN_1, GPIO_PIN_2 };
    if (gpiod_line_config_add_line_settings(line_cfg, offsets, 2, settings) != 0) {
        fprintf(stderr, "gpiod_line_config_add_line_settings failed: %s\n", strerror(errno));
        goto cleanup;
    }

    req_cfg = gpiod_request_config_new();
    if (req_cfg == NULL) {
        fprintf(stderr, "gpiod_request_config_new failed: %s\n", strerror(errno));
        goto cleanup;
    }
    gpiod_request_config_set_consumer(req_cfg, "ky032_av");

    bulk = gpiod_line_bulk_new();
    if (bulk == NULL) {
        fprintf(stderr, "gpiod_line_bulk_new failed: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_bulk_add(line_cfg, bulk, offsets, 2) != 0) {
        fprintf(stderr, "gpiod_line_bulk_add failed: %s\n", strerror(errno));
        goto cleanup;
    }

    req = gpiod_chip_request_lines(chip, req_cfg, bulk);
    if (req == NULL) {
        fprintf(stderr, "gpiod_chip_request_lines failed: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("KY-032 obstacle avoidance system started.\n");
    printf("  Sensor 1: GPIO%d (BCM)\n", GPIO_PIN_1);
    printf("  Sensor 2: GPIO%d (BCM)\n", GPIO_PIN_2);
    printf("  Poll interval: %d ms\n", POLL_INTERVAL_MS);
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    /* --- Main polling loop --- */
    while (g_running) {
        enum gpiod_line_value vals[2];
        int read_ret = gpiod_line_request_get_values(req, vals);

        if (read_ret != 0) {
            fprintf(stderr, "gpiod_line_request_get_values failed: %s\n", strerror(errno));
            break;
        }

        /* KY-032 is active-low: 0 = obstacle detected */
        int obstacle1 = (vals[0] == GPIOD_LINE_VALUE_ACTIVE) ? 0 : 1;
        int obstacle2 = (vals[1] == GPIOD_LINE_VALUE_ACTIVE) ? 0 : 1;

        print_timestamp();
        printf("Sensor 1: %s | Sensor 2: %s\n",
               obstacle1 ? "OBSTACLE" : "CLEAR",
               obstacle2 ? "OBSTACLE" : "CLEAR");
        fflush(stdout);

        usleep(POLL_INTERVAL_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (bulk != NULL)
        gpiod_line_bulk_free(bulk);
    if (req_cfg != NULL)
        gpiod_request_config_free(req_cfg);
    if (line_cfg != NULL)
        gpiod_line_config_free(line_cfg);
    if (settings != NULL)
        gpiod_line_settings_free(settings);
    if (req != NULL)
        gpiod_line_request_release(req);
    if (chip != NULL)
        gpiod_chip_close(chip);

    if (ret == EXIT_SUCCESS)
        printf("\nExiting cleanly.\n");

    return ret;
}

