    uint8_t tx[2] = { (uint8_t)(reg | 0x80), 0x00 };
    uint8_t rx[2] = { 0 };
    if (spi_transfer(fd, tx, rx, 2) < 0) return -1;
    *value = rx[1];
    return 0;
}

static int spi_write_register(int fd, uint8_t reg, uint8_t value) {
    uint8_t tx[2] = { (uint8_t)(reg & 0x7F), value };
    uint8_t rx[2] = { 0 };
    return spi_transfer(fd, tx, rx, 2);
}

static int read_gyro_data(int fd, float *x, float *y, float *z) {
    uint8_t x_raw, y_raw, z_raw;

    if (spi_read_register(fd, ADIS16266_REG_XGYRO_OUT, &x_raw) < 0) return -1;
    if (spi_read_register(fd, ADIS16266_REG_YGYRO_OUT, &y_raw) < 0) return -1;
    if (spi_read_register(fd, ADIS16266_REG_ZGYRO_OUT, &z_raw) < 0) return -1;

