        perror("SPI_IOC_WR_MODE failed");
        goto cleanup;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("SPI_IOC_WR_BITS_PER_WORD failed");
        goto cleanup;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("SPI_IOC_WR_MAX_SPEED_HZ failed");
        goto cleanup;
    }

    if (gpiod_line_set_value(cs_line, 0) < 0) {
        perror("gpiod_line_set_value (CS low) failed");
        goto cleanup;
    }

    if (spi_write_register(spi_fd, ADIS16266_REG_MSC_CTRL, 0x01) < 0) {
        fprintf(stderr, "Failed to write MSC_CTRL register\n");
        goto cleanup;
    }

