#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* LSM6DSR I2C 7-bit address */
#define LSM6DSR_ADDR 0x6B

/* WHO_AM_I register (0x0F) expected value */
#define LSM6DSR_WHO_AM_I 0x6B

/* WHO_AM_I register address */
#define WHO_AM_I_REG 0x0F

/* CTRL1_XL: accelerometer ODR = 104 Hz, FS_XL = +/-2g */
#define CTRL1_XL 0x10
#define CTRL1_XL_VAL 0x42

/* CTRL2_G: gyroscope ODR = 104 Hz, FS_G = +/-250 dps */
#define CTRL2_G 0x11
#define CTRL2_G_VAL 0x42

/* OUTX_L_G: gyro data starts here (0x22) */
#define OUTX_L_G 0x22

/* Sensitivities */
#define GYRO_SENSITIVITY 0.00875f   /* dps per LSB at +/-250 dps */
#define ACCEL_SENSITIVITY 0.000061f /* g per LSB at +/-2g */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int write_register(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing register 0x%02X (value 0x%02X): pigpio error %d\n",
                reg, value, rc);
        return -1;
    }
    return 0;
}

static int read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len)
{
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc != (int)len) {
        fprintf(stderr, "Error reading block from 0x%02X: pigpio returned %d (expected %u)\n",
                reg, rc, len);
        return -1;
    }
    return 0;
}

static int verify_sensor(int handle)
{
    int who = i2cReadByteData(handle, WHO_AM_I_REG);
    if (who < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: pigpio error %d\n", who);
        return -1;
    }
    if (who != LSM6DSR_WHO_AM_I) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who, LSM6DSR_WHO_AM_I);
        return -1;
    }
    return 0;
}

int main(void)
{
    /* Install SIGINT handler for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at LSM6DSR address */
    g_i2c_handle = i2cOpen(1, LSM6DSR_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus 1 at address 0x%02X: pigpio error %d\n",
                LSM6DSR_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Verify sensor identity */
    if (verify_sensor(g_i2c_handle) != 0) {
        fprintf(stderr, "LSM6DSR not detected at address 0x%02X\n", LSM6DSR_ADDR);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure accelerometer: 104 Hz, +/-2g */
    if (write_register(g_i2c_handle, CTRL1_XL, CTRL1_XL_VAL) != 0) {
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure gyroscope: 104 Hz, +/-250 dps */
    if (write_register(g_i2c_handle, CTRL2_G, CTRL2_G_VAL) != 0) {
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Allow sensor to settle after configuration */
    gpioDelay(100000); /* 100 ms */

    uint8_t data[12];
    int16_t gyro_x, gyro_y, gyro_z;
    int16_t accel_x, accel_y, accel_z;

    while (g_running) {
        /* Burst-read 12 bytes starting at OUTX_L_G (0x22):
         *   bytes 0-5  : gyro X/Y/Z (little-endian)
         *   bytes 6-11 : accel X/Y/Z (little-endian)
         */
        if (read_block(g_i2c_handle, OUTX_L_G, data, 12) != 0) {
            fprintf(stderr, "Failed to read sensor data block\n");
            break;
        }

        gyro_x = (int16_t)((data[1] << 8) | data[0]);
        gyro_y = (int16_t)((data[3] << 8) | data[2]);
        gyro_z = (int16_t)((data[5] << 8) | data[4]);
        accel_x = (int16_t)((data[7] << 8) | data[6]);
        accel_y = (int16_t)((data[9] << 8) | data[8]);
        accel_z = (int16_t)((data[11] << 8) | data[10]);

        float gyro_x_dps = gyro_x * GYRO_SENSITIVITY;
        float gyro_y_dps = gyro_y * GYRO_SENSITIVITY;
        float gyro_z_dps = gyro_z * GYRO_SENSITIVITY;
        float accel_x_g = accel_x * ACCEL_SENSITIVITY;
        float accel_y_g = accel_y * ACCEL_SENSITIVITY;
        float accel_z_g = accel_z * ACCEL_SENSITIVITY;

        printf("Gyro: X=%.3f dps, Y=%.3f dps, Z=%.3f dps | "
               "Accel: X=%.3f g, Y=%.3f g, Z=%.3f g\n",
               gyro_x_dps, gyro_y_dps, gyro_z_dps,
               accel_x_g, accel_y_g, accel_z_g);

        fflush(stdout);

        gpioDelay(100000); /* 100 ms */
    }

    /* Clean shutdown */
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

