    int16_t accel_x, accel_y, accel_z;

    while (g_running) {
        /* Burst-read 12 bytes starting at OUTX_L_G (0x22):
         *   bytes 0-5  : gyro X/Y/Z (little-endian)
         *   bytes 6-11 : accel X/Y/Z (little-endian)
         */
        if (read_block(g_i2c_handle, OUTX_L_G, data, 12) != 0) {
            fprintf(stderr, "Failed to read sensor data block\n");
            break;
        }

        gyro_x = (int16_t)((data[1] << 8) | data[0]);
        gyro_y = (int16_t)((data[3] << 8) | data[2]);
        gyro_z = (int16_t)((data[5] << 8) | data[4]);
        accel_x = (int16_t)((data[7] << 8) | data[6]);
        accel_y = (int16_t)((data[9] << 8) | data[8]);
        accel_z = (int16_t)((data[11] << 8) | data[10]);

        float gyro_x_dps = gyro_x * GYRO_SENSITIVITY;
        float gyro_y_dps = gyro_y * GYRO_SENSITIVITY;
        float gyro_z_dps = gyro_z * GYRO_SENSITIVITY;
        float accel_x_g = accel_x * ACCEL_SENSITIVITY;
        float accel_y_g = accel_y * ACCEL_SENSITIVITY;
        float accel_z_g = accel_z * ACCEL_SENSITIVITY;

        printf("Gyro: X=%.3f dps, Y=%.3f dps, Z=%.3f dps | "
               "Accel: X=%.3f g, Y=%.3f g, Z=%.3f g\n",
               gyro_x_dps, gyro_y_dps, gyro_z_dps,
               accel_x_g, accel_y_g, accel_z_g);

        fflush(stdout);

        gpioDelay(100000); /* 100 ms */
    }

    /* Clean shutdown */
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

