#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FXOS8700_ADDR 0x1D
#define WHO_AM_I_REG 0x0D
#define WHO_AM_I_VAL 0xC7
#define CTRL_REG1 0x2A
#define CTRL_REG2 0x2B
#define M_CTRL_REG1 0x5B
#define M_CTRL_REG2 0x5C
#define OUT_X_MSB 0x01
#define DATA_LENGTH 12

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg(int handle, uint8_t reg, uint8_t *val) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read error at reg 0x%02X: %d\n", reg, rc);
        return -1;
    }
    *val = (uint8_t)rc;
    return 0;
}

static int i2c_write_reg(int handle, uint8_t reg, uint8_t val) {
    int rc = i2cWriteByteData(handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "I2C write error at reg 0x%02X: %d\n", reg, rc);
        return -1;
    }
    return 0;
}

static int init_fxos8700(int handle) {
    uint8_t who_am_i = 0;
    if (i2c_read_reg(handle, WHO_AM_I_REG, &who_am_i) != 0) {
        fprintf(stderr, "Cannot read WHO_AM_I — sensor absent or bus error\n");
        return -1;
    }
    if (who_am_i != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who_am_i, WHO_AM_I_VAL);
        return -1;
    }

    /* Standby mode to allow configuration changes */
    if (i2c_write_reg(handle, CTRL_REG1, 0x00) != 0) return -1;
    if (i2c_write_reg(handle, CTRL_REG2, 0x00) != 0) return -1;

    /* Enable accelerometer (ODR=100Hz, 14-bit) and hybrid mode */
    if (i2c_write_reg(handle, CTRL_REG1, 0x00 | 0x01 | 0x02) != 0) return -1;

    /* Enable magnetometer (ODR=80Hz, 16-bit) */
    if (i2c_write_reg(handle, M_CTRL_REG1, 0x00 | 0x01) != 0) return -1;

    /* 12.15ms integration time for magnetometer */
    if (i2c_write_reg(handle, M_CTRL_REG2, 0x00 | 0x0C) != 0) return -1;

    /* Enter active mode */
    if (i2c_write_reg(handle, CTRL_REG1, 0x01 | 0x02) != 0) return -1;

    return 0;
}

static int read_sensor_data(int handle, int16_t *ax, int16_t *ay, int16_t *az,
                            int16_t *mx, int16_t *my, int16_t *mz) {
    uint8_t buf[DATA_LENGTH];
    int rc = i2cReadI2CBlockData(handle, OUT_X_MSB, (char *)buf, DATA_LENGTH);
    if (rc != DATA_LENGTH) {
        fprintf(stderr, "I2C block read failed: expected %d bytes, got %d\n",
                DATA_LENGTH, rc);
        return -1;
    }

    /* 6 bytes accelerometer: 14-bit left-aligned, 6 bytes magnetometer: 16-bit */
    *ax = (int16_t)((buf[0] << 8) | buf[1]) >> 2;
    *ay = (int16_t)((buf[2] << 8) | buf[3]) >> 2;
    *az = (int16_t)((buf[4] << 8) | buf[5]) >> 2;
    /* buf[6..11] are magnetometer; buf[12] is temperature, skipped */
    *mx = (int16_t)((buf[6] << 8) | buf[7]);
    *my = (int16_t)((buf[8] << 8) | buf[9]);
    *mz = (int16_t)((buf[10] << 8) | buf[11]);

    return 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(1, FXOS8700_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed: %d\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_fxos8700(i2c_handle) != 0) {
        fprintf(stderr, "FXOS8700 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("FXOS8700 initialized. Reading every 100 ms (Ctrl+C to stop)...\n");

    while (running) {
        int16_t ax, ay, az, mx, my, mz;
        if (read_sensor_data(i2c_handle, &ax, &ay, &az, &mx, &my, &mz) == 0) {
            printf("Accel: X=%6d Y=%6d Z=%6d  Mag: X=%6d Y=%6d Z=%6d\n",
                   ax, ay, az, mx, my, mz);
        } else {
            fprintf(stderr, "Read error — continuing\n");
        }
        gpioDelay(100000); /* 100 ms */
    }

    printf("\nShutting down...\n");
    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

