#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define ADXL345_ADDRESS 0x53
#define ADXL345_POWER_CTL 0x2D
#define ADXL345_DATAX0 0x32
#define ADXL345_BW_RATE 0x2C
#define ADXL345_FILTER_CTL 0x2C
#define TILT_THRESHOLD 30.0
#define LOG_FILE "/var/log/tilt_events.log"
#define I2C_BUS "/dev/i2c-1"
#define SAMPLE_INTERVAL_MS 100

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing to register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

int i2c_read_regs(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error setting register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != len) {
        fprintf(stderr, "Error reading %d bytes from register 0x%02X: %s\n", len, reg, strerror(errno));
        return -1;
    }
    return 0;
}

int init_adxl345(int fd) {
    if (i2c_write_reg8(fd, ADXL345_POWER_CTL, 0x00) < 0) return -1;
    usleep(1000);
    if (i2c_write_reg8(fd, ADXL345_BW_RATE, 0x0A) < 0) return -1;
    if (i2c_write_reg8(fd, ADXL345_FILTER_CTL, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, ADXL345_POWER_CTL, 0x08) < 0) return -1;
    return 0;
}

int read_accel_data(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buf[6];
    if (i2c_read_regs(fd, ADXL345_DATAX0, buf, 6) < 0) return -1;
    *x = (int16_t)((buf[1] << 8) | buf[0]);
    *y = (int16_t)((buf[3] << 8) | buf[2]);
    *z = (int16_t)((buf[5] << 8) | buf[4]);
    return 0;
}

void calculate_tilt(int16_t x, int16_t y, int16_t z, float *roll, float *pitch) {
    *roll = atan2(y, sqrt(x * x + z * z)) * 180.0 / M_PI;
    *pitch = atan2(-x, sqrt(y * y + z * z)) * 180.0 / M_PI;
}

int log_tilt_event(float roll, float pitch) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s - Tilt: Roll=%.2f, Pitch=%.2f\n", timestamp, roll, pitch);
    fclose(fp);
    return 0;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADXL345_ADDRESS) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", ADXL345_ADDRESS, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    uint8_t part_id;
    if (i2c_read_regs(i2c_fd, 0x00, &part_id, 1) < 0) {
        fprintf(stderr, "Sensor not detected at address 0x%02X\n", ADXL345_ADDRESS);
        close(i2c_fd);
        return 1;
    }
    if (part_id != 0xE5) {
        fprintf(stderr, "Unexpected part ID: 0x%02X (expected 0xE5)\n", part_id);
        close(i2c_fd);
        return 1;
    }

    if (init_adxl345(i2c_fd) < 0) {
        fprintf(stderr, "ADXL345 initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    printf("ADXL345 initialized. Logging tilt events (threshold: %.1f degrees)...\n", TILT_THRESHOLD);

    while (running) {
        int16_t x, y, z;
        if (read_accel_data(i2c_fd, &x, &y, &z) < 0) {
            fprintf(stderr, "Failed to read accelerometer data\n");
            usleep(SAMPLE_INTERVAL_MS * 1000);
            continue;
        }
        float roll, pitch;
        calculate_tilt(x, y, z, &roll, &pitch);
        if (fabs(roll) > TILT_THRESHOLD || fabs(pitch) > TILT_THRESHOLD) {
            if (log_tilt_event(roll, pitch) < 0) {
                fprintf(stderr, "Failed to log tilt event\n");
            }
        }
        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    printf("\nShutting down...\n");
    if (i2c_fd >= 0) {
        i2c_write_reg8(i2c_fd, ADXL345_POWER_CTL, 0x00);
        close(i2c_fd);
    }
    return 0;
}

