#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define SOUND_SENSOR_GPIO 17
#define SAMPLE_INTERVAL_US 1000   /* 1 ms between samples */
#define WINDOW_DURATION_S 5       /* 5-second monitoring window */
#define WINDOW_SAMPLES (WINDOW_DURATION_S * 1000000 / SAMPLE_INTERVAL_US)

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int read_sound_level(void)
{
    int high_count = 0;
    for (int i = 0; i < WINDOW_SAMPLES && g_running; i++) {
        if (gpioRead(SOUND_SENSOR_GPIO) == 1) {
            high_count++;
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }
    return high_count;
}

int main(int argc, char *argv[])
{
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <threshold>\n", argv[0]);
        return EXIT_FAILURE;
    }

    char *endptr = NULL;
    long threshold = strtol(argv[1], &endptr, 10);
    if (endptr == argv[1] || *endptr != '\0' || threshold <= 0) {
        fprintf(stderr, "Error: threshold must be a positive integer.\n");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SOUND_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", SOUND_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install signal handlers.\n");
    }

    printf("Monitoring sound levels on GPIO%d every %d ms for %d seconds...\n",
           SOUND_SENSOR_GPIO, SAMPLE_INTERVAL_US / 1000, WINDOW_DURATION_S);
    fflush(stdout);

    while (g_running) {
        int high_count = read_sound_level();

        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char time_buf[32];
        strftime(time_buf, sizeof(time_buf), "%Y-%m-%d %H:%M:%S", tm_info);

        if (high_count > (int)threshold) {
            printf("[%s] ALERT: Sound level exceeds threshold (%ld high readings in %d s).\n",
                   time_buf, (long)high_count, WINDOW_DURATION_S);
            fflush(stdout);
        } else {
            printf("[%s] Status: Sound level normal (%ld high readings in %d s).\n",
                   time_buf, (long)high_count, WINDOW_DURATION_S);
            fflush(stdout);
        }

        /* Pause 1 second between monitoring windows */
        for (int i = 0; i < 10 && g_running; i++) {
            gpioDelay(100000); /* 100 ms */
        }
    }

    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

