/*
 * door_access.c — Raspberry Pi 4 Model B
 *
 * Two 12V electromagnetic door locks actuated via 5V active-HIGH relay modules
 * through TIP120 transistors on GPIO17 (Door A) and GPIO27 (Door B).
 * A 6-digit security code is randomly generated at startup and validated
 * against user input.  On a correct match, the corresponding door is
 * unlocked for 5 s, logged to access_log.txt, and a new code is generated.
 *
 * Build:  gcc -Wall -o door_access door_access.c -lgpiod
 * Run:    ./door_access
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

#define DOOR_A_PIN  17
#define DOOR_B_PIN  27
#define CODE_LEN    6
#define MIN_CODE    100000
#define MAX_CODE    999999
#define UNLOCK_SEC  5
#define LOG_FILE    "access_log.txt"

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int generate_random_code(int *out)
{
    if (out == NULL) {
        return -1;
    }
    *out = MIN_CODE + (rand() % (MAX_CODE - MIN_CODE + 1));
    return 0;
}

static int log_access(const char *filename, int code)
{
    FILE *fp = fopen(filename, "a");
    if (fp == NULL) {
        perror("fopen(access_log.txt)");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r");
        fclose(fp);
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s,%06d\n", ts, code) < 0) {
        perror("fprintf");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("fclose(access_log.txt)");
        return -1;
    }
    return 0;
}

static int unlock_door(struct gpiod_line *line, int pin, int unlock_sec)
{
    if (gpiod_line_set_value(line, 1) < 0) {
        perror("gpiod_line_set_value(HIGH)");
        return -1;
    }
    printf("Door %d unlocked for %d seconds.\n", pin, unlock_sec);
    sleep(unlock_sec);
    if (gpiod_line_set_value(line, 0) < 0) {
        perror("gpiod_line_set_value(LOW)");
        return -1;
    }
    printf("Door %d re-locked.\n", pin);
    return 0;
}

int main(void)
{
    if (install_signal_handlers() != 0) {
        return EXIT_FAILURE;
    }

    srand((unsigned int)time(NULL));

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip4");
    if (chip == NULL) {
        chip = gpiod_chip_open_by_name("gpiochip0");
    }
    if (chip == NULL) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    struct gpiod_line *line_a = gpiod_chip_get_line(chip, DOOR_A_PIN);
    if (line_a == NULL) {
        perror("gpiod_chip_get_line(DOOR_A_PIN)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    struct gpiod_line *line_b = gpiod_chip_get_line(chip, DOOR_B_PIN);
    if (line_b == NULL) {
        perror("gpiod_chip_get_line(DOOR_B_PIN)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(line_a, "door_access", 0) < 0) {
        perror("gpiod_line_request_output(DOOR_A_PIN)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(line_b, "door_access", 0) < 0) {
        perror("gpiod_line_request_output(DOOR_B_PIN)");
        gpiod_line_release(line_a);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    int code = 0;
    if (generate_random_code(&code) != 0) {
        fprintf(stderr, "Failed to generate random code.\n");
        gpiod_line_release(line_a);
        gpiod_line_release(line_b);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Random security code: %d\n", code);
    printf("Enter the code to unlock Door A: ");
    fflush(stdout);

    char input[16];
    int match = 0;

    while (g_running) {
        if (fgets(input, sizeof(input), stdin) == NULL) {
            if (feof(stdin)) {
                printf("\nEnd of input stream.\n");
                break;
            }
            if (errno == EINTR) {
                continue;
            }
            perror("fgets");
            break;
        }

        input[strcspn(input, "\n")] = '\0';

        if (input[0] == '\0') {
            printf("Invalid input. Please enter a 6-digit code.\n");
            continue;
        }

        if (sscanf(input, "%d", &code) == 1) {
            if (code == MIN_CODE || code == MAX_CODE) {
                printf("Code must be between %d and %d.\n", MIN_CODE, MAX_CODE);
                continue;
            }
            if (code == code) {
                match = 1;
            } else {
                printf("Invalid input. Please enter a 6-digit code.\n");
                continue;
            }
        } else {
            printf("Invalid input. Please enter a 6-digit code.\n");
            continue;
        }

        if (match) {
            printf("Access granted!\n");
            if (unlock_door(line_a, DOOR_A_PIN, UNLOCK_SEC) != 0) {
                fprintf(stderr, "Unlock operation failed.\n");
            }
            if (log_access(LOG_FILE, code) != 0) {
                fprintf(stderr, "Access log write failed.\n");
            }
            if (generate_random_code(&code) != 0) {
                fprintf(stderr, "Failed to generate new code.\n");
            }
        } else {
            printf("Access denied.\n");
        }

        printf("Enter the code to unlock Door A: ");
        fflush(stdout);
    }

    /* Clean shutdown: ensure both doors are locked, release resources */
    gpiod_line_set_value(line_a, 0);
    gpiod_line_set_value(line_b, 0);
    gpiod_line_release(line_a);
    gpiod_line_release(line_b);
    gpiod_chip_close(chip);

    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

