#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <math.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

// LSM303DLHC Magnetometer I2C address
#define LSM303_MAG_ADDR 0x1E

// LSM303DLHC Magnetometer Registers
#define CTRL_REG1_M 0x20
#define OUT_X_L_M 0x08

// GPIO pin for LED
#define LED_PIN 17

// PWM frequency (Hz) - typical for 1 kHz PWM
#define PWM_FREQ 1000

// I2C device path
#define I2C_DEV "/dev/i2c-1"

// Global variables for cleanup
static int i2c_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *led_line = NULL;
static volatile sig_atomic_t running = 1;

// Function prototypes
int init_i2c(void);
int init_gpio(void);
int init_pwm(void);
int read_magnetometer_data(int16_t *x, int16_t *y, int16_t *z);
float calculate_magnetometer_z(float x, float y, float z);
void set_led_brightness(float brightness);
void cleanup(void);
void signal_handler(int sig);

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

// Initialize I2C communication
int init_i2c(void) {
    i2c_fd = open(I2C_DEV, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C device %s: %s\n", I2C_DEV, strerror(errno));
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, LSM303_MAG_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", LSM303_MAG_ADDR, strerror(errno));
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    // Verify sensor presence by reading CTRL_REG1_M
    uint8_t reg_val;
    if (read(i2c_fd, &reg_val, 1) != 1) {
        fprintf(stderr, "Failed to read from I2C device: %s\n", strerror(errno));
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    return 0;
}

// Initialize GPIO for LED control
int init_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return -1;
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", LED_PIN, strerror(errno));
        gpiod_chip_close(chip);
        chip = NULL;
        return -1;
    }

    if (gpiod_line_request_output(led_line, "magnetometer_led", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as output: %s\n", LED_PIN, strerror(errno));
        gpiod_chip_close(chip);
        chip = NULL;
        led_line = NULL;
        return -1;
    }

    return 0;
}

// Initialize PWM using hardware PWM via sysfs (Linux kernel PWM subsystem)
int init_pwm(void) {
    // Enable PWM on GPIO 17
    char pwm_path[64];
    snprintf(pwm_path, sizeof(pwm_path), "/sys/class/pwm/pwmchip0/pwm0");
    FILE *pwm_export = fopen(pwm_path, "w");
    if (!pwm_export) {
        fprintf(stderr, "Failed to export PWM: %s\n", strerror(errno));
        return -1;
    }
    fprintf(pwm_export, "0");
    fclose(pwm_export);

    // Set period (1/PWM_FREQ in nanoseconds)
    char period_path[64];
    snprintf(period_path, sizeof(period_path), "/sys/class/pwm/pwmchip0/pwm0/period");
    FILE *pwm_period = fopen(period_path, "w");
    if (!pwm_period) {
        fprintf(stderr, "Failed to set PWM period: %s\n", strerror(errno));
        close(i2c_fd);
        return -1;
    }
    fprintf(pwm_period, "%d", 1000000000 / PWM_FREQ);
    fclose(pwm_period);

    // Set duty cycle to 0
    char duty_path[64];
    snprintf(duty_path, sizeof(duty_path), "/sys/class/pwm/pwmchip0/pwm0/duty_cycle");
    FILE *pwm_duty = fopen(duty_path, "w");
    if (!pwm_duty) {
        fprintf(stderr, "Failed to set PWM duty cycle: %s\n", strerror(errno));
        close(i2c_fd);
        return -1;
    }
    fprintf(pwm_duty, "0");
    fclose(pwm_duty);

    return 0;
}

// Read magnetometer data (6 bytes starting from OUT_X_L_M)
int read_magnetometer_data(int16_t *x, int16_t *y, int16_t *z) {
    uint8_t reg = OUT_X_L_M;
    uint8_t buf[6];

    // Write register address
    if (write(i2c_fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write error: %s\n", strerror(errno));
        return -1;
    }

    // Read 6 bytes
    if (read(i2c_fd, buf, 6) != 6) {
        fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        return -1;
    }

    *x = (int16_t)((buf[1] << 8) | buf[0]);
    *y = (int16_t)((buf[3] << 8) | buf[2]);
    *z = (int16_t)((buf[5] << 8) | buf[4]);

    return 0;
}

// Calculate the magnitude of the Z-axis magnetic field
float calculate_magnetometer_z(float x, float y, float z) {
    return sqrtf(z * z);
}

// Set LED brightness using PWM duty cycle (0.0 to 1.0)
void set_led_brightness(float brightness) {
    if (brightness < 0.0f) brightness = 0.0f;
    if (brightness > 1.0f) brightness = 1.0f;

    // Convert brightness to duty cycle (0-1000000 for 1ms period)
    int duty_cycle = (int)(brightness * 1000000.0f);
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > 1000000) duty_cycle = 1000000;

    char duty_path[64];
    snprintf(duty_path, sizeof(duty_path), "/sys/class/pwm/pwmchip0/pwm0/duty_cycle");
    FILE *pwm_duty = fopen(duty_path, "w");
    if (!pwm_duty) {
        fprintf(stderr, "Failed to set PWM duty cycle: %s\n", strerror(errno));
        return;
    }
    fprintf(pwm_duty, "%d", duty_cycle);
    fclose(pwm_duty);
}

// Cleanup resources
void cleanup(void) {
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
        led_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

int main(void) {
    // Register signal handlers
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    // Initialize GPIO
    if (init_gpio() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    // Initialize PWM
    if (init_pwm() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Magnetometer LED control started. Press Ctrl+C to exit.\n");

    int16_t x, y, z;
    float x_val, y_val, z_val;
    float z_magnitude;

    while (running) {
        // Read magnetometer data
        if (read_magnetometer_data(&x, &y, &z) != 0) {
            fprintf(stderr, "Error reading magnetometer data. Skipping sample.\n");
            usleep(100000); // 100 ms
            continue;
        }

        // Convert raw data to float (assuming 16-bit signed, LSB = 0.0000612 Gauss)
        x_val = (float)x * 0.0000612f;
        y_val = (float)y * 0.0000612f;
        z_val = (float)z * 0.0000612f;

        // Calculate Z-axis magnitude
        z_magnitude = calculate_magnetometer_z(x_val, y_val, z_val);

        // Set LED brightness based on Z-axis magnitude
        set_led_brightness(z_magnitude);

        // Print debug output
        printf("X: %.4f Gauss, Y: %.4f Gauss, Z: %.4f Gauss, Z Magnitude: %.4f\n", x_val, y_val, z_val, z_magnitude);

        usleep(100000); // 100 ms delay
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

