/*
 * LSM303D tri-axial accelerometer monitor for Raspberry Pi Zero W.
 *
 * I2C  : /dev/i2c-1, LSM303D at 0x1D (SA0 tied high).
 * GPIO : BCM 23 (physical pin 16) — INT1 interrupt line.
 *
 * Build: gcc -O2 -Wall -Wextra -o lsm303d_mon lsm303d_mon.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define LSM303D_ADDR   0x1D

#define WHO_AM_I       0x0F
#define WHO_AM_I_VAL   0x49

#define CTRL_REG1      0x20
#define CTRL_REG4      0x23
#define OUT_X_L_A      0x28

#define INT1_OFFSET    23   /* BCM 23 */

#define BUFFER_SIZE    64
#define SAMPLE_PERIOD_US 10000   /* 10 ms */
#define INT1_WINDOW     10

/* +-2g full-scale: 1 mg/LSB => 0.061 mg/LSB */
#define ACCEL_SENSITIVITY 0.061f

typedef struct {
    int16_t x, y, z;
} accel_sample_t;

static accel_sample_t ring_buffer[BUFFER_SIZE];
static int   ring_head = 0;
static int   ring_count = 0;

static volatile sig_atomic_t running = 1;
static int  i2c_fd = -1;
static struct gpiod_chip  *chip = NULL;
static struct gpiod_line  *int_line = NULL;

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (i2c_smbus_read_byte_data(fd, reg) < 0) {
        fprintf(stderr, "I2C read reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *val = (uint8_t)(i2c_smbus_read_byte_data(fd, reg));
    return 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    if (i2c_smbus_write_byte_data(fd, reg, val) < 0) {
        fprintf(stderr, "I2C write reg 0x%02X = 0x%02X failed: %s\n",
                reg, val, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    if (i2c_smbus_read_i2c_block_data(fd, reg, len, buf) < 0) {
        fprintf(stderr, "I2C block read reg 0x%02X (%zu bytes) failed: %s\n",
                reg, len, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* LSM303D                                                             */
/* ------------------------------------------------------------------ */

static int lsm303d_init(void)
{
    uint8_t who;

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "open %s failed: %s\n", I2C_BUS, strerror(errno));
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, LSM303D_ADDR) < 0) {
        fprintf(stderr, "ioctl I2C_SLAVE 0x%02X failed: %s\n",
                LSM303D_ADDR, strerror(errno));
        return -1;
    }

    if (i2c_read_reg8(i2c_fd, WHO_AM_I, &who) < 0)
        return -1;

    if (who != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who, WHO_AM_I_VAL);
        return -1;
    }

    /* CTRL_REG1: 50 Hz ODR, XYZ axes enabled */
    if (i2c_write_reg8(i2c_fd, CTRL_REG1, 0x57) < 0)
        return -1;

    /* CTRL_REG4: full-scale +/-2g, no self-test */
    if (i2c_write_reg8(i2c_fd, CTRL_REG4, 0x00) < 0)
        return -1;

    return 0;
}

static int lsm303d_read_accel(accel_sample_t *out)
{
    uint8_t buf[6];

    if (i2c_read_block(i2c_fd, OUT_X_L_A | 0x80, buf, sizeof(buf)) < 0)
        return -1;

    out->x = (int16_t)((buf[1] << 8) | buf[0]);
    out->y = (int16_t)((buf[3] << 8) | buf[2]);
    out->z = (int16_t)((buf[5] << 8) | buf[4]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* GPIO interrupt (libgpiod)                                            */
/* ------------------------------------------------------------------ */

static int gpio_init(void)
{
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "gpiod_chip_open failed: %s\n", strerror(errno));
        return -1;
    }

    int_line = gpiod_chip_get_line(chip, INT1_OFFSET);
    if (!int_line) {
        fprintf(stderr, "gpiod get line %d failed: %s\n",
                INT1_OFFSET, strerror(errno));
        return -1;
    }

    if (gpiod_line_request_rising_edge_events(int_line, "lsm303d-int1") < 0) {
        fprintf(stderr, "gpiod request rising-edge events failed: %s\n",
                strerror(errno));
        return -1;
    }
    return 0;
}

static void gpio_notify(int event)
{
    (void)event;
    printf("\n--- INT1 triggered ---\n");
    fflush(stdout);

    int idx = (ring_head - INT1_WINDOW + BUFFER_SIZE) % BUFFER_SIZE;
    int count = (ring_count < INT1_WINDOW) ? ring_count : INT1_WINDOW;

    printf("  %4d  %4d  %4d\n",
           ring_buffer[(idx - 1 + BUFFER_SIZE) % BUFFER_SIZE].x,
           ring_buffer[(idx - 1 + BUFFER_SIZE) % BUFFER_SIZE].y,
           ring_buffer[(idx - 1 + BUFFER_SIZE) % BUFFER_SIZE].z);
    printf("  %4d  %4d  %4d\n",
           ring_buffer[(idx + 1) % BUFFER_SIZE].x,
           ring_buffer[(idx + 1) % BUFFER_SIZE].y,
           ring_buffer[(idx + 1) % BUFFER_SIZE].z);
    printf("  %4d  %4d  %4d\n",
           ring_buffer[(idx + 2) % BUFFER_SIZE].x,
           ring_buffer[(idx + 2) % BUFFER_SIZE].y,
           ring_buffer[(idx + 2) % BUFFER_SIZE].z);
    printf("  %4d  %4d  %4d\n",
           ring_buffer[(idx + 3) % BUFFER_SIZE].x,
           ring_buffer[(idx + 3) % BUFFER_SIZE].y,
           ring_buffer[(idx + 3) % BUFFER_SIZE].z);
    printf("  %4d  %4d  %4d\n",
           ring_buffer[(idx + 4) % BUFFER_SIZE].x,
           ring_buffer[(idx + 4) % BUFFER_SIZE].y,
           ring_buffer[(idx + 4) % BUFFER_SIZE].z);
    printf("  %4d  %4d  %4d\n\n",
           ring_buffer[(idx + 5) % BUFFER_SIZE].x,
           ring_buffer[(idx + 5) % BUFFER_SIZE].y,
           ring_buffer[(idx + 5) % BUFFER_SIZE].z);
    fflush(stdout);
}

static void sigint_handler(int sig)
{
    (void)sig;
    running = 0;
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    if (lsm303d_init() < 0) {
        fprintf(stderr, "LSM303D initialization failed.\n");
        goto cleanup;
    }

    if (gpio_init() < 0) {
        fprintf(stderr, "GPIO initialization failed.\n");
        goto cleanup;
    }

    printf("LSM303D monitoring started.  Ctrl-C to exit.\n");
    fflush(stdout);

    while (running) {
        accel_sample_t sample;

        if (lsm303d_read_accel(&sample) < 0) {
            fprintf(stderr, "Warning: I2C read failed, skipping sample.\n");
            usleep(SAMPLE_PERIOD_US);
            continue;
        }

        ring_buffer[ring_head] = sample;
        ring_head = (ring_head + 1) % BUFFER_SIZE;
        if (ring_count < BUFFER_SIZE)
            ring_count++;

        usleep(SAMPLE_PERIOD_US);
    }

    /* Graceful shutdown */
    if (i2c_fd >= 0) {
        (void)i2c_write_reg8(i2c_fd, CTRL_REG1, 0x00);   /* disable accel */
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (int_line) {
        gpiod_line_release(int_line);
        int_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }

    printf("\nExiting cleanly.\n");
    return 0;

cleanup:
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (int_line) {
        gpiod_line_release(int_line);
        int_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    return 1;
}

