/*
 * reciprocating_actuator.c
 *
 * Raspberry Pi 3 Model B+ — two 12V DC push-pull solenoids driven via
 * TIP120 transistors on GPIO17 (BCM) and GPIO27 (BCM), using libgpiod.
 *
 * Build:  gcc -O2 -Wall -Wextra -o reciprocating_actuator reciprocating_actuator.c -lgpiod
 * Run:    sudo ./reciprocating_actuator
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <gpiod.h>

#define SOLENOID_1_PIN  17   /* BCM */
#define SOLENOID_2_PIN  27   /* BCM */
#define DELAY_MS        500

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int sleep_ms(unsigned int ms)
{
    struct timespec req = {
        .tv_sec  = ms / 1000U,
        .tv_nsec = (long)(ms % 1000U) * 1000000L
    };
    struct timespec rem;

    while (nanosleep(&req, &rem) == -1) {
        if (errno != EINTR) {
            perror("nanosleep");
            return -1;
        }
        req = rem;
    }
    return 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL;
    struct gpiod_line *line2 = NULL;
    int rc = EXIT_FAILURE;

    if (install_signal_handlers() == -1)
        return EXIT_FAILURE;

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        perror("gpiod_chip_open_by_name(\"gpiochip0\")");
        return EXIT_FAILURE;
    }

    line1 = gpiod_chip_get_line(chip, SOLENOID_1_PIN);
    if (line1 == NULL) {
        perror("gpiod_chip_get_line(SOLENOID_1_PIN)");
        goto cleanup;
    }

    line2 = gpiod_chip_get_line(chip, SOLENOID_2_PIN);
    if (line2 == NULL) {
        perror("gpiod_chip_get_line(SOLENOID_2_PIN)");
        goto cleanup;
    }

    if (gpiod_line_request_output(line1, "reciprocating_actuator", 0) < 0) {
        perror("gpiod_line_request_output(line1)");
        goto cleanup;
    }

    if (gpiod_line_request_output(line2, "reciprocating_actuator", 0) < 0) {
        perror("gpiod_line_request_output(line2)");
        goto cleanup;
    }

    /* Ensure both solenoids are de-energized at startup */
    if (gpiod_line_set_value(line1, 0) < 0) {
        perror("gpiod_line_set_value(line1, 0)");
        goto cleanup;
    }
    if (gpiod_line_set_value(line2, 0) < 0) {
        perror("gpiod_line_set_value(line2, 0)");
        goto cleanup;
    }

    printf("Reciprocating actuator started. Press Ctrl+C to stop.\n");

    while (g_running) {
        if (gpiod_line_set_value(line1, 1) < 0) {
            perror("gpiod_line_set_value(line1, 1)");
            goto cleanup;
        }
        if (gpiod_line_set_value(line2, 0) < 0) {
            perror("gpiod_line_set_value(line2, 0)");
            goto cleanup;
        }
        if (sleep_ms(DELAY_MS) < 0)
            goto cleanup;

        if (!g_running)
            break;

        if (gpiod_line_set_value(line1, 0) < 0) {
            perror("gpiod_line_set_value(line1, 0)");
            goto cleanup;
        }
        if (gpiod_line_set_value(line2, 1) < 0) {
            perror("gpiod_line_set_value(line2, 1)");
            goto cleanup;
        }
        if (sleep_ms(DELAY_MS) < 0)
            goto cleanup;
    }

    rc = EXIT_SUCCESS;

cleanup:
    /* Ensure both lines are de-energized before releasing */
    if (line1 != NULL)
        gpiod_line_set_value(line1, 0);
    if (line2 != NULL)
        gpiod_line_set_value(line2, 0);

    if (line1 != NULL)
        gpiod_line_release(line1);
    if (line2 != NULL)
        gpiod_line_release(line2);
    if (chip != NULL)
        gpiod_chip_close(chip);

    if (rc == EXIT_SUCCESS)
        printf("\nClean shutdown complete.\n");
    return rc;
}

