#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <errno.h>
#include <pigpio.h>

#define LOCK1_GPIO 17
#define LOCK2_GPIO 27
#define EXPECTED_CODE "123456"
#define CODE_LENGTH 6
#define SERIAL_PORT_0 "/dev/serial0"
#define SERIAL_PORT_1 "/dev/serial1"
#define BAUD_RATE B9600
#define READ_TIMEOUT_SEC 5
#define UNLOCK_DURATION_MS 2000
#define POLL_DELAY_US 100000

static volatile sig_atomic_t g_running = 1;
static int g_serial0_fd = -1;
static int g_serial1_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }
    if (gpioSetMode(LOCK1_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", LOCK1_GPIO);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(LOCK2_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", LOCK2_GPIO);
        gpioTerminate();
        return -1;
    }
    if (gpioWrite(LOCK1_GPIO, 0) != 0) {
        fprintf(stderr, "Error: failed to write LOW to GPIO%d.\n", LOCK1_GPIO);
        gpioTerminate();
        return -1;
    }
    if (gpioWrite(LOCK2_GPIO, 0) != 0) {
        fprintf(stderr, "Error: failed to write LOW to GPIO%d.\n", LOCK2_GPIO);
        gpioTerminate();
        return -1;
    }
    return 0;
}

static int init_serial(const char *port) {
    int fd = open(port, O_RDWR | O_NOCTTY | O_NDELAY);
    if (fd < 0) {
        fprintf(stderr, "Error: cannot open %s: %s\n", port, strerror(errno));
        return -1;
    }
    if (fcntl(fd, F_SETFL, 0) < 0) {
        fprintf(stderr, "Error: cannot clear O_NDELAY on %s: %s\n", port, strerror(errno));
        close(fd);
        return -1;
    }
    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        fprintf(stderr, "Error: tcgetattr failed on %s: %s\n", port, strerror(errno));
        close(fd);
        return -1;
    }
    cfsetispeed(&tty, BAUD_RATE);
    cfsetospeed(&tty, BAUD_RATE);
    tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8;
    tty.c_cflag &= ~(PARENB | PARODD);
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CRTSCTS;
    tty.c_cflag |= CREAD | CLOCAL;
    tty.c_lflag = 0;
    tty.c_oflag = 0;
    tty.c_iflag = 0;
    tty.c_cc[VMIN] = 0;
    tty.c_cc[VTIME] = 5;
    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "Error: tcsetattr failed on %s: %s\n", port, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

static int read_code(int fd, char *code, size_t code_len) {
    size_t idx = 0;
    char ch;
    while (idx < code_len) {
        ssize_t n = read(fd, &ch, 1);
        if (n < 0) {
            if (errno == EAGAIN || errno == EWOULDBLOCK) {
                continue;
            }
            fprintf(stderr, "Error: read failed on %s: %s\n", (code_len > 1) ? SERIAL_PORT_0 : SERIAL_PORT_1, strerror(errno));
            return -1;
        }
        if (n == 0) {
            fprintf(stderr, "Error: serial port closed on %s\n", (code_len > 1) ? SERIAL_PORT_0 : SERIAL_PORT_1);
            return -1;
        }
        if (ch >= '0' && ch <= '9') {
            code[idx++] = ch;
        } else if (idx > 0) {
            idx = 0;
        }
    }
    code[idx] = '\0';
    return 0;
}

static int compare_codes(const char *a, const char *b) {
    if (strlen(a) != strlen(b)) {
        return 0;
    }
    for (int i = 0; i < CODE_LENGTH; i++) {
        if (a[i] != b[i]) {
            return 0;
        }
    }
    return 1;
}

static int unlock_doors(void) {
    if (gpioWrite(LOCK1_GPIO, 1) != 0) {
        fprintf(stderr, "Error: failed to unlock lock 1 (GPIO%d).\n", LOCK1_GPIO);
        return -1;
    }
    if (gpioWrite(LOCK2_GPIO, 1) != 0) {
        fprintf(stderr, "Error: failed to unlock lock 2 (GPIO%d).\n", LOCK2_GPIO);
        gpioWrite(LOCK1_GPIO, 0);
        return -1;
    }
    gpioDelay(UNLOCK_DURATION_MS * 1000);
    if (gpioWrite(LOCK1_GPIO, 0) != 0) {
        fprintf(stderr, "Error: failed to re-lock lock 1 (GPIO%d).\n", LOCK1_GPIO);
        return -1;
    }
    if (gpioWrite(LOCK2_GPIO, 0) != 0) {
        fprintf(stderr, "Error: failed to re-lock lock 2 (GPIO%d).\n", LOCK2_GPIO);
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (g_serial0_fd >= 0) {
        close(g_serial0_fd);
        g_serial0_fd = -1;
    }
    if (g_serial1_fd >= 0) {
        close(g_serial1_fd);
        g_serial1_fd = -1;
    }
    gpioWrite(LOCK1_GPIO, 0);
    gpioWrite(LOCK2_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: sigaction(SIGINT) failed: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return 1;
    }

    if (init_gpio() != 0) {
        return 1;
    }

    g_serial0_fd = init_serial(SERIAL_PORT_0);
    if (g_serial0_fd < 0) {
        cleanup();
        return 1;
    }
    g_serial1_fd = init_serial(SERIAL_PORT_1);
    if (g_serial1_fd < 0) {
        cleanup();
        return 1;
    }

    printf("Dual-factor authentication system started.\n");
    printf("Primary UART: %s | Secondary UART: %s | Expected code: %s\n",
           SERIAL_PORT_0, SERIAL_PORT_1, EXPECTED_CODE);
    printf("Locks will unlock for 2 seconds when both ports receive the correct code.\n");
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        char code0[CODE_LENGTH + 1] = {0};
        char code1[CODE_LENGTH + 1] = {0};

        if (read_code(g_serial0_fd, code0, CODE_LENGTH) != 0) {
            fprintf(stderr, "Warning: failed to read from %s.\n", SERIAL_PORT_0);
        }

        if (read_code(g_serial1_fd, code1, CODE_LENGTH) != 0) {
            fprintf(stderr, "Warning: failed to read from %s.\n", SERIAL_PORT_1);
        }

        if (compare_codes(code0, EXPECTED_CODE) && compare_codes(code1, EXPECTED_CODE)) {
            if (compare_codes(code0, code1)) {
                printf("Both ports received the correct code. Unlocking doors...\n");
                if (unlock_doors() == 0) {
                    printf("Doors unlocked successfully.\n");
                } else {
                    fprintf(stderr, "Error: failed to unlock doors.\n");
                }
            } else {
                fprintf(stderr, "Error: codes do not match (got '%s' and '%s').\n", code0, code1);
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    printf("Cleanup complete. Exiting.\n");
    return 0;
}

