#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <errno.h>
#include <gpiod.h>

#define PIR_PIN 4
#define RELAY_PIN 17
#define RELAY_DURATION_MS 1000
#define POLL_INTERVAL_MS 50
#define FAILSAFE_TIMEOUT_SEC 10

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void log_event(const char *msg) {
    syslog(LOG_INFO, "%s", msg);
}

static void log_warning(const char *msg) {
    syslog(LOG_WARNING, "%s", msg);
}

static void log_error(const char *msg) {
    syslog(LOG_ERR, "%s", msg);
}

int main(void) {
    openlog("door_strike", LOG_PID | LOG_CONS, LOG_USER);
    log_event("Door strike system starting");

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        log_error("Failed to register signal handlers");
        closelog();
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        log_error("Failed to open gpiochip0");
        closelog();
        return EXIT_FAILURE;
    }

    struct gpiod_line *pir_line = gpiod_chip_get_line(chip, PIR_PIN);
    if (!pir_line) {
        log_error("Failed to get PIR line (GPIO4)");
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }

    struct gpiod_line *relay_line = gpiod_chip_get_line(chip, RELAY_PIN);
    if (!relay_line) {
        log_error("Failed to get relay line (GPIO17)");
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(pir_line, "door_strike_pir") < 0) {
        log_error("Failed to request PIR line as input");
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(relay_line, "door_strike_relay", 0) < 0) {
        log_error("Failed to request relay line as output");
        gpiod_line_release(pir_line);
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }

    log_event("GPIO lines configured");

    time_t motion_start = 0;
    int relay_state = 0;

    while (program_running) {
        int pir_value = gpiod_line_get_value(pir_line);
        if (pir_value < 0) {
            log_error("Failed to read PIR sensor");
            break;
        }

        if (pir_value == 1) {
            if (relay_state == 0) {
                if (gpiod_line_set_value(relay_line, 1) < 0) {
                    log_error("Failed to energize relay");
                    break;
                }
                relay_state = 1;
                log_event("Motion detected - relay energized");
            }

            if (motion_start == 0) {
                motion_start = time(NULL);
            }

            if (difftime(time(NULL), motion_start) >= FAILSAFE_TIMEOUT_SEC) {
                if (relay_state == 1) {
                    if (gpiod_line_set_value(relay_line, 0) < 0) {
                        log_error("Failed to de-energize relay during failsafe");
                        break;
                    }
                    relay_state = 0;
                    log_event("Failsafe triggered - relay de-energized");
                }
                motion_start = 0;
            }
        } else {
            if (relay_state == 1) {
                if (gpiod_line_set_value(relay_line, 0) < 0) {
                    log_error("Failed to de-energize relay on motion end");
                    break;
                }
                relay_state = 0;
                log_event("Motion ended - relay de-energized");
            }
            motion_start = 0;
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    if (relay_state == 1) {
        gpiod_line_set_value(relay_line, 0);
    }

    gpiod_line_release(pir_line);
    gpiod_line_release(relay_line);
    gpiod_chip_close(chip);
    log_event("Door strike system shutting down");
    closelog();
    return EXIT_SUCCESS;
}

