#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>

#define RELAY1_PIN 4
#define RELAY2_PIN 17
#define RELAY3_PIN 27
#define RELAY4_PIN 22

#define RELAY_ON_TIME 300   /* seconds (5 minutes) */
#define RELAY_PAUSE_TIME 60 /* seconds (1 minute) */
#define TIMER_INTERVAL 60   /* seconds between timer ticks */
#define TIMER_ID 0

static volatile sig_atomic_t program_running = 1;
static volatile sig_atomic_t timer_state = 0; /* 0=idle, 1=active, 2=pause */

static const int relay_pins[4] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};

static void log_event(int pin, int state) {
    time_t now = time(NULL);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", localtime(&now));
    syslog(LOG_INFO, "Relay on GPIO%d set to %s", pin, state ? "ON" : "OFF");
}

static void deactivate_all_relays(void) {
    for (int i = 0; i < 4; i++) {
        if (gpioWrite(relay_pins[i], 1) != 0) {
            syslog(LOG_ERR, "Failed to set GPIO%d HIGH (deactivate)", relay_pins[i]);
        }
    }
}

static void timer_callback(int timer_id, void *userdata) {
    (void)timer_id;
    (void)userdata;

    if (timer_state == 0) {
        /* Activate relay 1 */
        if (gpioWrite(relay_pins[0], 0) != 0) {
            syslog(LOG_ERR, "Failed to activate relay 1 (GPIO%d)", relay_pins[0]);
            return;
        }
        log_event(relay_pins[0], 1);
        timer_state = 1;
    } else if (timer_state == 1) {
        /* Deactivate relay 1 */
        if (gpioWrite(relay_pins[0], 1) != 0) {
            syslog(LOG_ERR, "Failed to deactivate relay 1 (GPIO%d)", relay_pins[0]);
            return;
        }
        log_event(relay_pins[0], 0);
        timer_state = 2;
    } else {
        /* Pause: ensure all relays are OFF */
        deactivate_all_relays();
        timer_state = 0;
    }
}

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

int main(void) {
    openlog("irrigation_system", LOG_PID | LOG_CONS, LOG_USER);

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    for (int i = 0; i < 4; i++) {
        if (gpioSetMode(relay_pins[i], PI_OUTPUT) != 0) {
            syslog(LOG_ERR, "Failed to set GPIO%d as output", relay_pins[i]);
            deactivate_all_relays();
            gpioTerminate();
            closelog();
            return EXIT_FAILURE;
        }
        if (gpioWrite(relay_pins[i], 1) != 0) {
            syslog(LOG_ERR, "Failed to initialise GPIO%d HIGH (OFF)", relay_pins[i]);
            deactivate_all_relays();
            gpioTerminate();
            closelog();
            return EXIT_FAILURE;
        }
    }

    if (gpioSetTimerFuncEx(TIMER_ID, TIMER_INTERVAL, timer_callback, NULL) != 0) {
        syslog(LOG_ERR, "Failed to set timer function");
        deactivate_all_relays();
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "Failed to set signal handlers");
        deactivate_all_relays();
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "Irrigation system started");

    while (program_running) {
        sleep(1);
    }

    syslog(LOG_INFO, "Shutting down irrigation system");
    deactivate_all_relays();
    gpioSetTimerFuncEx(TIMER_ID, TIMER_INTERVAL, NULL, NULL);
    gpioTerminate();
    closelog();
    return EXIT_SUCCESS;
}

