#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define NUM_RELAYS 4
#define CHIP_NAME "gpiochip0"
#define RELAY_PINS {18, 23, 24, 25}

static const int relay_pins[NUM_RELAYS] = RELAY_PINS;
static const int relay_intervals[NUM_RELAYS] = {2, 3, 5, 7};

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static long long elapsed_seconds(const struct timespec *start, const struct timespec *end) {
    return (long long)(end->tv_sec - start->tv_sec) +
           (long long)(end->tv_nsec - start->tv_nsec) / 1000000000LL;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_RELAYS];
    bool relay_states[NUM_RELAYS];
    int i;
    struct timespec start_time, current_time;
    int ret;

    for (i = 0; i < NUM_RELAYS; i++) {
        relay_states[i] = false;
        lines[i] = NULL;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    for (i = 0; i < NUM_RELAYS; i++) {
        lines[i] = gpiod_chip_get_line(chip, relay_pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %d: %s\n", relay_pins[i], strerror(errno));
            goto cleanup;
        }

        ret = gpiod_line_request_output(lines[i], "smart-lighting", 0);
        if (ret < 0) {
            fprintf(stderr, "Failed to request GPIO line %d as output: %s\n", relay_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    clock_gettime(CLOCK_MONOTONIC, &start_time);

    while (running) {
        for (i = 0; i < NUM_RELAYS; i++) {
            clock_gettime(CLOCK_MONOTONIC, &current_time);
            long long elapsed = elapsed_seconds(&start_time, &current_time);

            if (elapsed >= relay_intervals[i]) {
                relay_states[i] = !relay_states[i];
                ret = gpiod_line_set_value(lines[i], relay_states[i] ? 1 : 0);
                if (ret < 0) {
                    fprintf(stderr, "Failed to set GPIO line %d: %s\n", relay_pins[i], strerror(errno));
                    goto cleanup;
                }
                start_time = current_time;
            }
        }
    }

cleanup:
    for (i = 0; i < NUM_RELAYS; i++) {
        if (lines[i]) {
            gpiod_line_set_value(lines[i], 0);
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return EXIT_SUCCESS;
}

