#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SOUND_SENSOR_GPIO 17
#define RELAY_GPIO 27
#define ALARM_DURATION_SEC 3
#define POLL_INTERVAL_US 100000
#define LOG_FILE "alarm_log.txt"

static volatile sig_atomic_t running = 1;
static volatile sig_atomic_t alarm_active = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_alarm_event(void) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        fclose(fp);
        return;
    }

    struct tm tm_info;
    if (!localtime_r(&t, &tm_info)) {
        fprintf(stderr, "localtime_r() failed\n");
        fclose(fp);
        return;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        fclose(fp);
        return;
    }

    if (fprintf(fp, "%s - Alarm triggered\n", timestamp) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
    }
}

static void activate_relay(void) {
    if (gpioWrite(RELAY_GPIO, 1) < 0) {
        fprintf(stderr, "Failed to set relay GPIO %d HIGH\n", RELAY_GPIO);
        return;
    }
    printf("Alarm activated!\n");
    log_alarm_event();

    for (int i = 0; i < ALARM_DURATION_SEC * 10 && running; i++) {
        gpioDelay(POLL_INTERVAL_US);
    }

    if (gpioWrite(RELAY_GPIO, 0) < 0) {
        fprintf(stderr, "Failed to set relay GPIO %d LOW\n", RELAY_GPIO);
    }
    printf("Alarm deactivated.\n");
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SOUND_SENSOR_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SOUND_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", RELAY_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(RELAY_GPIO, 0) < 0) {
        fprintf(stderr, "Failed to initialize relay GPIO %d to LOW\n", RELAY_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Sound-activated alarm system started. Press Ctrl+C to exit.\n");

    while (running) {
        int sound_level = gpioRead(SOUND_SENSOR_GPIO);
        if (sound_level < 0) {
            fprintf(stderr, "Failed to read GPIO %d\n", SOUND_SENSOR_GPIO);
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        if (sound_level == 1 && !alarm_active) {
            activate_relay();
            alarm_active = 1;
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return EXIT_SUCCESS;
}

