#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <string.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

// MPU-6050 Registers
#define MPU6050_ADDR 0x68
#define WHO_AM_I 0x75
#define PWR_MGMT_1 0x6B
#define GYRO_XOUT_H 0x43

// Sensitivity for +/- 250 dps range
#define GYRO_SENSITIVITY 131.0

// Circular buffer size
#define BUFFER_SIZE 100

// Threshold for angular velocity detection
#define THRESHOLD 50.0

// Global variables
static int i2c_fd = -1;
static volatile sig_atomic_t running = 1;

// Circular buffer structure
typedef struct {
    float x[BUFFER_SIZE];
    float y[BUFFER_SIZE];
    float z[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Function prototypes
int init_i2c();
int init_mpu6050();
int read_gyro_data(float *x, float *y, float *z);
void add_to_buffer(CircularBuffer *buffer, float x, float y, float z);
float calculate_magnitude(float x, float y, float z);
void detect_threshold(float x, float y, float z);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

// Cleanup resources
void cleanup() {
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

// Initialize I2C communication
int init_i2c() {
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open /dev/i2c-1: %s\n", strerror(errno));
        return -1;
    }
    return fd;
}

// Initialize MPU-6050
int init_mpu6050() {
    i2c_fd = init_i2c();
    if (i2c_fd < 0) {
        return -1;
    }

    // Verify device identity
    int who_am_i = i2c_smbus_read_byte_data(i2c_fd, WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register: %s\n", strerror(errno));
        return -1;
    }
    if (who_am_i != 0x68) {
        fprintf(stderr, "MPU-6050 not found. WHO_AM_I returned: 0x%02X\n", who_am_i);
        return -1;
    }

    // Wake up the MPU-6050 (clear sleep bit)
    if (i2c_smbus_write_byte_data(i2c_fd, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Failed to wake up MPU-6050: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Read gyroscope data
int read_gyro_data(float *x, float *y, float *z) {
    uint8_t buffer[6];
    int16_t raw_x, raw_y, raw_z;

    // Read 6 bytes starting from GYRO_XOUT_H
    if (i2c_smbus_read_i2c_block_data(i2c_fd, GYRO_XOUT_H, 6, (char *)buffer) != 6) {
        fprintf(stderr, "Failed to read gyroscope data: %s\n", strerror(errno));
        return -1;
    }

    // Combine high and low bytes (big-endian)
    raw_x = (int16_t)((buffer[0] << 8) | buffer[1]);
    raw_y = (int16_t)((buffer[2] << 8) | buffer[3]);
    raw_z = (int16_t)((buffer[4] << 8) | buffer[5]);

    // Convert to degrees per second
    *x = (float)raw_x / GYRO_SENSITIVITY;
    *y = (float)raw_y / GYRO_SENSITIVITY;
    *z = (float)raw_z / GYRO_SENSITIVITY;

    return 0;
}

// Add data to the circular buffer
void add_to_buffer(CircularBuffer *buffer, float x, float y, float z) {
    buffer->x[buffer->head] = x;
    buffer->y[buffer->head] = y;
    buffer->z[buffer->head] = z;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    }
}

// Calculate the magnitude of the angular velocity vector
float calculate_magnitude(float x, float y, float z) {
    return sqrtf(x * x + y * y + z * z);
}

// Detect threshold and trigger callback
void detect_threshold(float x, float y, float z) {
    float magnitude = calculate_magnitude(x, y, z);
    if (magnitude > THRESHOLD) {
        printf("Threshold exceeded! Magnitude: %.2f\n", magnitude);
    }
}

int main() {
    // Set up signal handler for Ctrl+C
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    // Initialize MPU-6050
    if (init_mpu6050() != 0) {
        fprintf(stderr, "MPU-6050 initialization failed. Exiting.\n");
        cleanup();
        return 1;
    }

    // Initialize circular buffer
    CircularBuffer gyro_buffer = {0};
    gyro_buffer.head = 0;
    gyro_buffer.count = 0;

    float x, y, z;

    // Main loop
    while (running) {
        // Read gyroscope data
        if (read_gyro_data(&x, &y, &z) == 0) {
            // Add data to the circular buffer
            add_to_buffer(&gyro_buffer, x, y, z);

            // Detect threshold
            detect_threshold(x, y, z);
        } else {
            fprintf(stderr, "Failed to read gyroscope data. Retrying...\n");
        }

        usleep(10000); // 10ms delay
    }

    // Cleanup
    cleanup();
    printf("Program terminated gracefully.\n");
    return 0;
}

