#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE 9600
#define LOG_FILE "co2_log.json"
#define ERROR_LOG_FILE "co2_error.log"
#define READ_INTERVAL_SEC 5
#define RESPONSE_TIMEOUT_MS 1000
#define RESPONSE_TIMEOUT_US 1000000
#define RESPONSE_TIMEOUT_US_PER_READ 10000
#define RESPONSE_TIMEOUT_READS (RESPONSE_TIMEOUT_US / RESPONSE_TIMEOUT_US_PER_READ)
#define RESPONSE_BYTES 9
#define READ_CMD_LEN 9
#define READ_CMD {0xFF,0x01,0x86,0x00,0x00,0x00,0x00,0x00,0x79}

static int uart_handle = -1;
static FILE *log_file = NULL;
static FILE *error_log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void log_error(const char *message) {
    if (!error_log_file) return;
    struct timeval tv;
    gettimeofday(&tv, NULL);
    struct tm *tm = localtime(&tv.tv_sec);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(error_log_file, "%s.%06ld: %s\n", ts, tv.tv_usec, message);
    fflush(error_log_file);
}

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_uart(void) {
    uart_handle = serOpen(UART_DEVICE, BAUD_RATE, 0);
    if (uart_handle < 0) {
        log_error("serOpen failed");
        return -1;
    }
    return 0;
}

static int read_co2(uint16_t *co2_ppm) {
    char cmd[READ_CMD_LEN];
    memset(cmd, 0, sizeof(cmd));
    memcpy(cmd, READ_CMD, READ_CMD_LEN);

    if (serWrite(uart_handle, cmd, READ_CMD_LEN) != READ_CMD_LEN) {
        log_error("serWrite failed");
        return -1;
    }

    struct timeval start, now;
    gettimeofday(&start, NULL);
    int bytes_read = 0;
    char buffer[256];

    while (bytes_read < RESPONSE_BYTES && !terminate) {
        int avail = serDataAvailable(uart_handle);
        if (avail < 0) {
            log_error("serDataAvailable failed");
            return -1;
        }
        if (avail > 0) {
            int to_read = (avail < (RESPONSE_BYTES - bytes_read)) ? avail : (RESPONSE_BYTES - bytes_read);
            if (serRead(uart_handle, buffer + bytes_read, to_read) != to_read) {
                log_error("serRead failed");
                return -1;
            }
            bytes_read += to_read;
            if (bytes_read == RESPONSE_BYTES) break;
        }
        gettimeofday(&now, NULL);
        long elapsed_us = (now.tv_sec - start.tv_sec) * 1000000L + (now.tv_usec - start.tv_usec);
        if (elapsed_us > RESPONSE_TIMEOUT_US) {
            log_error("Response timeout");
            return -1;
        }
        gpioDelay(RESPONSE_TIMEOUT_US_PER_READ);
    }

    if (bytes_read != RESPONSE_BYTES) {
        log_error("Incomplete response");
        return -1;
    }

    uint8_t checksum = (uint8_t)((uint8_t)response[1] + (uint8_t)response[2] +
                                  (uint8_t)response[3] + (uint8_t)response[4] +
                                  (uint8_t)response[5] + (uint8_t)response[6] +
                                  (uint8_t)response[7]);
    uint8_t expected = ~checksum + 1;
    if (response[8] != expected) {
        log_error("Checksum mismatch");
        return -1;
    }

    *co2_ppm = (uint16_t)(response[2] << 8) | response[3];
    return 0;
}

static void log_data(uint16_t co2_ppm, int error) {
    if (!log_file) return;
    struct timeval tv;
    gettimeofday(&tv, NULL);
    struct tm *tm = localtime(&tv.tv_sec);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(log_file, "{\"timestamp\": \"%s.%06ld\", \"co2_ppm\": %u, \"error\": %d}\n",
            ts, tv.tv_usec, co2_ppm, error);
    fflush(log_file);
}

static void send_data_to_server(uint16_t co2_ppm, int error) {
    printf("{\"timestamp\": \"\", \"co2_ppm\": %u, \"error\": %d}\n", co2_ppm, error);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen log");
        gpioTerminate();
        return 1;
    }

    error_log_file = fopen(ERROR_LOG_FILE, "a");
    if (!error_log_file) {
        perror("fopen error_log");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (init_uart() != 0) {
        fclose(log_file);
        fclose(error_log_file);
        gpioTerminate();
        return 1;
    }

    while (!terminate) {
        uint16_t co2_ppm = 0;
        int rc = read_co2(&co2_ppm);
        if (rc == 0) {
            log_data(co2_ppm, 0);
            send_data_to_server(co2_ppm, 0);
        } else {
            log_data(0, 1);
            send_data_to_server(0, 1);
        }
        for (int i = 0; i < READ_INTERVAL_SEC && !terminate; i++) {
            sleep(1);
        }
    }

    if (uart_handle >= 0) serClose(uart_handle);
    if (log_file) fclose(log_file);
    if (error_log_file) fclose(error_log_file);
    gpioTerminate();
    return 0;
}

