            }
            bytes_read += to_read;
            if (bytes_read == RESPONSE_BYTES) break;
        }
        gettimeofday(&now, NULL);
        long elapsed_us = (now.tv_sec - start.tv_sec) * 1000000L + (now.tv_usec - start.tv_usec);
        if (elapsed_us > RESPONSE_TIMEOUT_US) {
            log_error("Response timeout");
            return -1;
        }
        gpioDelay(RESPONSE_TIMEOUT_US_PER_READ);
    }

    if (bytes_read != RESPONSE_BYTES) {
        log_error("Incomplete response");
        return -1;
    }

    uint8_t checksum = (uint8_t)((uint8_t)response[1] + (uint8_t)response[2] +
                                  (uint8_t)response[3] + (uint8_t)response[4] +
                                  (uint8_t)response[5] + (uint8_t)response[6] +
                                  (uint8_t)response[7]);
    uint8_t expected = ~checksum + 1;
    if (response[8] != expected) {
        log_error("Checksum mismatch");
        return -1;
    }

    *co2_ppm = (uint16_t)(response[2] << 8) | response[3];
    return 0;
}

static void log_data(uint16_t co2_ppm, int error) {
    if (!log_file) return;
    struct timeval tv;
    gettimeofday(&tv, NULL);
    struct tm *tm = localtime(&tv.tv_sec);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(log_file, "{\"timestamp\": \"%s.%06ld\", \"co2_ppm\": %u, \"error\": %d}\n",
            ts, tv.tv_usec, co2_ppm, error);
    fflush(log_file);
}

static void send_data_to_server(uint16_t co2_ppm, int error) {
    printf("{\"timestamp\": \"\", \"co2_ppm\": %u, \"error\": %d}\n", co2_ppm, error);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen log");
        gpioTerminate();
        return 1;
    }

    error_log_file = fopen(ERROR_LOG_FILE, "a");
    if (!error_log_file) {
        perror("fopen error_log");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (init_uart() != 0) {
        fclose(log_file);
        fclose(error_log_file);
        gpioTerminate();
        return 1;
    }

    while (!terminate) {
        uint16_t co2_ppm = 0;
        int rc = read_co2(&co2_ppm);
        if (rc == 0) {
            log_data(co2_ppm, 0);
            send_data_to_server(co2_ppm, 0);
        } else {
            log_data(0, 1);
            send_data_to_server(0, 1);
        }
        for (int i = 0; i < READ_INTERVAL_SEC && !terminate; i++) {
            sleep(1);
        }
    }

    if (uart_handle >= 0) serClose(uart_handle);
    if (log_file) fclose(log_file);
    if (error_log_file) fclose(error_log_file);
    gpioTerminate();
    return 0;
}

