#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <stdbool.h>

/* HMC5883L I2C address (SA0 tied to GND) */
#define HMC5883L_ADDR 0x1E

/* HMC5883L register addresses */
#define HMC5883L_CONFIG_A 0x00
#define HMC5883L_CONFIG_B 0x01
#define HMC5883L_MODE     0x02
#define HMC5883L_DATA_X_MSB 0x03

/* GPIO pin for alert output (BCM numbering) */
#define ALERT_PIN 17

/* Target heading in degrees */
#define TARGET_HEADING 90.0

/* Circular buffer size */
#define BUFFER_SIZE 100

/* Hard-iron offsets (calibrate for your specific sensor) */
#define HARD_IRON_X 100.0
#define HARD_IRON_Y -50.0

/* I2C bus on Raspberry Pi 3 Model B+ */
#define I2C_BUS 1

/* Sensitivity for 1.3 Gauss gain: 1090 LSB/Gauss */
#define SENSITIVITY 1090.0

/* Sampling interval in microseconds */
#define SAMPLE_INTERVAL_US 100000

typedef struct {
    float x;
    float y;
    float heading;
} HeadingData;

typedef struct {
    HeadingData data[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

static int i2c_handle = -1;
static CircularBuffer heading_buffer;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static void init_circular_buffer(CircularBuffer *cb) {
    cb->head = 0;
    cb->count = 0;
}

static void add_to_buffer(CircularBuffer *cb, float x, float y, float heading) {
    cb->data[cb->head].x = x;
    cb->data[cb->head].y = y;
    cb->data[cb->head].heading = heading;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) cb->count++;
}

static float calculate_heading(float x, float y) {
    float heading = atan2f(y, x) * 180.0f / (float)M_PI;
    if (heading < 0.0f) heading += 360.0f;
    return heading;
}

static int configure_hmc5883l(int handle) {
    /* CONFIG_A: 8-average, 15 Hz output rate, normal measurement */
    if (i2cWriteByteData(handle, HMC5883L_CONFIG_A, 0x70) < 0) {
        fprintf(stderr, "Error writing CONFIG_A\n");
        return -1;
    }
    /* CONFIG_B: 1.3 Gauss gain */
    if (i2cWriteByteData(handle, HMC5883L_CONFIG_B, 0x20) < 0) {
        fprintf(stderr, "Error writing CONFIG_B\n");
        return -1;
    }
    /* MODE: continuous measurement */
    if (i2cWriteByteData(handle, HMC5883L_MODE, 0x00) < 0) {
        fprintf(stderr, "Error writing MODE\n");
        return -1;
    }
    return 0;
}

static int read_magnetometer(int handle, float *x, float *y, float *z) {
    char data[6];
    int16_t raw_x, raw_y, raw_z;

    /* Burst read 6 bytes starting at DATA_X_MSB (0x03) */
    if (i2cReadI2CBlockData(handle, HMC5883L_DATA_X_MSB, data, 6) != 6) {
        fprintf(stderr, "Error reading magnetometer data\n");
        return -1;
    }

    /* Data is MSB first: X, Z, Y */
    raw_x = (int16_t)((data[0] << 8) | (data[1] & 0xFF));
    raw_z = (int16_t)((data[2] << 8) | (data[3] & 0xFF));
    raw_y = (int16_t)((data[4] << 8) | (data[5] & 0xFF));

    /* Convert to Gauss and compensate for hard-iron distortion */
    *x = (float)raw_x / SENSITIVITY - HARD_IRON_X;
    *y = (float)raw_y / SENSITIVITY - HARD_IRON_Y;
    *z = (float)raw_z / SENSITIVITY;

    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(ALERT_PIN, 0);
    gpioTerminate();
}

int main(void) {
    float x, y, heading;
    int ret;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at HMC5883L address */
    i2c_handle = i2cOpen(I2C_BUS, HMC5883L_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %d\n",
                I2C_BUS, HMC5883L_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure sensor */
    if (configure_hmc5883l(i2c_handle) < 0) {
        fprintf(stderr, "Failed to configure HMC5883L\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure alert pin as output, initially low */
    gpioSetMode(ALERT_PIN, PI_OUTPUT);
    gpioWrite(ALERT_PIN, 0);

    /* Initialize circular buffer */
    init_circular_buffer(&heading_buffer);

    /* Set up signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("HMC5883L heading monitor started. Target heading: %.1f degrees\n",
           TARGET_HEADING);

    /* Main loop */
    while (!terminate) {
        ret = read_magnetometer(i2c_handle, &x, &y, NULL);
        if (ret == 0) {
            heading = calculate_heading(x, y);
            add_to_buffer(&heading_buffer, x, y, heading);

            if (fabsf(heading - TARGET_HEADING) > 10.0f) {
                gpioWrite(ALERT_PIN, 1);
            } else {
                gpioWrite(ALERT_PIN, 0);
            }
            printf("Heading: %.2f degrees (X=%.2f, Y=%.2f)\n", heading, x, y);
        } else {
            fprintf(stderr, "Read error, retrying...\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

