#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define RED_RELAY_PIN 17
#define GREEN_RELAY_PIN 27
#define BLUE_RELAY_PIN 22
#define BH1750_ADDR 0x23
#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "lighting_log.txt"
#define LUX_THRESHOLD_RED 50.0f
#define LUX_THRESHOLD_GREEN 150.0f
#define LUX_THRESHOLD_BLUE 300.0f
#define BH1750_CONV_TIME_MS 120
#define POLL_INTERVAL_MS 1000

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static int i2c_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *red_line = NULL;
static struct gpiod_line *green_line = NULL;
static struct gpiod_line *blue_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return -1;
    }
    red_line = gpiod_chip_get_line(chip, RED_RELAY_PIN);
    green_line = gpiod_chip_get_line(chip, GREEN_RELAY_PIN);
    blue_line = gpiod_chip_get_line(chip, BLUE_RELAY_PIN);
    if (!red_line || !green_line || !blue_line) {
        perror("gpiod_chip_get_line");
        return -1;
    }
    if (gpiod_line_request_output(red_line, "lighting", 0) < 0 ||
        gpiod_line_request_output(green_line, "lighting", 0) < 0 ||
        gpiod_line_request_output(blue_line, "lighting", 0) < 0) {
        perror("gpiod_line_request_output");
        return -1;
    }
    return 0;
}

static int init_i2c(void) {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("open I2C bus");
        return -1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    return 0;
}

static int init_log(void) {
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen log");
        return -1;
    }
    return 0;
}

static int read_bh1750(float *lux) {
    unsigned char cmd = 0x10;
    if (write(i2c_fd, &cmd, 1) != 1) {
        perror("write BH1750 config");
        return -1;
    }
    usleep(BH1750_CONV_TIME_MS * 1000);
    unsigned char buf[2];
    if (read(i2c_fd, buf, 2) != 2) {
        perror("read BH1750 data");
        return -1;
    }
    unsigned int raw = ((unsigned int)buf[0] << 8) | buf[1];
    *lux = (float)raw / 1.2f;
    return 0;
}

static void set_relay(int r, int g, int b) {
    gpiod_line_set_value(red_line, r);
    gpiod_line_set_value(green_line, g);
    gpiod_line_set_value(blue_line, b);
}

static void log_data(float lux, int r, int g, int b) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(log_file, "%s, Lux: %.2f, Red: %d, Green: %d, Blue: %d\n",
            ts, lux, r, g, b);
    fflush(log_file);
}

static void cleanup(void) {
    set_relay(0, 0, 0);
    if (red_line) gpiod_line_release(red_line);
    if (green_line) gpiod_line_release(green_line);
    if (blue_line) gpiod_line_release(blue_line);
    if (chip) gpiod_chip_close(chip);
    if (i2c_fd >= 0) close(i2c_fd);
    if (log_file) fclose(log_file);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (init_gpio() < 0) { cleanup(); return 1; }
    if (init_i2c() < 0) { cleanup(); return 1; }
    if (init_log() < 0) { cleanup(); return 1; }

    printf("Smart Lighting System started. Press Ctrl+C to exit.\n");

    while (running) {
        float lux;
        if (read_bh1750(&lux) < 0) {
            fprintf(stderr, "BH1750 read error, retrying...\n");
            usleep(POLL_INTERVAL_MS * 1000);
            continue;
        }

        int r = 0, g = 0, b = 0;
        if (lux < LUX_THRESHOLD_RED) { r = 1; g = 0; b = 0; }
        else if (lux < LUX_THRESHOLD_GREEN) { r = 0; g = 1; b = 0; }
        else if (lux < LUX_THRESHOLD_BLUE) { r = 0; g = 0; b = 1; }
        else { r = 1; g = 1; b = 1; }

        set_relay(r, g, b);
        log_data(lux, r, g, b);
        printf("Lux: %.2f, Red: %d, Green: %d, Blue: %d\n", lux, r, g, b);

        usleep(POLL_INTERVAL_MS * 1000);
    }

    cleanup();
    printf("Smart Lighting System stopped.\n");
    return 0;
}

