#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define IN1 17
#define IN2 18
#define IN3 27
#define IN4 22
#define BUTTON_LOCK 24
#define BUTTON_UNLOCK 23
#define STEPS_PER_REV 512
#define STEP_DELAY_US 2000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void deenergize(void) {
    gpioWrite(IN1, 0);
    gpioWrite(IN2, 0);
    gpioWrite(IN3, 0);
    gpioWrite(IN4, 0);
}

static void step_sequence(int step) {
    switch (step) {
        case 0: gpioWrite(IN1, 1); gpioWrite(IN2, 0); gpioWrite(IN3, 0); gpioWrite(IN4, 0); break;
        case 1: gpioWrite(IN1, 0); gpioWrite(IN2, 1); gpioWrite(IN3, 0); gpioWrite(IN4, 0); break;
        case 2: gpioWrite(IN1, 0); gpioWrite(IN2, 0); gpioWrite(IN3, 1); gpioWrite(IN4, 0); break;
        case 3: gpioWrite(IN1, 0); gpioWrite(IN2, 0); gpioWrite(IN3, 0); gpioWrite(IN4, 1); break;
    }
}

static void rotate(int steps, int direction) {
    int step = 0;
    for (int i = 0; i < steps && running; i++) {
        if (direction == 1) {
            step = (step + 1) & 3;
        } else {
            step = (step + 3) & 3;
        }
        step_sequence(step);
        gpioDelay(STEP_DELAY_US);
    }
    deenergize();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(IN1, PI_OUTPUT) != 0 ||
        gpioSetMode(IN2, PI_OUTPUT) != 0 ||
        gpioSetMode(IN3, PI_OUTPUT) != 0 ||
        gpioSetMode(IN4, PI_OUTPUT) != 0 ||
        gpioSetMode(BUTTON_LOCK, PI_INPUT) != 0 ||
        gpioSetMode(BUTTON_UNLOCK, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetPullUpDown(BUTTON_LOCK, PI_PUD_UP);
    gpioSetPullUpDown(BUTTON_UNLOCK, PI_PUD_UP);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Automatic Door Lock Simulator\n");
    printf("Press the button to rotate the motor. Lock = clockwise, Unlock = counter-clockwise.\n");
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        if (gpioRead(BUTTON_LOCK) == 0) {
            printf("Locking door...\n");
            rotate(STEPS_PER_REV, 1);
            break;
        }
        if (gpioRead(BUTTON_UNLOCK) == 0) {
            printf("Unlocking door...\n");
            rotate(STEPS_PER_REV, 0);
            break;
        }
        gpioDelay(100000);
    }

    deenergize();
    gpioTerminate();
    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

