#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <sys/stat.h>
#include <sys/types.h>

#define MPU6050_ADDR 0x68
#define MPU6050_PWR_MGMT_1 0x6B
#define MPU6050_ACCEL_XOUT_H 0x3B
#define MPU6050_GYRO_XOUT_H 0x43
#define PWM_CHIP 2
#define PWM_CHANNEL 0
#define PWM_PERIOD_NS 20000000
#define PWM_DUTY_NS 0
#define LOG_FILE "solar_tracker.log"
#define I2C_BUS "/dev/i2c-1"
#define SAMPLE_DELAY_MS 100

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static int pwm_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) {
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    if (read(fd, buf, len) != len) {
        return -1;
    }
    return 0;
}

static int init_mpu6050(int fd) {
    if (i2c_write_byte(fd, MPU6050_PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to wake MPU-6050 (write PWR_MGMT_1).\n");
        return -1;
    }
    usleep(100000);
    return 0;
}

static int read_accel(int fd, int16_t *ax, int16_t *ay, int16_t *az) {
    uint8_t buf[6];
    if (i2c_read_burst(fd, MPU6050_ACCEL_XOUT_H, buf, 6) < 0) {
        return -1;
    }
    *ax = (int16_t)((buf[0] << 8) | buf[1]);
    *ay = (int16_t)((buf[2] << 8) | buf[3]);
    *az = (int16_t)((buf[4] << 8) | buf[5]);
    return 0;
}

static int read_gyro(int fd, int16_t *gx, int16_t *gy, int16_t *gz) {
    uint8_t buf[6];
    if (i2c_read_burst(fd, MPU6050_GYRO_XOUT_H, buf, 6) < 0) {
        return -1;
    }
    *gx = (int16_t)((buf[0] << 8) | buf[1]);
    *gy = (int16_t)((buf[2] << 8) | buf[3]);
    *gz = (int16_t)((buf[4] << 8) | buf[5]);
    return 0;
}

static int init_pwm(void) {
    char path[256];
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm%d", PWM_CHIP, PWM_CHANNEL);
    pwm_fd = open(path, O_WRONLY);
    if (pwm_fd < 0) {
        perror("Error opening PWM sysfs");
        return -1;
    }
    FILE *fp = fopen(path "/period", O_WRONLY);
    if (!fp) {
        perror("Error setting PWM period");
        close(pwm_fd);
        pwm_fd = -1;
        return -1;
    }
    if (fprintf(fp, "%d", PWM_PERIOD_NS) < 0) {
        perror("Error setting PWM period");
        fclose(fp);
        close(pwm_fd);
        pwm_fd = -1;
        return -1;
    }
    fclose(fp);
