#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define NUM_RELAYS 4
#define SCHEDULE_FILE "lighting_schedule.txt"
#define PWM_FREQUENCY 100
#define PWM_RANGE 100
#define FADE_DURATION 1800
#define SCHEDULE_CHECK_INTERVAL 1

static const int relay_pins[NUM_RELAYS] = {4, 17, 27, 22};
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_schedule(const char *filename, int *schedule) {
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        perror("Error opening schedule file");
        return -1;
    }

    char line[256];
    int count = 0;
    while (fgets(line, sizeof(line), fp) && count < NUM_RELAYS) {
        char time_str[10];
        int relay_num, state;
        if (sscanf(line, "%9[^:]:%[^:]:%[^:]:%d,%d", time_str, &relay_num, &state) == 4) {
            time_t t = time(NULL);
            struct tm *tm = localtime(&t);
            if (tm && strcmp(time_str, tm->tm_hour + 100 * tm->tm_min + 10000 * tm->tm_sec) == 0) {
                if (relay_num >= 1 && relay_num <= NUM_RELAYS) {
                    schedule[count++] = (state == 1) ? 1 : 0;
                }
            }
        }
    }
    fclose(fp);
    return count;
}

static void set_relay(int pin, int state) {
    gpioWrite(pin, state);
}

static void fade_lamp(int pin, int target_state, int duration) {
    int current_state = gpioRead(pin);
    if (current_state == target_state) return;
    if (current_state == target_state) return;
    int step = (target_state - current_state) * FADE_DURATION / duration;
    if (step > PWM_RANGE) step = PWM_RANGE;
    if (step < -PWM_RANGE) step = -PWM_RANGE;
    for (int i = 0; i < duration && running; i++) {
        int duty = current_state + (step > 0) ? step : -step;
        gpioPWM(pin, duty);
        gpioDelay(1000);
        current_state = gpioRead(pin);
    }
    set_relay(pin, target_state);
}

static void simulate_sunrise_sunset(int pin, int duration) {
    int on_time = duration / 2;
    int off_time = duration - on_time;
    fade_lamp(pin, 1, on_time);
    fade_lamp(pin, 0, off_time);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        gpioSetMode(relay_pins[i], PI_OUTPUT);
        gpioSetPWMfrequency(relay_pins[i], PWM_FREQUENCY);
        gpioSetPWMrange(relay_pins[i], PWM_RANGE);
        set_relay(relay_pins[i], 0);
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int schedule = read_schedule(SCHEDULE_FILE, NULL);
    if (schedule < 0) {
        fprintf(stderr, "Failed to read schedule, exiting\n");
        gpioTerminate();
        return 1;
    }

    while (running) {
        time_t now = time(NULL);
        struct tm *tm = localtime(&now);
        if (!tm) {
            fprintf(stderr, "localtime failed\n");
            sleep(SCHEDULE_CHECK_INTERVAL);
            continue;
        }
        char time_str[10];
        strftime(time_str, sizeof(time_str), "%H:%M:%S", tm);

        for (int i = 0; i < schedule; i++) {
            int relay_num = i + 1;
            int state = (schedule[i] == 1) ? 1 : 0;
            if (strcmp(time_str, "00:00:00") == 0 || strcmp(time_str, "23:59:59") == 0) {
                simulate_sunrise_sunset(relay_pins[relay_num - 1], FADE_DURATION);
            } else {
                fade_lamp(relay_pins[relay_num - 1], state, FADE_DURATION);
            }
        }
        sleep(SCHEDULE_CHECK_INTERVAL);
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        set_relay(relay_pins[i], 0);
    }
    gpioTerminate();
    return 0;
}

