#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 23
#define ECHO_PIN    24
#define BUZZER_PIN  18

#define MIN_DISTANCE_CM  2.0f
#define MAX_DISTANCE_CM  30.0f
#define MIN_FREQUENCY_HZ  200
#define MAX_FREQUENCY_HZ  2000

#define TRIGGER_PULSE_US  10
#define ECHO_TIMEOUT_US   30000   /* 30 ms max echo wait (~5 m round trip) */
#define LOOP_DELAY_US     60000   /* 50 Hz loop cadence */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Measure distance (cm) from the HC-SR04.
 * Returns >= 0 on success, -1.0 on timeout / out-of-range / sensor-absent.
 */
static float measure_distance(void)
{
    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(trigger, 0) failed\n");
        return -1.0f;
    }
    gpioDelay(5);

    /* 10 us trigger pulse */
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: gpioWrite(trigger, 1) failed\n");
        return -1.0f;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(trigger, 0) failed\n");
        return -1.0f;
    }

    uint32_t start_tick = 0, end_tick = 0;
    int timeout = 0;

    /* Wait for echo rising edge */
    while (gpioRead(ECHO_PIN) == 0) {
        if (++timeout > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Error: Echo start timeout (sensor absent or not responding)\n");
            return -1.0f;
        }
        gpioDelay(1);
    }
    start_tick = gpioTick();

    timeout = 0;
    /* Wait for echo falling edge */
    while (gpioRead(ECHO_PIN) == 1) {
        if (++timeout > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Error: Echo end timeout (out of range or stuck high)\n");
            return -1.0f;
        }
        gpioDelay(1);
    }
    end_tick = gpioTick();

    uint32_t pulse_us = end_tick - start_tick;
    if (pulse_us == 0 || pulse_us > ECHO_TIMEOUT_US) {
        fprintf(stderr, "Error: Invalid pulse width %u us\n", pulse_us);
        return -1.0f;
    }

    /* Speed of sound ~343 m/s => 1 us ~= 0.0343 cm */
    float distance = (float)pulse_us / 1000000.0f * 0.0343f;
    return distance;
}

static int map_distance_to_frequency(float distance)
{
    if (distance < MIN_DISTANCE_CM) distance = MIN_DISTANCE_CM;
    if (distance > MAX_DISTANCE_CM) distance = MAX_DISTANCE_CM;

    float freq = MIN_FREQUENCY_HZ +
                 (distance - MIN_DISTANCE_CM) *
                 (MAX_FREQUENCY_HZ - MIN_FREQUENCY_HZ) /
                 (MAX_DISTANCE_CM - MIN_DISTANCE_CM);

