        fprintf(fp, "timestamp_error, X: %.2f, Y: %.2f, Z: %.2f\n", x, y, z);
    }
    fclose(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                MPU6050_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    if (mpu6050_init(fd) < 0) {
        fprintf(stderr, "MPU-6050 initialization failed\n");
        close(fd);
        return 1;
    }

    printf("MPU-6050 initialized. Logging to %s every 100 ms. Press Ctrl+C to stop.\n", LOG_FILE);

    while (g_running) {
        float x, y, z;
        if (read_gyro(fd, &x, &y, &z) < 0) {
            fprintf(stderr, "Gyro read error; continuing\n");
        } else {
            log_data(x, y, z);
        }
        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down cleanly.\n");
    close(fd);
    return 0;
}

