#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <poll.h>
#include <gpiod.h>

#define GPIO_PIN        17
#define LOG_FILE        "vibration_events.log"
#define WINDOW_SIZE     5
#define DEFAULT_TIMEOUT_MS 1000
#define POLL_TIMEOUT_MS  1000

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static void log_event(FILE *log_file, int value)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    if (fprintf(log_file, "%s, %d\n", timestamp, value) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
    }
}

static void earthquake_alert(FILE *log_file, int value)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    printf("EARTHQUAKE ALERT: Vibration event at %s, value=%d\n", timestamp, value);
    if (fprintf(log_file, "EARTHQUAKE ALERT: Vibration event at %s, value=%d\n", timestamp, value) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
    }
    if (fflush(log_file) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
    }
}

int main(int argc, char *argv[])
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    FILE *log_file = NULL;
    int timeout_ms = DEFAULT_TIMEOUT_MS;
    int window[WINDOW_SIZE];
    int window_index = 0;
    int window_count = 0;
    int ret = EXIT_FAILURE;

    if (argc > 1) {
        timeout_ms = atoi(argv[1]);
        if (timeout_ms <= 0) {
            fprintf(stderr, "Invalid timeout value: %s\n", argv[1]);
            return EXIT_FAILURE;
        }
    }

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (signal(SIGTERM, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        goto cleanup;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (line == NULL) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", GPIO_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_rising_edge_events(line, "vibration_sensor") < 0) {
        fprintf(stderr, "Failed to request rising edge events on GPIO %d: %s\n", GPIO_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_falling_edge_events(line, "vibration_sensor") < 0) {
        fprintf(stderr, "Failed to request falling edge events on GPIO %d: %s\n", GPIO_PIN, strerror(errno));
        goto cleanup;
    }

    memset(window, 0, sizeof(window));

    printf("Monitoring vibration sensor on GPIO%d (rising/falling edges). Timeout: %d ms. Press Ctrl+C to exit.\n",
           GPIO_PIN, timeout_ms);

    while (program_running) {
        struct pollfd pfd;
        pfd.fd = gpiod_line_event_get_fd(line);
        pfd.events = POLLIN;
        pfd.revents = 0;

        int poll_ret = poll(&pfd, 1, timeout_ms);
        if (poll_ret < 0) {
            if (errno == EINTR) {
                continue;
            }
            fprintf(stderr, "poll() failed: %s\n", strerror(errno));
            break;
        }
        if (poll_ret == 0) {
            continue;
        }

        if (pfd.revents & POLLIN) {
            struct gpiod_line_event event;
            if (gpiod_line_event_read(line, &event) < 0) {
                fprintf(stderr, "gpiod_line_event_read failed: %s\n", strerror(errno));
                continue;
            }

            if (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
                log_event(log_file, 1);
                if (window_count < WINDOW_SIZE) {
                    window[window_index] = 1;
                    window_count++;
                    window_index = (window_index + 1) % WINDOW_SIZE;
                } else {
                    window[window_index] = 1;
                    window_index = (window_index + 1) % WINDOW_SIZE;
                    for (int i = 0; i < WINDOW_SIZE - 1; i++) {
                        window[i] = window[(i + 1) % WINDOW_SIZE];
                    }
                }
                if (window_count >= 3 && window_count == window_index + 1) {
                    earthquake_alert(log_file, 1);
                }
            } else if (event.event_type == GPIOD_LINE_EVENT_FALLING_EDGE) {
                log_event(log_file, 0);
            }
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line != NULL) {
        gpiod_line_release(line);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
    if (log_file != NULL) {
        if (fclose(log_file) != 0) {
            fprintf(stderr, "fclose failed: %s\n", strerror(errno));
        }
    }
    return ret;
}

