code:
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* LSM303DLHC magnetometer constants */
#define LSM303_M_ADDRESS        0x1E
#define LSM303_M_WHO_AM_I        0x0F
#define LSM303_M_WHO_AM_I_VAL    0xBD
#define CRA_REG_M                0x00
#define MR_REG_M                 0x02
#define OUT_X_L_M               0x03
#define OUT_X_H_M               0x04
#define OUT_Z_L_M               0x05
#define OUT_Z_H_M               0x06
#define OUT_Y_L_M               0x07
#define OUT_Y_H_M               0x08

#define I2C_BUS                 "/dev/i2c-1"
#define CSV_FILE                "mag_log.csv"
#define SAMPLE_PERIOD_US        1000000  /* 1 second */
#define NUM_DIRECTIONS          8

/* Calibration offsets (replace with your calibrated values) */
#define X_OFFSET                10.0f
#define Y_OFFSET                -5.0f
#define Z_OFFSET                20.0f

typedef struct {
    float x;
    float y;
    float z;
} calibrated_data_t;

typedef struct {
    char  name[NUM_DIRECTIONS][16];
    float angles[NUM_DIRECTIONS];
} compass_directions_t;

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_csv_fp = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, int16_t *value)
{
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read 16-bit from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *value = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int initialize_magnetometer(int fd)
{
    uint8_t who_am_i = 0;
    if (i2c_read_reg8(fd, LSM303_M_WHO_AM_I, &who_am_i) != 0) {
        fprintf(stderr, "Cannot read WHO_AM_I register\n");
        return -1;
    }
    if (who_am_i != LSM303_M_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who_am_i, LSM303_M_WHO_AM_I_VAL);
        return -1;
    }

    /* Set continuous-conversion mode (ODR = 1 Hz, 8-average) */
    if (i2c_write_reg8(fd, CRA_REG_M, 0x00) != 0)
        return -1;

    /* Set magnetometer to continuous-conversion mode */
    if (i2c_write_reg8(fd, MR_REG_M, 0x00) != 0)
        return -1;

    return 0;
}

static int read_magnetometer_data(int fd, calibrated_data_t *data)
{
    int16_t raw_x, raw_y, raw_z;

    if (i2c_read_reg16(fd, OUT_X_H_M, &raw_x) != 0) return -1;
    if (i2c_read_reg16(fd, OUT_Y_H_M, &raw_y) != 0) return -1;
    if (i2c_read_reg16(fd, OUT_Z_H_M, &raw_z) != 0) return -1;

    /* Combine MSB and LSB; LSM303DLHC outputs X, Z, Y in that order */
    data->x = (float)raw_x;
    data->z = (float)raw_z;
    data->y = (float)raw_y;

    /* Apply hard-iron calibration offsets */
    data->x -= X_OFFSET;
    data->y -= Y_OFFSET;
    data->z -= Z_OFFSET;

    return 0;
}

static float calculate_heading(float x, float y)
{
    float heading = atan2f(y, x) * 180.0f / (float)M_PI;
    if (heading < 0.0f)
        heading += 360.0f;
    return heading;
}

static const char *compass_direction(float heading)
{
    const float angles[NUM_DIRECTIONS] = {
        45.0f, 135.0f, 225.0f, 315.0f,
        90.0f, 180.0f, 270.0f, 0.0f
    };
    const char  *names[NUM_DIRECTIONS] = {
        "N", "NE", "E", "SE",
        "S", "SW", "W", "NW"
    };

    for (int i = 0; i < NUM_DIRECTIONS; i++) {
        if (angles[i] - 22.5f <= heading && heading < angles[i] + 22.5f)
            return names[i];
    }
    return "UNKNOWN";
}

static int log_data(FILE *fp, const calibrated_data_t *data, float heading)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    if (fprintf(fp, "%s,%.2f,%.2f,%.2f,%.2f,%s\n",
                timestamp, data->x, data->y, data->z, heading,
                compass_direction(heading)) < 0) {
        fprintf(stderr, "Failed to write CSV row: %s\n", strerror(errno));
        return -1;
    }
    fflush(fp);
    return 0;
}

static int ensure_csv_header(FILE *fp)
{
    long pos = ftell(fp);
    if (pos < 0) {
        fprintf(stderr, "ftell failed: %s\n", strerror(errno));
        return -1;
    }
    if (pos == 0) {
        if (fprintf(fp, "Timestamp,Calibrated X,Calibrated Y,Calibrated Z,Heading,Direction\n") < 0) {
            fprintf(stderr, "Failed to write CSV header: %s\n", strerror(errno));
            return -1;
        }
        fflush(fp);
    }
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install signal handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, LSM303_M_ADDRESS) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                LSM303_M_ADDRESS, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    if (initialize_magnetometer(g_i2c_fd) != 0) {
        fprintf(stderr, "Magnetometer initialization failed\n");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    g_csv_fp = fopen(CSV_FILE, "a");
    if (g_csv_fp == NULL) {
        fprintf(stderr, "Cannot open %s: %s\n", CSV_FILE, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    if (ensure_csv_header(g_csv_fp) != 0) {
        fclose(g_csv_fp);
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    printf("LSM303DLHC magnetometer logging started. Press Ctrl+C to stop.\n");

    while (g_running) {
        calibrated_data_t data;
        if (read_magnetometer_data(g_i2c_fd, &data) != 0) {
            fprintf(stderr, "Read error; skipping sample\n");
        } else {
            float heading = calculate_heading(data.x, data.y);
            if (log_data(g_csv_fp, &data, heading) != 0) {
                fprintf(stderr, "CSV write error; continuing\n");
            }
            printf("Calibrated X: %.2f, Y: %.2f, Z: %.2f, Heading: %.2f, Direction: %s\n",
                   data.x, data.y, data.z, heading, compass_direction(heading));
        }
        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down cleanly...\n");
    if (g_csv_fp) fclose(g_csv_fp);
