#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17
#define DEBOUNCE_US 200000  /* 200 ms in microseconds */

static volatile sig_atomic_t running = 1;
static volatile sig_atomic_t relay_state = 0;
static volatile uint32_t last_touch_tick = 0;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

static void touch_callback(int gpio, int level, uint32_t tick)
{
    (void)gpio;

    if (level != 1) {
        /* Only act on rising edge (touch detected) */
        return;
    }

    /* Debounce: ignore touches within DEBOUNCE_US of the last one */
    uint32_t elapsed = tick - last_touch_tick;
    if (elapsed < DEBOUNCE_US) {
        return;
    }
    last_touch_tick = tick;

    relay_state = !relay_state;
    if (gpioWrite(RELAY_PIN, relay_state) < 0) {
        fprintf(stderr, "Error: gpioWrite failed on relay pin %d\n", RELAY_PIN);
        return;
    }

    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "Error: time() failed\n");
        return;
    }

    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "Error: localtime_r failed\n");
        return;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", &tm_info) == 0) {
        fprintf(stderr, "Error: strftime failed\n");
        return;
    }

    char log_entry[128];
    int len = snprintf(log_entry, sizeof(log_entry),
                       "{\"timestamp\":\"%s\",\"relay_state\":\"%s\"}",
                       timestamp, relay_state ? "ON" : "OFF");
    if (len < 0 || (size_t)len >= sizeof(log_entry)) {
        fprintf(stderr, "Error: log entry formatting failed\n");
        return;
    }

    FILE *fp = fopen("relay_log.json", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: cannot open relay_log.json for appending\n");
        return;
    }

    if (fprintf(fp, "%s\n", log_entry) < 0) {
        fprintf(stderr, "Error: fprintf to log file failed\n");
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Warning: fclose on log file failed\n");
    }
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for touch sensor pin %d\n",
                TOUCH_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for relay pin %d\n",
                RELAY_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(TOUCH_SENSOR_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown failed for touch sensor pin %d\n",
                TOUCH_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(RELAY_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite failed to initialise relay pin %d\n",
                RELAY_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetISRFunc(TOUCH_SENSOR_PIN, RISING_EDGE, 0, touch_callback) < 0) {
        fprintf(stderr, "Error: gpioSetISRFunc failed for touch sensor pin %d\n",
                TOUCH_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error: sigaction(SIGINT) failed\n");
        gpioSetISRFunc(TOUCH_SENSOR_PIN, RISING_EDGE, 0, NULL);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Touch sensor relay control started. Press Ctrl+C to exit.\n");

    while (running) {
        gpioDelay(100000); /* 100 ms */
    }

    /* Graceful shutdown */
    gpioWrite(RELAY_PIN, 0);
    gpioSetISRFunc(TOUCH_SENSOR_PIN, RISING_EDGE, 0, NULL);

    FILE *fp = fopen("relay_log.json", "a");
    if (fp != NULL) {
        time_t now = time(NULL);
        struct tm tm_info;
        if (now != (time_t)-1 && localtime_r(&now, &tm_info) != NULL) {
            char timestamp[32];
            if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z",
                         &tm_info) > 0) {
                fprintf(fp, "{\"timestamp\":\"%s\",\"relay_state\":\"OFF\"}\n",
                        timestamp);
            }
        }
        fclose(fp);
    }

    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return EXIT_SUCCESS;
}

