#include <unistd.h>
#include <gpiod.h>

#define NUM_RELAYS 4
#define MOISTURE_THRESHOLD 30
#define RELAY_ON_TIME 5
#define RELAY_GAP_TIME 1
#define LOOP_INTERVAL 10
#define LOG_FILE "irrigation_log.txt"

static const unsigned int relay_pins[NUM_RELAYS] = {17, 23, 24, 25};
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *lines[NUM_RELAYS];
static FILE *log_fp = NULL;
static volatile sig_atomic_t running = 1;

static void cleanup(void) {
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (lines[i]) {
            gpiod_line_set_value(lines[i], 1);
            gpiod_line_release(lines[i]);
            lines[i] = NULL;
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (log_fp) {
        fclose(log_fp);
        log_fp = NULL;
    }
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return -1;
    }
    for (int i = 0; i < NUM_RELAYS; i++) {
        lines[i] = gpiod_chip_get_line(chip, relay_pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "gpiod_chip_get_line failed for pin %u\n", relay_pins[i]);
            return -1;
        }
        int ret = gpiod_line_request_output(lines[i], "irrigation", 1);
        if (ret < 0) {
            fprintf(stderr, "gpiod_line_request_output failed for pin %u\n", relay_pins[i]);
            return -1;
        }
    }
    return 0;
}

static int activate_relay(int relay_num, int moisture_level) {
    if (moisture_level >= MOISTURE_THRESHOLD) return 0;
    if (gpiod_line_set_value(lines[relay_num], 0) < 0) {
        perror("gpiod_line_set_value (ON)");
        return -1;
    }
    time_t rawtime = time(NULL);
    struct tm *timeinfo = localtime(&rawtime);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);
    fprintf(log_fp, "%s - Relay %d activated, Moisture: %d\n", timestamp, relay_num + 1, moisture_level);
    fflush(log_fp);
    sleep(RELAY_ON_TIME);
    if (gpiod_line_set_value(lines[relay_num], 1) < 0) {
        perror("gpiod_line_set_value (OFF)");
        return -1;
    }
    sleep(RELAY_GAP_TIME);
    return 0;
}

int main(void) {
    srand((unsigned int)time(NULL));
    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        perror("fopen");
        return 1;
    }
    if (init_gpio() < 0) {
        cleanup();
        return 1;
    }
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    while (running) {
        int moisture_level = rand() % 101;
        printf("Moisture level: %d\n", moisture_level);
        for (int i = 0; i < NUM_RELAYS; i++) {
            if (activate_relay(i, moisture_level) < 0) {
                fprintf(stderr, "Error activating relay %d\n", i + 1);
            }
        }
        sleep(LOOP_INTERVAL);
    }
    cleanup();
    return 0;
}

