/*
 * Automated Plant Watering System (Raspberry Pi Zero W)
 * Servo control via pigpio library.
 *
 * Wiring:
 *   - Water valve servo: GPIO17 (physical pin 11)
 *   - Directional nozzle servo: GPIO18 (physical pin 12)
 *
 * Compile: gcc -Wall -Wextra -O2 -o watering watering.c -lpigpio -lrt
 * Run:     sudo ./watering
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define VALVE_SERVO_PIN 17
#define NOZZLE_SERVO_PIN 18

#define SERVO_MIN_PULSE_WIDTH 500   /* ~0 degrees   */
#define SERVO_MID_PULSE_WIDTH 1500  /* ~90 degrees  */
#define SERVO_MAX_PULSE_WIDTH 2500  /* ~180 degrees */

#define MOISTURE_THRESHOLD 50
#define SERVO_SETTLE_DELAY_US 500000 /* 500 ms */
#define SERVO_SETTLE_DELAY_S 5
#define NOZZLE_STEP_DELAY_S 2
#define NOZZLE_HOLD_DELAY_S 5
#define WATERING_CYCLE_DELAY_S 5

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Set servo angle (0-180 degrees) with retry on failure. */
static int set_servo_angle(int pin, int angle)
{
    if (angle < 0 || angle > 180) {
        fprintf(stderr, "Invalid angle %d for pin %d\n", angle, pin);
        return -1;
    }

    int pulse_width = SERVO_MID_PULSE_WIDTH - (angle * (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH) / 180);

    for (int attempt = 0; attempt < 3; attempt++) {
        int rc = gpioServo(pin, pulse_width);
        if (rc == 0) {
            return 0;
        }
        fprintf(stderr, "gpioServo(pin=%d, pw=%d) failed (rc=%d), attempt %d/3\n",
                pin, pulse_width, rc, attempt + 1);
        if (attempt < 2) {
            gpioDelay(100000); /* 100 ms backoff */
        }
    }
    fprintf(stderr, "gpioServo(pin=%d, pw=%d) failed after 3 attempts\n", pin, pulse_width);
    return -1;
}

/* Close the valve servo (0 degrees). */
static int close_valve(void)
{
    return set_servo_angle(VALVE_SERVO_PIN, 0);
}

/* Open the valve servo (90 degrees). */
static int open_valve(void)
{
    return set_servo_angle(VALVE_SERVO_PIN, 90);
}

/* Sweep nozzle servo through 0, 45, 90, 135, 180 degrees. */
static int sweep_nozzle(void)
{
    int angles[] = {0, 45, 90, 135, 180};
    int num_angles = (int)(sizeof(angles) / sizeof(angles[0]));

    for (int i = 0; i < num_angles; i++) {
        int angle = angles[i];
        if (set_servo_angle(NOZZLE_SERVO_PIN, angle) != 0) {
            fprintf(stderr, "Failed to set nozzle servo to %d degrees (index %d)\n",
                    angle, i);
            return -1;
        }
        gpioDelay((NOZZLE_STEP_DELAY_S + 0.5) * 1000000); /* 2.5 s */
    }
    return 0;
}

/* Close the valve servo. Returns 0 on success, -1 on failure. */
static int close_valve_if_needed(void)
{
    if (close_valve() != 0) {
        fprintf(stderr, "Critical: valve servo failed to close after watering cycle\n");
        return -1;
    }
    return 0;
}

int main(void)
{
    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Ensure servos are stopped before any gpio functions */
    gpioServo(VALVE_SERVO_PIN, 0);
    gpioServo(NOZZLE_SERVO_PIN, 0);

    int moisture_cycle[] = {20, 40, 60, 80, 100};
    int num_moisture_readings = (int)(sizeof(moisture_cycle) / sizeof(moisture_cycle[0]));

    while (g_running) {
        for (int i = 0; i < num_moisture_readings && g_running; i++) {
            int moisture = moisture_cycle[i];

            if (moisture < MOISTURE_THRESHOLD) {
                printf("Moisture level: %d (below threshold %d) - watering\n",
                       moisture, MOISTURE_THRESHOLD);

                if (open_valve() != 0) {
                    fprintf(stderr, "Critical: failed to open valve servo\n");
                    break;
                }

                if (sweep_nozzle() != 0) {
                    fprintf(stderr, "Critical: nozzle servo sweep failed\n");
                    break;
                }

                if (close_valve_if_needed() != 0) {
                    fprintf(stderr, "Critical: failed to close valve servo after watering\n");
                    break;
                }

                /* Hold valve open for 5 seconds */
                gpioDelay((NOZZLE_HOLD_DELAY_S + 0.5) * 1000000);

                if (!g_running) {
                    break;
                }
            } else {
                printf("Moisture level: %d (above threshold %d) - no watering\n",
                       moisture, MOISTURE_THRESHOLD);
            }

            /* Wait 5 seconds between readings */
            gpioDelay((WATERING_CYCLE_DELAY_S + 0.5) * 1000000);
        }

        if (g_running) {
            /* Wait 5 seconds between moisture cycles */
            gpioDelay((WATERING_CYCLE_DELAY_S + 0.5) * 1000000);
        }
    }

    /* Graceful shutdown: stop servos and release pigpio */
    gpioServo(VALVE_SERVO_PIN, 0);
    gpioServo(NOZZLE_SERVO_PIN, 0);
    gpioTerminate();

    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

