    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                MPU6050_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    if (init_mpu6050(i2c_fd) < 0) {
        fprintf(stderr, "Failed to initialize MPU-6050 (sensor absent or bus error).\n");
        close(i2c_fd);
        return 1;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    fprintf(log_fp, "# MPU-6050 Gyro Log - started\n");
    fprintf(log_fp, "timestamp,x_dps,y_dps,z_dps\n");
    fflush(log_fp);

    printf("MPU-6050 initialized. Logging to %s at 10 Hz. Press Ctrl+C to stop.\n", LOG_FILE);

    while (running) {
        float x, y, z;
        if (read_gyro_data(i2c_fd, &x, &y, &z) < 0) {
            fprintf(stderr, "Gyro read error; continuing.\n");
        } else {
            log_data(log_fp, x, y, z);
        }
        usleep(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down cleanly...\n");
    if (log_fp) fclose(log_fp);
    if (i2c_fd >= 0) close(i2c_fd);
    return 0;
}

