    }
    return 0;
}

static int rotate_counter_clockwise(void) {
    for (int i = 0; i < STEPS_PER_ROTATION; i++) {
        if (!running) return -1;
        for (int j = 3; j >= 0; j--) {
            if (safe_write(IN1, step_sequence[j][0]) != 0) return -1;
            if (safe_write(IN2, step_sequence[j][1]) != 0) return -1;
            if (safe_write(IN3, step_sequence[j][2]) != 0) return -1;
            if (safe_write(IN4, step_sequence[j][3]) != 0) return -1;
        }
        gpioDelay(STEP_DELAY_US);
    }
    return 0;
