        fprintf(stderr, "Error: failed to rotate motor counter-clockwise\n");
        return -1;
    }
    if (deenergize() != 0) {
        fprintf(stderr, "Error: failed to de-energize coils\n");
        return -1;
    }
    printf("Door unlocked.\n");
    return 0;
}

