        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (safe_set_mode(IN1, PI_OUTPUT) != 0 ||
        safe_set_mode(IN2, PI_OUTPUT) != 0 ||
        safe_set_mode(IN3, PI_OUTPUT) != 0 ||
        safe_set_mode(IN4, PI_OUTPUT) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (safe_pull_up(LOCK_BUTTON) != 0 || safe_pull_up(UNLOCK_BUTTON) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

