/*
 * HC-SR04 ultrasonic distance logger for Raspberry Pi 4 Model B.
 * Uses libgpiod v2.x API (gpiod.h).  Trigger on BCM GPIO17, echo on BCM GPIO18.
 * Logs distance in cm to distance_log.txt once per second.
 *
 * Build:  gcc -O2 -Wall -Wextra -o hcsr04_log hcsr04_log.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <gpiod.h>

#define TRIGGER_PIN  17          /* BCM GPIO17 */
#define ECHO_PIN     18          /* BCM GPIO18 */
#define LOG_FILE     "distance_log.txt"
#define SPEED_CM_US  0.01715     /* 343 m/s in cm per microsecond */
#define TRIGGER_US   10          /* 10 us trigger pulse */
#define ECHO_TIMEOUT_US 50000    /* 50 ms max echo wait */
#define MEASURE_INTERVAL_S 1
#define ECHO_GUARD_US 60000      /* 60 ms between measurements */

static volatile sig_atomic_t g_running = 1;
static FILE *g_log = NULL;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static void sleep_us(unsigned int us)
{
    struct timespec ts = {
        .tv_sec  = us / 1000000U,
        .tv_nsec = (long)(us % 1000000U) * 1000L
    };
    nanosleep(&ts, NULL);
}

/*
 * Busy-wait for the echo line to reach the requested value.
 * Returns 0 on success, -1 on timeout or read error.
 */
static int wait_for_value(struct gpiod_line *line, int val, unsigned int timeout_us)
{
    unsigned int elapsed = 0;
    while (gpiod_line_get_value(line) != val) {
        if (elapsed >= timeout_us)
            return -1;
        sleep_us(1);
        elapsed++;
    }
    return 0;
}

/*
 * Measure the echo pulse width in microseconds.
 * Returns duration in microseconds, or -1 on timeout/error.
 */
static long measure_pulse(struct gpiod_line *trig, struct gpiod_line *echo)
{
    /* Ensure trigger starts low */
    if (gpiod_line_set_value(trig, 0) < 0) {
        fprintf(stderr, "Error: failed to set trigger low: %s\n", strerror(errno));
        return -1;
    }
    sleep_us(5);

    /* 10 us trigger pulse */
    if (gpiod_line_set_value(trig, 1) < 0) {
        fprintf(stderr, "Error: failed to set trigger high: %s\n", strerror(errno));
        return -1;
    }
    sleep_us(TRIGGER_US);
    if (gpiod_line_set_value(trig, 0) < 0) {
        fprintf(stderr, "Error: failed to reset trigger low: %s\n", strerror(errno));
        return -1;
    }

    /* Wait for echo rising edge (timeout 50 ms) */
    if (wait_for_value(echo, 1, ECHO_TIMEOUT_US) < 0) {
        fprintf(stderr, "Error: timeout waiting for echo rising edge\n");
        return -1;
    }

    /* Measure echo high duration */
    unsigned int elapsed = 0;
    long duration = 0;
    while (gpiod_line_get_value(echo) == 1) {
        if (elapsed >= ECHO_TIMEOUT_US) {
            fprintf(stderr, "Error: timeout waiting for echo falling edge\n");
            return -1;
        }
        sleep_us(1);
        elapsed++;
    }

    duration = (long)elapsed;
    return duration;
}

static void log_distance(FILE *fp, long duration_us)
{
    double distance = (double)duration_us * SPEED_CM_US;
    if (distance < 0.0 || distance > 400.0) {
        fprintf(fp, "-1\n");
        fprintf(stderr, "Warning: distance out of range (%.2f cm)\n", distance);
    } else {
        fprintf(fp, "%.2f\n", distance);
    }
    fflush(fp);
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL;
    struct gpiod_line *echo = NULL;
    int ret = EXIT_FAILURE;

    /* Signal handling */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error: sigaction(SIGINT): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error: sigaction(SIGTERM): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open log file once */
    g_log = fopen(LOG_FILE, "a");
    if (!g_log) {
        fprintf(stderr, "Error: cannot open %s: %s\n", LOG_FILE, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open default gpiochip (gpiochip0 on Pi 4) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error: gpiod_chip_open_by_name: %s\n", strerror(errno));
        goto cleanup;
    }

    trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trig) {
        fprintf(stderr, "Error: gpiod_chip_get_line(%d): %s\n", TRIGGER_PIN, strerror(errno));
        goto cleanup;
    }

    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo) {
        fprintf(stderr, "Error: gpiod_chip_get_line(%d): %s\n", ECHO_PIN, strerror(errno));
        goto cleanup;
    }

    /* Request trigger as output, initial value low */
    if (gpiod_line_request_output(trig, "hcsr04-trig", 0) < 0) {
        fprintf(stderr, "Error: request trigger output: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Request echo as input */
    if (gpiod_line_request_input(echo, "hcsr04-echo") < 0) {
        fprintf(stderr, "Error: request echo input: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("HC-SR04 distance logger started.  Trigger=BCM%d  Echo=BCM%d  Log=%s\n",
           TRIGGER_PIN, ECHO_PIN, LOG_FILE);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        long duration = measure_pulse(trig, echo);
        if (duration < 0) {
            fprintf(stderr, "Error: measurement failed, logging -1\n");
            log_distance(g_log, 0);
        } else {
            log_distance(g_log, duration);
        }
        /* Guard against false echoes */
        sleep_us(ECHO_GUARD_US);
    }

    printf("\nShutting down...\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (trig)
        gpiod_line_release(trig);
    if (echo)
        gpiod_line_release(echo);
    if (chip)
        gpiod_chip_close(chip);
    if (g_log) {
        fclose(g_log);
        g_log = NULL;
    }
    return ret;
}

