/*
 * Proximity-based automated door system for Raspberry Pi 4 Model B
 * Sensor : VL53L1X time-of-flight (I2C bus 1, address 0x29)
 * Library: pigpio
 *
 * Build  : gcc -O2 -Wall -o door_system door_system.c -lpigpio -lrt
 * Run    : sudo ./door_system
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- VL53L1X constants (16-bit register addresses) ---- */
#define VL53L1X_ADDR             0x29
#define VL53L1X_REG_SOFT_RESET   0x0000
#define VL53L1X_REG_SYSTEM_MODE  0x0080
#define VL53L1X_REG_INT_STATUS   0x0044
#define VL53L1X_REG_RESULT_DIST  0x0096
#define VL53L1X_REG_RESULT_INT  0x0097

#define I2C_BUS                 1
#define RELAY_PIN               18
#define DISTANCE_THRESHOLD_CM    50
#define POLL_DELAY_US           100000  /* 100 ms */

/* ---- Globals for signal handler ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit register on the VL53L1X (pigpio i2cWriteWordData).    */
/* The VL53L1X expects the register address in its high byte.          */
/* ------------------------------------------------------------------ */
static int vl53l1x_write_reg16(int handle, uint16_t reg, uint16_t value)
{
    int rc = i2cWriteWordData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg 0x%04X, val 0x%04X): %s\n",
                reg, value, pigpio_error(rc));
    }
    return rc;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit register from the VL53L1X.                             */
/* ------------------------------------------------------------------ */
static int vl53l1x_read_reg16(int handle, uint16_t reg, uint16_t *out)
{
    int rc = i2cReadWordData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg 0x%04X): %s\n",
                reg, pigpio_error(rc));
        return -1;
    }
    *out = (uint16_t)rc;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialise the VL53L1X for continuous ranging.                       */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int vl53l1x_init(int handle)
{
    /* 1. Software reset */
    if (vl53l1x_write_reg16(handle, VL53L1X_REG_SOFT_RESET, 0x00) < 0)
        return -1;
    gpioDelay(1000);  /* 1 ms settle */

    /* 2. Clear any pending interrupt */
    if (vl53l1x_write_reg16(handle, VL53L1X_REG_INT_STATUS, 0x00) < 0)
        return -1;

    /* 3. Set ranging mode: continuous back-to-back ranging */
    if (vl53l1x_write_reg16(handle, VL53L1X_REG_SYSTEM_MODE, 0x01) < 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read the latest distance in centimetres.                            */
/* Returns -1 on error, -2 if no data ready yet, otherwise distance.  */
/* ------------------------------------------------------------------ */
static int vl53l1x_read_distance_cm(int handle)
{
    uint16_t int_status = 0;
    uint16_t dist_msb  = 0;
    uint16_t dist_lsb  = 0;
    int rc;

    /* Check if data is ready */
    rc = vl53l1x_read_reg16(handle, VL53L1X_REG_INT_STATUS, &int_status);
    if (rc < 0)
        return -1;

    if ((int_status & 0x01) == 0) {
        /* No new data yet */
        return -2;
    }

    /* Read 16-bit distance result */
    rc = vl53l1x_read_reg16(handle, VL53L1X_REG_RESULT_DIST, &dist_msb);
    if (rc < 0)
        return -1;

    rc = vl53l1x_read_reg16(handle, VL53L1X_REG_RESULT_INT, &dist_lsb);
    if (rc < 0)
        return -1;

    /* Distance is 16-bit, 0.5 cm per LSB (16-bit mode) */
    return (int)((dist_msb << 8) | dist_lsb) / 2;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    int distance;
    int rc;

    /* ---- Initialise pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus ---- */
    g_i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%02X: %s\n",
                I2C_BUS, VL53L1X_ADDR, pigpio_error(g_i2c_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Initialise sensor ---- */
    if (vl53l1x_init(g_i2c_handle) < 0) {
        fprintf(stderr, "VL53L1X initialisation failed (sensor absent or bus error)\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Configure relay pin ---- */
    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioWrite(RELAY_PIN, 0);  /* ensure door starts closed */

    /* ---- Signal handling ---- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Proximity door system started. Press Ctrl+C to exit.\n");

    /* ---- Main loop ---- */
    while (g_running) {
        distance = vl53l1x_read_distance_cm(g_i2c_handle);

        if (distance < 0) {
            fprintf(stderr, "Sensor read error (code %d)\n", distance);
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        if (distance == -2) {
            /* No new data yet; wait briefly and retry */
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        printf("Distance: %d cm\n", distance);

        if (distance <= DISTANCE_THRESHOLD_CM) {
            gpioWrite(RELAY_PIN, 1);  /* door open */
        } else {
            gpioWrite(RELAY_PIN, 0);  /* door close */
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* ---- Cleanup ---- */
    printf("\nShutting down...\n");
    gpioWrite(RELAY_PIN, 0);
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

