    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int mpu6050_init(int fd)
{
    /* Wake up the MPU-6050 (clear sleep bit) */
    if (i2c_write_reg(fd, REG_PWR_MGMT_1, 0x00) < 0)
        return -1;
    usleep(100000); /* 100 ms stabilization */

    /* Set sample rate divider to 7 -> 1 kHz / (1 + 7) = 125 Hz */
    if (i2c_write_reg(fd, REG_SMPLRT_DIV, 0x07) < 0)
        return -1;

    /* Set gyroscope full-scale range to ±250 dps */
    if (i2c_write_reg(fd, REG_GYRO_CONFIG, 0x00) < 0)
        return -1;

    return 0;
}

static int read_gyro_data(int fd, float *x, float *y, float *z)
{
    uint8_t buf[6];
    if (i2c_read_burst(fd, REG_GYRO_XOUT_H, buf, 6) < 0)
        return -1;

    int16_t raw_x = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_y = (int16_t)((buf[2] << 8) | buf[3]);
    int16_t raw_z = (int16_t)((buf[4] << 8) | buf[5]);

    *x = (float)raw_x / GYRO_SENSITIVITY;
    *y = (float)raw_y / GYRO_SENSITIVITY;
    *z = (float)raw_z / GYRO_SENSITIVITY;

    return 0;
}

int main(void)
{
    int fd = -1;
    float x, y, z;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install signal handlers: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the I2C bus */
    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire the I2C slave address */
    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Failed to acquire I2C bus access to 0x%02X: %s\n",
                MPU6050_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    /* Initialize the MPU-6050 */
    if (mpu6050_init(fd) < 0) {
        fprintf(stderr, "MPU-6050 initialization failed.\n");
        close(fd);
        return EXIT_FAILURE;
    }

    printf("MPU-6050 initialized. Reading gyroscope data (Ctrl+C to stop)...\n");

    /* Main loop */
    while (g_running) {
        if (read_gyro_data(fd, &x, &y, &z) == 0) {
            printf("X: %.2f dps, Y: %.2f dps, Z: %.2f dps\n", x, y, z);
        } else {
            fprintf(stderr, "Failed to read gyroscope data.\n");
        }
        usleep(100000); /* 100 ms sampling interval */
    }

    printf("\nExiting gracefully...\n");
    close(fd);
    return EXIT_SUCCESS;
}

