/*
 * Automated Plant Watering System (libgpiod v1 API)
 * Board:  Raspberry Pi 4 Model B
 * Relays: 4x 5V relay modules on BCM GPIO17, GPIO18, GPIO27, GPIO22
 * (physical pins 11, 12, 13, 15)
 * Logic:  Active-low relays; HIGH = relay OFF, LOW = relay ON
 * Timing: Each relay ON for 5 s, then 86400 s (24 h) before next cycle
 * Log:    Watering start times written to watering_log.txt
 * Build:  gcc -o watering watering.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define NUM_RELAYS      4
#define RELAY_DURATION  5          /* seconds per relay */
#define CYCLE_INTERVAL  86400      /* seconds between cycles */
#define POLL_INTERVAL   60         /* seconds between polling checks */
#define LOG_FILE        "watering_log.txt"

static const unsigned int relay_pins[NUM_RELAYS] = {17, 18, 27, 22};

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static int log_watering_time(void)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return -1;
    }

    time_t now = time(NULL);
    if (now == (time_t)-1) {
        perror("time()");
        fclose(fp);
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        perror("localtime_r()");
        fclose(fp);
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s\n", ts) < 0) {
        perror("fprintf()");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("fclose()");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
static int set_relay(struct gpiod_line *line, int value)
{
    if (gpiod_line_set_value(line, value) < 0) {
        perror("gpiod_line_set_value()");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_RELAYS];
    int line_requested = 0;
    int rc = EXIT_FAILURE;

    for (int i = 0; i < NUM_RELAYS; i++) {
        lines[i] = NULL;
    }

    /* ---- Signal handling ------------------------------------------ */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        goto cleanup;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        goto cleanup;
    }

    /* ---- Open GPIO chip ------------------------------------------- */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name(\"gpiochip0\")");
        goto cleanup;
    }

    /* ---- Request each relay line as output, active-low (HIGH = OFF) */
    for (int i = 0; i < NUM_RELAYS; i++) {
        lines[i] = gpiod_chip_get_line(chip, relay_pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "gpiod_chip_get_line(%u) failed\n", relay_pins[i]);
            goto cleanup;
        }

        if (gpiod_line_request_output(lines[i], "watering", 1) < 0) {
            fprintf(stderr, "gpiod_line_request_output(%u) failed\n", relay_pins[i]);
            goto cleanup;
        }
        line_requested = 1;
    }

    /* ---- Ensure all relays start OFF (HIGH) ----------------------- */
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (set_relay(lines[i], 1) < 0) {
            goto cleanup;
        }
    }

    printf("Watering system started. Press Ctrl+C to exit.\n");

    /* ---- Main loop ------------------------------------------------- */
    while (g_running) {
        time_t start = time(NULL);

        for (int i = 0; i < NUM_RELAYS; i++) {
            if (!g_running) {
                break;
            }
            if (set_relay(lines[i], 0) < 0) {
                goto cleanup;
            }
            printf("Relay %d ON for %d s\n", i + 1, RELAY_DURATION);
            sleep(RELAY_DURATION);

            if (set_relay(lines[i], 1) < 0) {
                goto cleanup;
            }
            printf("Relay %d OFF\n", i + 1);
        }

        if (g_running) {
            if (log_watering_time() < 0) {
                fprintf(stderr, "Warning: failed to log watering event\n");
            }
        }

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int s = 0; s < POLL_INTERVAL && g_running; s++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    rc = EXIT_SUCCESS;

cleanup:
    /* ---- Release lines and close chip -------------------------------- */
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return rc;
}

