#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define NUM_RELAYS 4
#define PWM_FREQUENCY 1000
#define PWM_RANGE 255
#define SUNRISE_DURATION 1800  // 30 minutes in seconds
#define STEP_DELAY 1           // seconds between steps

static const int relay_pins[NUM_RELAYS] = {17, 18, 27, 22};
static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void log_event(const char *message) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fflush(log_file);
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int setup_gpio(void) {
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (gpioSetMode(relay_pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: Failed to set GPIO %d as output\n", relay_pins[i]);
            return -1;
        }
        if (gpioSetPWMfrequency(relay_pins[i], PWM_FREQUENCY) != 0) {
            fprintf(stderr, "Error: Failed to set PWM frequency on GPIO %d\n", relay_pins[i]);
            return -1;
        }
        if (gpioSetPWMrange(relay_pins[i], PWM_RANGE) != 0) {
            fprintf(stderr, "Error: Failed to set PWM range on GPIO %d\n", relay_pins[i]);
            return -1;
        }
        if (gpioPWM(relay_pins[i], 0) != 0) {
            fprintf(stderr, "Error: Failed to initialize PWM duty cycle on GPIO %d\n", relay_pins[i]);
            return -1;
        }
    }
    return 0;
}

static void sunrise_simulation(void) {
    int step = 0;
    while (running && step < SUNRISE_DURATION) {
        for (int i = 0; i < NUM_RELAYS; i++) {
            if (gpioPWM(relay_pins[i], step) != 0) {
                fprintf(stderr, "Error: Failed to set PWM duty cycle on GPIO %d\n", relay_pins[i]);
                log_event("Error: Failed to set PWM duty cycle");
                return;
            }
        }
        char log_message[128];
        snprintf(log_message, sizeof(log_message), "Sunrise step %d/%d: duty cycle = %d", step + 1, SUNRISE_DURATION, step);
        log_event(log_message);
        step++;
        sleep(STEP_DELAY);
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    log_file = fopen("smart_lighting.log", "a");
    if (!log_file) {
        fprintf(stderr, "Error: Failed to open log file\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_event("Smart Lighting Sunrise Simulation Started");

    if (setup_gpio() != 0) {
        log_event("Error: GPIO setup failed");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: Failed to set signal handlers\n");
        log_event("Error: Failed to set signal handlers");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    sunrise_simulation();

    for (int i = 0; i < NUM_RELAYS; i++) {
        gpioPWM(relay_pins[i], 0);
    }

    log_event("Sunrise Simulation Complete");
    fclose(log_file);
    gpioTerminate();
    return EXIT_SUCCESS;
}

