#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <time.h>
#include <math.h>
#include <pigpio.h>

/* MPU-6050 I2C address (AD0 tied to GND) */
#define MPU6050_ADDR 0x68

/* MPU-6050 registers */
#define MPU6050_SMPLRT_DIV   0x19
#define MPU6050_GYRO_CONFIG  0x1B
#define MPU6050_PWR_MGMT_1   0x6B
#define MPU6050_WHO_AM_I     0x75
#define MPU6050_GYRO_XOUT_H  0x43

/* Expected WHO_AM_I response */
#define MPU6050_WHO_AM_I_RESP 0x68

/* GPIO pin for LED */
#define LED_PIN 17

/* Circular buffer size */
#define BUFFER_SIZE 100

/* Gyroscope threshold (degrees/second) */
#define GYRO_THRESHOLD 250.0f

/* Sensitivity for ±250 deg/s range (131 LSB/deg/s) */
#define GYRO_SENSITIVITY 131.0f

/* I2C bus on Raspberry Pi 3 Model B+ */
#define I2C_BUS 1

/* Maximum re-initialisation attempts */
#define MAX_REINIT_ATTEMPTS 3

/* Sampling period (microseconds) for 20 Hz */
#define SAMPLE_PERIOD_US 50000

typedef struct {
    struct timespec timestamp;
    int16_t gyro_x;
    int16_t gyro_y;
    int16_t gyro_z;
} gyro_data_t;

static gyro_data_t gyro_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_mpu6050(void) {
    int who = i2cReadByteData(i2c_handle, MPU6050_WHO_AM_I);
    if (who < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", who);
        return -1;
    }
    if (who != MPU6050_WHO_AM_I_RESP) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who, MPU6050_WHO_AM_I_RESP);
        return -1;
    }

    /* Wake up the MPU-6050 (clear SLEEP bit) */
    if (i2cWriteByteData(i2c_handle, MPU6050_PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error writing PWR_MGMT_1\n");
        return -1;
    }
    gpioDelay(100000); /* 100 ms settle */

    /* Set sample rate divider to 1 kHz / (1 + 7) = 125 Hz */
    if (i2cWriteByteData(i2c_handle, MPU6050_SMPLRT_DIV, 0x07) < 0) {
        fprintf(stderr, "Error writing SMPLRT_DIV\n");
        return -1;
    }

    /* Gyro full-scale range ±250 deg/s (FS_SEL = 0) */
    if (i2cWriteByteData(i2c_handle, MPU6050_GYRO_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error writing GYRO_CONFIG\n");
        return -1;
    }

    return 0;
}

static int read_gyro_data(float *x, float *y, float *z) {
    char buf[6];
    int16_t raw_x, raw_y, raw_z;

    if (i2cReadI2CBlockData(i2c_handle, MPU6050_GYRO_XOUT_H, buf, 6) != 6) {
        fprintf(stderr, "Error reading gyroscope data block\n");
        return -1;
    }

    raw_x = (int16_t)((buf[0] << 8) | (uint8_t)buf[1]);
    raw_y = (int16_t)((buf[2] << 8) | (uint8_t)buf[3]);
    raw_z = (int16_t)((buf[4] << 8) | (uint8_t)buf[5]);

    *x = (float)raw_x / GYRO_SENSITIVITY;
    *y = (float)raw_y / GYRO_SENSITIVITY;
    *z = (float)raw_z / GYRO_SENSITIVITY;

    return 0;
