static void check_threshold(float x, float y, float z) {
    if (fabsf(x) > GYRO_THRESHOLD ||
        fabsf(y) > GYRO_THRESHOLD ||
        fabsf(z) > GYRO_THRESHOLD) {
        gpioWrite(LED_PIN, 1);
    } else {
        gpioWrite(LED_PIN, 0);
    }
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %d\n",
                I2C_BUS, MPU6050_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_mpu6050() != 0) {
        fprintf(stderr, "MPU-6050 initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    float x, y, z;
    int reinit_attempts = 0;

    while (!terminate) {
        if (read_gyro_data(&x, &y, &z) == 0) {
            add_to_buffer(x, y, z);
            check_threshold(x, y, z);
            reinit_attempts = 0;
        } else {
            fprintf(stderr, "Read failed, re-initialising...\n");
            reinit_attempts++;
            if (reinit_attempts > MAX_REINIT_ATTEMPTS) {
                fprintf(stderr, "Max re-initialisation attempts reached, exiting.\n");
                break;
            }
            i2cClose(i2c_handle);
            i2c_handle = i2cOpen(I2C_BUS, MPU6050_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error re-opening I2C: %d\n", i2c_handle);
                reinit_attempts++;
                continue;
            }
            if (init_mpu6050() != 0) {
                fprintf(stderr, "Re-initialisation failed, retrying...\n");
                reinit_attempts++;
                continue;
            }
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

