        close(g_spi_fd); g_spi_fd = -1; return -1;
    }

    return 0;
}

static int gpio_init(void) {
    g_chip = gpiod_chip_open(GPIO_CHIP);
    if (!g_chip) {
        fprintf(stderr, "Error opening %s: %s\n", GPIO_CHIP, strerror(errno));
        return -1;
    }

    g_cs_line = gpiod_chip_get_line(g_chip, CS_LINE_OFFSET);
    if (!g_cs_line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", CS_LINE_OFFSET, strerror(errno));
        gpiod_chip_close(g_chip); g_chip = NULL; return -1;
    }

    if (gpiod_line_request_output(g_cs_line, "mpu9250-cs", 1) < 0) {
        fprintf(stderr, "Error requesting GPIO line as output: %s\n", strerror(errno));
        gpiod_chip_close(g_chip); g_chip = NULL; g_cs_line = NULL; return -1;
    }

    return 0;
}

static int cs_low(void) {
    if (g_cs_line) {
        if (gpiod_line_set_value(g_cs_line, 0) < 0) {
            fprintf(stderr, "Error asserting CS line: %s\n", strerror(errno));
            return -1;
        }
        return 0;
    }
    return -1;
}

static int cs_high(void) {
    if (g_cs_line) {
        if (gpiod_line_set_value(g_cs_line, 1) < 0) {
            fprintf(stderr, "Error de-asserting CS line: %s\n", strerror(errno));
            return -1;
        }
        return 0;
    }
    return -1;
}

static int spi_transfer(const uint8_t *tx, uint8_t *rx, size_t len) {
    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx;
    tr.rx_buf = (unsigned long)rx;
    tr.len = len;
    tr.speed_hz = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs = 0;

    if (cs_low() < 0) return -1;

    int ret = ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr);
    cs_high();

    if (ret < 0) {
        fprintf(stderr, "SPI transfer error: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_gyro_data(float *x, float *y, float *z) {
    uint8_t tx[6] = {0};
    uint8_t rx[6] = {0};

    if (spi_transfer(tx, rx, sizeof(tx)) < 0) return -1;

    int16_t raw_x = (int16_t)((rx[0] << 8) | rx[1]);
    int16_t raw_y = (int16_t)((rx[2] << 8) | rx[3]);
    int16_t raw_z = (int16_t)((rx[4] << 8) | rx[5]);

    *x = (float)raw_x / GYRO_SCALE;
    *y = (float)raw_y / GYRO_SCALE;
    *z = (float)raw_z / GYRO_SCALE;
    return 0;
}

static int log_data(float x, float y, float z) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) < 0) {
        fprintf(stderr, "Error getting time: %s\n", strerror(errno));
        return -1;
    }

    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    char timestamp[40];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info);
    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%09ldZ", ts.tv_nsec);

    if (fprintf(g_log_fp, "%s,%.2f,%.2f,%.2f\n", timestamp, x, y, z) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(g_log_fp);
    return 0;
}

static void cleanup(void) {
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
    if (g_cs_line) {
        gpiod_line_release(g_cs_line);
        g_cs_line = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting signal handler: %s\n", strerror(errno));
        return 1;
    }

    if (spi_init() < 0) {
        cleanup();
        return 1;
    }

    if (gpio_init() < 0) {
        cleanup();
        return 1;
    }

    g_log_fp = fopen("gyro_log.txt", "a");
    if (!g_log_fp) {
        fprintf(stderr, "Error opening gyro_log.txt: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    fprintf(g_log_fp, "# MPU-9250 Gyro Log - started\n");
    fflush(g_log_fp);

    while (g_running) {
        float x, y, z;
        int success = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && g_running; attempt++) {
            if (read_gyro_data(&x, &y, &z) == 0) {
                success = 1;
                break;
            }
            usleep(1000);
        }

        if (success) {
            if (log_data(x, y, z) < 0) {
                fprintf(stderr, "Logging failed, continuing...\n");
            }
        } else {
            fprintf(stderr, "Gyro read failed after %d attempts, continuing...\n", MAX_RETRIES);
        }

        usleep(SAMPLE_PERIOD_US);
    }

    cleanup();
    return 0;
}

