        return 1;
    }

    if (spi_init() < 0) {
        return 1;
    }

    if (gpio_init() < 0) {
        cleanup();
        return 1;
    }

    printf("MPU-6050 Stability Monitor started. Press Ctrl+C to exit.\n");

    while (program_running) {
        float x, y, z;

        if (read_gyro_axis(GYRO_XOUT_H, &x) < 0 ||
            read_gyro_axis(GYRO_YOUT_H, &y) < 0 ||
            read_gyro_axis(GYRO_ZOUT_H, &z) < 0) {
            fprintf(stderr, "Error reading gyroscope data. Retrying...\n");
            usleep(100000);
