#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

/* MPU-6050 I2C address (AD0 tied to GND) */
#define MPU6050_ADDR 0x68

/* MPU-6050 registers */
#define PWR_MGMT_1   0x6B
#define ACCEL_CONFIG 0x1C
#define ACCEL_XOUT_H 0x3B
#define ACCEL_XOUT_L 0x3C
#define ACCEL_YOUT_H 0x3D
#define ACCEL_YOUT_L 0x3E
#define ACCEL_ZOUT_H 0x3F
#define ACCEL_ZOUT_L 0x40

/* GPIO pin for LED */
#define LED_PIN 21

/* Tilt threshold (degrees) */
#define TILT_THRESHOLD 45.0

/* I2C bus on Raspberry Pi 4 */
#define I2C_BUS 1

/* Global state for signal handler */
static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/* Initialize MPU-6050: wake up and set accelerometer range to ±2g */
static int init_mpu6050(int handle) {
    /* Wake up the MPU-6050 (clear sleep bit) */
    if (i2cWriteByteData(handle, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write PWR_MGMT_1 (0x6B)\n");
        return -1;
    }
    gpioDelay(100000); /* 100 ms settling time */

    /* Set accelerometer range to ±2g (AFS_SEL = 0) */
    if (i2cWriteByteData(handle, ACCEL_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write ACCEL_CONFIG (0x1C)\n");
        return -1;
    }
    return 0;
}

/* Read 6 bytes of accelerometer data starting at ACCEL_XOUT_H */
static int read_accelerometer(int handle, int16_t *x, int16_t *y, int16_t *z) {
    char buf[6];
    int rc = i2cReadI2CBlockData(handle, ACCEL_XOUT_H, buf, 6);
    if (rc != 6) {
        fprintf(stderr, "Error: Failed to read accelerometer data (rc=%d)\n", rc);
        return -1;
    }
    *x = (int16_t)((buf[0] << 8) | (uint8_t)buf[1]);
    *y = (int16_t)((buf[2] << 8) | (uint8_t)buf[3]);
    *z = (int16_t)((buf[4] << 8) | (uint8_t)buf[5]);
    return 0;
}

/* Calculate roll and pitch from raw accelerometer data */
static void calculate_tilt(int16_t x, int16_t y, int16_t z, float *roll, float *pitch) {
    *roll = atan2((float)y, (float)z) * 180.0 / M_PI;
    *pitch = atan2(-(float)x, sqrt((float)y * y + (float)z * z)) * 180.0 / M_PI;
}

/* Log data to file in CSV format */
static void log_data(float roll, float pitch) {
    FILE *fp = fopen("tilt_log.txt", "a");
    if (!fp) {
