    while (running) {
        int16_t x, y, z;
        if (read_accelerometer(i2c_handle, &x, &y, &z) == 0) {
            float roll, pitch;
            calculate_tilt(x, y, z, &roll, &pitch);
            log_data(roll, pitch);

            if (fabs(roll) > TILT_THRESHOLD || fabs(pitch) > TILT_THRESHOLD) {
