#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define SI1145_ADDR    0x5A
#define REG_ALS_VIS    0x20
#define REG_PS1        0x22
#define REG_PS_LED21   0x81
#define PROX_THRESHOLD 100
#define GPIO_CHIP      "gpiochip0"
#define GPIO_LINE      17
#define LOG_FILE       "biometric_log.txt"
#define POLL_MS        100
#define I2C_RETRIES    3
#define I2C_RETRY_DELAY_MS 10

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_fp = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *led_line = NULL;

static void handle_signal(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    for (int attempt = 0; attempt < I2C_RETRIES; attempt++) {
        if (write(fd, buf, 2) == 2) return 0;
        fprintf(stderr, "I2C write reg 0x%02X failed (attempt %d): %s\n",
                reg, attempt + 1, strerror(errno));
        if (attempt < I2C_RETRIES - 1) usleep(I2C_RETRY_DELAY_MS * 1000);
    }
    return -1;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out) {
    for (int attempt = 0; attempt < I2C_RETRIES; attempt++) {
        if (write(fd, &reg, 1) != 1) {
            fprintf(stderr, "I2C write reg 0x%02X failed (attempt %d): %s\n",
                    reg, attempt + 1, strerror(errno));
            if (attempt < I2C_RETRIES - 1) usleep(I2C_RETRY_DELAY_MS * 1000);
            continue;
        }
        uint8_t buf[2];
        if (read(fd, buf, 2) != 2) {
            fprintf(stderr, "I2C read reg 0x%02X failed (attempt %d): %s\n",
                    reg, attempt + 1, strerror(errno));
            if (attempt < I2C_RETRIES - 1) usleep(I2C_RETRY_DELAY_MS * 1000);
            continue;
        }
        *out = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
        return 0;
    }
    return -1;
}

static void cleanup(void) {
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
        led_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (log_fp) {
        fclose(log_fp);
        log_fp = NULL;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("open " I2C_BUS);
        return EXIT_FAILURE;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, SI1145_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        cleanup();
        return EXIT_FAILURE;
    }

    if (i2c_write_reg8(i2c_fd, REG_PS_LED21, 0x0F) < 0) {
        fprintf(stderr, "Failed to configure PS LED drive\n");
        cleanup();
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        cleanup();
        return EXIT_FAILURE;
    }
    led_line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!led_line) {
        perror("gpiod_chip_get_line");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_output(led_line, "si1145-presence", 0) < 0) {
        perror("gpiod_line_request_output");
        cleanup();
        return EXIT_FAILURE;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        perror("fopen " LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    while (running) {
        uint16_t als = 0, prox = 0;
        if (i2c_read_reg16(i2c_fd, REG_ALS_VIS, &als) < 0 ||
            i2c_read_reg16(i2c_fd, REG_PS1, &prox) < 0) {
            fprintf(stderr, "Sensor read failed; continuing\n");
            usleep(POLL_MS * 1000);
            continue;
        }

        time_t now = time(NULL);
        struct tm tm_buf;
        struct tm *t = localtime_r(&now, &tm_buf);
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

        fprintf(log_fp, "%s,AmbientLight:%u,Proximity:%u\n", ts, als, prox);
        fflush(log_fp);

        int led_val = (prox > PROX_THRESHOLD) ? 1 : 0;
        if (gpiod_line_set_value(led_line, led_val) < 0) {
            perror("gpiod_line_set_value");
        }

        usleep(POLL_MS * 1000);
    }

    cleanup();
    return EXIT_SUCCESS;
}

