#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define GYRO_X_REG 0x02
#define GYRO_Y_REG 0x04
#define SENSITIVITY 200.0f
#define SAMPLE_DELAY_US 10000
#define MAX_REINIT_ATTEMPTS 3

static int spi_handle = -1;
static FILE *data_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int spi_init(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, (SPI_MODE & 3));
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI channel %d: %s\n", SPI_CHANNEL, pigpio_error(spi_handle));
        return -1;
    }
    return 0;
}

static int read_gyro_axis(int reg, int16_t *out) {
    char tx[2] = { (char)(reg | 0x80), 0x00 };
    char rx[2] = { 0, 0 };
    int ret = spiXfer(spi_handle, tx, rx, 2);
    if (ret != 2) {
        fprintf(stderr, "SPI transfer failed for reg 0x%02X: %s\n", reg, pigpio_error(ret));
        return -1;
    }
    *out = (int16_t)(((uint8_t)rx[0] << 8) | (uint8_t)rx[1]);
    return 0;
}

static int read_gyro_data(float *x_rate, float *y_rate) {
    int16_t raw_x, raw_y;
    if (read_gyro_axis(GYRO_X_REG, &raw_x) != 0) return -1;
    if (read_gyro_axis(GYRO_Y_REG, &raw_y) != 0) return -1;
    *x_rate = (float)raw_x / SENSITIVITY;
    *y_rate = (float)raw_y / SENSITIVITY;
    return 0;
}

static int log_data(float x_rate, float y_rate) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        fprintf(stderr, "clock_gettime failed: %s\n", strerror(errno));
        return -1;
    }
    double timestamp = (double)ts.tv_sec + (double)ts.tv_nsec / 1e9;
    if (fprintf(data_file, "%.6f,%.2f,%.2f\n", timestamp, x_rate, y_rate) < 0) {
        fprintf(stderr, "fprintf to file failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(data_file) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (spi_init() != 0) {
        gpioTerminate();
        return 1;
    }

    data_file = fopen("gyro_data.csv", "a");
    if (!data_file) {
        fprintf(stderr, "Error opening gyro_data.csv: %s\n", strerror(errno));
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    fseek(data_file, 0, SEEK_END);
    if (ftell(data_file) == 0) {
        fprintf(data_file, "timestamp,x_rate_deg_s,y_rate_deg_s\n");
        fflush(data_file);
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        fclose(data_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    printf("Gyroscope data logging started. Press Ctrl+C to stop.\n");

