#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SENSOR_1_PIN 23
#define SENSOR_2_PIN 24
#define ALERT_PIN 17
#define SEISMIC_THRESHOLD_MS 500
#define ALERT_DURATION_US 2000000
#define POLL_DELAY_US 100000

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *message) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s - %s\n", timestamp, message);
    fflush(log_file);
}

static void sensor_callback(int gpio, int level, uint32_t tick) {
    static uint32_t last_rising_tick_1 = 0;
    static uint32_t last_rising_tick_2 = 0;
    static int tilted_1 = 0;
    static int tilted_2 = 0;
    uint32_t now = tick;

    if (gpio == SENSOR_1_PIN) {
        if (level == 1) {
            if (!tilted_1) {
                last_rising_tick_1 = now;
                tilted_1 = 1;
            }
        } else {
            tilted_1 = 0;
        }
    } else if (gpio == SENSOR_2_PIN) {
        if (level == 1) {
            if (!tilted_2) {
                last_rising_tick_2 = now;
                tilted_2 = 1;
            }
        } else {
            tilted_2 = 0;
        }
    }

    if (tilted_1 && tilted_2) {
        uint32_t diff = now - last_rising_tick_1;
        if (diff >= SEISMIC_THRESHOLD_MS * 1000) {
            log_event("Seismic event detected!");
            if (gpioWrite(ALERT_PIN, 1) < 0) {
                fprintf(stderr, "Failed to set alert pin HIGH\n");
            }
            gpioDelay(ALERT_DURATION_US);
            if (gpioWrite(ALERT_PIN, 0) < 0) {
                fprintf(stderr, "Failed to set alert pin LOW\n");
            }
            tilted_1 = 0;
            tilted_2 = 0;
        }
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    log_file = fopen("seismic_events.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) < 0 ||
        gpioSetMode(SENSOR_2_PIN, PI_INPUT) < 0 ||
        gpioSetMode(ALERT_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(SENSOR_1_PIN, PI_PUD_DOWN) < 0 ||
        gpioSetPullUpDown(SENSOR_2_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Failed to set pull-down resistors\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetAlertFuncEx(SENSOR_1_PIN, sensor_callback, NULL) < 0 ||
        gpioSetAlertFuncEx(SENSOR_2_PIN, sensor_callback, NULL) < 0) {
        fprintf(stderr, "Failed to register alert callbacks\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install signal handlers: %s\n", strerror(errno));
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Seismic monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    gpioWrite(ALERT_PIN, 0);
    gpioSetAlertFuncEx(SENSOR_1_PIN, NULL, NULL);
    gpioSetAlertFuncEx(SENSOR_2_PIN, NULL, NULL);
    fclose(log_file);
    gpioTerminate();
    return EXIT_SUCCESS;
}

