#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <math.h>
#include <string.h>

/* ADXRS290 register addresses */
#define ADXRS290_REG_RATE_XL  0x02
#define ADXRS290_REG_RATE_XH  0x03

/* SPI configuration */
#define SPI_CHANNEL 0
#define SPI_SPEED   1000000  /* 1 MHz */
#define SPI_FLAGS   0        /* mode 0, active-low CE */

/* Gyroscope sensitivity: 200 LSB/deg/s */
#define GYRO_SENSITIVITY 200.0f

/* Angular velocity threshold (degrees per second) */
#define ANGULAR_VELOCITY_THRESHOLD 20.0f

/* LED GPIO pin */
#define LED_PIN 17

/* Circular buffer capacity */
#define BUFFER_SIZE 100

/* Structure to hold timestamp and angular velocity */
typedef struct {
    struct timespec timestamp;
    float angular_velocity;
} GyroData;

/* Circular buffer */
static GyroData gyro_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;

/* Global SPI handle */
static int spi_handle = -1;

/* Flag to indicate program termination */
static volatile sig_atomic_t terminate = 0;

/* Signal handler for graceful shutdown */
static void signal_handler(int signal) {
    (void)signal;
    terminate = 1;
}

/* Initialize pigpio and configure LED pin */
static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set LED pin %d as output\n", LED_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioWrite(LED_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialize LED pin %d to LOW\n", LED_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

/* Initialize SPI0 CE0 at 1 MHz, mode 0 */
static int initialize_spi(void) {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (pigpio error %d)\n", spi_handle);
        return -1;
    }
    return 0;
}

/* Read 16-bit two's-complement angular rate from ADXRS290 */
static int read_gyro_rate(float *angular_velocity) {
    char tx_buf[2];
    char rx_buf[2];
    int16_t raw_rate;

    /* Set MSB of register address to 1 for read */
    tx_buf[0] = (char)(ADXRS290_REG_RATE_XL | 0x80);
    tx_buf[1] = 0x00;

    if (spiXfer(spi_handle, tx_buf, rx_buf, 2) != 2) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    raw_rate = (int16_t)(((uint16_t)(uint8_t)rx_buf[0] << 8) |
                         (uint16_t)(uint8_t)rx_buf[1]);

    *angular_velocity = (float)raw_rate / GYRO_SENSITIVITY;
    return 0;
}

/* Add timestamped data to circular buffer */
static void add_to_buffer(float angular_velocity) {
    clock_gettime(CLOCK_MONOTONIC, &gyro_buffer[buffer_index].timestamp);
    gyro_buffer[buffer_index].angular_velocity = angular_velocity;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) {
        buffer_count++;
    }
}

/* Check angular velocity against threshold and control LED */
static void check_threshold(float angular_velocity) {
    if (fabsf(angular_velocity) > ANGULAR_VELOCITY_THRESHOLD) {
        gpioWrite(LED_PIN, 1);
    } else {
        gpioWrite(LED_PIN, 0);
    }
}

/* Cleanup resources */
static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    if (initialize_gpio() != 0) {
        return 1;
    }

    if (initialize_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    printf("ADXRS290 Gyroscope Monitoring Started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        float angular_velocity;

        if (read_gyro_rate(&angular_velocity) == 0) {
            add_to_buffer(angular_velocity);
            check_threshold(angular_velocity);
            printf("Angular Velocity: %.2f deg/s\n", angular_velocity);
        } else {
            fprintf(stderr, "Error: failed to read gyroscope data\n");
        }

        gpioDelay(100000); /* 100 ms */
    }

    cleanup();
    printf("Program terminated gracefully.\n");
    return 0;
}

