                         (uint16_t)(uint8_t)rx_buf[1]);

    *angular_velocity = (float)raw_rate / GYRO_SENSITIVITY;
    return 0;
}

/* Add timestamped data to circular buffer */
static void add_to_buffer(float angular_velocity) {
    clock_gettime(CLOCK_MONOTONIC, &gyro_buffer[buffer_index].timestamp);
    gyro_buffer[buffer_index].angular_velocity = angular_velocity;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) {
        buffer_count++;
    }
}

/* Check angular velocity against threshold and control LED */
static void check_threshold(float angular_velocity) {
    if (fabsf(angular_velocity) > ANGULAR_VELOCITY_THRESHOLD) {
        gpioWrite(LED_PIN, 1);
    } else {
        gpioWrite(LED_PIN, 0);
    }
}

/* Cleanup resources */
static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    if (initialize_gpio() != 0) {
        return 1;
    }

    if (initialize_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    printf("ADXRS290 Gyroscope Monitoring Started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        float angular_velocity;

        if (read_gyro_rate(&angular_velocity) == 0) {
            add_to_buffer(angular_velocity);
            check_threshold(angular_velocity);
            printf("Angular Velocity: %.2f deg/s\n", angular_velocity);
        } else {
            fprintf(stderr, "Error: failed to read gyroscope data\n");
        }

        gpioDelay(100000); /* 100 ms */
    }

    cleanup();
    printf("Program terminated gracefully.\n");
    return 0;
}

