#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LAMP1_PIN 17
#define LAMP2_PIN 18
#define LAMP3_PIN 27
#define PWM_RANGE 255
#define PWM_FREQ 100
#define FADE_DURATION 5  /* seconds */

static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int set_lamp(int pin, int brightness) {
    if (gpioPWM(pin, brightness) != 0) {
        fprintf(stderr, "Error: gpioPWM failed on pin %d\n", pin);
        return -1;
    }
    printf("Lamp on GPIO%d set to %d%% brightness\n", pin, brightness);
    return 0;
}

static int fade_lamp(int pin, int duration) {
    int step = (PWM_RANGE * 100) / (2 * duration);
    if (step < 1) step = 1;

    for (int i = 0; i < duration * 2 && !terminate; i++) {
        int brightness = (i < duration) ? (PWM_RANGE - step * i) : 0;
        if (set_lamp(pin, brightness) != 0) return -1;
        gpioDelay(1000000 / (2 * duration)); /* 500 ms per step */
    }
    return 0;
}

static int run_fade_sequence(int duration) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(LAMP1_PIN, PI_OUTPUT);
    gpioSetMode(LAMP2_PIN, PI_OUTPUT);
    gpioSetMode(LAMP3_PIN, PI_OUTPUT);

    if (gpioSetPWMrange(LAMP1_PIN, PWM_RANGE) != 0 ||
        gpioSetPWMrange(LAMP2_PIN, PWM_RANGE) != 0 ||
        gpioSetPWMrange(LAMP3_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: gpioSetPWMrange failed\n");
        gpioTerminate();
        return -1;
    }

    if (gpioSetPWMfrequency(LAMP1_PIN, PWM_FREQ) != 0 ||
        gpioSetPWMfrequency(LAMP2_PIN, PWM_FREQ) != 0 ||
        gpioSetPWMfrequency(LAMP3_PIN, PWM_FREQ) != 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency failed\n");
        gpioTerminate();
        return -1;
    }

    printf("Smart Sunset Simulator started. Fading for %d seconds...\n", duration);

    if (fade_lamp(LAMP1_PIN, duration) != 0) {
        gpioTerminate();
        return -1;
    }
    if (terminate) goto cleanup;

    if (fade_lamp(LAMP2_PIN, duration) != 0) {
        gpioTerminate();
        return -1;
    }
    if (terminate) goto cleanup;

    if (fade_lamp(LAMP3_PIN, duration) != 0) {
        gpioTerminate();
        return -1;
    }

cleanup:
    printf("Smart Sunset Simulator terminated.\n");
    gpioTerminate();
    return 0;
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <fade_duration_seconds>\n", argv[0]);
        return EXIT_FAILURE;
    }

    char *endptr;
    long duration = strtol(argv[1], &endptr, 10);
    if (*endptr != '\0' || duration < 1 || duration > 3600) {
        fprintf(stderr, "Error: fade duration must be 1-3600 seconds\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    return run_fade_sequence((int)duration);
}

