#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define CHIP_NAME "gpiochip4"
#define RED_PIN   17
#define YELLOW_PIN 22
#define GREEN_PIN  23
#define RED_ON    0
#define RED_OFF   1
#define YELLOW_ON 0
#define YELLOW_OFF 1
#define GREEN_ON  0
#define GREEN_OFF 1

static volatile sig_atomic_t running = 1;

static void sighandler(int sig) {
    (void)sig;
    running = 0;
}

static int set_state(struct gpiod_line *line, int val) {
    int ret = gpiod_line_set_value(line, val);
    if (ret < 0) {
        perror("gpiod_line_set_value");
        return -1;
    }
    return 0;
}

static void sleep_seconds(int seconds) {
    while (seconds > 0 && running) {
        sleep(1);
        seconds--;
    }
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[4] = {NULL, NULL, NULL, NULL};
    int pins[4] = {RED_PIN, YELLOW_PIN, GREEN_PIN, YELLOW_PIN};
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < 4; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "gpiod_chip_get_line failed for pin %d\n", pins[i]);
            goto cleanup;
        }
        if (gpiod_line_request_output(lines[i], "traffic-light", 1) < 0) {
            fprintf(stderr, "gpiod_line_request_output failed for pin %d\n", pins[i]);
            goto cleanup;
        }
    }

    printf("Traffic light simulation started. Press Ctrl+C to exit.\n");

    while (running) {
        if (set_state(lines[0], RED_ON) < 0) goto cleanup;
        printf("Red ON\n");
        sleep_seconds(10);

        if (!running) break;

        if (set_state(lines[0], RED_OFF) < 0) goto cleanup;
        if (set_state(lines[1], YELLOW_ON) < 0) goto cleanup;
        printf("Red OFF, Yellow ON\n");
        sleep_seconds(2);

        if (!running) break;

        if (set_state(lines[1], YELLOW_OFF) < 0) goto cleanup;
        if (set_state(lines[2], GREEN_ON) < 0) goto cleanup;
        printf("Yellow OFF, Green ON\n");
        sleep_seconds(10);

        if (!running) break;

        if (set_state(lines[2], GREEN_OFF) < 0) goto cleanup;
        if (set_state(lines[3], YELLOW_ON) < 0) goto cleanup;
        printf("Green OFF, Yellow ON\n");
        sleep_seconds(3);
    }

    ret = EXIT_SUCCESS;

cleanup:
    for (int i = 0; i < 4; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

