#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define RELAY_GPIO 17
#define MPR121_ADDR 0x5A
#define I2C_BUS 1
#define LOG_FILE "touch_relay.log"

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static int i2c_handle = -1;

static void log_message(const char *message) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fflush(log_file);
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int mpr121_write_reg(int handle, uint8_t reg, uint8_t value) {
    char buf[2] = {(char)reg, (char)value};
    if (i2cWriteDevice(handle, buf, 2) != 0) {
        log_message("Error: I2C write failed for MPR121 register");
        return -1;
    }
    return 0;
}

static int mpr121_init(int handle) {
    if (mpr121_write_reg(handle, 0x80, 0x63) != 0) return -1;  // Reset
    gpioDelay(1000);
    if (mpr121_write_reg(handle, 0x5E, 0x00) != 0) return -1;  // Stop mode
    if (mpr121_write_reg(handle, 0x5D, 0x01) != 0) return -1;  // Enable electrode 0
    if (mpr121_write_reg(handle, 0x41, 0x0A) != 0) return -1;  // Touch threshold
    if (mpr121_write_reg(handle, 0x42, 0x08) != 0) return -1;  // Release threshold
    if (mpr121_write_reg(handle, 0x5B, 0x21) != 0) return -1;  // Debounce
    if (mpr121_write_reg(handle, 0x5C, 0x0D) != 0) return -1;  // Charge time
    if (mpr121_write_reg(handle, 0x5E, 0x0D) != 0) return -1;  // Run mode
    return 0;
}

static int read_mpr121_touch(int handle) {
    char buf[2];
    if (i2cReadDevice(handle, buf, 2) != 2) {
        log_message("Error: I2C read failed for MPR121 touch status");
        return -1;
    }
    return ((uint8_t)buf[1] << 8) | (uint8_t)buf[0];
}

static void control_relay(int gpio, int state) {
    if (gpioWrite(gpio, state) != 0) {
        log_message("Error: Failed to write GPIO state");
    }
}

int main(void) {
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        return 1;
    }

    if (gpioInitialise() < 0) {
        log_message("Error: pigpio initialisation failed");
        fclose(log_file);
        return 1;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        log_message("Error: Failed to set GPIO mode");
        gpioTerminate();
        fclose(log_file);
        return 1;
    }
    gpioWrite(RELAY_GPIO, 0);

    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        log_message("Error: Failed to open I2C device");
        gpioTerminate();
        fclose(log_file);
        return 1;
    }

    if (mpr121_init(i2c_handle) != 0) {
        log_message("Error: MPR121 initialisation failed");
        i2cClose(i2c_handle);
        gpioTerminate();
        fclose(log_file);
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_message("Program started");

    int relay_state = 0;
    while (running) {
        int touch = read_mpr121_touch(i2c_handle);
        if (touch < 0) {
            gpioDelay(10000);
            continue;
        }
        if (touch & 0x01) {
            relay_state = !relay_state;
            control_relay(RELAY_GPIO, relay_state);
            log_message("Touch detected, toggling relay");
            gpioDelay(100000);
        }
        gpioDelay(10000);
    }

    log_message("Program exiting");
    gpioWrite(RELAY_GPIO, 0);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    fclose(log_file);
    return 0;
}

