    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_message("Program started");

    int relay_state = 0;
    while (running) {
        int touch = read_mpr121_touch(i2c_handle);
        if (touch < 0) {
            gpioDelay(10000);
            continue;
        }
        if (touch & 0x01) {
            relay_state = !relay_state;
            control_relay(RELAY_GPIO, relay_state);
            log_message("Touch detected, toggling relay");
            gpioDelay(100000);
        }
        gpioDelay(10000);
    }

    log_message("Program exiting");
    gpioWrite(RELAY_GPIO, 0);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    fclose(log_file);
    return 0;
}

