#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>

#define MOTOR_A_FORWARD 17
#define MOTOR_A_BACKWARD 18
#define MOTOR_B_FORWARD 22
#define MOTOR_B_BACKWARD 23
#define MOTOR_A_ENABLE 24
#define MOTOR_B_ENABLE 25

#define TILT_ERROR_MIN -10.0
#define TILT_ERROR_MAX 10.0
#define DISTANCE_MIN 2.0
#define DISTANCE_MAX 400.0
#define DISTANCE_THRESHOLD 20.0
#define PWM_RANGE 255
#define LOOP_DELAY_MS 50

static volatile int running = 1;
static FILE *log_file = NULL;

typedef struct {
    float Kp;
    float Ki;
    float Kd;
    float integral;
    float previous_error;
} PIDController;

static PIDController pid = {1.0, 0.01, 0.1, 0.0, 0.0};

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_motor_speed(int motor, int speed) {
    if (speed > PWM_RANGE) speed = PWM_RANGE;
    if (speed < -PWM_RANGE) speed = -PWM_RANGE;
    int enable_pin = (motor == 0) ? MOTOR_A_ENABLE : MOTOR_B_ENABLE;
    int forward_pin = (motor == 0) ? MOTOR_A_FORWARD : MOTOR_B_FORWARD;
    int backward_pin = (motor == 0) ? MOTOR_A_BACKWARD : MOTOR_B_BACKWARD;
    if (gpioPWM(enable_pin, 1) < 0) return -1;
    if (gpioPWM(enable_pin, 0) < 0) return -1;
    if (speed > 0) {
        if (gpioPWM(forward_pin, speed) < 0) return -1;
        if (gpioPWM(backward_pin, 0) < 0) return -1;
    } else if (speed < 0) {
        if (gpioPWM(forward_pin, 0) < 0) return -1;
        if (gpioPWM(backward_pin, -speed) < 0) return -1;
    } else {
        if (gpioPWM(forward_pin, 0) < 0) return -1;
        if (gpioPWM(backward_pin, 0) < 0) return -1;
    }
    return 0;
}

static void stop_motors(void) {
    set_motor_speed(0, 0);
    set_motor_speed(1, 0);
}

static void log_data(float tilt_error, float distance, int motor_a_speed, int motor_b_speed) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(log_file, "%s,%.2f,%.2f,%d,%d\n", timestamp, tilt_error, distance, motor_a_speed, motor_b_speed);
    fflush(log_file);
}

static void log_error(const char *message) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(log_file, "%s,ERROR,%s\n", timestamp, message);
    fflush(log_file);
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    if (gpioSetMode(MOTOR_A_FORWARD, PI_OUTPUT) < 0) return -1;
    if (gpioSetMode(MOTOR_A_BACKWARD, PI_OUTPUT) < 0) return -1;
    if (gpioSetMode(MOTOR_B_FORWARD, PI_OUTPUT) < 0) return -1;
    if (gpioSetMode(MOTOR_B_BACKWARD, PI_OUTPUT) < 0) return -1;
    if (gpioSetMode(MOTOR_A_ENABLE, PI_OUTPUT) < 0) return -1;
    if (gpioSetMode(MOTOR_B_ENABLE, PI_OUTPUT) < 0) return -1;
    if (gpioSetPWMrange(MOTOR_A_ENABLE, PWM_RANGE) < 0) return -1;
    if (gpioSetPWMrange(MOTOR_B_ENABLE, PWM_RANGE) < 0) return -1;
    if (gpioSetPWMrange(MOTOR_A_FORWARD, PWM_RANGE) < 0) return -1;
    if (gpioSetPWMrange(MOTOR_B_FORWARD, PWM_RANGE) < 0) return -1;
    if (gpioSetPWMrange(MOTOR_B_BACKWARD, PWM_RANGE) < 0) return -1;
    return 0;
}

static void cleanup(void) {
    stop_motors();
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (initialize_gpio() != 0) {
        return 1;
    }
    log_file = fopen("balance_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file\n");
        gpioTerminate();
        return 1;
    }
    signal(SIGINT, signal_handler);
