    while (running) {
        float tilt_error = (float)(rand() % (int)(TILT_ERROR_MAX * 2 + 1) - TILT_ERROR_MAX) / 10.0;
        float distance = (float)(rand() % (int)(DISTANCE_MAX * 2 + 1) - DISTANCE_MIN) / 10.0 + DISTANCE_MIN;
        float pid_output = pid.Kp * tilt_error + pid.integral + pid.Kd * (tilt_error - pid.previous_error);
        pid.integral += tilt_error;
        pid.previous_error = tilt_error;
        if (pid_output > PWM_RANGE) pid_output = PWM_RANGE;
        if (pid_output < -PWM_RANGE) pid_output = -PWM_RANGE;
        int motor_a_speed = (int)pid_output;
        int motor_b_speed = (int)pid_output;
        if (distance < DISTANCE_THRESHOLD) {
            motor_a_speed = -128;
            motor_b_speed = -128;
        }
        if (set_motor_speed(0, motor_a_speed) != 0) {
            log_error("Failed to set motor A speed");
