#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17
#define DEBOUNCE_DELAY_US 50000  /* 50 ms */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (code %d).\n", gpioInitialise());
        return EXIT_FAILURE;
    }

    /* Configure touch sensor pin as input with pull-down (TTP223 output is open-drain-like; pull-down ensures defined LOW when not touched) */
    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", TOUCH_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(TOUCH_SENSOR_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Error: failed to set pull-down on GPIO%d.\n", TOUCH_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure relay pin as output and ensure it starts OFF (LOW) */
    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", RELAY_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(RELAY_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise GPIO%d LOW.\n", RELAY_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Smart Light Switch ready. Touch the TTP223 sensor on GPIO%d to toggle the relay on GPIO%d.\n", TOUCH_SENSOR_PIN, RELAY_PIN);
    printf("Press Ctrl+C to exit.\n");

    int relay_state = 0;  /* 0 = OFF, 1 = ON */

    while (running) {
        int touch_detected = gpioRead(TOUCH_SENSOR_PIN);
        if (touch_detected < 0) {
            fprintf(stderr, "Error: failed to read GPIO%d.\n", TOUCH_SENSOR_PIN);
            break;
        }

        if (touch_detected == 1) {
            /* Debounce: wait before re-reading to avoid multiple triggers */
            gpioDelay(DEBOUNCE_DELAY_US);
            int confirm = gpioRead(TOUCH_SENSOR_PIN);
            if (confirm < 0) {
                fprintf(stderr, "Error: failed to read GPIO%d during debounce.\n", TOUCH_SENSOR_PIN);
                break;
            }
            if (confirm == 1) {
                relay_state = !relay_state;
                if (gpioWrite(RELAY_PIN, relay_state) != 0) {
                    fprintf(stderr, "Error: failed to write GPIO%d.\n", RELAY_PIN);
                    break;
                }
                printf("Relay toggled to %s.\n", relay_state ? "ON" : "OFF");
            }
        }

        gpioDelay(10000);  /* 10 ms poll interval */
    }

    /* Clean shutdown: ensure relay is OFF, then terminate pigpio */
    gpioWrite(RELAY_PIN, 0);
    gpioTerminate();
    printf("\nSmart Light Switch terminated cleanly.\n");
    return EXIT_SUCCESS;
}

