    if (gpioPWM(RED_PIN,   r) < 0) return -1;
    if (gpioPWM(GREEN_PIN, g) < 0) return -1;
    if (gpioPWM(BLUE_PIN,  b) < 0) return -1;
    return 0;
}

/* ---- ALSA capture context ---- */
static snd_pcm_t *capture_ctx = NULL;

/* ---- Cleanup helper ---- */
static void cleanup(void)
{
    if (capture_ctx) {
        snd_pcm_drain(capture_ctx);
        snd_pcm_close(capture_ctx);
        capture_ctx = NULL;
    }
    gpioTerminate();
}

/* ---- Main ---- */
int main(int argc, char *argv[])
{
    float sensitivity = g_config.sensitivity;

    if (argc > 1) {
        char *endptr = NULL;
        sensitivity = strtof(argv[1], &endptr);
        if (endptr == argv[1] || *endptr != '\0' || sensitivity <= 0.0f) {
            fprintf(stderr, "Error: invalid sensitivity '%s'.\n", argv[1]);
            return EXIT_FAILURE;
        }
        g_config.sensitivity = sensitivity;
    }

    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* ---- GPIO setup ---- */
    if (gpioSetMode(RED_PIN,   PI_OUTPUT) < 0 ||
        gpioSetMode(GREEN_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(BLUE_PIN,  PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO modes.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Start with LED off */
    if (set_rgb_color(0, 0, 0) < 0) {
        fprintf(stderr, "Error: failed to initialise PWM on GPIO pins.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- ALSA init (try to open default capture device) ---- */
    int alsa_available = 0;
    snd_pcm_stream_t stream_type = SND_PCM_STREAM_CAPTURE;

    if (snd_pcm_open(&capture_ctx, "default", stream_type, 0) != 0) {
        fprintf(stderr, "Warning: ALSA capture device unavailable "
                        "(%s). Simulating audio input.\n",
                        snd_strerror(snd_pcm_open(&capture_ctx, "default",
                                                   stream_type, 0)));
        alsa_available = 0;
    } else {
        alsa_available = 1;
        if (snd_pcm_prepare(capture_ctx) != 0) {
            fprintf(stderr, "Warning: ALSA capture device not prepared "
                            "(%s). Continuing with simulation.\n",
                            snd_strerror(snd_pcm_prepare(capture_ctx)));
            alsa_available = 0;
        }
    }

    /* ---- Signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Main loop ---- */
    while (g_running) {
        char buf[DEFAULT_PERIOD_SIZE * 2];
        int frames_read = 0;

        if (alsa_available) {
            frames_read = snd_pcm_readi(capture_ctx, buf, DEFAULT_PERIOD_SIZE);
        } else {
            /* Simulate: sine wave with amplitude 32768 (max 16-bit signed) */
            float amplitude = 32768.0f;
            float t = 0.0f;
            int r, g, b;
            map_amplitude_to_color(amplitude, sensitivity, &r, &g, &b);
            if (set_rgb_color(r, g, b) < 0) {
                fprintf(stderr, "Error: gpioPWM write failed.\n");
                break;
            }
            t += 0.01f;
            if (t > 2.0f) t = 0.0f;
            /* Sine wave for simulated audio */
            r = (int)(32768.0f * sinf(M_PI * t));
            g = (int)(32768.0f * sinf(M_PI * (t + 2.0f / 3.0f)));
            b = (int)(32768.0f * sinf(M_PI * (t + 4.0f / 3.0f)));
            if (set_rgb_color(r, g, b) < 0) {
                fprintf(stderr, "Error: gpioPWM write failed.\n");
                break;
            }
        }

        if (frames_read < 0) {
            if (frames_read == -EPIPE) {
                fprintf(stderr, "Warning: buffer overrun, recovering...\n");
                if (snd_pcm_recover(capture_ctx, frames_read, 0) != 0) {
                    fprintf(stderr, "Error: ALSA recover failed.\n");
                    break;
                }
            } else if (frames_read == -EINTR) {
                continue;
            } else {
                fprintf(stderr, "Error: ALSA read failed (%s).\n",
                        snd_strerror(frames_read));
                break;
            }
        }

        if (frames_read < DEFAULT_PERIOD_SIZE) {
            /* Partial period — keep running */
            usleep(UPDATE_DELAY_US);
            continue;
        }

        /* Drain any remaining samples in the buffer */
        while (snd_pcm_drain(capture_ctx) != 0) {
            if (g_running == 0) break;
            usleep(1000);
        }
    }

    /* ---- Graceful shutdown ---- */
    set_rgb_color(0, 0, 0);
    cleanup();
    return EXIT_SUCCESS;
}

