#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

/* TCS34725 I2C address (default) */
#define TCS34725_ADDR 0x29

/* TCS34725 register addresses */
#define TCS34725_ENABLE  0x80
#define TCS34725_ATIME   0x81
#define TCS34725_CDATA   0x14
#define TCS34725_RDATA   0x16
#define TCS34725_GDATA   0x18
#define TCS34725_BDATA   0x1A

/* Enable register bits */
#define TCS34725_ENABLE_PON  0x01
#define TCS34725_ENABLE_AEN  0x02

/* Integration time: 154 ms (0xD5) */
#define TCS34725_ATIME_154MS 0xD5

/* Global resources for signal handler cleanup */
static int i2c_handle = -1;
static FILE *fp = NULL;
static volatile sig_atomic_t terminate = 0;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* Write a single byte to a TCS34725 register; returns 0 on success, -1 on error */
static int tcs34725_write_reg(uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(i2c_handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing 0x%02X to register 0x%02X: pigpio error %d\n",
                value, reg, rc);
        return -1;
    }
    return 0;
}

/* Read a single byte from a TCS34725 register; returns 0 on success, -1 on error */
static int tcs34725_read_reg(uint8_t reg, uint8_t *value) {
    int rc = i2cReadByteData(i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading register 0x%02X: pigpio error %d\n", reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

/* Read four bytes starting at the clear data register (0x14) into a 4-byte buffer */
static int tcs34725_read_rgbc(uint16_t *c, uint16_t *r, uint16_t *g, uint16_t *b) {
    uint8_t buf[4];
    int rc = i2cReadI2CBlockData(i2c_handle, TCS34725_CDATA, (char *)buf, 4);
    if (rc != 4) {
        fprintf(stderr, "Error reading RGBC block: expected 4 bytes, got %d\n", rc);
        return -1;
    }
    *c = (uint16_t)((buf[1] << 8) | buf[0]);
    *r = (uint16_t)((buf[3] << 8) | buf[2]);
    *g = (uint16_t)((buf[5] << 8) | buf[4]);
    *b = (uint16_t)((buf[7] << 8) | buf[6]);
    return 0;
}

/* Initialise the TCS34725 sensor: power on, RGBC enable, integration time 154 ms */
static int tcs34725_init(void) {
    /* Power on */
    if (tcs34725_write_reg(TCS34725_ENABLE, TCS34725_ENABLE_PON) != 0) {
        return -1;
    }
    gpioDelay(3000); /* 3 ms power-on delay */

    /* Enable RGBC */
    if (tcs34725_write_reg(TCS34725_ENABLE, TCS34725_ENABLE_PON | TCS34725_ENABLE_AEN) != 0) {
        return -1;
    }

    /* Set integration time to 154 ms */
    if (tcs34725_write_reg(TCS34725_ATIME, TCS34725_ATIME_154MS) != 0) {
        return -1;
    }

    gpioDelay(2000); /* Wait for first integration cycle to complete */
    return 0;
}

/* Log a color reading to the CSV file */
static void log_color_data(uint16_t c, uint16_t r, uint16_t g, uint16_t b) {
    time_t now = time(NULL);
    if (fprintf(fp, "%ld,%u,%u,%u,%u\n", (long)now, c, r, g, b) < 0) {
        fprintf(stderr, "Error writing to CSV file: %s\n", strerror(errno));
    } else {
        fflush(fp);
    }
}

int main(void) {
    /* Register signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
    }

    /* Initialise pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at the TCS34725 address */
    i2c_handle = i2cOpen(1, TCS34725_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus 1 at address 0x%02X: pigpio error %d\n",
                TCS34725_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialise the sensor */
    if (tcs34725_init() != 0) {
        fprintf(stderr, "TCS34725 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open the CSV file for appending */
    fp = fopen("color_data.csv", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening color_data.csv: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write a header row if the file is empty */
    fseek(fp, 0, SEEK_END);
    if (ftell(fp) == 0) {
        fprintf(fp, "timestamp,clear,red,green,blue\n");
        fflush(fp);
    }

    printf("TCS34725 color sensor logging started. Press Ctrl+C to stop.\n");

    /* Main loop */
    while (!terminate) {
        uint16_t c, r, g, b;

        if (tcs34725_read_rgbc(&c, &r, &g, &b) == 0) {
            log_color_data(c, r, g, b);
        } else {
            fprintf(stderr, "Sensor read failed; logging zeros for this cycle.\n");
            log_color_data(0, 0, 0, 0);
        }

        gpioDelay(500000); /* 500 ms */
    }

    /* Cleanup */
    printf("\nShutting down...\n");
    if (fp != NULL) {
        fclose(fp);
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

