#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define CHIP_NAME "gpiochip0"
#define NUM_RELAYS 4
#define SUNRISE_DURATION 3600
#define DAYTIME_DURATION 3600
#define SUNSET_DURATION 3600
#define NIGHTTIME_DURATION 86400
#define PWM_STEPS 100
#define STEP_DELAY_US 10000

static const int relay_pins[NUM_RELAYS] = {17, 27, 22, 23};
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *relay_lines[NUM_RELAYS] = {NULL};
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cleanup(void) {
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (relay_lines[i]) {
            gpiod_line_set_value(relay_lines[i], 1);
            gpiod_line_release(relay_lines[i]);
            relay_lines[i] = NULL;
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

static int init_gpio(void) {
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return -1;
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        relay_lines[i] = gpiod_line_get(chip, relay_pins[i]);
        if (!relay_lines[i]) {
            fprintf(stderr, "gpiod_line_get failed for pin %d\n", relay_pins[i]);
            return -1;
        }
        if (gpiod_line_request_output(relay_lines[i], "sunrise-simulator", 1) < 0) {
            perror("gpiod_line_request_output");
            return -1;
        }
    }
    return 0;
}

static void set_all_relays(int value) {
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (relay_lines[i]) {
            gpiod_line_set_value(relay_lines[i], value);
        }
    }
}

static void sunrise_phase(void) {
    int duty_cycle = 0;
    for (int i = 0; i < PWM_STEPS && running; i++) {
        duty_cycle = (i * 100) / PWM_STEPS;
        set_all_relays(duty_cycle);
        usleep(STEP_DELAY_US);
    }
    set_all_relays(0);
}

static void daytime_phase(void) {
    set_all_relays(100);
    for (int i = 0; i < DAYTIME_DURATION * 3600 && running; i++) {
        usleep(1000000);
    }
    set_all_relays(0);
}

static void sunset_phase(void) {
    int duty_cycle = 100;
    for (int i = 0; i < PWM_STEPS && running; i++) {
        duty_cycle = (i * 100) / PWM_STEPS;
        set_all_relays(duty_cycle);
        usleep(STEP_DELAY_US);
    }
    set_all_relays(0);
}

static void nighttime_phase(void) {
    set_all_relays(0);
    for (int i = 0; i < NIGHTTIME_DURATION * 3600 && running; i++) {
        usleep(1000000);
    }
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (init_gpio() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    time_t start_time = time(NULL);
    while (running) {
        time_t current_time = time(NULL);
        int elapsed = (int)(current_time - start_time);

        if (elapsed >= SUNRISE_DURATION) {
            sunrise_phase();
            elapsed = 0;
        } else if (elapsed >= SUNRISE_DURATION + DAYTIME_DURATION) {
            daytime_phase();
            elapsed = 0;
        } else if (elapsed >= SUNRISE_DURATION + DAYTIME_DURATION + SUNSET_DURATION) {
            sunset_phase();
            elapsed = 0;
        } else if (elapsed >= SUNRISE_DURATION + DAYTIME_DURATION + SUNSET_DURATION + NIGHTTIME_DURATION) {
            nighttime_phase();
            elapsed = 0;
        }

        usleep(100000);
    }

    set_all_relays(0);
    cleanup();
    return EXIT_SUCCESS;
}

