            perror("gpiod_line_request_output");
            return -1;
        }
    }
    return 0;
}

static void set_all_relays(int value) {
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (relay_lines[i]) {
            gpiod_line_set_value(relay_lines[i], value);
        }
    }
}

static void sunrise_phase(void) {
    int duty_cycle = 0;
    for (int i = 0; i < PWM_STEPS && running; i++) {
        duty_cycle = (i * 100) / PWM_STEPS;
        set_all_relays(duty_cycle);
        usleep(STEP_DELAY_US);
    }
    set_all_relays(0);
}

static void daytime_phase(void) {
    set_all_relays(100);
    for (int i = 0; i < DAYTIME_DURATION * 3600 && running; i++) {
        usleep(1000000);
    }
    set_all_relays(0);
}

static void sunset_phase(void) {
    int duty_cycle = 100;
    for (int i = 0; i < PWM_STEPS && running; i++) {
        duty_cycle = (i * 100) / PWM_STEPS;
        set_all_relays(duty_cycle);
        usleep(STEP_DELAY_US);
    }
    set_all_relays(0);
}

static void nighttime_phase(void) {
    set_all_relays(0);
    for (int i = 0; i < NIGHTTIME_DURATION * 3600 && running; i++) {
        usleep(1000000);
    }
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (init_gpio() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    time_t start_time = time(NULL);
    while (running) {
        time_t current_time = time(NULL);
        int elapsed = (int)(current_time - start_time);

        if (elapsed >= SUNRISE_DURATION) {
            sunrise_phase();
            elapsed = 0;
        } else if (elapsed >= SUNRISE_DURATION + DAYTIME_DURATION) {
            daytime_phase();
            elapsed = 0;
        } else if (elapsed >= SUNRISE_DURATION + DAYTIME_DURATION + SUNSET_DURATION) {
            sunset_phase();
            elapsed = 0;
        } else if (elapsed >= SUNRISE_DURATION + DAYTIME_DURATION + SUNSET_DURATION + NIGHTTIME_DURATION) {
            nighttime_phase();
            elapsed = 0;
        }

        usleep(100000);
    }

    set_all_relays(0);
    cleanup();
    return EXIT_SUCCESS;
}

