#define MOTION_SENSOR_GPIO 17
#define VIDEO_DIR "/home/pi/videos/"
#define LOG_FILE "/home/pi/logs/motion_log.txt"
#define DEBOUNCE_MS 200
#define VIDEO_DURATION_SEC 5

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int get_timestamp(char *buf, size_t len) {
    time_t t = time(NULL);
    if (t == (time_t)-1) return -1;
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) return -1;
    if (strftime(buf, len, "%Y%m%d_%H%M%S", &tm) == 0) return -1;
    return 0;
}

static int execute_command(const char *cmd) {
    int status = system(cmd);
    if (status == -1) {
        fprintf(stderr, "Error: system() failed to execute command: %s\n", cmd);
        return -1;
    }
    if (!WIFEXITED(status) || WEXITSTATUS(status) != 0) {
        fprintf(stderr, "Error: command %s exited with status %d\n", cmd, WIFEXITED(status) ? WEXITSTATUS(status) : -1);
        return -1;
    }
    return 0;
}

static int log_motion_event(const char *timestamp) {
    if (log_file == NULL) {
        fprintf(stderr, "Error: log file is not open\n");
        return -1;
    }
    if (fprintf(log_file, "%s Motion detected on GPIO %d\n", timestamp, MOTION_SENSOR_GPIO) < 0) {
        fprintf(stderr, "Error: failed to write to log file\n");
        return -1;
    }
    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error: failed to flush log file\n");
        return -1;
    }
    return 0;
}

