#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

/* MPU-6050 I2C address (AD0 tied low) */
#define MPU6050_ADDR 0x68

/* MPU-6050 registers */
#define PWR_MGMT_1   0x6B
#define SMPLRT_DIV   0x19
#define GYRO_CONFIG  0x1B
#define GYRO_XOUT_H  0x43
#define GYRO_XOUT_L  0x44
#define GYRO_YOUT_H  0x45
#define GYRO_YOUT_L  0x46
#define GYRO_ZOUT_H  0x47
#define GYRO_ZOUT_L  0x48

/* Sensitivity for ±250°/s range: 131 LSB per °/s */
#define GYRO_SCALE 131.0f

/* Sampling interval in microseconds (100 Hz) */
#define SAMPLE_INTERVAL_US 10000

/* Maximum consecutive read failures before re-initialization */
#define MAX_READ_FAILURES 3

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int init_mpu6050(void) {
    /* Wake up the MPU-6050 (clear SLEEP bit) */
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write PWR_MGMT_1 (0x6B): %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(100000); /* 100 ms stabilization */

    /* Set sample rate divider to 125 Hz (0x07) */
    if (i2cWriteByteData(i2c_handle, SMPLRT_DIV, 0x07) < 0) {
        fprintf(stderr, "Error: Failed to write SMPLRT_DIV (0x19): %s\n", strerror(errno));
        return -1;
    }

    /* Set gyroscope full-scale range to ±250°/s (0x00) */
    if (i2cWriteByteData(i2c_handle, GYRO_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write GYRO_CONFIG (0x1B): %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int read_gyro_data(float *x, float *y, float *z) {
    char buffer[6];
    int16_t raw_x, raw_y, raw_z;

    /* Read 6 bytes starting at GYRO_XOUT_H (0x43) */
    if (i2cReadI2CBlockData(i2c_handle, GYRO_XOUT_H, buffer, 6) != 6) {
        fprintf(stderr, "Error: Failed to read gyroscope data: %s\n", strerror(errno));
        return -1;
    }

    raw_x = (int16_t)((buffer[0] << 8) | (uint8_t)buffer[1]);
    raw_y = (int16_t)((buffer[2] << 8) | (uint8_t)buffer[3]);
    raw_z = (int16_t)((buffer[4] << 8) | (uint8_t)buffer[5]);

    *x = (float)raw_x / GYRO_SCALE;
    *y = (float)raw_y / GYRO_SCALE;
    *z = (float)raw_z / GYRO_SCALE;

    return 0;
}

static void log_data(float x, float y, float z) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    double timestamp = (double)ts.tv_sec + (double)ts.tv_nsec / 1.0e9;

    fprintf(log_file, "%.3f,%.3f,%.3f,%.3f\n", timestamp, x, y, z);
    fflush(log_file);
}

int main(void) {
    float x, y, z;
    int consecutive_failures = 0;

    /* Register signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: Failed to register signal handler: %s\n", strerror(errno));
        return 1;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    /* Open I2C bus 1 at MPU-6050 address */
    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at address 0x%02X: %s\n",
                MPU6050_ADDR, strerror(errno));
        gpioTerminate();
        return 1;
    }

    /* Initialize MPU-6050 */
    if (init_mpu6050() != 0) {
        fprintf(stderr, "Error: MPU-6050 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    /* Open log file in append mode */
    log_file = fopen("gyro_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open gyro_log.csv: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    /* Write CSV header if file is empty */
    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "timestamp,x_degps,y_degps,z_degps\n");
        fflush(log_file);
    }

    printf("Gyroscope data logging started. Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (program_running) {
        if (read_gyro_data(&x, &y, &z) == 0) {
            log_data(x, y, z);
            consecutive_failures = 0;
        } else {
            consecutive_failures++;
            fprintf(stderr, "Warning: Gyroscope read failed (%d/%d)\n",
                    consecutive_failures, MAX_READ_FAILURES);

            /* Attempt sensor re-initialization up to 3 times */
            for (int attempt = 0; attempt < MAX_READ_FAILURES && program_running; attempt++) {
                fprintf(stderr, "Re-initializing MPU-6050 (attempt %d/%d)...\n",
                        attempt + 1, MAX_READ_FAILURES);
                if (init_mpu6050() == 0) {
                    break;
                }
                gpioDelay(100000); /* 100 ms between retries */
            }

            if (consecutive_failures >= MAX_READ_FAILURES) {
                fprintf(stderr, "Error: Max consecutive failures reached. Exiting.\n");
                break;
            }
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    /* Cleanup */
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    printf("Gyroscope data logging stopped.\n");
    return 0;
}

