                    consecutive_failures, MAX_READ_FAILURES);

            /* Attempt sensor re-initialization up to 3 times */
            for (int attempt = 0; attempt < MAX_READ_FAILURES && program_running; attempt++) {
                fprintf(stderr, "Re-initializing MPU-6050 (attempt %d/%d)...\n",
                        attempt + 1, MAX_READ_FAILURES);
                if (init_mpu6050() == 0) {
                    break;
                }
                gpioDelay(100000); /* 100 ms between retries */
            }

            if (consecutive_failures >= MAX_READ_FAILURES) {
                fprintf(stderr, "Error: Max consecutive failures reached. Exiting.\n");
                break;
            }
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    /* Cleanup */
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    printf("Gyroscope data logging stopped.\n");
    return 0;
}

