#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define NUM_ZONES 4
#define MOISTURE_THRESHOLD 30
#define LOG_FILE "irrigation_log.txt"
#define SLEEP_INTERVAL 5

static const int relay_pins[NUM_ZONES] = {4, 17, 27, 22};
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }
    for (int i = 0; i < NUM_ZONES; i++) {
        if (gpioSetMode(relay_pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: failed to set GPIO %d as output.\n", relay_pins[i]);
            gpioTerminate();
            return -1;
        }
        if (gpioWrite(relay_pins[i], 1) != 0) { /* relay OFF (active-low) */
            fprintf(stderr, "Error: failed to write HIGH to GPIO %d.\n", relay_pins[i]);
            gpioTerminate();
            return -1;
        }
    }
    return 0;
}

static int read_moisture_sensor(void) {
    return rand() % 101;
}

static int control_relay(int zone, int moisture_level) {
    int state = (moisture_level < MOISTURE_THRESHOLD) ? 0 : 1;
    if (gpioWrite(relay_pins[zone], state) != 0) {
        fprintf(stderr, "Error: failed to write GPIO %d.\n", relay_pins[zone]);
        return -1;
    }
    return state;
}

static void log_data(int zone, int moisture_level, int relay_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Zone %d, Moisture: %d, Relay: %s\n",
            timestamp, zone + 1, moisture_level, relay_state ? "ON" : "OFF");
    fflush(log_file);
}

static void cleanup(void) {
    for (int i = 0; i < NUM_ZONES; i++) {
        gpioWrite(relay_pins[i], 1); /* relay OFF (active-low) */
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    srand((unsigned int)time(NULL));

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("signal");
        return 1;
    }

    if (initialize_gpio() != 0) {
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    while (running) {
        for (int i = 0; i < NUM_ZONES; i++) {
            int moisture_level = read_moisture_sensor();
            int relay_state = control_relay(i, moisture_level);
            if (relay_state == -1) {
                cleanup();
                return 1;
            }
            log_data(i, moisture_level, relay_state);
        }
        sleep(SLEEP_INTERVAL);
    }

    cleanup();
    return 0;
}

