#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>

#define ADXL345_ADDRESS 0x53
#define ADXL345_REG_POWER_CTL 0x2D
#define ADXL345_REG_DATA_FORMAT 0x31
#define ADXL345_REG_DATAX0 0x32
#define ADXL345_SCALE_FACTOR 256.0f
#define FREEFALL_THRESHOLD 0.2f
#define FREEFALL_DURATION_MS 500
#define SAMPLE_INTERVAL_MS 100
#define ALARM_HOLD_MS 5000
#define LOG_FILE "freefall.log"

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int adxl345_init(void) {
    if (i2cWriteByteData(i2c_handle, ADXL345_REG_POWER_CTL, 0x08) < 0) {
        fprintf(stderr, "Error: Failed to enable measurement mode.\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, ADXL345_REG_DATA_FORMAT, 0x0B) < 0) {
        fprintf(stderr, "Error: Failed to configure data format.\n");
        return -1;
    }
    return 0;
}

static int read_accelerometer(float *x, float *y, float *z) {
    char buffer[6];
    int result = i2cReadI2CBlockData(i2c_handle, ADXL345_REG_DATAX0, buffer, 6);
    if (result != 6) {
        fprintf(stderr, "Error: I2C read failed (returned %d).\n", result);
        return -1;
    }
    int16_t raw_x = (int16_t)((buffer[1] << 8) | buffer[0]);
    int16_t raw_y = (int16_t)((buffer[3] << 8) | buffer[2]);
    int16_t raw_z = (int16_t)((buffer[5] << 8) | buffer[4]);
    *x = (float)raw_x / ADXL345_SCALE_FACTOR;
    *y = (float)raw_y / ADXL345_SCALE_FACTOR;
    *z = (float)raw_z / ADXL345_SCALE_FACTOR;
    return 0;
}

static int detect_freefall(float x, float y, float z) {
    if (fabsf(x) < FREEFALL_THRESHOLD &&
        fabsf(y) < FREEFALL_THRESHOLD &&
        fabsf(z) < FREEFALL_THRESHOLD) {
        return 1;
    }
    return 0;
}

static void trigger_alarm(void) {
    gpioWrite(27, 1);
    gpioDelay(ALARM_HOLD_MS * 1000);
    gpioWrite(27, 0);
}

static void log_event(float x, float y, float z) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open log file.\n");
        return;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s,%.3f,%.3f,%.3f\n", timestamp, x, y, z);
    fclose(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, ADXL345_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C device (handle %d).\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (adxl345_init() < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(27, PI_OUTPUT);
    gpioWrite(27, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    int freefall_count = 0;
    float x, y, z;

    while (!terminate) {
        if (read_accelerometer(&x, &y, &z) == 0) {
            if (detect_freefall(x, y, z)) {
                freefall_count++;
                if (freefall_count >= 2) {
                    trigger_alarm();
                    log_event(x, y, z);
                    freefall_count = 0;
                }
            } else {
                freefall_count = 0;
            }
        } else {
            fprintf(stderr, "Warning: Sensor read error, retrying...\n");
        }
        gpioDelay(SAMPLE_INTERVAL_MS * 1000);
    }

    gpioWrite(27, 0);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return 0;
}

