#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <pthread.h>

#define TRIGGER_PIN 4
#define ECHO_PIN 18
#define TRIGGER_PULSE_US 10
#define MEASUREMENT_INTERVAL_MS 200
#define ECHO_TIMEOUT_US 100000
#define MAX_DISTANCE_CM 400
#define SPEED_OF_SOUND_CM_PER_US 0.0343

#define ECHO_RISING_EDGE 0
#define ECHO_FALLING_EDGE 1

static volatile uint32_t start_tick = 0;
static volatile uint32_t end_tick = 0;
static volatile int echo_state = 0; /* 0=idle, 1=rising seen, 2=done */
static volatile int echo_received = 0;
static volatile int running = 1;
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void trigger_pulse(void) {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(TRIGGER_PIN, 0);
}

static void echo_callback(int gpio, int level, uint32_t tick) {
    (void)gpio;
    if (level == ECHO_RISING_EDGE) {
        pthread_mutex_lock(&mutex);
        start_tick = tick;
        echo_state = 1;
        echo_received = 0;
        pthread_mutex_unlock(&mutex);
    } else if (level == ECHO_FALLING_EDGE) {
        pthread_mutex_lock(&mutex);
        end_tick = tick;
        echo_state = 2;
        echo_received = 1;
        pthread_mutex_unlock(&mutex);
    }
}

static double calculate_distance_cm(uint32_t pulse_us) {
    return (double)pulse_us * SPEED_OF_SOUND_CM_PER_US / 2.0;
}

static void log_distance(double distance_cm) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long long timestamp_ns = (long long)ts.tv_sec * 1000000000LL + ts.tv_nsec;
    if (log_file) {
        fprintf(log_file, "%lld,%.2f\n", timestamp_ns, distance_cm);
        fflush(log_file);
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set TRIGGER_PIN %d as output\n", TRIGGER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set ECHO_PIN %d as input\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set alert function on ECHO_PIN %d\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen("distance_log.txt", "a");
    if (!log_file) {
        perror("Error opening distance_log.txt");
        gpioSetAlertFuncEx(ECHO_PIN, NULL, NULL);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        fclose(log_file);
        gpioSetAlertFuncEx(ECHO_PIN, NULL, NULL);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("HC-SR04 ranging started. TRIG=GPIO%d, ECHO=GPIO%d. Press Ctrl+C to stop.\n",
           TRIGGER_PIN, ECHO_PIN);

    while (running) {
        echo_state = 0;
        echo_received = 0;
        start_tick = 0;
        end_tick = 0;

        trigger_pulse();

        uint32_t deadline = gpioTick() + ECHO_TIMEOUT_US;
        while (running && echo_state != 2) {
            uint32_t now = gpioTick();
            if (now >= deadline) {
                echo_state = 2;
                pthread_mutex_lock(&mutex);
                end_tick = 0;
                pthread_mutex_unlock(&mutex);
                echo_received = 0;
            } else {
                gpioDelay(100);
            }
        }

        pthread_mutex_lock(&mutex);
        uint32_t pulse_us = 0;
        if (echo_received) {
            pulse_us = end_tick - start_tick;
        }
        pthread_mutex_unlock(&mutex);

        if (pulse_us == 0 || pulse_us > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Warning: invalid pulse width %u us, skipping\n", pulse_us);
        } else if (pulse_us > 23200) {
            fprintf(stderr, "Warning: pulse width %u us exceeds max range, skipping\n", pulse_us);
        } else {
            double distance_cm = calculate_distance_cm(pulse_us);
            if (distance_cm > 0.0 && distance_cm <= MAX_DISTANCE_CM) {
                log_distance(distance_cm);
                printf("Distance: %.2f cm\n", distance_cm);
            } else {
                fprintf(stderr, "Warning: distance %.2f cm out of range, skipping\n", distance_cm);
            }
        }

        gpioDelay(MEASUREMENT_INTERVAL_MS * 1000);
    }

    printf("\nShutting down...\n");
    gpioSetAlertFuncEx(ECHO_PIN, NULL, NULL);
    gpioWrite(TRIGGER_PIN, 0);
    gpioTerminate();
    if (log_file) {
        fclose(log_file);
    }
    pthread_mutex_destroy(&mutex);
    return EXIT_SUCCESS;
}

