#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

#define I2C_BUS 1
#define LIS3DH_ADDR 0x18
#define BUZZER_GPIO 17
#define FREEFALL_THRESHOLD 0.2f
#define IMPACT_THRESHOLD 1.5f
#define RETRY_COUNT 3
#define RETRY_DELAY_US 10000

#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_lis3dh(void) {
    if (i2cWriteByteData(i2c_handle, CTRL_REG1, 0x77) < 0) {
        fprintf(stderr, "Error: Failed to write CTRL_REG1\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, CTRL_REG4, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write CTRL_REG4\n");
        return -1;
    }
    return 0;
}

static int read_acceleration(float *x, float *y, float *z) {
    char buf[6];
    int retries = RETRY_COUNT;

    while (retries > 0) {
        int bytes = i2cReadI2CBlockData(i2c_handle, OUT_X_L, buf, 6);
        if (bytes == 6) {
            int16_t x_raw = (int16_t)((buf[1] << 8) | buf[0]);
            int16_t y_raw = (int16_t)((buf[3] << 8) | buf[2]);
            int16_t z_raw = (int16_t)((buf[5] << 8) | buf[4]);

            *x = (float)x_raw / 16384.0f;
            *y = (float)y_raw / 16384.0f;
            *z = (float)z_raw / 16384.0f;
            return 0;
        }
        retries--;
        if (retries > 0) {
            gpioDelay(RETRY_DELAY_US);
        }
    }
    fprintf(stderr, "Error: Failed to read acceleration after %d retries\n", RETRY_COUNT);
    return -1;
}

static void detect_fall(float x, float y, float z) {
    float magnitude = sqrtf(x * x + y * y + z * z);
    if (magnitude < FREEFALL_THRESHOLD) {
        printf("Freefall detected!\n");
        gpioWrite(BUZZER_GPIO, 1);
        gpioDelay(1000000);
        gpioWrite(BUZZER_GPIO, 0);
    }
}

static void detect_impact(float x, float y, float z) {
    float magnitude = sqrtf(x * x + y * y + z * z);
    if (magnitude > IMPACT_THRESHOLD) {
        printf("Impact detected!\n");
        gpioWrite(BUZZER_GPIO, 1);
        gpioDelay(1000000);
        gpioWrite(BUZZER_GPIO, 0);
    }
}

int main(int argc, char *argv[]) {
    float freefall_threshold = FREEFALL_THRESHOLD;
    float impact_threshold = IMPACT_THRESHOLD;

    if (argc > 1) {
        freefall_threshold = atof(argv[1]);
    }
    if (argc > 2) {
        impact_threshold = atof(argv[2]);
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, LIS3DH_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at address 0x%02X\n", LIS3DH_ADDR);
        gpioTerminate();
        return 1;
    }

    if (init_lis3dh() < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);
    gpioWrite(BUZZER_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    printf("Fall detection started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        float x, y, z;
        if (read_acceleration(&x, &y, &z) == 0) {
            detect_fall(x, y, z);
            detect_impact(x, y, z);
        } else {
            fprintf(stderr, "Error: Failed to read acceleration\n");
        }
        gpioDelay(10000);
    }

    gpioWrite(BUZZER_GPIO, 0);
    i2cClose(i2c_handle);
    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return 0;
}

