#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define MOTOR1_IN1 4
#define MOTOR1_IN2 17
#define MOTOR1_IN3 27
#define MOTOR1_IN4 22

#define MOTOR2_IN1 5
#define MOTOR2_IN2 6
#define MOTOR2_IN3 13
#define MOTOR2_IN4 19

#define STEPS_PER_REV 2048
#define STEP_DELAY_US 1000
#define STEP_FACTOR 10.0f
#define SIDE_LENGTH_MM 50.0f

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int safe_set_mode(unsigned gpio, unsigned mode) {
    if (gpioSetMode(gpio, mode) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%u, %u) failed\n", gpio, mode);
        return -1;
    }
    return 0;
}

static int safe_write(unsigned gpio, unsigned level) {
    if (gpioWrite(gpio, level) != 0) {
        fprintf(stderr, "Error: gpioWrite(%u, %u) failed\n", gpio, level);
        return -1;
    }
    return 0;
}

static int step_motor(unsigned motor, unsigned step) {
    int in1, in2, in3, in4;
    switch (motor) {
        case 1:
            in1 = MOTOR1_IN1; in2 = MOTOR1_IN2; in3 = MOTOR1_IN3; in4 = MOTOR1_IN4;
            break;
        case 2:
            in1 = MOTOR2_IN1; in2 = MOTOR2_IN2; in3 = MOTOR2_IN3; in4 = MOTOR2_IN4;
            break;
        default:
            fprintf(stderr, "Error: invalid motor %u\n", motor);
            return -1;
    }
    if (safe_write(in1, step & 0x01) != 0) return -1;
    if (safe_write(in2, (step >> 1) & 0x01) != 0) return -1;
    if (safe_write(in3, (step >> 2) & 0x01) != 0) return -1;
    if (safe_write(in4, (step >> 3) & 0x01) != 0) return -1;
    return 0;
}

static int move_motor(unsigned motor, int steps) {
    int direction = (steps > 0) ? 1 : -1;
    int abs_steps = abs(steps);
    int current_step = 0;
    int target_step = (steps > 0) ? 7 : 0;

    for (int i = 0; i < abs_steps && running; i++) {
        current_step = (current_step + direction + STEPS_PER_REV) % STEPS_PER_REV;
        if (step_motor(motor, current_step) != 0) {
            fprintf(stderr, "Error: step motor %u failed at step %d\n", motor, current_step);
            return -1;
        }
        gpioDelay(STEP_DELAY_US);
    }
    return 0;
}

static int draw_square(void) {
    if (move_motor(1, (int)(SIDE_LENGTH_MM * STEP_FACTOR)) != 0) return -1;
    if (move_motor(2, (int)(SIDE_LENGTH_MM * STEP_FACTOR)) != 0) return -1;
    if (move_motor(1, (int)(SIDE_LENGTH_MM * STEP_FACTOR)) != 0) return -1;
    if (move_motor(2, (int)(SIDE_LENGTH_MM * STEP_FACTOR)) != 0) return -1;
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler\n");
    }

    int pins[] = {MOTOR1_IN1, MOTOR1_IN2, MOTOR1_IN3, MOTOR1_IN4,
                  MOTOR2_IN1, MOTOR2_IN2, MOTOR2_IN3, MOTOR2_IN4};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); i++) {
        if (safe_set_mode(pins[i], PI_OUTPUT) != 0) {
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (safe_write(pins[i], 0) != 0) {
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    if (draw_square() != 0) {
        fprintf(stderr, "Error: square drawing failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

