#define LOG_FILE "/var/log/high_acceleration.log"
#define SAMPLE_INTERVAL_US 100000  /* 100 ms = 10 Hz */

/* LIS3DH register addresses */
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L   0x28
#define OUT_X_H   0x29
#define OUT_Y_L   0x2A
#define OUT_Y_H   0x2B
#define OUT_Z_L   0x2C
#define OUT_Z_H   0x2D

static int i2c_handle = -1;
static int i2c_address = DEFAULT_I2C_ADDR;
static float threshold = DEFAULT_THRESHOLD;
static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int init_lis3dh(int handle) {
    /* ±2g range, high-resolution mode (12-bit left-justified), 100 Hz ODR */
    if (i2cWriteByteData(handle, CTRL_REG1, 0x57) < 0) {
        fprintf(stderr, "Error: failed to write CTRL_REG1\n");
        return -1;
    }
    /* Enable all axes, normal mode, 12.5 Hz internal ODR (default) */
    if (i2cWriteByteData(handle, CTRL_REG4, 0x88) < 0) {
        fprintf(stderr, "Error: failed to write CTRL_REG4\n");
        return -1;
    }
    return 0;
}

static int read_acceleration(int handle, float *x, float *y, float *z) {
    char buffer[6];
    int16_t raw_x, raw_y, raw_z;

    if (i2cReadI2CBlockData(handle, OUT_X_L, buffer, 6) != 6) {
        fprintf(stderr, "Error: failed to read acceleration data\n");
        *x = 0.0f; *y = 0.0f; *z = 0.0f;
        return -1;
    }

    raw_x = (int16_t)((buffer[1] << 8) | (uint8_t)buffer[0]);
    raw_y = (int16_t)((buffer[3] << 8) | (uint8_t)buffer[2]);
    raw_z = (int16_t)((buffer[5] << 8) | (uint8_t)buffer[4]);

