#define LEFT_SENSOR_PIN 4
#define CENTER_SENSOR_PIN 17
#define RIGHT_SENSOR_PIN 27
#define ALERT_PIN 22
#define BUFFER_SIZE 5
#define ALERT_DURATION_MS 2000
#define POLL_INTERVAL_MS 10

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

typedef struct {
    int left;
    int center;
    int right;
} sensor_data_t;

typedef struct {
    sensor_data_t buffer[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

static void buffer_init(circular_buffer_t *cb) {
    cb->head = 0;
    cb->count = 0;
}

static void buffer_add(circular_buffer_t *cb, sensor_data_t data) {
    cb->buffer[cb->head] = data;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) cb->count++;
}

static void log_data(const circular_buffer_t *cb) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("[%s] Left: %d, Center: %d, Right: %d\n",
           timestamp, cb->buffer[cb->head].left,
           cb->buffer[cb->head].center, cb->buffer[cb->head].right);
    fflush(stdout);
}

static void trigger_alert(struct gpiod_line *alert_line) {
    if (gpiod_line_set_value(alert_line, 1) < 0) {
        fprintf(stderr, "Failed to set alert pin HIGH: %s\n", strerror(errno));
        return;
    }
    printf("Alert triggered!\n");
    fflush(stdout);

    struct timespec ts = {0, ALERT_DURATION_MS * 1000000L};
    nanosleep(&ts, NULL);

    if (gpiod_line_set_value(alert_line, 0) < 0) {
        fprintf(stderr, "Failed to set alert pin LOW: %s\n", strerror(errno));
    }
}

static void stop_robot(struct gpiod_line *left_line, struct gpiod_line *center_line,
                       struct gpiod_line *right_line, struct gpiod_line *alert_line) {
    printf("Stopping robot...\n");
    fflush(stdout);
    gpiod_line_set_value(left_line, 0);
    gpiod_line_set_value(center_line, 0);
    gpiod_line_set_value(right_line, 0);
    gpiod_line_set_value(alert_line, 0);
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *left_line = NULL, *center_line = NULL, *right_line = NULL, *alert_line = NULL;
    circular_buffer_t sensor_buffer;
    int ret = EXIT_FAILURE;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    buffer_init(&sensor_buffer);

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip4: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    left_line = gpiod_chip_get_line(chip, LEFT_SENSOR_PIN);
    center_line = gpiod_chip_get_line(chip, CENTER_SENSOR_PIN);
    right_line = gpiod_chip_get_line(chip, RIGHT_SENSOR_PIN);
    alert_line = gpiod_chip_get_line(chip, ALERT_PIN);

