#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define I2C_BUS        1
#define I2C_ADDR       0x30
#define RELAY_GPIO     17
#define FIELD_THRESHOLD 5.0f   /* mT */
#define SAMPLE_US      100000  /* 100 ms */
#define MAX_POLL_ATTEMPTS 50
#define LOG_FILE       "magnetic_events.txt"

/* Si7210 register addresses */
#define REG_DEVICE_CONFIG 0xC0
#define REG_HALL_SENSOR   0xC1
#define REG_DEVICE_CONFIG_VAL 0x00

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void log_event(const char *event)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
        fprintf(fp, "%s %s\n", ts, event);
    } else {
        fprintf(fp, "<unknown-time> %s\n", event);
    }
    fclose(fp);
}

static int init_sensor(void)
{
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        return -1;
    }
    /* Write 0x00 to DEVICE_CONFIG to clear any stale configuration */
    if (i2cWriteByteData(g_i2c_handle, REG_DEVICE_CONFIG, REG_DEVICE_CONFIG_VAL) < 0) {
        fprintf(stderr, "Error writing DEVICE_CONFIG: %s\n", strerror(errno));
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        return -1;
    }
    return 0;
}

static int read_field_raw(int *raw_out)
{
    int rc;
    int attempts = 0;

    /* Start one-shot conversion */
    rc = i2cWriteByteData(g_i2c_handle, REG_HALL_SENSOR, 0x01);
    if (rc < 0) {
        fprintf(stderr, "Error writing to HALL_SENSOR: %s\n", strerror(errno));
        return -1;
    }

    /* Poll until register 0xC1 reads 0x00 (conversion complete) */
    while (attempts < MAX_POLL_ATTEMPTS) {
        rc = i2cReadByteData(g_i2c_handle, REG_HALL_SENSOR);
        if (rc < 0) {
            fprintf(stderr, "Error reading HALL_SENSOR: %s\n", strerror(errno));
            return -1;
        }
        if (rc == 0x00)
            break;
        attempts++;
        gpioDelay(2000); /* 2 ms */
    }

    if (attempts >= MAX_POLL_ATTEMPTS) {
        fprintf(stderr, "Timeout waiting for HALL_SENSOR conversion\n");
        return -1;
    }

    /* Read 2 bytes from DEVICE_CONFIG (0xC0) */
    rc = i2cReadByteData(g_i2c_handle, REG_DEVICE_CONFIG);
    if (rc < 0) {
        fprintf(stderr, "Error reading DEVICE_CONFIG: %s\n", strerror(errno));
        return -1;
    }

    uint8_t lsb = (uint8_t)rc;
    rc = i2cReadByteData(g_i2c_handle, REG_DEVICE_CONFIG + 1);
    if (rc < 0) {
        fprintf(stderr, "Error reading DEVICE_CONFIG MSB: %s\n", strerror(errno));
        return -1;
    }
    uint8_t msb = (uint8_t)rc;

    int field_raw = (msb << 8) | lsb;
    *raw_out = field_raw;
    return 0;
}

static float raw_to_milliteas(int raw)
{
    /* Si7210: 1 LSB = 0.01 mT */
    return (float)raw * 0.01f;
}

static void control_relay(int state)
{
    if (gpioWrite(RELAY_GPIO, state) < 0) {
        fprintf(stderr, "Error writing to GPIO %d: %s\n",
                RELAY_GPIO, strerror(errno));
        log_event("ERROR: GPIO write failed");
        return;
    }
    if (state)
        log_event("Relay activated");
    else
        log_event("Relay deactivated");
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting GPIO %d as output: %s\n",
                RELAY_GPIO, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(RELAY_GPIO, 0);

    if (init_sensor() < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error installing SIGINT handler: %s\n", strerror(errno));
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_event("Program started");

    while (g_running) {
        int raw;
        if (read_field_raw(&raw) < 0) {
            gpioWrite(RELAY_GPIO, 0);
            log_event("ERROR: sensor read failed, deactivating relay");
            gpioDelay(SAMPLE_US);
            continue;
        }

        float field_mT = raw_to_milliteas(raw);
        int relay_state = (field_mT > FIELD_THRESHOLD) ? 1 : 0;
        control_relay(relay_state);

        char msg[128];
        snprintf(msg, sizeof(msg), "Field: %.2f mT, Relay: %s",
                 field_mT, relay_state ? "ON" : "OFF");
        log_event(msg);

        gpioDelay(SAMPLE_US);
    }

    /* Graceful shutdown */
    gpioWrite(RELAY_GPIO, 0);
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    log_event("Program stopped");
    gpioTerminate();
    return EXIT_SUCCESS;
}

