#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define PORT 5000
#define GPIO_PIN 18
#define BUFFER_SIZE 1024
#define LOG_FILE "relay_log.txt"

static volatile sig_atomic_t running = 1;
static int server_fd = -1;
static int client_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int signum) {
    (void)signum;
    running = 0;
}

static void log_event(const char *event) {
    if (!log_file) return;
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) return;
    fprintf(log_file, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, event);
    fflush(log_file);
}

static int control_relay(int state) {
    if (gpioWrite(GPIO_PIN, state) != 0) {
        fprintf(stderr, "Error: gpioWrite failed for pin %d\n", GPIO_PIN);
        return -1;
    }
    char msg[64];
    snprintf(msg, sizeof(msg), "Relay %s", state ? "ON" : "OFF");
    log_event(msg);
    printf("%s\n", msg);
    return 0;
}

static void cleanup(void) {
    if (client_fd >= 0) {
        close(client_fd);
        client_fd = -1;
    }
    if (server_fd >= 0) {
        close(server_fd);
        server_fd = -1;
    }
    if (log_file) {
        log_event("Server shutting down");
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(GPIO_PIN, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for pin %d\n", GPIO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(GPIO_PIN, 0);

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        perror("Error creating socket");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int opt = 1;
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        perror("Error setting SO_REUSEADDR");
        close(server_fd);
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sockaddr_in address;
    memset(&address, 0, sizeof(address));
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("Error binding socket");
        close(server_fd);
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (listen(server_fd, 3) < 0) {
        perror("Error listening on socket");
        close(server_fd);
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Server listening on port %d (GPIO %d)\n", PORT, GPIO_PIN);
    log_event("Server started");

    while (running) {
        struct sockaddr_in client_addr;
        socklen_t addrlen = sizeof(client_addr);
        client_fd = accept(server_fd, (struct sockaddr *)&client_addr, &addrlen);
        if (client_fd < 0) {
            if (errno == EINTR && !running) break;
            perror("Error accepting connection");
            continue;
        }

        char ip_str[INET_ADDRSTRLEN];
        inet_ntop(AF_INET, &client_addr.sin_addr, ip_str, sizeof(ip_str));
        printf("Connection from %s:%d\n", ip_str, ntohs(client_addr.sin_port));

        char buffer[BUFFER_SIZE];
        ssize_t valread = read(client_fd, buffer, BUFFER_SIZE - 1);
        if (valread < 0) {
            perror("Error reading from socket");
            close(client_fd);
            client_fd = -1;
            continue;
        }
        if (valread == 0) {
            printf("Client disconnected\n");
            close(client_fd);
            client_fd = -1;
            continue;
        }
        buffer[valread] = '\0';

        char *command = strtok(buffer, " \r\n");
        while (command) {
            if (strcmp(command, "ON") == 0) {
                control_relay(1);
            } else if (strcmp(command, "OFF") == 0) {
                control_relay(0);
            } else {
                log_event("Invalid command");
                const char *err = "Invalid command\n";
                send(client_fd, err, strlen(err), 0);
            }
            command = strtok(NULL, " \r\n");
        }
        send(client_fd, "OK\n", 3, 0);
        close(client_fd);
        client_fd = -1;
    }

    cleanup();
    return EXIT_SUCCESS;
}

