    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        perror("Error creating socket");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int opt = 1;
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        perror("Error setting SO_REUSEADDR");
        close(server_fd);
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sockaddr_in address;
    memset(&address, 0, sizeof(address));
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("Error binding socket");
        close(server_fd);
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (listen(server_fd, 3) < 0) {
        perror("Error listening on socket");
        close(server_fd);
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Server listening on port %d (GPIO %d)\n", PORT, GPIO_PIN);
    log_event("Server started");

    while (running) {
        struct sockaddr_in client_addr;
        socklen_t addrlen = sizeof(client_addr);
        client_fd = accept(server_fd, (struct sockaddr *)&client_addr, &addrlen);
        if (client_fd < 0) {
            if (errno == EINTR && !running) break;
            perror("Error accepting connection");
            continue;
        }

        char ip_str[INET_ADDRSTRLEN];
        inet_ntop(AF_INET, &client_addr.sin_addr, ip_str, sizeof(ip_str));
        printf("Connection from %s:%d\n", ip_str, ntohs(client_addr.sin_port));

        char buffer[BUFFER_SIZE];
        ssize_t valread = read(client_fd, buffer, BUFFER_SIZE - 1);
        if (valread < 0) {
            perror("Error reading from socket");
            close(client_fd);
            client_fd = -1;
            continue;
        }
        if (valread == 0) {
            printf("Client disconnected\n");
            close(client_fd);
            client_fd = -1;
            continue;
        }
        buffer[valread] = '\0';

        char *command = strtok(buffer, " \r\n");
        while (command) {
            if (strcmp(command, "ON") == 0) {
                control_relay(1);
            } else if (strcmp(command, "OFF") == 0) {
                control_relay(0);
            } else {
                log_event("Invalid command");
                const char *err = "Invalid command\n";
                send(client_fd, err, strlen(err), 0);
            }
            command = strtok(NULL, " \r\n");
        }
        send(client_fd, "OK\n", 3, 0);
        close(client_fd);
        client_fd = -1;
    }

    cleanup();
    return EXIT_SUCCESS;
}

