#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR1_ADDR 0x08
#define SENSOR2_ADDR 0x09
#define I2C_BUS 1
#define GPIO_RELAY 18
#define FLOW_THRESHOLD 5.0f
#define POLL_DELAY_US 100000
#define SCALE_FACTOR 1.0f / 1500.0f
#define LOG_FILE "flow_log.txt"

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle1 = -1;
static int g_i2c_handle2 = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static int read_flow_rate(int handle, float *flow_out) {
    uint8_t cmd[2] = {0x36, 0x08};
    uint8_t buf[3];
    int rc;

    rc = i2cWriteDevice(handle, (char *)cmd, 2);
    if (rc < 0) {
        fprintf(stderr, "I2C write error on handle %d: %d\n", handle, rc);
        return -1;
    }

    gpioDelay(2000);

    rc = i2cReadDevice(handle, (char *)buf, 3);
    if (rc < 0) {
        fprintf(stderr, "I2C read error on handle %d: %d\n", handle, rc);
        return -1;
    }
    if (rc != 3) {
        fprintf(stderr, "I2C read short on handle %d: got %d bytes\n", handle, rc);
        return -1;
    }

    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "CRC mismatch on handle %d\n", handle);
        return -1;
    }

    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *flow_out = (float)raw * SCALE_FACTOR;
    return 0;
}

static void log_flow_rates(float f1, float f2) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log");
        return;
    }

    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm;
    localtime_r(&ts.tv_sec, &tm);

    char tbuf[32];
    strftime(tbuf, sizeof(tbuf), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s.%03ld, Sensor1: %.2f ml/min, Sensor2: %.2f ml/min\n",
            tbuf, ts.tv_nsec / 1000000, f1, f2);
    fflush(fp);
    fclose(fp);
}

static void control_relay(float f1, float f2) {
    if (f1 < FLOW_THRESHOLD || f2 < FLOW_THRESHOLD) {
        gpioWrite(GPIO_RELAY, 1);
    } else {
        gpioWrite(GPIO_RELAY, 0);
    }
}

static void cleanup(void) {
    if (g_i2c_handle1 >= 0) {
        i2cClose(g_i2c_handle1);
        g_i2c_handle1 = -1;
    }
    if (g_i2c_handle2 >= 0) {
        i2cClose(g_i2c_handle2);
        g_i2c_handle2 = -1;
    }
    gpioWrite(GPIO_RELAY, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle1 = i2cOpen(I2C_BUS, SENSOR1_ADDR, 0);
    if (g_i2c_handle1 < 0) {
        fprintf(stderr, "Failed to open I2C for sensor 1 (0x%02X): %d\n", SENSOR1_ADDR, g_i2c_handle1);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_i2c_handle2 = i2cOpen(I2C_BUS, SENSOR2_ADDR, 0);
    if (g_i2c_handle2 < 0) {
        fprintf(stderr, "Failed to open I2C for sensor 2 (0x%02X): %d\n", SENSOR2_ADDR, g_i2c_handle2);
        i2cClose(g_i2c_handle1);
        g_i2c_handle1 = -1;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (i2cWriteByteData(g_i2c_handle1, 0x00, 0x36) < 0 ||
        i2cWriteByteData(g_i2c_handle2, 0x00, 0x36) < 0) {
        fprintf(stderr, "Failed to start measurement on either sensor\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_RELAY, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", GPIO_RELAY);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioWrite(GPIO_RELAY, 0) < 0) {
        fprintf(stderr, "Failed to initialize GPIO %d low\n", GPIO_RELAY);
        cleanup();
        return EXIT_FAILURE;
    }

    while (g_running) {
        float f1 = 0.0f, f2 = 0.0f;
        int ok1 = read_flow_rate(g_i2c_handle1, &f1);
        int ok2 = read_flow_rate(g_i2c_handle2, &f2);

        if (ok1 == 0 && ok2 == 0) {
            log_flow_rates(f1, f2);
            control_relay(f1, f2);
        } else {
            fprintf(stderr, "Read error or CRC mismatch; skipping cycle\n");
        }

        gpioDelay(POLL_DELAY_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

