#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <syslog.h>
#include <pigpio.h>

#define RAIN_SENSOR_PIN 17
#define MOTOR_ENABLE_PIN 22
#define MOTOR_IN1_PIN    23
#define MOTOR_IN2_PIN    24

#define POLL_INTERVAL_US  200000   /* 200 ms */
#define MOTOR_RUN_US      5000000  /* 5 s   */
#define DRY_CONSECUTIVE   3         /* ~600 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int safe_write(unsigned pin, unsigned level)
{
    if (gpioWrite(pin, level) < 0) {
        syslog(LOG_WARNING, "gpioWrite(pin=%u, level=%u) failed", pin, level);
        return -1;
    }
    return 0;
}

static int motor_stop(void)
{
    if (safe_write(MOTOR_ENABLE_PIN, 0) < 0) return -1;
    if (safe_write(MOTOR_IN1_PIN, 0) < 0) return -1;
    if (safe_write(MOTOR_IN2_PIN, 0) < 0) return -1;
    return 0;
}

static int motor_start(void)
{
    if (safe_write(MOTOR_ENABLE_PIN, 1) < 0) return -1;
    if (safe_write(MOTOR_IN1_PIN, 1) < 0) return -1;
    if (safe_write(MOTOR_IN2_PIN, 0) < 0) return -1;
    return 0;
}

static void motor_stop_and_verify(void)
{
    if (motor_stop() < 0) {
        syslog(LOG_ERR, "Failed to stop motor");
        return;
    }
    syslog(LOG_INFO, "Motor stopped");
}

static void cleanup(void)
{
    motor_stop_and_verify();
    gpioTerminate();
    syslog(LOG_INFO, "pigpio terminated");
    closelog();
}

int main(void)
{
    openlog("rain_window", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "sigaction failed: %m");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "gpioInitialise() failed");
        closelog();
        return EXIT_FAILURE;
    }
    syslog(LOG_INFO, "pigpio initialised");

    if (gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT) < 0) {
        syslog(LOG_ERR, "gpioSetMode(RAIN_SENSOR_PIN) failed");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(RAIN_SENSOR_PIN, PI_PUD_UP) < 0) {
        syslog(LOG_WARNING, "gpioSetPullUpDown(RAIN_SENSOR_PIN) failed");
    }

    if (gpioSetMode(MOTOR_ENABLE_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "gpioSetMode(motor pins) failed");
        cleanup();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "Rain window controller started (GPIO %d, %d, %d, %d)",
           RAIN_SENSOR_PIN, MOTOR_ENABLE_PIN, MOTOR_IN1_PIN, MOTOR_IN2_PIN);

    int dry_count = 0;
    int last_rain_state = 1;  /* assume dry at startup */

    while (g_running) {
        int rain_state = gpioRead(RAIN_SENSOR_PIN);
        if (rain_state < 0) {
            syslog(LOG_ERR, "gpioRead(RAIN_SENSOR_PIN) failed");
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        if (rain_state == 0) {  /* rain detected (DO LOW) */
            if (last_rain_state == 1) {
                syslog(LOG_INFO, "Rain detected");
                if (motor_start() == 0) {
                    syslog(LOG_INFO, "Motor started");
                    gpioDelay(MOTOR_RUN_US);
                    if (motor_stop() == 0) {
                        syslog(LOG_INFO, "Motor stopped");
                    } else {
                        syslog(LOG_ERR, "Failed to stop motor after run");
                    }
                } else {
                    syslog(LOG_ERR, "Failed to start motor");
                }
            }
            last_rain_state = 0;
            dry_count = 0;
        } else {  /* rain_state == 1: dry */
            dry_count++;
            if (dry_count >= DRY_CONSECUTIVE) {
                dry_count = 0;
                syslog(LOG_INFO, "Dry for %d polls, no rain", DRY_CONSECUTIVE);
            }
            last_rain_state = 1;
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    syslog(LOG_INFO, "Shutting down");
    cleanup();
    return EXIT_SUCCESS;
}

