                        syslog(LOG_INFO, "Motor stopped");
                    } else {
                        syslog(LOG_ERR, "Failed to stop motor after run");
                    }
                } else {
                    syslog(LOG_ERR, "Failed to start motor");
                }
            }
            last_rain_state = 0;
            dry_count = 0;
        } else {  /* rain_state == 1: dry */
            dry_count++;
            if (dry_count >= DRY_CONSECUTIVE) {
                dry_count = 0;
                syslog(LOG_INFO, "Dry for %d polls, no rain", DRY_CONSECUTIVE);
            }
            last_rain_state = 1;
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    syslog(LOG_INFO, "Shutting down");
    cleanup();
    return EXIT_SUCCESS;
}

