#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define SERVO_PIN      18
#define BUTTON_LOCK    21
#define BUTTON_UNLOCK  22
#define LOCK_PULSE_US  2000
#define UNLOCK_PULSE_US 1000
#define DEBOUNCE_US    50000   /* 50 ms */
#define POLL_DELAY_US  10000   /* 10 ms  */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int set_servo_pulse(int pulse_us)
{
    if (gpioServo(SERVO_PIN, pulse_us) < 0) {
        fprintf(stderr, "gpioServo failed for pulse %d us\n", pulse_us);
        return -1;
    }
    return 0;
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (install_signal_handlers() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure button pins as inputs with internal pull-ups so they read
       HIGH when idle (button not pressed). */
    if (gpioSetMode(BUTTON_LOCK, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", BUTTON_LOCK);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BUTTON_UNLOCK, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", BUTTON_UNLOCK);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(BUTTON_LOCK, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d\n", BUTTON_LOCK);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(BUTTON_UNLOCK, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d\n", BUTTON_UNLOCK);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Centre the servo at startup so the lock is released. */
    if (set_servo_pulse(1500) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }
    printf("Servo initialised at centre (1500 us). Lock released.\n");

    int last_lock = gpioRead(BUTTON_LOCK);
    int last_unlock = gpioRead(BUTTON_UNLOCK);
    if (last_lock < 0 || last_unlock < 0) {
        fprintf(stderr, "Initial button read failed\n");
        gpioServo(SERVO_PIN, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (g_running) {
        int lock_state = gpioRead(BUTTON_LOCK);
        int unlock_state = gpioRead(BUTTON_UNLOCK);

        if (lock_state < 0 || unlock_state < 0) {
            fprintf(stderr, "Button read error; aborting.\n");
            break;
        }

        /* Button is active-low: pressed -> LOW. */
        if (lock_state == 0 && last_lock == 1) {
            gpioDelay(DEBOUNCE_US);
            if (gpioRead(BUTTON_LOCK) == 0) {
                if (set_servo_pulse(LOCK_PULSE_US) == 0) {
                    printf("Lock activated.\n");
                }
                last_lock = 0;
            }
        }

        if (unlock_state == 0 && last_unlock == 1) {
            gpioDelay(DEBOUNCE_US);
            if (gpioRead(BUTTON_UNLOCK) == 0) {
                if (set_servo_pulse(UNLOCK_PULSE_US) == 0) {
                    printf("Unlock activated.\n");
                }
                last_unlock = 0;
            }
        }

        last_lock = lock_state;
        last_unlock = unlock_state;
        gpioDelay(POLL_DELAY_US);
    }

    /* Clean shutdown: stop servo pulses and release pigpio. */
    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
    printf("Shutdown complete.\n");
    return EXIT_SUCCESS;
}

