#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define PIR_PIN 4
#define FLOODLIGHT_PIN 17
#define LOG_FILE "security_log.txt"
#define ACTIVATION_DURATION 60
#define POLL_INTERVAL_US 100000

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int log_event(const char *event_type, const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char timestamp[64];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm);
        fprintf(fp, "%s - %s: %s\n", timestamp, event_type, message);
    } else {
        fprintf(fp, "<timestamp-error> - %s: %s\n", event_type, message);
    }
    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int activate_floodlight(void) {
    if (gpioWrite(FLOODLIGHT_PIN, 1) != 0) {
        fprintf(stderr, "Error activating floodlight on GPIO %d\n", FLOODLIGHT_PIN);
        return -1;
    }
    printf("Floodlight activated\n");
    return 0;
}

static int deactivate_floodlight(void) {
    if (gpioWrite(FLOODLIGHT_PIN, 0) != 0) {
        fprintf(stderr, "Error deactivating floodlight on GPIO %d\n", FLOODLIGHT_PIN);
        return -1;
    }
    printf("Floodlight deactivated\n");
    return 0;
}

static int log_activation(void) {
    return log_event("Activation", "Floodlight activated");
}

static int log_deactivation(int duration) {
    return log_event("Deactivation", "Floodlight deactivated after " + (duration > 0 ? duration : "0 seconds"));
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PIR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting PIR pin %d as input\n", PIR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FLOODLIGHT_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting floodlight pin %d as output\n", FLOODLIGHT_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(FLOODLIGHT_PIN, 0) != 0) {
        fprintf(stderr, "Error initializing floodlight pin %d to LOW\n", FLOODLIGHT_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error installing signal handler: %s\n", strerror(errno));
        gpioWrite(FLOODLIGHT_PIN, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Smart Security Light System started. Monitoring PIR on GPIO %d...\n", PIR_PIN);

    while (g_running) {
        int pir_value = gpioRead(PIR_PIN);
        if (pir_value < 0) {
            fprintf(stderr, "Error reading PIR pin %d\n", PIR_PIN);
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        if (pir_value == 1) {
            if (activate_floodlight() != 0) {
                gpioDelay(POLL_INTERVAL_US);
                continue;
            }

            if (log_activation() != 0) {
                fprintf(stderr, "Logging failed; turning off floodlight for safety\n");
                deactivate_floodlight();
                break;
            }

            time_t start_time = time(NULL);
            int duration = 0;

            while (g_running) {
                int pir_value = gpioRead(PIR_PIN);
                if (pir_value < 0) {
                    fprintf(stderr, "Error reading PIR pin %d\n", PIR_PIN);
                    break;
                }
                if (pir_value == 0) {
                    break;
                }
                gpioDelay(POLL_INTERVAL_US);
                duration++;
            }

            if (log_deactivation(duration) != 0) {
                fprintf(stderr, "Logging failed; turning off floodlight for safety\n");
                deactivate_floodlight();
                break;
            }

            if (deactivate_floodlight() != 0) {
                break;
            }

            time_t end_time = time(NULL);
            double elapsed = difftime(end_time, start_time);
            if (elapsed > ACTIVATION_DURATION) {
                fprintf(stderr, "Floodlight exceeded activation duration; turning off early\n");
                deactivate_floodlight();
            }
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    gpioWrite(FLOODLIGHT_PIN, 0);
    gpioTerminate();
    printf("Smart Security Light System stopped.\n");
    return EXIT_SUCCESS;
}

