#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define RELAY_GPIO 17
#define I2C_BUS 1
#define MPR121_ADDR 0x5A

#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_ELECTRODE_CONFIG 0x5E
#define MPR121_AUTOCONFIG0 0x7B
#define MPR121_AUTOCONFIG1 0x7C
#define MPR121_AUTOCONFIG2 0x7D
#define MPR121_DEBOUNCE 0x5B
#define MPR121_SOFTRESET 0x80
#define MPR121_ELECTRODE_CONFIG_ELECTRODES 0x5E

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int mpr121_write_reg(uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(i2c_handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing reg 0x%02X: %s\n", reg, pigpio_error(rc));
    }
    return rc;
}

static int mpr121_init(void) {
    if (mpr121_write_reg(MPR121_SOFTRESET, 0x63) < 0) return -1;
    gpioDelay(1000);

    if (mpr121_write_reg(0x2B, 0x01) < 0) return -1;
    if (mpr121_write_reg(0x2C, 0x01) < 0) return -1;
    if (mpr121_write_reg(0x2D, 0x00) < 0) return -1;
    if (mpr121_write_reg(0x2E, 0x00) < 0) return -1;
    if (mpr121_write_reg(0x2F, 0x00) < 0) return -1;
    if (mpr121_write_reg(0x30, 0x00) < 0) return -1;
    if (mpr121_write_reg(0x31, 0x00) < 0) return -1;

    if (mpr121_write_reg(MPR121_DEBOUNCE, 0x00) < 0) return -1;

    if (mpr121_write_reg(MPR121_AUTOCONFIG0, 0x0B) < 0) return -1;
    if (mpr121_write_reg(MPR121_AUTOCONFIG1, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_AUTOCONFIG2, 0x00) < 0) return -1;

    if (mpr121_write_reg(MPR121_ELECTRODE_CONFIG, 0x0C) < 0) return -1;

    return 0;
}

static int read_touch_status(uint16_t *status) {
    int rc = i2cReadWordData(i2c_handle, MPR121_TOUCHSTATUS_L);
    if (rc < 0) {
        fprintf(stderr, "Error reading touch status: %s\n", pigpio_error(rc));
