        uint16_t touch_status = 0;
        if (read_touch_status(&touch_status) < 0) {
            gpioDelay(100000);
            continue;
        }

        uint16_t fresh_touch = touch_status & 0x0001;
        if (fresh_touch && !prev_touch) {
            gpioDelay(200000);
            if ((touch_status & 0x0001) && !prev_touch) {
                relay_state = !relay_state;
                if (gpioWrite(RELAY_GPIO, relay_state) < 0) {
                    fprintf(stderr, "Error writing relay GPIO %d\n", RELAY_GPIO);
                } else {
                    printf("Relay toggled to %s\n", relay_state ? "ON" : "OFF");
                }
            }
        }
        prev_touch = touch_status;

        gpioDelay(10000);
    }

    printf("\nShutting down...\n");
    gpioWrite(RELAY_GPIO, 0);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

