#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>
#include <syslog.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <gpiod.h>

#define SERVO_PIN 17
#define PIR_PIN 4
#define PORT 5000
#define LOG_FILE "security.log"
#define PWM_PERIOD_NS 20000000  /* 20 ms -> 50 Hz */
#define PWM_DUTY_NS 1000000     /* 1 ms -> 0% */
#define PWM_RANGE_NS 20000000  /* 20 ms period */
#define MAX_COMMAND_LENGTH 256
#define MAX_BUFFER_SIZE 1024

static volatile sig_atomic_t running = 1;
static int server_fd = -1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *servo_line = NULL;
static struct gpiod_line *pir_line = NULL;

static void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", t);

    syslog(LOG_INFO, "%s: %s", timestamp, message);

    if (log_file) {
        fprintf(log_file, "%s: %s\n", timestamp, message);
        fflush(log_file);
    }
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void *servo_thread(void *arg) {
    (void)arg;
    while (running) {
        int angle = 0;
        if (server_fd >= 0) {
            char buffer[MAX_BUFFER_SIZE];
            ssize_t bytes = recv(server_fd, buffer, sizeof(buffer) - 1, 0);
            if (bytes > 0) {
                buffer[bytes] = '\0';
                char *cmd = strtok(buffer, " \r\n");
                if (cmd && strcmp(cmd, "SERVO") == 0) {
                    angle = atoi(strtok(NULL, " \r\n"));
                    if (angle >= 0 && angle <= 180) {
                        char msg[MAX_COMMAND_LENGTH];
                        snprintf(msg, sizeof(msg), "SERVO: %d", angle);
                        log_event(msg);
                    } else {
                        char msg[MAX_COMMAND_LENGTH];
                        snprintf(msg, sizeof(msg), "ERROR: Invalid servo angle: %d", angle);
                        log_event(msg);
                    }
                }
            }
        }
        if (angle >= 0 && angle <= 180) {
            int pulse_width_ns = (angle * PWM_DUTY_NS) / 180;
            if (gpiod_line_set_value(servo_line, 1) < 0) {
                log_event("ERROR: Failed to set servo line high");
            }
            struct timespec ts_start, ts_end;
            clock_gettime(CLOCK_MONOTONIC, &ts_start);
            while (gpiod_line_set_value(servo_line, 0) < 0) {
                if (!running) break;
            }
            clock_gettime(CLOCK_MONOTONIC, &ts_end);
            long elapsed_ns = (ts_end.tv_sec - ts_start.tv_sec) * 1000000000L +
                              (ts_end.tv_nsec - ts_start.tv_nsec);
            if (elapsed_ns < PWM_PERIOD_NS) {
                elapsed_ns = PWM_PERIOD_NS;
            }
            if (gpiod_line_set_value(servo_line, 1) < 0) {
                log_event("ERROR: Failed to set servo line high");
            }
            clock_gettime(CLOCK_MONOTONIC, &ts_end);
            elapsed_ns = (ts_end.tv_sec - ts_start.tv_sec) * 1000000000L +
                        (ts_end.tv_nsec - ts_start.tv_nsec);
            if (elapsed_ns > PWM_PERIOD_NS) {
                elapsed_ns = PWM_PERIOD_NS;
            }
        } else {
            if (gpiod_line_set_value(servo_line, 0) < 0) {
                log_event("ERROR: Failed to set servo line low");
            }
        }
        usleep(10000);
    }
    return NULL;
}

static void cleanup(void) {
    if (servo_line) {
        gpiod_line_set_value(servo_line, 0);
        gpiod_line_release(servo_line);
        servo_line = NULL;
    }
    if (pir_line) {
        gpiod_line_release(pir_line);
        pir_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (server_fd >= 0) {
        close(server_fd);
        server_fd = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    closelog();
}

int main(void) {
    openlog("security_server", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "Failed to set signal handlers: %s", strerror(errno));
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        syslog(LOG_ERR, "Failed to open log file: %s", strerror(errno));
        return 1;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        syslog(LOG_ERR, "Failed to open gpiochip4: %s", strerror(errno));
        fclose(log_file);
        log_file = NULL;
        return 1;
    }

    servo_line = gpiod_chip_get_line(chip, SERVO_PIN);
    if (!servo_line) {
        syslog(LOG_ERR, "Failed to get servo line %d: %s", SERVO_PIN, strerror(errno));
        cleanup();
        return 1;
    }

    pir_line = gpiod_chip_get_line(chip, PIR_PIN);
    if (!pir_line) {
        syslog(LOG_ERR, "Failed to get PIR line %d: %s", PIR_PIN, strerror(errno));
        cleanup();
        return 1;
    }

    if (gpiod_line_request_output(servo_line, "servo", 0) < 0) {
        syslog(LOG_ERR, "Failed to request servo line as output: %s", strerror(errno));
        cleanup();
        return 1;
    }

    if (gpiod_line_request_input(pir_line, "pir") < 0) {
        syslog(LOG_ERR, "Failed to request PIR line as input: %s", strerror(errno));
        cleanup();
        return 1;
    }

    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        syslog(LOG_ERR, "Failed to create socket: %s", strerror(errno));
        cleanup();
        return 1;
    }

    int opt = 1;
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        syslog(LOG_ERR, "Failed to set SO_REUSEADDR: %s", strerror(errno));
        cleanup();
        return 1;
    }

    struct sockaddr_in address;
    memset(&address, 0, sizeof(address));
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        syslog(LOG_ERR, "Failed to bind socket: %s", strerror(errno));
        cleanup();
        return 1;
    }

    if (listen(server_fd, 3) < 0) {
        syslog(LOG_ERR, "Failed to listen on socket: %s", strerror(errno));
        cleanup();
        return 1;
    }

    syslog(LOG_INFO, "Security server listening on port %d", PORT);

    pthread_t servo_thread_id;
    if (pthread_create(&servo_thread_id, NULL, servo_thread, NULL) != 0) {
        syslog(LOG_ERR, "Failed to create servo thread: %s", strerror(errno));
        cleanup();
        return 1;
    }

    while (running) {
        struct sockaddr_in client_addr;
        socklen_t addrlen = sizeof(client_addr);
        int new_socket = accept(server_fd, (struct sockaddr *)&client_addr, &addrlen);
        if (new_socket < 0) {
            if (errno == EINTR && !running) break;
            syslog(LOG_ERR, "Failed to accept connection: %s", strerror(errno));
            continue;
        }

        char client_ip[INET_ADDRSTRLEN];
        inet_ntop(AF_INET, &client_addr.sin_addr, client_ip, sizeof(client_ip));
        syslog(LOG_INFO, "Connection accepted from %s:%d", client_ip, ntohs(client_addr.sin_port));

        char buffer[MAX_BUFFER_SIZE];
        ssize_t bytes = recv(new_socket, buffer, sizeof(buffer) - 1, 0);
        if (bytes > 0) {
            buffer[bytes] = '\0';
            char *cmd = strtok(buffer, " \r\n");
            if (cmd && strcmp(cmd, "PIR") == 0) {
                int pir_value = gpiod_line_get_value(pir_line);
                char response[MAX_COMMAND_LENGTH];
                snprintf(response, sizeof(response), "PIR: %d", pir_value);
                send(new_socket, response, strlen(response), 0);
            } else {
                send(new_socket, "Invalid command", 13, 0);
            }
        } else if (bytes == 0) {
            syslog(LOG_INFO, "Client disconnected");
        } else {
            syslog(LOG_ERR, "Failed to receive data: %s", strerror(errno));
        }
        close(new_socket);
    }

    syslog(LOG_INFO, "Shutting down...");
    pthread_join(servo_thread_id, NULL);
    cleanup();
    return 0;
}

