        return -1;
    }

    gpioDelay(BH1750_CONV_TIME_MS * 1000);

    ret = i2cReadDevice(i2c_handle, buf, 2);
    if (ret != 2) {
        fprintf(stderr, "Error: i2cReadDevice returned %d (expected 2).\n", ret);
        return -1;
