#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <getopt.h>
#include <errno.h>
#include <gpiod.h>

#define HX711_DOUT_PIN  23
#define HX711_SCK_PIN   24
#define SOLENOID_PIN    25

#define DEFAULT_THRESHOLD 1000
#define DEFAULT_SCALE     100.0
#define DEFAULT_DURATION  200
#define POLL_INTERVAL_MS  500
#define MAX_RETRIES       3
#define TARE_SAMPLES      10
#define READ_SAMPLES      5
#define TARE_TIMEOUT_MS   1000

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int hx711_read(struct gpiod_line *dout, struct gpiod_line *sck, long *raw_out) {
    int i, j;
    long value = 0;
    int ready = 0;
    struct timespec ts = {0, 1000};

    /* Wait for DOUT to go LOW (data ready) */
    for (i = 0; i < TARE_TIMEOUT_MS; i++) {
        if (gpiod_line_get_value(dout) == 0) {
            ready = 1;
            break;
        }
        if (nanosleep(&ts, NULL) < 0 && errno != EINTR) {
            syslog(LOG_ERR, "nanosleep failed: %s", strerror(errno));
            return -1;
        }
    }
    if (!ready) {
        syslog(LOG_ERR, "HX711 DOUT timeout after %d ms", TARE_TIMEOUT_MS);
        return -1;
    }

    /* Read 24 bits MSB-first */
    for (i = 0; i < 24; i++) {
        if (gpiod_line_set_value(sck, 1) < 0) {
            syslog(LOG_ERR, "SCK high failed: %s", strerror(errno));
            return -1;
        }
        nanosleep(&ts, NULL);
        value <<= 1;
        if (gpiod_line_get_value(dout) == 1) {
            value |= 1;
        }
        if (gpiod_line_set_value(sck, 0) < 0) {
            syslog(LOG_ERR, "SCK low failed: %s", strerror(errno));
            return -1;
        }
        nanosleep(&ts, NULL);
    }

    /* 25th clock pulse: Channel A, Gain 128 */
    if (gpiod_line_set_value(sck, 1) < 0) {
        syslog(LOG_ERR, "SCK 25th high failed: %s", strerror(errno));
        return -1;
    }
    nanosleep(&ts, NULL);
    if (gpiod_line_set_value(sck, 0) < 0) {
        syslog(LOG_ERR, "SCK 25th low failed: %s", strerror(errno));
        return -1;
    }
    nanosleep(&ts, NULL);

    /* Convert 24-bit two's complement to signed 32-bit */
    if (value & 0x800000) {
        value |= 0xFF000000L;
    }
    *raw_out = value;
    return 0;
}

static long tare_readings(struct gpiod_line *dout, struct gpiod_line *sck, int samples) {
    long sum = 0;
    int i;
    for (i = 0; i < samples; i++) {
        long raw;
        if (hx711_read(dout, sck, &raw) < 0) {
            syslog(LOG_ERR, "Tare read %d failed", i);
            return -1;
        }
        sum += raw;
        usleep(10000);
    }
    return sum / samples;
}

static long read_weight(struct gpiod_line *dout, struct gpiod_line *sck, long tare_offset, double scale) {
    long sum = 0;
    int i;
    for (i = 0; i < READ_SAMPLES; i++) {
        long raw;
        if (hx711_read(dout, sck, &raw) < 0) {
            syslog(LOG_ERR, "Weight read %d failed", i);
            return -1;
        }
        sum += raw;
        usleep(10000);
    }
    return (sum / READ_SAMPLES) - tare_offset;
}

static void set_solenoid(struct gpiod_line *solenoid, int duration_ms) {
    if (gpiod_line_set_value(solenoid, 1) < 0) {
        syslog(LOG_ERR, "Failed to set solenoid HIGH: %s", strerror(errno));
        return;
    }
    usleep(duration_ms * 1000);
    if (gpiod_line_set_value(solenoid, 0) < 0) {
        syslog(LOG_ERR, "Failed to set solenoid LOW: %s", strerror(errno));
    }
}

int main(int argc, char *argv[]) {
    int opt;
    long threshold = DEFAULT_THRESHOLD;
    double scale = DEFAULT_SCALE;
    int duration_ms = DEFAULT_DURATION;

    openlog("weight_monitor", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "sigaction failed: %s", strerror(errno));
        closelog();
        return 1;
    }

    while ((opt = getopt(argc, argv, "t:s:d:")) != -1) {
        switch (opt) {
            case 't':
                threshold = atol(optarg);
                if (threshold <= 0) {
                    syslog(LOG_ERR, "Invalid threshold: %s", optarg);
                    closelog();
                    return 1;
                }
                break;
            case 's':
                scale = atof(optarg);
                if (scale <= 0) {
                    syslog(LOG_ERR, "Invalid scale: %s", optarg);
                    closelog();
                    return 1;
                }
                break;
            case 'd':
                duration_ms = atoi(optarg);
                if (duration_ms <= 0) {
                    syslog(LOG_ERR, "Invalid duration: %s", optarg);
                    closelog();
                    return 1;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold] [-s scale] [-d duration_ms]\n", argv[0]);
                closelog();
                return 1;
        }
    }

    syslog(LOG_INFO, "Starting weight monitoring (threshold=%ld g, scale=%.2f, duration=%d ms)",
           threshold, scale, duration_ms);

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "Failed to open gpiochip0: %s", strerror(errno));
        closelog();
        return 1;
    }

    struct gpiod_line *dout = gpiod_chip_get_line(chip, HX711_DOUT_PIN);
    struct gpiod_line *sck = gpiod_chip_get_line(chip, HX711_SCK_PIN);
    struct gpiod_line *solenoid = gpiod_chip_get_line(chip, SOLENOID_PIN);
    if (!dout || !sck || !solenoid) {
        syslog(LOG_ERR, "Failed to get GPIO lines: %s", strerror(errno));
        gpiod_chip_close(chip);
        closelog();
        return 1;
    }

    if (gpiod_line_request_input(dout, "hx711_dout") < 0) {
        syslog(LOG_ERR, "Failed to request DOUT as input: %s", strerror(errno));
        gpiod_chip_close(chip);
        closelog();
        return 1;
    }
    if (gpiod_line_request_output(sck, "hx711_sck", 0) < 0) {
        syslog(LOG_ERR, "Failed to request SCK as output: %s", strerror(errno));
        gpiod_line_release(dout);
        gpiod_chip_close(chip);
        closelog();
        return 1;
    }
    if (gpiod_line_request_output(solenoid, "solenoid", 0) < 0) {
        syslog(LOG_ERR, "Failed to request solenoid as output: %s", strerror(errno));
        gpiod_line_release(dout);
        gpiod_line_release(sck);
        gpiod_chip_close(chip);
        closelog();
        return 1;
    }

    long tare_offset = tare_readings(dout, sck, TARE_SAMPLES);
    if (tare_offset == -1) {
        syslog(LOG_ERR, "Tare failed");
        gpiod_line_release(dout);
        gpiod_line_release(sck);
        gpiod_line_release(solenoid);
        gpiod_chip_close(chip);
        closelog();
        return 1;
    }
    syslog(LOG_INFO, "Tare complete, offset=%ld", tare_offset);

    while (g_running) {
        long weight = read_weight(dout, sck, tare_offset, scale);
        if (weight == -1) {
            syslog(LOG_ERR, "Weight read failed");
            break;
        }

        if (weight > threshold) {
            set_solenoid(solenoid, duration_ms);
        }

        syslog(LOG_INFO, "Weight: %ld g", weight);
        usleep(POLL_INTERVAL_MS * 1000);
    }

    syslog(LOG_INFO, "Shutting down");
    gpiod_line_set_value(solenoid, 0);
    gpiod_line_release(dout);
    gpiod_line_release(sck);
    gpiod_line_release(solenoid);
    gpiod_chip_close(chip);
    closelog();
    return 0;
}

