    if (!chip) {
        syslog(LOG_ERR, "Failed to open gpiochip0: %s", strerror(errno));
        closelog();
        return 1;
    }

    struct gpiod_line *dout = gpiod_chip_get_line(chip, HX711_DOUT_PIN);
    struct gpiod_line *sck = gpiod_chip_get_line(chip, HX711_SCK_PIN);
    struct gpiod_line *solenoid = gpiod_chip_get_line(chip, SOLENOID_PIN);
    if (!dout || !sck || !solenoid) {
        syslog(LOG_ERR, "Failed to get GPIO lines: %s", strerror(errno));
        gpiod_chip_close(chip);
        closelog();
        return 1;
    }

    if (gpiod_line_request_input(dout, "hx711_dout") < 0) {
        syslog(LOG_ERR, "Failed to request DOUT as input: %s", strerror(errno));
        gpiod_chip_close(chip);
        closelog();
        return 1;
    }
    if (gpiod_line_request_output(sck, "hx711_sck", 0) < 0) {
        syslog(LOG_ERR, "Failed to request SCK as output: %s", strerror(errno));
        gpiod_line_release(dout);
        gpiod_chip_close(chip);
        closelog();
        return 1;
    }
    if (gpiod_line_request_output(solenoid, "solenoid", 0) < 0) {
        syslog(LOG_ERR, "Failed to request solenoid as output: %s", strerror(errno));
        gpiod_line_release(dout);
        gpiod_line_release(sck);
        gpiod_chip_close(chip);
        closelog();
        return 1;
    }

    long tare_offset = tare_readings(dout, sck, TARE_SAMPLES);
    if (tare_offset == -1) {
        syslog(LOG_ERR, "Tare failed");
        gpiod_line_release(dout);
        gpiod_line_release(sck);
        gpiod_line_release(solenoid);
        gpiod_chip_close(chip);
        closelog();
        return 1;
    }
    syslog(LOG_INFO, "Tare complete, offset=%ld", tare_offset);

    while (g_running) {
        long weight = read_weight(dout, sck, tare_offset, scale);
        if (weight == -1) {
            syslog(LOG_ERR, "Weight read failed");
            break;
        }

        if (weight > threshold) {
            set_solenoid(solenoid, duration_ms);
        }

        syslog(LOG_INFO, "Weight: %ld g", weight);
        usleep(POLL_INTERVAL_MS * 1000);
    }

    syslog(LOG_INFO, "Shutting down");
    gpiod_line_set_value(solenoid, 0);
    gpiod_line_release(dout);
    gpiod_line_release(sck);
    gpiod_line_release(solenoid);
    gpiod_chip_close(chip);
    closelog();
    return 0;
