/*
 * relay_controller.c — MQTT relay controller for Raspberry Pi 4 Model B
 *
 * Subscribes to home/lights/control and toggles GPIO17 (BCM 17, physical
 * pin 11) on receipt of "ON" or "OFF".  Uses libmosquitto for MQTT and
 * pigpio for GPIO control.  Build: gcc -O2 -Wall -Wextra -o relay_controller \
 *   relay_controller.c -lmosquitto -lpigpio -lrt
 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <syslog.h>
#include <errno.h>
#include <stdbool.h>
#include <pigpio.h>
#include <mosquitto.h>

#define MQTT_BROKER_ADDRESS      "localhost"
#define MQTT_BROKER_PORT          1883
#define MQTT_CLIENT_ID            "relay_controller_1"
#define MQTT_TOPIC                "home/lights/control"
#define MQTT_KEEPALIVE_INTERVAL   60
#define MQTT_MAX_PAYLOAD_LEN      256
#define GPIO_PIN                 17
#define GPIO_PUD_OFF              0
#define GPIO_MODE_OUTPUT          1
#define GPIO_INITIAL_STATE       0
#define MQTT_RECONNECT_DELAY_SEC  5
#define MQTT_MAX_RETRIES          10

static volatile sig_atomic_t g_running = 1;
static struct mosquitto *g_mosq = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* GPIO helpers                                                         */
/* ------------------------------------------------------------------ */
static int gpio_init(void)
{
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed: %s", strerror(errno));
        return -1;
    }

    if (gpioSetMode(GPIO_PIN, GPIO_MODE_OUTPUT) != 0) {
        syslog(LOG_ERR, "gpioSetMode(%d, OUTPUT) failed", GPIO_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPullUpDown(GPIO_PIN, GPIO_PUD_OFF) != 0) {
        syslog(LOG_WARNING, "gpioSetPullUpDown(%d, OFF) failed", GPIO_PIN);
    }

    if (gpioWrite(GPIO_PIN, GPIO_INITIAL_STATE) != 0) {
        syslog(LOG_ERR, "gpioWrite(%d, %d) failed", GPIO_PIN, GPIO_INITIAL_STATE);
        gpioTerminate();
        return -1;
    }

    syslog(LOG_INFO, "GPIO %d configured as output, initial state %s",
           GPIO_PIN, GPIO_INITIAL_STATE ? "LOW (relay OFF)" : "HIGH (relay ON)");
    return 0;
}

static void gpio_set_relay(int on)
{
    if (gpioWrite(GPIO_PIN, on ? 1 : 0) != 0) {
        syslog(LOG_ERR, "gpioWrite(%d, %d) failed", GPIO_PIN, on ? 1 : 0);
    }
}

/* ------------------------------------------------------------------ */
/* MQTT helpers                                                        */
/* ------------------------------------------------------------------ */
static void mqtt_connect_callback(struct mosquitto *mosq, void *userdata,
                                  int result)
{
    (void)userdata;
    if (result == MOSQ_ERR_SUCCESS) {
        syslog(LOG_INFO, "Connected to MQTT broker at %s:%d",
               MQTT_BROKER_ADDRESS, MQTT_BROKER_PORT);
        int rc = mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, 0);
        if (rc != MOSQ_ERR_SUCCESS) {
            syslog(LOG_ERR, "mosquitto_subscribe(%s, QoS 0) failed: %s",
                   MQTT_TOPIC, mosquitto_strerror(rc));
        } else {
            syslog(LOG_INFO, "Subscribed to %s", MQTT_TOPIC);
        }
    } else {
        syslog(LOG_ERR, "MQTT connect failed: %s", mosquitto_connack_string(result));
    }
}

static void mqtt_disconnect_callback(struct mosquitto *mosq, void *userdata,
                                     int rc)
{
    (void)mosq;
    (void)userdata;
    syslog(LOG_WARNING, "MQTT disconnected: %s", mosquitto_strerror(rc));
}

static void mqtt_message_callback(struct mosquitto *mosq, void *userdata,
                                  const struct mosquitto_message *message)
{
    (void)mosq;
    (void)userdata;

    if (message->payloadlen > 0 && message->payloadlen < MQTT_MAX_PAYLOAD_LEN) {
        char payload[MQTT_MAX_PAYLOAD_LEN];
        int len = message->payloadlen;
        memcpy(payload, message->payload, len);
        payload[len] = '\0';

        syslog(LOG_INFO, "Received message on %s: %s", message->topic, payload);

        if (strcmp(payload, "ON") == 0) {
            gpio_set_relay(1);
            syslog(LOG_INFO, "Relay ON");
        } else if (strcmp(payload, "OFF") == 0) {
            gpio_set_relay(0);
            syslog(LOG_INFO, "Relay OFF");
        } else {
            syslog(LOG_ERR, "Invalid payload: '%s'", payload);
        }
    } else {
        syslog(LOG_ERR, "Payload length out of range: %d", message->payloadlen);
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_mosq) {
        mosquitto_disconnect(g_mosq);
        mosquitto_destroy(g_mosq);
        g_mosq = NULL;
    }
    mosquitto_lib_cleanup();
    gpioTerminate();
    closelog();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    openlog("mqtt_relay", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "sigaction failed: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    if (gpio_init() != 0) {
        syslog(LOG_ERR, "GPIO initialization failed, exiting");
        closelog();
        return EXIT_FAILURE;
    }

    g_mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!g_mosq) {
        syslog(LOG_ERR, "mosquitto_new failed: %s", strerror(errno));
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    mosquitto_connect_callback_set(g_mosq, mqtt_connect_callback);
    mosquitto_disconnect_callback_set(g_mosq, mqtt_disconnect_callback);
    mosquitto_message_callback_set(g_mosq, mqtt_message_callback);

    int rc = mosquitto_connect(g_mosq, MQTT_BROKER_ADDRESS, MQTT_BROKER_PORT,
                               MQTT_KEEPALIVE_INTERVAL);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "mosquitto_connect failed: %s", mosquitto_strerror(rc));
        mosquitto_destroy(g_mosq);
        g_mosq = NULL;
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    while (g_running) {
        rc = mosquitto_loop(g_mosq, 100, 1);
        if (rc != MOSQ_ERR_SUCCESS) {
            syslog(LOG_ERR, "mosquitto_loop error: %s", mosquitto_strerror(rc));
            if (rc == MOSQ_ERR_CONN_LOST || rc == MOSQ_ERR_NO_CONN) {
                syslog(LOG_WARNING, "Broker disconnected, re-connecting in %d s",
                       MQTT_RECONNECT_DELAY_SEC);
                sleep(MQTT_RECONNECT_DELAY_SEC);
                rc = mosquitto_reconnect(g_mosq);
                if (rc != MOSQ_ERR_SUCCESS) {
                    syslog(LOG_ERR, "mosquitto_reconnect failed: %s",
                           mosquitto_strerror(rc));
                }
            } else {
                syslog(LOG_ERR, "Unexpected loop error, retrying in 1 s");
                sleep(1);
            }
            continue;
        }
        if (!g_running) break;
    }

    cleanup();
    return EXIT_SUCCESS;
}

