#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>

#define SERVO1_PIN 7
#define SERVO2_PIN 8
#define SERVO3_PIN 9
#define SERVO4_PIN 10
#define SERVO5_PIN 11

#define SERVO1_POSITION 1000
#define SERVO2_POSITION 1500
#define SERVO3_POSITION 2000
#define SERVO4_POSITION 500
#define SERVO5_POSITION 2500

#define PWM_FREQUENCY 50
#define PWM_RANGE 20000

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set PWM frequency and range for each pin
    gpioSetPWMfrequency(SERVO1_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(SERVO2_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(SERVO3_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(SERVO4_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(SERVO5_PIN, PWM_FREQUENCY);

    gpioSetPWMrange(SERVO1_PIN, PWM_RANGE);
    gpioSetPWMrange(SERVO2_PIN, PWM_RANGE);
    gpioSetPWMrange(SERVO3_PIN, PWM_RANGE);
    gpioSetPWMrange(SERVO4_PIN, PWM_RANGE);
    gpioSetPWMrange(SERVO5_PIN, PWM_RANGE);

    // Set initial positions (pulse width = position in microseconds)
    gpioServo(SERVO1_PIN, SERVO1_POSITION);
    gpioServo(SERVO2_PIN, SERVO2_POSITION);
    gpioServo(SERVO3_PIN, SERVO3_POSITION);
    gpioServo(SERVO4_PIN, SERVO4_POSITION);
    gpioServo(SERVO5_PIN, SERVO5_POSITION);

    // Hold for 3 seconds
    gpioDelay(3000000);

    // Stop PWM signals
    gpioServo(SERVO1_PIN, 0);
    gpioServo(SERVO2_PIN, 0);
    gpioServo(SERVO3_PIN, 0);
    gpioServo(SERVO4_PIN, 0);
    gpioServo(SERVO5_PIN, 0);

    gpioTerminate();
    return 0;
}

