#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* Motor A */
#define MOTOR_A_PWM_PIN 17
#define MOTOR_A_DIR_PIN 18
/* Motor B */
#define MOTOR_B_PWM_PIN 22
#define MOTOR_B_DIR_PIN 23

/* Encoder A */
#define ENC_A_A_PIN 4
#define ENC_A_B_PIN 5
/* Encoder B */
#define ENC_B_A_PIN 6
#define ENC_B_B_PIN 12

#define PWM_FREQUENCY 10000
#define PWM_RANGE 255
#define TARGET_SPEED 50.0
#define KP 0.5
#define KI 0.05
#define STALL_TIMEOUT_SEC 2
#define LOOP_DELAY_US 100000

static volatile int running = 1;
static volatile int encoder_a_count = 0;
static volatile int encoder_b_count = 0;
static volatile int encoder_a_last_tick = 0;
static volatile int encoder_b_last_tick = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void motor_a_forward(void) {
    gpioWrite(MOTOR_A_DIR_PIN, 1);
    gpioPWM(MOTOR_A_PWM_PIN, PWM_RANGE);
}

static void motor_a_backward(void) {
    gpioWrite(MOTOR_A_DIR_PIN, 0);
    gpioPWM(MOTOR_A_PWM_PIN, PWM_RANGE);
}

static void motor_b_forward(void) {
    gpioWrite(MOTOR_B_DIR_PIN, 1);
    gpioPWM(MOTOR_B_PWM_PIN, PWM_RANGE);
}

static void motor_b_backward(void) {
    gpioWrite(MOTOR_B_DIR_PIN, 0);
    gpioPWM(MOTOR_B_PWM_PIN, PWM_RANGE);
}

