#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define BH1750_ADDR 0x23
#define I2C_BUS 1
#define RELAY_GPIO 17
#define LUX_THRESHOLD_DAWN 50
#define LUX_THRESHOLD_DUSK 200
#define POLL_INTERVAL_SEC 5
#define BH1750_CONV_TIME_US 180000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_message(const char *msg) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s: %s\n", ts, msg);
    fflush(log_file);
}

static int init_pigpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return -1;
    }
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0);
    return 0;
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X: %d\n",
                I2C_BUS, BH1750_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

static int read_lux(float *lux_out) {
    char cmd = 0x21; /* One-Time High-Resolution Mode 2 (~120ms) */
    char buf[2];

    if (i2cWriteDevice(i2c_handle, &cmd, 1) != 0) {
        fprintf(stderr, "I2C write failed\n");
        return -1;
    }
    gpioDelay(BH1750_CONV_TIME_US);

    if (i2cReadDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "I2C read failed\n");
        return -1;
    }

    unsigned int raw = ((unsigned int)(unsigned char)buf[0] << 8) |
                       (unsigned int)(unsigned char)buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static void control_relay(int state) {
    if (gpioWrite(RELAY_GPIO, state ? 1 : 0) != 0) {
        fprintf(stderr, "Failed to write relay GPIO %d\n", RELAY_GPIO);
        return;
    }
    log_message(state ? "Relay ON" : "Relay OFF");
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();
    if (log_file) {
        log_message("Program terminated");
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (init_pigpio() != 0) return 1;
    if (init_i2c() != 0) { gpioTerminate(); return 1; }

    log_file = fopen("chicken_coop_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        cleanup();
        return 1;
    }

    log_message("Program started");

    int relay_state = 0;
    while (running) {
        float lux;
        if (read_lux(&lux) != 0) {
            fprintf(stderr, "Sensor read error; turning off relay\n");
            control_relay(0);
            relay_state = 0;
            sleep(POLL_INTERVAL_SEC);
            continue;
        }

        char msg[128];
        snprintf(msg, sizeof(msg), "Lux = %.1f", lux);
        log_message(msg);

        if (lux < LUX_THRESHOLD_DUSK && relay_state == 0) {
            control_relay(1);
            relay_state = 1;
        } else if (lux > LUX_THRESHOLD_DAWN && relay_state == 1) {
            control_relay(0);
            relay_state = 0;
        }

        sleep(POLL_INTERVAL_SEC);
    }

    cleanup();
    return 0;
}

