#include <errno.h>

#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17
#define DEBOUNCE_DELAY_MS 50
#define LOOP_DELAY_MS 10

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_state(int state) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    printf("[%s] Relay is now %s\n", timestamp, state ? "ON" : "OFF");
    fflush(stdout);
}

int main(void) {
    int relay_state = 0;
    int last_touch_state = 0;
    int first_touch = 1;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed (code %d).\n", gpioInitialise());
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input.\n", TOUCH_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", RELAY_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(RELAY_PIN, relay_state) != 0) {
        fprintf(stderr, "Error: failed to initialize relay state on GPIO %d.\n", RELAY_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Warning: could not register SIGINT handler: %s\n", strerror(errno));
    }

    printf("Touch-controlled relay started. Touch sensor on GPIO %d, relay on GPIO %d.\n",
           TOUCH_SENSOR_PIN, RELAY_PIN);
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (running) {
        int touch_state = gpioRead(TOUCH_SENSOR_PIN);
        if (touch_state < 0) {
            fprintf(stderr, "Error: failed to read GPIO %d (code %d).\n", TOUCH_SENSOR_PIN, touch_state);
            break;
        }

        if (touch_state == 1 && last_touch_state == 0) {
            if (first_touch) {
                first_touch = 0;
            } else {
                gpioDelay(DEBOUNCE_DELAY_MS * 1000);
                int touch_state2 = gpioRead(TOUCH_SENSOR_PIN);
                if (touch_state2 == 1) {
                    relay_state = !relay_state;
                    if (gpioWrite(RELAY_PIN, relay_state) != 0) {
                        fprintf(stderr, "Error: failed to write GPIO %d.\n", RELAY_PIN);
                        break;
                    }
                    log_state(relay_state);
                    gpioDelay(DEBOUNCE_DELAY_MS * 1000);
                }
            }
        }

        last_touch_state = touch_state;
        gpioDelay(LOOP_DELAY_MS * 1000);
    }

    gpioWrite(RELAY_PIN, 0);
    gpioTerminate();
    printf("\nExiting gracefully...\n");
    return EXIT_SUCCESS;
}

