#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <pigpio.h>
#include <unistd.h>

#define FLOW_SENSOR_GPIO 17
#define SOLENOID_GPIO 27
#define PULSES_PER_LITER 450.0
#define LPM_THRESHOLD_HIGH 5.0
#define LPM_THRESHOLD_LOW 4.5
#define HYSTERESIS 0.5
#define LOG_FILE "water_flow.log"
#define SAMPLE_INTERVAL_US 1000000
#define DEBOUNCE_US 1000000

static volatile int pulse_count = 0;
static pthread_mutex_t pulse_mutex = PTHREAD_MUTEX_INITIALIZER;
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;

static void log_event(const char *message) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fflush(log_file);
}

static void pulse_callback(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio; (void)level; (void)tick; (void)userdata;
    pthread_mutex_lock(&pulse_mutex);
    pulse_count++;
    pthread_mutex_unlock(&pulse_mutex);
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    if (gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set flow sensor pin mode\n");
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(SOLENOID_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set solenoid pin mode\n");
        gpioTerminate();
        return -1;
    }
    if (gpioSetPullUpDown(FLOW_SENSOR_GPIO, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set pull-down on flow sensor pin\n");
        gpioTerminate();
        return -1;
    }
    if (gpioWrite(SOLENOID_GPIO, 1) != 0) {
        fprintf(stderr, "Failed to set solenoid initial state\n");
        gpioTerminate();
        return -1;
    }
    if (gpioSetISRFuncEx(FLOW_SENSOR_GPIO, RISING_EDGE, DEBOUNCE_US, pulse_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR function for flow sensor\n");
        gpioTerminate();
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    gpioWrite(SOLENOID_GPIO, 1);
    if (log_file) {
        log_event("Solenoid valve reopened (safe state).");
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
    pthread_mutex_destroy(&pulse_mutex);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (initialize_gpio() != 0) {
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen");
        gpioWrite(SOLENOID_GPIO, 0);
        gpioTerminate();
        pthread_mutex_destroy(&pulse_mutex);
        return 1;
    }
    log_event("Water flow monitoring started.");

    while (running) {
        int current_count;
        pthread_mutex_lock(&pulse_mutex);
        current_count = pulse_count;
        pulse_count = 0;
        pthread_mutex_unlock(&pulse_mutex);

        double lpm = (double)current_count / PULSES_PER_LITER * 60.0;

        char log_message[128];
        snprintf(log_message, sizeof(log_message), "Flow rate: %.2f LPM", lpm);
        log_event(log_message);

        if (lpm > LPM_THRESHOLD_HIGH) {
            if (gpioWrite(SOLENOID_GPIO, 0) != 0) {
                log_event("Error: Failed to close solenoid valve.");
            } else {
                log_event("Solenoid valve closed (flow rate exceeded threshold).");
            }
        } else if (lpm < LPM_THRESHOLD_LOW) {
            if (gpioWrite(SOLENOID_GPIO, 1) != 0) {
                log_event("Error: Failed to open solenoid valve.");
            } else {
                log_event("Solenoid valve opened (flow rate below threshold).");
            }
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    log_event("Shutting down gracefully.");
    cleanup();
    return 0;
}

