#define DEFAULT_CALIBRATION_FACTOR 500.0
#define DEFAULT_SERVER_IP "127.0.0.1"
#define DEFAULT_SERVER_PORT 12345
#define LOG_FILE "dispensing_log.json"
#define MAX_RETRIES 1000
#define SERVO_MIN_PULSEWIDTH 1000
#define SERVO_MAX_PULSEWIDTH 2000
#define HX711_TIMEOUT_US 1000000

static volatile sig_atomic_t running = 1;
static int server_fd = -1;
static int client_fd = -1;
static double calibration_factor = DEFAULT_CALIBRATION_FACTOR;
static char server_ip[20] = DEFAULT_SERVER_IP;
static int server_port = DEFAULT_SERVER_PORT;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_config(const char *filename) {
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        fprintf(stderr, "Warning: Could not open config file %s: %s. Using defaults.\n", filename, strerror(errno));
        return -1;
    }
    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        char *key = strtok(line, "=\n");
        char *value = strtok(NULL, "\n");
        if (!key || !value) continue;
        if (strcmp(key, "calibration_factor") == 0) {
            calibration_factor = atof(value);
        } else if (strcmp(key, "server_ip") == 0) {
            strncpy(server_ip, value, sizeof(server_ip) - 1);
            server_ip[sizeof(server_ip) - 1] = '\0';
        } else if (strcmp(key, "server_port") == 0) {
            server_port = atoi(value);
        }
    }
    fclose(fp);
    return 0;
}

static int read_hx711(void) {
    int data = 0;
    int i;
    int timeout = 0;
    while (gpioRead(HX711_DATA_PIN) == 1) {
        gpioDelay(1);
        timeout++;
        if (timeout > HX711_TIMEOUT_US) {
            fprintf(stderr, "Error: HX711 timeout waiting for data pin low.\n");
            return -1;
        }
    }
    for (i = 0; i < 24; i++) {
        gpioWrite(HX711_SCK_PIN, 1);
        gpioDelay(1);
        data <<= 1;
        if (gpioRead(HX711_DATA_PIN)) data++;
        gpioWrite(HX711_SCK_PIN, 0);
        gpioDelay(1);
    }
    gpioWrite(HX711_SCK_PIN, 1);
    gpioDelay(1);
    gpioWrite(HX711_SCK_PIN, 0);
    gpioDelay(1);
    data ^= 0x800000;
    return data;
}

static double get_weight(int raw) {
    return (double)raw / calibration_factor;
}

static int set_servo_pulsewidth(int pulsewidth) {
    if (pulsewidth < SERVO_MIN_PULSEWIDTH || pulsewidth > SERVO_MAX_PULSEWIDTH) {
        fprintf(stderr, "Error: Invalid servo pulsewidth %d (must be %d-%d).\n", pulsewidth, SERVO_MIN_PULSEWIDTH, SERVO_MAX_PULSEWIDTH);
        return -1;
    }
    if (gpioServo(SERVO_PIN, pulsewidth) != 0) {
        fprintf(stderr, "Error: gpioServo failed for pulsewidth %d.\n", pulsewidth);
        return -1;
    }
    return 0;
}

static int log_dispensing_event(double target, double actual, const char *error) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error: Could not open log file %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(fp, "{\"timestamp\":\"%s\",\"target_weight\":%.2f,\"actual_weight\":%.2f,\"error\":\"%s\"}\n", timestamp, target, actual, error ? error : "null");
    fclose(fp);
    return 0;
}

static void cleanup(void) {
    if (client_fd >= 0) {
        close(client_fd);
        client_fd = -1;
    }
    if (server_fd >= 0) {
        close(server_fd);
        server_fd = -1;
    }
    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return 1;
    }

    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_SCK_PIN, PI_OUTPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    if (read_config(CONFIG_FILE) != 0) {
        fprintf(stderr, "Warning: Using default configuration.\n");
    }

    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        perror("Error: Could not create socket");
        gpioTerminate();
        return 1;
    }

    int opt = 1;
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        perror("Error: Could not set SO_REUSEADDR");
        cleanup();
        return 1;
    }

    struct sockaddr_in server_addr;
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = inet_addr(server_ip);
    server_addr.sin_port = htons(server_port);

    if (bind(server_fd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("Error: Could not bind socket");
        cleanup();
        return 1;
    }

    if (listen(server_fd, 3) < 0) {
        perror("Error: Could not listen on socket");
        cleanup();
        return 1;
    }

    printf("Listening on %s:%d...\n", server_ip, server_port);

    while (running) {
        struct sockaddr_in client_addr;
        socklen_t client_len = sizeof(client_addr);
        client_fd = accept(server_fd, (struct sockaddr *)&client_addr, &client_len);
        if (client_fd < 0) {
            if (running) perror("Error: Could not accept connection");
            continue;
        }
        printf("Connection accepted from %s:%d\n", inet_ntoa(client_addr.sin_addr), ntohs(client_addr.sin_port));

        char buffer[1024];
        ssize_t bytes = recv(client_fd, buffer, sizeof(buffer) - 1, 0);
        if (bytes > 0) {
            buffer[bytes] = '\0';
            char *endptr;
            double target = strtod(buffer, &endptr);
            if (endptr != buffer && *endptr == '\n' || *endptr == '\0') {
                printf("Target weight: %.2f g\n", target);
                int raw = read_hx711();
                if (raw < 0) {
                    fprintf(stderr, "Error: Failed to read HX711.\n");
                    log_dispensing_event(target, 0.0, "HX711 read error");
                } else {
                    double actual = get_weight(raw);
                    printf("Actual weight: %.2f g\n", actual);
                    if (send(client_fd, "OK", 2, 0) < 0) {
                        perror("Error: Could not send response");
                    }
                    log_dispensing_event(target, actual, NULL);
                }
            } else {
                fprintf(stderr, "Error: Invalid weight format: %s\n", buffer);
                log_dispensing_event(target, 0.0, "Invalid weight format");
            }
        } else if (bytes == 0) {
            printf("Client disconnected.\n");
        } else {
            perror("Error: Could not receive data from client");
        }
        close(client_fd);
        client_fd = -1;
    }

    cleanup();
    return 0;
}

