#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17
#define DEBOUNCE_MS 50
#define POLL_DELAY_US 10000

static volatile sig_atomic_t running = 1;
static int relay_state = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_relay_state(int state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s Relay: %s\n", timestamp, state ? "ON" : "OFF");
    fflush(stdout);
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input\n", TOUCH_SENSOR_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output\n", RELAY_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioWrite(RELAY_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise relay state to LOW\n");
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void cleanup(void) {
    gpioWrite(RELAY_PIN, 0);
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    int debounce_ms = DEBOUNCE_MS;

    if (argc > 1) {
        char *endptr;
        long val = strtol(argv[1], &endptr, 10);
        if (*endptr != '\0' || val <= 0 || val > 10000) {
            fprintf(stderr, "Usage: %s [-d <milliseconds>]\n", argv[0]);
            return EXIT_FAILURE;
        }
        debounce_ms = (int)val;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("Touch-controlled desk lamp started. Touch sensor on GPIO %d, relay on GPIO %d. Debounce: %d ms. Press Ctrl+C to exit.\n",
           TOUCH_SENSOR_PIN, RELAY_PIN, debounce_ms);

    int last_touch_state = gpioRead(TOUCH_SENSOR_PIN);
    if (last_touch_state < 0) {
        fprintf(stderr, "Error: failed to read initial touch sensor state\n");
        cleanup();
        return EXIT_FAILURE;
    }

    while (running) {
        int current_touch_state = gpioRead(TOUCH_SENSOR_PIN);
        if (current_touch_state < 0) {
            fprintf(stderr, "Error: failed to read touch sensor state\n");
            break;
        }

        if (current_touch_state == 1 && last_touch_state == 0) {
            relay_state = !relay_state;
            if (gpioWrite(RELAY_PIN, relay_state) != 0) {
                fprintf(stderr, "Error: failed to write relay state\n");
                break;
            }
            log_relay_state(relay_state);
        }

        last_touch_state = current_touch_state;
        gpioDelay(POLL_DELAY_US);
    }

    cleanup();
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

