#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <termios.h>
#include <pigpio.h>

#define SERVO_PIN 18
#define MIN_PULSE_US 500
#define MAX_PULSE_US 2500
#define MIN_ANGLE 0
#define MAX_ANGLE 180
#define SERVO_FREQ_HZ 50
#define SERVO_PERIOD_US 20000
#define SERVO_START_ANGLE 90
#define STEP_ANGLE 10

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_angle(int angle) {
    if (angle < MIN_ANGLE || angle > MAX_ANGLE) {
        fprintf(stderr, "Angle %d out of range [%d, %d]\n", angle, MIN_ANGLE, MAX_ANGLE);
        return -1;
    }
    int pulse_us = MIN_PULSE_US + (angle * (MAX_PULSE_US - MIN_PULSE_US) / MAX_ANGLE);
    if (pulse_us < MIN_PULSE_US || pulse_us > MAX_PULSE_US) {
        fprintf(stderr, "Pulse width %d out of range [%d, %d]\n", pulse_us, MIN_PULSE_US, MAX_PULSE_US);
        return -1;
    }
    if (gpioServo(SERVO_PIN, pulse_us) < 0) {
        fprintf(stderr, "gpioServo failed on pin %d\n", SERVO_PIN);
        return -1;
    }
    return 0;
}

static int restore_terminal(int saved_tty) {
    if (saved_tty < 0) return 0;
    tcsetattr(saved_tty, TCSANOW, &saved_termios);
    if (tcsetattr(STDIN_FILENO, TCSANOW, &saved_termios) != 0) {
        perror("tcsetattr(stdin)");
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    int saved_tty = STDIN_FILENO;
    struct termios saved_termios;
    if (tcgetattr(saved_tty, &saved_termios) != 0) {
        perror("tcgetattr");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (tcgetattr(STDIN_FILENO, &saved_termios) != 0) {
        perror("tcgetattr(stdin)");
        restore_terminal(saved_tty);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    saved_termios.c_lflag &= ~(ICANON | ECHO);
    saved_termios.c_cc[VMIN] = 0;
    saved_termios.c_cc[VTIME] = 0;
    if (tcsetattr(saved_tty, TCSANOW, &saved_termios) != 0) {
        perror("tcsetattr(stdin)");
        restore_terminal(saved_tty);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int angle = SERVO_START_ANGLE;
    if (set_angle(angle) != 0) {
        restore_terminal(saved_tty);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    printf("Servo angle: %d degrees\n", angle);
    fflush(stdout);

    int saved_tty_raw = saved_tty;

    while (running) {
        char c;
        ssize_t n = read(STDIN_FILENO, &c, 1);
        if (n < 0) {
            if (errno == EINTR) continue;
            perror("read");
            break;
        }
        if (n == 0) continue;

        if (c == '+') {
            angle += STEP_ANGLE;
            if (set_angle(angle) != 0) break;
            printf("Servo angle: %d degrees\n", angle);
            fflush(stdout);
        } else if (c == '-') {
            angle -= STEP_ANGLE;
            if (set_angle(angle) != 0) break;
            printf("Servo angle: %d degrees\n", angle);
            fflush(stdout);
        } else if (c == 'q' || c == 'Q') {
            break;
        } else if (c == '\n' || c == '\r') {
            continue;
        }
    }

    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
    restore_terminal(saved_tty_raw);
    return EXIT_SUCCESS;
}

