#include <errno.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME      "gpiochip0"
#define MOTOR_GPIO_LINE     17
#define LOG_FILE            "motor_rpm.log"
#define SAMPLE_INTERVAL_SEC 5
#define DEBOUNCE_MS         2
#define POLL_TIMEOUT_MS     100

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static void log_rpm(FILE *fp, double rpm)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    fprintf(fp, "%s,%.2f\n", timestamp, rpm);
    fflush(fp);
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    FILE *log_fp = NULL;
    struct timespec last_sample, now;
    long long pulse_count = 0;
    int ret;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, MOTOR_GPIO_LINE);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_input_flags(line, "motor_rpm",
                                          GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP);
    if (ret < 0) {
        perror("gpiod_line_request_input_flags");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        perror("fopen");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    clock_gettime(CLOCK_MONOTONIC, &last_sample);

    printf("Monitoring motor RPM on GPIO %d. Press Ctrl+C to exit.\n", MOTOR_GPIO_LINE);

    while (program_running) {
        struct timespec ts = { 0, POLL_TIMEOUT_MS * 1000000L };
        ret = gpiod_line_event_wait(line, &ts);
        if (ret < 0) {
            if (errno == EINTR) continue;
            perror("gpiod_line_event_wait");
            break;
        }
        if (ret == 0) {
            continue;
        }

        struct gpiod_line_event event;
        ret = gpiod_line_event_read(line, &event);
        if (ret < 0) {
            if (errno == EINTR) continue;
            perror("gpiod_line_event_read");
            break;
        }

        if (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
            pulse_count++;
        }

        clock_gettime(CLOCK_MONOTONIC, &now);
        long long elapsed_ms = (now.tv_sec - last_sample.tv_sec) * 1000LL
                             + (now.tv_nsec - last_sample.tv_nsec) / 1000000LL;

        if (elapsed_ms >= SAMPLE_INTERVAL_SEC) {
            double rpm = (double)pulse_count / SAMPLE_INTERVAL_SEC * 60.0;
            log_rpm(log_fp, rpm);
            printf("RPM: %.2f\n", rpm);
            pulse_count = 0;
            last_sample = now;
        }
    }

    printf("\nShutting down...\n");
    if (log_fp) fclose(log_fp);
    if (line) gpiod_line_release(line);
    if (chip) gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

