#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define TOUCH_SENSOR_GPIO 4
#define RELAY_GPIO        17
#define POLL_DELAY_US     50000   /* 50 ms */
#define FAILSAFE_TIMEOUT  10       /* seconds */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int init_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(TOUCH_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(TOUCH_SENSOR_GPIO) failed\n");
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(RELAY_GPIO) failed\n");
        gpioTerminate();
        return -1;
    }

    /* Ensure relay starts in the OFF state */
    if (gpioWrite(RELAY_GPIO, 0) != 0) {
        fprintf(stderr, "Error: gpioWrite(RELAY_GPIO, 0) failed\n");
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void cleanup(void)
{
    /* Release the relay (active-HIGH module) and terminate pigpio */
    gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (init_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("Touch-controlled relay on GPIO%d, sensor on GPIO%d. Press Ctrl+C to exit.\n",
           RELAY_GPIO, TOUCH_SENSOR_GPIO);

    time_t last_touch_time = 0;
    int relay_state = 0;

    while (g_running) {
        int sensor_value = gpioRead(TOUCH_SENSOR_GPIO);

        if (sensor_value == PI_BAD_GPIO) {
            fprintf(stderr, "Error: gpioRead(TOUCH_SENSOR_GPIO) returned PI_BAD_GPIO\n");
            break;
        }

        if (sensor_value == 1) {
            time_t now = time(NULL);
            if (now - last_touch_time >= FAILSAFE_TIMEOUT) {
                /* Failsafe: force relay OFF and reset timeout */
                relay_state = 0;
                if (gpioWrite(RELAY_GPIO, 0) != 0) {
                    fprintf(stderr, "Error: gpioWrite(RELAY_GPIO, 0) during failsafe\n");
                    break;
                }
                last_touch_time = now;
                printf("Failsafe: relay OFF, sensor HIGH for > %d s\n", FAILSAFE_TIMEOUT);
            } else {
                relay_state = !relay_state;
                if (gpioWrite(RELAY_GPIO, relay_state) != 0) {
                    fprintf(stderr, "Error: gpioWrite(RELAY_GPIO, %d) failed\n", relay_state);
                    break;
                }
                printf("Touch detected — relay %s\n", relay_state ? "ON" : "OFF");
                last_touch_time = now;
            }
        } else {
            /* Sensor released: reset timeout */
            last_touch_time = 0;
        }

        gpioDelay(POLL_DELAY_US);
    }

    cleanup();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

