#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define FLOW_SENSOR_GPIO 24
#define VALVE_ENABLE_GPIO 23
#define PWM_GPIO 18
#define PULSES_PER_LITER 450.0
#define SAMPLE_INTERVAL_US 100000
#define PWM_RANGE 255
#define Kp 1.0

static volatile int flow_count = 0;
static volatile int running = 1;
static FILE *log_file = NULL;

static void pulse_callback(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio; (void)level; (void)tick; (void)userdata;
    flow_count++;
}

static double calculate_flow_rate(int pulses) {
    return (double)pulses / PULSES_PER_LITER * 60.0;
}

static int set_valve_position(int position) {
    if (gpioPWM(PWM_GPIO, position) < 0) {
        fprintf(stderr, "Error: gpioPWM failed for position %d\n", position);
        return -1;
    }
    return 0;
}

static int control_flow(double target_flow_rate, double current_flow_rate) {
    double error = target_flow_rate - current_flow_rate;
    int valve_position = (int)(Kp * error);
    if (valve_position < 0) valve_position = 0;
    if (valve_position > PWM_RANGE) valve_position = PWM_RANGE;
    return set_valve_position(valve_position);
}

static void log_data(double flow_rate, int valve_position) {
    if (!log_file) return;
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long timestamp_ms = (ts.tv_sec * 1000) + (ts.tv_nsec / 1000000);
    fprintf(log_file, "%ld,%.2f,%d\n", timestamp_ms, flow_rate, valve_position);
    fflush(log_file);
}

static void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <target_flow_rate_L_per_min>\n", argv[0]);
        return 1;
    }

    double target_flow_rate = atof(argv[1]);
    if (target_flow_rate <= 0.0) {
        fprintf(stderr, "Error: target flow rate must be positive\n");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return 1;
    }

    if (gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set flow sensor GPIO mode\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(VALVE_ENABLE_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set valve enable GPIO mode\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(PWM_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set PWM GPIO mode\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMrange(PWM_GPIO, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: failed to set PWM range\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMfrequency(PWM_GPIO, 1000) < 0) {
        fprintf(stderr, "Error: failed to set PWM frequency\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMdutycycle(PWM_GPIO, 0) < 0) {
        fprintf(stderr, "Error: failed to set initial PWM duty cycle\n");
        gpioTerminate();
        return 1;
    }

    if (gpioWrite(VALVE_ENABLE_GPIO, 1) < 0) {
        fprintf(stderr, "Error: failed to enable valve\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetISRFuncEx(FLOW_SENSOR_GPIO, RISING_EDGE, 0, pulse_callback, NULL) < 0) {
        fprintf(stderr, "Error: failed to set ISR for flow sensor\n");
        gpioWrite(VALVE_ENABLE_GPIO, 0);
        gpioTerminate();
        return 1;
    }

    log_file = fopen("flow_log.csv", "a");
    if (!log_file) {
        fprintf(stderr, "Error: failed to open flow_log.csv\n");
        gpioWrite(VALVE_ENABLE_GPIO, 0);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error: failed to set signal handlers\n");
        fclose(log_file);
        gpioWrite(VALVE_ENABLE_GPIO, 0);
        gpioTerminate();
        return 1;
    }

    printf("Flow control system started. Target: %.2f L/min\n", target_flow_rate);

    while (running) {
        int pulses = 0;
        gpioDelay(SAMPLE_INTERVAL_US);

        int pulses_read = gpioRead(FLOW_SENSOR_GPIO);
        if (pulses_read < 0) {
            fprintf(stderr, "Warning: failed to read flow sensor GPIO\n");
            pulses = 0;
        } else {
            pulses = pulses_read;
        }

        double flow_rate = calculate_flow_rate(pulses);
        int valve_position = control_flow(target_flow_rate, flow_rate);
        log_data(flow_rate, valve_position);
    }

    printf("\nShutting down...\n");
    gpioPWM(PWM_GPIO, 0);
    gpioWrite(VALVE_ENABLE_GPIO, 0);
    fclose(log_file);
    gpioTerminate();
    return 0;
}

