    if (gpioWrite(VALVE_ENABLE_GPIO, 1) < 0) {
        fprintf(stderr, "Error: failed to enable valve\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetISRFuncEx(FLOW_SENSOR_GPIO, RISING_EDGE, 0, pulse_callback, NULL) < 0) {
        fprintf(stderr, "Error: failed to set ISR for flow sensor\n");
        gpioWrite(VALVE_ENABLE_GPIO, 0);
        gpioTerminate();
        return 1;
    }

    log_file = fopen("flow_log.csv", "a");
    if (!log_file) {
        fprintf(stderr, "Error: failed to open flow_log.csv\n");
        gpioWrite(VALVE_ENABLE_GPIO, 0);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error: failed to set signal handlers\n");
        fclose(log_file);
        gpioWrite(VALVE_ENABLE_GPIO, 0);
        gpioTerminate();
        return 1;
    }

    printf("Flow control system started. Target: %.2f L/min\n", target_flow_rate);

    while (running) {
        int pulses = 0;
        gpioDelay(SAMPLE_INTERVAL_US);

        int pulses_read = gpioRead(FLOW_SENSOR_GPIO);
        if (pulses_read < 0) {
            fprintf(stderr, "Warning: failed to read flow sensor GPIO\n");
            pulses = 0;
        } else {
            pulses = pulses_read;
        }

        double flow_rate = calculate_flow_rate(pulses);
        int valve_position = control_flow(target_flow_rate, flow_rate);
        log_data(flow_rate, valve_position);
    }

    printf("\nShutting down...\n");
    gpioPWM(PWM_GPIO, 0);
    gpioWrite(VALVE_ENABLE_GPIO, 0);
    fclose(log_file);
    gpioTerminate();
    return 0;
}

