#define SPI_SPEED 100000
#define LOG_FILE "/var/log/door_access.log"
#define DEBOUNCE_US 50000
#define LOCK_TIME_US 5000000
#define SPI_READ_BYTES 10
#define VALID_TAG_LEN 10
#define NO_TAG_RESPONSE 0x00

static volatile sig_atomic_t running = 1;
static FILE *log_fp = NULL;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *msg) {
    if (!log_fp) return;
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(log_fp, "%04d-%02d-%02dT%02d:%02d:%02d %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
        fflush(log_fp);
    }
}

static int read_rfid(void) {
    char tx[SPI_READ_BYTES] = {0};
    char rx[SPI_READ_BYTES] = {0};
    int ret = spiXfer(spi_handle, tx, rx, SPI_READ_BYTES);
    if (ret != SPI_READ_BYTES) {
        log_event("SPI read failed");
        return -1;
    }
    if (rx[0] == NO_TAG_RESPONSE) {
        log_event("RFID: no tag present");
        return -1;
    }
    if (memcmp(rx, (char[]){0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08, 0x09, 0x0A}, VALID_TAG_LEN) != 0) {
        log_event("RFID: invalid tag");
        return -1;
    }
    log_event("RFID: valid tag");
    return 0;
}

static void disengage_locks(void) {
    gpioWrite(LOCK1_PIN, 0);
    gpioWrite(LOCK2_PIN, 0);
    gpioDelay(LOCK_TIME_US);
    gpioWrite(LOCK1_PIN, 1);
    gpioWrite(LOCK2_PIN, 1);
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    disengage_locks();
    if (log_fp) {
        log_event("System shutdown");
        fclose(log_fp);
        log_fp = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        perror("fopen log");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(LOCK1_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(LOCK2_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(BUTTON_PIN, PI_INPUT) != 0) {
        log_event("Failed to set GPIO modes");
        cleanup();
        return 1;
    }

    gpioSetPullUpDown(BUTTON_PIN, PI_PUD_UP);
    gpioWrite(LOCK1_PIN, 1);
    gpioWrite(LOCK2_PIN, 1);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        log_event("SPI open failed");
        cleanup();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_event("System started");

    while (running) {
        int button_state = gpioRead(BUTTON_PIN);
        if (button_state == 0) {
            gpioDelay(DEBOUNCE_US);
            button_state = gpioRead(BUTTON_PIN);
            if (button_state == 0) {
                if (read_rfid() == 0) {
                    log_event("Two-factor authentication successful");
                    disengage_locks();
                } else {
                    log_event("Two-factor authentication failed");
                }
            }
        }
        gpioDelay(100000);
    }

    cleanup();
    return 0;
}

