#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define MOTOR1_ENA 23
#define MOTOR1_IN1 24
#define MOTOR1_IN2 25
#define MOTOR2_ENB 12
#define MOTOR2_IN3 16
#define MOTOR2_IN4 20

#define ENCODER1_A 5
#define ENCODER1_B 6
#define ENCODER2_A 26
#define ENCODER2_B 19

#define PWM_FREQ 100
#define PWM_PERIOD_US 10000
#define SAMPLE_INTERVAL_US 100000
#define TARGET_RPM 60.0
#define KP 1.0
#define KI 0.1
#define KD 0.01
#define PULSES_PER_REV 600

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *ena_line = NULL;
static struct gpiod_line *in1_line = NULL;
static struct gpiod_line *in2_line = NULL;
static struct gpiod_line *enb_line = NULL;
static struct gpiod_line *in3_line = NULL;
static struct gpiod_line *in4_line = NULL;
static struct gpiod_line *enc1_a_line = NULL;
static struct gpiod_line *enc1_b_line = NULL;
static struct gpiod_line *enc2_a_line = NULL;
static struct gpiod_line *enc2_b_line = NULL;

static int motor1_count = 0;
static int motor2_count = 0;
static pthread_mutex_t motor1_count_mutex = PTHREAD_MUTEX_INITIALIZER;
static pthread_mutex_t motor2_count_mutex = PTHREAD_MUTEX_INITIALIZER;

static double motor1_integral = 0.0;
static double motor1_prev_error = 0.0;
static double motor2_integral = 0.0;
static double motor2_prev_error = 0.0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_data(double rpm1, double rpm2, double p1, double i1, double d1, double p2, double i2, double d2, double out1, double out2) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s,%.2f,%.2f,%.4f,%.4f,%.4f,%.4f,%.4f,%.4f,%.4f,%.4f\n",
            ts, rpm1, rpm2, p1, i1, d1, p2, i2, d2, out1, out2);
    fflush(log_file);
}

static void *encoder_thread(void *arg) {
    (void)arg;
    struct gpiod_line_event event;
    struct timespec ts = {0, 1000000}; /* 1 ms poll timeout */
    while (running) {
        int ret = gpiod_line_event_wait(enc1_a_line, &ts);
        if (ret < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "Encoder1 event wait failed: %s\n", strerror(errno));
            break;
        }
        if (ret == 0) continue; /* timeout, no event */

        ret = gpiod_line_event_read(enc1_a_line, &event);
        if (ret < 0) {
            fprintf(stderr, "Encoder1 event read failed: %s\n", strerror(errno));
            continue;
        }
        if (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
            int b_val = gpiod_line_get_value(enc1_b_line);
            if (b_val < 0) {
                fprintf(stderr, "Encoder1 B read failed: %s\n", strerror(errno));
                continue;
            }
            if (b_val == 0) {
                motor1_count++;
            } else {
                motor1_count--;
            }
            pthread_mutex_lock(&motor1_count_mutex);
            int c = motor1_count;
            pthread_mutex_unlock(&motor1_count_mutex);
        }
    }
    return NULL;
}

static void set_motor_speed(int motor, double speed) {
    double duty = (speed / TARGET_RPM) * PWM_PERIOD_US;
    if (motor == 1) {
        if (duty > PWM_PERIOD_US) duty = PWM_PERIOD_US;
        if (duty < 0) duty = 0;
        if (duty < PWM_PERIOD_US / 2) {
            gpiod_line_set_value(in1_line, 1);
            gpiod_line_set_value(in2_line, 0);
        } else {
            gpiod_line_set_value(in1_line, 0);
            gpiod_line_set_value(in2_line, 1);
        }
        gpiod_line_set_value(ena_line, 1);
        usleep((useconds_t)duty);
        gpiod_line_set_value(ena_line, 0);
        usleep((useconds_t)(PWM_PERIOD_US - duty));
    } else if (motor == 2) {
        if (duty > PWM_PERIOD_US) duty = PWM_PERIOD_US;
        if (duty < 0) duty = 0;
        if (duty < PWM_PERIOD_US / 2) {
            gpiod_line_set_value(in3_line, 1);
            gpiod_line_set_value(in4_line, 0);
        } else {
            gpiod_line_set_value(in3_line, 0);
            gpiod_line_set_value(in4_line, 1);
        }
        gpiod_line_set_value(enb_line, 1);
        usleep((useconds_t)duty);
        gpiod_line_set_value(enb_line, 0);
        usleep((useconds_t)(PWM_PERIOD_US - duty));
    }
}

static double calculate_pid(double current_rpm, double target_rpm, double kp, double ki, double kd, double *integral, double *prev_error) {
    double error = target_rpm - current_rpm;
    *integral += error;
    double derivative = error - *prev_error;
    double output = kp * error + ki * (*integral) + kd * derivative;
    *prev_error = error;
    return output;
}

static void cleanup(void) {
    if (ena_line) gpiod_line_set_value(ena_line, 0);
    if (in1_line) gpiod_line_set_value(in1_line, 0);
    if (in2_line) gpiod_line_set_value(in2_line, 0);
    if (enb_line) gpiod_line_set_value(enb_line, 0);
    if (in3_line) gpiod_line_set_value(in3_line, 0);
    if (in4_line) gpiod_line_set_value(in4_line, 0);
    if (enc1_a_line) gpiod_line_release(enc1_a_line);
    if (enc1_b_line) gpiod_line_release(enc1_b_line);
    if (enc2_a_line) gpiod_line_release(enc2_a_line);
    if (enc2_b_line) gpiod_line_release(enc2_b_line);
    if (chip) gpiod_chip_close(chip);
    if (log_file) fclose(log_file);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip4: %s\n", strerror(errno));
        return 1;
    }

    ena_line = gpiod_chip_get_line(chip, MOTOR1_ENA);
    in1_line = gpiod_chip_get_line(chip, MOTOR1_IN1);
    in2_line = gpiod_chip_get_line(chip, MOTOR1_IN2);
    enb_line = gpiod_chip_get_line(chip, MOTOR2_ENB);
    in3_line = gpiod_chip_get_line(chip, MOTOR2_IN3);
    in4_line = gpiod_chip_get_line(chip, MOTOR2_IN4);
    enc1_a_line = gpiod_chip_get_line(chip, ENCODER1_A);
    enc1_b_line = gpiod_chip_get_line(chip, ENCODER1_B);
    enc2_a_line = gpiod_chip_get_line(chip, ENCODER2_A);
    enc2_b_line = gpiod_chip_get_line(chip, ENCODER2_B);

    if (!ena_line || !in1_line || !in2_line || !enb_line || !in3_line || !in4_line ||
        !enc1_a_line || !enc1_b_line || !enc2_a_line || !enc2_b_line) {
        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    if (gpiod_line_request_output(ena_line, "motor1", 0) < 0 ||
        gpiod_line_request_output(in1_line, "motor1", 0) < 0 ||
        gpiod_line_request_output(in2_line, "motor1", 0) < 0 ||
        gpiod_line_request_output(enb_line, "motor2", 0) < 0 ||
        gpiod_line_request_output(in3_line, "motor2", 0) < 0 ||
        gpiod_line_request_output(in4_line, "motor2", 0) < 0) {
        fprintf(stderr, "Failed to request motor lines: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    if (gpiod_line_request_both_edges_events(enc1_a_line, "encoder1") < 0 ||
        gpiod_line_request_both_edges_events(enc2_a_line, "encoder2") < 0) {
        fprintf(stderr, "Failed to request encoder events: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    log_file = fopen("motor_log.csv", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }
    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,RPM1,RPM2,PID1_P,PID1_I,PID1_D,PID2_P,PID2_I,PID2_D,PID2_OUT,MOTOR1_DUTY,MOTOR2_DUTY\n");
    }

    pthread_t enc1, enc2;
    if (pthread_create(&enc1, NULL, encoder_thread, NULL) != 0) {
        fprintf(stderr, "Failed to create encoder 1 thread: %s\n", strerror(errno));
        cleanup();
        return 1;
    }
    if (pthread_create(&enc2, NULL, encoder_thread, NULL) != 0) {
        fprintf(stderr, "Failed to create encoder 2 thread: %s\n", strerror(errno));
        running = 0;
        pthread_join(enc1, NULL);
        cleanup();
        return 1;
    }

    while (running) {
        struct timespec ts = {0, SAMPLE_INTERVAL_US};
        int ret = gpiod_line_event_wait(enc1_a_line, &ts);
        if (ret < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "Encoder event wait failed: %s\n", strerror(errno));
            break;
        }
        if (ret == 0) continue;

        struct gpiod_line_event event;
        ret = gpiod_line_event_read(enc1_a_line, &event);
        if (ret < 0) {
            fprintf(stderr, "Encoder1 event read failed: %s\n", strerror(errno));
            continue;
        }
        if (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
            int b_val = gpiod_line_get_value(enc1_b_line);
            if (b_val < 0) {
                fprintf(stderr, "Encoder1 B read failed: %s\n", strerror(errno));
                continue;
            }
            if (b_val == 0) {
                motor1_count++;
            } else {
                motor1_count--;
            }
            pthread_mutex_lock(&motor1_count_mutex);
            int c = motor1_count;
            pthread_mutex_unlock(&motor1_count_mutex);
        }

        struct timespec start, now;
        clock_gettime(CLOCK_MONOTONIC, &start);
        double elapsed = 0.0;
        while (running && elapsed < SAMPLE_INTERVAL_US) {
            clock_gettime(CLOCK_MONOTONIC, &now);
            elapsed = (now.tv_sec - start.tv_sec) * 1000000.0 + (now.tv_nsec - start.tv_nsec) / 1000.0;
        }

        double rpm1 = (double)motor1_count * 600.0 / elapsed;
        double rpm2 = (double)motor2_count * 600.0 / elapsed;

        double p1 = KP * (rpm1 - TARGET_RPM);
        double i1 = KI * motor1_integral;
        double d1 = KD * (rpm1 - TARGET_RPM - motor1_prev_error);
        double out1 = p1 + i1 + d1;
        motor1_integral += (rpm1 - TARGET_RPM) * elapsed;
        motor1_prev_error = rpm1 - TARGET_RPM;

        double p2 = KP * (rpm2 - TARGET_RPM);
        double i2 = KI * motor2_integral;
        double d2 = KD * (rpm2 - TARGET_RPM - motor2_prev_error);
        double out2 = p2 + i2 + d2;
        motor2_integral += (rpm2 - TARGET_RPM) * elapsed;
        motor2_prev_error = rpm2 - TARGET_RPM;

        set_motor_speed(1, out1);
        set_motor_speed(2, out2);

        log_data(rpm1, rpm2, p1, i1, d1, p2, i2, d2, out1, out2);
    }

    running = 0;
    pthread_join(enc1, NULL);
    pthread_join(enc2, NULL);
    cleanup();
    return 0;
}

