#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

/* MPR121 I2C address (ADDR pin tied to GND) */
#define MPR121_ADDR 0x5A

/* MPR121 register addresses */
#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ECR           0x5E
#define MPR121_SOFTRESET     0x80
#define MPR121_MHDR          0x2B
#define MPR121_NHDR          0x2C
#define MPR121_NCLR          0x2D
#define MPR121_FDLR          0x2E
#define MPR121_MHDF          0x2F
#define MPR121_NHDF          0x30
#define MPR121_NCLF          0x31
#define MPR121_FDLF          0x32
#define MPR121_NHDT          0x33
#define MPR121_NCLT          0x34
#define MPR121_FDLT          0x35
#define MPR121_TOUCHTH_0     0x41
#define MPR121_RELEASETH_0  0x42
#define MPR121_DEBOUNCE      0x5B
#define MPR121_CONFIG1       0x5C
#define MPR121_CONFIG2       0x5D
#define MPR121_ECR           0x5E

/* Relay GPIO pin */
#define RELAY_GPIO 17

/* I2C bus on Raspberry Pi 3 Model B+ */
#define I2C_BUS 1

/* Global state for signal handler */
static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

/* Function prototypes */
static int mpr121_init(int handle);
static int read_touch_status(int handle, uint16_t *status);
static void control_relay(int gpio, int state);
static void log_relay_state(int gpio, int state);
static void cleanup(void);
static void signal_handler(int sig);

int main(void)
{
    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus to MPR121 */
    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d at address 0x%02X (pigpio error %d).\n",
                I2C_BUS, MPR121_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize MPR121 sensor */
    if (mpr121_init(i2c_handle) != 0) {
        fprintf(stderr, "Error: MPR121 initialization failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure relay GPIO as output and ensure it starts OFF */
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0);

    /* Open log file in append mode */
    log_file = fopen("relay_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open relay_log.txt: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Register signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Failed to register SIGINT handler: %s\n", strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Failed to register SIGTERM handler: %s\n", strerror(errno));
    }

    printf("MPR121 relay control started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (running) {
        uint16_t touch_status = 0;

        if (read_touch_status(i2c_handle, &touch_status) != 0) {
            fprintf(stderr, "Error: Failed to read touch status from MPR121.\n");
            gpioDelay(100000); /* 100 ms backoff on I2C error */
            continue;
        }

        /* Check if any electrode is touched (bit 0 of touch status indicates any touch) */
        if (touch_status & 0x0001) {
            control_relay(RELAY_GPIO, 1);
            log_relay_state(RELAY_GPIO, 1);
        } else {
            control_relay(RELAY_GPIO, 0);
            log_relay_state(RELAY_GPIO, 0);
        }

        gpioDelay(50000); /* 50 ms polling interval */
    }

    cleanup();
    return EXIT_SUCCESS;
}

/* Initialize the MPR121 sensor */
static int mpr121_init(int handle)
{
    /* Soft reset */
    if (i2cWriteByteData(handle, MPR121_SOFTRESET, 0x63) < 0) {
        fprintf(stderr, "Error: Failed to write soft reset to MPR121.\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms delay after reset */

    /* Set filter configuration registers */
    if (i2cWriteByteData(handle, MPR121_MHDR, 0x01) < 0 ||
        i2cWriteByteData(handle, MPR121_NHDR, 0x01) < 0 ||
        i2cWriteByteData(handle, MPR121_NCLR, 0x0E) < 0 ||
        i2cWriteByteData(handle, MPR121_FDLR, 0x00) < 0 ||
        i2cWriteByteData(handle, MPR121_MHDF, 0x01) < 0 ||
        i2cWriteByteData(handle, MPR121_NHDF, 0x05) < 0 ||
        i2cWriteByteData(handle, MPR121_NCLF, 0x01) < 0 ||
        i2cWriteByteData(handle, MPR121_FDLF, 0x00) < 0 ||
        i2cWriteByteData(handle, MPR121_NHDT, 0x00) < 0 ||
        i2cWriteByteData(handle, MPR121_NCLT, 0x00) < 0 ||
        i2cWriteByteData(handle, MPR121_FDLT, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write filter configuration to MPR121.\n");
        return -1;
    }

    /* Set touch and release thresholds for all 12 electrodes */
    for (int i = 0; i < 12; i++) {
        if (i2cWriteByteData(handle, MPR121_TOUCHTH_0 + 2 * i, 50) < 0) {
            fprintf(stderr, "Error: Failed to write touch threshold for electrode %d.\n", i);
            return -1;
        }
        if (i2cWriteByteData(handle, MPR121_RELEASETH_0 + 2 * i, 30) < 0) {
            fprintf(stderr, "Error: Failed to write release threshold for electrode %d.\n", i);
            return -1;
        }
    }

    /* Set debounce time (10 ms) */
    if (i2cWriteByteData(handle, MPR121_DEBOUNCE, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write debounce time to MPR121.\n");
        return -1;
    }

    /* Configure run mode: 12 electrodes, baseline tracking enabled */
    if (i2cWriteByteData(handle, MPR121_ECR, 0x8C) < 0) {
        fprintf(stderr, "Error: Failed to write ECR to MPR121.\n");
        return -1;
    }

    return 0;
}

/* Read the 16-bit touch status from the MPR121 */
static int read_touch_status(int handle, uint16_t *status)
{
    char buf[2];

    if (i2cReadI2CBlockData(handle, MPR121_TOUCHSTATUS_L, buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to read touch status from MPR121.\n");
        return -1;
    }

    *status = (uint16_t)((buf[1] << 8) | buf[0]);
    return 0;
}

/* Control the relay module */
static void control_relay(int gpio, int state)
{
    gpioWrite(gpio, state);
}

/* Log the relay state change to a file */
static void log_relay_state(int gpio, int state)
{
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: Failed to get local time.\n");
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s - Relay on GPIO %d is now %s\n",
            timestamp, gpio, state ? "ON" : "OFF");
    fflush(log_file);
}

/* Cleanup resources */
static void cleanup(void)
{
    /* Ensure relay is OFF */
    if (i2c_handle >= 0) {
        gpioWrite(RELAY_GPIO, 0);
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

/* Signal handler for graceful shutdown */
static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

