#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

#define MPR121_ADDR 0x5A
#define RELAY_GPIO 17
#define I2C_BUS 1
#define STABILIZE_MS 100
#define POLL_DELAY_MS 100

// MPR121 register addresses
#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ECR 0x5E
#define MPR121_MHD_R 0x2B
#define MPR121_NHD_R 0x2C
#define MPR121_NCL_R 0x2D
#define MPR121_FDL_R 0x2E
#define MPR121_NHD_F 0x2F
#define MPR121_NCL_F 0x30
#define MPR121_FDL_F 0x31
#define MPR121_NHD_C 0x32
#define MPR121_NCL_C 0x33
#define MPR121_FDL_C 0x34
#define MPR121_E0TTH 0x41
#define MPR121_E0RTH 0x42
#define MPR121_DEBOUNCE 0x5B
#define MPR121_CONFIG1 0x5C
#define MPR121_CONFIG2 0x5D
#define MPR121_ECR_EN 0x20

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int i2c_write_reg(uint8_t reg, uint8_t value) {
    char buf[2] = { (char)reg, (char)value };
    if (i2cWriteDevice(i2c_handle, buf, 2) != 0) {
        fprintf(stderr, "I2C write error at reg 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg(uint8_t reg, uint8_t *value) {
    if (i2cWriteDevice(i2c_handle, (char *)&reg, 1) != 0) {
        fprintf(stderr, "I2C write reg address error: %s\n", strerror(errno));
        return -1;
    }
    if (i2cReadDevice(i2c_handle, (char *)value, 1) != 1) {
        fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int mpr121_init(void) {
    // Stop mode
    if (i2c_write_reg(MPR121_ECR, 0x00) != 0) return -1;
    usleep(1000);

    // Touch / release thresholds for all 12 electrodes
    for (int i = 0; i < 12; i++) {
        if (i2c_write_reg(MPR121_E0TTH + i * 2, 0x10) != 0) return -1;
        if (i2c_write_reg(MPR121_E0RTH + i * 2, 0x0A) != 0) return -1;
    }

    // Debounce: 3 samples for touch, 3 for release
    if (i2c_write_reg(MPR121_DEBOUNCE, 0x33) != 0) return -1;

    // Config1: FFI=6 samples, CDC=16 µA
    if (i2c_write_reg(MPR121_CONFIG1, 0x10) != 0) return -1;

    // Config2: CDT=0.5 µs, SFI=4 samples, ESI=4 µs
    if (i2c_write_reg(MPR121_CONFIG2, 0x20) != 0) return -1;

    // Filter configuration (rising/falling)
    if (i2c_write_reg(MPR121_MHD_R, 0x01) != 0) return -1;
    if (i2c_write_reg(MPR121_NHD_R, 0x01) != 0) return -1;
    if (i2c_write_reg(MPR121_NCL_R, 0x00) != 0) return -1;
    if (i2c_write_reg(MPR121_FDL_R, 0x00) != 0) return -1;
    if (i2c_write_reg(MPR121_MHD_F, 0x01) != 0) return -1;
    if (i2c_write_reg(MPR121_NHD_F, 0x01) != 0) return -1;
    if (i2c_write_reg(MPR121_NCL_F, 0x00) != 0) return -1;
    if (i2c_write_reg(MPR121_FDL_F, 0x00) != 0) return -1;
    if (i2c_write_reg(MPR121_MHD_C, 0x01) != 0) return -1;
    if (i2c_write_reg(MPR121_NHD_C, 0x01) != 0) return -1;
    if (i2c_write_reg(MPR121_NCL_C, 0x00) != 0) return -1;
    if (i2c_write_reg(MPR121_FDL_C, 0x00) != 0) return -1;

    // Enter run mode: ELEPROX_EN=0, ELE_EN=1 (0x20)
    if (i2c_write_reg(MPR121_ECR, MPR121_ECR_EN) != 0) return -1;

    usleep(STABILIZE_MS * 1000);
    return 0;
}

static int read_touch_status(uint16_t *touch_status) {
    uint8_t low, high;
    if (i2c_read_reg(MPR121_TOUCHSTATUS_L, &low) != 0) return -1;
    if (i2c_read_reg(MPR121_TOUCHSTATUS_H, &high) != 0) return -1;
    *touch_status = ((uint16_t)high << 8) | low;
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X: %s\n",
                I2C_BUS, MPR121_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (mpr121_init() != 0) {
        fprintf(stderr, "MPR121 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Touch sensor relay control started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        uint16_t touch_status;
        if (read_touch_status(&touch_status) == 0) {
            if (touch_status > 0) {
                gpioWrite(RELAY_GPIO, !gpioRead(RELAY_GPIO));
                printf("Touch detected (0x%04X), relay toggled\n", touch_status);
            }
        } else {
            fprintf(stderr, "Failed to read touch status\n");
        }
        usleep(POLL_DELAY_MS * 1000);
    }

    gpioWrite(RELAY_GPIO, 0);
    i2cClose(i2c_handle);
    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return EXIT_SUCCESS;
}

