    if (i2c_write_reg(MPR121_FDL_R, 0x00) != 0) return -1;
    if (i2c_write_reg(MPR121_MHD_F, 0x01) != 0) return -1;
    if (i2c_write_reg(MPR121_NHD_F, 0x01) != 0) return -1;
    if (i2c_write_reg(MPR121_NCL_F, 0x00) != 0) return -1;
    if (i2c_write_reg(MPR121_FDL_F, 0x00) != 0) return -1;
    if (i2c_write_reg(MPR121_MHD_C, 0x01) != 0) return -1;
    if (i2c_write_reg(MPR121_NHD_C, 0x01) != 0) return -1;
    if (i2c_write_reg(MPR121_NCL_C, 0x00) != 0) return -1;
    if (i2c_write_reg(MPR121_FDL_C, 0x00) != 0) return -1;

    // Enter run mode: ELEPROX_EN=0, ELE_EN=1 (0x20)
    if (i2c_write_reg(MPR121_ECR, MPR121_ECR_EN) != 0) return -1;

    usleep(STABILIZE_MS * 1000);
    return 0;
}

static int read_touch_status(uint16_t *touch_status) {
    uint8_t low, high;
    if (i2c_read_reg(MPR121_TOUCHSTATUS_L, &low) != 0) return -1;
    if (i2c_read_reg(MPR121_TOUCHSTATUS_H, &high) != 0) return -1;
    *touch_status = ((uint16_t)high << 8) | low;
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X: %s\n",
                I2C_BUS, MPR121_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (mpr121_init() != 0) {
        fprintf(stderr, "MPR121 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Touch sensor relay control started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        uint16_t touch_status;
        if (read_touch_status(&touch_status) == 0) {
            if (touch_status > 0) {
                gpioWrite(RELAY_GPIO, !gpioRead(RELAY_GPIO));
                printf("Touch detected (0x%04X), relay toggled\n", touch_status);
            }
        } else {
            fprintf(stderr, "Failed to read touch status\n");
        }
        usleep(POLL_DELAY_MS * 1000);
    }

    gpioWrite(RELAY_GPIO, 0);
    i2cClose(i2c_handle);
    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return EXIT_SUCCESS;
}

