#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

#define MOTOR1_PIN 17
#define MOTOR2_PIN 27
#define MIN_DURATION_MS 50
#define MAX_DURATION_MS 200
#define MIN_DUTY_CYCLE 0
#define MAX_DUTY_CYCLE 255
#define MIN_PATTERN_LENGTH 5
#define MAX_PATTERN_LENGTH 15
#define STEP_DELAY_US 10000  // 10 ms

volatile sig_atomic_t shutdown_flag = 0;

void signal_handler(int signal) {
    (void)signal;
    shutdown_flag = 1;
}

int generate_pattern(int *duty_cycles, int *duration_ms, int length) {
    if (length < MIN_PATTERN_LENGTH || length > MAX_PATTERN_LENGTH) {
        fprintf(stderr, "Error: Pattern length %d out of range [%d, %d]\n",
                length, MIN_PATTERN_LENGTH, MAX_PATTERN_LENGTH);
        return -1;
    }
    for (int i = 0; i < length; i++) {
        duty_cycles[i] = (rand() % (MAX_DUTY_CYCLE - MIN_DUTY_CYCLE + 1)) + MIN_DUTY_CYCLE;
        duration_ms[i] = (rand() % (MAX_DURATION_MS - MIN_DURATION_MS + 1)) + MIN_DURATION_MS;
    }
    return 0;
}

int play_pattern(int motor1_pin, int motor2_pin, int *duty_cycles, int *duration_ms, int length) {
    for (int i = 0; i < length; i++) {
        if (gpioPWM(motor1_pin, duty_cycles[i]) != 0) {
            fprintf(stderr, "Error: Failed to set PWM duty cycle on GPIO %d\n", motor1_pin);
            return -1;
        }
        if (gpioPWM(motor2_pin, duty_cycles[i]) != 0) {
            fprintf(stderr, "Error: Failed to set PWM duty cycle on GPIO %d\n", motor2_pin);
            return -1;
        }
        gpioDelay(duration_ms[i] * 1000);  // Convert ms to us
    }
    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    if (gpioSetMode(MOTOR1_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output\n", MOTOR1_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(MOTOR2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output\n", MOTOR2_PIN);
        gpioTerminate();
        return 1;
    }

    // Seed random number generator
    srand(time(NULL));

    // Set up signal handler for graceful shutdown
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Failed to set SIGINT handler\n");
    }

    printf("Haptic feedback system started. Press Ctrl+C to exit.\n");

    while (!shutdown_flag) {
        int *duty_cycles = malloc((MAX_PATTERN_LENGTH + 1) * sizeof(int));
        int *duration_ms = malloc((MAX_PATTERN_LENGTH + 1) * sizeof(int));
        if (duty_cycles == NULL || duration_ms == NULL) {
            fprintf(stderr, "Error: Memory allocation failed\n");
            free(duty_cycles);
            free(duration_ms);
            break;
        }

        int length = generate_pattern(duty_cycles + 1, duration_ms + 1, MAX_PATTERN_LENGTH);
        if (length != 0) {
            free(duty_cycles);
            free(duration_ms);
            break;
        }

        // Play the pattern
        if (play_pattern(MOTOR1_PIN, MOTOR2_PIN, duty_cycles + 1, duration_ms + 1, length) != 0) {
            free(duty_cycles);
            free(duration_ms);
            break;
        }

        free(duty_cycles);
        free(duration_ms);
    }

    // Cleanup
    printf("\nShutting down...\n");
    gpioPWM(MOTOR1_PIN, 0);
    gpioPWM(MOTOR2_PIN, 0);
    gpioTerminate();
    printf("Cleanup complete.\n");
    return 0;
}

