static volatile sig_atomic_t running = 1;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_hx711(int data_pin, int clock_pin) {
    int data = 0;
    int timeout = 0;
    while (gpioRead(data_pin) == 1) {
        gpioDelay(100);
        timeout += 100;
        if (timeout >= HX711_TIMEOUT_US) {
            fprintf(stderr, "HX711 timeout waiting for data pin low\n");
            return -1;
        }
    }
    for (int i = 0; i < 24; i++) {
        gpioWrite(clock_pin, 1);
        gpioDelay(1);
        gpioWrite(clock_pin, 0);
        data <<= 1;
        if (gpioRead(data_pin)) data |= 1;
    }
    gpioWrite(clock_pin, 1);
    gpioDelay(1);
    gpioWrite(clock_pin, 0);
    data ^= 0x800000;
    return data;
}

static double calibrate_hx711(int data_pin, int clock_pin, int num_readings) {
    double sum = 0.0;
    int valid = 0;
    for (int i = 0; i < num_readings; i++) {
        int raw = read_hx711(data_pin, clock_pin);
        if (raw >= 0) {
            sum += raw;
            valid++;
        }
    }
    if (valid == 0) return 0.0;
    return sum / valid;
}

static void log_weight(double weight) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_fp, "%s, %.2f\n", ts, weight);
    fflush(log_fp);
}

static void save_calibration(const char *filename, double scale, double offset) {
    FILE *fp = fopen(filename, "w");
    if (!fp) { perror("fopen calibration"); return; }
    fprintf(fp, "%.6f %.6f\n", scale, offset);
    fclose(fp);
}

static void load_calibration(const char *filename, double *scale, double *offset) {
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        *scale = SCALE_FACTOR;
        *offset = OFFSET;
        return;
    }
    char line[256];
    if (!fgets(line, sizeof(line), fp)) { fclose(fp); *scale = SCALE_FACTOR; *offset = OFFSET; return; }
    fclose(fp);
    char *end;
    *scale = strtod(line, &end);
    if (end == line) { fclose(fp); *scale = SCALE_FACTOR; *offset = OFFSET; return; }
    *offset = strtod(end, NULL);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }
    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT);
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);
    gpioWrite(SOLENOID_PIN, 0);
    load_calibration(CALIBRATION_FILE, &SCALE_FACTOR, &OFFSET);
    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) { perror("fopen log"); gpioTerminate(); return 1; }
    signal(SIGINT, signal_handler);
    double offset_raw = calibrate_hx711(HX711_DATA_PIN, HX711_CLOCK_PIN, 100);
    if (offset_raw < 0) offset_raw = 0.0;
    SCALE_FACTOR = (OFFSET - offset_raw) / 100.0;
    save_calibration(CALIBRATION_FILE, SCALE_FACTOR, OFFSET);
    printf("Calibration complete. Offset=%.2f, Scale=%.6f\n", OFFSET, SCALE_FACTOR);
    while (running) {
        int raw = read_hx711(HX711_DATA_PIN, HX711_CLOCK_PIN);
        if (raw < 0) {
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }
        double weight = (raw - OFFSET) * SCALE_FACTOR;
        log_weight(weight);
        if (weight > WEIGHT_THRESHOLD) {
            gpioWrite(SOLENOID_PIN, 1);
        } else {
            gpioWrite(SOLENOID_PIN, 0);
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }
    gpioWrite(SOLENOID_PIN, 0);
    fclose(log_fp);
    gpioTerminate();
    return 0;
}

