#include <pigpio.h>
#include <syslog.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <string.h>

#define RAIN_SENSOR_PIN 4
#define MOTOR_IN1_PIN 17
#define MOTOR_IN2_PIN 18
#define MOTOR_PWM_PIN 27
#define PWM_FREQUENCY 1000
#define PWM_DUTY_CYCLE 150
#define MOTOR_RUN_TIME 5
#define DEBOUNCE_READINGS 5
#define DEBOUNCE_DELAY_MS 50
#define CHECK_INTERVAL_SEC 60
#define LOG_FILE "/var/log/window_control.log"

static volatile sig_atomic_t running = 1;
static int motor_running = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_rain_sensor(void) {
    int low_count = 0;
    for (int i = 0; i < DEBOUNCE_READINGS; i++) {
        if (gpioRead(RAIN_SENSOR_PIN) == 0) {
            low_count++;
        }
        gpioDelay(DEBOUNCE_DELAY_MS * 1000);
    }
    return (low_count >= 3) ? 1 : 0;
}

static void close_window(void) {
    syslog(LOG_INFO, "Closing window...");
    if (gpioWrite(MOTOR_IN1_PIN, 1) != 0) {
        syslog(LOG_ERR, "Failed to set IN1 high");
        return;
    }
    if (gpioWrite(MOTOR_IN2_PIN, 0) != 0) {
        syslog(LOG_ERR, "Failed to set IN2 low");
        return;
    }
    if (gpioPWM(MOTOR_PWM_PIN, PWM_DUTY_CYCLE) != 0) {
        syslog(LOG_ERR, "Failed to set PWM duty cycle");
        return;
    }
    motor_running = 1;
    syslog(LOG_INFO, "Motor running for %d seconds...", MOTOR_RUN_TIME);
    for (int i = 0; i < MOTOR_RUN_TIME * 10 && running; i++) {
        gpioDelay(100000);
    }
    if (gpioWrite(MOTOR_IN1_PIN, 0) != 0) {
        syslog(LOG_ERR, "Failed to stop motor");
    }
    if (gpioWrite(MOTOR_IN2_PIN, 0) != 0) {
        syslog(LOG_ERR, "Failed to stop motor");
    }
    if (gpioPWM(MOTOR_PWM_PIN, 0) != 0) {
        syslog(LOG_ERR, "Failed to stop PWM");
    }
    motor_running = 0;
    syslog(LOG_INFO, "Window closed.");
}

static void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    syslog(LOG_INFO, "%s: %s", timestamp, message);
}

int main(void) {
    openlog("window_control", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Starting window control system...");

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialization failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT) != 0) {
        syslog(LOG_ERR, "Failed to set rain sensor pin mode");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_PWM_PIN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set motor pin modes");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(MOTOR_PWM_PIN, PWM_FREQUENCY) != PWM_FREQUENCY) {
        syslog(LOG_ERR, "Failed to set PWM frequency");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "Failed to set signal handlers");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "GPIO initialized. Waiting for rain sensor...");
    while (running) {
        if (read_rain_sensor()) {
            syslog(LOG_INFO, "Rain detected!");
            close_window();
            syslog(LOG_INFO, "Window closed. Waiting %d seconds...", CHECK_INTERVAL_SEC);
            for (int i = 0; i < CHECK_INTERVAL_SEC * 10 && running; i++) {
                gpioDelay(100000);
            }
        } else {
            gpioDelay(100000);
        }
    }

    syslog(LOG_INFO, "Shutting down...");
    gpioWrite(MOTOR_IN1_PIN, 0);
    gpioWrite(MOTOR_IN2_PIN, 0);
    gpioPWM(MOTOR_PWM_PIN, 0);
    gpioTerminate();
    closelog();
    return EXIT_SUCCESS;
}

