#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>

#define HX711_DT 23
#define HX711_SCK 24
#define SOLENOID_PIN 17
#define WEIGHT_THRESHOLD 100.0
#define LOCK_DURATION 5
#define READ_TIMEOUT_US 1000000
#define LOG_FILE "stock_events.txt"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_hx711(int dt_pin, int sck_pin) {
    int data = 0;
    int timeout = 0;

    while (gpioRead(dt_pin) == 1) {
        gpioDelay(100);
        timeout += 100;
        if (timeout >= READ_TIMEOUT_US) {
            fprintf(stderr, "Error: HX711 data line stuck high (timeout).\n");
            return -1;
        }
    }

    for (int i = 0; i < 24; i++) {
        gpioWrite(sck_pin, 1);
        gpioDelay(1);
        data <<= 1;
        if (gpioRead(dt_pin)) {
            data |= 1;
        }
        gpioWrite(sck_pin, 0);
        gpioDelay(1);
    }

    gpioWrite(sck_pin, 1);
    gpioDelay(1);
    gpioWrite(sck_pin, 0);
    gpioDelay(1);

    if (data & 0x800000) {
        data |= 0xFF000000;
    }

    return data;
}

static double convert_to_grams(int raw_value) {
    const double scale_factor = 0.0009765625;
    return (double)raw_value * scale_factor;
}

static void activate_solenoid(int pin, int duration_seconds) {
    if (gpioWrite(pin, 1) != 0) {
        fprintf(stderr, "Error: Failed to activate solenoid.\n");
        return;
    }
    gpioDelay(duration_seconds * 1000000);
    if (gpioWrite(pin, 0) != 0) {
        fprintf(stderr, "Error: Failed to deactivate solenoid.\n");
    }
}

static void log_event(const char *filename) {
    FILE *fp = fopen(filename, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open log file '%s': %s\n", filename, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s: Ingredient stock level below threshold. Solenoid activated.\n", timestamp);
    fclose(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(HX711_DT, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set DT pin mode.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(HX711_SCK, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set SCK pin mode.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SOLENOID_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set solenoid pin mode.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioWrite(SOLENOID_PIN, 0);
    gpioWrite(HX711_SCK, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: Failed to set signal handlers.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Kitchen ingredient stock monitor started. Press Ctrl+C to exit.\n");

    while (running) {
        int raw_value = read_hx711(HX711_DT, HX711_SCK);
        if (raw_value == -1) {
            fprintf(stderr, "Error: HX711 read failed. Retrying in 1 second.\n");
            gpioDelay(1000000);
            continue;
        }

        double weight = convert_to_grams(raw_value);

        if (weight < WEIGHT_THRESHOLD) {
            printf("Ingredient stock level below threshold: %.2f g\n", weight);
            activate_solenoid(SOLENOID_PIN, LOCK_DURATION);
            log_event(LOG_FILE);
        }

        gpioDelay(1000000);
    }

    gpioWrite(SOLENOID_PIN, 0);
    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return EXIT_SUCCESS;
}

