#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define PIR_PIN 17
#define BUZZER_PIN 18
#define BUZZER_DURATION_MS 2000
#define CONSUMER "motion_detector"

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *pir_line = NULL;
static struct gpiod_line *buzzer_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int init_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return -1;
    }

    pir_line = gpiod_chip_get_line(chip, PIR_PIN);
    if (!pir_line) {
        fprintf(stderr, "Failed to get PIR line %d: %s\n", PIR_PIN, strerror(errno));
        return -1;
    }

    if (gpiod_line_request_input(pir_line, CONSUMER) < 0) {
        fprintf(stderr, "Failed to request PIR line as input: %s\n", strerror(errno));
        return -1;
    }

    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (!buzzer_line) {
        fprintf(stderr, "Failed to get buzzer line %d: %s\n", BUZZER_PIN, strerror(errno));
        return -1;
    }

    if (gpiod_line_request_output(buzzer_line, CONSUMER, 0) < 0) {
        fprintf(stderr, "Failed to request buzzer line as output: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static void cleanup_gpio(void) {
    if (buzzer_line) {
        gpiod_line_set_value(buzzer_line, 0);
        gpiod_line_release(buzzer_line);
        buzzer_line = NULL;
    }
    if (pir_line) {
        gpiod_line_release(pir_line);
        pir_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

static int read_pir(void) {
    int val = gpiod_line_get_value(pir_line);
    if (val < 0) {
        fprintf(stderr, "Failed to read PIR line: %s\n", strerror(errno));
        return -1;
    }
    return val;
}

static int activate_buzzer(int duration_ms) {
    if (gpiod_line_set_value(buzzer_line, 1) < 0) {
        fprintf(stderr, "Failed to activate buzzer: %s\n", strerror(errno));
        return -1;
    }
    usleep(duration_ms * 1000);
    if (gpiod_line_set_value(buzzer_line, 0) < 0) {
        fprintf(stderr, "Failed to deactivate buzzer: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int log_motion(void) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (!timeinfo) {
        fprintf(stderr, "Failed to get local time\n");
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file) {
        fprintf(log_file, "%s Motion detected\n", timestamp);
        fflush(log_file);
        return 0;
    }
    fprintf(stderr, "Log file not open\n");
    return -1;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction SIGINT");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction SIGTERM");
        return EXIT_FAILURE;
    }

    if (init_gpio() < 0) {
        cleanup_gpio();
        return EXIT_FAILURE;
    }

    log_file = fopen("motion_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open motion_log.txt: %s\n", strerror(errno));
        cleanup_gpio();
        return EXIT_FAILURE;
    }

    printf("Motion detection started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int pir_val = read_pir();
        if (pir_val < 0) {
            fprintf(stderr, "PIR read error, exiting\n");
            break;
        }

        if (pir_val == 1) {
            printf("Motion detected!\n");
            if (activate_buzzer(BUZZER_DURATION_MS) < 0) {
                fprintf(stderr, "Buzzer activation error\n");
            }
            if (log_motion() < 0) {
                fprintf(stderr, "Logging error\n");
            }
        }

        usleep(100000);
    }

    printf("\nShutting down...\n");
    cleanup_gpio();
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    printf("Exiting.\n");
    return EXIT_SUCCESS;
}

