#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_OFFSET 18
#define CONFIG_FILE "watering.conf"
#define MIN_DURATION 1
#define MAX_DURATION 3600

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int signum) {
    (void)signum;
    program_running = 0;
}

static int read_configuration(const char *filename, int *duration) {
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        fprintf(stderr, "Error opening configuration file '%s': %s\n",
                filename, strerror(errno));
        return -1;
    }

    char line[256];
    int found = 0;
    while (fgets(line, sizeof(line), fp)) {
        if (strncmp(line, "duration=", 9) == 0) {
            found = 1;
            char *endptr = NULL;
            long val = strtol(line + 9, &endptr, 10);
            if (endptr == line + 9 || *endptr != '\n' && *endptr != '\0') {
                fprintf(stderr, "Invalid duration format in config file\n");
                fclose(fp);
                return -1;
            }
            if (val < MIN_DURATION || val > MAX_DURATION) {
                fprintf(stderr, "Duration out of range: %ld (must be %d-%d)\n",
                        val, MIN_DURATION, MAX_DURATION);
                fclose(fp);
                return -1;
            }
            *duration = (int)val;
            break;
        }
    }

    if (!found) {
        fprintf(stderr, "Configuration file '%s' does not contain 'duration=' line.\n", filename);
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

static int set_valve(struct gpiod_line *line, int duration) {
    if (gpiod_line_set_value(line, 1) < 0) {
        fprintf(stderr, "Error setting GPIO line high: %s\n", strerror(errno));
        return -1;
    }
    printf("Valve ON for %d seconds\n", duration);

    for (int i = 0; i < duration && program_running; i++) {
        sleep(1);
    }

    if (gpiod_line_set_value(line, 0) < 0) {
        fprintf(stderr, "Error setting GPIO line low: %s\n", strerror(errno));
        return -1;
    }
    printf("Valve OFF\n");
    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int duration = 0;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error installing SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error installing SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip '%s': %s\n",
                GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n",
                GPIO_LINE_OFFSET, strerror(errno));
        goto cleanup_chip;
    }

    if (gpiod_line_request_output(line, "watering-system", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %s\n",
                GPIO_LINE_OFFSET, strerror(errno));
        goto cleanup_chip;
    }

    if (read_configuration(CONFIG_FILE, &duration) < 0) {
        goto cleanup_line;
    }

    if (duration == 0) {
        fprintf(stderr, "No watering duration configured.\n");
        goto cleanup_line;
    }

    printf("Watering duration: %d seconds\n", duration);

    while (program_running) {
        if (set_valve(line, duration) < 0) {
            break;
        }
    }

    ret = EXIT_SUCCESS;

cleanup_line:
    gpiod_line_set_value(line, 0);
    gpiod_line_release(line);

cleanup_chip:
    gpiod_chip_close(chip);

    if (ret == EXIT_SUCCESS) {
        printf("Program finished.\n");
    }
    return ret;
}

