#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define LEFT_SENSOR_PIN 4
#define MIDDLE_SENSOR_PIN 17
#define RIGHT_SENSOR_PIN 27
#define MOTOR_PWM1_PIN 22
#define MOTOR_PWM2_PIN 23
#define MOTOR_PWM3_PIN 24
#define MOTOR_PWM4_PIN 25
#define PWM_FREQUENCY 1000
#define PWM_RANGE 255
#define LOG_FILE "trace_log.txt"
#define LOOP_DELAY_US 10000

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT) < 0 ||
        gpioSetMode(MIDDLE_SENSOR_PIN, PI_INPUT) < 0 ||
        gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set sensor GPIO modes\n");
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(MOTOR_PWM1_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_PWM2_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_PWM3_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_PWM4_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set motor GPIO modes\n");
        gpioTerminate();
        return -1;
    }

    if (gpioSetPWMfrequency(MOTOR_PWM1_PIN, PWM_FREQUENCY) < 0 ||
        gpioSetPWMfrequency(MOTOR_PWM2_PIN, PWM_FREQUENCY) < 0 ||
        gpioSetPWMfrequency(MOTOR_PWM3_PIN, PWM_FREQUENCY) < 0 ||
        gpioSetPWMfrequency(MOTOR_PWM4_PIN, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        gpioTerminate();
        return -1;
    }

    if (gpioSetPWMrange(MOTOR_PWM1_PIN, PWM_RANGE) < 0 ||
        gpioSetPWMrange(MOTOR_PWM2_PIN, PWM_RANGE) < 0 ||
        gpioSetPWMrange(MOTOR_PWM3_PIN, PWM_RANGE) < 0 ||
        gpioSetPWMrange(MOTOR_PWM4_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void set_motor_speeds(int left_speed, int right_speed) {
    if (left_speed < 0) left_speed = 0;
    if (right_speed < 0) right_speed = 0;

    if (gpioPWM(MOTOR_PWM1_PIN, left_speed) < 0 ||
        gpioPWM(MOTOR_PWM2_PIN, right_speed) < 0 ||
        gpioPWM(MOTOR_PWM3_PIN, right_speed) < 0 ||
        gpioPWM(MOTOR_PWM4_PIN, left_speed) < 0) {
        fprintf(stderr, "Failed to set motor PWM\n");
    }
}

static void stop_motors(void) {
    set_motor_speeds(0, 0);
}

static void log_data(int left, int middle, int right, int left_speed, int right_speed) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Failed to get local time\n");
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Left: %d, Middle: %d, Right: %d, LeftSpeed: %d, RightSpeed: %d\n",
                timestamp, left, middle, right, left_speed, right_speed);
        fflush(log_file);
    } else {
        fprintf(stderr, "Log file not open\n");
    }
}

static void cleanup(void) {
    stop_motors();
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    int left_speed = 0, right_speed = 0;
    int left, middle, right;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    if (initialize_gpio() != 0) {
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    printf("Line following robot started. Press Ctrl+C to stop.\n");

    while (running) {
        left = gpioRead(LEFT_SENSOR_PIN);
        middle = gpioRead(MIDDLE_SENSOR_PIN);
        right = gpioRead(RIGHT_SENSOR_PIN);

        if (left < 0 || middle < 0 || right < 0) {
            fprintf(stderr, "Failed to read sensor GPIO\n");
            break;
        }

        if (middle == 0) {
            left_speed = PWM_RANGE;
            right_speed = 0;
        } else if (left == 0) {
            left_speed = PWM_RANGE / 2;
            right_speed = PWM_RANGE;
        } else if (right == 0) {
            left_speed = PWM_RANGE;
            right_speed = PWM_RANGE / 2;
        } else {
            left_speed = 0;
            right_speed = 0;
        }

        set_motor_speeds(left_speed, right_speed);
        log_data(left, middle, right, left_speed, right_speed);

        gpioDelay(LOOP_DELAY_US);
    }

    cleanup();
    printf("Robot stopped.\n");
    return 0;
}

