            break;
        }

        if (middle == 0) {
            left_speed = PWM_RANGE;
            right_speed = 0;
        } else if (left == 0) {
            left_speed = PWM_RANGE / 2;
            right_speed = PWM_RANGE;
        } else if (right == 0) {
            left_speed = PWM_RANGE;
            right_speed = PWM_RANGE / 2;
        } else {
            left_speed = 0;
            right_speed = 0;
        }

        set_motor_speeds(left_speed, right_speed);
        log_data(left, middle, right, left_speed, right_speed);

        gpioDelay(LOOP_DELAY_US);
    }

    cleanup();
    printf("Robot stopped.\n");
    return 0;
}

