#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define BH1750_ADDR 0x23
#define CONTINUOUS_HIGH_RES_MODE 0x10
#define RELAY_GPIO 23
#define LUX_THRESHOLD 150.0f
#define LOG_FILE "grow_log.txt"
#define I2C_BUS 1
#define MEASUREMENT_DELAY_US 180000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_message(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    fprintf(fp, "%s.%03ld: %s\n", timestamp, ts.tv_nsec / 1000000, message);
    fclose(fp);
}

static int read_bh1750(int handle, float *lux) {
    char cmd = CONTINUOUS_HIGH_RES_MODE;
    if (i2cWriteDevice(handle, &cmd, 1) != 0) {
        log_message("Error: Failed to send measurement command to BH1750");
        return -1;
    }
    gpioDelay(MEASUREMENT_DELAY_US);
    char buf[2];
    if (i2cReadDevice(handle, buf, 2) != 2) {
        log_message("Error: Failed to read data from BH1750");
        return -1;
    }
    uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    *lux = (float)raw / 1.2f;
    return 0;
}

static void control_relay(int gpio, int state) {
    if (gpioWrite(gpio, state) != 0) {
        log_message("Error: Failed to write to relay GPIO");
        return;
    }
    char msg[64];
    snprintf(msg, sizeof(msg), "Relay GPIO %d set to %s", gpio, state ? "ON" : "OFF");
    log_message(msg);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0);
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    log_message("Program started");
    while (running) {
        float lux;
        if (read_bh1750(i2c_handle, &lux) == 0) {
            char msg[128];
            snprintf(msg, sizeof(msg), "Lux: %.2f", lux);
            log_message(msg);
            if (lux < LUX_THRESHOLD) {
                control_relay(RELAY_GPIO, 1);
            } else {
                control_relay(RELAY_GPIO, 0);
            }
        }
        gpioDelay(500000);
    }
    control_relay(RELAY_GPIO, 0);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    log_message("Program terminated");
    return 0;
}

