#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

#define SERVO_PIN 18
#define LOCK_BUTTON_PIN 21
#define UNLOCK_BUTTON_PIN 22
#define SERVO_LOCK_PULSE 1000
#define SERVO_UNLOCK_PULSE 2000
#define DEBOUNCE_DELAY_MS 100
#define SERVO_MIN_PULSE 500
#define SERVO_MAX_PULSE 2500

static volatile int running = 1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);

    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    gpioSetMode(LOCK_BUTTON_PIN, PI_INPUT);
    gpioSetMode(UNLOCK_BUTTON_PIN, PI_INPUT);
    gpioSetPullUpDown(LOCK_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(UNLOCK_BUTTON_PIN, PI_PUD_UP);

    int current_pulse = SERVO_LOCK_PULSE;
    int target_pulse = SERVO_LOCK_PULSE;

    while (running) {
        int lock_pressed = (gpioRead(LOCK_BUTTON_PIN) == 0);
        int unlock_pressed = (gpioRead(UNLOCK_BUTTON_PIN) == 0);

        if (lock_pressed && current_pulse != SERVO_LOCK_PULSE) {
            target_pulse = SERVO_LOCK_PULSE;
        } else if (unlock_pressed && current_pulse != SERVO_UNLOCK_PULSE) {
            target_pulse = SERVO_UNLOCK_PULSE;
        }

        if (target_pulse != current_pulse) {
            if (target_pulse < SERVO_MIN_PULSE || target_pulse > SERVO_MAX_PULSE) {
                fprintf(stderr, "Error: Invalid pulse width %d out of range [500, 2500]. Keeping current pulse.\n", target_pulse);
            } else {
                gpioServo(SERVO_PIN, target_pulse);
                current_pulse = target_pulse;
                printf("Servo moved to %d us (%s)\n", current_pulse, target_pulse == SERVO_LOCK_PULSE ? "locked" : "unlocked");
            }
        }

        if (lock_pressed) {
            gpioDelay(DEBOUNCE_DELAY_MS * 1000);
        } else if (unlock_pressed) {
            gpioDelay(DEBOUNCE_DELAY_MS * 1000);
        }

        gpioDelay(10000);
    }

    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
    printf("Program terminated cleanly.\n");
    return EXIT_SUCCESS;
}

