#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>
#include <gpiod.h>
#include <zmq.h>

#define GPIO_CHIP_NAME "gpiochip4"
#define SOUND_SENSOR_PIN 17
#define ALARM_LED_PIN 27
#define SOUND_ALERTS_TOPIC "SOUND_ALERTS"
#define ZMQ_PORT 5555
#define POLL_INTERVAL_US 10000
#define ALARM_DURATION_MS 1000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(struct gpiod_chip **chip, struct gpiod_line **line) {
    *chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!*chip) {
        fprintf(stderr, "Failed to open GPIO chip %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        return -1;
    }

    *line = gpiod_chip_get_line(*chip, SOUND_SENSOR_PIN);
    if (!*line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", SOUND_SENSOR_PIN, strerror(errno));
        gpiod_chip_close(*chip);
        *chip = NULL;
        return -1;
    }

    if (gpiod_line_request_input(*line, "sound_alarm") < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as input: %s\n", SOUND_SENSOR_PIN, strerror(errno));
        gpiod_chip_close(*chip);
        *chip = NULL;
        return -1;
    }

    *line = gpiod_chip_get_line(*chip, ALARM_LED_PIN);
    if (!*line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", ALARM_LED_PIN, strerror(errno));
        gpiod_line_release(*line);
        gpiod_chip_close(*chip);
        *chip = NULL;
        return -1;
    }

    if (gpiod_line_request_output(*line, "sound_alarm", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as output: %s\n", ALARM_LED_PIN, strerror(errno));
        gpiod_line_release(*line);
        gpiod_chip_close(*chip);
        *chip = NULL;
        return -1;
    }

    return 0;
}

static void cleanup_gpio(struct gpiod_chip *chip, struct gpiod_line *line) {
    if (line) {
        gpiod_line_set_value(line, 0);
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

static int init_zmq(void) {
    void *context = zmq_ctx_new();
    if (!context) {
        fprintf(stderr, "Failed to create ZMQ context: %s\n", strerror(errno));
        return -1;
    }

    void *socket = zmq_socket(context, ZMQ_TOPIC);
    if (!socket) {
        fprintf(stderr, "Failed to create ZMQ socket: %s\n", strerror(errno));
        zmq_ctx_destroy(context);
        return -1;
    }

    int ret = zmq_bind(socket, "tcp://*:" ZMQ_PORT);
    if (ret != 0) {
        fprintf(stderr, "Failed to bind ZMQ socket to port %d: %s\n", ZMQ_PORT, zmq_strerror(ret));
        zmq_socket_close(socket);
        zmq_ctx_destroy(context);
        return -1;
    }

    return socket;
}

static void cleanup_zmq(void *socket) {
    if (socket) {
        zmq_socket_close(socket);
    }
    zmq_ctx_destroy(NULL);
}

int main(int argc, char *argv[]) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *sound_line = NULL;
    struct gpiod_line *led_line = NULL;
    void *zmq_socket = NULL;
    int mode = -1;

    if (argc != 2) {
        fprintf(stderr, "Usage: %s <mode> (sound_sensor or alarm_node)\n", argv[0]);
        return EXIT_FAILURE;
    }

    if (strcmp(argv[1], "sound_sensor") == 0) {
        mode = 0;
    } else if (strcmp(argv[1], "alarm_node") == 0) {
        mode = 1;
    } else {
        fprintf(stderr, "Invalid mode. Use 'sound_sensor' or 'alarm_node'.\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (init_gpio(&chip, &sound_line) < 0) {
        return EXIT_FAILURE;
    }

    if (init_zmq(&zmq_socket) < 0) {
        cleanup_gpio(chip, sound_line);
        return EXIT_FAILURE;
    }

    if (mode == 0) {
        printf("Sound sensor mode. Polling GPIO%d every %d us. Press Ctrl+C to exit.\n", SOUND_SENSOR_PIN, POLL_INTERVAL_US);
        while (running) {
            int val = gpiod_line_get_value(sound_line);
            if (val < 0) {
                fprintf(stderr, "Failed to read sound sensor: %s\n", strerror(errno));
                break;
            }

            if (val == 0) {
                printf("Sound detected!\n");
                if (zmq_msg_init_size(zmq_msg_t, 0) < 0) {
