#include <zmq.h>

#define GPIO_CHIP_NAME "gpiochip4"
#define SOUND_SENSOR_PIN 17
#define ALARM_LED_PIN 27
#define SOUND_ALERTS_TOPIC "SOUND_ALERTS"
#define ZMQ_PORT 5555
#define POLL_INTERVAL_US 10000
#define ALARM_DURATION_MS 1000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(struct gpiod_chip **chip, struct gpiod_line **line) {
    *chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!*chip) {
        fprintf(stderr, "Failed to open GPIO chip %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        return -1;
    }

    *line = gpiod_chip_get_line(*chip, SOUND_SENSOR_PIN);
    if (!*line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", SOUND_SENSOR_PIN, strerror(errno));
        gpiod_chip_close(*chip);
        *chip = NULL;
        return -1;
    }

    if (gpiod_line_request_input(*line, "sound_alarm") < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as input: %s\n", SOUND_SENSOR_PIN, strerror(errno));
        gpiod_chip_close(*chip);
        *chip = NULL;
        return -1;
    }

    *line = gpiod_chip_get_line(*chip, ALARM_LED_PIN);
    if (!*line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", ALARM_LED_PIN, strerror(errno));
        gpiod_line_release(*line);
        gpiod_chip_close(*chip);
        *chip = NULL;
        return -1;
    }

    if (gpiod_line_request_output(*line, "sound_alarm", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as output: %s\n", ALARM_LED_PIN, strerror(errno));
        gpiod_line_release(*line);
        gpiod_chip_close(*chip);
        *chip = NULL;
        return -1;
    }

    return 0;
}

static void cleanup_gpio(struct gpiod_chip *chip, struct gpiod_line *line) {
    if (line) {
        gpiod_line_set_value(line, 0);
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

static int init_zmq(void) {
    void *context = zmq_ctx_new();
    if (!context) {
        fprintf(stderr, "Failed to create ZMQ context: %s\n", strerror(errno));
        return -1;
    }

    void *socket = zmq_socket(context, ZMQ_TOPIC);
    if (!socket) {
        fprintf(stderr, "Failed to create ZMQ socket: %s\n", strerror(errno));
        zmq_ctx_destroy(context);
        return -1;
    }

    int ret = zmq_bind(socket, "tcp://*:" ZMQ_PORT);
    if (ret != 0) {
        fprintf(stderr, "Failed to bind ZMQ socket to port %d: %s\n", ZMQ_PORT, zmq_strerror(ret));
