#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <syslog.h>
#include <time.h>
#include <pigpio.h>
#include <mosquitto.h>

#define IR_GPIO 17
#define MQTT_HOST "localhost"
#define MQTT_PORT 1883
#define MQTT_TOPIC "ir/decoded"
#define MAX_PULSES 100
#define NEC_HEADER_MARK 9000
#define NEC_HEADER_SPACE 4500
#define NEC_BIT_MARK 560
#define NEC_ONE_SPACE 1690
#define NEC_ZERO_SPACE 560
#define NEC_TOLERANCE 2000
#define MQTT_CLIENT_ID "ir_decoder"
#define MQTT_CLIENT_ID_LEN 20

static volatile sig_atomic_t running = 1;
static volatile uint32_t pulse_buf[MAX_PULSES];
static volatile int pulse_count = 0;
static volatile int last_state = 1;
static volatile uint32_t last_tick = 0;
static struct mosquitto *mosq = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void ir_callback(int gpio, int level, uint32_t tick) {
    (void)gpio;
    uint32_t diff = tick - last_tick;
    last_tick = tick;
    last_state = level;

    if (level == 0) {
        if (pulse_count < MAX_PULSES) {
            pulse_buf[pulse_count++] = diff;
        }
    }
}

static int decode_nec(const uint32_t *pulses, int count, uint32_t *address, uint32_t *command) {
    if (count < 34) return -1;

    if (pulses[0] < NEC_HEADER_MARK - NEC_TOLERANCE || pulses[0] > NEC_HEADER_MARK + NEC_TOLERANCE) return -1;
    if (pulses[1] < NEC_HEADER_SPACE - NEC_TOLERANCE || pulses[1] > NEC_HEADER_SPACE + NEC_TOLERANCE) return -1;

    uint32_t address_data = 0, command_data = 0;
    int bit_idx = 0;
    int addr_done = 0, cmd_done = 0;

    for (int i = 0; i < 32 && bit_idx < 32; i += 2) {
        if (i + 1 >= count) return -1;
        if (pulses[i] < NEC_BIT_MARK - NEC_TOLERANCE || pulses[i] > NEC_BIT_MARK + NEC_TOLERANCE) return -1;

        uint32_t space = pulses[i + 1];
        if (space > NEC_ONE_SPACE - NEC_TOLERANCE && space < NEC_ONE_SPACE + NEC_TOLERANCE) {
            address_data |= (1u << bit_idx);
        } else if (space > NEC_ZERO_SPACE - NEC_TOLERANCE && space < NEC_ZERO_SPACE + NEC_TOLERANCE) {
            /* Space indicates a 0 bit; no action needed for address */
        } else {
            return -1;
        }
        bit_idx++;
        if (bit_idx == 16) addr_done = 1;
    }

    for (int i = 32; i < count; i += 2) {
        if (i + 1 >= count) return -1;
        if (pulses[i] < NEC_BIT_MARK - NEC_TOLERANCE || pulses[i] > NEC_BIT_MARK + NEC_TOLERANCE) return -1;

        uint32_t space = pulses[i + 1];
        if (space > NEC_ONE_SPACE - NEC_TOLERANCE && space < NEC_ONE_SPACE + NEC_TOLERANCE) {
            command_data |= (1u << (bit_idx - 16));
        } else if (space > NEC_ZERO_SPACE - NEC_TOLERANCE && space < NEC_ZERO_SPACE + NEC_TOLERANCE) {
            /* Space indicates a 0 bit; no action needed for command */
        } else {
            return -1;
        }
        bit_idx++;
        if (bit_idx == 32) cmd_done = 1;
    }

    if (!addr_done || !cmd_done) return -1;

    *address = address_data;
    *command = command_data;
    return 0;
}

static int validate_nec(uint32_t address, uint32_t command) {
    /* Extended NEC frames are allowed; inverted-address validation is not required */
    return 0;
}

static void log_message(uint32_t address, uint32_t command) {
    char buf[256];
    snprintf(buf, sizeof(buf), "Address: 0x%08X, Command: 0x%08X", address, command);
    syslog(LOG_INFO, "%s", buf);
}

static void mqtt_connect_callback(struct mosquitto *mosq, void *userdata, int result) {
    (void)userdata;
    if (result == MOSQ_ERR_SUCCESS) {
        syslog(LOG_INFO, "MQTT connected to %s:%d", MQTT_HOST, MQTT_PORT);
    } else {
        syslog(LOG_ERR, "MQTT connect failed: %s", mosquitto_strerror(result));
    }
}

static void mqtt_message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message) {
    (void)mosq;
    (void)userdata;
    if (message->payloadlen > 0) {
        char payload[32];
        int len = message->payloadlen < (int)sizeof(payload) - 1 ? message->payloadlen : (int)sizeof(payload) - 1;
        memcpy(payload, message->payload, len);
        payload[len] = '\0';

        char buf[256];
        snprintf(buf, sizeof(buf), "Received: %s", payload);
        syslog(LOG_INFO, "%s", buf);

        char json[256];
        snprintf(json, sizeof(json), "{\"address\": 0x%08X, \"command\": 0x%08X}", *(uint32_t *)payload, *(uint32_t *)(payload + 8));
        syslog(LOG_INFO, "%s", json);

        int rc = mosquitto_publish(mosq, NULL, MQTT_TOPIC, (int)strlen(json), json, 0, false);
        if (rc != MOSQ_ERR_SUCCESS) {
            syslog(LOG_ERR, "MQTT publish failed: %s", mosquitto_strerror(rc));
        }
    }
}

static void cleanup(void) {
    if (mosq) {
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
        mosq = NULL;
    }
    mosquitto_lib_cleanup();
    gpioTerminate();
    closelog();
}

int main(void) {
    openlog("ir_decoder", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "Failed to set signal handlers");
        closelog();
        return 1;
    }

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialization failed");
        closelog();
        return 1;
    }

    if (gpioSetMode(IR_GPIO, PI_INPUT) != 0) {
        syslog(LOG_ERR, "Failed to set GPIO %d as input", IR_GPIO);
        gpioTerminate();
        closelog();
        return 1;
    }

    if (gpioSetPullUpDown(IR_GPIO, PI_PUD_UP) != 0) {
        syslog(LOG_ERR, "Failed to set pull-up on GPIO %d", IR_GPIO);
        gpioTerminate();
        closelog();
        return 1;
    }

    if (gpioSetAlertFunc(IR_GPIO, ir_callback) != 0) {
        syslog(LOG_ERR, "Failed to set alert function on GPIO %d", IR_GPIO);
        gpioTerminate();
        closelog();
        return 1;
    }

    mosquitto_lib_init();
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        syslog(LOG_ERR, "Failed to create MQTT client");
        gpioTerminate();
        closelog();
        return 1;
    }

    mosquitto_connect_callback_set(mosq, mqtt_connect_callback);
    mosquitto_message_callback_set(mosq, mqtt_message_callback);

    int rc = mosquitto_connect(mosq, MQTT_HOST, MQTT_PORT, 60);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "MQTT connect failed: %s", mosquitto_strerror(rc));
        mosquitto_destroy(mosq);
        mosq = NULL;
        mosquitto_lib_cleanup();
        gpioTerminate();
        closelog();
        return 1;
    }

    rc = mosquitto_loop_start(mosq);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "MQTT loop start failed: %s", mosquitto_strerror(rc));
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
        mosq = NULL;
        mosquitto_lib_cleanup();
        gpioTerminate();
        closelog();
        return 1;
    }

    syslog(LOG_INFO, "IR decoder started on GPIO %d", IR_GPIO);

    while (running) {
        gpioDelay(100000);
    }

    syslog(LOG_INFO, "Shutting down IR decoder");
    gpioSetAlertFunc(IR_GPIO, NULL);
    gpioSetPullUpDown(IR_GPIO, PI_PUD_OFF);
    gpioTerminate();

    if (mosq) {
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
        mosq = NULL;
    }
    mosquitto_lib_cleanup();

    closelog();
    return 0;
}

