#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define NUM_SENSORS    4
#define BH1750_ADDR_1  0x23
#define BH1750_ADDR_2  0x24
#define BH1750_ADDR_3  0x25
#define BH1750_ADDR_4  0x26
#define BH1750_CMD_OT_HRES 0x20
#define CONV_TIME_MS   180
#define MULTICAST_ADDR "239.255.255.250"
#define MULTICAST_PORT 5005
#define SAMPLE_PERIOD_S 1

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_open(int addr) {
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02x) failed: %s\n", addr, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

static int bh1750_read(int fd, float *lux_out) {
    uint8_t cmd = BH1750_CMD_OT_HRES;
    ssize_t w = write(fd, &cmd, 1);
    if (w != 1) {
        fprintf(stderr, "write(0x%02x) failed: %s\n", cmd, strerror(errno));
        return -1;
    }
    usleep(CONV_TIME_MS * 1000);
    uint8_t buf[2];
    ssize_t r = read(fd, buf, 2);
    if (r != 2) {
        fprintf(stderr, "read failed: %s\n", strerror(errno));
        return -1;
    }
    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static int send_multicast(int sock, const float *data) {
    char msg[256];
    int len = snprintf(msg, sizeof(msg), "%d,%.1f;%d,%.1f;%d,%.1f;%d,%.1f",
                        1, data[0], 2, data[1], 3, data[2], 4, data[3]);
    if (len < 0 || (size_t)len >= sizeof(msg)) {
        fprintf(stderr, "snprintf failed\n");
        return -1;
    }
    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    if (inet_pton(AF_INET, MULTICAST_ADDR, &addr.sin_addr) <= 0) {
        fprintf(stderr, "inet_pton(%s) failed: %s\n", MULTICAST_ADDR, strerror(errno));
        return -1;
    }
    addr.sin_port = htons(MULTICAST_PORT);
    if (sendto(sock, msg, (size_t)len, 0, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        fprintf(stderr, "sendto failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    int i2c_fds[NUM_SENSORS];
    int sock = -1;
    int sensor_fds = 0;

    for (int i = 0; i < NUM_SENSORS; i++) {
        i2c_fds[i] = -1;
    }

    for (int i = 0; i < NUM_SENSORS; i++) {
        i2c_fds[i] = i2c_open((i < 2) ? BH1750_ADDR_1 : (i < 4) ? BH1750_ADDR_2 : (i < 6) ? BH1750_ADDR_3 : BH1750_ADDR_4);
        if (i2c_fds[i] < 0) {
            sensor_fds = -1;
            break;
        }
        sensor_fds++;
    }

    if (sensor_fds == 0) {
        fprintf(stderr, "No sensors initialized\n");
        return 1;
    }

    sock = socket(AF_INET, SOCK_DGRAM, 0);
    if (sock < 0) {
        perror("socket");
        for (int i = 0; i < sensor_fds; i++) close(i2c_fds[i]);
        return 1;
    }

    int addrs[NUM_SENSORS];
    for (int i = 0; i < NUM_SENSORS; i++) {
        addrs[i] = BH1750_ADDR_1 + (i < 2) ? 0 : (i < 4) ? 1 : 2;
    }

    while (g_running) {
        float data[NUM_SENSORS];
        for (int i = 0; i < NUM_SENSORS; i++) {
            if (i2c_fds[i] < 0) {
                data[i] = NAN;
            } else {
                float lux;
                if (bh1750_read(i2c_fds[i], &lux) < 0) {
                    data[i] = NAN;
                } else {
                    data[i] = lux;
                }
            }
        }

        if (send_multicast(sock, data) < 0) {
            fprintf(stderr, "Multicast send failed\n");
        }

        sleep(SAMPLE_PERIOD_S);
    }

    for (int i = 0; i < sensor_fds; i++) {
        if (i2c_fds[i] >= 0) close(i2c_fds[i]);
    }
    if (sock >= 0) close(sock);
    return 0;
}

