/*
 * AS7341 10-Channel Light/Color Sensor Logger
 * Board:  Raspberry Pi 3 Model B+
 * Bus:    /dev/i2c-1 (GPIO2=SDA, GPIO3=SCL)
 * Sensor: Adafruit AS7341 at I2C address 0x39
 *
 * Build:  gcc -O2 -Wall -o as7341_logger as7341_logger.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define AS7341_ADDR    0x39

/* AS7341 register addresses */
#define AS7341_REG_ENABLE  0x80
#define AS7341_REG_ID      0x24
#define AS7341_REG_WHOAMI  0x24
#define AS7341_REG_SMUX    0xAF
#define AS7341_REG_SP_EN   0x80
#define AS7341_REG_DATA0   0x60
#define AS7341_REG_DATA1   0x61
#define AS7341_REG_DATA2   0x62
#define AS7341_REG_DATA3   0x63
#define AS7341_REG_DATA4   0x64
#define AS7341_REG_DATA5   0x65
#define AS7341_REG_DATA6   0x66
#define AS7341_REG_DATA7   0x67
#define AS7341_REG_DATA8   0x68
#define AS7341_REG_DATA9   0x69
#define AS7341_REG_CLEAR   0x6A
#define AS7341_REG_NIR     0x6B

#define AS7341_WHOAMI_VAL  0x19
#define AS7341_ID_VAL      0x39

#define LOG_FILE "spectral_log.csv"
#define SAMPLE_INTERVAL_SEC 5

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *val)
{
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read 16-bit from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *val = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor initialization                                               */
/* ------------------------------------------------------------------ */
static int as7341_init(int fd)
{
    uint8_t whoami = 0;

    /* Verify device identity */
    if (i2c_read_reg8(fd, AS7341_REG_WHOAMI, &whoami) != 0) {
        fprintf(stderr, "Cannot read WHO_AM_I — sensor absent or bus error.\n");
        return -1;
    }
    if (whoami != AS7341_WHOAMI_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                whoami, AS7341_WHOAMI_VAL);
        return -1;
    }

    /* Power on */
    if (i2c_write_reg8(fd, AS7341_REG_ENABLE, 0x00) != 0) return -1; /* clear PON */
    if (i2c_write_reg8(fd, AS7341_REG_ENABLE, 0x01) != 0) return -1; /* PON = 1 */

    /* Disable all spectral channels before configuration */
    if (i2c_write_reg8(fd, AS7341_REG_SMUX, 0x00) != 0) return -1;

    /* CFG6: F1-F8, Clear, NIR */
    if (i2c_write_reg8(fd, AS7341_REG_SMUX, 0x0F) != 0) return -1;

    /* Enable spectral measurement */
    if (i2c_write_reg8(fd, AS7341_REG_SP_EN, 0x01) != 0) return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Data acquisition                                                    */
/* ------------------------------------------------------------------ */
static int as7341_read_data(int fd, uint16_t *data)
{
    for (int i = 0; i < 10; i++) {
        if (i2c_read_reg16(fd, AS7341_REG_DATA0 + i, &data[i]) != 0)
            return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Lux approximation (simplified)                                      */
/* ------------------------------------------------------------------ */
static float calculate_lux(const uint16_t *data)
{
    float sum = 0.0f;
    for (int i = 0; i < 10; i++)
        sum += (float)data[i];
    return sum * 0.1f; /* placeholder — real implementation needed */
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_data(FILE *fp, const uint16_t *data, float lux)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s,%u,%u,%u,%u,%u,%u,%u,%u,%u,%u,%.2f\n",
                ts,
                data[0], data[1], data[2], data[3],
                data[4], data[5], data[6], data[7], data[8], data[9],
                lux) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    fflush(fp);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        /* Power down sensor */
        (void)i2c_write_reg8(g_i2c_fd, AS7341_REG_ENABLE, 0x00);
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, AS7341_ADDR) < 0) {
        fprintf(stderr, "ioctl I2C_SLAVE 0x%02X failed: %s\n",
                AS7341_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (as7341_init(g_i2c_fd) != 0) {
        fprintf(stderr, "AS7341 initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    fseek(g_log_fp, 0, SEEK_END);
    if (ftell(g_log_fp) == 0) {
        fprintf(g_log_fp, "Timestamp,F1,F2,F3,F4,F5,F6,F7,F8,Clear,NIR,Lux\n");
        fflush(g_log_fp);
    }

