#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define DEFAULT_I2C_ADDR 0x37
#define DEFAULT_INTERVAL 1
#define DEFAULT_FILENAME "seismic_data.csv"
#define I2C_DEV "/dev/i2c-1"
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10
#define ACCEL_REG 0x28
#define ACCEL_BYTES 6
#define SCALE_FACTOR 0.000244f  /* g/LSB for ±8 g range */

static int i2c_fd = -1;
static FILE *data_file = NULL;
static FILE *error_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void log_error(const char *msg) {
    if (!error_file) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(error_file, "%s: %s (errno=%d: %s)\n", ts, msg, errno, strerror(errno));
    fflush(error_file);
}

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    for (int i = 0; i < MAX_RETRIES; i++) {
        if (write(fd, buf, 2) == 2) return 0;
        log_error("I2C write to register failed");
        usleep(RETRY_DELAY_MS * 1000);
    }
    return -1;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, int len) {
    for (int i = 0; i < MAX_RETRIES; i++) {
        if (write(fd, &reg, 1) == 1) {
            if (read(fd, buf, len) == len) return 0;
        }
        log_error("I2C burst read failed");
        usleep(RETRY_DELAY_MS * 1000);
    }
    return -1;
}

static int read_accel(int fd, float *x, float *y, float *z) {
    uint8_t buf[ACCEL_BYTES];
    if (i2c_read_burst(fd, ACCEL_REG, buf, ACCEL_BYTES) != 0) {
        log_error("Failed to read acceleration data");
        return -1;
    }
    int16_t raw_x = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t raw_y = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t raw_z = (int16_t)((buf[5] << 8) | buf[4]);
    *x = (float)raw_x * SCALE_FACTOR;
    *y = (float)raw_y * SCALE_FACTOR;
    *z = (float)raw_z * SCALE_FACTOR;
    return 0;
}

static int log_data(FILE *fp, float x, float y, float z) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    if (fprintf(fp, "%s,%.6f,%.6f,%.6f\n", ts, x, y, z) < 0) {
        log_error("Failed to write data to CSV");
        return -1;
    }
    fflush(fp);
    return 0;
}

static void cleanup(void) {
    if (data_file) { fclose(data_file); data_file = NULL; }
    if (error_file) { fclose(error_file); error_file = NULL; }
    if (i2c_fd >= 0) { close(i2c_fd); i2c_fd = -1; }
}

int main(int argc, char *argv[]) {
    int i2c_addr = DEFAULT_I2C_ADDR;
    int interval = DEFAULT_INTERVAL;
    char filename[256] = DEFAULT_FILENAME;

    int opt;
    while ((opt = getopt(argc, argv, "a:i:f:h")) != -1) {
        switch (opt) {
            case 'a': i2c_addr = (int)strtol(optarg, NULL, 0); break;
            case 'i': interval = atoi(optarg); break;
            case 'f': strncpy(filename, optarg, sizeof(filename) - 1); filename[sizeof(filename) - 1] = '\0'; break;
            case 'h':
            default:
                fprintf(stderr, "Usage: %s [-a i2c_addr] [-i interval] [-f filename]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    if (i2c_addr < 0x03 || i2c_addr > 0x77) {
        fprintf(stderr, "Invalid I2C address: 0x%02X\n", i2c_addr);
        return EXIT_FAILURE;
    }

    i2c_fd = open(I2C_DEV, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_DEV, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, i2c_addr) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", i2c_addr, strerror(errno));
        log_error("Failed to set I2C slave address");
        cleanup();
        return EXIT_FAILURE;
    }

    data_file = fopen(filename, "a");
    if (!data_file) {
        fprintf(stderr, "Failed to open %s: %s\n", filename, strerror(errno));
        log_error("Failed to open data file");
        cleanup();
        return EXIT_FAILURE;
    }

    error_file = fopen("seismic_error.log", "a");
    if (!error_file) {
        fprintf(stderr, "Failed to open error log: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Seismic data logging started. I2C addr=0x%02X, interval=%ds, output=%s\n",
           i2c_addr, interval, filename);

    while (!terminate) {
        float x, y, z;
        if (read_accel(i2c_fd, &x, &y, &z) == 0) {
            if (log_data(data_file, x, y, z) != 0) {
                fprintf(stderr, "Logging failed, continuing...\n");
            }
        } else {
            fprintf(stderr, "Sensor read failed, continuing...\n");
        }
        sleep(interval);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

