static const uint8_t MAGIC_WORD[MAGIC_WORD_SIZE] = {0x02, 0x04, 0x03, 0x06, 0x08, 0x05, 0x09, 0x07};

static volatile sig_atomic_t running = 1;
static int uart_handle = -1;
static FILE *csv_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_uart(const char *device, int baud_rate) {
    int handle = serOpen((char *)device, baud_rate, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening UART %s: %s\n", device, strerror(errno));
        return -1;
    }
    return handle;
}

static int init_csv(const char *filename) {
    csv_file = fopen(filename, "a");
    if (!csv_file) {
        fprintf(stderr, "Error opening CSV file %s: %s\n", filename, strerror(errno));
        return -1;
    }
    if (ftell(csv_file) == 0) {
        fprintf(csv_file, "timestamp,object_index,range_m,velocity_mps\n");
    }
    return 0;
}

static void close_resources(void) {
    if (uart_handle >= 0) {
        serClose(uart_handle);
        uart_handle = -1;
    }
    if (csv_file) {
        fflush(csv_file);
        fclose(csv_file);
        csv_file = NULL;
    }
    gpioTerminate();
}

static void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(stderr, "%s Error: %s\n", timestamp, message);
}

static int read_exact(int handle, uint8_t *buffer, int count) {
    int total_read = 0;
    while (total_read < count) {
        int bytes_read = serRead(handle, (char *)(buffer + total_read), count - total_read);
        if (bytes_read < 0) {
            log_error("Error reading from UART");
            return -1;
        }
        if (bytes_read == 0) {
            gpioDelay(1000);
            continue;
        }
        total_read += bytes_read;
    }
    return 0;
}

static int find_magic_word(int handle) {
    uint8_t buffer[MAX_FRAME_SIZE];
    int buffer_index = 0;
    int magic_index = -1;

    while (running) {
        int bytes_read = serRead(handle, (char *)(buffer + buffer_index), MAX_FRAME_SIZE - buffer_index);
        if (bytes_read < 0) {
            log_error("Error reading from UART");
            return -1;
        }
        if (bytes_read == 0) {
            gpioDelay(1000);
            continue;
        }
        buffer_index += bytes_read;

        for (int i = 0; i <= buffer_index - MAGIC_WORD_SIZE; i++) {
            if (memcmp(buffer + i, MAGIC_WORD, MAGIC_WORD_SIZE) == 0) {
                magic_index = i;
                break;
            }
        }

        if (magic_index >= 0) {
            break;
        }

        if (buffer_index >= MAX_FRAME_SIZE) {
            log_error("Frame buffer overflow");
            buffer_index = 0;
            magic_index = -1;
            continue;
        }
    }

    if (magic_index < 0) {
        return -1;
    }

    int remaining = buffer_index - magic_index;
    if (remaining < 32) {
        log_error("Incomplete frame header");
        return -1;
    }

    uint32_t total_packet_len = *(uint32_t *)(buffer + magic_index + 4);
    if (total_packet_len < 32 || total_packet_len > MAX_FRAME_SIZE) {
        log_error("Invalid total packet length");
        return -1;
    }

    if (remaining < (int)total_packet_len) {
        log_error("Incomplete frame payload");
        return -1;
    }

    return total_packet_len;
}

static int process_frame(int handle) {
    uint8_t *buffer = malloc(MAX_FRAME_SIZE);
    if (!buffer) {
        log_error("Memory allocation failed");
        return -1;
    }

    int total_packet_len = find_magic_word(handle);
    if (total_packet_len < 0) {
        free(buffer);
        return -1;
    }

    if (total_packet_len > MAX_FRAME_SIZE) {
        log_error("Frame length exceeds maximum");
        free(buffer);
        return -1;
    }

    int bytes_read = serRead(handle, (char *)buffer, total_packet_len);
    if (bytes_read < 0) {
        log_error("Error reading from UART");
        free(buffer);
        return -1;
    }
    if (bytes_read != total_packet_len) {
        log_error("Incomplete frame read");
        free(buffer);
        return -1;
    }

    uint32_t frame_number = *(uint32_t *)(buffer + 4);
    uint32_t num_detected_objects = *(uint32_t *)(buffer + 8);

    if (num_detected_objects > MAX_OBJECTS) {
        num_detected_objects = MAX_OBJECTS;
    }

    for (uint32_t i = 0; i < num_detected_objects; i++) {
        uint32_t range_idx = *(uint32_t *)(buffer + 12 + i * 12);
        uint32_t velocity_idx = *(uint32_t *)(buffer + 16 + i * 12);
        uint16_t range_msb = *(uint16_t *)(buffer + 20 + i * 12);
        uint16_t range_lsb = *(uint16_t *)(buffer + 22 + i * 12);
        uint16_t velocity_msb = *(uint16_t *)(buffer + 24 + i * 12);
        uint16_t velocity_lsb = *(uint16_t *)(buffer + 26 + i * 12);

        if (range_idx > 0 && range_lsb > 0 && velocity_idx > 0 && velocity_lsb > 0) {
            float range = (float)(range_msb << 8 | range_lsb) / 1000.0f;
            float velocity = (float)(velocity_msb << 8 | velocity_lsb) / 100.0f;
            if (range >= 0.0f && velocity >= 0.0f) {
                time_t now = time(NULL);
                struct tm *t = localtime(&now);
                char timestamp[32];
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

                if (fprintf(csv_file, "%s,%u,%.2f,%.2f\n", timestamp, i, range, velocity) < 0) {
                    log_error("Error writing to CSV file");
                }
                fflush(csv_file);
            }
        }
    }

    free(buffer);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    uart_handle = init_uart(UART_DEVICE, BAUD_RATE);
    if (uart_handle < 0) {
        gpioTerminate();
        return 1;
    }

    if (init_csv(CSV_FILE) < 0) {
        serClose(uart_handle);
        gpioTerminate();
        return 1;
    }

    printf("Radar data acquisition started. Press Ctrl+C to exit.\n");

    while (running) {
        int total_packet_len = process_frame(uart_handle);
        if (total_packet_len < 0) {
            gpioDelay(100000);
            continue;
        }
        if (total_packet_len > 0) {
            gpioDelay(10000);
        }
    }

    printf("Radar data acquisition stopped.\n");
    close_resources();
    return 0;
}

