    tcflush(fd, TCIOFLUSH);
    return fd;
}

static void get_timestamp(char *buf, size_t len) {
    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(buf, len, "%Y-%m-%d %H:%M:%S", timeinfo);
}

static void log_detection(const char *timestamp, double range) {
    printf("Timestamp: %s, Range: %.2f meters\n", timestamp, range);
    fflush(stdout);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return 1;
    }

    int uart_fd = init_uart(UART_DEVICE);
    if (uart_fd < 0) {
        return 1;
    }

    char line_buf[LINE_BUF_SIZE];
    size_t line_len = 0;
    char timestamp_str[32];
    char *line_ptr = line_buf;

    while (g_running) {
        fd_set readfds;
        FD_ZERO(&readfds);
        FD_SET(uart_fd, &readfds);

        struct timeval timeout;
        timeout.tv_sec = POLL_TIMEOUT_SEC;
        timeout.tv_usec = 0;

        int sel = select(uart_fd + 1, &readfds, NULL, NULL, &timeout);

        if (sel < 0) {
            if (errno == EINTR) {
                continue;
            }
            fprintf(stderr, "select() failed: %s\n", strerror(errno));
            break;
        }

        if (sel > 0) {
            char ch;
            ssize_t n = read(uart_fd, &ch, 1);
            if (n < 0) {
                if (errno == EAGAIN || errno == EWOULDBLOCK) {
                    continue;
                }
                fprintf(stderr, "read() failed: %s\n", strerror(errno));
                break;
            }

            if (n == 0) {
                /* Sensor disappeared or disconnected */
                fprintf(stderr, "UART read returned 0 bytes (sensor absent?)\n");
                break;
            }

            if (ch == '\n') {
                if (line_len > 0) {
                    line_buf[line_len] = '\0';
                    char *newline = strchr(line_buf, '\r');
                    if (newline) *newline = '\0';

                    char *token = strtok(line_buf, ",");
                    if (token != NULL) {
                        char *endptr;
                        double range = strtod(token, &endptr);
                        if (endptr != token && range >= 0.0) {
                            char *ts = strtok(NULL, "\r\n");
                            if (ts != NULL) {
                                get_timestamp(timestamp_str, sizeof(timestamp_str));
                                log_detection(timestamp_str, range);
                            }
                        }
                    }
                    line_len = 0;
                    line_ptr = line_buf;
                }
            } else {
                if (line_len < LINE_BUF_SIZE - 1) {
                    line_buf[line_len++] = ch;
                    line_ptr = line_buf + line_len;
                } else {
                    fprintf(stderr, "Line buffer overflow, discarding data\n");
                    line_len = 0;
                    line_ptr = line_buf;
                }
            }
        }
    }

    if (uart_fd >= 0) {
        tcflush(uart_fd, TCIOFLUSH);
        close(uart_fd);
    }

    return 0;
}

