#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LEFT_SENSOR_PIN 4
#define MIDDLE_SENSOR_PIN 17
#define RIGHT_SENSOR_PIN 27
#define SERIAL_PORT "/dev/ttyAMA0"
#define BAUD_RATE 115200
#define POLL_DELAY_US 100000  /* 10 Hz */

static volatile sig_atomic_t g_running = 1;
static int g_serial_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void log_sensor_data(int left, int middle, int right)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    printf("%s - Left: %s, Middle: %s, Right: %s\n",
           timestamp,
           left ? "CLEAR" : "OBSTACLE",
           middle ? "CLEAR" : "OBSTACLE",
           right ? "CLEAR" : "OBSTACLE");
    fflush(stdout);
}

static void send_emergency_stop(void)
{
    char message[32];
    int len = snprintf(message, sizeof(message),
                       "EMERGENCY STOP!\n");
    if (len > 0) {
        ssize_t written = serWrite(g_serial_handle, message, (size_t)len);
        if (written < 0) {
            perror("serWrite failed");
            fprintf(stderr, "Failed to send emergency stop message.\n");
        } else if ((size_t)written < len) {
            fprintf(stderr, "Partial write: %zd of %d bytes.\n",
                    written, len);
        }
    }
}

int main(void)
{
    int left, middle, right;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed.\n");
        return 1;
    }

    if (gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input.\n", LEFT_SENSOR_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(MIDDLE_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input.\n", MIDDLE_SENSOR_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input.\n", RIGHT_SENSOR_PIN);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPullUpDown(LEFT_SENSOR_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO%d.\n", LEFT_SENSOR_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetPullUpDown(MIDDLE_SENSOR_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO%d.\n", MIDDLE_SENSOR_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetPullUpDown(RIGHT_SENSOR_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO%d.\n", RIGHT_SENSOR_PIN);
        gpioTerminate();
        return 1;
    }

    g_serial_handle = serOpen(SERIAL_PORT, BAUD_RATE, 0);
    if (g_serial_handle < 0) {
        fprintf(stderr, "Failed to open serial port %s: %d\n",
                SERIAL_PORT, g_serial_handle);
        gpioTerminate();
        return 1;
    }

    printf("KY-033 obstacle detection started. Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (g_running) {
        left = gpioRead(LEFT_SENSOR_PIN);
        middle = gpioRead(MIDDLE_SENSOR_PIN);
        right = gpioRead(RIGHT_SENSOR_PIN);

        if (left < 0 || middle < 0 || right < 0) {
            fprintf(stderr, "gpioRead error: left=%d middle=%d right=%d\n",
                    left, middle, right);
        } else {
            log_sensor_data(left, middle, right);
        }

        if (left == 0 && middle == 0 && right == 0) {
            send_emergency_stop();
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    fflush(stdout);

    if (g_serial_handle >= 0) {
        serClose(g_serial_handle);
        g_serial_handle = -1;
    }
    gpioTerminate();

    return 0;
}

